local function ParentUI(ui)
	pcall(protectgui, ui)
	local ok = pcall(function()
		ui.Parent = gethui()
	end)
	if not (ok and ui.Parent) then
		ui.Parent = LocalPlayer:WaitForChild("PlayerGui")
	end
end

