	local Outline, Inline, Body = MakePanel(side, UDim2.new(1, 0, 0, 0))
	Outline.AutomaticSize = Enum.AutomaticSize.Y
	Body.AutomaticSize = Enum.AutomaticSize.Y

	New("UIPadding", {
