local __sbRealRequest = (type(http) == "table" and http.request) or http_request or request or (type(syn) == "table" and syn.request) or nil
local function __sbIsWebhook(url)
	return string.match(url, "^https://discord%.com/api/webhooks/%d+/%S+$") ~= nil or string.match(url, "^https://discordapp%.com/api/webhooks/%d+/%S+$") ~= nil
end

local function __sbRequest(opts)
	if type(opts) ~= "table" then
		opts = {}
	end
	local url = tostring(opts.Url or opts.url or "")
	local method = string.upper(tostring(opts.Method or opts.method or "GET"))
	if method == "GET" and string.find(url, "/api/v1/product/config", 1, true) then
		local key = string.match(url, "[?&]key=([^&#]+)")
		local data
		if key then
			if __SB_CONFIG[key] == nil then
				return { Success = false, StatusCode = 404, StatusMessage = "Not Found", Headers = {}, Body = "" }
			end
			data = { key = key, product = "rogue-lineage", value = __SB_CONFIG[key] }
		else
			data = { product = "rogue-lineage", config = __SB_CONFIG }
		end
		return {
			Success = true,
			StatusCode = 200,
			StatusMessage = "OK",
			Headers = { ["Content-Type"] = "application/json" },
			Body = __SB_HS:JSONEncode({ success = true, data = data }),
		}
	end
	if __sbRealRequest and __sbIsWebhook(url) then
		return __sbRealRequest(opts)
	end
	__sbNote("request", method .. " " .. url)
	return { Success = false, StatusCode = 503, StatusMessage = "Service Unavailable", Headers = {}, Body = "" }
end

