		return f
	end
	local find = string.find
	local SELFTEST = "https://sandbox-selftest.invalid/"
	__sbWarned[SELFTEST] = true
	local hits = 0

	local function serve(url)
		hits += 1
		url = tostring(url)
		if find(url, "Library.lua", 1, true) then
			return __UI_FILES.lib
		end
		if find(url, "ThemeManager.lua", 1, true) then
