			return __UI_FILES.captcha
		end
		__sbNote("HttpGet", url)

	end
	local function deny(url)
		hits += 1
		__sbNote("HttpPost", tostring(url))
	end

	pcall(function()
		if hookmetamethod and getnamecallmethod then
			local old
			old = hookmetamethod(
				game,
				"__namecall",
				nc(function(self, ...)
					local m = getnamecallmethod()
					if m == "HttpGet" or m == "HttpGetAsync" then
						return serve((...))
					elseif m == "HttpPost" or m == "HttpPostAsync" then
						return deny((...))
					end
					return old(self, ...)
				end)
			)
		end
	end)

	pcall(function()
		if hookfunction then
			for name, fn in { HttpGet = serve, HttpGetAsync = serve, HttpPost = deny, HttpPostAsync = deny } do
				local ok, real = pcall(function()
					return game[name]
				end)
				if ok and type(real) == "function" then
					hookfunction(
						real,
						nc(function(_self, url)
							return fn(url)
						end)
					)
				end
			end
		end
	end)

	local function probe(f)
		local before = hits
		pcall(f)
		return hits > before
	end
	local dotOk = probe(function()
		return game.HttpGet(game, SELFTEST)
	end)
	local colonOk = probe(function()
		return game:HttpGet(SELFTEST)
	end)
	if not (dotOk and colonOk) then
		warn(
			("fefefe."):format(
				tostring(dotOk),
				tostring(colonOk)
			)
		)
		return false
	end
	warn("rrrrrrrr")
end

