                    Text = 'Rune Cast Whitelist',
                    Tooltip = 'At 0 mana, only these spells can burn a rune',
                    Default = saved.enabled == true,
                    Callback = save,
                })
                box:AddDropdown('RuneCastCast', {
                    Text = 'Rune Cast',
                    Tooltip = 'Left click at 0 mana',
                    Multi = true,
                    Values = savedCast,
                    Default = {},
