                ['Dagger Throw'] = true,
                Arguere = true,
                Grapple = true,
                ['Autumn Rain'] = true,
                Ignis = true,
                Percutiens = true,
                Spindulys = true,
                Snowball = true,
                ['Signet Ring'] = true,
                Shift = true,
            }
            local SOUNDS = {
                OwlSlash = {
                    delay = 0.1,
                    blockDuration = 0.7,
                    requiresVisibility = false,
                    ability = 'Owlslash',
                },
                Shadowrush = {
                    delay = 0.05,
                    blockDuration = 0.3,
                    requiresVisibility = true,
