                },
            }
            local UNEQUIP_WEAPONS = {
                Dagger = true,
                Sword = true,
                Rapier = true,
            }
            local DAGGER_SKILLS = {
                Lethality = true,
                ['Triple Dagger Throw'] = true,
                ['Dagger Throw'] = true,
            }
            local RAPIER_SKILLS = {
                ['Elegant Slash'] = true,
                ["Needle's Eye"] = true,
                ['Dagger Throw'] = true,
            }
            local COUNTER_COOLDOWN = 10
            local COUNTER_BLOCKERS = {
                'Charge',
                'Stun',
                'ReturnStun',
                'Action',
                'Blocking',
                'SpellBlocking',
                'NoDamage',
                'ActiveCast',
            }
            local UNEQUIP_BYPASS_WAIT = 0.04
            local PARRY_SWAP_WEAPONS = {
                'Dagger',
                'Spear',
            }

            local function findBypassTool(weaponName)
                local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')

                if not backpack then
                    return nil
                end

                local target = 'Action Surge'

                if weaponName == 'Dagger' then
                    target = 'Owl Slash'
                elseif weaponName == 'Rapier' then
                    target = 'Dagger Throw'
                end

                for _, tool in backpack:GetChildren()do
                    if tool:IsA('Tool') and tool.Name == target then
                        return tool
                    end
                end

                return nil
            end

            return function(ctx)
                local Library = ctx.Library
                local Toggles, Options = Library.Toggles, Library.Options
                local Combat = ctx.Tabs.Combat
                local RISKY_TOOLTIP = Gate.risky()
                local windowActive = true

                ctx.Maid:Connect(UserInputService.WindowFocused, function()
                    windowActive = true
                end)
                ctx.Maid:Connect(UserInputService.WindowFocusReleased, function()
                    windowActive = false
                end)

                local function observingOther()
                    local query = ctx.State.isSpectating

                    if not query then
                        return false
                    end

                    local ok, watching = pcall(query)

                    return ok and watching == true
                end
                local function parryMuted()
                    if not Toggles.ParryDisableWhenUnfocused.Value then
                        return false
                    end

                    return not windowActive or UserInputService:GetFocusedTextBox() ~= nil or observingOther() or (Toggles.Freecam ~= nil and Toggles.Freecam.Value == true)
                end

                local getChar = BASIL_NO_VIRTUALIZE(function()
                    return LocalPlayer.Character
                end)

                local function getHRP(char)
                    return char and char:FindFirstChild('HumanoidRootPart')
                end

                do
                    local maid = Maid.new()

                    ctx.Maid:Give(maid)

                    local charMaids = {}

                    ctx.Maid:Give(function()
                        for _, pm in charMaids do
                            pm:DoCleaning()
                        end

                        charMaids = {}
                    end)

                    local lastParry = 0
                    local inputBlocked = false

                    local function blockInputs()
                        inputBlocked = true

                        ContextActionService:BindAction('SentinelParryKeys', function(
                        )
                            return Enum.ContextActionResult.Sink
                        end, false, table.unpack(BLOCKED_KEYS))
                        ContextActionService:BindAction('SentinelParryMouse', function(
                        )
                            return inputBlocked and Enum.ContextActionResult.Sink or nil
                        end, false, Enum.UserInputType.MouseButton1, Enum.UserInputType.MouseButton2)
                    end
                    local function unblockInputs()
                        inputBlocked = false

                        pcall(ContextActionService.UnbindAction, ContextActionService, 'SentinelParryKeys')
                        pcall(ContextActionService.UnbindAction, ContextActionService, 'SentinelParryMouse')
                    end

                    ctx.Maid:Give(unblockInputs)

                    local function raycastReaches(fromHRP, targetHRP)
                        local params = RaycastParams.new()

                        params.FilterDescendantsInstances = {
                            getChar(),
                        }
                        params.FilterType = Enum.RaycastFilterType.Exclude

                        local res = Workspace:Raycast(fromHRP.Position, targetHRP.Position - fromHRP.Position, params)

                        return not res or res.Instance:IsDescendantOf(targetHRP.Parent)
                    end
                    local function onScreenVisible(hrp)
                        local _, onScreen = Workspace.CurrentCamera:WorldToScreenPoint(hrp.Position)
                        local pHRP = getHRP(getChar())

                        return onScreen and pHRP and raycastReaches(pHRP, hrp)
                    end
                    local function isVisible(hrp)
                        local _, onScreen = Workspace.CurrentCamera:WorldToScreenPoint(hrp.Position)

                        if not onScreen then
                            return false
                        end

                        local pHRP = getHRP(getChar())

                        if not pHRP then
                            return false
                        end

                        local dir = (hrp.Position - pHRP.Position).Unit
                        local threshold = math.cos(math.rad(Options.ParryFovAngle.Value / 2))

                        if pHRP.CFrame.LookVector:Dot(dir) > threshold then
                            return raycastReaches(pHRP, hrp)
                        end

                        return false
                    end
                    local function parryLog(fmt, ...)
                        if Toggles.ParryDebug and Toggles.ParryDebug.Value then
                            print(string.format('[sentinel] parry: ' .. fmt, ...))
                        end
                    end
                    local function onCooldown()
                        local char = getChar()

                        return not char or char:FindFirstChild('ParryCool') ~= nil
                    end
                    local function parryHeld()
                        return ctx.State.parryHeld ~= nil and ctx.State.parryHeld() == true
                    end
                    local function performParry(
                        delay,
                        blockDuration,
                        useVim,
                        attacker,
                        forceSemiBlatant,
                        ignoreCooldown,
                        label
                    )
                        label = label or 'parry'

                        local who = attacker and attacker.Name or 'someone'

                        if attacker and ctx.State.isFriendly and ctx.State.isFriendly(attacker) then
                            parryLog('%s from %s ignored, they are an ally', label, who)

                            return
                        end
                        if parryHeld() then
                            parryLog('%s from %s skipped, legit day farm is running', label, who)

                            return
                        end

                        local char = getChar()

                        if not char then
                            parryLog('%s from %s skipped, no character', label, who)

                            return
                        end
                        if char:FindFirstChild('SpellBlocking') then
                            parryLog('%s from %s skipped, a mana block is already up', label, who)

                            return
                        end
                        if parryMuted() then
                            parryLog('%s from %s skipped, the window is not focused', label, who)

                            return
                        end

                        local now = os.clock()

                        if now - lastParry < AUTO_PARRY_COOLDOWN then
                            parryLog('%s from %s skipped, only %.0fms since the last parry', label, who, (now - lastParry) * 1000)

                            return
                        end

                        local semiBlatant = forceSemiBlatant or Toggles.ParrySemiBlatantBlock.Value

                        if not semiBlatant and char:FindFirstChild('NoDash') then
                            parryLog(
[[%s from %s skipped, NoDash is up and semi blatant block is off]], label, who)

                            return
                        end
                        if char:FindFirstChildOfClass('ForceField') then
                            parryLog('%s from %s skipped, the spawn shield is up', label, who)

                            return
                        end
                        if onCooldown() and not ignoreCooldown then
                            parryLog('%s from %s skipped, ParryCool is up', label, who)

                            return
                        end

                        lastParry = now
                        blockDuration = blockDuration or 0.3

                        local adjusted = delay or 0

                        if Toggles.ParryCustomDelay.Value then
                            adjusted += Options.ParryCustomDelayMs.Value / 1000
                        elseif Toggles.ParryPingAdjust.Value then
                            adjusted -= Utility.getPing() / 2000
                        end

                        adjusted = math.max(0, adjusted)

                        parryLog('%s from %s, blocking %.0fms after a %.0fms wait (%s%s)', label, who, (blockDuration or 0) * 1000, adjusted * 1000, useVim and 'keypress' or 'remote', semiBlatant and ', held' or '')

                        if not useVim then
                            blockInputs()
                        end
                        if adjusted > 0 then
                            task.wait(adjusted)

                            if onCooldown() and not ignoreCooldown then
                                parryLog('%s from %s dropped mid wait, ParryCool came up', label, who)
                                unblockInputs()

                                return
                            end
                        end

                        char = getChar()

                        if not char then
                            unblockInputs()

                            return
                        end

                        local humanoid = char:FindFirstChildOfClass('Humanoid')
                        local mana = char:FindFirstChild('Mana')
                        local held = char:FindFirstChildOfClass('Tool')

                        if humanoid and mana and mana.Value > 0 and held and held:FindFirstChild('Spell') then
                            humanoid:UnequipTools()

                            local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')

                            for _, name in PARRY_SWAP_WEAPONS do
                                local weapon = backpack and backpack:FindFirstChild(name)

                                if weapon and weapon:IsA('Tool') then
                                    humanoid:EquipTool(weapon)

                                    break
                                end
                            end
                        end

                        local handler = char:FindFirstChild('CharacterHandler', true)
                        local remotes = handler and handler:FindFirstChild('Remotes')
                        local blockRemote = remotes and remotes:FindFirstChild('Block')
                        local unblockRemote = remotes and remotes:FindFirstChild('Unblock')

                        if semiBlatant and blockRemote and unblockRemote then
                            task.spawn(function()
                                local endTime = os.clock() + blockDuration

                                while os.clock() < endTime do
                                    blockRemote:FireServer(false)
                                    task.wait()
                                end

                                unblockRemote:FireServer({})
                                unblockInputs()
                            end)
                        elseif useVim or not (blockRemote and unblockRemote) then
                            task.spawn(function()
                                VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.F, false, game)
                                task.wait(blockDuration)
                                VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.F, false, game)
                                unblockInputs()
                            end)
                        else
                            blockRemote:FireServer(false)
                            task.delay(blockDuration, function()
                                unblockRemote:FireServer({})
                                unblockInputs()
                            end)
                        end
                    end

                    local counterAttack
                    local lastCounter = -math.huge

                    local function onAttackerSound(
                        sound,
                        attackerChar,
                        attackerHRP
                    )
                        if not Toggles.AutoPerfectBlock.Value or parryHeld() then
                            return
                        end

                        local info = SOUNDS[sound.Name]
                        local counter = info and Options.AutoCounter and Options.AutoCounter.Value[info.ability]

                        if not (info and (Options.ParryAbilities.Value[info.ability] or counter)) then
                            return
                        end

                        local char = getChar()
                        local pHRP = getHRP(char)

                        if not pHRP then
                            return
                        end

                        local distance = (pHRP.Position - attackerHRP.Position).Magnitude
                        local heard = Players:GetPlayerFromCharacter(attackerChar)
                        local heardName = heard and heard.Name or attackerChar.Name

                        if distance > DETECTION_RANGE then
                            parryLog('%s heard from %s at %.0f studs, past the %d stud range', info.ability, heardName, distance, DETECTION_RANGE)

                            return
                        end

                        parryLog('%s heard from %s at %.0f studs', info.ability, heardName, distance)

                        if sound.Name == 'OwlSlash' then
                            if not char:FindFirstChild('AIRSLASH') then
                                parryLog('%s dropped, it is not us being slashed', info.ability)

                                return
                            end
                        elseif sound.Name == 'Shadowrush' or sound.Name == 'ShadowrushCharge' then
                            local facing = attackerHRP.CFrame.LookVector:Dot((pHRP.Position - attackerHRP.Position).Unit)

                            if facing <= -0.17 then
                                parryLog('%s dropped, %s is facing away from us', info.ability, heardName)

                                return
                            end
                        elseif sound.Name == 'PerfectCast' then
                            if not (attackerChar:FindFirstChild('Verdien') or attackerChar:FindFirstChild('New Verdien')) then
                                parryLog('%s dropped, %s has no Verdien on them', info.ability, heardName)

                                return
                            end
                        end

                        local visible = Toggles.ParryIgnoreVisibility.Value or not info.requiresVisibility or isVisible(attackerHRP)

                        if not visible then
                            parryLog('%s dropped, %s is not in sight', info.ability, heardName)

                            return
                        end

                        local delay = info.delay

                        if (sound.Name == 'Shadowrush' or sound.Name == 'ShadowrushCharge') and distance <= 9 then
                            delay = 0
                        end

                        local attacker = Players:GetPlayerFromCharacter(attackerChar)
                        local schedule = (sound.Name == 'Shadowrush' or sound.Name == 'ShadowrushCharge') and task.defer or task.spawn

                        if counter then
                            schedule(function()
                                if counterAttack() then
                                    parryLog('%s from %s countered instead of blocked', info.ability, heardName)

                                    return
                                end

                                parryLog('%s from %s could not be countered, blocking instead', info.ability, heardName)
                                performParry(delay, info.blockDuration, info.useVim == true, attacker, false, info.ignoreCooldown == true, info.ability)
                            end)
                        else
                            schedule(performParry, delay, info.blockDuration, info.useVim == true, attacker, false, info.ignoreCooldown == true, info.ability)
                        end
                    end
                    local function connectSounds(player, char)
                        local pm = charMaids[player]

                        if not pm then
                            return
                        end

                        local cm = Maid.new()

                        pm.char = cm

                        local hrp = char:WaitForChild('HumanoidRootPart', 3)

                        if not hrp or pm.char ~= cm then
                            return
                        end

                        local hooked = {}

                        cm:Give(function()
                            for _, pair in hooked do
                                pair.played:Disconnect()
                                pair.gone:Disconnect()
                            end

                            table.clear(hooked)
                        end)

                        local function hook(sound)
                            if hooked[sound] then
                                return
                            end

                            local pair = {}

                            pair.played = sound.Played:Connect(function()
                                onAttackerSound(sound, char, hrp)
                            end)
                            pair.gone = sound.Destroying:Once(function()
                                if hooked[sound] == pair then
                                    pair.played:Disconnect()

                                    hooked[sound] = nil
                                end
                            end)
                            hooked[sound] = pair
                        end

                        for _, sound in hrp:GetChildren()do
                            if sound:IsA('Sound') then
                                hook(sound)
                            end
                        end

                        cm:Connect(hrp.ChildAdded, function(child)
                            if child:IsA('Sound') then
                                task.wait(0.1)
                                hook(child)
                            end
                        end)
                    end
                    local function connectPlayer(player)
                        if player == LocalPlayer or charMaids[player] then
                            return
                        end

                        local pm = Maid.new()

                        charMaids[player] = pm

                        pm:Connect(player.CharacterAdded, function(char)
                            task.wait(0.5)
                            connectSounds(player, char)
                        end)
                        pm:Connect(player.CharacterRemoving, function()
                            pm.char = nil
                        end)

                        if player.Character then
                            connectSounds(player, player.Character)
                        end
                    end
                    local function connectEarthPillar()
                        local thrown = Workspace:FindFirstChild('Thrown')

                        if not thrown then
                            return
                        end

                        maid:Connect(thrown.ChildAdded, function(model)
                            if not (Toggles.AutoPerfectBlock.Value and Options.ParryAbilities.Value.Viribus) or parryHeld() then
                                return
                            end
                            if not model:IsA('Model') then
                                return
                            end

                            local crater = model:WaitForChild('Crater', 1)

                            if crater and crater:IsA('Model') then
                                crater = crater.PrimaryPart or crater:FindFirstChildWhichIsA('BasePart')
                            end
                            if not (crater and crater:IsA('BasePart')) then
                                return
                            end

                            local pHRP = getHRP(getChar())

                            if not pHRP then
                                return
                            end

                            local ownMarker = 'EarthSpear' .. LocalPlayer.Name

                            for _ = 1, 12 do
                                if model:FindFirstChild(ownMarker) then
                                    return
                                end

                                local casterKnown = false

                                for _, c in model:GetChildren()do
                                    if string.sub(c.Name, 1, 10) == 'EarthSpear' then
                                        casterKnown = true

                                        break
                                    end
                                end

                                if casterKnown then
                                    break
                                end

                                task.wait(0.02)
                            end

                            if (crater.Position - pHRP.Position).Magnitude > EARTH_PILLAR_DISTANCE then
                                return
                            end

                            local closest, closestDist = nil, math.huge

                            for _, p in Players:GetPlayers()do
                                local cHRP = p ~= LocalPlayer and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                                if cHRP then
                                    local d = (cHRP.Position - crater.Position).Magnitude

                                    if d < 50 and d < closestDist then
                                        closest, closestDist = cHRP, d
                                    end
                                end
                            end

                            local function inFov(dir)
                                return pHRP.CFrame.LookVector:Dot(dir) > math.cos(math.rad(Options.ParryFovAngle.Value / 2))
                            end

                            local target = closest and closest.Position or crater.Position

                            if inFov((target - pHRP.Position).Unit) then
                                performParry(0, EARTH_PILLAR_DURATION, false, closest and Players:GetPlayerFromCharacter(closest.Parent), nil, nil, 'Viribus')
                            else
                                parryLog('Viribus dropped, the crater is outside the parry cone')
                            end
                        end)
                    end
                    local function connectGrapple(char)
                        maid.grapple = char.DescendantAdded:Connect(function(
                            child
                        )
                            if not (Toggles.AutoPerfectBlock.Value and Options.ParryAbilities.Value.Grapple) or parryHeld() then
                                return
                            end
                            if not (child:IsA('Attachment') and child.Name == 'Attachment2') then
                                return
                            end

                            task.wait(0.05)

                            local enemy

                            for _, p in Players:GetPlayers()do
                                local leftArm = p ~= LocalPlayer and p.Character and p.Character:FindFirstChild('Left Arm')
                                local cord = leftArm and leftArm:FindFirstChild('Cord')

                                if cord and cord:IsA('Beam') and cord.Attachment1 == child then
                                    enemy = p

                                    break
                                end
                            end

                            if not enemy then
                                return
                            end

                            local pHRP = getHRP(getChar())
                            local eHRP = enemy.Character and enemy.Character:FindFirstChild('HumanoidRootPart')

                            if pHRP and eHRP then
                                if not Toggles.ParrySemiBlatantBlock.Value and (pHRP.Position - eHRP.Position).Magnitude > 60 then
                                    return
                                end
                            end
                            if not Toggles.ParryIgnoreVisibility.Value and eHRP and not onScreenVisible(eHRP) then
                                parryLog('Grapple dropped, %s is not in sight', enemy.Name)

                                return
                            end

                            performParry(0, 0.25, true, enemy, false, true, 'Grapple')
                        end)
                    end
                    local function enable()
                        for _, p in Players:GetPlayers()do
                            connectPlayer(p)
                        end

                        maid:Connect(Players.PlayerAdded, connectPlayer)
                        maid:Connect(Players.PlayerRemoving, function(p)
                            if charMaids[p] then
                                charMaids[p]:DoCleaning()

                                charMaids[p] = nil
                            end
                        end)
                        connectEarthPillar()

                        if getChar() then
                            connectGrapple(getChar())
                        end

                        maid:Connect(LocalPlayer.CharacterAdded, function(char)
                            task.wait(0.5)
                            connectGrapple(char)
                        end)
                    end
                    local function disable()
                        maid:DoCleaning()

                        for _, pm in charMaids do
                            pm:DoCleaning()
                        end

                        charMaids = {}

                        unblockInputs()
                    end

                    local AutoParry = Combat:AddLeftGroupbox('Auto Parry')

                    AutoParry:AddToggle('AutoPerfectBlock', {
                        Text = 'Auto Parry',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enable()
                            else
                                disable()
                            end
                        end,
                    })
                    AutoParry:AddToggle('EnableCustomBlocks', {
                        Text = 'Enable Custom Blocks',
                        Default = false,
                        Tooltip = 'Blocks the custom parries picked below',
                    })
                    AutoParry:AddToggle('ParryDebug', {
                        Text = 'Debug Parries',
                        Default = false,
                        Tooltip = 'Prints what the parry saw and did',
                    })
                    AutoParry:AddDropdown('ParryAbilities', {
                        Text = 'Abilities',
                        Multi = true,
                        Values = {
                            'Viribus',
                            'Owlslash',
                            'Shadowrush',
                            'Verdien',
                            'Grapple',
                        },
                        Default = {
                            'Viribus',
                            'Owlslash',
                            'Shadowrush',
                        },
                    })
                    AutoParry:AddDropdown('AutoCounter', {
                        Text = 'Auto Counter',
                        Tooltip = 'Counters these instead of blocking, needs Counter',
                        Multi = true,
                        Values = {
                            'Owlslash',
                            'Shadowrush',
                        },
                        Default = {
                            'Owlslash',
                            'Shadowrush',
                        },
                        AllowNull = true,
                    })
                    AutoParry:AddDropdown('ActiveCustomBlocks', {
                        Text = 'Custom Parries',
                        Multi = true,
                        Values = {},
                        Default = {},
                        AllowNull = true,
                    })

                    local AUTOBLOCK_DIR = 'sentinel/autoblocks'
                    local loadedBlocks = {}
                    local abLogLocal = false
                    local builder

                    local function normId(id)
                        return tostring(id):match('%d+') or tostring(id)
                    end
                    local function ensureBlockDir()
                        if makefolder and not (isfolder and isfolder(AUTOBLOCK_DIR)) then
                            pcall(makefolder, 'sentinel')
                            pcall(makefolder, AUTOBLOCK_DIR)
                        end
                    end
                    local function reloadBlocks()
                        table.clear(loadedBlocks)

                        if not listfiles then
                            return
                        end

                        ensureBlockDir()

                        local ok, files = pcall(listfiles, AUTOBLOCK_DIR)

                        if not (ok and files) then
                            return
                        end

                        for _, f in files do
                            local name = tostring(f):match('([^/\\]+)%.json$')

                            if name and isfile and readfile and isfile(tostring(f)) then
                                local okc, data = pcall(function()
                                    return HttpService:JSONDecode(readfile(tostring(f)))
                                end)

                                if okc and type(data) == 'table' and data.id then
                                    loadedBlocks[name] = data
                                end
                            end
                        end
                    end
                    local function saveBlockData(form)
                        if not writefile then
                            return false
                        end

                        ensureBlockDir()

                        local data = {
                            name = form.name,
                            id = form.id,
                            kind = form.kind or 'anim',
                            delay = tonumber(form.delay) or 0,
                            hold = tonumber(form.hold) or 0,
                            range = tonumber(form.range) or 30,
                            tool = form.tool or '',
                            mode = form.mode or 'normal',
                            manaShield = form.manaShield == true,
                            frame = tonumber(form.frame) or 0,
                            enabled = form.enabled ~= false,
                        }
                        local okc, encoded = pcall(function()
                            return HttpService:JSONEncode(data)
                        end)

                        if not okc or type(encoded) ~= 'string' then
                            return false
                        end

                        local okw = pcall(writefile, AUTOBLOCK_DIR .. '/' .. form.name .. '.json', encoded)

                        if okw then
                            reloadBlocks()
                        end

                        return okw
                    end
                    local function deleteBlockData(name)
                        if delfile and name and name ~= '' then
                            pcall(delfile, AUTOBLOCK_DIR .. '/' .. name .. '.json')
                            reloadBlocks()
                        end
                    end
                    local function blockForId(id)
                        local key = normId(id)
                        local active = (Options.ActiveCustomBlocks and Options.ActiveCustomBlocks.Value) or {}

                        for name, b in loadedBlocks do
                            if active[name] and b.enabled ~= false and normId(b.id) == key then
                                return b
                            end
                        end

                        return nil
                    end
                    local function airslashLockout(id)
                        if normId(id) ~= AIRSLASH_SOUND then
                            return false
                        end

                        local char = getChar()

                        return char ~= nil and (char:FindFirstChild('AIRSLASH') ~= nil or CollectionService:HasTag(char, 'GrappledPulled'))
                    end
                    local function toolKey(name)
                        return type(name) == 'string' and name:lower():match('^%s*(.-)%s*$') or ''
                    end
                    local function equipTool(toolName)
                        local c = getChar()
                        local hum = c and c:FindFirstChildOfClass('Humanoid')

                        if not (hum and toolName and toolName ~= '') then
                            return false
                        end

                        local lower = toolKey(toolName)
                        local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                        for _, cont in {c, bp}do
                            if cont then
                                for _, t in cont:GetChildren()do
                                    if t:IsA('Tool') and t.Name:lower() == lower then
                                        hum:EquipTool(t)

                                        return true
                                    end
                                end
                            end
                        end

                        return false
                    end
                    local function isToolHeld(name)
                        local c = getChar()

                        if not c then
                            return false
                        end

                        local lower = name:lower()

                        for _, t in c:GetChildren()do
                            if t:IsA('Tool') and t.Name:lower() == lower then
                                return true
                            end
                        end

                        return false
                    end
                    local function fireCharRemote(name, ...)
                        local c = getChar()
                        local handler = c and c:FindFirstChild('CharacterHandler', true)
                        local remotes = handler and handler:FindFirstChild('Remotes')
                        local r = remotes and remotes:FindFirstChild(name)

                        if r then
                            local args = {...}

                            pcall(function()
                                r:FireServer(table.unpack(args))
                            end)
                        end
                    end
                    local function counterReady()
                        local c = getChar()

                        if not (c and c:FindFirstChild('Humanoid')) then
                            return false, 'no character'
                        end

                        local since = os.clock() - lastCounter

                        if since < COUNTER_COOLDOWN then
                            return false, string.format('%.1fs left on the cooldown', COUNTER_COOLDOWN - since)
                        end

                        for _, name in COUNTER_BLOCKERS do
                            if c:FindFirstChild(name) then
                                return false, name .. ' is on us'
                            end
                        end

                        if CollectionService:HasTag(c, 'Unconscious') or CollectionService:HasTag(c, 'Knocked') then
                            return false, 'we are down'
                        end

                        local used = c:FindFirstChild('LastUsed')
                        local stamp = used and tonumber(tostring(used.Value or ''):match('^Counter:Skill:(%d+)'))

                        if stamp and os.time() - stamp < COUNTER_COOLDOWN then
                            return false, string.format('%ds left on the cooldown', COUNTER_COOLDOWN - (os.time() - stamp))
                        end

                        return true
                    end

                    counterAttack = function()
                        local ready, why = counterReady()

                        if not ready then
                            parryLog('counter unavailable, %s', tostring(why))

                            return false
                        end
                        if not isToolHeld('Counter') then
                            if not equipTool('Counter') then
                                parryLog('counter unavailable, the tool is not on us')

                                return false
                            end

                            task.wait(0.03)
                        end

                        lastCounter = os.clock()

                        fireCharRemote('LeftClick', {
                            math.random(1, 10),
                            math.random(),
                        })

                        return true
                    end

                    local function doBlock(mode, holdDur)
                        local c = getChar()
                        local handler = c and c:FindFirstChild('CharacterHandler', true)
                        local remotes = handler and handler:FindFirstChild('Remotes')
                        local blockR = remotes and remotes:FindFirstChild('Block')
                        local unblockR = remotes and remotes:FindFirstChild('Unblock')

                        if mode == 'vim' or not (blockR and unblockR) then
                            task.spawn(function()
                                VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.F, false, game)
                                task.wait(holdDur)
                                VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.F, false, game)
                            end)
                        elseif mode == 'semiblatant' then
                            task.spawn(function()
                                local endT = os.clock() + holdDur

                                while os.clock() < endT do
                                    blockR:FireServer(false)
                                    task.wait()
                                end

                                unblockR:FireServer({})
                            end)
                        else
                            blockR:FireServer(false)
                            task.delay(holdDur, function()
                                unblockR:FireServer({})
                            end)
                        end
                    end
                    local function waitTrigger(block, track)
                        local frame = tonumber(block.frame) or 0

                        if frame > 0 and track then
                            local target = frame / 100
                            local t = 0

                            while t < 2.5 do
                                local len = track.Length or 0

                                if len > 0 and (track.TimePosition / len) >= target then
                                    return
                                end

                                task.wait()

                                t += 0.03
                            end
                        else
                            local delay = (tonumber(block.delay) or 0) / 1000

                            if delay > 0 then
                                task.wait(delay)
                            end
                        end
                    end
                    local function manaShieldBlock(block, track)
                        local mode = block.mode or 'normal'
                        local holdDur = (tonumber(block.hold) or 300) / 1000

                        task.spawn(function()
                            local c = getChar()
                            local hum = c and c:FindFirstChildOfClass('Humanoid')

                            if not hum then
                                return
                            end

                            local held

                            for _, t in c:GetChildren()do
                                if t:IsA('Tool') and t:FindFirstChild('Spell') then
                                    held = t

                                    break
                                end
                            end

                            local manaVal = c:FindFirstChild('Mana')
                            local mana = ctx.State.mana

                            if manaVal and manaVal.Value < 5 and mana and mana.available and mana.available() then
                                pcall(function()
                                    mana.chargeUntil(10)
                                end)
                            end
                            if not held then
                                local bp = LocalPlayer:FindFirstChildOfClass('Backpack')
                                local folder = bp and bp:FindFirstChild('Spell', true)
                                local spellTool = folder and folder.Parent

                                if spellTool and spellTool:IsA('Tool') then
                                    hum:EquipTool(spellTool)
                                end
                            end

                            waitTrigger(block, track)
                            doBlock(mode, holdDur)
                        end)
                    end
                    local function isSnarvindur(text)
                        return type(text) == 'string' and text:lower():find('snarvindur', 1, true) ~= nil
                    end
                    local function tempestSoulSwing(block, track, signal)
                        local c = getChar()
                        local hum = c and c:FindFirstChildOfClass('Humanoid')

                        if not hum then
                            return
                        end
                        if c:FindFirstChild('CounterSpell') then
                            return
                        end

                        local held = c:FindFirstChildOfClass('Tool')
                        local restore = held and held.Name or nil

                        if restore and toolKey(restore) == 'tempest soul' then
                            restore = nil
                        end

                        waitTrigger(block, track)

                        local mana = ctx.State.mana

                        if mana and mana.canUse and not mana.canUse() then
                            return
                        end

                        local manaVal = c:FindFirstChild('Mana')
                        local banked = isSnarvindur(signal) or isSnarvindur(block.name)

                        if banked and not (manaVal and manaVal.Value > 0) then
                            return
                        end
                        if not equipTool('Tempest Soul') then
                            return
                        end
                        if not banked then
                            if mana and mana.charge then
                                pcall(mana.charge)
                            end

                            local deadline = os.clock() + 3

                            while not (manaVal and manaVal.Value > 0) and os.clock() < deadline do
                                task.wait()

                                manaVal = c:FindFirstChild('Mana')
                            end
                        end
                        if mana and mana.decharge then
                            pcall(mana.decharge)
                        end
                        if manaVal and manaVal.Value > 0 then
                            fireCharRemote('LeftClick', {
                                math.random(1, 10),
                                math.random(),
                            })

                            local confirm = os.clock() + 1

                            while not c:FindFirstChild('CounterSpell') and os.clock() < confirm do
                                task.wait()
                            end

                            if not c:FindFirstChild('CounterSpell') then
                                Console.print('[sentinel] tempest soul: no CounterSpell after the swing')
                            end
                        end

                        task.wait(0.05)

                        if restore then
                            equipTool(restore)
                        else
                            hum:UnequipTools()
                        end
                    end

                    local lastCustomBlock = 0

                    local function runBlock(block, player, track, signal)
                        if ctx.State.isFriendly and ctx.State.isFriendly(player) then
                            return
                        end

                        local now = os.clock()

                        if now - lastCustomBlock < 0.25 then
                            return
                        end

                        lastCustomBlock = now

                        local mode = block.mode or 'normal'
                        local hold = (tonumber(block.hold) or 300) / 1000

                        if block.manaShield then
                            manaShieldBlock(block, track)

                            return
                        end

                        local tool = toolKey(block.tool)

                        if tool ~= '' then
                            if tool == 'counter' then
                                task.spawn(function()
                                    waitTrigger(block, track)
                                    counterAttack()
                                end)
                            elseif tool == 'tempest soul' then
                                task.spawn(function()
                                    tempestSoulSwing(block, track, signal)
                                end)
                            else
                                task.spawn(function()
                                    waitTrigger(block, track)
                                    equipTool(block.tool)
                                end)
                            end

                            return
                        end
                        if mode == 'off' then
                            return
                        end

                        local frame = tonumber(block.frame) or 0

                        if frame > 0 and track then
                            task.spawn(function()
                                waitTrigger(block, track)
                                performParry(0, hold, mode == 'vim', player, mode == 'semiblatant', false, tostring(block.name or 'custom block'))
                            end)
                        else
                            performParry((tonumber(block.delay) or 0) / 1000, hold, mode == 'vim', player, mode == 'semiblatant', false, tostring(block.name or 'custom block'))
                        end
                    end
                    local function matchesFilter(player, filter)
                        if not filter or filter == '' then
                            return abLogLocal == (player == LocalPlayer)
                        end

                        local f = filter:lower()

                        return player.Name:lower() == f or player.DisplayName:lower() == f or player.Name:lower():find(f, 1, true) ~= nil
                    end
                    local function onSignal(
                        player,
                        char,
                        name,
                        id,
                        kind,
                        track
                    )
                        if not id or id == '' then
                            return
                        end

                        local nm = (name and name ~= '' and name) or (kind == 'sound' and 'Sound' or 'Animation')

                        if builder and builder:IsVisible() then
                            if matchesFilter(player, builder:GetFilter()) then
                                builder:AddLog(nm, id, kind)
                            end
                            if player == LocalPlayer then
                                builder:LivePlay(id, nm, kind)
                            end
                        end
                        if player == LocalPlayer or not (Toggles.EnableCustomBlocks and Toggles.EnableCustomBlocks.Value) or parryHeld() then
                            return
                        end

                        local block = blockForId(id)

                        if not block then
                            return
                        end
                        if airslashLockout(id) then
                            return
                        end

                        local myHRP = getHRP(getChar())
                        local atkHRP = getHRP(char)

                        if myHRP and atkHRP then
                            local dist = (myHRP.Position - atkHRP.Position).Magnitude

                            if dist <= (tonumber(block.range) or 30) then
                                runBlock(block, player, track, name)
                            end
                        end
                    end

                    local obsMaid = Maid.new()

                    ctx.Maid:Give(obsMaid)

                    local animMaids = {}
                    local respawnWatch = {}
                    local observing = false

                    local function hookChar(player, char)
                        local m = animMaids[player]

                        if not m then
                            m = Maid.new()
                            animMaids[player] = m
                        end

                        m:DoCleaning()

                        local hum = char:FindFirstChildOfClass('Humanoid')

                        if hum then
                            m:Connect(hum.AnimationPlayed, function(tr)
                                local a = tr and tr.Animation

                                if a then
                                    onSignal(player, char, a.Name, a.AnimationId, 'anim', tr)
                                end
                            end)
                        else
                            m:Connect(char.ChildAdded, function(c)
                                if c:IsA('Humanoid') then
                                    hookChar(player, char)
                                end
                            end)
                        end

                        local hookedSounds = {}

                        m:Give(function()
                            for _, pair in hookedSounds do
                                pair.played:Disconnect()
                                pair.gone:Disconnect()
                            end

                            table.clear(hookedSounds)
                        end)

                        local function hookSound(s)
                            if s:IsA('Sound') and not hookedSounds[s] then
                                local pair = {}

                                pair.played = s.Played:Connect(function()
                                    onSignal(player, char, s.Name, s.SoundId, 'sound')
                                end)
                                pair.gone = s.Destroying:Once(function()
                                    if hookedSounds[s] == pair then
                                        pair.played:Disconnect()

                                        hookedSounds[s] = nil
                                    end
                                end)
                                hookedSounds[s] = pair

                                if s.IsPlaying then
                                    onSignal(player, char, s.Name, s.SoundId, 'sound')
                                end
                            end
                        end

                        for _, d in char:GetDescendants()do
                            hookSound(d)
                        end

                        m:Connect(char.DescendantAdded, hookSound)
                    end
                    local function watchPlayer(player)
                        if player.Character then
                            hookChar(player, player.Character)
                        end
                        if respawnWatch[player] then
                            respawnWatch[player]:Disconnect()
                        end

                        respawnWatch[player] = player.CharacterAdded:Connect(function(
                            char
                        )
                            task.wait(0.2)

                            if observing then
                                hookChar(player, char)
                            end
                        end)
                    end
                    local function stop_observers()
                        observing = false

                        obsMaid:DoCleaning()

                        for _, m in animMaids do
                            m:DoCleaning()
                        end

                        table.clear(animMaids)

                        for _, conn in respawnWatch do
                            conn:Disconnect()
                        end

                        table.clear(respawnWatch)
                    end
                    local function start_observers()
                        if observing then
                            return
                        end

                        observing = true

                        watchPlayer(LocalPlayer)

                        for _, p in Players:GetPlayers()do
                            if p ~= LocalPlayer then
                                watchPlayer(p)
                            end
                        end

                        obsMaid:Connect(Players.PlayerAdded, function(p)
                            if observing then
                                watchPlayer(p)
                            end
                        end)
                        obsMaid:Connect(Players.PlayerRemoving, function(p)
                            if animMaids[p] then
                                animMaids[p]:DoCleaning()

                                animMaids[p] = nil
                            end
                            if respawnWatch[p] then
                                respawnWatch[p]:Disconnect()

                                respawnWatch[p] = nil
                            end
                        end)
                    end

                    ctx.Maid:Give(stop_observers)

                    local function evaluate_observers()
                        local want = (builder and builder:IsVisible()) or (Toggles.EnableCustomBlocks and Toggles.EnableCustomBlocks.Value)

                        if want then
                            start_observers()
                        else
                            stop_observers()
                        end
                    end
                    local function pushSaved()
                        local names = {}

                        for name in loadedBlocks do
                            table.insert(names, name)
                        end

                        if Options.ActiveCustomBlocks then
                            Options.ActiveCustomBlocks:SetValues(names)
                        end
                        if not builder then
                            return
                        end

                        local list = {}

                        for _, b in loadedBlocks do
                            table.insert(list, b)
                        end

                        builder:SetSavedBlocks(list)
                    end

                    builder = Library:CreateAutoBlockBuilder({
                        Title = 'Auto Block Builder',
                        Visible = false,
                        OnSave = function(form)
                            if not form.name or form.name == '' then
                                Notify.say('Enter a block name first')

                                return
                            end
                            if not form.id or form.id == '' then
                                Notify.say('Select a detected signal first')

                                return
                            end

                            local renamed = form.editing and form.editing ~= '' and form.editing ~= form.name

                            if saveBlockData(form) then
                                if renamed then
                                    deleteBlockData(form.editing)
                                end

                                pushSaved()
                                Notify.say((renamed and 'Renamed block to: ' or 'Saved block: ') .. form.name)
                            else
                                Notify.say('Save failed (writefile required)')
                            end
                        end,
                        OnDelete = function(name)
                            if not name or name == '' then
                                return
                            end

                            deleteBlockData(name)
                            pushSaved()
                            Notify.say('Deleted block: ' .. tostring(name))
                        end,
                        OnToggleLog = function(on)
                            abLogLocal = on and true or false
                        end,
                        OnVisibleChanged = function()
                            evaluate_observers()
                        end,
                    })

                    reloadBlocks()
                    pushSaved()

                    if Toggles.EnableCustomBlocks then
                        Toggles.EnableCustomBlocks:OnChanged(function()
                            evaluate_observers()
                        end)
                    end

                    AutoParry:AddButton({
                        Text = 'Open Auto Block Builder',
                        Func = function()
                            builder:Toggle()
                        end,
                    })
                    evaluate_observers()

                    local SettingsBox = Combat:AddRightGroupbox('Parry Settings')

                    SettingsBox:AddToggle('ParryPingAdjust', {
                        Text = 'Ping Adjustment',
                        Default = true,
                    })
                    SettingsBox:AddToggle('ParryCustomDelay', {
                        Text = 'Use Custom Delay',
                        Default = false,
                    })
                    SettingsBox:AddSlider('ParryCustomDelayMs', {
                        Text = 'Custom Delay',
                        Min = -500,
                        Max = 500,
                        Default = 0,
                        Rounding = 0,
                        Suffix = 'ms',
                    })
                    SettingsBox:AddSlider('ParryFovAngle', {
                        Text = 'FOV Angle',
                        Min = 0,
                        Max = 360,
                        Default = 120,
                        Rounding = 0,
                    })
                    SettingsBox:AddToggle('ParryDisableWhenUnfocused', {
                        Text = 'Disable When Unfocused',
                        Tooltip = 'Off while tabbed out, typing, observing or in freecam',
                        Default = false,
                    })
                    SettingsBox:AddToggle('ParryIgnoreVisibility', {
                        Text = 'Ignore Visibility (Blatant)',
                        Default = false,
                    })

                    local semiBlatant = SettingsBox:AddToggle('ParrySemiBlatantBlock', {
                        Text = 'Semi-Blatant Block',
                        Default = false,
                        Tooltip = RISKY_TOOLTIP,
                    })

                    Gate.mark(ctx, 'Risky', 'ParrySemiBlatantBlock', semiBlatant)
                end
                do
                    local maid = Maid.new()

                    ctx.Maid:Give(maid)

                    local CombatUtils = Combat:AddLeftGroupbox('Combat Utilities')

                    local function blatantOn()
                        local toggle = Toggles.BlatantMode

                        return toggle ~= nil and toggle.Value == true
                    end
                    local function fireCharacterRemote(name, ...)
                        local char = getChar()
                        local handler = char and char:FindFirstChild('CharacterHandler')
                        local remotes = handler and handler:FindFirstChild('Remotes')
                        local remote = remotes and remotes:FindFirstChild(name)

                        if remote then
                            remote:FireServer(...)
                        end
                    end

                    do
                        local holdMaid = Maid.new()

                        maid:Give(holdMaid)

                        local holdingF = false
                        local lastBlock = 0
                        local hadSpell = false
                        local spellStopped = false
                        local dropAt = 0

                        local function blockSuppressed(char)
                            return CollectionService:HasTag(char, 'Knocked') or CollectionService:HasTag(char, 'Unconscious') or char:FindFirstChild('Grabbed') ~= nil or char:FindFirstChild('Climbing') ~= nil or char:FindFirstChild('AttackExcept') ~= nil
                        end
                        local function startHoldBlock()
                            holdMaid:Connect(UserInputService.InputBegan, function(
                                input,
                                processed
                            )
                                if not processed and input.KeyCode == Enum.KeyCode.F then
                                    holdingF = true
                                    spellStopped = false
                                end
                            end)
                            holdMaid:Connect(UserInputService.InputEnded, function(
                                input
                            )
                                if input.KeyCode == Enum.KeyCode.F then
                                    holdingF = false
                                end
                            end)
                            holdMaid:Connect(RunService.RenderStepped, BASIL_NO_VIRTUALIZE(function(
                            )
                                local char = getChar()

                                if not char then
                                    hadSpell = false
                                    spellStopped = false

                                    return
                                end

                                local spellBlock = char:FindFirstChild('SpellBlocking') ~= nil

                                if hadSpell and not spellBlock then
                                    spellStopped = true
                                    dropAt = os.clock()

                                    if holdingF then
                                        pcall(fireCharacterRemote, 'Unblock', {})
                                    end
                                end

                                hadSpell = spellBlock

                                if not holdingF then
                                    return
                                end
                                if spellBlock then
                                    return
                                end
                                if spellStopped then
                                    local now = os.clock()

                                    if now - dropAt < 0.2 then
                                        if now - lastBlock >= 0.016 then
                                            lastBlock = now

                                            pcall(fireCharacterRemote, 'Unblock', {})
                                        end
                                    elseif char:FindFirstChild('Blocking') and now - lastBlock >= 0.05 then
                                        lastBlock = now

                                        pcall(fireCharacterRemote, 'Unblock', {})
                                    end

                                    return
                                end
                                if blockSuppressed(char) then
                                    return
                                end
                                if char:FindFirstChild('Blocking') then
                                    return
                                end

                                local now = os.clock()

                                if now - lastBlock < math.max(Options.HoldBlockDelay.Value / 1000, 0.1) then
                                    return
                                end

                                lastBlock = now

                                pcall(fireCharacterRemote, 'Block', false)
                            end))
                        end
                        local function stopHoldBlock()
                            holdingF = false

                            holdMaid:DoCleaning()
                        end

                        local holdBlock = CombatUtils:AddToggle('HoldBlock', {
                            Text = 'Hold Block (F)',
                            Default = false,
                            Tooltip = RISKY_TOOLTIP,
                            Callback = function(on)
                                if on then
                                    startHoldBlock()
                                else
                                    stopHoldBlock()
                                end
                            end,
                        })

                        Gate.mark(ctx, 'Risky', 'HoldBlock', holdBlock)
                        CombatUtils:AddSlider('HoldBlockDelay', {
                            Text = 'Block Delay',
                            Min = 0,
                            Max = 1000,
                            Default = 0,
                            Rounding = 0,
                            Suffix = 'ms',
                        })
                    end
                    do
                        local carryMaid = Maid.new()

                        maid:Give(carryMaid)

                        local holdingV = false

                        local function startHoldCarry()
                            carryMaid:Connect(UserInputService.InputBegan, function(
                                input,
                                processed
                            )
                                if not processed and input.KeyCode == Enum.KeyCode.V then
                                    holdingV = true
                                end
                            end)
                            carryMaid:Connect(UserInputService.InputEnded, function(
                                input
                            )
                                if input.KeyCode == Enum.KeyCode.V then
                                    holdingV = false
                                end
                            end)
                            carryMaid:Connect(RunService.RenderStepped, BASIL_NO_VIRTUALIZE(function(
                            )
                                local char = holdingV and getChar()

                                if not char or char:FindFirstChild('Grabbing') or char:FindFirstChild('Climbing') then
                                    return
                                end

                                pcall(fireCharacterRemote, 'Carry')
                            end))
                        end

                        local holdCarry = CombatUtils:AddToggle('HoldCarry', {
                            Text = 'Hold Carry (V)',
                            Default = false,
                            Tooltip = RISKY_TOOLTIP,
                            Callback = function(on)
                                holdingV = false

                                carryMaid:DoCleaning()

                                if on then
                                    startHoldCarry()
                                end
                            end,
                        })

                        Gate.mark(ctx, 'Risky', 'HoldCarry', holdCarry)
                    end
                    do
                        local pfMaid = Maid.new()

                        maid:Give(pfMaid)

                        local active = {}

                        local function targetHRP()
                            local cam = Workspace.CurrentCamera
                            local subject = cam and cam.CameraSubject

                            if not (subject and subject.Name == 'Humanoid') then
                                return nil
                            end

                            local model = subject.Parent

                            if not model or model == getChar() then
                                return nil
                            end

                            return model:FindFirstChild('HumanoidRootPart')
                        end
                        local function isProjectile(name)
                            local ok, hit = pcall(string.match, 'FlowerProjectile', name)

                            return ok and hit ~= nil
                        end
                        local function startPerflora()
                            local thrown = Workspace:FindFirstChild('Thrown')

                            if not thrown then
                                return
                            end

                            table.clear(active)

                            for _, child in thrown:GetChildren()do
                                if child:IsA('BasePart') and isProjectile(child.Name) then
                                    active[child] = true
                                end
                            end

                            pfMaid:Connect(thrown.ChildAdded, function(child)
                                if child:IsA('BasePart') and isProjectile(child.Name) then
                                    active[child] = true
                                end
                            end)
                            pfMaid:Connect(thrown.ChildRemoved, function(child)
                                active[child] = nil
                            end)
                            pfMaid:Connect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                            )
                                local hrp = targetHRP()

                                if not hrp then
                                    return
                                end

                                local pos = hrp.Position

                                for proj in active do
                                    if proj.Parent then
                                        proj.Position = pos
                                    else
                                        active[proj] = nil
                                    end
                                end
                            end))
                        end
                        local function stopPerflora()
                            pfMaid:DoCleaning()
                            table.clear(active)
                        end

                        CombatUtils:AddToggle('PerfloraTeleport', {
                            Text = 'Perflora Teleport',
                            Tooltip = Gate.blatant('homes Perflora onto your target'),
                            Default = false,
                            Callback = function(on)
                                if on then
                                    startPerflora()
                                else
                                    stopPerflora()
                                end
                            end,
                        })
                        Gate.mark(ctx, 'Blatant', 'PerfloraTeleport')
                    end
                    do
                        local OPAL_REACH = 13
                        local OPAL_SWING_WINDOW = 1
                        local OPAL_BURST = 0.4
                        local FLAT = Vector3.new(1, 0, 1)
                        local opalMaid = Maid.new()

                        maid:Give(opalMaid)

                        local opal = {
                            swingAt = 0,
                            selfPlays = setmetatable({}, {
                                __mode = 'k',
                            }),
                            bursts = setmetatable({}, {
                                __mode = 'k',
                            }),
                            realOn = nil,
                        }

                        local function weaponTool()
                            local char = getChar()
                            local tool = char and char:FindFirstChildOfClass('Tool')

                            return (tool and tool:FindFirstChild('PrimaryWeapon')) and tool or nil
                        end
                        local function facedTarget(char, myRoot)
                            local live = Workspace:FindFirstChild('Live')
                            local look = myRoot.CFrame.LookVector * FLAT

                            if not live or look.Magnitude < 0.01 then
                                return nil
                            end

                            look = look.Unit

                            local best, bestDot

                            for _, model in live:GetChildren()do
                                local root = model ~= char and getHRP(model)

                                if root and (root.Position - myRoot.Position).Magnitude <= OPAL_REACH then
                                    local flat = (root.Position - myRoot.Position) * FLAT
                                    local dot = flat.Magnitude > 0.01 and look:Dot(flat.Unit) or 1

                                    if dot > 0 and (not bestDot or dot > bestDot) then
                                        best, bestDot = model, dot
                                    end
                                end
                            end

                            return best
                        end
                        local function ourHit(model)
                            local char = getChar()
                            local myRoot = getHRP(char)

                            if model == char or not myRoot or facedTarget(char, myRoot) ~= model then
                                return false
                            end

                            return os.clock() - opal.swingAt <= OPAL_SWING_WINDOW or char:FindFirstChild('LightAttack') ~= nil or char:FindFirstChild('HeavyAttack') ~= nil
                        end
                        local function burst(emit)
                            local held = opal.bursts[emit]

                            if not held then
                                held = {
                                    was = emit.Enabled,
                                }
                                opal.bursts[emit] = held
                            end

                            held.untilAt = os.clock() + OPAL_BURST
                            emit.Enabled = true

                            task.delay(OPAL_BURST, function()
                                if opal.bursts[emit] == held and os.clock() >= held.untilAt then
                                    opal.bursts[emit] = nil
                                    emit.Enabled = held.was
                                end
                            end)
                        end
                        local function watchClash(m, model, clash)
                            if m.clash or not (clash and clash:IsA('Sound')) then
                                return
                            end

                            m.clash = clash.Played:Connect(function()
                                local mine = opal.selfPlays[clash] or 0

                                if mine > 0 then
                                    opal.selfPlays[clash] = mine - 1
                                elseif ourHit(model) then
                                    opal.realOn = weaponTool()
                                end
                            end)
                        end
                        local function onStun(model, m)
                            local tool = weaponTool()

                            if not tool or tool == opal.realOn or not ourHit(model) then
                                return
                            end

                            local root = getHRP(model)
                            local emit = root:FindFirstChild('HolyEmit')
                            local clash = root:FindFirstChild('HolyClash')

                            watchClash(m, model, clash)

                            if emit and emit:IsA('ParticleEmitter') then
                                burst(emit)
                            end
                            if clash and clash:IsA('Sound') then
                                opal.selfPlays[clash] = (opal.selfPlays[clash] or 0) + 1

                                clash:Play()
                            end
                        end
                        local function hook(model)
                            if not model:IsA('Model') or model == getChar() or opalMaid[model] then
                                return
                            end

                            local m = Maid.new()

                            opalMaid[model] = m

                            m:Connect(model.ChildAdded, function(child)
                                if child.Name == 'Stun' then
                                    onStun(model, m)
                                end
                            end)

                            local root = getHRP(model)

                            watchClash(m, model, root and root:FindFirstChild('HolyClash'))
                        end
                        local function watchSwing(char)
                            opalMaid.swing = char and char.ChildAdded:Connect(function(
                                child
                            )
                                if child.Name == 'LightAttack' or child.Name == 'HeavyAttack' then
                                    opal.swingAt = os.clock()
                                end
                            end) or nil
                        end
                        local function startOpal()
                            local live = Workspace:FindFirstChild('Live')

                            if not live then
                                return
                            end

                            for _, model in live:GetChildren()do
                                hook(model)
                            end

                            opalMaid.added = live.ChildAdded:Connect(hook)
                            opalMaid.removed = live.ChildRemoved:Connect(function(
                                model
                            )
                                opalMaid[model] = nil
                            end)

                            watchSwing(getChar())

                            opalMaid.respawn = LocalPlayer.CharacterAdded:Connect(watchSwing)
                        end

                        CombatUtils:AddToggle('OpalHit', {
                            Text = 'Opal Hit',
                            Default = false,
                            Tooltip = 'Opal hit sound on whoever you hit',
                            Callback = function(on)
                                opalMaid:DoCleaning()

                                opal.realOn = nil

                                if on then
                                    startOpal()
                                end
                            end,
                        })
                    end
                    do
                        local CHARGE_KEY = Enum.KeyCode.G

                        maid:Connect(UserInputService.InputBegan, function(
                            input,
                            processed
                        )
                            if processed or input.KeyCode ~= CHARGE_KEY then
                                return
                            end
                            if not Toggles.BetterManaCharge.Value or not getChar() then
                                return
                            end

                            local mana = ctx.State.mana

                            if not mana or not mana.available() then
                                return
                            end

                            task.spawn(function()
                                mana.charge()
                                task.wait(0.1 + Utility.getPing() / 900)

                                repeat
                                    task.wait()

                                    local char = getChar()

                                    if char and not char:FindFirstChild('Charge') then
                                        mana.charge()
                                        task.wait(0.1 + Utility.getPing() / 900)
                                    end
                                until not UserInputService:IsKeyDown(CHARGE_KEY) or not (Toggles.BetterManaCharge and Toggles.BetterManaCharge.Value)

                                mana.decharge()
                            end)
                        end)
                        CombatUtils:AddToggle('BetterManaCharge', {
                            Text = 'Better Mana Charge',
                            Tooltip = 'Hold G to charge through stuns',
                            Default = false,
                        })
                    end
                    do
                        local charMaid = Maid.new()

                        maid:Give(charMaid)

                        local TDT_BLOCK_STATES = {
                            'Grabbed',
                            'Climbing',
                            'ClimbCoolDown',
                            'ManaStop',
                            'SpellBlocking',
                            'ActiveCast',
                            'Stun',
                        }

                        local function canAct(char)
                            for _, blocker in TDT_BLOCK_STATES do
                                if char:FindFirstChild(blocker) then
                                    return false
                                end
                            end

                            return not (CollectionService:HasTag(char, 'Knocked') or CollectionService:HasTag(char, 'Unconscious'))
                        end

                        local tdtArmedAt = 0

                        task.spawn(function()
                            local ok, vfx = pcall(function()
                                local requests = ReplicatedStorage:WaitForChild('Requests', 10)

                                return requests and requests:WaitForChild('ClientVFX', 10)
                            end)

                            if ok and vfx then
                                maid:Connect(vfx.OnClientEvent, function(
                                    name,
                                    data
                                )
                                    if name == 'ShadowDagger' and type(data) == 'table' and data.char == getChar() then
                                        tdtArmedAt = os.clock()
                                    end
                                end)
                            end
                        end)

                        local function setup(char)
                            charMaid:DoCleaning()

                            if not char then
                                return
                            end

                            tdtArmedAt = 0

                            charMaid:Connect(char.ChildRemoved, function(child)
                                if child.Name == 'Triple Dagger Throw' then
                                    tdtArmedAt = 0
                                end
                                if not Toggles.BetterUnequip.Value then
                                    return
                                end
                                if not (child:IsA('Tool') and UNEQUIP_WEAPONS[child.Name]) then
                                    return
                                end

                                task.defer(function()
                                    local c = getChar()
                                    local hum = c and c:FindFirstChildOfClass('Humanoid')

                                    if not hum then
                                        return
                                    end

                                    local currentTool = c:FindFirstChildOfClass('Tool')
                                    local isDaggerSkill = currentTool and child.Name == 'Dagger' and DAGGER_SKILLS[currentTool.Name]
                                    local isRapierSkill = currentTool and child.Name == 'Rapier' and RAPIER_SKILLS[currentTool.Name]

                                    if currentTool and not (isDaggerSkill or isRapierSkill) then
                                        return
                                    end

                                    local reequipName = (isDaggerSkill or isRapierSkill) and currentTool.Name or nil
                                    local bypass = findBypassTool(child.Name)

                                    if bypass then
                                        hum:EquipTool(bypass)
                                        task.wait(UNEQUIP_BYPASS_WAIT)
                                    end

                                    hum:UnequipTools()

                                    if reequipName then
                                        task.wait(0.01)

                                        local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
                                        local tool = backpack and backpack:FindFirstChild(reequipName)

                                        if tool then
                                            hum:EquipTool(tool)
                                        end
                                    end
                                end)
                            end)
                        end

                        setup(getChar())
                        maid:Connect(LocalPlayer.CharacterAdded, setup)
                        maid:Connect(UserInputService.InputBegan, function(
                            input,
                            processed
                        )
                            if processed or not Toggles.BetterUnequip.Value then
                                return
                            end

                            local isR = input.KeyCode == Enum.KeyCode.R
                            local isRMB = input.UserInputType == Enum.UserInputType.MouseButton2

                            if not (isR or isRMB) then
                                return
                            end

                            local c = getChar()
                            local hum = c and c:FindFirstChildOfClass('Humanoid')
                            local tdt = c and c:FindFirstChild('Triple Dagger Throw')

                            if not (hum and tdt and tdt:IsA('Tool')) then
                                return
                            end
                            if not (canAct(c) and os.clock() - tdtArmedAt <= TDT_M2_WINDOW) then
                                return
                            end

                            hum:UnequipTools()
                            fireCharacterRemote('RightClick', {
                                math.random(1, 10),
                                math.random(),
                            })

                            tdtArmedAt = 0
                        end)
                        CombatUtils:AddToggle('BetterUnequip', {
                            Text = 'Better Unequip',
                            Default = false,
                            Tooltip = 'Skips the unequip animation',
                        })
                    end
                    do
                        local function handleChild(obj)
                            if not Toggles.AutoMisogi.Value or obj.Name ~= 'LandedShoryuExcept' then
                                return
                            end

                            task.wait(0.02)

                            local char = getChar()
                            local hum = char and char:FindFirstChildOfClass('Humanoid')
                            local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
                            local tool = backpack and backpack:FindFirstChild('Rising Dragon')

                            if not (hum and tool) then
                                return
                            end

                            hum:EquipTool(tool)
                            task.spawn(function()
                                while Toggles.AutoMisogi.Value and obj.Parent == char and not char:FindFirstChild('TPSafe') do
                                    if not char:FindFirstChild('Rising Dragon') then
                                        local bp = LocalPlayer:FindFirstChildOfClass('Backpack')
                                        local re = bp and bp:FindFirstChild('Rising Dragon')

                                        if re then
                                            hum:EquipTool(re)
                                        end
                                    end

                                    fireCharacterRemote('RightClick', {
                                        math.random(1, 10),
                                        math.random(),
                                    })
                                    task.wait(0.1)
                                end
                            end)
                        end

                        local charMaid = Maid.new()

                        maid:Give(charMaid)

                        local function setup(char)
                            charMaid:DoCleaning()

                            if char then
                                charMaid:Connect(char.ChildAdded, handleChild)
                            end
                        end

                        setup(getChar())
                        maid:Connect(LocalPlayer.CharacterAdded, setup)
                        CombatUtils:AddToggle('AutoMisogi', {
                            Text = 'Auto Misogi',
                            Default = false,
                        })
                    end
                    do
                        local function strip(obj)
                            if obj.Name == 'Confused' and Toggles.NoHystericus and Toggles.NoHystericus.Value then
                                task.defer(function()
                                    pcall(function()
                                        obj:Destroy()
                                    end)
                                end)
                            end
                        end

                        local confusedMaid = Maid.new()

                        maid:Give(confusedMaid)

                        local function watch(char)
                            confusedMaid:DoCleaning()

                            if not char then
                                return
                            end

                            confusedMaid:Connect(char.ChildAdded, strip)

                            local existing = char:FindFirstChild('Confused')

                            if existing then
                                strip(existing)
                            end
                        end

                        watch(getChar())
                        maid:Connect(LocalPlayer.CharacterAdded, watch)
                        CombatUtils:AddToggle('NoHystericus', {
                            Text = 'No Hystericus',
                            Default = false,
                        })
                    end
                    do
                        local slotMaid = Maid.new()

                        maid:Give(slotMaid)

                        local toolMaid = Maid.new()

                        maid:Give(toolMaid)

                        local cd = {
                            counting = {},
                            onCooldown = {},
                            tool = '',
                            spell = '',
                            painted = false,
                        }

                        local function shown()
                            return Toggles.CooldownIndicator ~= nil and Toggles.CooldownIndicator.Value == true
                        end
                        local function slotContainers()
                            local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                            local gui = pg and pg:FindFirstChild('BackpackGui')
                            local bag = gui and gui:FindFirstChild('BackpackFrame')

                            return {
                                gui and gui:FindFirstChild('MainFrame'),
                                bag and bag:FindFirstChild('ScrollingFrame'),
                            }
                        end
                        local function slotFor(text)
                            for _, container in slotContainers()do
                                for _, slot in container:GetChildren()do
                                    if slot:IsA('TextButton') and slot.Text == text then
                                        return slot
                                    end
                                end
                            end

                            return nil
                        end
                        local function paintSlots(show)
                            for _, container in slotContainers()do
                                for _, slot in container:GetChildren()do
                                    local spellFrame, meleeFrame = slot:FindFirstChild('SpellFrame'), slot:FindFirstChild('MeleeFrame')
                                    local overlay = slot:FindFirstChild('Overlay')

                                    if show then
                                        if spellFrame then
                                            spellFrame.Visible = true

                                            if overlay then
                                                overlay.ImageColor3 = SLOT.spell
                                            end
                                        elseif meleeFrame then
                                            meleeFrame.Visible = true

                                            if overlay then
                                                overlay.ImageColor3 = SLOT.meleeShown
                                            end
                                        end
                                    else
                                        if spellFrame then
                                            spellFrame.Visible = false
                                        elseif meleeFrame then
                                            meleeFrame.Visible = false
                                        end
                                        if overlay then
                                            overlay.ImageColor3 = SLOT.idle
                                        end
                                    end
                                end
                            end
                        end
                        local function canStart(char, toolName, isSpell)
                            local head = char and char:FindFirstChild('Head')

                            if not head or (head.Transparency == 1 and not SLOT.invisible[toolName]) then
                                return false
                            end
                            if char:FindFirstChild('SpellBlocking') and not isSpell then
                                return false
                            end

                            for _, name in SLOT.blockers do
                                if char:FindFirstChild(name) then
                                    return false
                                end
                            end

                            local live = Workspace:FindFirstChild('Live')

                            return head:FindFirstChild('Bone') == nil and live ~= nil and live:FindFirstChild(char.Name) ~= nil
                        end
                        local function countdown(kind, toolName)
                            local isSpell = kind ~= 'melee'

                            if not canStart(getChar(), toolName, isSpell) then
                                return
                            end

                            local spellName = cd.spell
                            local length

                            if kind == 'melee' then
                                length = SkillCooldowns.skills[toolName]

                                if toolName == 'Bane' and type(length) == 'number' then
                                    local bag = LocalPlayer:FindFirstChildOfClass('Backpack')

                                    length += (bag and bag:FindFirstChild('UpgradedBane')) and 5 or
-5
                                end

                                cd.onCooldown[toolName] = true
                            elseif kind == 'spell' then
                                length = SkillCooldowns.spells[spellName]
                            else
                                length = SkillCooldowns.special[spellName]
                            end
                            if type(length) ~= 'number' then
                                cd.onCooldown[toolName] = nil

                                return
                            end

                            task.spawn(function()
                                task.wait(length)

                                if kind == 'melee' then
                                    cd.onCooldown[toolName] = nil
                                end
                            end)

                            local slot = slotFor(isSpell and spellName or toolName)

                            if not slot then
                                return
                            end

                            local colour = SLOT[kind]
                            local frame = Make('Frame', {
                                Name = isSpell and 'SpellFrame' or 'MeleeFrame',
                                BorderSizePixel = 0,
                                AnchorPoint = Vector2.new(0, 1),
                                Position = UDim2.new(0, 0, 1, 0),
                                Size = UDim2.new(1, 0, 1, 0),
                                BackgroundTransparency = 0.7,
                                ZIndex = 1,
                                BackgroundColor3 = colour,
                                Parent = slot,
                            })

                            cd.counting[frame] = true

                            task.spawn(function()
                                for _ = 1, 100 do
                                    if not frame.Parent then
                                        break
                                    end

                                    frame.Size = UDim2.new(1, 0, frame.Size.Y.Scale - 0.01, 0)

                                    task.wait(length / 100)

                                    local overlay = slot:FindFirstChild('Overlay')

                                    if overlay and overlay.ImageColor3 ~= colour and kind ~= 'special' and shown() then
                                        overlay.ImageColor3 = colour
                                    end
                                end

                                cd.counting[frame] = nil

                                local overlay = slot:FindFirstChild('Overlay')

                                if overlay then
                                    overlay.ImageColor3 = SLOT.idle
                                end

                                frame:Destroy()
                            end)
                        end
                        local function onToolAdded(child)
                            local name = child.Name

                            if cd.tool ~= '' or not child:IsA('Tool') then
                                return
                            end
                            if SkillCooldowns.skills[name] == nil and SkillCooldowns.spells[name] == nil then
                                return
                            end

                            cd.tool = name

                            local mouse = LocalPlayer:GetMouse()

                            toolMaid:Connect(mouse.Button1Down, function()
                                if shown() and SkillCooldowns.skills[name] and not cd.onCooldown[name] then
                                    countdown('melee', name)
                                end
                            end)
                            toolMaid:Connect(mouse.Button2Down, function()
                                if shown() and (child:FindFirstChild('Spell') or child:FindFirstChild('GodSpell') or child:FindFirstChild('SkillSpell')) then
                                    cd.spell = name
                                end
                            end)

                            local char = getChar()
                            local humanoid = char and char:FindFirstChildOfClass('Humanoid')

                            if humanoid then
                                toolMaid:Connect(humanoid.AnimationPlayed, function(
                                    track
                                )
                                    if not (shown() and SLOT.casts[track.Animation.AnimationId] and type(SkillCooldowns.spells[cd.spell]) == 'number') then
                                        return
                                    end
                                    if SkillCooldowns.special[cd.spell] then
                                        task.spawn(countdown, 'special', name)
                                    end

                                    countdown('spell', name)
                                end)
                            end
                        end
                        local function onToolRemoved(child)
                            if child.Name == cd.tool then
                                cd.tool = ''

                                toolMaid:DoCleaning()
                            end
                        end
                        local function hook(char)
                            cd.tool = ''

                            toolMaid:DoCleaning()

                            if not char then
                                return
                            end

                            slotMaid.added = char.ChildAdded:Connect(onToolAdded)
                            slotMaid.removed = char.ChildRemoved:Connect(onToolRemoved)
                        end

                        maid:Give(function()
                            for frame in cd.counting do
                                pcall(frame.Destroy, frame)
                            end

                            table.clear(cd.counting)

                            if cd.painted then
                                paintSlots(false)
                            end
                        end)
                        CombatUtils:AddToggle('CooldownIndicator', {
                            Text = 'Cooldown Indicator',
                            Default = false,
                            Tooltip = 'Shades hotbar slots on cooldown',
                            Callback = function(on)
                                slotMaid:DoCleaning()
                                toolMaid:DoCleaning()

                                cd.tool = ''

                                if on or cd.painted then
                                    paintSlots(on)
                                end
                                if not on then
                                    return
                                end

                                cd.painted = true

                                hook(getChar())

                                slotMaid.respawn = LocalPlayer.CharacterAdded:Connect(function(
                                    char
                                )
                                    table.clear(cd.onCooldown)

                                    cd.spell = ''

                                    hook(char)
                                end)
                            end,
                        })
                    end
                    do
                        local attachMaid = Maid.new()

                        maid:Give(attachMaid)

                        local victim
                        local glueProp, gluedRoot

                        local function glue(root, part)
                            if not (root and sethiddenproperty) or glueProp == false then
                                return
                            end
                            if glueProp then
                                pcall(sethiddenproperty, root, glueProp, part)
                            else
                                for _, prop in {
                                    'PhysicsRepRootPart',
                                    'PhysicsRepRootRef',
                                }do
                                    if pcall(sethiddenproperty, root, prop, part) then
                                        glueProp = prop

                                        break
                                    end
                                end

                                glueProp = glueProp or false
                            end

                            gluedRoot = (glueProp and part) and root or nil
                        end
                        local function unglue()
                            if gluedRoot then
                                glue(gluedRoot, nil)
                            end
                        end
                        local function getNearby()
                            local pHRP = getHRP(getChar())

                            if not pHRP then
                                return nil
                            end

                            local cam = Workspace.CurrentCamera
                            local mousePos = UserInputService:GetMouseLocation()
                            local closest, minDist = nil, 350

                            for _, player in Players:GetPlayers()do
                                local char = player ~= LocalPlayer and player.Character
                                local hrp = char and getHRP(char)
                                local hum = char and char:FindFirstChildOfClass('Humanoid')

                                if hrp and hum and hum.Health > 0 then
                                    local screen, onScreen = cam:WorldToViewportPoint(hrp.Position)

                                    if onScreen then
                                        local sd = (mousePos - Vector2.new(screen.X, screen.Y)).Magnitude

                                        if sd < minDist and (pHRP.Position - hrp.Position).Magnitude < 130 then
                                            closest, minDist = player, sd
                                        end
                                    end
                                end
                            end

                            return closest
                        end
                        local function stopAttach()
                            attachMaid:DoCleaning()
                            unglue()

                            local char = getChar()

                            if char then
                                local torso = char:FindFirstChild('Torso')
                                local head = char:FindFirstChild('Head')

                                if torso then
                                    torso.CanCollide = true
                                end
                                if head then
                                    head.CanCollide = true
                                end
                            end

                            victim = nil
                        end

                        ctx.Maid:Give(stopAttach)

                        local function startAttach()
                            attachMaid:DoCleaning()

                            victim = getNearby()

                            attachMaid:Connect(RunService.Stepped, BASIL_NO_VIRTUALIZE(function(
                            )
                                if not blatantOn() then
                                    victim = nil

                                    unglue()

                                    return
                                end
                                if not victim then
                                    victim = getNearby()

                                    if not victim then
                                        unglue()

                                        return
                                    end
                                end

                                local char = getChar()
                                local victimChar = victim.Character
                                local pHRP = getHRP(char)
                                local vHRP = victimChar and getHRP(victimChar)
                                local vHum = victimChar and victimChar:FindFirstChildOfClass('Humanoid')

                                if not (pHRP and vHRP and vHum) or vHum.Health <= 0 then
                                    victim = nil

                                    unglue()

                                    return
                                end
                                if (pHRP.Position - vHRP.Position).Magnitude > 130 then
                                    victim = nil

                                    unglue()

                                    return
                                end

                                pHRP.AssemblyLinearVelocity = Vector3.zero

                                local torso = char:FindFirstChild('Torso')
                                local head = char:FindFirstChild('Head')

                                if torso then
                                    torso.CanCollide = false
                                end
                                if head then
                                    head.CanCollide = false
                                end
                                if Toggles.Fling and Toggles.Fling.Value then
                                    unglue()

                                    pHRP.CFrame = vHRP.CFrame * CFrame.new(0, -2, 0)

                                    return
                                end

                                glue(pHRP, vHRP)

                                local offset = 2

                                if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                                    offset = -1
                                elseif UserInputService:IsKeyDown(Enum.KeyCode.S) then
                                    offset = 6.5
                                end
                                if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                                    pHRP.CFrame = vHRP.CFrame + vHRP.CFrame:VectorToWorldSpace(Vector3.new(1, 0, 0) *
-3) + vHRP.CFrame.LookVector * -offset
                                elseif UserInputService:IsKeyDown(Enum.KeyCode.D) then
                                    pHRP.CFrame = vHRP.CFrame + vHRP.CFrame:VectorToWorldSpace(Vector3.new(
-1, 0, 0) * -3) + vHRP.CFrame.LookVector * -offset
                                else
                                    pHRP.CFrame = vHRP.CFrame + vHRP.CFrame.LookVector *
-offset
                                end
                            end))
                        end

                        CombatUtils:AddLabel({
                            Text = 'Attach to Back',
                            Tooltip = Gate.blatant(),
                        }):AddKeyPicker('AttachToBackKeybind', {
                            Default = 'None',
                            Mode = 'Toggle',
                            Text = 'Attach to Back',
                            Callback = function(state)
                                if not state then
                                    stopAttach()

                                    return
                                end
                                if not blatantOn() then
                                    Notify.say('Attach to Back requires Blatant Mode')

                                    return
                                end

                                startAttach()
                            end,
                        })
                    end
                end
                do
                    local cloneref = cloneref or function(x)
                        return x
                    end
                    local maid = Maid.new()

                    ctx.Maid:Give(maid)

                    local aimRunning = false
                    local silentTarget, silentVector, silentPart
                    local fovCircle, fovOutline
                    local mouse, mouseRemote, remoteResolved

                    ctx.Maid:Give(function()
                        for _, drawing in {fovCircle, fovOutline}do
                            if drawing then
                                pcall(function()
                                    drawing:Remove()
                                end)
                            end
                        end

                        if mouseRemote and mouse then
                            mouseRemote.OnClientInvoke = function()
                                return {
                                    Hit = mouse.Hit,
                                    Target = mouse.Target,
                                    UnitRay = mouse.UnitRay,
                                    X = mouse.X,
                                    Y = mouse.Y,
                                }
                            end
                        end
                    end)

                    local function ensureDrawings()
                        if fovCircle then
                            return
                        end

                        fovOutline = Drawing.new('Circle')
                        fovOutline.Thickness = FOV_OUTLINE_THICKNESS
                        fovOutline.NumSides = FOV_SIDES
                        fovOutline.Filled = false
                        fovOutline.Color = Color3.new(0, 0, 0)
                        fovOutline.Transparency = FOV_OUTLINE_ALPHA
                        fovOutline.Visible = false
                        fovCircle = Drawing.new('Circle')
                        fovCircle.Thickness = FOV_THICKNESS
                        fovCircle.NumSides = FOV_SIDES
                        fovCircle.Filled = false
                        fovCircle.Color = FOV_DEFAULT_COLOR
                        fovCircle.Transparency = 1
                        fovCircle.Visible = false
                    end
                    local function resolveRemote()
                        if remoteResolved then
                            return
                        end

                        remoteResolved = true
                        mouse = cloneref(LocalPlayer:GetMouse())

                        if game.PlaceId == NO_MOUSE_REMOTE_PLACE then
                            return
                        end

                        local requests = ReplicatedStorage:WaitForChild('Requests', 5)

                        mouseRemote = requests and requests:WaitForChild('GetMouse', 5)
                    end
                    local function cameraCanSee(part, targetChar)
                        local cam = Workspace.CurrentCamera
                        local camPos = cam.CFrame.Position
                        local dir = part.Position - camPos
                        local params = RaycastParams.new()

                        params.FilterType = Enum.RaycastFilterType.Exclude
                        params.FilterDescendantsInstances = {
                            getChar(),
                            targetChar,
                        }

                        local res = Workspace:Raycast(camPos, dir, params)

                        if not res or res.Instance == part then
                            return true
                        end
                        if res.Instance.Transparency > 0.9 and not res.Instance.CanCollide then
                            return true
                        end

                        return math.abs((res.Position - camPos).Magnitude - dir.Magnitude) < 1
                    end
                    local function acquireTarget()
                        local pHRP = getHRP(getChar())

                        if not pHRP then
                            silentTarget, silentVector, silentPart = nil, nil, nil
                            ctx.State.aimbotTarget = nil

                            return
                        end

                        local cam = Workspace.CurrentCamera
                        local mousePos = UserInputService:GetMouseLocation()
                        local fov = Options.SilentAimFov.Value
                        local best, bestDist, bestPart, bestVector

                        for _, player in Players:GetPlayers()do
                            local char = player ~= LocalPlayer and player.Character
                            local friendly = ctx.State.isFriendly and ctx.State.isFriendly(player)

                            if char and not friendly and not char:FindFirstChild('Carried') then
                                if not (Toggles.IgnoreBlocking.Value and char:FindFirstChild('Blocking')) then
                                    for _, partName in AIM_HIT_PARTS do
                                        local part = char:FindFirstChild(partName)

                                        if part then
                                            local screen, onScreen = cam:WorldToViewportPoint(part.Position)

                                            if onScreen then
                                                local d = (mousePos - Vector2.new(screen.X, screen.Y)).Magnitude

                                                if d <= fov and (not bestDist or d < bestDist) then
                                                    if not Toggles.SilentAimVisibleCheck.Value or cameraCanSee(part, char) then
                                                        best, bestDist = player, d
                                                        bestPart, bestVector = part, part.Position
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end

                        if Toggles.SilentAimMobs and Toggles.SilentAimMobs.Value then
                            local live = Workspace:FindFirstChild('Live')
                            local myChar = getChar()

                            for _, model in (live and live:GetChildren()) or {}do
                                if model ~= myChar and model:FindFirstChild('MonsterInfo') then
                                    local hum = model:FindFirstChildWhichIsA('Humanoid')
                                    local part = model:FindFirstChild('Head') or (hum and hum.RootPart) or model:FindFirstChild('HumanoidRootPart') or model:FindFirstChild('Torso')

                                    if hum and hum.Health > 0 and part then
                                        local screen, onScreen = cam:WorldToViewportPoint(part.Position)

                                        if onScreen then
                                            local d = (mousePos - Vector2.new(screen.X, screen.Y)).Magnitude

                                            if d <= fov and (not bestDist or d < bestDist) then
                                                if not Toggles.SilentAimVisibleCheck.Value or cameraCanSee(part, model) then
                                                    best, bestDist = model, d
                                                    bestPart, bestVector = part, part.Position
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end

                        silentTarget, silentPart, silentVector = best, bestPart, bestVector
                        ctx.State.aimbotTarget = best
                    end
                    local function isValidToolEquipped()
                        local char = getChar()
                        local tool = char and char:FindFirstChildOfClass('Tool')

                        return tool ~= nil and VALID_TOOLS[tool.Name] == true
                    end
                    local function mousePassthrough()
                        return {
                            Hit = mouse.Hit,
                            Target = mouse.Target,
                            UnitRay = mouse.UnitRay,
                            X = mouse.X,
                            Y = mouse.Y,
                        }
                    end
                    local function spoofMouse()
                        if not isValidToolEquipped() then
                            return mousePassthrough()
                        end
                        if silentTarget and silentVector and silentPart then
                            local cam = Workspace.CurrentCamera
                            local screen = cam:WorldToScreenPoint(silentVector)

                            return {
                                Hit = CFrame.new(silentVector),
                                Target = silentPart,
                                X = screen.X,
                                Y = screen.Y,
                                UnitRay = Ray.new(cam.CFrame.Position, (silentVector - cam.CFrame.Position).Unit),
                            }
                        end

                        return mousePassthrough()
                    end
                    local function legitStep()
                        if not (mousemoverel and silentVector) then
                            return
                        end

                        local picker = Options.SilentAimKey

                        if picker and picker.GetState and not picker:GetState() then
                            return
                        end

                        local cam = Workspace.CurrentCamera
                        local screen, onScreen = cam:WorldToViewportPoint(silentVector)

                        if not onScreen then
                            return
                        end

                        local center = UserInputService:GetMouseLocation()
                        local smooth = math.max(1, (Options.SilentAimSmooth and Options.SilentAimSmooth.Value) or 3)

                        mousemoverel((screen.X - center.X) / smooth, (screen.Y - center.Y) / smooth)
                    end
                    local function startSilentAim()
                        if aimRunning then
                            return
                        end

                        aimRunning = true

                        resolveRemote()
                        ensureDrawings()

                        local aimAccum = 0

                        maid:Connect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                            dt
                        )
                            local at = UserInputService:GetMouseLocation()
                            local radius = Options.SilentAimFov.Value
                            local shown = windowActive and not Toggles.HideFovCircle.Value and not (ctx.State.progActive and ctx.State.progActive())

                            for _, drawing in {fovOutline, fovCircle}do
                                drawing.Position = at
                                drawing.Radius = radius
                                drawing.Visible = shown
                            end

                            fovCircle.Color = (Options.FovCircleColor and Options.FovCircleColor.Value) or FOV_DEFAULT_COLOR
                            fovCircle.Transparency = (Options.FovCircleColor and Options.FovCircleColor.Transparency) and 1 - Options.FovCircleColor.Transparency or 1

                            aimAccum += dt

                            if aimAccum >= 0.03 then
                                aimAccum = 0

                                acquireTarget()
                            end
                            if Options.SilentAimMode and Options.SilentAimMode.Value == 'Legit' then
                                if mouseRemote then
                                    mouseRemote.OnClientInvoke = mousePassthrough
                                end

                                legitStep()
                            elseif mouseRemote then
                                mouseRemote.OnClientInvoke = spoofMouse
                            end
                        end))
                    end
                    local function stopSilentAim()
                        aimRunning = false

                        maid:DoCleaning()

                        silentTarget, silentVector, silentPart = nil, nil, nil
                        ctx.State.aimbotTarget = nil

                        for _, drawing in {fovCircle, fovOutline}do
                            if drawing then
                                drawing.Visible = false
                            end
                        end

                        if mouseRemote then
                            mouseRemote.OnClientInvoke = mousePassthrough
                        end
                    end

                    local SilentAimBox = Combat:AddRightGroupbox('Silent Aim')

                    SilentAimBox:AddToggle('SilentAim', {
                        Text = 'Silent Aim',
                        Default = false,
                        Callback = function(on)
                            if on then
                                startSilentAim()
                            else
                                stopSilentAim()
                            end
                        end,
                    })
                    SilentAimBox:AddDropdown('SilentAimMode', {
                        Text = 'Mode',
                        Tooltip = 'Silent: nothing moves. Legit: moves your camera',
                        Values = {
                            'Silent',
                            'Legit',
                        },
                        Default = 'Silent',
                    })
                    SilentAimBox:AddLabel('Aim Key'):AddKeyPicker('SilentAimKey', {
                        Default = 'MouseButton2',
                        Mode = 'Hold',
                        Text = 'Aim Key',
                        NoUI = false,
                    })
                    SilentAimBox:AddSlider('SilentAimSmooth', {
                        Text = 'Legit Smoothing',
                        Min = 1,
                        Max = 20,
                        Default = 3,
                        Rounding = 0,
                    })
                    SilentAimBox:AddSlider('SilentAimFov', {
                        Text = 'FOV',
                        Min = 0,
                        Max = 200,
                        Default = 100,
                        Rounding = 0,
                    })
                    SilentAimBox:AddToggle('IgnoreBlocking', {
                        Text = 'Ignore Blocking Players',
                        Default = false,
                    })
                    SilentAimBox:AddToggle('SilentAimMobs', {
                        Text = 'Target Mobs',
                        Default = false,
                    })
                    SilentAimBox:AddToggle('HideFovCircle', {
                        Text = 'Hide FOV Circle',
                        Default = false,
                    }):AddColorPicker('FovCircleColor', {
                        Default = FOV_DEFAULT_COLOR,
                        Title = 'FOV Circle',
                        Transparency = 0,
                    })
                    SilentAimBox:AddToggle('SilentAimVisibleCheck', {
                        Text = 'Visible Check',
                        Default = false,
                    })
                end
                do
                    local clickMaid = Maid.new()

                    ctx.Maid:Give(clickMaid)

                    local click = {
                        accum = 0,
                        char = nil,
                        press = nil,
                        release = nil,
                        why = nil,
                        mouse = LocalPlayer:GetMouse(),
                        heldAt = 0,
                        flickered = false,
                        holdStart = nil,
                        sent = 0,
                        released = false,
                        blockedTools = {},
                    }

                    clickMaid:Connect(UserInputService.InputEnded, function(
                        input
                    )
                        if input.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputState == Enum.UserInputState.End then
                            click.heldAt = 0
                            click.released = true
                        end
                    end)

                    local function clickRemotes()
                        local char = getChar()
                        local handler = char and char:FindFirstChild('CharacterHandler')
                        local remotes = handler and handler:FindFirstChild('Remotes')

                        return remotes and remotes:FindFirstChild('LeftClick'), remotes and remotes:FindFirstChild('LeftClickRelease')
                    end

                    local flagged = BASIL_NO_VIRTUALIZE(function(name)
                        return Toggles[name] ~= nil and Toggles[name].Value == true
                    end)
                    local clickBlocked = BASIL_NO_VIRTUALIZE(function(char)
                        if not char then
                            return 'no character'
                        end
                        if ctx.State.skinHandleHeld or ctx.State.bundleHandleHeld then
                            return 'dragging a customization handle'
                        end

                        for _, name in CLICK_BLOCKERS do
                            if char:FindFirstChild(name) then
                                return name
                            end
                        end

                        local observing = char:FindFirstChild('Observing')

                        if observing and observing:IsA('Accessory') then
                            return 'Observing'
                        end
                        if CollectionService:HasTag(char, 'Knocked') then
                            return 'Knocked'
                        end
                        if CollectionService:HasTag(char, 'Unconscious') then
                            return 'Unconscious'
                        end
                        if char:FindFirstChildOfClass('ForceField') then
                            return 'forcefield up'
                        end

                        local held = char:FindFirstChildOfClass('Tool')

                        if held and click.blockedTools[held.Name] then
                            return 'blocked tool in hand: ' .. held.Name
                        end
                        if flagged('AutoclickerSpellCheck') then
                            local tool = char:FindFirstChildOfClass('Tool')

                            if tool and (tool:FindFirstChild('Spell') or tool:FindFirstChild('GodSpell')) then
                                local allowed = Options.AutoclickerAllowedSpells and Options.AutoclickerAllowedSpells.Value

                                if not (allowed and allowed[tool.Name]) then
                                    return 'spell in hand: ' .. tool.Name
                                end
                            end
                        end
                        if Library.MouseIsOverWindow and Library:MouseIsOverWindow(click.mouse) then
                            return 'pointer on the menu'
                        end

                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local gui = pg and pg:FindFirstChild('BackpackGui')

                        if not gui then
                            return nil
                        end

                        local bag = gui:FindFirstChild('BackpackFrame')

                        if bag and bag.Visible and flagged('AutoclickerInventoryCheck') then
                            return 'inventory open'
                        end

                        local hotbar, storage = gui:FindFirstChild('MainFrame'), bag and bag:FindFirstChild('ScrollingFrame')

                        for _, obj in pg:GetGuiObjectsAtPosition(click.mouse.X, click.mouse.Y)do
                            local slot = obj:IsA('TextButton') and obj or obj:FindFirstAncestorWhichIsA('TextButton')

                            if slot and (slot.Parent == hotbar or (storage ~= nil and slot.Parent == storage)) then
                                return 'pointer on a hotbar slot'
                            end
                        end

                        return nil
                    end)
                    local endHold = BASIL_NO_VIRTUALIZE(function(now, how)
                        if click.holdStart then
                            Debug.log('autoclicker', string.format('hold ended after %.1fs (%s), %d click(s) sent', now - click.holdStart, how, click.sent))
                        end

                        click.holdStart = nil
                    end)

                    clickMaid:Connect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                        dt
                    )
                        if not (Toggles.AutoclickerHold and Toggles.AutoclickerHold.Value) then
                            if click.holdStart then
                                endHold(os.clock(), 'M1 Hold turned off')
                            end

                            click.accum, click.why, click.flickered = 0, nil, false

                            return
                        end

                        local now = os.clock()

                        if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
                            click.heldAt = now
                        elseif click.heldAt > 0 and not click.flickered then
                            click.flickered = true

                            Debug.log('autoclicker', 'M1 read as up with no release, still holding')
                        end

                        local typing = UserInputService:GetFocusedTextBox() ~= nil
                        local holding = click.heldAt > 0 and now - click.heldAt <= CLICK_RELEASE_GRACE and not typing

                        if not holding then
                            if click.holdStart then
                                endHold(now, click.released and 'released' or typing and 'typing in a box' or 'button read up for a quarter second')
                            end

                            click.accum, click.why, click.flickered = 0, nil, false

                            return
                        end
                        if not click.holdStart then
                            click.holdStart, click.sent, click.released = now, 0, false
                        end

                        local char = getChar()
                        local why = clickBlocked(char)

                        if not why and (click.char ~= char or not (click.press and click.press.Parent)) then
                            click.char = char
                            click.press, click.release = clickRemotes()

                            if not click.press then
                                why = 'no LeftClick remote'
                            end
                        end

                        local state = why or 'clicking'

                        if state ~= click.why then
                            click.why = state

                            if why then
                                Debug.log('autoclicker', 'holding off: ' .. why)
                            elseif char then
                                local present = {}

                                for _, name in CLICK_TRACE do
                                    if char:FindFirstChild(name) then
                                        table.insert(present, name)
                                    end
                                end

                                Debug.log('autoclicker', 'clicking' .. (#present > 0 and ' with ' .. table.concat(present, ', ') or ''))
                            end
                        end
                        if why then
                            click.accum = 0

                            return
                        end

                        local interval = 1 / math.max(1, (Options.AutoclickerCPS and Options.AutoclickerCPS.Value) or 10)

                        click.accum = math.min(click.accum + dt, interval * 5)

                        while click.accum >= interval do
                            click.accum -= interval

                            pcall(click.press.FireServer, click.press, {
                                math.random(1, 10),
                                math.random(),
                            })

                            click.sent += 1

                            if click.release then
                                pcall(click.release.FireServer, click.release, {
                                    math.random(1, 10),
                                    math.random(),
                                })
                            end

                            local tool = char:FindFirstChildOfClass('Tool')

                            if tool then
                                pcall(tool.Activate, tool)
                            end
                        end
                    end))

                    local ClickBox = Combat:AddRightGroupbox('Autoclicker')

                    ClickBox:AddToggle('AutoclickerHold', {
                        Text = 'M1 Hold',
                        Default = false,
                        Tooltip = 'Works with skills like Shadowrush',
                    })
                    ClickBox:AddSlider('AutoclickerCPS', {
                        Text = 'Clicks per Second',
                        Min = 1,
                        Max = 100,
                        Default = 10,
                        Rounding = 0,
                    })
                    ClickBox:AddToggle('AutoclickerSpellCheck', {
                        Text = 'Spell Check',
                        Default = true,
                        Tooltip = "Stops while you're holding a spell",
                    })
                    ClickBox:AddToggle('AutoclickerInventoryCheck', {
                        Text = 'Inventory Check',
                        Default = true,
                        Tooltip = 'Stops while your inventory is open',
                    })
                    ClickBox:AddDropdown('AutoclickerAllowedSpells', {
                        Text = 'Allowed Spells',
                        Tooltip = 'Still clicked with Spell Check on',
                        Multi = true,
                        Values = {},
                        Default = {},
                        AllowNull = true,
                    })

                    do
                        local saved = (Json.read(Paths.AUTOCLICK_BLOCKED) or {})[tostring(LocalPlayer.UserId)]
                        local wanted = click.blockedTools

                        for _, name in type(saved) == 'table' and saved or {
                            'Mirror',
                        }do
                            wanted[name] = true
                        end

                        local blocked = ClickBox:AddDropdown('AutoclickerBlockedTools', {
                            Text = 'Blocked Tools',
                            Tooltip = 'Never clicks while one is held',
                            Multi = true,
                            Values = {},
                            Default = {},
                            AllowNull = true,
                        })
                        local shown = {}

                        local function refreshTools()
                            local names, picked = {}, {}

                            table.clear(shown)

                            for _, holder in {
                                LocalPlayer:FindFirstChildOfClass('Backpack'),
                                LocalPlayer.Character,
                            }do
                                for _, tool in holder and holder:GetChildren() or {}do
                                    if tool:IsA('Tool') and not shown[tool.Name] then
                                        shown[tool.Name] = true

                                        table.insert(names, tool.Name)

                                        picked[tool.Name] = wanted[tool.Name]
                                    end
                                end
                            end

                            table.sort(names)
                            blocked:SetValues(names)
                            blocked:SetValue(picked)
                        end

                        blocked:OnChanged(function()
                            for name in shown do
                                wanted[name] = blocked.Value[name] == true or nil
                            end

                            local picks = {}

                            for name in wanted do
                                table.insert(picks, name)
                            end

                            table.sort(picks)
                            Json.update(Paths.AUTOCLICK_BLOCKED, function(all)
                                all[tostring(LocalPlayer.UserId)] = picks
                            end)
                        end)

                        local function watchTools()
                            local bag = LocalPlayer:WaitForChild('Backpack', 10)

                            if not bag then
                                return
                            end

                            clickMaid.toolBag = bag.ChildAdded:Connect(function(
                                tool
                            )
                                if not shown[tool.Name] and tool:IsA('Tool') then
                                    refreshTools()
                                end
                            end)

                            refreshTools()
                        end

                        clickMaid:Connect(LocalPlayer.CharacterAdded, function()
                            task.spawn(watchTools)
                        end)
                        clickMaid:Give(task.spawn(watchTools))
                    end
                    do
                        local listed = {}

                        local function isSpell(tool)
                            return tool:IsA('Tool') and (tool:FindFirstChild('Spell') ~= nil or tool:FindFirstChild('GodSpell') ~= nil)
                        end
                        local function refreshSpells()
                            local names = {}

                            table.clear(listed)

                            local function add(name)
                                if not listed[name] then
                                    listed[name] = true

                                    table.insert(names, name)
                                end
                            end

                            for name in ctx.State.spellCost or {}do
                                add(name)
                            end
                            for _, name in CLICK_LISTED_SPELLS do
                                add(name)
                            end
                            for _, holder in {
                                LocalPlayer:FindFirstChildOfClass('Backpack'),
                                LocalPlayer.Character,
                            }do
                                for _, tool in holder and holder:GetChildren() or {}do
                                    if isSpell(tool) then
                                        add(tool.Name)
                                    end
                                end
                            end
                            for name, on in Options.AutoclickerAllowedSpells.Value do
                                if on then
                                    add(name)
                                end
                            end

                            table.sort(names)
                            Options.AutoclickerAllowedSpells:SetValues(names)
                        end
                        local function watchBag()
                            local bag = LocalPlayer:WaitForChild('Backpack', 10)

                            if not bag then
                                return
                            end

                            clickMaid.spellBag = bag.ChildAdded:Connect(function(
                                tool
                            )
                                if not listed[tool.Name] and isSpell(tool) then
                                    refreshSpells()
                                end
                            end)

                            refreshSpells()
                        end

                        clickMaid:Connect(LocalPlayer.CharacterAdded, function()
                            task.spawn(watchBag)
                        end)
                        clickMaid:Give(task.spawn(function()
                            for _ = 1, 60 do
                                if ctx.State.spellCost then
                                    break
                                end

                                task.wait(0.25)
                            end

                            watchBag()
                        end))
                    end
                end

                RuneCast.attach(ctx, Combat)
            end
        end

        function __DARKLUA_BUNDLE_MODULES.u(): typeof(__modImpl())
            local v = __DARKLUA_BUNDLE_MODULES.cache.u

            if not v then
