            end
            local function assetIdOf(object)
                local ok, id = pcall(gethiddenproperty, object, 'AssetId')

                return ok and type(id) == 'string' and id:gsub('%%20', ''):match('%d+') or nil
            end
            local function identifyTrinket(v)
                local C = TRINKET_COLORS

                if v.ClassName == 'UnionOperation' and assetIdOf(v) == '2765613127' then
                    return 'Idol of the Forgotten', C.common.Color, C.common.ZIndex
                elseif v.ClassName == 'UnionOperation' and assetIdOf(v) == '15583017412' then
                    return 'Ornament', C.event.Color, C.event.ZIndex
                elseif v.ClassName == 'UnionOperation' and assetIdOf(v) == '15611175305' then
                    return 'Present', C.event.Color, C.event.ZIndex
                elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://5196782997' then
                    return 'Old Ring', C.common.Color, C.common.ZIndex
                elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://5196776695' then
                    return 'Ring', C.common.Color, C.common.ZIndex
                elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://5204003946' then
                    return 'Goblet', C.common.Color, C.common.ZIndex
                elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://5196577540' then
                    return 'Old Amulet', C.common.Color, C.common.ZIndex
                elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://5196551436' then
                    return 'Amulet', C.common.Color, C.common.ZIndex
                elseif v.ClassName == 'Part' and v:FindFirstChildWhichIsA('SpecialMesh') and v:FindFirstChild('OrbParticle') then
                    return '???', C.rare.Color, C.rare.ZIndex
                elseif v.ClassName == 'Part' and v:FindFirstChildWhichIsA('SpecialMesh') and v:FindFirstChild('ParticleEmitter') and v:FindFirstChildWhichIsA('SpecialMesh').MeshId == '' and v:FindFirstChildWhichIsA('SpecialMesh').MeshType == Enum.MeshType.Sphere then
                    return 'Opal', C.common.Color, C.common.ZIndex
                elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://5204453430' then
                    return 'Scroll', C.rare.Color, C.rare.ZIndex
                elseif v:FindFirstChild('Mesh') and v.Mesh.MeshId == 'rbxassetid://%202877143560%20' and v:FindFirstChild('ParticleEmitter') and string.match(tostring(v.ParticleEmitter.Color), '0 1 1 1 0 1 1 1 1 0') and v.ClassName == 'Part' and tostring(v.Color) == '0.643137, 0.733333, 0.745098' then
                    return 'Diamond', C.rare.Color, C.rare.ZIndex
                elseif v:FindFirstChild('Mesh') and v.Mesh.MeshId == 'rbxassetid://%202877143560%20' and v:FindFirstChild('ParticleEmitter') and string.match(tostring(v.ParticleEmitter.Color), '0 1 1 1 0 1 1 1 1 0') and v.ClassName == 'Part' and v.Color.G > v.Color.R and v.Color.G > v.Color.B then
                    return 'Emerald', C.rare.Color, C.rare.ZIndex
                elseif v:FindFirstChild('Mesh') and v.Mesh.MeshId == 'rbxassetid://%202877143560%20' and v:FindFirstChild('ParticleEmitter') and string.match(tostring(v.ParticleEmitter.Color), '0 1 1 1 0 1 1 1 1 0') and v.ClassName == 'Part' and v.Color.R > v.Color.G and v.Color.R > v.Color.B then
                    return 'Ruby', C.rare.Color, C.rare.ZIndex
                elseif v:FindFirstChild('Mesh') and v.Mesh.MeshId == 'rbxassetid://%202877143560%20' and v:FindFirstChild('ParticleEmitter') and string.match(tostring(v.ParticleEmitter.Color), '0 1 1 1 0 1 1 1 1 0') and v.ClassName == 'Part' and v.Color.B > v.Color.G and v.Color.B > v.Color.R then
                    return 'Sapphire', C.rare.Color, C.rare.ZIndex
                elseif v.ClassName == 'Part' and v:FindFirstChild('ParticleEmitter') and not string.match(tostring(v.ParticleEmitter.Color), '0 1 1 1 0 1 1 1 1 0') then
                    return 'Rift Gem', C.mythic.Color, C.mythic.ZIndex
                elseif v.ClassName == 'MeshPart' and v:FindFirstChild('ParticleEmitter') and string.match(tostring(v.ParticleEmitter.Color), '0 0.635294 0 1 0 1 0.635294 0 1 0') then
                    return 'Rift Gem', C.mythic.Color, C.mythic.ZIndex
                elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://5197099782' and v:FindFirstChild('MeshPart') and v.MeshPart.MeshId == 'rbxassetid://5197111525' then
                    return 'Amulet of the White King', C.artifact.Color, C.artifact.ZIndex
                elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://5196963069' and v:FindFirstChild('MeshPart') and v.MeshPart.MeshId == 'rbxassetid://5196975152' then
                    return 'Lannis Amulet', C.artifact.Color, C.artifact.ZIndex
                elseif v:FindFirstChild('Attachment') and v.Attachment:FindFirstChildOfClass('ParticleEmitter') and v.Attachment:FindFirstChildOfClass('ParticleEmitter').Rate == 3 then
                    return 'Mysterious Artifact', C.mythic.Color, C.mythic.ZIndex
                elseif v:IsA('MeshPart') and v.MeshId == 'rbxassetid://4103271893' then
                    return 'Candy', C.event.Color, C.event.ZIndex
                elseif v.ClassName == 'UnionOperation' then
                    if inTable(TRINKET_MASKS, assetIdOf(v)) then
                        return 'Scary Mask', C.event.Color, C.event.ZIndex
                    elseif assetIdOf(v) == '4117970107' then
                        return 'Pumpkin Centerpiece', C.event.Color, C.event.ZIndex
                    elseif assetIdOf(v) == '17590006505' then
                        return 'Idol of War', C.event.Color, C.event.ZIndex
                    end
                elseif v:FindFirstChild('Attachment') and v.Attachment:FindFirstChildOfClass('ParticleEmitter') and v.Attachment:FindFirstChildOfClass('ParticleEmitter').Rate == 5 and tostring(v.Attachment:FindFirstChildOfClass('ParticleEmitter').Color):split(' ')[3] ~= '0.8' then
                    local name = (game.PlaceId == 3541987450) and 'Phoenix Flower' or 'Azael Horn'

                    return name, C.mythic.Color, C.mythic.ZIndex
                elseif v:FindFirstChild('Attachment') and v.Attachment:FindFirstChildOfClass('ParticleEmitter') and v.Attachment:FindFirstChildOfClass('ParticleEmitter').Rate == 5 and tostring(v.Attachment:FindFirstChildOfClass('ParticleEmitter').Color):split(' ')[3] == '0.8' then
                    return 'Phoenix Down', C.artifact.Color, C.artifact.ZIndex
                elseif v.ClassName == 'MeshPart' and v.BrickColor.Name == 'Black' then
                    return 'Night Stone', C.artifact.Color, C.artifact.ZIndex
                elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://%202520762076%20' then
                    return 'Howler Friend', C.artifact.Color, C.artifact.ZIndex
                elseif v.ClassName == 'Part' and v:FindFirstChild('OrbParticle') and string.match(tostring(v.OrbParticle.Color),
[[0 0.105882 0.596078 0.596078 0 1 0.105882 0.596078 0.596078 0 ]]) then
                    return 'Ice Essence', C.rare.Color, C.rare.ZIndex
                end
                if game.PlaceId == 3541987450 then
                    if v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://4027112893' and v:FindFirstChild('Part') then
                        return 'Bound Book', C.rare.Color, C.rare.ZIndex
                    elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://%202877143560%20' and tostring(v.Color) == '0.643137, 0.733333, 0.745098' then
                        return 'Diamond', C.rare.Color, C.rare.ZIndex
                    elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://%202877143560%20' and v.Color.B < v.Color.G and v.Color.B > v.Color.R then
                        return 'Emerald', C.rare.Color, C.rare.ZIndex
                    elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://%202877143560%20' and v.Color.R > v.Color.G and v.Color.R > v.Color.B then
                        return 'Ruby', C.rare.Color, C.rare.ZIndex
                    elseif v.ClassName == 'MeshPart' and v.MeshId == 'rbxassetid://%202877143560%20' and v.Color.B > v.Color.R and v.Color.B > v.Color.G then
                        return 'Sapphire', C.rare.Color, C.rare.ZIndex
                    end
                end

                return 'Opal', C.none.Color, C.none.ZIndex
            end
            local function identifyIngredient(object)
                return INGREDIENT_IDENTIFIERS[assetIdOf(object)]
            end

            local INGREDIENT_OTHER = 'Other'
            local INGREDIENT_NAMES = {}

            do
                local seen = {}

                for _, name in INGREDIENT_IDENTIFIERS do
                    if not seen[name] then
                        seen[name] = true

                        table.insert(INGREDIENT_NAMES, name)
                    end
                end

                table.sort(INGREDIENT_NAMES)
                table.insert(INGREDIENT_NAMES, INGREDIENT_OTHER)
            end

            local function isIngredientPart(object)
                return object:IsA('BasePart') and object:FindFirstChild('ClickDetector') ~= nil and object:FindFirstChild('Blacklist') ~= nil
            end
            local function trinketArea(object)
                local markers = Workspace:FindFirstChild('AreaMarkers')

                if not markers then
                    return 'None'
                end

                local best, bestSq = 'None', math.huge
                local pos = object.Position

                for _, marker in markers:GetChildren()do
                    local diff = pos - marker.Position
                    local sq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z

                    if sq < bestSq then
                        best, bestSq = marker.Name, sq
                    end
                end

                return best
            end

            return function(ctx)
                local Library = ctx.Library
                local Toggles, Options = Library.Toggles, Library.Options
                local Visuals = ctx.Tabs.Visuals

                ctx.State = ctx.State or {}

                local windowActive = true

                ctx.Maid:Connect(UserInputService.WindowFocused, function()
                    windowActive = true
                end)
                ctx.Maid:Connect(UserInputService.WindowFocusReleased, function()
                    windowActive = false
                end)

                do
                    local maid = Maid.new()

                    ctx.Maid:Give(maid)

                    local espMaid = Maid.new()
                    local chamsMaid = Maid.new()

                    maid:Give(espMaid)
                    maid:Give(chamsMaid)

                    local objects = {}
                    local chamsFolder

                    local function getChamsFolder()
                        if not chamsFolder then
                            chamsFolder = Gui.folder()
                        end

                        return chamsFolder
                    end
                    local function isFriendly(player)
                        return ctx.State.isFriendly ~= nil and ctx.State.isFriendly(player) or false
                    end
                    local function isEmpty(value)
                        return value == nil or value == ''
                    end
                    local function realName(player)
                        local first = player:GetAttribute('FirstName')

                        if not isEmpty(first) then
                            local last = player:GetAttribute('LastName')
                            local uber = player:GetAttribute('UberTitle')
                            local full = tostring(first)

                            if not isEmpty(last) then
                                full = full .. ' ' .. tostring(last)
                            end
                            if not isEmpty(uber) then
                                return full .. ', ' .. tostring(uber)
                            end

                            return full
                        end

                        local leaderstats = player:FindFirstChild('leaderstats')
                        local firstStat = leaderstats and leaderstats:FindFirstChild('FirstName')

                        if not firstStat then
                            return 'nil'
                        end

                        local last = leaderstats:FindFirstChild('LastName')
                        local uber = leaderstats:FindFirstChild('UberTitle')
                        local full = tostring(firstStat.Value)

                        if last and last.Value ~= '' then
                            full = full .. ' ' .. tostring(last.Value)
                        end
                        if uber and uber.Value ~= '' then
                            return full .. ', ' .. tostring(uber.Value)
                        end

                        return full
                    end
                    local function getName(player)
                        local real = realName(player)

                        return (ctx.State.maskRogue and ctx.State.maskRogue(player, real)) or real
                    end
                    local function maskUser(player)
                        return (ctx.State.maskUser and ctx.State.maskUser(player)) or player.Name
                    end

                    local envScratch = {
                        Toggles = Toggles,
                        Options = Options,
                        isFriendly = isFriendly,
                        getName = getName,
                        maskUser = maskUser,
                    }

                    local function buildEnv()
                        envScratch.camera = Workspace.CurrentCamera
                        envScratch.windowActive = windowActive
                        envScratch.elements = Options.PlayerESPInfo.Value or {}
                        envScratch.mousePos = UserInputService:GetMouseLocation()
                        envScratch.aimbotTarget = ctx.State.aimbotTarget
                        envScratch.aimbotColor = Options.PlayerAimbotChamsColor and Options.PlayerAimbotChamsColor.Value
                        envScratch.chamsFolder = getChamsFolder()

                        return envScratch
                    end
                    local function anyChamsEnabled()
                        return Toggles.PlayerChams.Value and (Toggles.PlayerFriendlyChams.Value or Toggles.PlayerLowHealth.Value or Toggles.PlayerAimbotChams.Value or Toggles.PlayerRacialChams.Value)
                    end
                    local function ensureObjects()
                        for _, player in Players:GetPlayers()do
                            if player ~= LocalPlayer and not objects[player] then
                                objects[player] = EntityESP.new(player)
                            end
                        end
                    end
                    local function destructAll()
                        for _, esp in objects do
                            esp:destroy()
                        end

                        table.clear(objects)
                    end
                    local function startEspLoop()
                        espMaid.loop = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                        )
                            local env = buildEnv()

                            for _, esp in objects do
                                esp:update(env)
                            end
                        end))
                    end

                    local aimbotMobHL

                    local function updateAimbotMob()
                        local target = ctx.State.aimbotTarget
                        local on = Toggles.PlayerChams.Value and Toggles.PlayerAimbotChams.Value and windowActive and typeof(target) == 'Instance' and target:IsA('Model')

                        if not on then
                            if aimbotMobHL then
                                aimbotMobHL.Adornee = nil
                                aimbotMobHL.Enabled = false
                            end

                            return
                        end
                        if not aimbotMobHL then
                            aimbotMobHL = Make('Highlight', {
                                Parent = getChamsFolder(),
                            })
                        end

                        local color = (Options.PlayerAimbotChamsColor and Options.PlayerAimbotChamsColor.Value) or Color3.fromRGB(255, 255, 0)
                        local pulse = Toggles.PlayerChamsPulse and Toggles.PlayerChamsPulse.Value
                        local wave = pulse and math.sin(os.clock() * 5) or 0

                        aimbotMobHL.FillColor = color
                        aimbotMobHL.OutlineColor = color
                        aimbotMobHL.FillTransparency = pulse and (wave - 0.25) or 0.65
                        aimbotMobHL.OutlineTransparency = pulse and (wave / 1.5) or 0.25
                        aimbotMobHL.DepthMode = (Toggles.PlayerChamsOccluded and Toggles.PlayerChamsOccluded.Value) and Enum.HighlightDepthMode.Occluded or Enum.HighlightDepthMode.AlwaysOnTop
                        aimbotMobHL.Adornee = target
                        aimbotMobHL.Enabled = true
                    end

                    local frame = 0

                    local function startChamsLoop()
                        chamsMaid.loop = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                        )
                            frame += 1

                            if frame % 2 ~= 0 then
                                return
                            end

                            local env = buildEnv()

                            for _, esp in objects do
                                esp:updateChams(env)
                            end

                            updateAimbotMob()
                        end))
                    end
                    local function enableEsp()
                        ensureObjects()
                        startEspLoop()
                    end
                    local function disableEsp()
                        espMaid:DoCleaning()

                        for _, esp in objects do
                            esp:hideAll()
                        end

                        if not anyChamsEnabled() then
                            destructAll()
                        end
                    end
                    local function updateChams()
                        if anyChamsEnabled() then
                            ensureObjects()
                            startChamsLoop()
                        else
                            chamsMaid:DoCleaning()

                            for _, esp in objects do
                                esp:hideChams()
                            end

                            if aimbotMobHL then
                                aimbotMobHL.Adornee = nil
                                aimbotMobHL.Enabled = false
                            end
                            if not Toggles.PlayerESP.Value then
                                destructAll()
                            end
                        end
                    end

                    maid:Connect(Players.PlayerAdded, function(player)
                        if player ~= LocalPlayer and (Toggles.PlayerESP.Value or anyChamsEnabled()) then
                            objects[player] = objects[player] or EntityESP.new(player)
                        end
                    end)
                    maid:Connect(Players.PlayerRemoving, function(player)
                        if objects[player] then
                            objects[player]:destroy()

                            objects[player] = nil
                        end
                    end)
                    ctx.Maid:Give(function()
                        destructAll()

                        if chamsFolder then
                            chamsFolder:Destroy()
                        end
                    end)

                    local PlayerBox = Visuals:AddLeftGroupbox('Player ESP')
                    local ChamsBox = Visuals:AddRightGroupbox('Chams')

                    PlayerBox:AddToggle('PlayerESP', {
                        Text = 'Player ESP',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enableEsp()
                            else
                                disableEsp()
                            end
                        end,
                    }):AddKeyPicker('PlayerESPKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'Player ESP Toggle',
                        SyncToggleState = true,
                        Callback = function(state)
                            if Toggles.PlayerESP.Value ~= state then
                                Toggles.PlayerESP:SetValue(state)
                            end
                        end,
                    })
                    PlayerBox:AddToggle('PlayerName', {
                        Text = 'Name',
                        Default = true,
                    })
                    PlayerBox:AddToggle('PlayerBox', {
                        Text = 'Box',
                        Default = true,
                    })
                    PlayerBox:AddToggle('PlayerHealth', {
                        Text = 'Health',
                        Default = true,
                    })
                    PlayerBox:AddDropdown('PlayerESPInfo', {
                        Text = 'Info',
                        Multi = true,
                        Values = {
                            'Mana',
                            'Mana Text',
                            'Temperature',
                            'Tags',
                            'Intent',
                            'Racial',
                            'Observe Block',
                        },
                        Default = {
                            'Intent',
                            'Tags',
                            'Mana',
                        },
                    })
                    PlayerBox:AddToggle('PlayerHoverDetails', {
                        Text = 'Fade Away',
                        Default = false,
                    })
                    PlayerBox:AddSlider('PlayerRange', {
                        Text = 'Range',
                        Min = 0,
                        Max = 9000,
                        Default = 1000,
                        Rounding = 0,
                    })

                    do
                        local hvMaid = Maid.new()

                        ctx.Maid:Give(hvMaid)

                        local function applyHealth(char, distance)
                            if not char or char == LocalPlayer.Character then
                                return
                            end

                            local hum = char:FindFirstChildWhichIsA('Humanoid')

                            if not hum then
                                return
                            end

                            hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.DisplayWhenDamaged

                            if char:FindFirstChild('MonsterInfo') then
                                hum.NameDisplayDistance = 0
                            end

                            hum.HealthDisplayDistance = distance
                            hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Subject
                        end
                        local function setAll(distance)
                            local live = Workspace:FindFirstChild('Live')

                            if not live then
                                return
                            end

                            for _, v in live:GetChildren()do
                                applyHealth(v, distance)
                            end
                        end
                        local function reset()
                            local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                            if LocalPlayer.Character and bp and bp:FindFirstChild('HealerVision') then
                                return
                            end

                            setAll(0)
                        end

                        PlayerBox:AddDivider()
                        PlayerBox:AddToggle('PlayerHealthview', {
                            Text = 'Player Healthview',
                            Tooltip = 'Health bars on hurt players nearby',
                            Default = false,
                            Callback = function(on)
                                if on then
                                    setAll(Options.PlayerHealthviewRange.Value)

                                    local live = Workspace:FindFirstChild('Live')

                                    if live then
                                        hvMaid.added = live.ChildAdded:Connect(function(
                                            ch
                                        )
                                            task.spawn(function()
                                                local hum = ch:WaitForChild('Humanoid', 3)

                                                if hum and Toggles.PlayerHealthview.Value then
                                                    applyHealth(ch, Options.PlayerHealthviewRange.Value)
                                                end
                                            end)
                                        end)
                                    end
                                else
                                    hvMaid:DoCleaning()
                                    reset()
                                end
                            end,
                        })
                        PlayerBox:AddSlider('PlayerHealthviewRange', {
                            Text = 'Healthview Range',
                            Min = 0,
                            Max = 1000,
                            Default = 80,
                            Rounding = 0,
                            Suffix = ' studs',
                            Callback = function(value)
                                if Toggles.PlayerHealthview and Toggles.PlayerHealthview.Value then
                                    setAll(value)
                                end
                            end,
                        })
                        ctx.Maid:Give(function()
                            if Toggles.PlayerHealthview and Toggles.PlayerHealthview.Value then
                                reset()
                            end
                        end)
                    end

                    ChamsBox:AddToggle('PlayerChams', {
                        Text = 'Player Highlights',
                        Tooltip = 'Chams',
                        Default = false,
                        Callback = updateChams,
                    })
                    ChamsBox:AddDivider()
                    ChamsBox:AddToggle('PlayerFriendlyChams', {
                        Text = 'Friendly Chams',
                        Default = false,
                        Callback = updateChams,
                    })
                    ChamsBox:AddToggle('PlayerLowHealth', {
                        Text = 'Low Health Chams',
                        Default = false,
                        Callback = updateChams,
                    })
                    ChamsBox:AddToggle('PlayerAimbotChams', {
                        Text = 'Player Aimbot Chams',
                        Default = false,
                        Callback = updateChams,
                    }):AddColorPicker('PlayerAimbotChamsColor', {
                        Default = Color3.fromRGB(255, 255, 0),
                    })
                    ChamsBox:AddToggle('PlayerRacialChams', {
                        Text = 'Racial Chams',
                        Default = false,
                        Callback = updateChams,
                    })
                    ChamsBox:AddToggle('PlayerChamsPulse', {
                        Text = 'Chams Pulse',
                        Default = false,
                    })
                    ChamsBox:AddToggle('PlayerChamsOccluded', {
                        Text = 'Chams Occluded',
                        Default = false,
                    })

                    do
                        local verdienMaid = Maid.new()

                        maid:Give(verdienMaid)

                        local highlights = {}

                        local function dropHighlight(player)
                            local hl = highlights[player]

                            if hl then
                                hl:Destroy()

                                highlights[player] = nil
                            end
                        end

                        local shown = false

                        local function hideHighlights()
                            shown = false

                            for _, hl in highlights do
                                if hl.Enabled then
                                    hl.Enabled = false
                                end
                            end
                        end

                        local verdienLoop = BASIL_NO_VIRTUALIZE(function()
                            local char = LocalPlayer.Character
                            local root = char and char:FindFirstChild('HumanoidRootPart')
                            local tool = char and char:FindFirstChildOfClass('Tool')
                            local name = tool and tool.Name
                            local verdien = name == 'Verdien' or name == 'New Verdien'
                            local dominus = name == 'Dominus' and not char:FindFirstChild('DomCD') and not char:FindFirstChildOfClass('ForceField')

                            if not (windowActive and root and (verdien or dominus)) then
                                if shown then
                                    hideHighlights()
                                end

                                return
                            end

                            local myPos = root.Position
                            local pick, pickDistance

                            if dominus then
                                local live = Workspace:FindFirstChild('Live')

                                for _, player in Players:GetPlayers()do
                                    local other = player ~= LocalPlayer and player.Character
                                    local otherRoot = other and other.Parent == live and other:FindFirstChild('HumanoidRootPart')

                                    if otherRoot and not CollectionService:HasTag(other, 'Unconscious') and not other:FindFirstChild('NoControl') and not other:FindFirstChildOfClass('ForceField') then
                                        local d = (otherRoot.Position - myPos).Magnitude

                                        if d < 20 and (not pickDistance or d < pickDistance) then
                                            pick, pickDistance = player, d
                                        end
                                    end
                                end
                            end

                            shown = true

                            local pulse = Toggles.PlayerChamsPulse and Toggles.PlayerChamsPulse.Value
                            local wave = pulse and math.sin(os.clock() * 5) or 0
                            local fill = pulse and (wave - 0.25) or 0.65
                            local outline = pulse and (wave / 1.5) or 0.25
                            local depth = (Toggles.PlayerChamsOccluded and Toggles.PlayerChamsOccluded.Value) and Enum.HighlightDepthMode.Occluded or Enum.HighlightDepthMode.AlwaysOnTop

                            for _, player in Players:GetPlayers()do
                                local other = player ~= LocalPlayer and player.Character
                                local hl = highlights[player]
                                local lands

                                if dominus then
                                    lands = player == pick
                                else
                                    local target = other and (other:FindFirstChild('HumanoidRootPart') or other:FindFirstChild('UpperTorso') or other:FindFirstChild('Torso'))
                                    local distance = target and (target.Position - myPos).Magnitude

                                    lands = distance and distance <= 25 and not other:FindFirstChild('VerdienCooldown') and not other:FindFirstChild('Blocking')
                                end
                                if lands then
                                    if not hl then
                                        hl = Make('Highlight', {
                                            FillColor = Color3.fromRGB(170, 0, 255),
                                            OutlineColor = Color3.fromRGB(170, 0, 255),
                                            Parent = getChamsFolder(),
                                        })
                                        highlights[player] = hl
                                    end
                                    if hl.FillTransparency ~= fill then
                                        hl.FillTransparency = fill
                                    end
                                    if hl.OutlineTransparency ~= outline then
                                        hl.OutlineTransparency = outline
                                    end
                                    if hl.DepthMode ~= depth then
                                        hl.DepthMode = depth
                                    end
                                    if hl.Adornee ~= other then
                                        hl.Adornee = other
                                    end
                                    if not hl.Enabled then
                                        hl.Enabled = true
                                    end
                                elseif hl and hl.Enabled then
                                    hl.Enabled = false
                                end
                            end
                        end)

                        ChamsBox:AddDivider()
                        ChamsBox:AddToggle('VerdienESP', {
                            Text = 'Verdien/Dominus ESP',
                            Tooltip = 'Purple when your Verdien or Dominus can land',
                            Default = false,
                            Callback = function(on)
                                verdienMaid:DoCleaning()

                                for player in highlights do
                                    dropHighlight(player)
                                end

                                if on then
                                    verdienMaid:Connect(RunService.RenderStepped, verdienLoop)
                                    verdienMaid:Connect(Players.PlayerRemoving, dropHighlight)
                                end
                            end,
                        })
                    end
                end
                do
                    local function createWorldEsp(cfg)
                        local objects = {}
                        local maid = Maid.new()

                        ctx.Maid:Give(maid)

                        local function add(object)
                            if objects[object] or not cfg.match(object) then
                                return
                            end

                            local info = cfg.build(object)

                            if not info then
                                return
                            end

                            objects[object] = {
                                esp = ObjectESP.new(object, info.color, info.zindex),
                                name = info.name,
                                info = info,
                            }
                        end
                        local function remove(object)
                            local entry = objects[object]

                            if entry then
                                entry.esp:destroy()

                                objects[object] = nil
                            end
                        end
                        local function destroyAll()
                            for _, entry in objects do
                                entry.esp:destroy()
                            end

                            table.clear(objects)
                        end

                        ctx.Maid:Give(destroyAll)

                        local frame = 0
                        local loop = BASIL_NO_VIRTUALIZE(function()
                            frame += 1

                            if cfg.everyOther and frame % 2 ~= 0 then
                                return
                            end

                            local camera = Workspace.CurrentCamera
                            local camPos = camera.CFrame.Position
                            local env = cfg.begin and cfg.begin() or nil

                            for object, entry in objects do
                                if object.Parent == nil then
                                    remove(object)
                                elseif not windowActive then
                                    entry.esp:hide()
                                else
                                    local pos = cfg.getPosition(object)

                                    if not pos then
                                        entry.esp:hide()
                                    else
                                        local distance = (camPos - pos).Magnitude
                                        local show, label = cfg.resolve(object, entry, distance, env)

                                        if show then
                                            entry.esp:render(camera, pos, label)
                                        else
                                            entry.esp:hide()
                                        end
                                    end
                                end
                            end
                        end)

                        local function enable()
                            local folder = cfg.folder()

                            if folder then
                                for _, object in folder:GetChildren()do
                                    add(object)
                                end

                                maid:Connect(folder.ChildAdded, function(
                                    object
                                )
                                    add(object)

                                    if not objects[object] then
                                        task.delay(0.2, function()
                                            if object.Parent then
                                                add(object)
                                            end
                                        end)
                                    end
                                end)
                                maid:Connect(folder.ChildRemoved, remove)
                            end

                            maid:Connect(RunService.RenderStepped, loop)
                        end
                        local function disable()
                            maid:DoCleaning()
                            destroyAll()
                        end

                        return enable, disable
                    end

                    local trinketEnv = {
                        types = nil,
                        ignoreRange = nil,
                        range = 0,
                        showArea = false,
                    }
                    local enableTrinket, disableTrinket = createWorldEsp({
                        folder = function()
                            return Workspace
                        end,
                        match = function(object)
                            return object.Name == 'Part' and object:FindFirstChild('ID') ~= nil
                        end,
                        build = function(object)
                            local name, color, zindex = identifyTrinket(object)

                            return {
                                color = color,
                                zindex = zindex,
                                name = name,
                                rarity = RARITY_BY_ZINDEX[zindex],
                                area = trinketArea(object),
                            }
                        end,
                        getPosition = BASIL_NO_VIRTUALIZE(function(object)
                            return object:IsA('BasePart') and object.Position or nil
                        end),
                        begin = BASIL_NO_VIRTUALIZE(function()
                            trinketEnv.types = Options.TrinketTypes.Value
                            trinketEnv.ignoreRange = Options.TrinketIgnoreRangeTypes.Value
                            trinketEnv.range = Options.TrinketRange.Value
                            trinketEnv.showArea = Toggles.TrinketShowArea.Value

                            return trinketEnv
                        end),
                        resolve = BASIL_NO_VIRTUALIZE(function(
                            _,
                            entry,
                            distance,
                            env
                        )
                            local rarity = entry.info.rarity

                            if not (rarity and env.types[rarity]) then
                                return false
                            end
                            if env.ignoreRange[rarity] ~= true and distance >= env.range then
                                return false
                            end

                            local areaText = (entry.info.area ~= 'None' and env.showArea) and (' (' .. entry.info.area .. ')') or ''

                            return true, entry.name .. '\n[' .. math.floor(distance) .. ']' .. areaText
                        end),
                    })
                    local enableFallion, disableFallion = createWorldEsp({
                        folder = function()
                            return Workspace:FindFirstChild('NPCs')
                        end,
                        match = function(object)
                            return object.Name == 'Fallion'
                        end,
                        build = function()
                            return {
                                color = Color3.fromRGB(255, 115, 229),
                                zindex = -10,
                                name = '[Fallion]',
                            }
                        end,
                        getPosition = BASIL_NO_VIRTUALIZE(function(object)
                            local hrp = object:FindFirstChild('HumanoidRootPart')

                            return hrp and hrp.Position or nil
                        end),
                        resolve = BASIL_NO_VIRTUALIZE(function(
                            _,
                            entry,
                            distance
                        )
                            return true, entry.name .. '\n[' .. math.floor(distance) .. ']'
                        end),
                        everyOther = true,
                    })
                    local enableNpc, disableNpc = createWorldEsp({
                        folder = function()
                            return Workspace:FindFirstChild('NPCs')
                        end,
                        match = function(object)
                            return (object:FindFirstChildOfClass('Pants') and object:FindFirstChild('Humanoid') and object:FindFirstChild('Torso') ~= nil) or (object.Name == 'The Eagle' and object:FindFirstChild('Humanoid') and object:FindFirstChild('HumanoidRootPart') ~= nil)
                        end,
                        build = function(object)
                            local color

                            if object.Name == 'The Eagle' and object:FindFirstChild('HumanoidRootPart') then
                                color = object.HumanoidRootPart.Color
                            else
                                color = object.Torso.Color
                            end

                            return {
                                color = color,
                                zindex = -10,
                                name = '[' .. object.Name .. ']',
                            }
                        end,
                        getPosition = BASIL_NO_VIRTUALIZE(function(object)
                            local hrp = object:FindFirstChild('HumanoidRootPart')

                            return hrp and hrp.Position or nil
                        end),
                        resolve = BASIL_NO_VIRTUALIZE(function(
                            _,
                            entry,
                            distance
                        )
                            return true, entry.name .. '\n[' .. math.floor(distance) .. ']'
                        end),
                        everyOther = true,
                    })
                    local enableSpookyHat, disableSpookyHat = createWorldEsp({
                        folder = function()
                            return Workspace:FindFirstChild('Thrown')
                        end,
                        match = function(object)
                            return object.Name == 'SpookyHat'
                        end,
                        build = function()
                            return {
                                color = Color3.fromRGB(255, 140, 0),
                                zindex = -10,
                                name = '[Spooky Hat]',
                            }
                        end,
                        getPosition = BASIL_NO_VIRTUALIZE(function(object)
                            if object:IsA('BasePart') then
                                return object.Position
                            end
                            if object:IsA('Model') then
                                return object:GetPivot().Position
                            end

                            local part = object:FindFirstChildWhichIsA('BasePart', true)

                            return part and part.Position or nil
                        end),
                        resolve = BASIL_NO_VIRTUALIZE(function(
                            _,
                            entry,
                            distance
                        )
                            return true, entry.name .. '\n[' .. math.floor(distance) .. ']'
                        end),
                        everyOther = true,
                    })
                    local ingredientFolder

                    local function findIngredientFolder()
                        if ingredientFolder and ingredientFolder.Parent then
                            return ingredientFolder
                        end

                        ingredientFolder = nil

                        for _, instance in Workspace:GetChildren()do
                            if instance.ClassName == 'Folder' then
                                for _, ingredient in instance:GetChildren()do
                                    if ingredient.ClassName == 'UnionOperation' and ingredient:FindFirstChild('ClickDetector') and ingredient:FindFirstChild('Blacklist') then
                                        ingredientFolder = instance

                                        return instance
                                    end
                                end
                            end
                        end

                        return nil
                    end

                    ctx.State.identifyTrinket = identifyTrinket
                    ctx.State.trinketArea = trinketArea
                    ctx.State.findIngredientFolder = findIngredientFolder
                    ctx.State.identifyIngredient = identifyIngredient

                    local ingredientEnv = {
                        range = 0,
                        picked = nil,
                    }
                    local enableIngredient, disableIngredient = createWorldEsp({
                        folder = findIngredientFolder,
                        match = isIngredientPart,
                        everyOther = true,
                        build = function(object)
                            local known = identifyIngredient(object)

                            return {
                                color = object.Color,
                                zindex = -10,
                                name = known or object.Name or 'Unknown',
                                pick = known or INGREDIENT_OTHER,
                            }
                        end,
                        getPosition = BASIL_NO_VIRTUALIZE(function(object)
                            return object.Position
                        end),
                        begin = BASIL_NO_VIRTUALIZE(function()
                            ingredientEnv.range = Options.IngredientRange.Value
                            ingredientEnv.picked = Options.IngredientTypes and Options.IngredientTypes.Value or nil

                            return ingredientEnv
                        end),
                        resolve = BASIL_NO_VIRTUALIZE(function(
                            object,
                            entry,
                            distance,
                            env
                        )
                            if env.picked and not env.picked[entry.info.pick] then
                                return false
                            end
                            if distance >= env.range or object.Transparency == 1 then
                                return false
                            end

                            return true, entry.name .. '\n[' .. math.floor(distance) .. ']'
                        end),
                    })
                    local enableOre, disableOre = createWorldEsp({
                        folder = function()
                            return Workspace:FindFirstChild('Ores')
                        end,
                        match = function(object)
                            return object:IsA('BasePart')
                        end,
                        build = function(object)
                            return {
                                color = object.Color,
                                zindex = -10,
                                name = object.Name,
                            }
                        end,
                        getPosition = BASIL_NO_VIRTUALIZE(function(object)
                            return object.Position
                        end),
                        resolve = BASIL_NO_VIRTUALIZE(function(
                            object,
                            entry,
                            distance
                        )
                            if object.Transparency == 1 or distance >= Options.ore_range.Value then
                                return false
                            end

                            entry.toggleKey = entry.toggleKey or (entry.name:lower() .. '_esp')

                            local sub = Toggles[entry.toggleKey]

                            if not (sub and sub.Value) then
                                return false
                            end

                            return true, entry.name .. '\n[' .. math.floor(distance) .. ']'
                        end),
                    })
                    local shriekerObjects = {}
                    local shriekerFolder
                    local shriekerMaid = Maid.new()

                    ctx.Maid:Give(shriekerMaid)

                    local function getShriekerFolder()
                        if not shriekerFolder then
                            shriekerFolder = Gui.folder()
                        end

                        return shriekerFolder
                    end
                    local function shriekerColor(shrieker)
                        local info = shrieker:FindFirstChild('MonsterInfo')
                        local master = info and info:FindFirstChild('Master')

                        if master then
                            if LocalPlayer.Character and master.Value == LocalPlayer.Character then
                                return Color3.fromRGB(0, 255, 255)
                            end

                            return Color3.fromRGB(255, 0, 80)
                        end

                        return Color3.fromRGB(255, 255, 255)
                    end
                    local function isShrieker(model)
                        return model:IsA('Model') and string.find(model.Name, 'Shrieker') ~= nil and model:FindFirstChild('MonsterInfo') ~= nil
                    end
                    local function addShrieker(model)
                        if shriekerObjects[model] or not isShrieker(model) then
                            return
                        end

                        local highlight = Make('Highlight', {
                            FillTransparency = 0.65,
                            OutlineTransparency = 0.5,
                            OutlineColor = Color3.fromRGB(255, 255, 255),
                            FillColor = shriekerColor(model),
                            Adornee = model,
                            Enabled = false,
                            Parent = getShriekerFolder(),
                        })

                        shriekerObjects[model] = highlight
                    end
                    local function removeShrieker(model)
                        local highlight = shriekerObjects[model]

                        if highlight then
                            highlight:Destroy()

                            shriekerObjects[model] = nil
                        end
                    end
                    local function destroyShriekers()
                        for _, highlight in shriekerObjects do
                            highlight:Destroy()
                        end

                        table.clear(shriekerObjects)
                    end

                    ctx.Maid:Give(function()
                        destroyShriekers()

                        if shriekerFolder then
                            shriekerFolder:Destroy()
                        end
                    end)

                    local function enableShrieker()
                        local live = Workspace:FindFirstChild('Live')

                        if live then
                            for _, model in live:GetChildren()do
                                addShrieker(model)
                            end

                            shriekerMaid:Connect(live.ChildAdded, function(
                                model
                            )
                                task.spawn(function()
                                    model:WaitForChild('MonsterInfo', 5)

                                    if Toggles.ShriekerChams and Toggles.ShriekerChams.Value then
                                        addShrieker(model)
                                    end
                                end)
                            end)
                            shriekerMaid:Connect(live.ChildRemoved, removeShrieker)
                        end

                        shriekerMaid:Connect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                        )
                            local myHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                            for model, highlight in shriekerObjects do
                                if model.Parent == nil then
                                    removeShrieker(model)
                                elseif not windowActive then
                                    highlight.Enabled = false
                                else
                                    local hrp = model:FindFirstChild('HumanoidRootPart')

                                    if not hrp then
                                        highlight.Enabled = false
                                    elseif myHrp and (myHrp.Position - hrp.Position).Magnitude > 800 then
                                        highlight.Enabled = false
                                    else
                                        highlight.FillColor = shriekerColor(model)
                                        highlight.Enabled = true
                                    end
                                end
                            end
                        end))
                    end
                    local function disableShrieker()
                        shriekerMaid:DoCleaning()
                        destroyShriekers()
                    end

                    local WorldBox = Visuals:AddLeftGroupbox('World ESP')

                    WorldBox:AddToggle('TrinketEsp', {
                        Text = 'Trinket ESP',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enableTrinket()
                            else
                                disableTrinket()
                            end
                        end,
                    })
                    WorldBox:AddToggle('TrinketShowArea', {
                        Text = 'Show Area',
                        Default = false,
                    })
                    WorldBox:AddDropdown('TrinketTypes', {
                        Text = 'Show Types',
                        Multi = true,
                        Values = {
                            'Common',
                            'Rare',
                            'Mythic',
                            'Artifact',
                            'Event',
                        },
                        Default = {
                            'Common',
                            'Rare',
                            'Mythic',
                            'Artifact',
                            'Event',
                        },
                    })
                    WorldBox:AddDropdown('TrinketIgnoreRangeTypes', {
                        Text = 'Unlimited Range For',
                        Multi = true,
                        Values = {
                            'Common',
                            'Rare',
                            'Mythic',
                            'Artifact',
                            'Event',
                        },
                        Default = {
                            'Mythic',
                            'Artifact',
                            'Event',
                        },
                    })
                    WorldBox:AddSlider('TrinketRange', {
                        Text = 'Range',
                        Min = 0,
                        Max = 2000,
                        Default = 75,
                        Rounding = 0,
                    })
                    WorldBox:AddDivider()
                    WorldBox:AddToggle('ShriekerChams', {
                        Text = 'Shrieker Chams',
                        Tooltip = 'Cyan = yours, red = others',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enableShrieker()
                            else
                                disableShrieker()
                            end
                        end,
                    })
                    WorldBox:AddToggle('FallionEsp', {
                        Text = 'Fallion ESP',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enableFallion()
                            else
                                disableFallion()
                            end
                        end,
                    })
                    WorldBox:AddToggle('NpcEsp', {
                        Text = 'NPC ESP',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enableNpc()
                            else
                                disableNpc()
                            end
                        end,
                    })
                    WorldBox:AddToggle('SpookyHatEsp', {
                        Text = 'Spooky Hat ESP',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enableSpookyHat()
                            else
                                disableSpookyHat()
                            end
                        end,
                    })

                    local IngredientBox = Visuals:AddRightGroupbox('Ingredient ESP')

                    IngredientBox:AddToggle('IngredientEsp', {
                        Text = 'Ingredient ESP',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enableIngredient()
                            else
                                disableIngredient()
                            end
                        end,
                    }):AddKeyPicker('IngredientEspKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'Ingredient ESP',
                        SyncToggleState = true,
                    })
                    IngredientBox:AddDropdown('IngredientTypes', {
                        Text = 'Show',
                        Multi = true,
                        Values = INGREDIENT_NAMES,
                        Default = table.clone(INGREDIENT_NAMES),
                    })
                    IngredientBox:AddSlider('IngredientRange', {
                        Text = 'Range',
                        Min = 0,
                        Max = 2000,
                        Default = 60,
                        Rounding = 0,
                    })

                    local OreBox = Visuals:AddLeftGroupbox('Ore ESP')

                    OreBox:AddToggle('ore_esp', {
                        Text = 'Ore ESP',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enableOre()
                            else
                                disableOre()
                            end
                        end,
                    }):AddKeyPicker('OreEspKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'Ore ESP Toggle',
                        SyncToggleState = true,
                        Callback = function(state)
                            if Toggles.ore_esp.Value ~= state then
                                Toggles.ore_esp:SetValue(state)
                            end
                        end,
                    })
                    OreBox:AddToggle('mythril_esp', {
                        Text = 'Mythril',
                        Default = true,
                    })
                    OreBox:AddToggle('copper_esp', {
                        Text = 'Copper',
                        Default = true,
                    })
                    OreBox:AddToggle('iron_esp', {
                        Text = 'Iron',
                        Default = true,
                    })
                    OreBox:AddToggle('tin_esp', {
                        Text = 'Tin',
                        Default = true,
                    })
                    OreBox:AddSlider('ore_range', {
                        Text = 'Range',
                        Min = 0,
                        Max = 12000,
                        Default = 50,
                        Rounding = 0,
                    })
                end
                do
                    local maid = Maid.new()

                    ctx.Maid:Give(maid)

                    local objects = {}
                    local chamsFolder

                    local function getChamsFolder()
                        if not chamsFolder then
                            chamsFolder = Gui.folder()
                        end

                        return chamsFolder
                    end

                    local WORKSPACE_MONSTERS = {
                        ['Ice Dragon'] = true,
                        ['ChasedDragon'] = true,
                    }

                    local function isMonster(model)
                        return model:IsA('Model') and model ~= LocalPlayer.Character and (model:FindFirstChild('MonsterInfo') ~= nil or WORKSPACE_MONSTERS[model.Name] == true)
                    end
                    local function add(model)
                        if objects[model] or not isMonster(model) then
                            return
                        end

                        objects[model] = MonsterESP.new(model)
                    end
                    local function remove(model)
                        local esp = objects[model]

                        if esp then
                            esp:destroy()

                            objects[model] = nil
                        end
                    end
                    local function destroyAll()
                        for _, esp in objects do
                            esp:destroy()
                        end

                        table.clear(objects)
                    end

                    ctx.Maid:Give(function()
                        destroyAll()

                        if chamsFolder then
                            chamsFolder:Destroy()
                        end
                    end)

                    local function huntsMe(model)
                        local hq = model:FindFirstChild('HuntQuest')

                        if not hq then
                            return false
                        end

                        local ok, value = pcall(function()
                            return hq.Value
                        end)

                        if not ok then
                            return false
                        end
                        if typeof(value) == 'Instance' then
                            return value == LocalPlayer or value.Name == LocalPlayer.Name
                        end

                        return type(value) == 'string' and value == LocalPlayer.Name
                    end

                    local questTarget, lastQuestScan = nil, 0
                    local questHighWater = -1

                    local function resolveQuestTarget()
                        local now = os.clock()

                        if now - lastQuestScan < 0.5 then
                            return questTarget
                        end

                        lastQuestScan = now
                        questTarget = nil

                        if game.PlaceId ~= 3541987450 then
                            return nil
                        end

                        local live = Workspace:FindFirstChild('Live')

                        if not live then
                            return nil
                        end

                        for _, model in live:GetChildren()do
                            if model:IsA('Model') and huntsMe(model) then
                                local n = tonumber(model.Name:match('(%d+)$')) or 0

                                if n >= questHighWater then
                                    questHighWater, questTarget = n, model
                                end
                            end
                        end

                        return questTarget
                    end

                    local monsterEnv = {
                        Toggles = Toggles,
                        Options = Options,
                    }

                    local function buildEnv()
                        monsterEnv.camera = Workspace.CurrentCamera
                        monsterEnv.windowActive = windowActive
                        monsterEnv.chamsFolder = getChamsFolder()
                        monsterEnv.skipShriekers = Toggles.ShriekerChams and Toggles.ShriekerChams.Value or false
                        monsterEnv.questTarget = resolveQuestTarget()

                        return monsterEnv
                    end
                    local function anyOn()
                        return Toggles.MonsterEsp.Value or (Toggles.MonsterChams and Toggles.MonsterChams.Value)
                    end

                    local liveMaid = Maid.new()

                    ctx.Maid:Give(liveMaid)

                    local liveConnected = false

                    local function syncLive()
                        if anyOn() and not liveConnected then
                            liveConnected = true

                            local live = Workspace:FindFirstChild('Live')

                            if live then
                                for _, obj in live:GetDescendants()do
                                    if obj.Name == 'MonsterInfo' and obj.Parent and obj.Parent:IsA('Model') then
                                        add(obj.Parent)
                                    end
                                end

                                liveMaid:Connect(live.DescendantAdded, function(
                                    obj
                                )
                                    if obj.Name == 'MonsterInfo' and obj.Parent and obj.Parent:IsA('Model') and anyOn() then
                                        add(obj.Parent)
                                    end
                                end)
                                liveMaid:Connect(live.DescendantRemoving, function(
                                    obj
                                )
                                    if obj.Name == 'MonsterInfo' and obj.Parent then
                                        remove(obj.Parent)
                                    end
                                end)
                            end

                            local function watchWorkspaceMonster(model)
                                if model and model:IsA('Model') and WORKSPACE_MONSTERS[model.Name] then
                                    add(model)
                                end
                            end

                            for name in WORKSPACE_MONSTERS do
                                watchWorkspaceMonster(Workspace:FindFirstChild(name))
                            end

                            liveMaid:Connect(Workspace.ChildAdded, function(
                                child
                            )
                                if WORKSPACE_MONSTERS[child.Name] and anyOn() then
                                    watchWorkspaceMonster(child)
                                end
                            end)
                            liveMaid:Connect(Workspace.ChildRemoved, function(
                                child
                            )
                                if WORKSPACE_MONSTERS[child.Name] then
                                    remove(child)
                                end
                            end)
                        elseif not anyOn() and liveConnected then
                            liveConnected = false

                            liveMaid:DoCleaning()
                            destroyAll()
                        end
                    end
                    local function enable()
                        syncLive()

                        maid.loop = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                        )
                            local env = buildEnv()

                            for model, esp in objects do
                                if model.Parent == nil then
                                    remove(model)
                                else
                                    esp:update(env)
                                end
                            end
                        end))
                    end
                    local function disable()
                        maid:DoCleaning()

                        for _, esp in objects do
                            esp:hideAll()
                        end

                        syncLive()
                    end

                    local chamsMaid = Maid.new()

                    ctx.Maid:Give(chamsMaid)

                    local function updateChams()
                        syncLive()

                        if Toggles.MonsterChams and Toggles.MonsterChams.Value then
                            chamsMaid.loop = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                            )
                                local env = buildEnv()

                                for _, esp in objects do
                                    esp:updateChams(env)
                                end
                            end))
                        else
                            chamsMaid:DoCleaning()

                            for _, esp in objects do
                                esp:hideChams()
                            end
                        end
                    end

                    local MonsterBox = Visuals:AddRightGroupbox('Monster ESP')

                    MonsterBox:AddToggle('MonsterEsp', {
                        Text = 'Monster ESP',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enable()
                            else
                                disable()
                            end
                        end,
                    }):AddKeyPicker('MonsterEspKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'Monster ESP Toggle',
                        SyncToggleState = true,
                        Callback = function(state)
                            if Toggles.MonsterEsp.Value ~= state then
                                Toggles.MonsterEsp:SetValue(state)
                            end
                        end,
                    })
                    MonsterBox:AddToggle('MonsterName', {
                        Text = 'Name',
                        Default = true,
                    })
                    MonsterBox:AddToggle('MonsterBox', {
                        Text = 'Box',
                        Default = true,
                    })
                    MonsterBox:AddToggle('MonsterHealth', {
                        Text = 'Health',
                        Default = true,
                    })
                    MonsterBox:AddDivider()
                    MonsterBox:AddToggle('MonsterChams', {
                        Text = 'Monster Highlights',
                        Default = false,
                        Callback = updateChams,
                    })
                    MonsterBox:AddToggle('MonsterChamsOccluded', {
                        Text = 'Chams Occluded',
                        Default = false,
                    })
                    MonsterBox:AddSlider('MonsterRange', {
                        Text = 'Range',
                        Min = 0,
                        Max = 5000,
                        Default = 1500,
                        Rounding = 0,
                    })
                end
                do
                    local maid = Maid.new()

                    ctx.Maid:Give(maid)

                    local light = {
                        game = {},
                        ours = {},
                        fullbright = {
                            'Ambient',
                            'OutdoorAmbient',
                            'Brightness',
                        },
                        nofog = {
                            'FogColor',
                            'FogEnd',
                            'FogStart',
                        },
                        tint = nil,
                    }

                    local function same(a, b)
                        if typeof(a) == 'Color3' and typeof(b) == 'Color3' then
                            return math.abs(a.R - b.R) < 0.004 and math.abs(a.G - b.G) < 0.004 and math.abs(a.B - b.B) < 0.004
                        elseif type(a) == 'number' and type(b) == 'number' then
                            return math.abs(a - b) <= 0.001 * math.max(1, math.abs(b))
                        end

                        return a == b
                    end
                    local function hold(prop, value)
                        if light.ours[prop] == nil then
                            light.game[prop] = Lighting[prop]
                        end

                        light.ours[prop] = value
                        Lighting[prop] = value
                    end
                    local function release(props)
                        for _, prop in props do
                            if light.ours[prop] ~= nil then
                                light.ours[prop] = nil

                                if light.game[prop] ~= nil then
                                    Lighting[prop] = light.game[prop]
                                end
                            end
                        end
                    end

                    for _, prop in {
                        'Ambient',
                        'OutdoorAmbient',
                        'Brightness',
                        'FogColor',
                        'FogEnd',
                        'FogStart',
                    }do
                        maid:Connect(Lighting:GetPropertyChangedSignal(prop), BASIL_NO_VIRTUALIZE(function(
                        )
                            local ours = light.ours[prop]

                            if ours == nil then
                                return
                            end

                            local value = Lighting[prop]

                            if not same(value, ours) then
                                light.game[prop] = value
                                Lighting[prop] = ours
                            end
                        end))
                    end

                    local function holdTint()
                        local areacolor = Lighting:FindFirstChild('areacolor')

                        if not areacolor then
                            return
                        end
                        if not (light.tint and light.tint.effect == areacolor) then
                            light.tint = {
                                effect = areacolor,
                                enabled = areacolor.Enabled,
                            }
                            maid.tint = areacolor:GetPropertyChangedSignal('Enabled'):Connect(function(
                            )
                                if light.tint and light.tint.effect == areacolor and areacolor.Enabled then
                                    light.tint.enabled = true
                                    areacolor.Enabled = false
                                end
                            end)
                        end

                        areacolor.Enabled = false
                    end
                    local function releaseTint()
                        local tint = light.tint

                        light.tint = nil
                        maid.tint = nil

                        if tint and tint.effect.Parent then
                            tint.effect.Enabled = tint.enabled
                        end
                    end

                    local applyFullbright = BASIL_NO_VIRTUALIZE(function()
                        local m = Options.BrightnessLevel.Value / 100
                        local color = Color3.new(m, m, m)

                        hold('Ambient', color)
                        hold('OutdoorAmbient', color)
                        hold('Brightness', 1 + m * 2)
                        holdTint()
                    end)
                    local applyNoFog = BASIL_NO_VIRTUALIZE(function()
                        hold('FogColor', Color3.fromRGB(254, 254, 254))
                        hold('FogEnd', 100000)
                        hold('FogStart', 50)
                    end)

                    maid:Connect(Lighting:GetPropertyChangedSignal('ClockTime'), function(
                    )
                        if Toggles.ChangeTime.Value and Lighting.ClockTime ~= Options.ClockTimeValue.Value then
                            Lighting.ClockTime = Options.ClockTimeValue.Value
                        end
                    end)
                    ctx.Maid:Give(function()
                        maid:DoCleaning()
                        release(light.fullbright)
                        release(light.nofog)
                        releaseTint()

                        for toggleKey, effectName in {
                            NoBlindness = 'Blindness',
                            NoBlur = 'Blur',
                            NoSanity = 'Sanity',
                        }do
                            local t = Toggles[toggleKey]
                            local fx = t and t.Value and Lighting:FindFirstChild(effectName)

                            if fx then
                                fx.Enabled = true
                            end
                        end
                    end)

                    local function setEffect(name, enabled)
                        local effect = Lighting:FindFirstChild(name)

                        if effect then
                            effect.Enabled = enabled
                        end
                    end

                    local EnvBox = Visuals:AddRightGroupbox('Environment')

                    EnvBox:AddToggle('Fullbright', {
                        Text = 'Fullbright',
                        Default = false,
                        Callback = function(on)
                            if on then
                                applyFullbright()
                            else
                                release(light.fullbright)
                                releaseTint()
                            end
                        end,
                    }):AddKeyPicker('FullbrightKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'Fullbright Toggle',
                        SyncToggleState = true,
                        Callback = function(state)
                            if Toggles.Fullbright.Value ~= state then
                                Toggles.Fullbright:SetValue(state)
                            end
                        end,
                    })
                    EnvBox:AddSlider('BrightnessLevel', {
                        Text = 'Brightness Level',
                        Min = 0,
                        Max = 100,
                        Default = 80,
                        Rounding = 0,
                        Callback = function()
                            if Toggles.Fullbright.Value then
                                applyFullbright()
                            end
                        end,
                    })
                    EnvBox:AddToggle('NoFog', {
                        Text = 'No Fog',
                        Default = false,
                        Callback = function(on)
                            if on then
                                applyNoFog()
                            else
                                release(light.nofog)
                            end
                        end,
                    }):AddKeyPicker('NoFogKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'No Fog Toggle',
                        SyncToggleState = true,
                        Callback = function(state)
                            if Toggles.NoFog.Value ~= state then
                                Toggles.NoFog:SetValue(state)
                            end
                        end,
                    })
                    EnvBox:AddToggle('ChangeTime', {
                        Text = 'Change Time',
                        Default = false,
                        Callback = function(on)
                            if on then
                                Lighting.ClockTime = Options.ClockTimeValue.Value
                            end
                        end,
                    })
                    EnvBox:AddSlider('ClockTimeValue', {
                        Text = 'Time',
                        Min = 0,
                        Max = 24,
                        Default = 12,
                        Rounding = 0,
                        Callback = function(value)
                            if Toggles.ChangeTime.Value then
                                Lighting.ClockTime = value
                            end
                        end,
                    })
                    EnvBox:AddToggle('NoBlindness', {
                        Text = 'No Blindness',
                        Default = false,
                        Callback = function(on)
                            setEffect('Blindness', not on)
                        end,
                    })
                    EnvBox:AddToggle('NoBlur', {
                        Text = 'No Blur',
                        Default = false,
                        Callback = function(on)
                            setEffect('Blur', not on)
                        end,
                    })
                    EnvBox:AddToggle('NoSanity', {
                        Text = 'No Sanity',
                        Default = false,
                        Callback = function(on)
                            setEffect('Sanity', not on)
                        end,
                    })
                end
                do
                    local ManaBox = Visuals:AddLeftGroupbox('Mana & Vulnere')
                    local DEFAULT = Color3.new(0.842775, 0.347882, 0.00407237)
                    local saved = {}
                    local dragonlings = {}
                    local restoreManaTargets
                    local manaSettledAt = 0

                    ctx.Maid:Give(LocalPlayer.CharacterAdded:Connect(function()
                        manaSettledAt = tick() + 2
                    end))
                    ManaBox:AddToggle('ChangeManaColor', {
                        Text = 'Change Mana Color',
                        Default = false,
                        Callback = function(on)
                            if not on and restoreManaTargets then
                                restoreManaTargets()
                            end
                        end,
                    }):AddColorPicker('ManaColorValue', {Default = DEFAULT})
                    ManaBox:AddToggle('RainbowMana', {
                        Text = 'Rainbow Mana',
                        Default = false,
                    })
                    ManaBox:AddToggle('ChangeVulnColor', {
                        Text = 'Change Vulnere Color',
                        Default = false,
                    }):AddColorPicker('VulnColorValue', {Default = DEFAULT})
                    ManaBox:AddToggle('RainbowVulnere', {
                        Text = 'Rainbow Vulnere',
                        Default = false,
                    })

                    local rainbow = BASIL_NO_VIRTUALIZE(function()
                        return Color3.fromHSV(tick() % 5 / 5, 1, 1)
                    end)
                    local manaColor = BASIL_NO_VIRTUALIZE(function()
                        if Toggles.RainbowMana and Toggles.RainbowMana.Value then
                            return rainbow()
                        end

                        return Options.ManaColorValue.Value
                    end)

                    local function vulnColor()
                        if Toggles.ChangeVulnColor and Toggles.ChangeVulnColor.Value then
                            if Toggles.RainbowVulnere and Toggles.RainbowVulnere.Value then
                                return rainbow()
                            end

                            return Options.VulnColorValue.Value
                        end
                        if Toggles.ChangeManaColor and Toggles.ChangeManaColor.Value then
                            return manaColor()
                        end

                        return nil
                    end

                    local applyOne = BASIL_NO_VIRTUALIZE(function(
                        inst,
                        prop,
                        value
                    )
                        if not inst then
                            return
                        end

                        local props = saved[inst]

                        if not props then
                            props = {}
                            saved[inst] = props
                        end
                        if props[prop] == nil then
                            props[prop] = inst[prop]
                        end

                        pcall(function()
                            inst[prop] = value
                        end)
                    end)
                    local originalManaColor = BASIL_NO_VIRTUALIZE(function()
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local stat = pg and pg:FindFirstChild('StatGui')
                        local left = stat and stat:FindFirstChild('LeftContainer')
                        local mana = left and left:FindFirstChild('Mana')
                        local slider = mana and mana:FindFirstChild('Slider')

                        if slider then
                            local s = saved[slider]

                            return (s and s.BackgroundColor3) or slider.BackgroundColor3
                        end

                        local char = LocalPlayer.Character
                        local abilities = char and char:FindFirstChild('ManaAbilities')
                        local ms = abilities and abilities:FindFirstChild('ManaSprint')

                        if not ms then
                            return nil
                        end

                        local s = saved[ms]

                        return (s and s.Value) or ms.Value
                    end)

                    local function applyManaParticle(inst, seq, baseSeq)
                        if not inst then
                            return
                        end

                        local props = saved[inst]

                        if not props then
                            props = {}
                            saved[inst] = props
                        end
                        if props.Color == nil then
                            props.Color = baseSeq or inst.Color
                        end

                        pcall(function()
                            inst.Color = seq
                        end)
                    end

                    function restoreManaTargets()
                        for inst, props in saved do
                            if inst.Parent then
                                for prop, value in props do
                                    pcall(function()
                                        inst[prop] = value
                                    end)
                                end
                            end
                        end

                        table.clear(saved)
                    end

                    ctx.Maid:Give(restoreManaTargets)

                    local function manaRecolor(inst, color)
                        if not inst then
                            return
                        end
                        if inst:IsA('BasePart') then
                            applyOne(inst, 'Color', color)
                        end

                        for _, d in inst:GetDescendants()do
                            if d:IsA('BasePart') then
                                applyOne(d, 'Color', color)
                            elseif d:IsA('Beam') or d:IsA('ParticleEmitter') or d:IsA('Trail') then
                                applyOne(d, 'Color', ColorSequence.new(color))
                            elseif d:IsA('Light') then
                                applyOne(d, 'Color', color)
                            end
                        end
                    end
                    local function applyManaTargets()
                        if not (Toggles.ChangeManaColor and Toggles.ChangeManaColor.Value) then
                            return
                        end

                        for inst in saved do
                            if not inst.Parent then
                                saved[inst] = nil
                            end
                        end

                        local color = manaColor()
                        local seq = ColorSequence.new(color)
                        local char = LocalPlayer.Character

                        if not char or tick() < manaSettledAt then
                            return
                        end

                        local abilities = char:FindFirstChild('ManaAbilities')
                        local sprint = abilities and abilities:FindFirstChild('ManaSprint')
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local stat = pg and pg:FindFirstChild('StatGui')
                        local left = stat and stat:FindFirstChild('LeftContainer')
                        local mana = left and left:FindFirstChild('Mana')

                        applyOne(mana and mana:FindFirstChild('Slider'), 'BackgroundColor3', color)

                        if sprint then
                            applyOne(sprint, 'Value', color)
                        end

                        local hrp = char:FindFirstChild('HumanoidRootPart')
                        local base = originalManaColor()
                        local baseSeq = base and ColorSequence.new(base) or nil

                        applyManaParticle(hrp and hrp:FindFirstChild('ManaStopParticle'), seq, baseSeq)
                        applyManaParticle(hrp and hrp:FindFirstChild('DodgePartic'), seq, baseSeq)

                        local torso = char:FindFirstChild('Torso')

                        applyOne(torso and torso:FindFirstChild('Clouds'), 'Color', seq)
                        applyOne(torso and torso:FindFirstChild('Shards'), 'Color', seq)

                        for _, armName in {
                            'Right Arm',
                            'Left Arm',
                        }do
                            local arm = char:FindFirstChild(armName)
                            local mag = arm and arm:FindFirstChild('Mag')

                            applyOne(mag and mag:FindFirstChild('Mage'), 'Color', seq)

                            local mag2 = arm and arm:FindFirstChild('Mag2')

                            applyOne(mag2 and mag2:FindFirstChild('Trail'), 'Color', seq)
                        end
                        for _, holderName in {
                            'Hilt',
                            'Torso',
                        }do
                            local holder = char:FindFirstChild(holderName)

                            if holder then
                                for _, w in holder:GetChildren()do
                                    if w:IsA('BasePart') and w.Name:find('Spirit', 1, true) then
                                        applyOne(w, 'Color', color)
                                        applyOne(w, 'Material', Enum.Material.Neon)
                                    elseif w:IsA('BasePart') and w.Name:find('Energy Spear', 1, true) then
                                        applyOne(w, 'Color', color)
                                    end
                                end
                            end
                        end
                        for d in dragonlings do
                            if not d.Parent then
                                dragonlings[d] = nil
                            else
                                local occ = d:FindFirstChild('Occupant')
                                local owner = occ and occ.Value

                                if owner and (owner == char or owner:IsDescendantOf(char)) then
                                    for _, p in d:GetDescendants()do
                                        if p:IsA('BasePart') and p:FindFirstChild('ManaColor') then
                                            applyOne(p, 'Color', color)
                                        elseif p:IsA('Trail') and p.Name == 'MoveT' then
                                            applyOne(p, 'Color', seq)
                                        end
                                    end
                                end
                            end
                        end
                    end

                    local accum = 0

                    ctx.Maid:Connect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                        dt
                    )
                        accum += dt

                        local interval = (Toggles.RainbowMana and Toggles.RainbowMana.Value) and 0.03 or 0.1

                        if accum < interval then
                            return
                        end

                        accum = 0

                        applyManaTargets()
                    end))

                    local vulnPrefix = LocalPlayer.Name .. 'Vulnere'
                    local ourVulns = {}

                    local function nearOurVuln(pos)
                        for i = #ourVulns, 1, -1 do
                            local v = ourVulns[i]

                            if not v.Parent then
                                table.remove(ourVulns, i)
                            else
                                local ok, d = pcall(function()
                                    return (v.Position - pos).Magnitude
                                end)

                                if ok and d < 12 then
                                    return true
                                end
                            end
                        end

                        return false
                    end

                    local colorNear = BASIL_NO_VIRTUALIZE(function(a, b)
                        if math.abs(a.R - b.R) < 0.05 and math.abs(a.G - b.G) < 0.05 and math.abs(a.B - b.B) < 0.05 then
                            return true
                        end

                        local ah, as = a:ToHSV()
                        local bh, bs = b:ToHSV()

                        if as < 0.2 or bs < 0.2 then
                            return false
                        end

                        local dh = math.abs(ah - bh)

                        return math.min(dh, 1 - dh) < 0.04
                    end)
                    local ensnaringUntil = 0
                    local tintThrown = BASIL_NO_VIRTUALIZE(function(
                        obj,
                        ownsFn,
                        duration,
                        apply
                    )
                        if not (Toggles.ChangeManaColor and Toggles.ChangeManaColor.Value) then
                            return
                        end

                        task.spawn(function()
                            local char = LocalPlayer.Character
                            local orig = originalManaColor()

                            if not (obj.Parent and char and orig) then
                                return
                            end

                            local lastUsed = char:FindFirstChild('LastUsed')
                            local lu = (lastUsed and type(lastUsed.Value) == 'string' and lastUsed.Value) or ''

                            if not ownsFn(lu) then
                                return
                            end

                            local matched = false
                            local applied = false
                            local scanUntil = os.clock() + 1
                            local deadline = os.clock() + duration

                            while obj.Parent and Toggles.ChangeManaColor and Toggles.ChangeManaColor.Value and os.clock() < deadline do
                                if not matched and os.clock() < scanUntil then
                                    local base = (obj:IsA('BasePart') and obj) or obj:FindFirstChildWhichIsA('BasePart')

                                    if base and colorNear(base.Color, orig) then
                                        matched = true
                                    end
                                end
                                if matched then
                                    local color = manaColor()

                                    apply(color, ColorSequence.new(color))

                                    applied = true
                                end
                                if applied then
                                    task.wait(0.06)
                                else
                                    task.wait()
                                end
                            end
                        end)
                    end)
                    local onThrownChild = BASIL_NO_VIRTUALIZE(function(obj)
                        if not LocalPlayer.Character then
                            return
                        end
                        if obj.Name == 'ParticleArm' or obj.Name == 'ParticleBack' then
                            if not (Toggles.ChangeManaColor and Toggles.ChangeManaColor.Value) then
                                return
                            end

                            task.spawn(function()
                                local char = LocalPlayer.Character
                                local arm = char and (char:FindFirstChild('Right Arm') or char:FindFirstChild('HumanoidRootPart'))

                                if not (arm and obj:IsA('BasePart')) then
                                    return
                                end

                                task.wait(0.05)

                                if not (obj.Parent and (obj.Position - arm.Position).Magnitude < 8) then
                                    return
                                end

                                local trail = obj:FindFirstChild('TestTrail')

                                if not trail then
                                    return
                                end

                                applyOne(trail, 'Color', ColorSequence.new(manaColor()))

                                while obj.Parent and trail.Parent and Toggles.ChangeManaColor and Toggles.ChangeManaColor.Value and Toggles.RainbowMana and Toggles.RainbowMana.Value do
                                    pcall(function()
                                        trail.Color = ColorSequence.new(rainbow())
                                    end)
                                    task.wait()
                                end

                                if trail.Parent and Toggles.ChangeManaColor and Toggles.ChangeManaColor.Value then
                                    pcall(function()
                                        trail.Color = ColorSequence.new(manaColor())
                                    end)
                                end
                            end)
                        elseif obj.Name == 'Energy Spear' then
                            if Toggles.ChangeManaColor and Toggles.ChangeManaColor.Value then
                                task.spawn(function()
                                    local char = LocalPlayer.Character
                                    local orig = originalManaColor()

                                    if not (obj.Parent and char and orig) then
                                        return
                                    end

                                    local lastUsed = char:FindFirstChild('LastUsed')
                                    local lu = (lastUsed and type(lastUsed.Value) == 'string' and lastUsed.Value) or ''

                                    if not (lu:find('Justice Spears', 1, true) or lu:find('Heroic Volley', 1, true) or char:FindFirstChild('NoJump')) then
                                        return
                                    end

                                    local tracked = {}
                                    local applied = false
                                    local scanUntil = os.clock() + 1
                                    local deadline = os.clock() + 2

                                    while obj.Parent and Toggles.ChangeManaColor and Toggles.ChangeManaColor.Value and os.clock() < deadline do
                                        local color = manaColor()
                                        local seq = ColorSequence.new(color)

                                        if os.clock() < scanUntil then
                                            if obj:IsA('BasePart') and colorNear(obj.Color, orig) then
                                                tracked[obj] = 'part'
                                            end

                                            for _, p in obj:GetDescendants()do
                                                if p:IsA('BasePart') and colorNear(p.Color, orig) then
                                                    tracked[p] = 'part'
                                                elseif p:IsA('Trail') and p.Name == 'MoveT' then
                                                    tracked[p] = 'trail'
                                                end
                                            end
                                        end

                                        for p, kind in tracked do
                                            if p.Parent then
                                                pcall(function()
                                                    if kind == 'trail' then
                                                        p.Color = seq
                                                    else
                                                        p.Color = color
                                                    end
                                                end)

                                                applied = true
                                            end
                                        end

                                        if applied then
                                            task.wait(0.06)
                                        else
                                            task.wait()
                                        end
                                    end
                                end)
                            end
                        elseif obj.Name == 'GroundBase' or obj.Name == 'GroundSpear' then
                            tintThrown(obj, function(lu)
                                if lu:find('Ensnaring Strikes', 1, true) then
                                    ensnaringUntil = os.clock() + 12

                                    return true
                                end

                                return os.clock() < ensnaringUntil
                            end, 12, function(color)
                                pcall(function()
                                    obj.Color = color
                                end)
                            end)
                        elseif obj.Name == 'Arrow' then
                            tintThrown(obj, function(lu)
                                return lu:find('Heroic Volley', 1, true) ~= nil
                            end, 3, function(color, seq)
                                pcall(function()
                                    obj.Color = color
                                end)

                                local at = obj:FindFirstChild('At')
                                local particle = at and at:FindFirstChild('Particle')

                                if particle then
                                    pcall(function()
                                        particle.Color = seq
                                    end)
                                end

                                local light = obj:FindFirstChild('Light')

                                if light then
                                    pcall(function()
                                        light.Color = color
                                    end)
                                end

                                local trail = obj:FindFirstChild('Trail')

                                if trail then
                                    pcall(function()
                                        trail.Color = seq
                                    end)
                                end
                            end)
                        elseif obj.Name == 'shinie' then
                            local vc = vulnColor()

                            if not (vc and obj:IsA('BasePart') and nearOurVuln(obj.Position)) then
                                return
                            end

                            local att = obj:FindFirstChild('Attachment')

                            if att then
                                for _, n in {
                                    'arc',
                                    'light',
                                }do
                                    local p = att:FindFirstChild(n)

                                    if p then
                                        pcall(function()
                                            p.Color = ColorSequence.new(vc)
                                        end)
                                    end
                                end
                            end
                        elseif obj.Name:sub(1, #vulnPrefix) == vulnPrefix then
                            local vc = vulnColor()

                            if not vc then
                                return
                            end

                            table.insert(ourVulns, obj)
                            task.spawn(function()
                                local deadline = tick() + 1.2

                                while obj.Parent and tick() < deadline do
                                    pcall(function()
                                        obj.Color = vc
                                    end)

                                    local trail = obj:FindFirstChild('VulnTrail')

                                    if trail then
                                        pcall(function()
                                            trail.Color = ColorSequence.new(vc)
                                        end)
