                    end
                    if wasKilled then
                        Debug.log('menutele', 'stopping: the attempt ended in a death rather than a menu')

                        break
                    end
                end

                Debug.log('menutele', string.format('%s after %d attempt(s)', landed and 'landed' or 'gave up', tries))

                return landed
            end

            function Menu.menuTele(pos, shouldRun, maxAttempts)
                shouldRun = shouldRun or alwaysRun

                local release = teleportGuard and teleportGuard(MENU_TELE_GUARD)
                local releaseFps = FpsCap.lift()
                local ok, landed = pcall(menuTeleAttempts, pos, shouldRun, maxAttempts)

                releaseFps()

                if release then
                    release()
                end
                if not ok then
                    error(landed, 0)
                end

                return landed
            end

            return Menu
        end

