                            end

                            local view = CFrame.new(camPos) * CFrame.fromEulerAnglesYXZ(
-movePosition.Y / 300, -movePosition.X / 300, 0) * CFrame.new(velocity + Vector3.new(0, 0, dolly))

                            camPos = view.Position
                            Workspace.CurrentCamera.CFrame = view

                            if rightDown then
                                local pos = Vector2.new(mouse.X, mouse.Y)

                                UserInputService.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition

                                movePosition -= lastRight - pos

                                lastRight = pos
                            end
                        end))
                        engineMaid:Give(function()
                            pcall(RunService.UnbindFromRenderStep, RunService, 'SentinelFreecamView')
                        end)
                    end
                    local function disable()
                        engineMaid:DoCleaning()
                        table.clear(keysDown)

                        velocity, dolly = Vector3.zero, 0
                        rightDown = false

                        pcall(ContextActionService.UnbindAction, ContextActionService, 'SentinelFreecam')

                        UserInputService.MouseBehavior = Enum.MouseBehavior.Default

                        local camera = Workspace.CurrentCamera

                        camera.CameraType = Enum.CameraType.Custom

                        local char = getChar()
                        local humanoid = char and char:FindFirstChildOfClass('Humanoid')

                        if humanoid then
                            camera.CameraSubject = humanoid
                        end
                    end

                    ctx.State.freecamAt = function(target)
                        if typeof(target) ~= 'CFrame' then
                            return false
                        end

                        local pitch, yaw = target:ToEulerAnglesYXZ()

                        movePosition = Vector2.new(-yaw * 300, math.clamp(-pitch * 300,
-460, 460))
                        velocity, dolly = Vector3.zero, 0
                        camPos = target.Position
                        Workspace.CurrentCamera.CFrame = target

                        if Toggles.Freecam and not Toggles.Freecam.Value then
                            Toggles.Freecam:SetValue(true)
                        else
                            Workspace.CurrentCamera.CameraType = Enum.CameraType.Scriptable
                        end

                        return true
                    end
                    ctx.State.freecamOff = function()
                        if Toggles.Freecam and Toggles.Freecam.Value then
                            Toggles.Freecam:SetValue(false)
                        end
                    end

                    ctx.Maid:Give(function()
                        if Toggles.Freecam and Toggles.Freecam.Value then
                            disable()
                        end
                    end)

                    local FreecamBox = Movement:AddRightGroupbox('Freecam')

                    FreecamBox:AddToggle('Freecam', {
                        Text = 'Freecam',
                        Default = false,
                        Callback = function(on)
                            if on then
                                enable()
                            else
                                disable()
                            end
                        end,
                    }):AddKeyPicker('FreecamKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'Freecam Toggle',
                        SyncToggleState = true,
                        Callback = function(state)
                            if Toggles.Freecam.Value ~= state then
                                Toggles.Freecam:SetValue(state)
                            end
                        end,
                    })
                    FreecamBox:AddToggle('FreecamMoveCharacter', {
                        Text = 'Move Character',
                        Tooltip = 'Walk around while the camera stays put',
                        Default = false,
                    })
                    FreecamBox:AddSlider('FreecamSpeed', {
                        Text = 'Freecam Speed',
                        Min = 0,
                        Max = 12,
                        Default = 1,
                        Rounding = 1,
                    })
                    FreecamBox:AddSlider('FreecamSmoothing', {
                        Text = 'Smoothing',
                        Tooltip = '0 = instant',
                        Min = 0,
                        Max = 100,
                        Default = 25,
                        Rounding = 0,
                    })
                end
                do
                    local maid = Maid.new()

                    ctx.Maid:Give(maid)

                    local speedObject
                    local lastNotif = 0

                    local function targetValue()
                        if not (Toggles.SpeedBoost and Toggles.SpeedBoost.Value) then
                            return 0
                        end

                        return (Options.SpeedBoostValue and Options.SpeedBoostValue.Value) or 16
                    end
                    local function makeSpeedObject(char)
                        local boosts = char and char:FindFirstChild('Boosts')

                        if not boosts then
                            return
                        end
                        if speedObject and speedObject.Parent then
                            speedObject:Destroy()
                        end

                        speedObject = Make('IntValue', {
                            Name = 'SpeedBoost',
                            Value = targetValue(),
                            Parent = boosts,
                        })
                    end
                    local function setup(char)
                        if not char then
                            return
                        end

                        task.spawn(function()
                            char:WaitForChild('Boosts', 10)

                            if Toggles.SpeedBoost and Toggles.SpeedBoost.Value then
                                makeSpeedObject(char)
                            end
                        end)
                    end

                    local SpeedBox = Movement:AddLeftGroupbox('Speed')

                    SpeedBox:AddToggle('SpeedBoost', {
                        Text = 'SpeedBoost',
                        Tooltip = 'Capped at 20 without Blatant',
                        Default = false,
                        Callback = function()
                            makeSpeedObject(getChar())
                        end,
                    })
                    SpeedBox:AddSlider('SpeedBoostValue', {
                        Text = 'Speed',
                        Default = 16,
                        Min = 0.1,
                        Max = 250,
                        Rounding = 1,
                        Callback = function(value)
                            if not (Toggles.BlatantMode and Toggles.BlatantMode.Value) and value > 20 then
                                Options.SpeedBoostValue:SetValue(20)

                                local now = tick()

                                if now - lastNotif > 2 then
                                    Notify.say('Speed limited to 20 (Blatant Mode off)')

                                    lastNotif = now
                                end

                                return
                            end
                            if Toggles.SpeedBoost and Toggles.SpeedBoost.Value and speedObject and speedObject.Parent then
                                speedObject.Value = value
                            end
                        end,
                    })

                    maid.respawn = LocalPlayer.CharacterAdded:Connect(setup)

                    if getChar() then
                        setup(getChar())
                    end

                    ctx.Maid:Give(function()
                        if speedObject and speedObject.Parent then
                            pcall(function()
                                speedObject:Destroy()
                            end)
                        end
                    end)
                end
                do
                    local WAYPOINT_ROOT = 'sentinel/waypoints'
                    local WAYPOINT_DIR = WAYPOINT_ROOT .. '/' .. tostring(game.PlaceId)
                    local WaypointBox = Movement:AddRightGroupbox('Waypoints')
                    local markerMaid = Maid.new()

                    ctx.Maid:Give(markerMaid)

                    local drawWaypoints

                    local function migrateFlatWaypoints()
                        if not (listfiles and isfile and readfile and writefile and delfile and isfolder and makefolder) then
                            return
                        end

                        local ok, files = pcall(listfiles, WAYPOINT_ROOT)

                        if not ok or not files then
                            return
                        end

                        for _, file in files do
                            local name = tostring(file):match('([^/\\]+)%.json$')

                            if name and isfile(file) then
                                local read, body = pcall(readfile, file)
                                local decoded = read and select(2, pcall(function(
                                )
                                    return HttpService:JSONDecode(body)
                                end))
                                local place = type(decoded) == 'table' and tonumber(decoded.place)

                                if place then
                                    local dir = WAYPOINT_ROOT .. '/' .. tostring(place)

                                    if not isfolder(dir) then
                                        pcall(makefolder, dir)
                                    end

                                    local target = dir .. '/' .. name .. '.json'

                                    if not isfile(target) and pcall(writefile, target, body) then
                                        pcall(delfile, file)
                                    end
                                end
                            end
                        end
                    end

                    pcall(migrateFlatWaypoints)

                    local function waypointFiles()
                        local out = {}

                        if not listfiles then
                            return out
                        end

                        local ok, files = pcall(listfiles, WAYPOINT_DIR)

                        if ok and files then
                            for _, file in files do
                                local name = tostring(file):match('([^/\\]+)%.json$')

                                if name then
                                    table.insert(out, name)
                                end
                            end
                        end

                        table.sort(out)

                        return out
                    end
                    local function readWaypoint(name)
                        local file = WAYPOINT_DIR .. '/' .. tostring(name or '') .. '.json'

                        if not (isfile and readfile) or tostring(name or '') == '' or not isfile(file) then
                            return nil
                        end

                        local ok, decoded = pcall(function()
                            return HttpService:JSONDecode(readfile(file))
                        end)

                        if not ok or type(decoded) ~= 'table' or type(decoded.x) ~= 'number' then
                            return nil
                        end

                        return decoded
                    end

                    function drawWaypoints()
                        markerMaid:DoCleaning()

                        if not (Toggles.VisualizeWaypoints and Toggles.VisualizeWaypoints.Value) then
                            return
                        end

                        local home = Workspace:FindFirstChild('Thrown') or Workspace

                        for _, name in waypointFiles()do
                            local point = readWaypoint(name)

                            if point and (not point.place or point.place == game.PlaceId) then
                                local marker = Make('Part', {
                                    Shape = Enum.PartType.Ball,
                                    Size = Vector3.new(2, 2, 2),
                                    Position = Vector3.new(point.x, point.y, point.z),
                                    Anchored = true,
                                    CanCollide = false,
                                    CanQuery = false,
                                    CanTouch = false,
                                    CastShadow = false,
                                    Material = Enum.Material.Neon,
                                    Color = Color3.fromRGB(120, 255, 180),
                                    Transparency = 0.2,
                                })
                                local tag = Make('BillboardGui', {
                                    Size = UDim2.new(0, 140, 0, 26),
                                    StudsOffset = Vector3.new(0, 2.2, 0),
                                    AlwaysOnTop = true,
                                    LightInfluence = 0,
                                    Parent = marker,
                                })
                                local text = Make('TextLabel', {
                                    Size = UDim2.fromScale(1, 1),
                                    BackgroundTransparency = 1,
                                    Font = Enum.Font.GothamBold,
                                    TextSize = 14,
                                    TextColor3 = marker.Color,
                                    TextStrokeTransparency = 0.3,
                                    Text = name,
                                    Parent = tag,
                                })

                                marker.Parent = home

                                markerMaid:Give(marker)
                            end
                        end
                    end

                    local function refreshWaypoints(pick)
                        if Options.SavedWaypoints then
                            Options.SavedWaypoints:SetValues(waypointFiles())

                            if pick then
                                Options.SavedWaypoints:SetValue(pick)
                            end
                        end

                        drawWaypoints()
                    end

                    WaypointBox:AddToggle('VisualizeWaypoints', {
                        Text = 'Show Waypoints',
                        Default = false,
                        Callback = function()
                            drawWaypoints()
                        end,
                    })
                    WaypointBox:AddInput('WaypointName', {
                        Text = 'Name',
                        Placeholder = 'where you are standing',
                        Finished = true,
                    })
                    WaypointBox:AddButton({
                        Text = 'Save Waypoint',
                        Func = function()
                            local root = Character.root()

                            if not root then
                                Notify.say('No character to take a waypoint from')

                                return
                            end

                            local name = tostring((Options.WaypointName and Options.WaypointName.Value) or ''):match('^%s*(.-)%s*$')

                            name = name:gsub('[^%w _%-]', '')

                            if name == '' then
                                Notify.say('Give the waypoint a name first')

                                return
                            end
                            if not (writefile and makefolder and isfolder) then
                                Notify.say('This executor cannot write files')

                                return
                            end
                            if not isfolder('sentinel') then
                                pcall(makefolder, 'sentinel')
                            end
                            if not isfolder(WAYPOINT_ROOT) then
                                pcall(makefolder, WAYPOINT_ROOT)
                            end
                            if not isfolder(WAYPOINT_DIR) then
                                pcall(makefolder, WAYPOINT_DIR)
                            end

                            local body = HttpService:JSONEncode({
                                x = root.Position.X,
                                y = root.Position.Y,
                                z = root.Position.Z,
                                place = game.PlaceId,
                            })

                            if not pcall(writefile, WAYPOINT_DIR .. '/' .. name .. '.json', body) then
                                Notify.say('Could not write that waypoint')

                                return
                            end

                            refreshWaypoints(name)
                            Notify.say('Saved waypoint ' .. name)
                        end,
                    })
                    WaypointBox:AddDropdown('SavedWaypoints', {
                        Text = 'Saved',
                        Values = waypointFiles(),
                        Default = nil,
                        AllowNull = true,
                    })
                    WaypointBox:AddButton({
                        Text = 'Teleport',
                        Tooltip = Gate.blatant(),
                        Func = function()
                            if not Gate.allow(ctx, 'Blatant', 'Waypoint teleport') then
                                return
                            end

                            local name = Options.SavedWaypoints and Options.SavedWaypoints.Value
                            local point = readWaypoint(name)

                            if not point then
                                Notify.say('Pick a saved waypoint first')

                                return
                            end
                            if point.place and point.place ~= game.PlaceId then
                                Notify.say('That waypoint was saved in another realm')

                                return
                            end

                            local target = Vector3.new(point.x, point.y, point.z)

                            task.spawn(function()
                                local landed = Menu.menuTele(target, nil, 1)

                                Library:Notify({
                                    Title = 'sentinel.bz',
                                    Description = landed and ('Landed at ' .. tostring(name)) or ('Menu teleport to ' .. tostring(name) .. ' failed'),
                                })
                            end)
                        end,
                    })
                    WaypointBox:AddButton({
                        Text = 'Delete Waypoint',
                        DoubleClick = true,
                        Func = function()
                            local name = Options.SavedWaypoints and Options.SavedWaypoints.Value

                            if not name or name == '' or not delfile then
                                return
                            end

                            pcall(delfile, WAYPOINT_DIR .. '/' .. name .. '.json')
                            refreshWaypoints()
                            Notify.say('Deleted waypoint ' .. tostring(name))
                        end,
                    })
                    WaypointBox:AddButton({
                        Text = 'Refresh List',
                        Func = refreshWaypoints,
                    })
                end
                do
                    local BoostBox = Movement:AddLeftGroupbox('Boosts')
                    local climbMaid = Maid.new()

                    ctx.Maid:Give(climbMaid)

                    local climbBuff

                    local function myClimbBuff(value)
                        return value:IsA('NumberValue') and value.Name == 'ClimbBoost' and value:GetAttribute('MyClimbBuff') == true
                    end
                    local function stripClimbBuffs(char)
                        local boosts = char and char:FindFirstChild('Boosts')

                        if not boosts then
                            return
                        end

                        for _, value in boosts:GetChildren()do
                            if myClimbBuff(value) then
                                pcall(function()
                                    value:Destroy()
                                end)
                            end
                        end

                        climbBuff = nil
                    end
                    local function applyClimbBoost(char)
                        if not (char and Toggles.ClimbBoost and Toggles.ClimbBoost.Value) then
                            return
                        end

                        local boosts = char:FindFirstChild('Boosts') or char:WaitForChild('Boosts', 10)

                        if not (boosts and Toggles.ClimbBoost.Value and char.Parent) then
                            return
                        end

                        for _, value in boosts:GetChildren()do
                            if myClimbBuff(value) then
                                climbBuff = value

                                break
                            end
                        end

                        if not (climbBuff and climbBuff.Parent) then
                            climbBuff = Make('NumberValue', {
                                Name = 'ClimbBoost',
                            })

                            climbBuff:SetAttribute('MyClimbBuff', true)

                            climbBuff.Parent = boosts
                        end

                        climbBuff.Value = (Options.ClimbBoostValue and Options.ClimbBoostValue.Value) or 2.1
                    end

                    local gelidusMaid = Maid.new()

                    ctx.Maid:Give(gelidusMaid)

                    local tracked = {}
                    local lastGelidusNotif = 0

                    local function trackGelidus(obj)
                        if obj:IsA('BodyVelocity') and obj.Name == 'ForwardVelocity' and obj.MaxForce == GELIDUS_FORCE then
                            tracked[obj] = true
                        end
                    end
                    local function watchGelidusRoot(char)
                        local root = getHRP(char)

                        if not root then
                            return
                        end

                        for _, obj in root:GetChildren()do
                            trackGelidus(obj)
                        end

                        gelidusMaid.root = root.ChildAdded:Connect(trackGelidus)
                    end
                    local function startGelidus()
                        gelidusMaid:DoCleaning()
                        table.clear(tracked)
                        watchGelidusRoot(getChar())

                        gelidusMaid.spawned = LocalPlayer.CharacterAdded:Connect(function(
                            char
                        )
                            table.clear(tracked)
                            watchGelidusRoot(char)
                        end)
                        gelidusMaid.step = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                        )
                            local want = math.clamp(Options.GelidusSpeed.Value, GELIDUS_SLIDER_MIN, GELIDUS_SLIDER_MAX)

                            for obj in tracked do
                                if not obj.Parent then
                                    tracked[obj] = nil
                                elseif obj.MaxForce == GELIDUS_FORCE then
                                    local velocity = obj.Velocity
                                    local flat = Vector3.new(velocity.X, 0, velocity.Z)
                                    local speed = flat.Magnitude

                                    if speed > 0 then
                                        if speed >= GELIDUS_MIN_SPEED and speed <= GELIDUS_MAX_SPEED then
                                            speed = want
                                        end

                                        speed = math.min(speed, want)

                                        local dir = flat.Unit

                                        obj.Velocity = Vector3.new(dir.X * speed, velocity.Y, dir.Z * speed)
                                    end
                                end
                            end
                        end))
                    end

                    local vimInstance

                    local function getVim()
                        if not vimInstance then
                            local ok, v = pcall(function()
                                return Instance.new('VirtualInputManager')
                            end)

                            vimInstance = ok and v or nil
                        end

                        return vimInstance
                    end

                    local manaRunMaid = Maid.new()

                    ctx.Maid:Give(manaRunMaid)

                    local lastTap = {}
                    local activeDirection, syntheticW, syntheticDown
                    local activationId = 0

                    local function sendKey(down, code)
                        local vim = getVim()

                        if not vim then
                            return
                        end

                        pcall(function()
                            vim:SendKeyEvent(down, code, false, game)
                        end)
                    end
                    local function tapKey(code)
                        sendKey(true, code)
                        task.wait(MANA_RUN_STEP)
                        sendKey(false, code)
                    end
                    local function releaseManaRun()
                        activationId += 1

                        syntheticDown = false
                        syntheticW = false

                        sendKey(false, Enum.KeyCode.Down)
                        sendKey(false, Enum.KeyCode.W)

                        activeDirection = nil
                    end
                    local function activateManaRun(direction)
                        releaseManaRun()

                        activationId += 1

                        local mine = activationId

                        activeDirection = direction

                        task.spawn(function()
                            local function stale()
                                return mine ~= activationId or activeDirection ~= direction
                            end

                            tapKey(Enum.KeyCode.W)
                            task.wait(MANA_RUN_STEP)

                            if stale() then
                                return
                            end

                            sendKey(true, Enum.KeyCode.W)

                            syntheticW = true

                            task.wait(MANA_RUN_STEP)

                            if stale() then
                                return
                            end

                            tapKey(Enum.KeyCode.Up)

                            if direction ~= Enum.KeyCode.S or stale() then
                                return
                            end

                            tapKey(Enum.KeyCode.Down)

                            if stale() then
                                return
                            end

                            sendKey(true, Enum.KeyCode.Down)

                            syntheticDown = true
                        end)
                    end

                    local climbToggle = BoostBox:AddToggle('ClimbBoost', {
                        Text = 'Climb Boost',
                        Default = false,
                        Tooltip = Gate.risky(),
                        Callback = function(on)
                            climbMaid:DoCleaning()

                            if not on then
                                stripClimbBuffs(getChar())

                                return
                            end

                            task.spawn(applyClimbBoost, getChar())

                            climbMaid.respawn = LocalPlayer.CharacterAdded:Connect(function(
                                char
                            )
                                climbBuff = nil

                                task.spawn(applyClimbBoost, char)
                            end)
                        end,
                    })

                    Gate.mark(ctx, 'Risky', 'ClimbBoost', climbToggle)

                    local gelidusToggle = BoostBox:AddToggle('GelidusBoost', {
                        Text = 'Gelidus Boost',
                        Tooltip = Gate.risky('faster Gelidus slide'),
                        Default = false,
                        Callback = function(on)
                            if on then
                                startGelidus()
                            else
                                gelidusMaid:DoCleaning()
                                table.clear(tracked)
                            end
                        end,
                    })

                    Gate.mark(ctx, 'Risky', 'GelidusBoost', gelidusToggle)

                    do
                        local hoppaMaid = Maid.new()

                        ctx.Maid:Give(hoppaMaid)

                        local lifted = {}
                        local lifts = {
                            [50] = 120,
                            [100] = 200,
                            [200] = 280,
                            [400] = 500,
                        }

                        local function trackHoppa(obj)
                            if obj:IsA('BodyVelocity') and obj.Name == 'WindVelocity' then
                                lifted[obj] = false
                            end
                        end
                        local function watchHoppaRoot(char)
                            local root = char and (getHRP(char) or char:WaitForChild('HumanoidRootPart', 10))

                            if not (root and Toggles.HoppaBoost.Value) then
                                return
                            end

                            for _, obj in root:GetChildren()do
                                trackHoppa(obj)
                            end

                            hoppaMaid.root = root.ChildAdded:Connect(trackHoppa)
                        end
                        local function startHoppa()
                            hoppaMaid:DoCleaning()
                            table.clear(lifted)
                            task.spawn(watchHoppaRoot, getChar())

                            hoppaMaid.spawned = LocalPlayer.CharacterAdded:Connect(function(
                                char
                            )
                                table.clear(lifted)
                                watchHoppaRoot(char)
                            end)
                            hoppaMaid.step = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                            )
                                for obj, y in lifted do
                                    if not obj.Parent then
                                        lifted[obj] = nil
                                    elseif obj.MaxForce == Vector3.new(1000000, 1000000, 1000000) then
                                        local velocity = obj.Velocity

                                        if not y then
                                            for from, to in lifts do
                                                if math.abs(velocity.Y - from) <= 0.5 then
                                                    y = to
                                                    lifted[obj] = to

                                                    break
                                                end
                                            end
                                        end
                                        if y then
                                            obj.Velocity = Vector3.new(velocity.X, y, velocity.Z)
                                        end
                                    end
                                end
                            end))
                        end

                        local hoppaToggle = BoostBox:AddToggle('HoppaBoost', {
                            Text = 'Hoppa Boost',
                            Tooltip = Gate.risky('higher Hoppa jumps'),
                            Default = false,
                            Callback = function(on)
                                if on then
                                    startHoppa()
                                else
                                    hoppaMaid:DoCleaning()
                                    table.clear(lifted)
                                end
                            end,
                        })

                        Gate.mark(ctx, 'Risky', 'HoppaBoost', hoppaToggle)
                    end

                    BoostBox:AddToggle('DirectionalManaRun', {
                        Text = 'Directional Mana Run',
                        Default = false,
                        Tooltip = 'Double tap A, D or S to mana run that way',
                        Callback = function(on)
                            if not on then
                                releaseManaRun()
                            end
                        end,
                    })
                    BoostBox:AddDivider()
                    BoostBox:AddSlider('ClimbBoostValue', {
                        Text = 'Climb',
                        Default = 2.1,
                        Min = 0.1,
                        Max = 10,
                        Rounding = 1,
                        Callback = function(value)
                            if climbBuff and climbBuff.Parent then
                                climbBuff.Value = value
                            end
                        end,
                    })
                    BoostBox:AddSlider('GelidusSpeed', {
                        Text = 'Gelidus Speed',
                        Min = GELIDUS_SLIDER_MIN,
                        Max = GELIDUS_SLIDER_MAX,
                        Default = 103,
                        Rounding = 0,
                        Callback = function(value)
                            if blatantOn() or value <= GELIDUS_LEGIT_MAX then
                                return
                            end

                            Options.GelidusSpeed:SetValue(GELIDUS_LEGIT_MAX)

                            local now = tick()

                            if now - lastGelidusNotif > 2 then
                                lastGelidusNotif = now

                                Notify.say('Gelidus speed limited to ' .. GELIDUS_LEGIT_MAX .. ' (Blatant Mode off)')
                            end
                        end,
                    })
                    manaRunMaid:Connect(UserInputService.InputBegan, function(
                        input,
                        processed
                    )
                        if processed or getFocusedTextBox(UserInputService) then
                            return
                        end
                        if not (Toggles.DirectionalManaRun and Toggles.DirectionalManaRun.Value) then
                            return
                        end

                        local code = input.KeyCode

                        if code ~= Enum.KeyCode.A and code ~= Enum.KeyCode.S and code ~= Enum.KeyCode.D then
                            return
                        end

                        local now = tick()
                        local previous = lastTap[code] or 0

                        lastTap[code] = now

                        if previous > 0 and (now - previous) <= MANA_RUN_DOUBLE_TAP then
                            lastTap[code] = 0

                            activateManaRun(code)
                        end
                    end)
                    manaRunMaid:Connect(UserInputService.InputEnded, function(
                        input
                    )
                        if not activeDirection then
                            return
                        end

                        local code = input.KeyCode
                        local watched = code == Enum.KeyCode.A or code == Enum.KeyCode.S or code == Enum.KeyCode.D

                        if code == activeDirection or (watched and not isKeyDown(UserInputService, activeDirection)) then
                            releaseManaRun()
                        end
                    end)
                    ctx.Maid:Give(releaseManaRun)
                    ctx.Maid:Give(function()
                        stripClimbBuffs(getChar())
                    end)
                end
            end
        end

        function __DARKLUA_BUNDLE_MODULES.H(): typeof(__modImpl())
            local v = __DARKLUA_BUNDLE_MODULES.cache.H

