            local function getPing()
                local ok, ping = pcall(function()
                    return game:GetService('Stats'):WaitForChild('PerformanceStats'):WaitForChild('Ping'):GetValue()
                end)

                return ok and ping or 0
            end
            local function randomWait(usePing)
                if usePing then
                    local d = 0.025 + getPing() / 1000

                    return d > 0.35 and 0.35 or d
                end

                local base = math.random(25, 350) / 1000
                local jitter = math.random() * 0.05

                if math.random() < 0.2 then
                    base = base + math.random() * 0.1
                end

                local d = base + jitter

                if d < 0.025 then
                    d = 0.025
                end
                if d > 0.35 then
                    d = 0.35
                end

                return d
            end

            local RING_DROP = Vector3.new(0, -60, 0)

            local function safeConnect(signal, fn)
                local ok, conn = pcall(function()
                    return signal:Connect(fn)
                end)

                return ok and conn or nil
            end

            return function(ctx)
                local Library = ctx.Library
                local Toggles, Options = Library.Toggles, Library.Options
                local Automation = ctx.Tabs.Automation
                local fireclickdetector = fireclickdetector
                local firetouchinterest = firetouchinterest
                local firesignal = firesignal
                local replicatesignal = replicatesignal
                local getconnections = getconnections
                local hookfunction = hookfunction
                local unloaded = false
                local featureMaid = Maid.new()

                ctx.Maid:Give(featureMaid)
                ctx.Maid:Give(function()
                    unloaded = true
                end)

                ctx.State.Serverhop = Serverhop
                ctx.State.CpuThrottle = CpuThrottle
                ctx.State.spellCost = SPELL_COST

                ctx.Maid:Give(function()
                    CpuThrottle.stop()
                end)

                local function notify(text)
                    Notify.say(text)
                end

                do
                    local AutomationTabs = Automation:AddLeftTabbox()

                    ctx.State.progressionTab = AutomationTabs:AddTab('Progression')

                    if IS_KHEI then
                        ctx.State.gripsTab = AutomationTabs:AddTab('Grips')
                    end

                    ctx.State.castleRockTab = AutomationTabs:AddTab('Castle Rock')
                    ctx.State.rotBotTab = AutomationTabs:AddTab('Rot Bot')
                    ctx.State.scroomBotTab = AutomationTabs:AddTab('Scroom Bot')

                    if IS_KHEI then
                        for _, hidden in {
                            ctx.State.castleRockTab,
                            ctx.State.rotBotTab,
                            ctx.State.scroomBotTab,
                        }do
                            hidden.Button.Visible = false
                        end
                    end

                    local DIALOGUE_SPEAKERS = {
                        ['Doctor'] = true,
                        ['Engineer'] = true,
                        ['Miner John'] = true,
                        ['Mysterious Stranger'] = true,
                        ['Vinifera'] = true,
                        ['Gary'] = true,
                        ['Yeti'] = true,
                        ['Inn Keeper'] = true,
                        ['Fallion'] = true,
                        ['Kyley'] = true,
                        ['Innkeeper'] = true,
                        ['Esterina'] = true,
                    }
                    local dialogueRemote, dialogueConn
                    local scanConns = {}

                    local function handleDialogue(data)
                        if not (Toggles.AutoDialogue and Toggles.AutoDialogue.Value) then
                            return
                        end

                        local char = LocalPlayer.Character

                        if not char or not char:FindFirstChild('InDialogue') then
                            return
                        end

                        local speaker = data.speaker
                        local msg = data.msg
                        local obelisk = type(msg) == 'string' and msg:find('Obelisk', 1, true) ~= nil

                        if obelisk then
                        elseif not speaker or speaker == '' or speaker:match('^%s*$') then
                            return
                        elseif speaker == '...' then
                            local choices = data.choices

                            if msg and msg:find('drop back to your inn') and choices and choices[1] == 'Take me away.' then
                            else
                                return
                            end
                        elseif not DIALOGUE_SPEAKERS[speaker] then
                            return
                        end

                        task.wait(0.1)

                        if not dialogueRemote then
                            return
                        end
                        if obelisk then
                            local resonate

                            for _, choice in data.choices or {}do
                                if type(choice) == 'string' and choice:lower() == 'resonate' then
                                    resonate = choice

                                    break
                                end
                            end

                            if resonate then
                                dialogueRemote:FireServer({choice = resonate})
                            else
                                dialogueRemote:FireServer({exit = true})
                            end

                            return
                        end
                        if not data.choices or #data.choices == 0 then
                            dialogueRemote:FireServer({exit = true})
                        else
                            dialogueRemote:FireServer({
                                choice = data.choices[1],
                            })
                        end
                    end
                    local function hasField(tbl, key)
                        for k in pairs(tbl)do
                            if typeof(k) == 'string' and k:lower() == key then
                                return true
                            end
                        end

                        return false
                    end
                    local function bindDialogueRemote(remote)
                        dialogueRemote = remote

                        if dialogueConn then
                            dialogueConn:Disconnect()
                        end

                        dialogueConn = safeConnect(remote.OnClientEvent, handleDialogue)
                    end
                    local function setupDialogue()
                        if dialogueRemote then
                            return
                        end

                        local requests = ReplicatedStorage:FindFirstChild('Requests')

                        if not requests then
                            return
                        end

                        local direct = requests:FindFirstChild('Dialogue')

                        if direct and direct:IsA('RemoteEvent') then
                            bindDialogueRemote(direct)

                            return
                        end

                        for _, remote in requests:GetChildren()do
                            if remote:IsA('RemoteEvent') then
                                local conn = safeConnect(remote.OnClientEvent, function(
                                    data
                                )
                                    if typeof(data) == 'table' and (hasField(data, 'choices') or hasField(data, 'speaker')) then
                                        if not dialogueRemote then
                                            bindDialogueRemote(remote)
                                            handleDialogue(data)
                                        end
                                    end
                                end)

                                if conn then
                                    table.insert(scanConns, conn)
                                end
                            end
                        end
                    end
                    local function teardownDialogue()
                        for _, c in scanConns do
                            pcall(function()
                                c:Disconnect()
                            end)
                        end

                        scanConns = {}

                        if dialogueConn then
                            dialogueConn:Disconnect()

                            dialogueConn = nil
                        end

                        dialogueRemote = nil
                    end

                    featureMaid:Give(teardownDialogue)

                    ctx.State.autoDialogueSetup = setupDialogue
                    ctx.State.autoDialogueTeardown = teardownDialogue

                    local bardConns = {}

                    local function clearBardConns()
                        for _, c in bardConns do
                            pcall(function()
                                c:Disconnect()
                            end)
                        end

                        bardConns = {}
                    end
                    local function canSignal()
                        return replicatesignal ~= nil or firesignal ~= nil
                    end
                    local function pressNote(button)
                        if replicatesignal then
                            pcall(replicatesignal, button.MouseButton1Down)
                        end
                        if firesignal then
                            pcall(firesignal, button.MouseButton1Down)
                        end
                    end
                    local function armBard(bardGui)
                        local c = safeConnect(bardGui.ChildAdded, function(
                            child
                        )
                            if not (Toggles.AutoBard and Toggles.AutoBard.Value) or not canSignal() then
                                return
                            end
                            if child:IsA('ImageButton') and child.Name == 'Button' then
                                child.Parent.Enabled = true

                                task.wait(0.9 + (math.random(3, 11) / 100))
                                pressNote(child)
                            end
                        end)

                        if c then
                            table.insert(bardConns, c)
                        end
                    end
                    local function setupBard()
                        clearBardConns()

                        if not canSignal() then
                            notify(
[[Auto Bard needs replicatesignal or firesignal (unsupported executor)]])

                            return
                        end

                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                        if not pg then
                            return
                        end

                        local existing = pg:FindFirstChild('BardGui')

                        if existing then
                            armBard(existing)
                        end

                        local watch = safeConnect(pg.ChildAdded, function(
                            child
                        )
                            if child.Name == 'BardGui' and Toggles.AutoBard and Toggles.AutoBard.Value then
                                armBard(child)
                            end
                        end)

                        if watch then
                            table.insert(bardConns, watch)
                        end
                    end

                    featureMaid:Give(clearBardConns)

                    ctx.State.autoBardSetup = setupBard
                    ctx.State.autoBardClear = clearBardConns

                    local AUDIO_EXT = {
                        mp3 = true,
                        ogg = true,
                        wav = true,
                        flac = true,
                    }
                    local custom, playing
                    local songConns = {}

                    local function dropSongConns()
                        for _, c in songConns do
                            pcall(function()
                                c:Disconnect()
                            end)
                        end

                        table.clear(songConns)
                    end
                    local function bardMap()
                        local raw = Options.BardMusicMap and Options.BardMusicMap.Value or ''
                        local ok, map = pcall(HttpService.JSONDecode, HttpService, raw ~= '' and raw or '{}')

                        return (ok and type(map) == 'table') and map or {}
                    end
                    local function songOf(tool)
                        local activator = tool:IsA('Tool') and tool:FindFirstChild('Activator')
                        local s = activator and activator:FindFirstChild('Song')

                        return (s and s:IsA('Sound')) and s or nil
                    end

                    local learnedSongs = {}

                    local function isSongTool(tool)
                        return tool:IsA('Tool') and (tool:FindFirstChild('Song') ~= nil or learnedSongs[tool.Name] or songOf(tool) ~= nil)
                    end
                    local function songTools()
                        local out = {}

                        for _, container in {
                            LocalPlayer.Character,
                            LocalPlayer:FindFirstChildOfClass('Backpack'),
                        }do
                            for _, tool in container and container:GetChildren() or {}do
                                if isSongTool(tool) then
                                    table.insert(out, tool)
                                end
                            end
                        end

                        return out
                    end
                    local function ownedSongs()
                        local names, seen = {}, {}

                        for _, tool in songTools()do
                            if not seen[tool.Name] then
                                seen[tool.Name] = true

                                table.insert(names, tool.Name)
                            end
                        end
                        for name in bardMap()do
                            if not seen[name] then
                                seen[name] = true

                                table.insert(names, name)
                            end
                        end

                        table.sort(names)

                        return names
                    end
                    local function musicFiles()
                        Paths.ensure(Paths.BARD)

                        local out = {}
                        local ok, list = pcall(function()
                            return listfiles(Paths.BARD)
                        end)

                        for _, path in (ok and type(list) == 'table') and list or {}do
                            local name = tostring(path):match('[^/\\]+$')
                            local ext = name and name:match('%.(%w+)$')

                            if ext and AUDIO_EXT[ext:lower()] then
                                table.insert(out, name)
                            end
                        end

                        table.sort(out)

                        return out
                    end
                    local function songName(sound)
                        for _, tool in songTools()do
                            local own = songOf(tool)

                            if own and own.SoundId == sound.SoundId then
                                return tool.Name
                            end
                        end

                        local held = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Tool')

                        return held and held.Name
                    end
                    local function stopCustom()
                        dropSongConns()

                        if playing and playing.sound.Parent then
                            playing.sound.Volume = playing.volume
                        end

                        playing = nil

                        if custom then
                            custom:Stop()
                        end
                    end
                    local function startCustom(sound)
                        local name = songName(sound)

                        if name then
                            learnedSongs[name] = true
                        end
                        if not (Toggles.CustomBardMusic and Toggles.CustomBardMusic.Value) then
                            return
                        end

                        local file = name and bardMap()[name]

                        if type(file) ~= 'string' or file == '' then
                            return
                        end

                        local asset
                        local id = file:match('^id:(%d+)$')

                        if id then
                            asset = 'rbxassetid://' .. id
                        else
                            local path = Paths.BARD .. '/' .. file

                            if not (isfile and isfile(path)) then
                                notify(file .. ' is missing from workspace/' .. Paths.BARD)

                                return
                            end

                            local ok, loaded = pcall(getcustomasset, path)

                            if not ok then
                                notify('Could not load ' .. file)

                                return
                            end

                            asset = loaded
                        end

                        stopCustom()

                        if not (custom and custom.Parent) then
                            custom = Instance.new('Sound')
                            custom.Name = 'SentinelBard'
                            custom.Looped = true
                            custom.Parent = Services:Get('SoundService')
                        end

                        playing = {
                            sound = sound,
                            volume = sound.Volume,
                        }
                        sound.Volume = 0

                        table.insert(songConns, sound:GetPropertyChangedSignal('Volume'):Connect(function(
                        )
                            if playing and playing.sound == sound and sound.Volume ~= 0 then
                                sound.Volume = 0
                            end
                        end))
                        table.insert(songConns, sound:GetPropertyChangedSignal('Playing'):Connect(function(
                        )
                            if not sound.Playing then
                                stopCustom()
                            end
                        end))
                        table.insert(songConns, sound.AncestryChanged:Connect(function(
                        )
                            if not sound:IsDescendantOf(game) then
                                stopCustom()
                            end
                        end))

                        custom.SoundId = asset
                        custom.Volume = (Options.BardMusicVolume and Options.BardMusicVolume.Value) or 1
                        custom.TimePosition = 0

                        custom:Play()
                    end
                    local function currentSong()
                        local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
                        local s = root and root:FindFirstChild('Song')

                        return (s and s:IsA('Sound') and s.Playing) and s or nil
                    end
                    local function reapply()
                        local s = (playing and playing.sound) or currentSong()

                        stopCustom()

                        if s and s.Playing then
                            startCustom(s)
                        end
                    end

                    local rootConn

                    local function watchRoot(char)
                        if rootConn then
                            rootConn:Disconnect()

                            rootConn = nil
                        end

                        stopCustom()

                        local root = char and char:WaitForChild('HumanoidRootPart', 10)

                        if not root or LocalPlayer.Character ~= char then
                            return
                        end

                        rootConn = root.ChildAdded:Connect(function(child)
                            if child.Name == 'Song' and child:IsA('Sound') then
                                task.defer(startCustom, child)
                            end
                        end)
                    end

                    task.spawn(watchRoot, LocalPlayer.Character)
                    featureMaid:Give(LocalPlayer.CharacterAdded:Connect(watchRoot))
                    featureMaid:Give(function()
                        if rootConn then
                            rootConn:Disconnect()
                        end

                        stopCustom()

                        if custom then
                            custom:Destroy()
                        end
                    end)

                    ctx.State.bardMusic = {
                        songs = ownedSongs,
                        files = musicFiles,
                        map = bardMap,
                        apply = reapply,
                        stop = stopCustom,
                        setVolume = function(v)
                            if custom then
                                custom.Volume = v
                            end
                        end,
                    }
                end
                do
                    local CraftBox = Automation:AddRightGroupbox('Auto Crafting')
                    local autoPotActive = false
                    local autoCraftActive = false

                    local function grabStation(stationType)
                        local char = LocalPlayer.Character

                        if not (char and char:FindFirstChild('HumanoidRootPart')) then
                            return nil
                        end

                        local stations = Workspace:FindFirstChild('Stations')

                        if not stations then
                            return nil
                        end

                        local hrp = char.HumanoidRootPart

                        for _, v in stations:GetChildren()do
                            local timer = v:FindFirstChild('Timer')

                            if timer and (timer.Position - hrp.Position).Magnitude <= 15 and string.find(v.Name, stationType) then
                                return v
                            end
                        end

                        return nil
                    end
                    local function hasMaterials(recipeSet, item)
                        local recipe = recipeSet[item]

                        if not recipe then
                            return false
                        end

                        local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')

                        if not backpack then
                            return false
                        end

                        local count = setmetatable({}, {
                            __index = function()
                                return 0
                            end,
                        })

                        for _, v in backpack:GetChildren()do
                            if recipe[v.Name] then
                                local quantity = v:FindFirstChild('Quantity')

                                count[v.Name] = count[v.Name] + (quantity and quantity.Value or 1)
                            end
                        end
                        for ingredient, needed in recipe do
                            if count[ingredient] < needed then
                                return false
                            end
                        end

                        return recipe
                    end
                    local function craftDelay()
                        local opt = Options.AutoCraftDelay and Options.AutoCraftDelay.Value

                        if opt and opt > 0 then
                            return opt
                        end

                        return randomWait(true)
                    end
                    local function settleTime()
                        return math.clamp(0.4 + getPing() * 3 / 1000, 0.75, 3)
                    end

                    local craftVim = nil

                    local function clickAt(part)
                        if not craftVim then
                            local ok, created = pcall(Instance.new, 'VirtualInputManager')

                            craftVim = ok and created or nil
                        end

                        local camera = Workspace.CurrentCamera

                        if not (craftVim and camera) then
                            return false
                        end

                        local point, onScreen = camera:WorldToViewportPoint(part.Position)
                        local x, y = point.X, point.Y

                        if not onScreen then
                            x, y = camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2
                        end

                        local previous = UserInputService:GetMouseLocation()

                        craftVim:SendMouseButtonEvent(x, y, 0, true, game, 1)
                        task.wait(0.05)
                        craftVim:SendMouseButtonEvent(x, y, 0, false, game, 1)

                        return previous
                    end

                    local quickMouseBack = true

                    local function moveMouseBack(previous)
                        if craftVim and previous then
                            pcall(craftVim.SendMouseMoveEvent, craftVim, previous.X, previous.Y, game)
                        end
                    end
                    local function waitContents(station, done, timeout)
                        local deadline = os.clock() + timeout

                        while not unloaded and os.clock() < deadline do
                            if done(station.Contents.Value) then
                                return true
                            end

                            task.wait()
                        end

                        return done(station.Contents.Value)
                    end
                    local function isEmpty(value)
                        return value == '[]'
                    end
                    local function emptyStation(station, part)
                        for _ = 1, STATION_TRIES do
                            if unloaded or isEmpty(station.Contents.Value) then
                                break
                            end

                            fireclickdetector(station[part].ClickEmpty)
                            waitContents(station, isEmpty, settleTime())
                        end

                        return isEmpty(station.Contents.Value)
                    end
                    local function addOneIngredient(
                        station,
                        part,
                        name,
                        active,
                        keepHeld
                    )
                        local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
                        local char = LocalPlayer.Character
                        local held = char and char:FindFirstChild(name)
                        local tool = if held and held:IsA('Tool')then held else backpack and char and backpack:FindFirstChild(name)

                        if not tool then
                            return false
                        end

                        local remote = tool:FindFirstChildWhichIsA('RemoteEvent')

                        if remote and tool.Parent ~= char then
                            task.wait(randomWait(true))
                        end
                        if tool.Parent ~= char then
                            for _ = 1, STATION_TRIES do
                                tool.Parent = char

                                if tool.Parent == char then
                                    break
                                end

                                task.wait(randomWait(true))
                            end
                        end
                        if tool.Parent ~= char then
                            return false
                        end
                        if not remote then
                            task.wait(math.clamp(0.1 + getPing() / 1000, 0.15, 0.6))
                        end

                        local landed = false
                        local mouseWas = nil

                        for try = 1, STATION_TRIES do
                            if not active() then
                                break
                            end

                            local before = station.Contents.Value
                            local early = false

                            if remote then
                                remote:FireServer(station[part].CFrame, station[part])
                            else
                                local previous = clickAt(station[part])

                                mouseWas = mouseWas or previous
                                early = quickMouseBack and try == 1

                                if early then
                                    task.wait(math.max(MOUSE_BACK_AFTER, getPing() / 2000 + 0.05))
                                    moveMouseBack(mouseWas)
                                end
                            end

                            landed = waitContents(station, function(value)
                                return value ~= before
                            end, settleTime())

                            if landed or unloaded then
                                break
                            end
                            if early then
                                quickMouseBack = false
                            end
                        end

                        moveMouseBack(mouseWas)

                        if not (keepHeld and landed) and tool.Parent == char and backpack.Parent then
                            tool.Parent = backpack
                        end

                        return landed
                    end
                    local function contentsMatch(value, items)
                        local ok, list = pcall(HttpService.JSONDecode, HttpService, value)

                        if not (ok and type(list) == 'table') then
                            return true
                        end

                        local held = {}

                        for _, name in list do
                            held[name] = (held[name] or 0) + 1
                        end
                        for name, count in items do
                            if held[name] ~= count then
                                return false
                            end

                            held[name] = nil
                        end

                        return next(held) == nil
                    end
                    local function skillKey(name)
                        return (tostring(name):lower():gsub('[^%w]', ''))
                    end
                    local function hasSkill(name)
                        local wanted = skillKey(name)

                        for _, holder in {
                            LocalPlayer:FindFirstChildOfClass('Backpack'),
                            LocalPlayer.Character,
                        }do
                            for _, item in holder and holder:GetChildren() or {}do
                                if skillKey(item.Name) == wanted then
                                    return true
                                end
                            end
                        end

                        return false
                    end
                    local function countsBrews()
                        return hasSkill('Double Craft') and not hasSkill('Snake Blood')
                    end
                    local function countItem(name)
                        local total = 0

                        for _, holder in {
                            LocalPlayer:FindFirstChildOfClass('Backpack'),
                            LocalPlayer.Character,
                        }do
                            for _, item in holder and holder:GetChildren() or {}do
                                if item.Name == name then
                                    local quantity = item:FindFirstChild('Quantity')

                                    total += quantity and quantity.Value or 1
                                end
                            end
                        end

                        return total
                    end
                    local function brewOnce(items, station, parts, active)
                        if not emptyStation(station, parts.empty) then
                            return false, 'the station would not empty'
                        end

                        for name, count in items do
                            for index = 1, count do
                                if not active() then
                                    return false, 'stopped'
                                end
                                if not addOneIngredient(station, parts.add, name, active, index < count) then
                                    return false, active() and (name .. ' never went in') or 'stopped'
                                end
                            end
                        end

                        if parts.settle then
                            task.wait(parts.settle)
                        end
                        if not contentsMatch(station.Contents.Value, items) then
                            return false, 'the station held ' .. station.Contents.Value .. ' instead of the recipe'
                        end

                        for _ = 1, STATION_TRIES do
                            if not active() then
                                return false, 'stopped'
                            end
                            if isEmpty(station.Contents.Value) then
                                break
                            end

                            fireclickdetector(station[parts.concoct].ClickConcoct)
                            waitContents(station, isEmpty, settleTime() + CONCOCT_EXTRA)
                        end

                        if not isEmpty(station.Contents.Value) then
                            return false, 'it never concocted'
                        end

                        return true
                    end
                    local function craft(
                        stationType,
                        itemToCraft,
                        limit,
                        alive
                    )
                        if not fireclickdetector then
                            notify(
[[Auto Crafting needs fireclickdetector (unsupported executor)]])

                            return false
                        end
                        if not LocalPlayer.Character then
                            return false
                        end
                        if not (autoPotActive or autoCraftActive) then
                            return false
                        end

                        local station = grabStation(stationType)
                        local recipeSet = stationType == 'Alchemy' and POTIONS or WEAPONS
                        local items = hasMaterials(recipeSet, itemToCraft)

                        if not station then
                            notify(stationType == 'Alchemy' and 'You must be near a cauldron!' or 'You must be near a smithing station!')

                            return false
                        end
                        if not items then
                            notify('Some ingredients are missing!')

                            return false
                        end

                        local alchemy = stationType == 'Alchemy'
                        local parts = alchemy and ALCHEMY_PARTS or SMITHING_PARTS
                        local made, brews, failed = 0, 0, false
                        local startCount = limit and countItem(itemToCraft)
                        local byBrews = limit and alchemy and countsBrews()

                        local function active()
                            return not unloaded and (if alchemy then autoPotActive else autoCraftActive) and not (alive and not alive())
                        end

                        repeat
                            if not active() then
                                break
                            end

                            local ok, why = brewOnce(items, station, parts, active)

                            if not ok then
                                if why ~= 'stopped' then
                                    failed = true

                                    notify(string.format('Crafting stopped: %s', why))
                                end

                                break
                            end

                            brews += 1

                            made = brews

                            if byBrews then
                                if brews >= limit then
                                    break
                                end
                            elseif limit then
                                local deadline = os.clock() + settleTime()

                                while countItem(itemToCraft) - startCount < brews and os.clock() < deadline and not unloaded do
                                    task.wait()
                                end

                                task.wait(OUTPUT_SETTLE)

                                made = math.max(countItem(itemToCraft) - startCount, brews)

                                if made >= limit then
                                    break
                                end
                            end

                            items = hasMaterials(recipeSet, itemToCraft)

                            task.wait(craftDelay())
                        until not items or unloaded

                        return not failed, made, byBrews and 'brews' or nil
                    end

                    ctx.State.craft = function(stationType, item, limit, alive)
                        if stationType == 'Alchemy' then
                            autoPotActive = true
                        else
                            autoCraftActive = true
                        end

                        local ok, made, unit = craft(stationType, item, limit, alive)

                        autoPotActive = false
                        autoCraftActive = false

                        return ok, made or 0, unit
                    end
                    ctx.State.hasMaterials = hasMaterials
                    ctx.State.potionRecipes = POTIONS
                    ctx.State.potionNames = REALM_POTIONS
                    ctx.State.weaponRecipes = WEAPONS
                    ctx.State.weaponNames = WEAPON_ORDER

                    CraftBox:AddDropdown('PotionType', {
                        Text = 'Potion',
                        Values = REALM_POTIONS,
                        Default = REALM_POTIONS[1],
                    })
                    CraftBox:AddToggle('AutoPotion', {
                        Text = 'Auto Potion',
                        Tooltip = 'Needs a cauldron nearby',
                        Default = false,
                        Callback = function(on)
                            autoPotActive = on

                            if not on then
                                return
                            end

                            task.spawn(function()
                                while autoPotActive and not unloaded do
                                    if not craft('Alchemy', Options.PotionType.Value) then
                                        autoPotActive = false

                                        if Toggles.AutoPotion then
                                            Toggles.AutoPotion:SetValue(false)
                                        end

                                        break
                                    end
                                end
                            end)
                        end,
                    })
                    CraftBox:AddDropdown('WeaponType', {
                        Text = 'Weapon',
                        Values = WEAPON_ORDER,
                        Default = 'Mythril Dagger',
                    })
                    CraftBox:AddToggle('AutoCraft', {
                        Text = 'Auto Craft',
                        Tooltip = 'Needs a smithing station nearby',
                        Default = false,
                        Callback = function(on)
                            autoCraftActive = on

                            if not on then
                                return
                            end

                            task.spawn(function()
                                while autoCraftActive and not unloaded do
                                    if not craft('Smithing', Options.WeaponType.Value) then
                                        autoCraftActive = false

                                        if Toggles.AutoCraft then
                                            Toggles.AutoCraft:SetValue(false)
                                        end

                                        break
                                    end
                                end
                            end)
                        end,
                    })
                    CraftBox:AddSlider('AutoCraftDelay', {
                        Text = 'Craft Delay',
                        Default = 0.25,
                        Min = 0.1,
                        Max = 5,
                        Rounding = 2,
                        Suffix = 's',
                    })
                    featureMaid:Give(function()
                        autoPotActive = false
                        autoCraftActive = false
                    end)
                end
                do
                    local ManaBox = Automation:AddRightGroupbox('Mana & Training')

                    ManaBox:AddToggle('AutoCharge', {
                        Text = 'Auto Mana Charge',
                        Default = false,
                    })
                    ManaBox:AddSlider('AutoChargeThreshold', {
                        Text = 'Charge To',
                        Default = 100,
                        Min = 1,
                        Max = 100,
                        Rounding = 0,
                        Suffix = '%',
                    })
                    ManaBox:AddToggle('SnapTrain', {
                        Text = 'Snap Train',
                        Tooltip = 'Casts your held spell to train it',
                        Default = false,
                    })
                    ManaBox:AddToggle('TrainClimb', {
                        Text = 'Train Climb',
                        Default = false,
                    })

                    local function screenCounter(title, y)
                        local counter = {count = 0}
                        local gui, label

                        ctx.Maid:Give(function()
                            if gui then
                                gui:Destroy()
                            end
                        end)

                        function counter.show(on)
                            if on and not gui then
                                gui, label = Gui.notice(y)
                            end
                            if label then
                                label.Text = string.format('%s count: %d', title, counter.count)
                                label.Visible = on
                            end
                        end

                        return counter
                    end

                    local tespians = screenCounter('Tespians', 50)

                    do
                        local maskMaid = Maid.new()

                        featureMaid:Give(maskMaid)

                        local maskRunning = false
                        local talk
                        local lootUntil = 0

                        local function onEffect(kind, text)
                            if kind ~= 'notification' or type(text) ~= 'string' or os.clock() > lootUntil then
                                return
                            end

                            local path = Paths.CACHE .. '/scarymask/' .. LocalPlayer.UserId .. '.log'
                            local line = os.date('[%Y-%m-%d %H:%M:%S] ') .. LocalPlayer.Name .. ': ' .. text .. '\n'

                            pcall(function()
                                Paths.ensureFor(path)

                                if appendfile then
                                    appendfile(path, line)
                                else
                                    writefile(path, (isfile(path) and readfile(path) or '') .. line)
                                end
                            end)
                        end
                        local function maskTool(holder)
                            local found = holder and holder:FindFirstChild('Scary Mask')

                            return found and found:IsA('Tool') and found or nil
                        end
                        local function houseInReach(hrp)
                            local npcs = Workspace:FindFirstChild('NPCs')

                            if not npcs then
                                return nil
                            end

                            local best, bestDist

                            for _, house in npcs:GetChildren()do
                                local root = house.Name:find('^HalloweenHouse') and house:FindFirstChild('HumanoidRootPart')
                                local cd = root and root:FindFirstChild('ClickDetector')

                                if cd then
                                    local dist = (root.Position - hrp.Position).Magnitude

                                    if dist <= cd.MaxActivationDistance and (not bestDist or dist < bestDist) then
                                        best, bestDist = cd, dist
                                    end
                                end
                            end

                            return best
                        end
                        local function onLine(remote, data)
                            local t = talk

                            if not t or t.over or type(data) ~= 'table' or (data.choices == nil and data.speaker == nil) then
                                return
                            end
                            if t.remote and remote ~= t.remote then
                                return
                            end

                            t.remote = remote

                            local choices = data.choices
                            local offered = {}

                            for _, choice in type(choices) == 'table' and choices or {}do
                                table.insert(offered, tostring(choice))
                            end

                            Debug.log('scarymask', string.format('%s: %s [%s]', tostring(data.speaker), tostring(data.msg), table.concat(offered, ' | ')))

                            if choices and #choices > 0 then
                                if table.find(choices, 'Trick or treat?') then
                                    if not t.char:FindFirstChild('HalloweenMask') then
                                        pcall(function()
                                            t.hum:EquipTool(t.mask)
                                        end)
                                        task.wait(0.02 + math.random() * 0.28)

                                        local wornBy, retryAt = os.clock() + 3, 0

                                        while not t.over and not t.char:FindFirstChild('HalloweenMask') and os.clock() < wornBy do
                                            if os.clock() >= retryAt then
                                                retryAt = os.clock() + 0.5

                                                pcall(function()
                                                    if t.mask.Parent ~= t.char then
                                                        t.hum:EquipTool(t.mask)
                                                    else
                                                        t.mask:Activate()
                                                    end
                                                end)
                                            end

                                            task.wait()
                                        end

                                        if t.over then
                                            return
                                        end
                                        if not t.char:FindFirstChild('HalloweenMask') then
                                            Debug.log('scarymask', 'the mask never went on, leaving')

                                            t.over = true

                                            return
                                        end
                                    end

                                    task.wait(0.05)

                                    local deadline = os.clock() + 3

                                    while not t.over and os.clock() < deadline do
                                        remote:FireServer({
                                            choice = 'Trick or treat?',
                                        })
                                        task.wait()
                                    end
                                elseif table.find(choices, '...') then
                                    remote:FireServer({
                                        choice = '...',
                                    })
                                else
                                    t.over = true
                                end
                            else
                                t.over = true
                            end
                        end
                        local function autoScaryMask()
                            if maskRunning then
                                return
                            end

                            maskRunning = true

                            local requests = ReplicatedStorage:FindFirstChild('Requests')

                            for _, remote in requests and requests:GetChildren() or {}do
                                if remote:IsA('RemoteEvent') then
                                    maskMaid:Connect(remote.OnClientEvent, function(
                                        data,
                                        ...
                                    )
                                        if remote.Name == 'DirectClientEffect' then
                                            onEffect(data, ...)
                                        else
                                            onLine(remote, data)
                                        end
                                    end)
                                end
                            end

                            while not unloaded and Toggles.AutoScaryMask.Value do
                                local char = LocalPlayer.Character
                                local hrp = char and char:FindFirstChild('HumanoidRootPart')
                                local hum = char and char:FindFirstChildOfClass('Humanoid')
                                local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
                                local mask = maskTool(backpack) or maskTool(char)
                                local cd = hrp and hum and mask and houseInReach(hrp)

                                if not cd then
                                    task.wait(0.25)

                                    continue
                                end
                                if char:FindFirstChild('InDialogue') then
                                    Dialogue.close(2)
                                    task.wait(0.25)

                                    continue
                                end

                                local t = {
                                    hum = hum,
                                    mask = mask,
                                    char = char,
                                }

                                talk = t
                                lootUntil = math.huge

                                fireclickdetector(cd)

                                local deadline = os.clock() + 8

                                while not t.over and os.clock() < deadline and not unloaded and Toggles.AutoScaryMask.Value do
                                    task.wait()
                                end

                                Debug.log('scarymask', t.over and 'talk over, exiting' or os.clock() >= deadline and 'no reply from the house in 8s, exiting' or 'stopped mid talk, exiting')

                                t.over = true
                                talk = nil

                                local exitBy = os.clock() + 3

                                while t.remote and char:FindFirstChild('InDialogue') and os.clock() < exitBy do
                                    t.remote:FireServer({exit = true})

                                    local sentAt = os.clock()

                                    while char:FindFirstChild('InDialogue') and os.clock() - sentAt < 0.8 do
                                        task.wait()
                                    end
                                end

                                if char:FindFirstChild('InDialogue') then
                                    Dialogue.close(2)
                                end

                                pcall(function()
                                    hum:UnequipTools()
                                end)

                                lootUntil = os.clock() + 3

                                task.wait(0.3 + math.random() * 1.2)
                            end

                            maskMaid:DoCleaning()

                            maskRunning = false
                        end

                        ManaBox:AddToggle('AutoScaryMask', {
                            Text = 'Auto Scary Mask',
                            Tooltip = 'Trick or treats at the house you stand by',
                            Default = false,
                            Callback = function(on)
                                if on then
                                    task.spawn(autoScaryMask)
                                end
                            end,
                        })
                    end

                    ManaBox:AddToggle('LoopOrderly', {
                        Text = 'Loop Gain Orderly',
                        Tooltip = Gate.risky('uses Tespian Elixirs to farm Orderly'),
                        Default = false,
                        Callback = function(on)
                            if on then
                                tespians.count = 0
                            end

                            tespians.show(on)
                        end,
                    })
                    Gate.mark(ctx, 'Risky', 'LoopOrderly')

                    do
                        local candyRunning = false
                        local candies = screenCounter('Candies', 100)

                        local function loopCandy()
                            if candyRunning then
                                return
                            end

                            candyRunning = true

                            while not unloaded and Toggles.LoopCandy and Toggles.LoopCandy.Value do
                                task.wait()

                                if Menu.startMenu() then
                                    Menu.clickPlay()

                                    continue
                                end

                                local char = LocalPlayer.Character
                                local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
                                local pick = Options.CandiesDropDown and Options.CandiesDropDown.Value
                                local tool = backpack and type(pick) == 'string' and backpack:FindFirstChild(pick:match('^(.-)%(') or pick)
                                local hum = char and char:FindFirstChildOfClass('Humanoid')

                                if tool and hum and char:FindFirstChild('HumanoidRootPart') and not CollectionService:HasTag(char, 'Danger') then
                                    hum:EquipTool(tool)
                                    task.wait()
                                    tool:Activate()

                                    if char.Parent then
                                        task.wait(1.05)

                                        local rtm = Remotes.requestRemote('ReturnToMenu')

                                        if rtm then
                                            task.spawn(function()
                                                pcall(rtm.InvokeServer, rtm)
                                            end)
                                        end
                                    end

                                    candies.count += 1

                                    candies.show(true)
                                end
                            end

                            candyRunning = false

                            candies.show(false)
                        end

                        ManaBox:AddToggle('LoopCandy', {
                            Text = 'Loop Candy',
                            Tooltip = Gate.risky('eats the picked candy over and over'),
                            Default = false,
                            Callback = function(on)
                                if on then
                                    candies.count = 0

                                    candies.show(true)
                                    task.spawn(loopCandy)
                                else
                                    candies.show(false)
                                end
                            end,
                        })
                        Gate.mark(ctx, 'Risky', 'LoopCandy')
                        ManaBox:AddDropdown('CandiesDropDown', {
                            Text = 'Candies List',
                            Values = {
                                'Red Candy(Sword XP)',
                                'Blue Candy(Spear XP)',
                                'Green Candy(Dagger XP)',
                                'Orange Candy(Fist XP)',
                                'White Candy(Orderly)',
                                'Black Candy(Chaotic)',
                            },
                            Default = 1,
                            Multi = false,
                        })
                    end

                    if not (hookfunction or Remotes.keyHandlerEnabled()) then
                        ManaBox:AddLabel('Mana engine needs hookfunction or KeyHandler')
                    else
                        local mana_remote, manaMode
                        local vimInstance

                        local function getVim()
                            if not vimInstance then
                                local ok, v = pcall(function()
                                    return Instance.new('VirtualInputManager')
                                end)

                                vimInstance = ok and v or nil
                            end

                            return vimInstance
                        end

                        local holdingCharge = false

                        local function pressChargeKey(down)
                            local vim = getVim()

                            if not vim then
                                return false
                            end

                            local ok = pcall(function()
                                vim:SendKeyEvent(down, Enum.KeyCode.G, false, game)
                            end)

                            return ok
                        end
                        local function releaseCharge()
                            if holdingCharge then
                                pressChargeKey(false)

                                holdingCharge = false
                            end
                        end
                        local function chargeMana()
                            if mana_remote then
                                if manaMode == 'table' then
                                    mana_remote:FireServer({
                                        math.random(1, 10),
                                        math.random(),
                                    })
                                else
                                    mana_remote:FireServer(true)
                                end

                                return
                            end
                            if not holdingCharge then
                                holdingCharge = pressChargeKey(true)
                            end
                        end
                        local function dechargeMana()
                            if mana_remote then
                                if manaMode == 'table' then
                                    mana_remote:FireServer()
                                else
                                    mana_remote:FireServer(false)
                                end

                                return
                            end

                            releaseCharge()
                        end
                        local function canUseMana()
                            local char = LocalPlayer.Character

                            if not char then
                                return false
                            end

                            for _, blocker in {
                                'Grabbed',
                                'Climbing',
                                'ClimbCoolDown',
                                'ManaStop',
                                'SpellBlocking',
                                'ActiveCast',
                                'Stun',
                            }do
                                if char:FindFirstChild(blocker) then
                                    return false
                                end
                            end

                            if CollectionService:HasTag(char, 'Knocked') or CollectionService:HasTag(char, 'Unconscious') then
                                return false
                            end

                            return true
                        end
                        local function leftClick()
                            local char = LocalPlayer.Character
                            local handler = char and char:FindFirstChild('CharacterHandler')
                            local remotes = handler and handler:FindFirstChild('Remotes')
                            local remote = remotes and remotes:FindFirstChild('LeftClick')

                            if remote then
                                pcall(function()
                                    remote:FireServer({
                                        math.random(1, 10),
                                        tonumber('0.' .. math.random(1e15, 9e15)),
                                    })
                                end)
                            end
                        end

                        local smoothedPing = 0

                        local function chargeWait(base, mult)
                            task.wait(base + (smoothedPing / 1000) * (mult or 1))
                        end
                        local function loopWait(base, mult)
                            task.wait(base + (math.min(smoothedPing, 150) / 2000) * (mult or 1))
                        end
                        local function chargeManaUntil(amount, shouldContinue)
                            local char = LocalPlayer.Character

                            if not char or char:FindFirstChildWhichIsA('ForceField') or not canUseMana() then
                                return
                            end

                            local mana = char:FindFirstChild('Mana')

                            if not mana then
                                return
                            end
                            if char:FindFirstChild('Charge') or holdingCharge then
                                dechargeMana()

                                if not (Toggles.SnapTrain and Toggles.SnapTrain.Value) then
                                    chargeWait(0.2, 1)
                                end
                            end

                            local stallStart, lastMana = tick(), mana.Value

                            while not unloaded and mana.Value < math.clamp(amount, 0, 98) and (not shouldContinue or shouldContinue()) do
                                if mana.Value > lastMana then
                                    stallStart, lastMana = tick(), mana.Value
                                elseif tick() - stallStart > 4 then
                                    break
                                end

                                chargeMana()

                                if Toggles.SnapTrain and Toggles.SnapTrain.Value then
                                    chargeWait(0.03, 0.5)
                                else
                                    chargeWait(0.1, 1.2)
                                end
                            end

                            if char:FindFirstChild('Charge') or holdingCharge then
                                dechargeMana()

                                if not (Toggles.SnapTrain and Toggles.SnapTrain.Value) then
                                    chargeWait(0.3, 1)
                                end
                            end
                        end

                        ctx.State.mana = {
                            chargeUntil = chargeManaUntil,
                            charge = chargeMana,
                            decharge = dechargeMana,
                            canUse = canUseMana,
                            available = function()
                                return mana_remote ~= nil or getVim() ~= nil
                            end,
                            usingKeyPress = function()
                                return mana_remote == nil
                            end,
                        }

                        ctx.Maid:Give(releaseCharge)

                        local function observeMana(remote, ...)
                            if mana_remote then
                                return
                            end

                            local char = LocalPlayer.Character
                            local handler = char and char:FindFirstChild('CharacterHandler')
                            local remotes = handler and handler:FindFirstChild('Remotes')

                            if not (remotes and remote.Parent == remotes) then
                                return
                            end

                            local args = {...}
                            local name = remote.Name

                            if name == 'SetManaChargeState' then
                                mana_remote, manaMode = remote, 'bool'
                            elseif name:match(
[[^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$]]) and #args == 1 and typeof(args[1]) == 'boolean' then
                                mana_remote, manaMode = remote, 'bool'
                            elseif name:sub(1, 4) == 'M0ai' and #args == 1 and typeof(args[1]) == 'table' then
                                local t = args[1]
                                local keys = 0

                                for _ in pairs(t)do
                                    keys += 1
                                end

                                local a, b = t[1], t[2]

                                if keys == 2 and typeof(a) == 'number' and typeof(b) == 'number' and b % 1 ~= 0 then
                                    mana_remote, manaMode = remote, 'table'
                                end
                            end
                        end

                        ctx.State.fireServerObservers = ctx.State.fireServerObservers or {}

                        table.insert(ctx.State.fireServerObservers, observeMana)

                        ctx.State.getRemote = ctx.State.getRemote or Remotes.getRemote

                        local function detectManaRemote(char)
                            mana_remote = nil

                            releaseCharge()

                            if getgenv and getgenv().SentinelNoMana then
                                return
                            end
                            if char:WaitForChild('Humanoid', 5) == nil then
                                return
                            end

                            local handler = char:WaitForChild('CharacterHandler', 5)

                            if not handler then
                                return
                            end
                            if handler:WaitForChild('Remotes', 5) == nil then
                                return
                            end

                            local forcefield = char:FindFirstChildOfClass('ForceField')

                            if forcefield then
                                while not unloaded and forcefield and forcefield:IsDescendantOf(game) do
                                    task.wait(0.5)
                                end
                            end

                            task.wait(0.3)

                            local kr

                            if Remotes.keyHandlerEnabled() then
                                pcall(function()
                                    kr = Remotes.getRemote('SetManaChargeState') or Remotes.getRemote('Charge')
                                end)
                            end
                            if kr then
                                mana_remote = kr
                                manaMode = (tostring(kr.Name):sub(1, 4) == 'M0ai') and 'table' or 'bool'

                                pcall(function()
                                    ctx.State.dialogueRemote = Remotes.getRemote('PostDialogue') or Remotes.getRemote('SendDialogue') or ctx.State.dialogueRemote
                                end)

                                return
                            end
                            if pressChargeKey(true) then
                                task.wait(0.15)
                                pressChargeKey(false)
                                task.wait(0.2)
                            end
                            if not mana_remote then
                                Console.print(
[[[sentinel] mana: no charge remote resolved, holding G instead]])
                            end
                        end

                        task.spawn(function()
                            while not unloaded do
                                smoothedPing = math.clamp((smoothedPing * 0.3) + (getPing() * 0.7), 0, 300)

                                task.wait(0.25)
                            end
                        end)

                        local chargeThread

                        local function applyAutoCharge(character)
                            pcall(task.cancel, chargeThread)

                            chargeThread = task.spawn(function()
                                local mana = character:WaitForChild('Mana', 30)

                                if not mana then
                                    return
                                end

                                local cachedTool = nil

                                while not unloaded do
                                    if Toggles.SnapTrain and Toggles.SnapTrain.Value then
                                        task.wait(0.01)
                                    else
                                        task.wait(randomWait(true))
                                    end
                                    if not LocalPlayer.Character or LocalPlayer.Character ~= character then
                                        break
                                    end

                                    local char = LocalPlayer.Character
                                    local manaVal = mana.Value

                                    if Toggles.SnapTrain and Toggles.SnapTrain.Value then
                                        if Toggles.AutoCharge and Toggles.AutoCharge.Value then
                                            Toggles.AutoCharge:SetValue(false)
                                        end

                                        local tool = char:FindFirstChildOfClass('Tool')

                                        if tool and tool:FindFirstChild('Spell') and not cachedTool then
                                            cachedTool = tool
                                        end
                                        if cachedTool and SPELL_COST[cachedTool.Name] then
                                            local spellData = SPELL_COST[cachedTool.Name][1]
                                            local minCost, maxCost = spellData[1], spellData[2]
                                            local midCost = (minCost + maxCost) / 2
                                            local range = maxCost - minCost
                                            local buffer = math.min(3, math.floor(range / 3))

                                            if buffer < 1 then
                                                buffer = 0
                                            end
                                            if manaVal < (midCost - 1) then
                                                chargeManaUntil(midCost)
                                            end
                                            if manaVal >= (minCost + buffer) and manaVal <= (maxCost - buffer) and not CollectionService:HasTag(char, 'Casting') then
                                                local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')

                                                if char:FindFirstChildOfClass('Tool') ~= cachedTool then
                                                    if cachedTool.Parent == backpack then
                                                        char.Humanoid:EquipTool(cachedTool)
                                                        loopWait(0.01)
                                                    end
                                                end

                                                leftClick()

                                                local timeout = 0

                                                repeat
                                                    task.wait(0.005)

                                                    timeout += 1
                                                until CollectionService:HasTag(char, 'Casting') or timeout > 20

                                                if CollectionService:HasTag(char, 'Casting') then
                                                    char.Humanoid:UnequipTools()

                                                    timeout = 0

                                                    repeat
                                                        task.wait(0.01)

                                                        timeout += 1
                                                    until not CollectionService:HasTag(char, 'Casting') or timeout > 100

                                                    task.wait(randomWait(true))

                                                    if cachedTool.Parent == LocalPlayer:FindFirstChildOfClass('Backpack') then
                                                        char.Humanoid:EquipTool(cachedTool)
                                                    end
                                                end
                                            end
                                        end
                                    else
                                        cachedTool = nil
                                    end
                                    if (Toggles.AutoCharge and Toggles.AutoCharge.Value) and mana_remote and manaVal <= Options.AutoChargeThreshold.Value and not CollectionService:HasTag(char, 'Casting') then
                                        if Toggles.TrainClimb and Toggles.TrainClimb.Value then
                                            Toggles.TrainClimb:SetValue(false)
                                        end

                                        chargeManaUntil(Options.AutoChargeThreshold.Value)
                                    end
                                    if Toggles.TrainClimb and Toggles.TrainClimb.Value then
                                        if Toggles.AutoCharge and Toggles.AutoCharge.Value then
                                            Toggles.AutoCharge:SetValue(false)
                                        end

                                        chargeManaUntil(100)

                                        local vim = getVim()

                                        repeat
                                            if vim then
                                                vim:SendKeyEvent(true, Enum.KeyCode.Space, false, game)
                                                loopWait(0.05)
                                                vim:SendKeyEvent(false, Enum.KeyCode.Space, false, game)
                                                loopWait(0.05)
                                            else
                                                task.wait(0.1)
                                            end
                                        until mana.Value == 0 or not (Toggles.TrainClimb and Toggles.TrainClimb.Value) or unloaded
                                    end
                                end
                            end)
                        end

                        if LocalPlayer.Character then
                            task.spawn(function()
                                detectManaRemote(LocalPlayer.Character)
                            end)
                            applyAutoCharge(LocalPlayer.Character)
                        end

                        featureMaid:Give(LocalPlayer.CharacterAdded:Connect(function(
                            char
                        )
                            task.spawn(function()
                                detectManaRemote(char)
                            end)
                            applyAutoCharge(char)
                        end))
                        task.spawn(function()
                            while not unloaded do
                                task.wait(0.6)

                                local char = LocalPlayer.Character
                                local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')

                                if backpack and char and not CollectionService:HasTag(char, 'Danger') and Toggles.LoopOrderly and Toggles.LoopOrderly.Value then
                                    local elixir = backpack:FindFirstChild('Tespian Elixir')

                                    if elixir then
                                        char.Humanoid:EquipTool(elixir)
                                        task.wait(0.1)

                                        local equipped = char:FindFirstChild('Tespian Elixir')
                                        local remote = equipped and equipped:FindFirstChild('RemoteEvent')

                                        if remote then
                                            remote:FireServer(char.HumanoidRootPart.CFrame, 'Part', 'Self')

                                            tespians.count += 1

                                            tespians.show(Toggles.LoopOrderly.Value)
                                            task.wait(1.5)
                                            Character.kill()

                                            repeat
                                                task.wait(0.5)
                                            until (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('Immortal')) or unloaded
                                        end
                                    end
                                end
                            end
                        end)
                    end
                end
                do
                    ctx.State.healerTab = Automation:AddLeftGroupbox('Healer')

                    local PickupBox = Automation:AddLeftGroupbox('Auto Pickup')
                    local trinketConn, trinketAddConn
                    local trinkets = {}

                    local function isTrinketPart(object)
                        return object.Name == 'Part' and object:FindFirstChild('ID') ~= nil
                    end
                    local function startTrinket()
                        if trinketConn then
                            return
                        end

                        trinkets = {}

                        for _, object in Workspace:GetChildren()do
                            if isTrinketPart(object) then
                                table.insert(trinkets, object)
                            end
                        end

                        trinketAddConn = safeConnect(Workspace.ChildAdded, function(
                            object
                        )
                            if isTrinketPart(object) then
                                table.insert(trinkets, object)
                            end
                        end)

                        local trinketAccum = 0
                        local seen = setmetatable({}, {
                            __mode = 'k',
                        })

                        trinketConn = safeConnect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                            dt
                        )
                            if not LocalPlayer.Character or not fireclickdetector then
                                return
                            end

                            trinketAccum += dt

                            if trinketAccum < 0.1 then
                                return
                            end

                            trinketAccum = 0

                            local identify = ctx.State.identifyTrinket

                            for i = #trinkets, 1, -1 do
                                if not trinkets[i] or not trinkets[i].Parent then
                                    table.remove(trinkets, i)
                                end
                            end

                            for _, object in trinkets do
                                local info = seen[object]

                                if not info then
                                    info = {}
                                    seen[object] = info
                                end

                                local cd = info.cd

                                if not (cd and cd.Parent) then
                                    cd = object:FindFirstChild('ClickDetector', true)
                                    info.cd = cd
                                end
                                if cd then
                                    local distance = LocalPlayer:DistanceFromCharacter(object.CFrame.Position)

                                    if distance > 0 and distance < cd.MaxActivationDistance then
                                        if info.name == nil and identify then
                                            info.name = identify(object)
                                        end
                                        if info.name ~= 'Azael Horn' then
                                            fireclickdetector(cd)
                                        end
                                    end
                                end
                            end
                        end))
                    end
                    local function stopTrinket()
                        if trinketConn then
                            trinketConn:Disconnect()

                            trinketConn = nil
                        end
                        if trinketAddConn then
                            trinketAddConn:Disconnect()

                            trinketAddConn = nil
                        end

                        trinkets = {}
                    end

                    featureMaid:Give(stopTrinket)
                    PickupBox:AddToggle('AutoTrinket', {
                        Text = 'Auto Trinket',
                        Default = false,
                        Callback = function(on)
                            if on then
                                startTrinket()
                            else
                                stopTrinket()
                            end
                        end,
                    }):AddKeyPicker('AutoTrinketKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'Auto Trinket',
                        SyncToggleState = true,
                    })

                    local lootMaid = Maid.new()

                    featureMaid:Give(lootMaid)

                    local looting = false
                    local lootPin = nil
                    local lootButton

                    local function lootTele(target)
                        lootPin = nil

                        local char = LocalPlayer.Character
                        local root = char and char:FindFirstChild('HumanoidRootPart')

                        if not root then
                            return false
                        end

                        local distance = (target - root.Position).Magnitude

                        if distance > LOOT_TELEPORT_CAP then
                            return false
                        end

                        local speed = (Options.LootAreaSpeed and Options.LootAreaSpeed.Value) or 115
                        local duration = math.max(distance / speed, 0.15)
                        local tween = TweenService:Create(root, TweenInfo.new(duration, Enum.EasingStyle.Linear), {
                            CFrame = CFrame.new(target),
                        })

                        lootMaid.tween = function()
                            pcall(function()
                                tween:Cancel()
                            end)
                        end

                        local completed = false

                        tween.Completed:Connect(function()
                            completed = true
                        end)
                        tween:Play()

                        while not completed and looting do
                            task.wait()
                        end

                        if not looting then
                            pcall(function()
                                tween:Cancel()
                            end)

                            return false
                        end

                        lootPin = target

                        task.wait(0.25)

                        return completed
                    end
                    local function inReach(object)
                        local cd = object:FindFirstChild('ClickDetector', true)
                        local distance = LocalPlayer:DistanceFromCharacter(object.CFrame.Position)

                        return cd ~= nil and distance > 0 and distance < cd.MaxActivationDistance, cd
                    end
                    local function grabTrinket(object, others, clicked)
                        local identify = ctx.State.identifyTrinket

                        local function horn(o)
                            return identify ~= nil and identify(o) == 'Azael Horn'
                        end

                        if horn(object) then
                            return
                        end

                        local deadline = tick() + LOOT_GRAB_TIME

                        while looting and object.Parent and tick() < deadline do
                            if not object:FindFirstChild('ClickDetector', true) then
                                return
                            end

                            for i = 0, #others do
                                local item = i == 0 and object or others[i]

                                if item and item.Parent and (i == 0 or not horn(item)) then
                                    local reach, cd = inReach(item)

                                    if reach then
                                        clicked[item] = true

                                        fireclickdetector(cd)
                                    end
                                end
                            end

                            task.wait(0.1)
                        end
                    end
                    local function stopLooting()
                        looting = false
                    end

                    featureMaid:Give(function()
                        stopLooting()
                        Character.reclip(LocalPlayer.Character)
                    end)

                    local function runLootArea()
                        local char = LocalPlayer.Character
                        local root = char and char:FindFirstChild('HumanoidRootPart')
                        local humanoid = char and char:FindFirstChildOfClass('Humanoid')

                        if not root or not humanoid or humanoid.Health <= 0 then
                            Notify.say('Loot Area needs a living character')

                            return
                        end

                        local radius = (Options.LootAreaRadius and Options.LootAreaRadius.Value) or 0
                        local found, from = {}, root.Position
                        local origin = from

                        for _, object in Workspace:GetChildren()do
                            if isTrinketPart(object) and (object.Position - from).Magnitude <= radius then
                                table.insert(found, object)
                            end
                        end

                        if #found == 0 then
                            Notify.say(string.format('Loot Area: nothing within %d studs', radius))

                            return
                        end

                        looting = true

                        if lootButton then
                            lootButton:SetText('Stop')
                        end

                        lootMaid.spawned = Workspace.ChildAdded:Connect(function(
                            object
                        )
                            if looting and isTrinketPart(object) and (object.Position - origin).Magnitude <= radius and not table.find(found, object) then
                                table.insert(found, object)
                            end
                        end)

                        local proximityWas = {
                            notifier = Toggles.ProximityNotifier and Toggles.ProximityNotifier.Value,
                            allies = Toggles.ProximityIgnoreAllies and Toggles.ProximityIgnoreAllies.Value,
                            distance = Options.ProximityDistance and Options.ProximityDistance.Value,
                        }

                        if Toggles.ProximityNotifier then
                            Toggles.ProximityNotifier:SetValue(true)
                        end
                        if Toggles.ProximityIgnoreAllies then
                            Toggles.ProximityIgnoreAllies:SetValue(true)
                        end
                        if Options.ProximityDistance then
                            Options.ProximityDistance:SetValue(1000)
                        end

                        local releaseGuards = ctx.State.holdGuards and ctx.State.holdGuards(LOOT_GUARD) or nil

                        humanoid:SetStateEnabled(5, false)
                        humanoid:ChangeState(3)

                        local function abandon(why)
                            if not looting then
                                return
                            end

                            looting = false
                            lootPin = nil

                            Notify.say('Loot Area: ' .. why)
                        end

                        lootMaid.died = humanoid.Died:Connect(function()
                            abandon('stopped, you died')
                        end)
                        lootMaid.gone = LocalPlayer.CharacterRemoving:Connect(function(
                        )
                            abandon('stopped, lost the character')
                        end)

                        local held = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                        )
                            local c = LocalPlayer.Character
                            local r = c and c:FindFirstChild('HumanoidRootPart')

                            if not r or c ~= char then
                                return
                            end

                            Character.noclip(c, true)

                            if lootPin then
                                r.CFrame = CFrame.new(lootPin)
                                r.AssemblyLinearVelocity = Vector3.zero
                            end
                        end))

                        lootMaid.noclip = held

                        Notify.say(string.format('Loot Area: %d trinket%s in range', #found, #found == 1 and '' or 's'))

                        local clicked = {}
                        local refused = false
                        local swept = pcall(function()
                            while looting and #found > 0 do
                                local bestIdx, bestDist

                                for idx, object in found do
                                    if object.Parent then
                                        local d = (object.Position - from).Magnitude

                                        if not bestDist or d < bestDist then
                                            bestIdx, bestDist = idx, d
                                        end
                                    else
                                        found[idx] = false
                                    end
                                end

                                if not bestIdx then
                                    break
                                end

                                local target = found[bestIdx]

                                table.remove(found, bestIdx)

                                for i = #found, 1, -1 do
                                    if not found[i] then
                                        table.remove(found, i)
                                    end
                                end

                                if target.Parent then
                                    if ctx.State.refreshGuards then
                                        ctx.State.refreshGuards(LOOT_GUARD)
                                    end
                                    if not inReach(target) then
                                        from = target.Position

                                        if not lootTele(target.Position + Vector3.new(0, 3, 0)) then
                                            refused = looting

                                            break
                                        end
                                    end

                                    grabTrinket(target, found, clicked)
                                end
                            end
                        end)

                        if releaseGuards then
                            releaseGuards()
                        end

                        lootPin = nil

                        local endHum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                        if endHum then
                            endHum:SetStateEnabled(5, true)
                            endHum:ChangeState(Enum.HumanoidStateType.Running)
                        end

                        local done = looting and swept

                        looting = false
                        lootMaid.spawned = nil

                        if lootButton then
                            lootButton:SetText('Loot Area')
                        end
                        if Toggles.ProximityNotifier and proximityWas.notifier ~= nil then
                            Toggles.ProximityNotifier:SetValue(proximityWas.notifier)
                        end
                        if Toggles.ProximityIgnoreAllies and proximityWas.allies ~= nil then
                            Toggles.ProximityIgnoreAllies:SetValue(proximityWas.allies)
                        end
                        if Options.ProximityDistance and proximityWas.distance ~= nil then
                            Options.ProximityDistance:SetValue(proximityWas.distance)
                        end

                        local taken = 0

                        for object in clicked do
                            if not object.Parent then
                                taken += 1
                            end
                        end

                        pcall(Character.awaitClear, LOOT_SETTLE, LOOT_SETTLE_MAX)

                        if lootMaid.noclip == held then
                            lootMaid.noclip = nil
                            lootMaid.died = nil
                            lootMaid.gone = nil

                            Character.reclip(LocalPlayer.Character)
                        end
                        if refused then
                            Notify.say('Loot Area: stopped, the next trinket is out of reach')
                        end
                        if done then
                            Notify.say(string.format('Loot Area: picked up %d', taken))
                        end
                    end

                    local ingConn
                    local ingredientFolder, lastFolderScan = nil, 0
                    local activeIngredients = {}
                    local lastCheck, lastPos = 0, nil
                    local ingredientCds = {}
                    local ingredientFireAccum = 0
                    local ingredientMaid = Maid.new()

                    featureMaid:Give(ingredientMaid)

                    local function trackIngredient(object)
                        local cd = object:FindFirstChild('ClickDetector')

                        if not cd or (ctx.State.identifyIngredient and ctx.State.identifyIngredient(object) == 'Blood Thorn') then
                            return
                        end

                        ingredientCds[object] = cd
                    end
                    local function bindIngredientFolder(folder)
                        ingredientMaid:DoCleaning()
                        table.clear(ingredientCds)

                        if not folder then
                            return
                        end

                        for _, object in folder:GetChildren()do
                            trackIngredient(object)
                        end

                        ingredientMaid:Give(folder.ChildAdded:Connect(trackIngredient))
                        ingredientMaid:Give(folder.ChildRemoved:Connect(function(
                            object
                        )
                            ingredientCds[object] = nil
                        end))
                    end

                    local refreshActiveIngredients = BASIL_NO_VIRTUALIZE(function(
                        hrp
                    )
                        local now = tick()

                        if not (ingredientFolder and ingredientFolder.Parent) or now - lastFolderScan > 1 then
                            lastFolderScan = now

                            local found = ctx.State.findIngredientFolder and ctx.State.findIngredientFolder() or nil

                            if found ~= ingredientFolder then
                                ingredientFolder = found

                                bindIngredientFolder(found)
                            end
                        end

                        table.clear(activeIngredients)

                        for object, cd in ingredientCds do
                            if object.Parent then
                                local d = (object.Position - hrp.Position).Magnitude

                                if d > 0 and d < cd.MaxActivationDistance - 2 then
                                    table.insert(activeIngredients, cd)
                                end
                            else
                                ingredientCds[object] = nil
                            end
                        end
                    end)

                    local function startIngredient()
                        if ingConn then
                            return
                        end

                        ingredientFolder, lastFolderScan, lastPos = nil, 0, nil
                        ingredientFireAccum = 0

                        table.clear(activeIngredients)

                        ingConn = safeConnect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                        )
                            local char = LocalPlayer.Character
                            local hrp = char and char:FindFirstChild('HumanoidRootPart')

                            if not hrp or not fireclickdetector then
                                return
                            end

                            local now = tick()
                            local pos = hrp.Position

                            if lastPos == nil or now - lastCheck > 0.2 or (now - lastCheck > 0.1 and (pos - lastPos).Magnitude > 2) then
                                lastCheck, lastPos = now, pos

                                refreshActiveIngredients(hrp)
                            end
                            if now - ingredientFireAccum >= INGREDIENT_FIRE then
                                ingredientFireAccum = now

                                for _, cd in activeIngredients do
                                    fireclickdetector(cd)
                                end
                            end
                        end))
                    end
                    local function stopIngredient()
                        if ingConn then
                            pcall(function()
                                ingConn:Disconnect()
                            end)

                            ingConn = nil
                        end

                        ingredientMaid:DoCleaning()
                        table.clear(ingredientCds)
                        table.clear(activeIngredients)

                        ingredientFolder = nil
                    end

                    featureMaid:Give(stopIngredient)
                    PickupBox:AddToggle('AutoIngredient', {
                        Text = 'Auto Ingredient',
                        Default = false,
                        Callback = function(on)
                            if on then
                                startIngredient()
                            else
                                stopIngredient()
                            end
                        end,
                    }):AddKeyPicker('AutoIngredientKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'Auto Ingredient',
                        SyncToggleState = true,
                    })

                    local weaponMaid = Maid.new()

                    featureMaid:Give(weaponMaid)

                    local weaponItems = {}

                    local function trackWeapon(weapon)
                        local pickup = weapon:FindFirstChild('ClickDetector')

                        if not (pickup and weapon:FindFirstChild('Prop')) then
                            return
                        end

                        local mainPart = weapon:IsA('Model') and weapon:FindFirstChildWhichIsA('BasePart') or weapon

                        if mainPart:IsA('BasePart') then
                            weaponItems[weapon] = {
                                part = mainPart,
                                pickup = pickup,
                                range = pickup.MaxActivationDistance - 2,
                            }
                        end
                    end

                    local weaponGen = 0

                    local function stopWeapon()
                        weaponGen += 1

                        weaponMaid:DoCleaning()
                        table.clear(weaponItems)
                    end

                    featureMaid:Give(stopWeapon)

                    local function startWeapon()
                        stopWeapon()

                        local gen = weaponGen

                        weaponMaid:Give(task.spawn(function()
                            local ok, thrown = pcall(function()
                                return Workspace:FindFirstChild('Thrown') or Workspace:WaitForChild('Thrown', 30)
                            end)

                            if not ok or not thrown or gen ~= weaponGen then
                                return
                            end

                            for _, weapon in thrown:GetChildren()do
                                trackWeapon(weapon)
                            end

                            local added = safeConnect(thrown.ChildAdded, function(
                                weapon
                            )
                                task.delay(1, function()
                                    if weapon.Parent == thrown then
                                        trackWeapon(weapon)
                                    end
                                end)
                            end)
                            local removed = safeConnect(thrown.ChildRemoved, function(
                                weapon
                            )
                                weaponItems[weapon] = nil
                            end)
                            local accum = 0
                            local sweep = safeConnect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                                dt
                            )
                                accum += dt

                                if accum < 0.1 or unloaded or not fireclickdetector then
                                    return
                                end

                                accum = 0

                                local char = LocalPlayer.Character

                                if not (char and char:FindFirstChild('Head')) then
                                    return
                                end

                                for weapon, info in weaponItems do
                                    if weapon.Parent == nil then
                                        weaponItems[weapon] = nil
                                    elseif LocalPlayer:DistanceFromCharacter(info.part.Position) <= info.range then
                                        fireclickdetector(info.pickup)
                                    end
                                end
                            end))

                            for _, conn in {added, removed, sweep}do
                                if conn then
                                    weaponMaid:Give(conn)
                                end
                            end
                        end))
                    end

                    PickupBox:AddToggle('AutoWeapon', {
                        Text = 'Auto Weapon',
                        Default = false,
                        Callback = function(on)
                            if on then
                                startWeapon()
                            else
                                stopWeapon()
                            end
                        end,
                    }):AddKeyPicker('AutoWeaponKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'Auto Weapon',
                        SyncToggleState = true,
                    })

                    local function findTool(names)
                        local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
                        local pools = {
                            backpack,
                            LocalPlayer.Character,
                        }

                        for _, pool in pools do
                            if pool then
                                for _, item in pool:GetChildren()do
                                    if item:IsA('Tool') then
                                        for _, name in names do
                                            if item.Name == name then
                                                return item
                                            end
                                        end
                                    end
                                end
                            end
                        end

                        return nil
                    end
                    local function useTool(tool)
                        local char = LocalPlayer.Character

                        if not (char and tool) then
                            return
                        end

                        local humanoid = char:FindFirstChildOfClass('Humanoid')

                        if not humanoid then
                            return
                        end

                        humanoid:UnequipTools()

                        local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')

                        if backpack and tool.Parent == backpack then
                            humanoid:EquipTool(tool)
                        end
                        if not char:FindFirstChild(tool.Name) then
                            tool.AncestryChanged:Wait()
                        end

                        task.wait(0.025)

                        local charTool = char:FindFirstChild(tool.Name)

                        if charTool then
                            charTool:Activate()
                        end
                    end

                    PickupBox:AddToggle('AutoResurrection', {
                        Text = 'Auto Resurrection',
                        Default = false,
                    })

                    do
                        local okSig, unconsciousSignal = pcall(function()
                            return CollectionService:GetInstanceAddedSignal('Unconscious')
                        end)

                        if okSig and unconsciousSignal then
                            featureMaid:Give(safeConnect(unconsciousSignal, function(
                                instance
                            )
                                if instance == LocalPlayer.Character and Toggles.AutoResurrection and Toggles.AutoResurrection.Value then
                                    task.spawn(function()
                                        task.wait(randomWait())

                                        local tool = findTool({
                                            'Resurrection',
                                            'Dragon Awakening',
                                            'Dragon Resurrection',
                                        })

                                        if tool then
                                            useTool(tool)
                                        end
                                    end)
                                end
                            end))
                        end
                    end

                    PickupBox:AddDivider()

                    local bagConn, bagAddConn, bagRemConn
                    local bags = {}

                    local function isValidBag(object)
                        return object:IsA('BasePart') and object.Name:find('Bag') ~= nil
                    end

                    local bagItems = {
                        names = {},
                        picked = {},
                    }

                    do
                        local saved = Json.read(Paths.BAG_ITEMS)

                        if type(saved) == 'table' then
                            for _, name in type(saved.names) == 'table' and saved.names or {}do
                                table.insert(bagItems.names, tostring(name))
                            end
                            for _, name in type(saved.picked) == 'table' and saved.picked or {}do
                                bagItems.picked[tostring(name)] = true
                            end
                        end
                    end

                    local function saveBagItems()
                        local picked = {}

                        for name in bagItems.picked do
                            table.insert(picked, name)
                        end

                        table.sort(picked)
                        Json.write(Paths.BAG_ITEMS, {
                            names = bagItems.names,
                            picked = picked,
                        })
                    end

