                    local now = os.clock()

                    if now - (seenAt[obj] or -math.huge) < BURST then
                        return
                    end

                    seenAt[obj] = now

                    local mine, why = ownsSound(obj)
                    local where = select(2, pcall(function()
                        return obj:GetFullName()
