                Vector3.new(3223, 142, -2519),
                Vector3.new(3227, 148, -2521),
            }
            local HAND_TO_LILIN = {
                Vector3.new(3225, 142, -2520),
                Vector3.new(3221, 142, -2517),
                Vector3.new(3223, 128, -2518),
            }
            local LILIN_SPOT = Vector3.new(3224, 128, -2516)
            local HAND_SPOT = Vector3.new(3227, 148, -2521)
            local LERASE_DONE = {
                'Why am I still here',
            }
            local HENDRICK_DONE = {
                {
                    exact = 'Mmm...',
                },
            }

            local function skillKey(s)
                return (tostring(s):lower():gsub('[^%w]', ''))
            end
            local function missingFrom(list)
                local have = {}

                for _, pool in {
                    LocalPlayer:FindFirstChildOfClass('Backpack'),
                    LocalPlayer.Character,
                }do
                    if pool then
                        for _, item in pool:GetChildren()do
                            have[skillKey(item.Name)] = true
                        end
                    end
                end

                local missing = {}

                for _, s in list do
                    if not have[skillKey(s)] then
                        table.insert(missing, s)
                    end
                end

                return missing
            end
            local function haveAnyOf(list)
                return #missingFrom(list) < #list
            end
            local function settleForAny(list, seconds)
                local waited = 0
                local limit = seconds or SKILL_SETTLE

                while waited < limit and not (charReady() and haveAnyOf(list)) do
                    task.wait(0.25)

                    waited += 0.25
                end

                return haveAnyOf(list)
            end

            local SERVER_UNSET = {
                [''] = true,
                ['Name Unidentified'] = true,
                ['Unknown Region'] = true,
                ['Unknown'] = true,
            }

            local function readServerStats()
                local name, region = '', ''
                local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                local gui = pg and pg:FindFirstChild('ServerStatsGui')
                local frame = gui and gui:FindFirstChild('Frame')
                local box = frame and frame:FindFirstChild('Stats')

                if box then
                    local sn = box:FindFirstChild('ServerName')

                    if sn then
                        name = sn.Text:match('Server Name: (.+)') or ''
                    end

                    local sr = box:FindFirstChild('ServerRegion')

                    if sr then
                        region = sr.Text:match('Server Region: (.+)') or ''
                    end
                end

                return name, region
            end
            local function serverInfo(settle)
                local deadline = tick() + (settle or 0)
                local name, region = readServerStats()

                while SERVER_UNSET[name] and tick() < deadline do
                    task.wait(0.25)

                    name, region = readServerStats()
                end

                return name ~= '' and name or 'Unknown', region ~= '' and region or 'Unknown'
            end

            local progWebhookUrl = ''
            local ProgHook = Webhook.scoped(function()
                return progWebhookUrl
            end)

            local function footerText()
                if Webhook.config.showUsername then
                    return string.format('Players: %d/23 | %s | Job: %s', #Players:GetPlayers(), LocalPlayer.Name, game.JobId)
                end

                return string.format('Players: %d/23 | Job: %s', #Players:GetPlayers(), game.JobId)
            end
            local function fmtDur(secs)
                secs = math.max(0, math.floor(tonumber(secs) or 0))

                local h, m, s = math.floor(secs / 3600), math.floor((secs % 3600) / 60), secs % 60

                if h > 0 then
                    return string.format('%dh %dm %ds', h, m, s)
                end

                return string.format('%dm %ds', m, s)
            end
            local function iniBlock(rows)
                return '```ini\n' .. table.concat(rows, '\n') .. '\n```'
            end
            local function timeBlock(startClock, kheiClock)
                if not startClock then
                    return iniBlock({
                        '[+] Total  unknown',
                    })
                end

                local now = os.time()
                local rows = {
                    string.format('[+] %-6s %s', 'Total', fmtDur(now - startClock)),
                }

                if kheiClock then
                    table.insert(rows, string.format('[+] %-6s %s', 'Gaia', fmtDur(kheiClock - startClock)))
                    table.insert(rows, string.format('[+] %-6s %s', 'Khei', fmtDur(now - kheiClock)))
                end

                return iniBlock(rows)
            end
            local function silverBlock(startSilver, endSilver)
                local rows = {
                    string.format('[+] %-6s %s', 'Start', startSilver and tostring(startSilver) or 'unknown'),
                    string.format('[+] %-6s %s', 'End', endSilver and tostring(endSilver) or 'unknown'),
                }

                if startSilver and endSilver then
                    local delta = startSilver - endSilver

                    table.insert(rows, string.format('[+] %-6s %s', delta >= 0 and 'Spent' or 'Gained', tostring(math.abs(delta))))
                end

                return iniBlock(rows)
            end
            local function friendly(ctx, p)
                if ctx.State.isFriendly then
                    return ctx.State.isFriendly(p) == true
                end

                return ctx.State.isFriend ~= nil and ctx.State.isFriend(p) == true
            end
            local function rosterLines(ctx, rogueName, origin, radius)
                return Threats.roster(origin, radius, rogueName, function(p)
                    return friendly(ctx, p)
                end)
            end

            local lastSpawnAt = 0

            local function settleAfterSpawn()
                while tick() - lastSpawnAt < 2 do
                    task.wait(0.1)
                end
            end
            local function menuButtonUp()
                local pg = LocalPlayer:FindFirstChild('PlayerGui')
                local gui = pg and pg:FindFirstChild('MenuReturnGui')
                local menu = gui and (gui:FindFirstChild('Menu') or gui:FindFirstChild('Menu', true))

                return menu ~= nil and menu.Visible
            end
            local function waitMenuOut()
                settleAfterSpawn()

                local deadline = tick() + MENU_OUT_WAIT

                while tick() < deadline do
                    if charReady() and menuButtonUp() then
                        return true
                    end

                    task.wait(0.1)
                end

                return false
            end
            local function kheiMenuOut()
                if not waitMenuOut() then
                    return
                end

                local rtm = Remotes.requestRemote('ReturnToMenu')

                if rtm then
                    pcall(function()
                        rtm:InvokeServer()
                    end)
                end
            end

            local HOP_COLOR = 0xe67e22
            local STOP_COLOR = 0xed4245
            local SKIP_COLOR = 0x5865f2
            local INFO_COLOR = 0x57f287

            local function noteEmbed(title, color, description, detail)
                local name, region = serverInfo()
                local fields = {
                    {
                        name = 'Server',
                        value = string.format('`%s`\n`%s`', name, region),
                        inline = true,
                    },
                    {
                        name = 'Job',
                        value = string.format('`%s`', tostring(game.JobId)),
                        inline = true,
                    },
                }

                if detail and #detail > 0 then
                    local header, rows = 'Nearby', detail

                    if #detail > 1 and detail[1]:find('Within', 1, true) then
                        header, rows = (detail[1]:gsub('%*%*', '')), {
                            table.unpack(detail, 2),
                        }
                    end

                    table.insert(fields, {
                        name = header,
                        value = table.concat(rows, '\n'),
                        inline = false,
                    })
                end

                return {
                    title = title,
                    description = description,
                    color = color,
                    fields = fields,
                    footer = {
                        text = footerText(),
                    },
                    timestamp = os.date('!%Y-%m-%dT%H:%M:%SZ'),
                }
            end
            local function hopNote(msg, detail, ping, phase)
                local title = phase and string.format('Serverhop [%s]', tostring(phase)) or 'Serverhop'
                local embed = noteEmbed(title, HOP_COLOR, msg, detail)

                if ping then
                    pcall(ProgHook.embedWith, ping, embed)
                else
                    pcall(ProgHook.embed, embed)
                end
            end
            local function stopNote(msg, detail)
                pcall(ProgHook.embedWith, '@everyone', noteEmbed('Stopped', STOP_COLOR, msg, detail))
            end
            local function haltNote(msg)
                pcall(ProgHook.embed, noteEmbed('Stopped', STOP_COLOR, msg))
            end
            local function skipNote(msg)
                pcall(ProgHook.embed, noteEmbed('Skipped', SKIP_COLOR, msg))
            end

            local skipReason = nil

            local function skipQuiet(msg)
                skipReason = msg
            end
            local function infoNote(title, msg)
                pcall(ProgHook.embed, noteEmbed(title, INFO_COLOR, msg))
            end
            local function manaUnlocked()
                local pg = LocalPlayer:FindFirstChild('PlayerGui')
                local gui = pg and pg:FindFirstChild('StatGui')
                local left = gui and gui:FindFirstChild('LeftContainer')

                return left ~= nil and left.Visible
            end
            local function manaTrained()
                local c = LocalPlayer.Character
                local abilities = c and c:FindFirstChild('ManaAbilities')

                return manaUnlocked() and abilities ~= nil and abilities:FindFirstChild('CanClimb') ~= nil
            end

            local ZOFFSET_ANIM = 'rbxassetid://2986649587'
            local ZOFFSET_FREEZE = 1.7
            local zOffsetTrack, zOffsetChar

            local function zOffsetStart()
                local c = LocalPlayer.Character
                local hum = c and c:FindFirstChildOfClass('Humanoid')
                local animator = hum and hum:FindFirstChildOfClass('Animator')

                if not animator then
                    return
                end
                if not zOffsetTrack or zOffsetChar ~= c then
                    zOffsetChar = c

                    local anim = Make('Animation', {AnimationId = ZOFFSET_ANIM})
                    local ok, t = pcall(function()
                        return animator:LoadAnimation(anim)
                    end)

                    zOffsetTrack = ok and t or nil

                    if zOffsetTrack then
                        zOffsetTrack.Looped = true

                        pcall(function()
                            zOffsetTrack.Priority = Enum.AnimationPriority.Action4
                        end)
                    end
                end
                if zOffsetTrack then
                    zOffsetTrack:Play(0)

                    zOffsetTrack.TimePosition = ZOFFSET_FREEZE

                    zOffsetTrack:AdjustSpeed(0)
                end
            end
            local function zOffsetHold()
                if LocalPlayer.Character ~= zOffsetChar then
                    zOffsetStart()

                    return
                end

                local t = zOffsetTrack

                if not t then
                    return
                end
                if not t.IsPlaying then
                    t:Play(0)

                    t.TimePosition = ZOFFSET_FREEZE

                    t:AdjustSpeed(0)

                    return
                end
                if t.Speed ~= 0 then
                    t:AdjustSpeed(0)
                end
                if math.abs(t.TimePosition - ZOFFSET_FREEZE) > 0.02 then
                    t.TimePosition = ZOFFSET_FREEZE
                end
            end
            local function zOffsetStop()
                if zOffsetTrack then
                    pcall(function()
                        zOffsetTrack:Stop()
                    end)
                end
            end

            return function(ctx)
                sharedState = ctx.State
                ctx.State.offsetStart = zOffsetStart
                ctx.State.offsetHold = zOffsetHold
                ctx.State.offsetStop = zOffsetStop

                local section = ctx.State.progressionTab

                if not section then
                    return
                end

                local Toggles = ctx.Library.Toggles
                local Options = ctx.Library.Options
                local running = false
                local hopCommitted = false
                local proximityGraceUntil = 0
                local pebbleHolders = {}
                local activeTween = {}
                local stopButton
                local startButton
                local guard = Maid.new()

                ctx.Maid:Give(guard)
                ctx.Maid:Give(function()
                    running = false

                    zOffsetStop()
                    restoreTouch()
                    MemStore.remove('progression_active')
                    MemStore.remove('khei_run')
                end)

                local function setStopVisible(v)
                    if stopButton and stopButton.Holder then
                        stopButton.Holder.Visible = v
                    end
                end
                local function setStartVisible(v)
                    if startButton and startButton.Holder then
                        startButton.Holder.Visible = v
                    end
                end
                local function idleUI()
                    setStopVisible(false)
                    setStartVisible(true)
                end

                local state
                local stop
                local handleDanger
                local activePath = {}
                local resumePath = nil
                local dangerBusy = false
                local busy = false
                local savedToggles = {}
                local vim
                local CACHE_DIR = 'sentinel/.cache'
                local HttpService = game:GetService('HttpService')

                local function dbg(fmt, ...)
                    if not Debug.enabled() then
                        return
                    end

                    local ok, str = pcall(string.format, fmt, ...)
                    local line = '[auto-sigil] ' .. (ok and str or tostring(fmt))

                    print(line)
                    Debug.log('auto-sigil', line)
                end
                local function notify(msg)
                    Notify.say(msg)
                end
                local function setBusy(b)
                    busy = b
                end
                local function inDanger()
                    local c = LocalPlayer.Character

                    return c ~= nil and CollectionService:HasTag(c, 'Danger')
                end
                local function playerWithinProximity()
                    local prox = Options.ProgProximity and Options.ProgProximity.Value or 0

                    if prox <= 0 then
                        return false
                    end

                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                    if not hrp then
                        return false
                    end

                    for _, p in Players:GetPlayers()do
                        local ph = p ~= LocalPlayer and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                        if ph and (ph.Position - hrp.Position).Magnitude <= prox then
                            return true
                        end
                    end

                    return false
                end
                local function holdIfUnsafe()
                    while running and inDanger() and playerWithinProximity() do
                        task.wait(0.5)
                    end
                end
                local function stateFile()
                    return CACHE_DIR .. '/' .. tostring(LocalPlayer.UserId) .. '.json'
                end
                local function loadState()
                    local ok, data = pcall(function()
                        if isfile and isfile(stateFile()) then
                            return HttpService:JSONDecode(readfile(stateFile()))
                        end
                    end)
                    local out = (ok and type(data) == 'table') and data or nil
                    local stamps = MemStore.getJSON('prog_stamps')

                    if type(stamps) == 'table' then
                        for key, v in stamps do
                            out = out or {}

                            if out[key] == nil then
                                out[key] = v
                            end
                        end
                    end

                    return out
                end
                local function saveState()
                    if not state then
                        return
                    end

                    MemStore.setJSON('prog_stamps', {
                        startClock = state.startClock,
                        kheiClock = state.kheiClock,
                        startSilver = state.startSilver,
                        runId = state.runId,
                    })
                    pcall(function()
                        if makefolder then
                            pcall(makefolder, 'sentinel')
                            pcall(makefolder, CACHE_DIR)
                        end
                        if writefile then
                            writefile(stateFile(), HttpService:JSONEncode(state))
                        end
                    end)
                end
                local function setPhase(phase, step)
                    if not running then
                        return
                    end

                    state = state or {}
                    state.phase = phase
                    state.step = step or 0

                    saveState()
                    dbg('phase -> %s (step %s)', tostring(phase), tostring(state.step))
                end
                local function hardStop(reason)
                    if not running then
                        dbg('stopped by hand, skipping the kick for: %s', tostring(reason))

                        return
                    end

                    dbg('HARD STOP: %s', tostring(reason))
                    saveState()

                    running = false

                    setStopVisible(false)
                    MemStore.remove('progression_active')
                    BotClaims.release()
                    MemStore.remove('khei_run')
                    MemStore.remove('khei_handoff_servers')
                    guard:DoCleaning()
                    Danger.waitClear()

                    if waitMenuOut() then
                        Menu.returnToMenu()
                    end

                    pcall(Danger.kick, 'auto-sigil: ' .. tostring(reason))
                end
                local function once(key, fn)
                    state = state or {}
                    state.done = state.done or {}

                    if state.done[key] then
                        return
                    end

                    skipReason = nil

                    local ok = fn()

                    if not running then
                        return
                    end
                    if ok == false then
                        state.skips = state.skips or {}

                        local n = (state.skips[key] or 0) + 1

                        state.skips[key] = n

                        saveState()
                        dbg('step %s did not take (attempt %d): %s', key, n, skipReason or 'no reason recorded')

                        if n == SKIP_REPORT_AFTER then
                            skipNote(string.format('%s has not taken after %d tries: %s', key, n, skipReason or 'no reason recorded'))
                        end

                        return
                    end

                    state.done[key] = true

                    if state.skips then
                        state.skips[key] = nil
                    end

                    saveState()
                end
                local function markOrderlyDone()
                    state = state or {}
                    state.done = state.done or {}

                    local changed = not state.done.jagen

                    state.done.jagen = true

                    for _, key in ORDERLY_STEPS do
                        if not state.done[key] then
                            state.done[key] = true
                            changed = true
                        end
                    end

                    if changed then
                        dbg(
[[orderly quests marked done, the Jagen training is already held]])
                        saveState()
                    end
                end

                local resetButton
                local intentionalUntil = 0

                local function intentional()
                    intentionalUntil = tick() + 8
                end
                local function setResetVisible(v)
                    if resetButton and resetButton.Holder then
                        resetButton.Holder.Visible = v
                    end
                end
                local function hasProgress()
                    return (isfile and isfile(stateFile())) or state ~= nil
                end
                local function getRogue(p)
                    local rogue = ctx.State.getRogueName and ctx.State.getRogueName(p)

                    if not rogue or rogue == '' or rogue == 'nil' or rogue == 'Unknown' then
                        rogue = p.DisplayName or p.Name
                    end

                    return rogue
                end
                local function deathKick()
                    if not running then
                        return
                    end

                    running = false

                    if state then
                        state.boundInn = nil
                    end

                    MemStore.remove('progression_active')
                    saveState()

                    local dhrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                    stopNote(string.format('the bot died on **%s**', tostring(state and state.phase or '?')), rosterLines(ctx, getRogue, dhrp and dhrp.Position, 700))
                    waitMenuOut()
                    pcall(Danger.kick, 'auto-sigil: bot died - stopped')
                end
                local function watchAA(character)
                    if not character then
                        return
                    end

                    local seen, firstAt = {}, 0

                    guard.aaWatch = character.ChildAdded:Connect(function(
                        child
                    )
                        if not running or not AA_MARKERS[child.Name] then
                            return
                        end
                        if tick() < intentionalUntil then
                            return
                        end

                        local now = tick()

                        if now - firstAt > 2 then
                            seen, firstAt = {}, now
                        end

                        seen[child.Name] = true

                        local n = 0

                        for _ in seen do
                            n += 1
                        end

                        if n < 3 then
                            return
                        end

                        seen = {}

                        local danger = CollectionService:HasTag(character, 'Danger')

                        intentional()
                        task.spawn(function()
                            local t = 0

                            while t < 15 do
                                intentional()

                                if LocalPlayer.Character and LocalPlayer.Character ~= character then
                                    break
                                end

                                task.wait(0.25)

                                t += 0.25
                            end

                            if not (LocalPlayer.Character and LocalPlayer.Character ~= character) then
                                dbg(
[[AA markers seen but nothing died within 5s, treating as a false positive]])

                                return
                            end
                            if not running then
                                return
                            end

                            state = state or {}
                            state.aaGunned = true

                            if danger then
                                saveState()
                                stopNote('AA gunned while in Danger, kicking')
                                hardStop('AA gunned while in Danger')

                                return
                            end

                            saveState()
                            stopNote('AA gunned, menuing and kicking')
                            hardStop('AA gunned')
                        end)
                    end)
                end
                local function bindDeath(character)
                    local hum = character and character:FindFirstChildOfClass('Humanoid')

                    if not hum then
                        return
                    end

                    proximityGraceUntil = math.max(proximityGraceUntil, tick() + 3)

                    watchAA(character)

                    guard.deathWatch = hum.Died:Connect(function()
                        if not running or tick() < intentionalUntil then
                            return
                        end

                        deathKick()
                    end)
                end
                local function isObserving(p)
                    local c = p.Character

                    if not c then
                        return false
                    end
                    if game.PlaceId == KHEI_PLACE then
                        local bp = p:FindFirstChildOfClass('Backpack')

                        return c:FindFirstChild('Observe') ~= nil or (bp ~= nil and bp:FindFirstChild('Observe') ~= nil) or c:FindFirstChild('Observing') ~= nil
                    end

                    return c:FindFirstChild('Observing') ~= nil
                end

                local getServerValue = Remotes.getServerValue

                ctx.State.getServerValue = getServerValue

                if LocalPlayer.Character then
                    lastSpawnAt = tick()
                end

                ctx.Maid:Give(LocalPlayer.CharacterAdded:Connect(function()
                    lastSpawnAt = tick()
                end))

                local function checkSilver()
                    return getServerValue('Silver')
                end
                local function label()
                    return 'Auto-' .. (Options.ProgClass and Options.ProgClass.Value or 'Sigil')
                end
                local function progEmbed(title, color, lines, fields)
                    local name, region = serverInfo()

                    table.insert(lines, 1, string.format('**Server:** `%s (%s)`', name, region))

                    return {
                        title = title .. ' | ' .. (game.PlaceId == KHEI_PLACE and 'KHEI' or 'GAIA'),
                        description = table.concat(lines, '\n'),
                        color = color,
                        fields = fields,
                        footer = {
                            text = footerText(),
                        },
                        timestamp = os.date('!%Y-%m-%dT%H:%M:%SZ'),
                    }
                end
                local function waitMenuReady(timeout, requireChar)
                    local deadline = tick() + (timeout or 8)

                    while(running or hopCommitted) and tick() < deadline do
                        local c = LocalPlayer.Character

                        if not c then
                            if not requireChar then
                                return true
                            end

                            task.wait(0.1)

                            continue
                        end
                        if requireChar and not charReady() then
                            task.wait(0.1)

                            continue
                        end

                        local pg = LocalPlayer:FindFirstChild('PlayerGui')
                        local gui = pg and pg:FindFirstChild('MenuReturnGui')
                        local menu = gui and (gui:FindFirstChild('Menu') or gui:FindFirstChild('Menu', true))

                        if menu and menu.Visible then
                            return true
                        end

                        task.wait(0.1)
                    end

                    return false
                end
                local function executeHop(reason, origin, radius, ping)
                    if hopCommitted or ctx.State.progHalted then
                        return false
                    end

                    hopCommitted = true
                    running = false

                    serverInfo(5)

                    local selfHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
                    local note = {}

                    for _, row in (roster and #roster > 0) and roster or rosterLines(ctx, getRogue, origin or (selfHrp and selfHrp.Position), radius or 700)do
                        table.insert(note, row)
                    end

                    hopNote(reason, note, ping, state and state.phase or '?')

                    local lastHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                    if lastHrp then
                        MemStore.setJSON('prog_lastpos', {
                            x = lastHrp.Position.X,
                            y = lastHrp.Position.Y,
                            z = lastHrp.Position.Z,
                        })
                    end
                    if state and state.phase == 'P5' then
                        MemStore.remove('prog_pathpoint')
                    end

                    intentional()
                    waitMenuOut()

                    local avoidTwins = Toggles.AvoidOtherBots == nil or Toggles.AvoidOtherBots.Value
                    local ok, _, why = Serverhop.hop({
                        strategy = (state and state.phase == 'P3') and 'largest' or 'smallest',
                        minPlayers = game.PlaceId ~= KHEI_PLACE and (Options.MinPlayerCount and Options.MinPlayerCount.Value) or 0,
                        reason = reason,
                        returnToMenu = not inAir(),
                        avoid = avoidTwins and BotClaims.takenJobs() or nil,
                        onPick = BotClaims.claim,
                        cancelled = function()
                            return ctx.State.progHalted == true
                        end,
                    })

                    if not ok and not ctx.State.progHalted then
                        idleUI()

                        local failed = label() .. ' serverhop failed: ' .. tostring(why or 'no joinable server')

                        stopNote(failed)
                        Danger.waitClear()
                        waitMenuOut()
                        Danger.kick('sentinel: ' .. failed)
                    end

                    return ok
                end

                local smoothTeleport

                local function progressionServerhop(
                    reason,
                    origin,
                    radius,
                    ping,
                    roster
                )
                    if not running or hopCommitted then
                        return false
                    end
                    if Toggles.ProgStayInServer and Toggles.ProgStayInServer.Value then
                        return false
                    end

                    return executeHop(reason, origin, radius, ping) and true or false
                end
                local function settleBeforeHop()
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                    if not hum then
                        return
                    end

                    local t = 0

                    while t < 1.5 and hum.FloorMaterial == Enum.Material.Air do
                        task.wait(0.1)

                        t += 0.1
                    end
                end
                local function hopOrDie(reason, origin, radius)
                    settleBeforeHop()

                    return executeHop(reason, origin, radius)
                end
                local function handleModerator(p)
                    local avoided = AvoidList.has(p)

                    if friendly(ctx, p) and not avoided then
                        return
                    end

                    local who = AvoidList.label(p)

                    if Toggles.ProgStayInServer and Toggles.ProgStayInServer.Value then
                        hardStop(who .. ' ' .. p.Name .. ' present')

                        return
                    end

                    local key = 'moderator_encounter_' .. p.Name
                    local count = (tonumber(MemStore.get(key)) or 0) + 1

                    MemStore.set(key, count)
                    dbg('%s %s detected (encounter %d)', who:lower(), p.Name, count)

                    local char = LocalPlayer.Character
                    local mhrp = char and char:FindFirstChild('HumanoidRootPart')
                    local danger = not avoided and char ~= nil and CollectionService:HasTag(char, 'Danger')

                    if count >= 3 or danger then
                        running = false

                        saveState()
                        MemStore.remove('progression_active')
                        stopNote(string.format('%s %s%s, kicking', who:lower(), p.Name, danger and ' (in danger)' or ' encountered 3x'))
                        Danger.waitClear()
                        waitMenuOut()
                        Danger.kick('auto-sigil: ' .. who:lower() .. ' encountered')
                    else
                        progressionServerhop(who .. ' ' .. p.Name .. ' present', mhrp and mhrp.Position, 700)
                    end
                end
                local function watchable()
                    return game.PlaceId == KHEI_PLACE or (state ~= nil and (state.aaGunned == true or (state.done ~= nil and state.done.frey == true))) or #missingFrom(FREY_SKILLS) < #FREY_SKILLS
                end
                local function checkPlayerThreat(p, illusionistOnly)
                    if not running or p == LocalPlayer then
                        return false
                    end
                    if not illusionistOnly and ctx.State.isModerator and ctx.State.isModerator(p) then
                        handleModerator(p)

                        return false
                    end
                    if not (Toggles.ProgSkipIllusionist and Toggles.ProgSkipIllusionist.Value and watchable() and isObserving(p)) or friendly(ctx, p) then
                        return false
                    end

                    local ihrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
                    local how = game.PlaceId == KHEI_PLACE and ' carrying Observe' or ' observing'

                    progressionServerhop('Illusionist ' .. getRogue(p) .. how, ihrp and ihrp.Position, (Options.ProgProximity and Options.ProgProximity.Value) or 700)

                    return true
                end
                local function watchCharacter(p, char)
                    if not char then
                        return
                    end

                    guard['char_' .. p.UserId] = char.ChildAdded:Connect(function(
                        child
                    )
                        if child.Name == 'Observing' then
                            checkPlayerThreat(p)
                        end
                    end)

                    if char:FindFirstChild('Observing') then
                        checkPlayerThreat(p)
                    end
                end
                local function watchPlayer(p)
                    if p == LocalPlayer then
                        return
                    end

                    checkPlayerThreat(p)
                    watchCharacter(p, p.Character)

                    guard['cadd_' .. p.UserId] = p.CharacterAdded:Connect(function(
                        char
                    )
                        watchCharacter(p, char)
                    end)
                end

                local sigilAccum = 0
                local heartbeat = BASIL_NO_VIRTUALIZE(function(dt)
                    if not running then
                        return
                    end

                    sigilAccum += dt

                    if sigilAccum < 0.05 then
                        return
                    end

                    sigilAccum = 0

                    if not sweptSuper and tick() >= superSweepAt then
                        superSweepAt = tick() + 2

                        if watchable() then
                            sweptSuper = true

                            dbg('went super, re-checking everyone for illusionists')

                            for _, p in Players:GetPlayers()do
                                checkPlayerThreat(p)
                            end
                        end
                    end

                    local char = LocalPlayer.Character
                    local hrp = char and char:FindFirstChild('HumanoidRootPart')

                    if not hrp then
                        return
                    end

                    local dangered = CollectionService:HasTag(char, 'Danger') and tick() >= intentionalUntil

                    if dangered then
                        handleDanger()

                        if not running then
                            return
                        end
                    end
                    if Toggles.ProgStayInServer and Toggles.ProgStayInServer.Value then
                        return
                    end

                    local prox = Options.ProgProximity and Options.ProgProximity.Value or 0
                    local graceOver = tick() >= proximityGraceUntil

                    for _, p in Players:GetPlayers()do
                        if p ~= LocalPlayer then
                            local pchar = p.Character
                            local phrp = pchar and pchar:FindFirstChild('HumanoidRootPart')

                            if phrp and not Threats.inSpawnBox(phrp.Position) then
                                local d = (phrp.Position - hrp.Position).Magnitude
                                local pebbleTool = pchar:FindFirstChild('Pebble')

                                if pebbleTool and pebbleTool:IsA('Tool') then
                                    pebbleHolders[p] = tick()

                                    if d <= PEBBLE_HOLD_RANGE and not dangered and not friendly(ctx, p) then
                                        progressionServerhop(string.format('%s holding Pebble (%.0f studs)', getRogue(p), d), hrp.Position, PEBBLE_HOLD_RANGE)

                                        return
                                    end
                                end
                                if prox > 0 and graceOver and d <= prox and not dangered and not friendly(ctx, p) then
                                    progressionServerhop(string.format('%s within %.0f studs', getRogue(p), d), hrp.Position, prox)

                                    return
                                end

                                local opal = d <= Threats.RANGE.opalHold and pchar:FindFirstChild('Opal Shard')

                                if opal and opal:IsA('Tool') and not friendly(ctx, p) and Threats.allowed(Options, 'opalshard') and pingMs() > Threats.OPAL_HOLD_PING then
                                    progressionServerhop(string.format('%s holding Opal Shard (%.0f studs, %.0fms ping)', getRogue(p), d, pingMs()), hrp.Position, Threats.RANGE.opalHold)

                                    return
                                end
                            end
                        end
                    end
                end)

                local function handlePebbleThrow(object)
                    local char = LocalPlayer.Character
                    local hrp = char and char:FindFirstChild('HumanoidRootPart')
                    local owner, ownerD

                    for p, t in pebbleHolders do
                        if p ~= LocalPlayer and tick() - t <= PEBBLE_OWNER_WINDOW and not friendly(ctx, p) then
                            local ph = p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                            if ph then
                                local d = hrp and (ph.Position - hrp.Position).Magnitude or 0

                                if not ownerD or d < ownerD then
                                    owner, ownerD = p, d
                                end
                            end
                        end
                    end

                    if owner and (not hrp or ownerD <= PEBBLE_THROW_RANGE) then
                        progressionServerhop(string.format('%s threw Pebble (%.0f studs)', getRogue(owner), ownerD), hrp and hrp.Position, PEBBLE_THROW_RANGE)
                    end
                end

                local threatsDetach, snapArmed

                local function armThreats()
                    if threatsDetach then
                        threatsDetach()
                    end

                    threatsDetach, snapArmed = Threats.watch({
                        active = function()
                            return running and not hopCommitted
                        end,
                        isFriend = function(p)
                            return friendly(ctx, p)
                        end,
                        allow = function(kind)
                            return Threats.allowed(Options, kind)
                        end,
                        report = function(threat)
                            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                            if threat.kind ~= 'glassmask' and threat.kind ~= 'celeritas' then
                                local escape = threat.dodge or Threats.sidestep(threat.position)

                                if escape then
                                    smoothTeleport(escape)
                                end
                            end

                            progressionServerhop(threat.label, hrp and hrp.Position, threat.range, threat.kind == 'glassmask' and '@everyone' or nil)
                        end,
                    })

                    if not snapArmed then
                        dbg('arm: ClientVFX missing, snap Celeritas detection is off')
                    end
                end
                local function arm()
                    guard:DoCleaning()

                    superSweepAt, sweptSuper = 0, false

                    table.clear(pebbleHolders)

                    proximityGraceUntil = tick() + PROXIMITY_GRACE

                    for _, p in Players:GetPlayers()do
                        watchPlayer(p)
                    end

                    task.spawn(function()
                        while running and inDanger() do
                            task.wait(0.5)
                        end

                        for _, p in Players:GetPlayers()do
                            local char = p ~= LocalPlayer and not friendly(ctx, p) and p.Character

                            if char then
                                for _, item in char:GetChildren()do
                                    if item:IsA('Tool') and (item.Name == 'Pebble' or item.Name == 'Perflora') then
                                        progressionServerhop(string.format('%s already holding %s at the start', getRogue(p), item.Name))

                                        return
                                    end
                                end
                            end
                        end
                    end)
                    guard:Connect(RunService.Heartbeat, heartbeat)
                    guard:Connect(Workspace.ChildAdded, function(obj)
                        if running and obj:IsA('MeshPart') and obj.Name == 'pebble' then
                            handlePebbleThrow(obj)
                        end
                    end)
                    armThreats()
                    guard:Give(function()
                        if threatsDetach then
                            threatsDetach()

                            threatsDetach = nil
                        end
                    end)
                    task.spawn(suppressTouch)
                    guard:Connect(Players.PlayerAdded, watchPlayer)
                    AAGun.watch(guard, function()
                        if not running then
                            return
                        end

                        intentional()

                        state = state or {}
                        state.aaGunned = true

                        local phase = tostring(state.phase or '?')

                        dbg('AA gunned on %s, stopping', phase)

                        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        stopNote(string.format(
[[AA gunned on **%s**, stopped so you can start it again yourself]], phase), rosterLines(ctx, getRogue, hrp and hrp.Position, 700))
                        hardStop('AA gunned on ' .. phase)
                    end)

                    if game.PlaceId == KHEI_PLACE then
                        guard:Give(task.spawn(function()
                            while running do
                                task.wait(1)

                                for _, p in Players:GetPlayers()do
                                    if not running or hopCommitted then
                                        break
                                    end
                                    if checkPlayerThreat(p, true) then
                                        break
                                    end
                                end
                            end
                        end))
                    end
                    if ctx.State.onModeratorFlagged then
                        guard.flagged = ctx.State.onModeratorFlagged(function(
                            p
                        )
                            if running then
                                handleModerator(p)
                            end
                        end)
                    end

                    guard:Connect(Players.PlayerRemoving, function(p)
                        guard['char_' .. p.UserId] = nil
                        guard['cadd_' .. p.UserId] = nil
                    end)
                    bindDeath(LocalPlayer.Character)
                    guard:Connect(LocalPlayer.CharacterAdded, bindDeath)
                    guard:Give(task.spawn(function()
                        local smoothed, overSince = pingMs(), nil

                        while running do
                            task.wait(PING_SAMPLE)

                            smoothed = smoothed * 0.8 + pingMs() * 0.2

                            local limit = (Options.ProgPing and Options.ProgPing.Value) or 0

                            if limit <= 0 or smoothed <= limit or hopCommitted or (Toggles.ProgStayInServer and Toggles.ProgStayInServer.Value) then
                                overSince = nil
                            elseif not overSince then
                                overSince = os.clock()
                            elseif os.clock() - overSince >= PING_HOP_SUSTAIN then
                                overSince = nil

                                dbg('ping %.0fms over the %.0fms limit for %ds, hopping', smoothed, limit, PING_HOP_SUSTAIN)
                                task.spawn(progressionServerhop, string.format('%.0fms ping over the %.0fms limit', smoothed, limit))
                            end
                        end
                    end))
                    guard:Give(PingWatch.watch(function(ping, baseline)
                        if running and not hopCommitted then
                            task.spawn(progressionServerhop, string.format('ping spiked to %.0fms from %.0fms', ping, baseline))
                        end
                    end))

                    if getfpscap and setfpscap then
                        guard:Give(task.spawn(function()
                            while running do
                                local ok, cap = pcall(getfpscap)

                                if ok and type(cap) == 'number' and cap > 0 and cap < 50 then
                                    pcall(setfpscap, 60)
                                    dbg('FPS cap was %d, raised to 60', cap)
                                end

                                task.wait(2)
                            end
                        end))
                    end

                    guard:Give(task.spawn(function()
                        while running do
                            task.wait(60)

                            if running and not hopCommitted then
                                BotClaims.claim(game.JobId)
                            end
                        end
                    end))
                    guard:Connect(Players.PlayerAdded, function(p)
                        task.wait(1)

                        local avoidTwins = Toggles.AvoidOtherBots == nil or Toggles.AvoidOtherBots.Value

                        if running and avoidTwins and BotClaims.twinHere() == p then
                            progressionServerhop('another of your bots (' .. p.Name .. ') joined')
                        end
                    end)
                end

                function smoothTeleport(target, speed, grounded)
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild('HumanoidRootPart')
                    local cw = 0

                    while running and not root and cw < 8 do
                        task.wait(0.1)

                        cw += 0.1

                        char = LocalPlayer.Character
                        root = char and char:FindFirstChild('HumanoidRootPart')
                    end

                    if not root then
                        return
                    end

                    local settleUntil = os.clock() + 15

                    while running and os.clock() < settleUntil do
                        local h = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        if h and h.Parent and (h.Position - Vector3.new(-2, -102, 133)).Magnitude > 100 then
                            break
                        end

                        task.wait(0.15)
                    end

                    root = (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')) or root

                    if not root then
                        return
                    end

                    local targetPosition

                    if typeof(target) == 'CFrame' then
                        targetPosition = target.Position
                    elseif typeof(target) == 'Vector3' then
                        targetPosition = target
                    elseif typeof(target) == 'Instance' and target:IsA('BasePart') then
                        targetPosition = target.Position
                    else
                        return
                    end

                    local humanoid = char:FindFirstChildOfClass('Humanoid')

                    if humanoid and not grounded then
                        humanoid:SetStateEnabled(5, false)
                        humanoid:ChangeState(3)
                    end
                    if grounded then
                        restoreClip(char)
                    end

                    local connection = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        local c = LocalPlayer.Character

                        if grounded then
                            local h = c and c:FindFirstChildOfClass('Humanoid')

                            if h and h:GetState() ~= Enum.HumanoidStateType.Running then
                                h:ChangeState(Enum.HumanoidStateType.Running)
                            end

                            return
                        end

                        Character.noclip(c, true)
                    end))

                    speed = speed or (Options.TrinketBotSpeed and Options.TrinketBotSpeed.Value) or 100

                    local function hop(pos, retry)
                        local r = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        if not r then
                            return
                        end

                        local dist = (pos - r.Position).Magnitude
                        local tween = TweenService:Create(r, TweenInfo.new(dist / speed, Enum.EasingStyle.Linear), {
                            CFrame = CFrame.new(pos),
                        })

                        activeTween.tween = tween

                        local completed = false

                        tween.Completed:Connect(function()
                            completed = true
                        end)
                        tween:Play()
                        BASIL_NO_VIRTUALIZE(function()
                            while not completed and running do
                                task.wait()
                            end
                        end)()

                        if not running then
                            tween:Cancel()
                        else
                            local r2 = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
                            local off = r2 and (r2.Position - pos).Magnitude or 0

                            if off > 8 and (retry or 0) < 2 then
                                activeTween.tween = nil

                                hop(pos, (retry or 0) + 1)

                                return
                            end
                        end

                        activeTween.tween = nil
                    end

                    while running do
                        local r = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        if not r then
                            break
                        end

                        local d = (targetPosition - r.Position).Magnitude

                        if d <= 1400 then
                            hop(targetPosition)

                            break
                        end

                        hop(r.Position + (targetPosition - r.Position).Unit * 1400)
                    end

                    if humanoid and not grounded then
                        humanoid:SetStateEnabled(5, true)
                        humanoid:ChangeState(5)
                    end

                    connection:Disconnect()
                    Character.clearVeil()

                    activeTween.tween = nil
                    activeTween.connection = nil
                end

                ctx.State.progWaitDanger = function()
                    local c = LocalPlayer.Character

                    if not (c and CollectionService:HasTag(c, 'Danger')) then
                        return true
                    end

                    local hrp = c:FindFirstChild('HumanoidRootPart')

                    if hrp and (hrp.Position - A2_DANGER_NEAR).Magnitude <= 380 then
                        dbg('danger near the Oresfall approach, perching until it clears')
                        smoothTeleport(A2_DANGER_PERCH)
                    end

                    local t = 0

                    while t < 150 do
                        c = LocalPlayer.Character

                        if not c or not CollectionService:HasTag(c, 'Danger') then
                            return true
                        end

                        task.wait(0.5)

                        t += 0.5
                    end

                    return false
                end
                ctx.State.progKillWhenClear = function()
                    local c = LocalPlayer.Character

                    if c and CollectionService:HasTag(c, 'Danger') then
                        local hrp = c:FindFirstChild('HumanoidRootPart')

                        if hrp and (hrp.Position - A2_DANGER_NEAR).Magnitude <= 380 then
                            dbg('danger near the Oresfall approach, perching until it clears')
                            smoothTeleport(A2_DANGER_PERCH)
                        end

                        dbg('kill held until Danger drops')

                        repeat
                            RunService.Heartbeat:Wait()

                            c = LocalPlayer.Character
                        until not running or not (c and CollectionService:HasTag(c, 'Danger'))

                        task.wait(0.5)
                    end

                    local old = LocalPlayer.Character

                    if not running or not old then
                        return nil
                    end

                    intentional()
                    pcall(Character.kill)

                    return old
                end

                local requestRemote = Remotes.requestRemote

                local function checkCapabilities()
                    local missing = {}

                    if not fireclickdetector then
                        table.insert(missing, 'fireclickdetector')
                    end
                    if not firesignal then
                        table.insert(missing, 'firesignal')
                    end
                    if not firetouchinterest then
                        table.insert(missing, 'firetouchinterest')
                    end
                    if not (writefile and readfile) then
                        table.insert(missing, 'writefile/readfile')
                    end

                    return missing
                end

                local HARDCODE_ON = {
                    'NoKillBricks',
                    'NoFall',
                    'NoOrderlyBarriers',
                    'AutoIngredient',
                    'AutoTrinket',
                    'AutoBard',
                    'AntiAfk',
                }

                local function setToggle(key, value)
                    local t = Toggles[key]

                    if t then
                        pcall(function()
                            t:SetValue(value)
                        end)
                    end
                end

                local enforceRegistered = false

                local function registerEnforce()
                    if enforceRegistered then
                        return
                    end

                    enforceRegistered = true

                    for _, key in HARDCODE_ON do
                        local t = Toggles[key]

                        if t then
                            pcall(function()
                                t:OnChanged(function()
                                    if running and not t.Value then
                                        setToggle(key, true)
                                    end
                                end)
                            end)
                        end
                    end
                end
                local function forceToggles()
                    savedToggles = {}

                    for _, key in HARDCODE_ON do
                        local t = Toggles[key]

                        if t then
                            savedToggles[key] = t.Value

                            setToggle(key, true)
                        end
                    end

                    local nmt = Toggles.NoMobTrigger

                    if nmt then
                        savedToggles.NoMobTrigger = nmt.Value

                        setToggle('NoMobTrigger', false)
                    end

                    registerEnforce()
                end
                local function restoreToggles()
                    for key, val in savedToggles do
                        setToggle(key, val)
                    end

                    savedToggles = {}
                end
                local function clickRemote(name)
                    local char = LocalPlayer.Character
                    local handler = char and char:FindFirstChild('CharacterHandler')
                    local remotes = handler and handler:FindFirstChild('Remotes')

                    return remotes and remotes:FindFirstChild(name)
                end
                local function getVim()
                    if not vim then
                        local ok, v = pcall(Instance.new, 'VirtualInputManager')

                        vim = ok and v or nil
                    end

                    return vim
                end
                local function hasLightAttack()
                    local c = LocalPlayer.Character

                    return c ~= nil and c:FindFirstChild('LightAttack') ~= nil
                end
                local function swingOnce()
                    local v = getVim()

                    if v then
                        task.spawn(function()
                            pcall(function()
                                v:SendMouseButtonEvent(0, 0, 0, true, game, 1)
                                task.wait(math.random(1, 15) / 1000)
                                v:SendMouseButtonEvent(0, 0, 0, false, game, 1)
                            end)
                        end)
                    end

                    local r = clickRemote('LeftClick')

                    if r then
                        pcall(function()
                            r:FireServer({
                                math.random(1, 10),
                                tonumber('0.' .. math.random(1e15, 9e15)),
                            })
                        end)
                    end
                end
                local function leftClick(count)
                    count = count or 1

                    for _ = 1, count do
                        if not running then
                            return
                        end

                        local t = 0

                        while running and hasLightAttack() and t < 1.5 do
                            task.wait(0.03)

                            t += 0.03
                        end

                        if not running then
                            return
                        end

                        swingOnce()
                        task.wait(0.1)
                    end
                end
                local function goTo(target, recover)
                    if recover then
                        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
                        local dist = hrp and (hrp.Position - target).Magnitude or math.huge

                        if dist > 300 then
                            dbg(
[[goTo: %.0f studs from target - out of position, recovering instead of teleporting]], dist)
                            recover()

                            return false
                        end
                    end

                    smoothTeleport(target)

                    return true
                end
                local function pathTo(list)
                    activePath = list

                    local sig = #list .. '|' .. tostring(list[1]) .. '|' .. tostring(list[#list])
                    local startIdx = 1

                    if resumePath and resumePath.sig == sig then
                        startIdx = math.max(1, math.min(resumePath.idx or 1, #list))
                        resumePath = nil
                    end

                    for i = startIdx, #list do
                        if not running then
                            return false
                        end

                        holdIfUnsafe()

                        local from = i == startIdx and Character.root()
                        local leg = from and (list[i] - from.Position).Magnitude or 0

                        if leg > PATH_MAX_LEG then
                            dbg(
[[pathTo: %.0f studs from the path's start, menu teleporting there instead of flying]], leg)
                            ctx.State.progWaitDanger()
                            waitMenuReady(25, true)

                            local landed = Menu.menuTele(list[i], function()
                                return running
                            end)

                            if not landed then
                                if running then
                                    progressionServerhop(string.format(
[[could not reach a path start %.0f studs away without flying across the map]], leg))
                                end

                                return false
                            end
                        end

                        smoothTeleport(list[i])
                        MemStore.setJSON('prog_pathpoint', {
                            sig = sig,
                            idx = i,
                        })
                        task.wait(0.02)
                    end

                    MemStore.remove('prog_pathpoint')

                    return true
                end

                local near = Character.near

                local function waitArrival(pos, radius, timeout)
                    local t = 0

                    while running and not near(pos, radius) and t < (timeout or 8) do
                        task.wait(0.1)

                        t += 0.1
                    end

                    return near(pos, radius)
                end
                local function forceTeleport(pos)
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild('HumanoidRootPart')

                    if not root then
                        return
                    end

                    local settleUntil = os.clock() + 15

                    while running and os.clock() < settleUntil do
                        local h = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        if h and h.Parent and (h.Position - Vector3.new(-2, -102, 133)).Magnitude > 100 then
                            break
                        end

                        task.wait(0.15)
                    end

                    char = LocalPlayer.Character
                    root = char and char:FindFirstChild('HumanoidRootPart')

                    if not root then
                        return
                    end

                    local hum = char:FindFirstChildOfClass('Humanoid')

                    if hum then
                        hum:SetStateEnabled(5, false)
                        hum:ChangeState(3)
                    end

                    local conn = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        Character.noclip(LocalPlayer.Character)
                    end))
                    local speed = (Options.TrinketBotSpeed and Options.TrinketBotSpeed.Value) or 100
                    local dist = (pos - root.Position).Magnitude
                    local tween = TweenService:Create(root, TweenInfo.new(dist / speed, Enum.EasingStyle.Linear), {
                        CFrame = CFrame.new(pos),
                    })
                    local done = false

                    tween.Completed:Connect(function()
                        done = true
                    end)
                    tween:Play()

                    local t = 0

                    while not done and t < 5 do
                        t += task.wait()
                    end

                    conn:Disconnect()
                end
                local function hostileNear(pos, radius)
                    for _, p in Players:GetPlayers()do
                        if p ~= LocalPlayer and not friendly(ctx, p) then
                            local ph = p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                            if ph and (ph.Position - pos).Magnitude <= radius then
                                return true
                            end
                        end
                    end

                    return false
                end
                local function nearestHostile(pos, radius)
                    local best, bestD

                    for _, p in Players:GetPlayers()do
                        if p ~= LocalPlayer and not friendly(ctx, p) then
                            local ph = p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                            if ph then
                                local d = (ph.Position - pos).Magnitude

                                if d <= radius and (not bestD or d < bestD) then
                                    best, bestD = p, d
                                end
                            end
                        end
                    end

                    return best
                end

                ctx.Maid:Give(RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                )
                    if tick() - a2FleeAt < 0.25 then
                        return
                    end

                    a2FleeAt = tick()

                    if hopCommitted or not running or not (state and state.phase == 'P5') then
                        a2FleeHit = false

                        return
                    end

                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                    if not hrp then
                        return
                    end

                    local y = hrp.Position.Y

                    if y < A2_FLEE_Y_MIN or y > A2_FLEE_Y_MAX or (hrp.Position - A2_FLEE_WATCH).Magnitude > A2_FLEE_SELF then
                        return
                    end
                    if hostileNear(A2_FLEE_WATCH, A2_FLEE_RADIUS) then
                        a2FleeHit = true
                    end
                end)))

                ctx.State.a2FleeDue = function()
                    return a2FleeHit
                end

                local function escapeAlongPath(attacker)
                    local aHrp = attacker.Character and attacker.Character:FindFirstChild('HumanoidRootPart')
                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
                    local points = activePath

                    if not (aHrp and hrp and points and #points > 0) then
                        return false
                    end

                    local startIdx, minD = 1, math.huge

                    for idx, p in points do
                        local d = (p - hrp.Position).Magnitude

                        if d < minD then
                            minD = d
                            startIdx = idx
                        end
                    end

                    local goFirst = (points[1] - aHrp.Position).Magnitude > (points[#points] - aHrp.Position).Magnitude
                    local target = goFirst and 1 or #points
                    local step = goFirst and -1 or 1

                    for j = startIdx + step, target, step do
                        local pt = points[j]

                        if ctx.State.progHalted then
                            break
                        end
                        if pt then
                            if hostileNear(pt, 90) then
                                break
                            end

                            forceTeleport(pt)
                            task.wait(0.2)

                            local c = LocalPlayer.Character

                            if c and not CollectionService:HasTag(c, 'Danger') then
                                return true
                            end
                        end
                    end

                    local c = LocalPlayer.Character

                    return c ~= nil and not CollectionService:HasTag(c, 'Danger')
                end

                function handleDanger()
                    if dangerBusy or tick() < intentionalUntil then
                        return
                    end

                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                    if not hrp then
                        return
                    end

                    local prox = (Options.ProgProximity and Options.ProgProximity.Value) or 300

                    if prox <= 0 then
                        return
                    end

                    local attacker = nearestHostile(hrp.Position, prox * 0.4)

                    if not attacker then
                        return
                    end

                    dangerBusy = true
                    running = false

                    local name = getRogue(attacker)
                    local atPit = state ~= nil and state.phase == 'P5' and (hrp.Position - A2_FLEE_WATCH).Magnitude <= A2_FLEE_SELF

                    task.spawn(function()
                        guard.attachLock = nil

                        zOffsetStop()

                        if atPit then
                            local perch = A2_FLEE_PATH[A2_FLEE_PERCH]

                            forceTeleport(perch)

                            local pin = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                            )
                                local r = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                                if r then
                                    r.CFrame = CFrame.new(perch)
                                    r.AssemblyLinearVelocity = Vector3.zero
                                end
                            end))
                            local waited = 0

                            while inDanger() and waited < A2_FLEE_HOLD_MAX and not ctx.State.progHalted do
                                task.wait(0.5)

                                waited += 0.5
                            end

                            pin:Disconnect()

                            if not ctx.State.progHalted then
                                state.a2resume = true

                                saveState()
                            end

                            executeHop('went up to the perch away from ' .. name .. ' while combat-locked')
                        elseif escapeAlongPath(attacker) then
                            executeHop('escaped ' .. name .. ' while combat-locked')
                        else
                            executeHop('could not break away from ' .. name .. ', hopping out', nil, nil, '@here')
                        end

                        dangerBusy = false
                    end)
                end

                local function reset(anchor, radius)
                    local old = ctx.State.progKillWhenClear()

                    if not old then
                        dbg('reset aborted, no character to reset')

                        return false
                    end

                    local t = 0

                    repeat
                        intentional()
                        task.wait(0.3)

                        t += 0.3
                    until (LocalPlayer.Character and LocalPlayer.Character ~= old and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')) or t > 20 or not running

                    if anchor then
                        return waitArrival(anchor, radius or 150, 10)
                    end

                    return true
                end

                local nearestModel = NPC.nearestModel
                local nearestNPC = NPC.nearestNPC

                local function runDialogue(
                    npc,
                    choices,
                    timeout,
                    doneWhen,
                    successWhen,
                    beforeAnswer
                )
                    if not running then
                        return false
                    end

                    setBusy(true)

                    local ok, wasDone, offered, closed, sent, gave = Dialogue.run(npc, choices, {
                        shouldRun = function()
                            return running
                        end,
                        timeout = timeout,
                        doneWhen = doneWhen,
                        successWhen = successWhen,
                        beforeAnswer = beforeAnswer,
                        minHold = 0.5,
                        log = function(m)
                            dbg('%s', m)
                        end,
                    })

                    setBusy(false)

                    return ok, wasDone, offered, closed, sent, gave
                end
                local function talkTo(
                    name,
                    anchor,
                    choices,
                    doneWhen,
                    successWhen,
                    beforeAnswer
                )
                    if not running then
                        return false
                    end

                    local npc = nearestNPC(name, anchor)

                    if not npc then
                        dbg('talk %s: not found near the anchor', name)

                        return false
                    end

                    local began, runs = tick(), 1
                    local ok, wasDone, offered, closed, sent, gave = runDialogue(npc, choices, nil, doneWhen, successWhen, beforeAnswer)

                    if not ok and running then
                        runs = 2
                        ok, wasDone, offered, closed, sent, gave = runDialogue(npc, choices, nil, doneWhen, successWhen, beforeAnswer)
                    end

                    local took = tick() - began
                    local picks = (sent and #sent > 0) and table.concat(sent, ' > ') or 'nothing'
                    local tail = string.format('[%.1fs, %d run%s]', took, runs, runs == 1 and '' or 's')

                    if wasDone then
                        dbg('talk %s: opened on its already-done line %s', name, tail)
                    elseif ok then
                        dbg('talk %s: sent %d/%d [%s] %s', name, sent and #sent or 0, #choices, picks, tail)
                    elseif #choices == 0 then
                        dbg('talk %s: confirm click, not on his finished line yet %s', name, tail)
                    else
                        dbg('talk %s: sent %d/%d [%s] | last offered: %s | %s %s', name, sent and #sent or 0, #choices, picks, offered or 'nothing', closed and 'he closed on a choiceless line' or 'timed out', tail)
                    end

                    return ok, wasDone, gave, offered
                end
                local function talkConfirm(
                    name,
                    anchor,
                    choices,
                    doneWhen,
                    tries,
                    beforeAnswer
                )
                    for _ = 1, (tries or 4)do
                        if not running then
                            return false
                        end

                        local _, wasDone = talkTo(name, anchor, choices, doneWhen, nil, beforeAnswer)

                        if wasDone then
                            return true
                        end

                        task.wait(1)

                        local _, confirmed = talkTo(name, anchor, {}, doneWhen)

                        if confirmed then
                            dbg('talk %s: confirmed on his finished line', name)

                            return true
                        end

                        dbg('talk %s: no confirmation, running it again', name)
                        task.wait(1.5)
                    end

                    skipQuiet(name .. ' never confirmed the quest')

                    return false
                end
                local function getInventoryValue()
                    local total = 0
                    local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                    if not bp then
                        return 0
                    end

                    for _, v in bp:GetChildren()do
                        local sv = v:FindFirstChild('SilverValue')

                        if sv then
                            total += sv.Value
                        end
                    end

                    return total
                end

                ctx.State.progPackSettled = function(timeout)
                    local deadline = tick() + (timeout or 15)
                    local lastCount, stableSince = -1, tick()

                    while running and tick() < deadline do
                        local bp = LocalPlayer:FindFirstChildOfClass('Backpack')
                        local n = bp and #bp:GetChildren() or -1

                        if n ~= lastCount then
                            lastCount, stableSince = n, tick()
                        elseif n > 0 and tick() - stableSince >= 1.5 and tick() - lastSpawnAt >= 3 then
                            return true
                        end

                        task.wait(0.25)
                    end

                    return false
                end

                local function hasTool(name)
                    local bp = LocalPlayer:FindFirstChildOfClass('Backpack')
                    local c = LocalPlayer.Character

                    return (bp ~= nil and bp:FindFirstChild(name) ~= nil) or (c ~= nil and c:FindFirstChild(name) ~= nil)
                end
                local function scroomGroup(pHRP, radius, count)
                    local live = Workspace:FindFirstChild('Live')

                    if not live then
                        return {}
                    end

                    local found = {}

                    for _, obj in live:GetChildren()do
                        if string.find(obj.Name, 'Zombie Scroom') then
                            local hrp = obj:FindFirstChild('HumanoidRootPart')
                            local hum = obj:FindFirstChildOfClass('Humanoid')

                            if hrp and hum and hum.Health > 0 then
                                local d = (hrp.Position - pHRP.Position).Magnitude

                                if d <= radius then
                                    table.insert(found, {
                                        hrp = hrp,
                                        dist = d,
                                    })
                                end
                            end
                        end
                    end

                    table.sort(found, function(a, b)
                        return a.dist < b.dist
                    end)

                    local group = {}

                    for i = 1, math.min(count, #found)do
                        table.insert(group, found[i].hrp)
                    end

                    return group
                end
                local function startAttach(groupFn, dist)
                    local function groupCenter(fromHrp)
                        local group = groupFn(fromHrp)

                        if #group == 0 then
                            return nil
                        end

                        local center, lookSum = Vector3.zero, Vector3.zero

                        for _, hrp in group do
                            center += hrp.Position
                            lookSum += hrp.CFrame.LookVector
                        end

                        center /= #group

                        local lookDir = Vector3.new(lookSum.X, 0, lookSum.Z)

                        lookDir = lookDir.Magnitude < 0.01 and Vector3.new(0, 0,
-1) or lookDir.Unit

                        return center, lookDir
                    end

                    local pHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                    if pHRP then
                        local center, lookDir = groupCenter(pHRP)

                        if center then
                            smoothTeleport(center + lookDir * (dist or 8.5))
                        end
                    end

                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                    if hum then
                        hum:SetStateEnabled(5, false)
                        hum:ChangeState(3)
                    end

                    return RunService.Stepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        if not running then
                            return
                        end

                        local c = LocalPlayer.Character
                        local r = c and c:FindFirstChild('HumanoidRootPart')

                        if not r then
                            return
                        end

                        local center, lookDir = groupCenter(r)

                        if not center then
                            return
                        end

                        Character.noclip(c)

                        r.CFrame = CFrame.lookAt(center + lookDir * (dist or 8.5), center)
                        r.AssemblyLinearVelocity = Vector3.zero
                    end))
                end
                local function attackUntil(
                    predicate,
                    waitBetween,
                    groupFn,
                    dist,
                    onUnsafe
                )
                    setBusy(true)

                    local conn = startAttach(groupFn, dist)

                    while running and not predicate() do
                        if onUnsafe then
                            local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                            if hum and hum.Health < A2_RETREAT_HP and inDanger() then
                                pcall(function()
                                    conn:Disconnect()
                                end)
                                onUnsafe()

                                conn = startAttach(groupFn, dist)
                            end
                        end

                        leftClick(5)
                        task.wait(waitBetween or 2.5)
                    end

                    pcall(function()
                        conn:Disconnect()
                    end)
                    setBusy(false)
                end

                local INN_ANCHORS = NPC.INN_ANCHORS

                local function setInn(name, ownRetry)
                    if not running then
                        return false
                    end

                    dbg('setInn -> %s', tostring(name))

                    local dest = INN_ANCHORS[name]
                    local destProx = Options.ProgProximity and Options.ProgProximity.Value or 0

                    if dest and destProx > 0 then
                        for _, p in Players:GetPlayers()do
                            if p ~= LocalPlayer and not friendly(ctx, p) then
                                local ph = p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                                if ph and (ph.Position - dest[1]).Magnitude <= destProx then
                                    progressionServerhop(string.format('%s at the %s inn', getRogue(p), name), dest[1], destProx)

                                    return false
                                end
                            end
                        end
                    end
                    if getServerValue('Lives') == 0 then
                        return false
                    end

                    local anchor = INN_ANCHORS[name]

                    if state and state.boundInn == name and anchor and near(anchor[1], anchor[2]) then
                        dbg('setInn: already bound+near %s, settling', tostring(name))
                        NPC.waitSettled(anchor, function()
                            return running
                        end)

                        return true
                    end

                    ctx.State.progWaitDanger()

                    local aw = 0

                    while running and not charReady() and aw < 45 do
                        task.wait(0.3)

                        aw += 0.3
                    end

                    if not running then
                        return false
                    end
                    if not waitMenuReady(30, true) then
                        dbg('setInn: character never finished spawning, not binding %s', tostring(name))

                        return false
                    end

                    setBusy(true)

                    local ok = NPC.setInn(name, {
                        shouldRun = function()
                            return running
                        end,
                        breakJoints = true,
                        onBeforeBreak = intentional,
                        attempts = 4,
                        log = function(n)
                            dbg('setInn: no keeper found for %s', tostring(n))
                        end,
                    })

                    setBusy(false)

                    if ok then
                        if state then
                            state.boundInn = name

                            saveState()
                        end

                        return true
                    end
                    if state then
                        state.boundInn = nil

                        saveState()
                    end
                    if not ownRetry and running and pingMs() > 250 and not (Toggles.ProgStayInServer and Toggles.ProgStayInServer.Value) then
                        hopOrDie(string.format('setInn(%s) failed + %.0fms ping - hopping', tostring(name), pingMs()))
                    end

                    return false
                end

                ctx.State.setInn = setInn
                ctx.State.progActive = function()
                    return running
                end

                local function loopOrderly(times)
                    setBusy(true)

                    for _ = 1, times do
                        if not running then
                            break
                        end

                        while running and LocalPlayer.Character and CollectionService:HasTag(LocalPlayer.Character, 'Danger') do
                            task.wait(0.3)
                        end

                        local ew = 0
                        local c, hum, elixir

                        while running and ew < 25 do
                            c, hum = charReady()

                            local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                            elixir = bp and bp:FindFirstChild('Tespian Elixir')

                            if c and hum and elixir then
                                break
                            end

                            task.wait(0.3)

                            ew += 0.3
                        end

                        if not (c and hum) then
                            c = LocalPlayer.Character
                            hum = c and c:FindFirstChildOfClass('Humanoid')

                            local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                            elixir = bp and bp:FindFirstChild('Tespian Elixir')
                        end
                        if not (c and hum and elixir and hum.Health > 0) then
                            dbg(
[[loopOrderly: no live character holding a Tespian Elixir after %.0fs, stopping the cycle]], ew)

                            break
                        end

                        hum:EquipTool(elixir)
                        task.wait(1.4)
                        waitMenuReady(25, true)

                        local cc = LocalPlayer.Character
                        local equipped = cc and cc:FindFirstChild('Tespian Elixir')
                        local remote = equipped and equipped:FindFirstChild('RemoteEvent')
                        local hrp = cc and cc:FindFirstChild('HumanoidRootPart')

                        if not (remote and hrp) then
                            dbg(
[[loopOrderly: the elixir never reached the character, retrying]])
                        else
                            remote:FireServer(hrp.CFrame, 'Part', 'Self')
                            task.wait(1.5)

                            if not ctx.State.progKillWhenClear() then
                                dbg('tespian: no character to reset this cycle')

                                break
                            end

                            local w = 0

                            repeat
                                intentional()
                                task.wait(0.5)

                                w += 0.5
                            until (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('Immortal')) or w > 20 or not running
                        end
                    end

                    setBusy(false)
                end

                local POTION_BAGS = {
                    ['Health Potion'] = true,
                    ['Liquid Wisdom'] = true,
                    ['Ice Protection'] = true,
                    ['Tespian Elixir'] = true,
                }

                local function bagPart(v)
                    return (v:IsA('BasePart') and v) or v:FindFirstChildWhichIsA('BasePart')
                end
                local function collectBag(part)
                    smoothTeleport(part.Position)

                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                    if firetouchinterest and hrp then
                        pcall(function()
                            firetouchinterest(part, hrp, 0)
                            firetouchinterest(part, hrp, 1)
                        end)
                    end

                    task.wait(0.2)
                end
                local function phaseP1()
                    dbg('P1: scanning Thrown for bags within 50')

                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
                    local thrown = Workspace:FindFirstChild('Thrown')

                    if hrp and thrown then
                        local origin = hrp.Position

                        for _, v in thrown:GetChildren()do
                            if v.Name == 'ToolBag' then
                                local bg = v:FindFirstChild('BillboardGui')
                                local tl = bg and bg:FindFirstChild('Tool')
                                local part = bagPart(v)

                                if tl and POTION_BAGS[tl.Text] and part and (part.Position - origin).Magnitude <= 50 then
                                    dbg('P1: collecting ToolBag %s', tostring(tl.Text))
                                    collectBag(part)
                                end
                            end
                        end
                        for _, v in thrown:GetChildren()do
                            if v.Name == 'MoneyBag' then
                                local part = bagPart(v)

                                if part and (part.Position - origin).Magnitude <= 50 then
                                    dbg('P1: collecting MoneyBag')
                                    collectBag(part)
                                end
                            end
                        end

                        smoothTeleport(origin)
                    end

                    local REQUIRED = {
                        'Liquid Wisdom',
                        'Health Potion',
                        'Ice Protection',
                        'Tespian Elixir',
                    }
                    local missing = {}

                    for _, potion in REQUIRED do
                        if not hasTool(potion) then
                            table.insert(missing, potion)
                        end
                    end

                    if #missing > 0 and hasManaDash() and #missingFrom(JAGEN_SKILLS) < #JAGEN_SKILLS then
                        dbg(
[[P1: this character already finished Gaia, not asking for the potions]])

                        state.phase = 'DONE'
                        state.kheiClock = state.kheiClock or os.time()

                        saveState()
                        MemStore.remove('progression_active')
                        restoreToggles()

                        if Toggles.ProgGoToKhei and Toggles.ProgGoToKhei.Value then
                            MemStore.set('khei_run', 'true')
                            ctx.State.progYaaldaHandoff()
                        else
                            task.spawn(function()
                                haltNote('this character already finished Gaia')
                            end)

                            if stop then
                                stop()
                            end
                        end

                        return
                    end
                    if #missing > 0 then
                        notify('Auto-Sigil stopped - needs ' .. table.concat(missing, ', '))
                        stopNote('missing potions: ' .. table.concat(missing, ', ') .. '. give them, then Start again')

                        if stop then
                            stop()
                        end

                        return
                    end

                    setPhase('P2')
                end
                local function phaseP2()
                    if hasTool('Tespian Elixir') then
                        loopOrderly(5)
                    end

                    setPhase('P3')
                end

                local GEMSTONES = {
                    Opal = true,
                    Ruby = true,
                    Sapphire = true,
                    Diamond = true,
                    Emerald = true,
                }

                local function backpackAny(pred)
                    local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                    if not bp then
