                local function findNPCNear(name, fallbackPos)
                    local function here()
                        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        return (hrp and hrp.Position) or fallbackPos
                    end

                    local npc = nearestNPC(name, here())
                    local w = 0

                    while running and not npc and w < 6 do
                        task.wait(0.5)

                        w += 0.5

                        npc = nearestNPC(name, here())
                    end

                    local at = here()

                    if npc then
                        local part = npc:FindFirstChild('HumanoidRootPart') or npc:FindFirstChildWhichIsA('BasePart')

                        if part then
                            dbg(
[[%s part (%.1f,%.1f,%.1f) | bot (%.1f,%.1f,%.1f) | %.1f studs apart]], name, part.Position.X, part.Position.Y, part.Position.Z, at.X, at.Y, at.Z, (part.Position - at).Magnitude)
                        end
                    else
                        dbg('%s not found near (%.0f,%.0f,%.0f) - nearby NPCs:', name, at.X, at.Y, at.Z)

                        local npcs = Workspace:FindFirstChild('NPCs')

                        if npcs then
                            for _, n in npcs:GetChildren()do
                                local part = n:FindFirstChild('HumanoidRootPart') or n:FindFirstChildWhichIsA('BasePart')

                                if part and (part.Position - at).Magnitude < 90 then
                                    dbg('  %s (%.0f studs)', n.Name, (part.Position - at).Magnitude)
                                end
                            end
                        end
                    end

                    return npc
                end
                local function sellTo(npc, choices)
                    local before = getInventoryValue()
                    local tries = 0

                    repeat
                        runDialogue(npc, choices)

                        tries += 1
                    until getInventoryValue() < before or tries >= 3 or not running

                    if getInventoryValue() >= before then
                        dbg(
[[sale via %s did not reduce inventory (%d) - name/dialogue may be wrong]], npc.Name, getInventoryValue())
                    end
                end
                local function isTrinketPart(o)
                    return o.Name == 'Part' and o:FindFirstChild('ID') ~= nil
                end
                local function sweepTrinkets(origin, radius, collected)
                    while running do
                        local char = LocalPlayer.Character
                        local root = char and char:FindFirstChild('HumanoidRootPart')

                        if not root then
                            break
                        end

                        local targets = {}

                        for _, obj in Workspace:GetChildren()do
                            if isTrinketPart(obj) and obj.Parent then
                                local idVal = obj:FindFirstChild('ID')
                                local id = idVal and idVal.Value

                                if not (id and collected[id]) and (obj.Position - origin).Magnitude <= radius then
                                    table.insert(targets, {
                                        obj = obj,
                                        d = (obj.Position - root.Position).Magnitude,
                                        id = id,
                                    })
                                end
                            end
                        end

                        if #targets == 0 then
                            break
                        end

                        table.sort(targets, function(a, b)
                            return a.d < b.d
                        end)

                        for _, t in targets do
                            if not running then
                                break
                            end
                            if t.obj.Parent then
                                smoothTeleport(t.obj.Position)
                                task.wait(0.18)

                                local cd = t.obj:FindFirstChild('ClickDetector', true)

                                if cd and fireclickdetector then
                                    fireclickdetector(cd)
                                end

                                task.wait(0.18)
                            end
                            if t.id then
                                collected[t.id] = true
                            end
                        end
                    end
                end
                local function holdAt(pos, duration)
