                        if r then
                            r.CFrame = CFrame.new(pos)
                            r.AssemblyLinearVelocity = Vector3.zero
                        end
                    end))
                    local elapsed = 0

                    while running and elapsed < duration do
                        task.wait(0.25)

                        elapsed += 0.25
                    end

                    lockConn:Disconnect()
                end
