                local function scroomsIn(center, radius, yLevel)
                    local n, live = 0, Workspace:FindFirstChild('Live')

                    if not live then
                        return 0
                    end

                    for _, obj in live:GetChildren()do
                        if string.find(obj.Name, 'Zombie Scroom') then
                            local hrp = obj:FindFirstChild('HumanoidRootPart')
                            local hum = obj:FindFirstChildOfClass('Humanoid')

                            if hrp and hum and hum.Health > 0 and (hrp.Position - center).Magnitude <= radius and (not yLevel or math.abs(hrp.Position.Y - yLevel) <= A2_SCROOM_Y_TOL) then
                                n += 1
                            end
                        end
                    end

                    return n
                end
                local function nearestScroomTo(pos)
                    local live = Workspace:FindFirstChild('Live')

                    if not live then
                        return nil
                    end

                    local best, bestD

                    for _, obj in live:GetChildren()do
                        if string.find(obj.Name, 'Zombie Scroom') then
                            local hrp = obj:FindFirstChild('HumanoidRootPart')
                            local hum = obj:FindFirstChildOfClass('Humanoid')

                            if hrp and hum and hum.Health > 0 then
                                local d = (hrp.Position - pos).Magnitude

                                if not bestD or d < bestD then
                                    best, bestD = hrp.Position, d
                                end
                            end
                        end
                    end

                    return best
                end
                local function startScroomAttach(
                    scroomHrp,
                    offset,
                    faceThreat,
                    speed
                )
                    if not scroomHrp.Parent then
                        return
                    end

                    local function frontOf()
                        local look = scroomHrp.CFrame.LookVector

                        look = Vector3.new(look.X, 0, look.Z)
                        look = look.Magnitude > 0.01 and look.Unit or Vector3.new(0, 0,
-1)

                        return scroomHrp.Position + look * offset
                    end

                    smoothTeleport(frontOf(), speed)

                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                    if hum then
                        hum:SetStateEnabled(5, false)
                        hum:ChangeState(3)
                    end

                    guard.attachLock = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        local c = LocalPlayer.Character
                        local r = c and c:FindFirstChild('HumanoidRootPart')

                        if r and scroomHrp.Parent then
                            Character.noclip(c)
                            zOffsetHold()

                            local facePos = faceThreat and nearestScroomTo(r.Position) or scroomHrp.Position

                            r.CFrame = CFrame.lookAt(frontOf(), facePos)
                            r.AssemblyLinearVelocity = Vector3.zero
                        end
                    end))
                end
                local function stopScroomAttach()
                    guard.attachLock = nil
                end
                local function attachToScroom(
                    scroomHrp,
                    offset,
                    duration,
                    speed
                )
                    startScroomAttach(scroomHrp, offset, true, speed)

                    local t = 0

                    while running and t < duration do
                        if not scroomHrp.Parent or math.abs(scroomHrp.Position.Y - A2_SCROOM_Y) > A2_SCROOM_Y_TOL then
                            break
                        end

                        task.wait(0.05)

                        t += 0.05
                    end

                    stopScroomAttach()
                end
                local function startHoldBlock()
                    local r = clickRemote('Block')

                    if r then
