                local function gatherScrooms(center, radius)
                    local w = 0

                    while running and scroomsIn(center, radius) == 0 and w < 30 do
                        task.wait(0.5)

                        w += 0.5
                    end

                    local live = Workspace:FindFirstChild('Live')

                    if not live then
                        return
                    end

                    local total, inRange, nearest = 0, 0, nil

                    for _, obj in live:GetChildren()do
                        if string.find(obj.Name, 'Zombie Scroom') then
                            local hrp = obj:FindFirstChild('HumanoidRootPart')
                            local hum = obj:FindFirstChildOfClass('Humanoid')

                            if hrp and hum and hum.Health > 0 and math.abs(hrp.Position.Y - A2_SCROOM_Y) <= A2_SCROOM_Y_TOL then
                                total += 1

                                local d = (hrp.Position - center).Magnitude

                                if not nearest or d < nearest then
                                    nearest = d
                                end
                                if d <= radius then
                                    inRange += 1
                                end
                            end
                        end
                    end

                    dbg('gather: %d live scrooms, %d within %d studs (nearest %.0f)', total, inRange, radius, nearest or
-1)

                    local candidates = {}

                    for _, obj in live:GetChildren()do
                        if string.find(obj.Name, 'Zombie Scroom') then
                            local hrp = obj:FindFirstChild('HumanoidRootPart')
                            local hum = obj:FindFirstChildOfClass('Humanoid')

                            if hrp and hum and hum.Health > 0 and (hrp.Position - center).Magnitude <= radius and math.abs(hrp.Position.Y - A2_SCROOM_Y) <= A2_SCROOM_Y_TOL then
                                table.insert(candidates, hrp)
                            end
                        end
                    end

                    local picked = {}
                    local from = center

                    while#picked < 4 and #candidates > 0 do
                        local bestIdx, bestD = nil, math.huge

                        for i, hrp in candidates do
                            local d = (hrp.Position - from).Magnitude

                            if d < bestD then
                                bestD, bestIdx = d, i
                            end
                        end

                        if not bestIdx then
                            break
                        end

                        local chosen = table.remove(candidates, bestIdx)

                        table.insert(picked, chosen)

                        from = chosen.Position
                    end

                    table.sort(picked, function(a, b)
                        return (a.Position - A2_STAND_POS).Magnitude > (b.Position - A2_STAND_POS).Magnitude
                    end)
                    dbg('gather: pulling %d scrooms', #picked)
                    zOffsetStart()
                    startHoldBlock()

                    for i, hrp in picked do
                        if not running then
                            break
                        end
                        if hrp.Parent and math.abs(hrp.Position.Y - A2_SCROOM_Y) <= A2_SCROOM_Y_TOL then
                            attachToScroom(hrp, 18.5, 1.8, i == 1 and A2_FIRST_SPEED or A2_HERD_SPEED)
                        end
                    end

                    stopHoldBlock()

                    return picked
                end
