                                local master = info and info:FindFirstChild('Master')
                                local hrp = m:FindFirstChild('HumanoidRootPart')
                                local hum = m:FindFirstChildOfClass('Humanoid')

                                if master and master.Value == masterChar and hrp and hum and hum.Health > 0 then
                                    table.insert(out, hrp)
                                end
                            end
                        end

                        return out
                    end
