                local function standAndAttack(cf, onUnsafe, manaTrain)
                    setBusy(true)
                    zOffsetStart()

                    local function lockOn()
                        guard.standLock = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                        )
                            local r = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                            if r then
                                r.CFrame = cf
                                r.AssemblyLinearVelocity = Vector3.zero
                            end

                            zOffsetHold()
                        end))
                    end

                    lockOn()

                    local startT, emptySince, engaged = tick(), nil, false

                    while running and not ctx.State.a2FleeDue() and tick() - startT < 200 do
                        if scroomsIn(cf.Position, 20, A2_SCROOM_Y) == 0 then
                            emptySince = emptySince or tick()

                            if tick() - emptySince > 1.5 then
                                break
                            end
                        else
                            emptySince = nil
                        end
                        if scroomBehind(cf, 15) then
                            guard.standLock = nil

                            smoothTeleport(Vector3.new(2002, 155, -2339))
                            holdAt(Vector3.new(2002, 155, -2339), 1.5)
                            lockOn()
                        end
                        if onUnsafe and tick() - startT > 4 then
                            local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                            if hum and hum.Health < A2_RETREAT_HP and inDanger() then
                                guard.standLock = nil

                                onUnsafe()
                                lockOn()
                            end
                        end
                        if not engaged and scroomsIn(cf.Position, A2_ENGAGE_RANGE, A2_SCROOM_Y) > 0 then
                            engaged = true
                        end
                        if manaTrained() then
                            if manaTrain then
