                            local mhum = mc and mc:FindFirstChildOfClass('Humanoid')

                            if mhum and mc:FindFirstChildOfClass('Tool') then
                                mhum:UnequipTools()
                            end

                            local mana = mc and mc:FindFirstChild('Mana')
                            local manaApi = ctx.State.mana
                            local canCycle = manaUnlocked() and mana ~= nil and manaApi ~= nil and manaApi.available()

                            if canCycle and mana.Value <= 2 then
                                manaApi.chargeUntil(100, function()
                                    return running and not manaTrained()
                                end)
                            end
                            if engaged then
                                leftClick(3)
                            end
                        elseif engaged then
                            leftClick(3)
                        end

                        local w = 0

                        while running and w < 0.5 do
                            task.wait(0.1)

                            w += 0.1
                        end
                    end

                    guard.standLock = nil

                    zOffsetStop()
                    setBusy(false)
                end
                local function airHold(pos, secs, speed, noclipTravel)
                    smoothTeleport(pos, speed, not noclipTravel)
