                local function gatherAndLead(gatherRadius)
                    local picked = gatherScrooms(GATHER_CENTER, gatherRadius)

                    if not running then
                        return picked
                    end

                    local alive = 0

                    for _, hrp in (picked or {})do
                        if not scroomGone(hrp) and math.abs(hrp.Position.Y - A2_SCROOM_Y) <= A2_SCROOM_Y_TOL then
                            alive += 1
                        end
                    end

                    if alive == 0 then
                        dbg('A2: nothing survived the pull, skipping the lead')

                        return {}
                    end

                    for i, leg in A2_LEAD do
                        if not running then
                            return
                        end
                        if ctx.State.progA2Fallen() then
                            return {}
                        end

                        airHold(leg[1], leg[2], A2_HERD_SPEED, i == 1)
                    end

                    if not running then
                        return
                    end

                    airHold(Vector3.new(2000, A2_LEAD_Y, -2312), 3, A2_HERD_SPEED)

                    return picked
                end
                local function killCycle(gatherRadius, manaTrain)
                    local standCF = A2_STAND_CF()
                    local killed, pulled = 0, 0
                    local counted = {}

                    for round = 1, 4 do
                        if not running or ctx.State.a2FleeDue() then
                            return killed, pulled
