                        ctx.State.progA2Fallen()

                        local pw = 0

                        while running and scroomsIn(GATHER_CENTER, gatherRadius, A2_SCROOM_Y) == 0 and pw < 1.5 do
                            task.wait(0.15)

                            pw += 0.15
                        end

                        if scroomsIn(GATHER_CENTER, gatherRadius, A2_SCROOM_Y) == 0 then
                            dbg('A2: nothing in the pit, skipping the gather')

