                        local seen, gone, acc = {}, {}, 0
                        local track = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                            dt
                        )
                            acc += dt

                            if acc < 0.25 then
                                return
                            end

                            acc = 0

                            local r = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
                            local live = Workspace:FindFirstChild('Live')

                            if not (r and live) then
                                return
                            end

                            for _, obj in live:GetChildren()do
                                if string.find(obj.Name, 'Zombie Scroom') and not seen[obj] then
                                    local h = obj:FindFirstChild('HumanoidRootPart')
                                    local hum = obj:FindFirstChildOfClass('Humanoid')

                                    if h and hum and (h.Position - r.Position).Magnitude <= A2_COUNT_RADIUS then
                                        seen[obj] = hum
                                    end
                                end
                            end
                            for obj, hum in seen do
                                if obj.Parent ~= live or hum.Health <= A2_DEAD_HP then
                                    gone[obj] = true
                                end
                            end
                        end))
                        local training = manaTrain and not manaTrained()

                        if training then
                            local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                            if hum then
                                hum:UnequipTools()
                            end
                        else
                            equipSword()
                        end

                        standAndAttack(training and (standCF + standCF.LookVector * A2_PUNCH_OFFSET) or standCF, a2Retreat, training)

                        if not (manaTrain and not manaTrained()) then
                            local passes = 0

                            while running and scroomsIn(standCF.Position, 50, A2_SCROOM_Y) > 0 and passes < 4 do
                                if scroomsIn(standCF.Position, A2_MELEE_HOLD, A2_SCROOM_Y) == 0 then
                                    gatherAndLead(gatherRadius)
                                end
                                if not running then
                                    break
                                end

                                standAndAttack(standCF, a2Retreat, false)

                                passes += 1
                            end
                        end

                        pcall(function()
                            track:Disconnect()
                        end)

                        local live = Workspace:FindFirstChild('Live')
                        local roundKills, tracked, hpLeft = 0, 0, {}

                        for obj, hum in seen do
                            tracked += 1

                            if gone[obj] or obj.Parent ~= live or hum.Health <= A2_DEAD_HP then
                                if not counted[obj] then
                                    counted[obj] = true

                                    roundKills += 1
                                end
                            else
                                table.insert(hpLeft, string.format('%.0f', hum.Health))
                            end
                        end

                        pulled += tracked
                        killed += roundKills

                        dbg(
[[A2: round %d engaged %d (picked %d), %d dead, %d alive within 50 (hp left: %s)]], round, tracked, picked and #picked or 0, roundKills, scroomsIn(standCF.Position, 50, A2_SCROOM_Y), #hpLeft > 0 and table.concat(hpLeft, ', ') or 'none')
                    end

                    return killed, pulled
                end
                local function dwell(seconds, untilScrooms)
                    startHoldBlock()

                    local live = untilScrooms and Workspace:FindFirstChild('Live')
                    local bell = false
                    local conn = live and live.ChildAdded:Connect(function(obj)
                        if string.find(obj.Name, 'Zombie Scroom') then
                            bell = true
                        end
                    end)
                    local t = 0

                    while running and t < seconds do
                        task.wait(0.25)

                        t += 0.25

                        if bell then
                            bell = false

                            task.wait(1.5)

                            t += 1.5

                            if scroomsIn(GATHER_CENTER, A2_GATHER_RADIUS, A2_SCROOM_Y) > 0 then
                                dbg('A2: scrooms respawned, going down early')

                                break
                            end
                        end
                    end

                    if conn then
                        pcall(function()
                            conn:Disconnect()
                        end)
                    end

                    stopHoldBlock()
                end
                local function sectionA2()
                    dbg('P5: section A2 (zombie scrooms)')

                    state = state or {}

                    if state.a2resume and not near(A2_STAGE, PATH_MAX_LEG) then
                        dbg(
[[P5: resuming but nowhere near the pit, taking the Oresfall route instead]])

                        state.a2resume = nil
                    end
                    if not state.a2resume then
                        if not setInn('Oresfall') and running then
                            dbg(
[[P5: the Oresfall bind did not take, trying again from Oresfall]])
                            pathTo({
                                Vector3.new(2955, 257, -26),
                            })
                            setInn('Oresfall')
                        end

                        local walkedToDormin = not (state.done and state.done.p5_dormin)

                        once('p5_dormin', function()
                            pathTo({
                                Vector3.new(2955, 257, -26),
                                Vector3.new(2848, 256, 73),
                                Vector3.new(2852, 287, 76),
                            })

                            return talkConfirm('Dormin', Vector3.new(2852, 287, 76), {
                                'Of course.',
                            }, DORMIN_DONE, 5)
                        end)
                        ctx.State.progWaitDanger()

                        if state.boundInn == 'Oresfall' then
                            if walkedToDormin then
                                reset()
                            end

                            pathTo(A2_PATH)
                        elseif running and not near(A2_STAGE, 150) then
                            dbg('P5: no Oresfall bind, menu teleporting to the pit')
                            waitMenuReady(25, true)

                            local landed = Menu.menuTele(A2_STAGE, function()
                                return running
                            end)

                            if not landed and running then
                                dbg(
[[P5: the menu teleport to the pit did not take, walking the Oresfall route instead]])
                                pathTo(A2_PATH)
                            end
                        end
                    end

                    state.a2resume = nil

                    if not manaTrained() then
                        dbg(
[[P5: no CanClimb yet, punching until the bar is up and CanClimb lands (bar %s)]], manaUnlocked() and 'up' or 'hidden')
                        skipNote('no CanClimb yet, punching scrooms for mana')
                    end

                    state.a2kills = tonumber(state.a2kills) or 0

                    local firstPass = true
                    local empties, barren = 0, 0
                    local pitChecked = false
                    local awaitRespawn = false

                    while running and state.a2kills < A2_KILL_TARGET do
                        if ctx.State.a2FleeDue() then
                            dbg(
[[P5: players closed in on the pit, going straight up to the perch]])

                            state.a2resume = true

                            saveState()

                            local caught = rosterLines(ctx, getRogue, A2_FLEE_WATCH, A2_FLEE_RADIUS)
                            local perch = A2_FLEE_PATH[A2_FLEE_PERCH]

                            smoothTeleport(perch)

                            local waited = 0

                            while running and inDanger() and waited < A2_FLEE_HOLD_MAX do
                                holdAt(perch, 2)

                                waited += 2
                            end

                            if inDanger() then
                                dbg('P5: still tagged after %ds on the perch, hopping anyway', waited)
                            end
                            if not progressionServerhop('players closed in on the A2 pit', A2_FLEE_WATCH, A2_FLEE_RADIUS, '@here', caught) then
                                dbg('P5: nothing hopped, coming down the high route to the stage')

                                for i = A2_FLEE_PERCH + 1, #A2_FLEE_PATH do
                                    if not running then
                                        break
                                    end

                                    smoothTeleport(A2_FLEE_PATH[i])
                                end

                                while running and ctx.State.a2FleeDue() do
                                    task.wait(2)
                                end
                            end

                            return false
                        end

                        dbg('P5: %d of %d zombie scrooms killed', state.a2kills, A2_KILL_TARGET)

                        local manaTrain = not manaTrained()
                        local firstDescent = firstPass

                        if firstPass then
                            firstPass = false

                            pathTo({A2_STAGE})
                            dwell(awaitRespawn and 16 or 8, awaitRespawn)

                            awaitRespawn = false

                            if not running then
                                break
                            end
                        else
                            pathTo(A2_CYCLE_A)
                            dwell(16, true)

                            if not running then
                                break
                            end
                        end
                        if not running then
                            break
                        end
                        if not pitChecked then
                            pitChecked = true

                            if hostileNear(PIT_CENTER, A2_PIT_CLEAR) then
                                dbg('P5: players at the pit, leaving before we descend')
                                pathTo({A2_STAGE})

                                state.a2resume = true

                                saveState()

                                if not progressionServerhop('players at the A2 pit', PIT_CENTER, A2_PIT_CLEAR) then
                                    dbg(
[[P5: nothing hopped, holding at the stage until the pit clears]])

                                    while running and hostileNear(PIT_CENTER, A2_PIT_CLEAR) do
                                        task.wait(2)
                                    end
                                end

                                return false
                            end
                        end

                        pathTo(firstDescent and A2_ENTRY or A2_CYCLE_B)

                        local killed, pulled = killCycle(A2_GATHER_RADIUS, manaTrain)

                        state.a2kills += killed

                        saveState()

                        if pulled > 0 and killed == 0 then
                            barren += 1

                            if barren >= A2_BARREN_LIMIT then
                                stopNote(string.format('%s pulled scrooms %dx without a kill, check it has a sword', label(), barren))
                                hardStop('A2 dealt no damage for ' .. barren .. ' rounds')

                                return
                            end
                        else
                            barren = 0
                        end
                        if pulled == 0 then
                            empties += 1

                            if empties >= 2 then
                                pathTo({A2_STAGE})

                                state.a2resume = true

                                saveState()

                                if not progressionServerhop('A2 pit stayed empty') then
                                    dbg(
[[P5: nothing hopped, waiting at the stage for the pit to repopulate]])
                                    dwell(30, true)

                                    empties = 0
                                    firstPass = true
                                    awaitRespawn = true

                                    continue
                                end

                                return false
                            end

                            dbg('A2: pit empty, waiting at the stage for a respawn')

                            firstPass = true
                            awaitRespawn = true
                        else
                            empties = 0
                            awaitRespawn = false
                        end
                    end

                    local finished = running and (tonumber(state.a2kills) or 0) >= A2_KILL_TARGET

                    if finished then
                        state.a2kills = nil

                        saveState()
                    end

                    return finished
                end
                local function phaseP5()
                    if not hasTool('Sword') then
                        dbg('P5: no sword in the pack, dropping back to P4 to buy one')

                        state.a2resume = nil

                        setPhase('P4')

                        return
                    end

                    do
                        local thrown = Workspace:FindFirstChild('Thrown')

                        if thrown then
                            local part = Make('Part', {
                                Name = 'Part',
                                Anchored = true,
                                CanCollide = true,
                                Size = Vector3.new(579, 1, 457),
                                CFrame = CFrame.new(2078.95801, 110.362061, -2296.52441),
                                Color = Color3.fromRGB(0, 0, 255),
                                Material = Enum.Material.Neon,
                                Parent = thrown,
                            })

                            guard.p5part = part
                        end
                    end

                    local necro = findNecro()
                    local farmed

                    if necro then
                        farmed = sectionA1(necro)
                    else
                        farmed = sectionA2()
                    end

                    guard.p5part = nil

                    if not farmed then
                        dbg('P5: the XP farm did not finish, staying on P5')

                        return
                    end

                    setPhase('P6')
                end
                local function phaseP6()
                    state = state or {}
                    state.done = state.done or {}

                    local done = state.done
                    local need = {}

                    if not done.p6_alana and not hasTool('Health Potion') then
                        table.insert(need, 'Health Potion')
                    end
                    if not done.p6_kothe and not hasTool('Liquid Wisdom') then
                        table.insert(need, 'Liquid Wisdom')
                    end
                    if not hasTool('Ice Protection') then
                        table.insert(need, 'Ice Protection')
                    end
                    if #need > 0 then
                        stopNote('missing ' .. table.concat(need, ', ') .. ', give them and Start again')
                        waitMenuOut()
                        pcall(function()
                            local rtm = requestRemote('ReturnToMenu')

                            if rtm then
                                rtm:InvokeServer()
                            end
                        end)
                        hardStop('missing potions for P6: ' .. table.concat(need, ', '))

                        return
                    end

                    ctx.State.progPackSettled()
                    settleForAny(ALFRIC_SKILLS, SKILL_SETTLE_LONG)

                    if #missingFrom(ALFRIC_SKILLS) == 0 then
                        dbg('P6: Alfric already maxed, skipping')
                    elseif done.alfric then
                        dbg(
[[P6: Alfric reads %s missing but the step is already done, not going back to Renova]], table.concat(missingFrom(ALFRIC_SKILLS), ', '))
                    else
                        dbg('P6: Alfric missing %s', table.concat(missingFrom(ALFRIC_SKILLS), ', '))

                        if near(A2_STAND_POS, 600) then
                            pathTo({
                                Vector3.new(1965, 143, -2283),
                                Vector3.new(1920, 205, -2237),
                            })
                        end

                        setInn('Renova')
                        once('alfric', function()
                            ctx.State.progPackSettled()
                            pathTo({
                                Vector3.new(-2068, 305, -634),
                                Vector3.new(-1844, 252, -265),
                                Vector3.new(-1805, 315, -227),
                            })

                            for _ = 1, 8 do
                                if not running or #missingFrom(ALFRIC_SKILLS) == 0 then
                                    break
                                end

                                talkTo('Alfric', Vector3.new(-1805, 315, -227), {
                                    'Yeah.',
                                    "I'll pay.",
                                })
                                task.wait(0.4)
                            end

                            if #missingFrom(ALFRIC_SKILLS) > 0 then
                                skipQuiet('Alfric still owes ' .. table.concat(missingFrom(ALFRIC_SKILLS), ', ') .. '')

                                return false
                            end

                            return true
                        end)
                    end
                    if not (done.p6_dormin and done.p6_alana) then
                        setInn('Oresfall')
                        once('p6_dormin', function()
                            pathTo({
                                Vector3.new(2955, 257, -26),
                                Vector3.new(2848, 256, 73),
                                Vector3.new(2852, 287, 76),
                            })

                            return talkConfirm('Dormin', Vector3.new(2852, 287, 76), {
                                'Of course.',
                            }, DORMIN_DONE, 5)
                        end)

                        if hasTool('Health Potion') then
                            once('p6_alana', function()
                                pathTo({
                                    Vector3.new(2862, 255, 72),
                                    Vector3.new(2792, 252, -44),
                                    Vector3.new(2809, 303, -33),
                                })

                                for _ = 1, 5 do
                                    if not running or not hasTool('Health Potion') then
                                        break
                                    end

                                    local _, alreadyDone = talkTo('Alana', Vector3.new(2809, 303,
-33), {
                                        "What's wrong?",
                                        "I'm here to help.",
                                        "I'm sorry to hear that.",
                                        'Of course.',
                                    }, ALANA_DONE)

                                    if alreadyDone then
                                        break
                                    end

                                    local _, _, gaveIt = talkTo('Alana', Vector3.new(2809, 303,
-33), {
                                        'Would this potion be of any use?',
                                    }, ALANA_DONE, ALANA_GAVE)

                                    if gaveIt then
                                        break
                                    end
                                    if hasTool('Health Potion') then
                                        task.wait(1.5)
                                    end
                                end

                                if hasTool('Health Potion') then
                                    skipQuiet('Alana never took the Health Potion')

                                    return false
                                end

                                return true
                            end)
                        elseif not done.p6_alana then
                            skipNote('skipped Alana: no Health Potion in the pack')
                        end
                    end
                    if not done.p6_lachesis then
                        setInn('Southern Sanctuary')
                        once('p6_lachesis', function()
                            pathTo({
                                Vector3.new(-1291, 143, 323),
                            })

                            return talkConfirm('Lachesis', Vector3.new(-1291, 143, 323), {
                                "What's the matter?",
                                "It's no problem. Can I help?",
                                'Is it a scroom?',
                                'Glad to help.',
                            }, LACHESIS_DONE, 4)
                        end)
                    end

                    local freyMaxed = done.frey or #missingFrom(FREY_SKILLS) == 0
                    local kotheSpot = Vector3.new(1923, 258, -850)

                    if done.p6_kothe and freyMaxed then
                        dbg('P6: Kothe done and Frey maxed, skipping Central Sanctuary')
                    else
                        if not near(kotheSpot, 150) then
                            ctx.State.progWaitDanger()
                            setBusy(true)
                            waitMenuReady(25, true)

                            local landed = Menu.menuTele(kotheSpot, function()
                                return running
                            end)

                            setBusy(false)

                            if not landed then
                                if running and not (Toggles.ProgStayInServer and Toggles.ProgStayInServer.Value) then
                                    progressionServerhop('the menu teleport to Central Sanctuary did not take')
                                end

                                return
                            end
                        end
                        if not done.p6_kothe then
                            proximityGraceUntil = math.huge

                            local packWait = 0

                            while running and not hasTool('Liquid Wisdom') and packWait < 25 do
                                task.wait(0.1)

                                packWait += 0.1
                            end

                            if hasTool('Liquid Wisdom') then
                                once('p6_kothe', function()
                                    pathTo({
                                        Vector3.new(1923, 258, -850),
                                    })

                                    for _ = 1, 5 do
                                        if not running or not hasTool('Liquid Wisdom') then
                                            break
                                        end

                                        talkTo('Kothe', Vector3.new(1923, 258, -850), {
                                            "What's wrong?",
                                            'Can I help?',
                                            "There's something else I can help with, then?",
                                        }, KOTHE_DONE)

                                        local _, _, gaveIt = talkTo('Kothe', Vector3.new(1923, 258,
-850), {
                                            'Is this it?',
                                        }, KOTHE_DONE, KOTHE_GAVE)

                                        if gaveIt then
                                            break
                                        end
                                        if hasTool('Liquid Wisdom') then
                                            task.wait(1.5)
                                        end
                                    end

                                    if hasTool('Liquid Wisdom') then
                                        skipQuiet('Kothe never took the Liquid Wisdom')

                                        return false
                                    end

                                    return true
                                end)
                            else
                                stopNote(label() .. ': no Liquid Wisdom found in backpack for Kothe')
                                hardStop('no Liquid Wisdom found in backpack')

                                return
                            end

                            proximityGraceUntil = tick()
                        end
                        if not freyMaxed then
                            local freyRefused, freyDone = false, false

                            once('frey', function()
                                ctx.State.progPackSettled()
                                pathTo({
                                    Vector3.new(1921, 258, -851),
                                    Vector3.new(1926, 285, -864),
                                    Vector3.new(1905, 285, -810),
                                    Vector3.new(1913, 307, -813),
                                    Vector3.new(1955, 309, -830),
                                })

                                for _ = 1, 8 do
                                    if not running or #missingFrom(FREY_SKILLS) == 0 then
                                        break
                                    end

                                    local _, wasDone, refused = talkTo('Frey', Vector3.new(1954, 309,
-833), {
                                        'Is there anything you can teach me?',
                                        "I'll pay.",
                                    }, FREY_DONE, FREY_REFUSED)

                                    if wasDone then
                                        freyDone = true

                                        break
                                    end
                                    if refused then
                                        freyRefused = true
                                        skipReason = 'Frey says the character is not prepared'

                                        break
                                    end

                                    task.wait(0.4)
                                end

                                return freyDone or #missingFrom(FREY_SKILLS) == 0
                            end)

                            if running and freyRefused then
                                local unfinished = {}

                                for _, key in {
                                    'p6_dormin',
                                    'p6_alana',
                                    'p6_lachesis',
                                    'p6_kothe',
                                }do
                                    if not done[key] then
                                        table.insert(unfinished, key)
                                    end
                                end

                                stopNote(string.format('%s is short of orderly, Frey refused the training', label()), {
                                    '**Orderly quests not marked done**',
                                    #unfinished > 0 and table.concat(unfinished, ', ') or
[[none, so the Tespian loop fell short or a quest was done by hand without registering]],
                                })
                                hardStop('Frey refused the training')

                                return
                            end
                            if running and not done.frey and #missingFrom(FREY_SKILLS) > 0 then
                                local owed = table.concat(missingFrom(FREY_SKILLS), ', ')
                                local silver = tonumber(getServerValue('Silver')) or 0

                                if silver >= FREY_COST then
                                    stopNote('Frey still owes ' .. owed .. ' (' .. tostring(silver) .. ' silver), hopping')
                                    progressionServerhop('Frey did not teach ' .. owed)
                                else
                                    stopNote('Frey still owes ' .. owed .. ', only ' .. tostring(silver) .. ' silver, stopping')
                                    hardStop('out of silver for Frey')
                                end

                                return
                            end
                        end
                    end

                    local function findTurnip()
                        for _, pool in {
                            LocalPlayer:FindFirstChildOfClass('Backpack'),
                            LocalPlayer.Character,
                        }do
                            if pool then
                                for _, item in pool:GetChildren()do
                                    if item.Name == 'Turnip' then
                                        return item
                                    end
                                end
                            end
                        end

                        return nil
                    end
                    local function waitForTurnip(timeout)
                        if findTurnip() then
                            return true
                        end

                        local bp = LocalPlayer:FindFirstChildOfClass('Backpack')
                        local got = false
                        local conn = bp and bp.ChildAdded:Connect(function(
                            child
                        )
                            if child.Name == 'Turnip' then
                                got = true
                            end
                        end)
                        local t = 0

                        while running and not got and t < (timeout or 15) do
                            task.wait(0.2)

                            t += 0.2

                            got = got or findTurnip() ~= nil
                        end

                        if conn then
                            conn:Disconnect()
                        end

                        return got
                    end

                    if not (done.p6_draug and done.p6_dorgoth and done.p6_reynauld) then
                        setInn('Castle Sanctuary')
                        once('p6_draug', function()
                            pathTo({
                                Vector3.new(6145, 1344, 118),
                            })

                            return talkConfirm('Draug', Vector3.new(6145, 1344, 118), {
                                'Thank you.',
                            }, DRAUG_DONE, 4)
                        end)
                        once('p6_dorgoth', function()
                            local held = findTurnip()

                            if held then
                                dbg('P6: Turnip already held (%s in %s), skipping Dorgoth', held.ClassName, held.Parent and held.Parent.Name or '?')

                                return
                            end

                            pathTo({
                                Vector3.new(6142, 1344, 93),
                            })

                            for _ = 1, 2 do
                                if not running or findTurnip() then
                                    break
                                end

                                talkTo('Dorgoth', Vector3.new(6142, 1344, 93), {
                                    'Alright.',
                                })
                                waitForTurnip(15)
                            end

                            if not findTurnip() then
                                skipQuiet('Dorgoth did not hand over the Turnip')

                                return false
                            end

                            return true
                        end)
                        once('p6_reynauld', function()
                            pathTo({
                                Vector3.new(6380, 1334, -213),
                                Vector3.new(6293, 1121, -459),
                                Vector3.new(6294, 1039, -756),
                                Vector3.new(6122, 1039, -755),
                                Vector3.new(6090, 1067, -755),
                                Vector3.new(5658, 1067, -1166),
                                Vector3.new(5342, 1067, -1108),
                                Vector3.new(4921, 1067, -861),
                                Vector3.new(4953, 544, -900),
                            })

                            local _, wasDone, gave = talkTo('Reynauld', Vector3.new(4953, 544,
-900), {
                                'Hello?',
                                'Sir?',
                            }, ELLIPSIS_DONE, REYNAULD_GAVE)

                            if not (gave or wasDone) then
                                skipQuiet(
[[Reynauld never collapsed, so the dagger was never handed over]])

                                return false
                            end

                            return true
                        end)
                    end
                    if not done.p6_hespe then
                        setInn('Southern Sanctuary')
                        once('p6_hespe', function()
                            pathTo({
                                Vector3.new(-476, 169, 854),
                                Vector3.new(-283, 491, 936),
                            })

                            local everOffered = false

                            for _ = 1, 3 do
                                if not running then
                                    return false
                                end

                                local _, wasDone, gave, offered = talkTo('Hespe', Vector3.new(
-283, 491, 936), {
                                    'A man told me to bring this to you.',
                                    '...',
                                }, ELLIPSIS_DONE, HESPE_GAVE)

                                if wasDone or gave then
                                    return true
                                end

                                everOffered = everOffered or offered ~= nil

                                task.wait(1)
                            end

                            skipQuiet(everOffered and 'Hespe never gave his closing line' or 'no dagger to hand over, Reynauld never gave it')

                            return false
                        end)
                    end
                    if not done.p6_brom then
