                local function spamFirstChoice(npc, maxClicks, timeout)
                    local requests = ReplicatedStorage:FindFirstChild('Requests')
                    local cd = npc and npc:FindFirstChildWhichIsA('ClickDetector', true)

                    if not (requests and cd and fireclickdetector) then
                        dbg('spamFirstChoice: unavailable (requests=%s cd=%s fcd=%s)', tostring(requests ~= nil), tostring(cd ~= nil), tostring(fireclickdetector ~= nil))

                        return
                    end

                    local clicks, lastEvent, conns = 0, 0, {}

                    for _, remote in requests:GetChildren()do
                        if remote:IsA('RemoteEvent') then
                            table.insert(conns, remote.OnClientEvent:Connect(function(
                                data
                            )
                                if type(data) ~= 'table' or (data.choices == nil and data.speaker == nil) then
                                    return
                                end

                                lastEvent = tick()

                                local pick = type(data.choices) == 'table' and data.choices[1] or nil
                                local answer = (type(pick) == 'string' and {choice = pick}) or (type(data.endchoice) == 'string' and {exit = true}) or nil

                                if answer then
                                    clicks += 1

                                    task.delay(DIALOGUE_REPLY_MIN + math.random() * DIALOGUE_REPLY_JITTER, function(
                                    )
                                        pcall(function()
                                            remote:FireServer(answer)
                                        end)
                                    end)
                                end
                            end))
                        end
                    end

                    fireclickdetector(cd)

                    local started = tick()

                    while clicks < (maxClicks or 15) and tick() - started < (timeout or 25) do
                        task.wait(0.5)

                        if tick() - lastEvent > 3 then
                            fireclickdetector(cd)

                            lastEvent = tick()
                        end
                    end

                    dbg('spamFirstChoice: %d choices answered', clicks)

                    for _, c in conns do
                        pcall(function()
                            c:Disconnect()
                        end)
                    end
                end

                ctx.State.progYaaldaHandoff = function()
                    for attempt = 1, KHEI_HANDOFF_TRIES do
                        if not running then
                            return
                        end

                        local npcs = Workspace:FindFirstChild('NPCs')
                        local yaalda = npcs and npcs:FindFirstChild('Yaalda')
                        local yhrp = yaalda and yaalda:FindFirstChild('HumanoidRootPart')

                        if yhrp then
                            dbg('finish: Yaalda handoff attempt %d/%d', attempt, KHEI_HANDOFF_TRIES)

                            local landed = menuTele(function()
                                local n = Workspace:FindFirstChild('NPCs')
                                local y = n and n:FindFirstChild('Yaalda')
                                local h = y and y:FindFirstChild('HumanoidRootPart')

                                return h and h.Position or nil
                            end, 1)

                            if landed then
                                spamFirstChoice(yaalda, 15, 75)
                            else
                                dbg(
[[finish: the teleport to Yaalda did not take, not clicking from here]])
                            end
                        else
                            dbg('finish: Yaalda not in workspace.NPCs (attempt %d/%d)', attempt, KHEI_HANDOFF_TRIES)
                        end

                        task.wait(3)

                        if attempt >= PING_HOP_AFTER and pingMs() > PING_HOP_LIMIT and not (Toggles.ProgStayInServer and Toggles.ProgStayInServer.Value) then
                            dbg(
[[finish: %.0fms ping after %d tries - hopping to retry the handoff elsewhere]], pingMs(), attempt)

                            if progressionServerhop(string.format('%.0fms ping stalling the Khei handoff', pingMs())) then
                                return
                            end
                        end
                    end

                    if not running then
                        return
                    end

                    haltNote(string.format('Khei: Yaalda never took the handoff after %d tries', KHEI_HANDOFF_TRIES))
                    MemStore.remove('khei_run')
                    MemStore.remove('khei_handoff_servers')
                    idleUI()

                    if stop then
                        stop()
                    end
                end
                ctx.State.progKheiHandoff = function()
                    if running then
                        return
                    end

                    local servers = (tonumber(MemStore.get('khei_handoff_servers')) or 0) + 1

                    MemStore.set('khei_handoff_servers', servers)

                    if servers > KHEI_HANDOFF_SERVERS then
                        dbg('khei: handoff gave up after %d servers', servers - 1)
                        MemStore.remove('khei_run')
                        MemStore.remove('khei_handoff_servers')
                        task.spawn(function()
                            haltNote(string.format('Khei: could not hand off to Yaalda across %d servers', KHEI_HANDOFF_SERVERS))
                        end)

                        return
                    end

                    running = true
                    hopCommitted = false
                    ctx.State.progHalted = false

                    setStopVisible(true)
                    setStartVisible(false)
                    arm()
                    task.spawn(ctx.State.progYaaldaHandoff)
                end

                local function finishProgression()
                    if not running then
                        return
                    end
                    if not settleForAny(JAGEN_SKILLS, SKILL_SETTLE_LONG) then
                        dbg('P7: no Jagen training, refusing to mark DONE')
                        task.spawn(function()
                            haltNote('no Jagen training, stopped at P7')
                        end)

                        if stop then
                            stop()
                        end

                        return
                    end

                    local goKhei = Toggles.ProgGoToKhei and Toggles.ProgGoToKhei.Value

                    if goKhei and not hasManaDash() then
                        dbg('P7: no Mana Dash, refusing the Khei handoff')
                        task.spawn(function()
                            haltNote('no Mana Dash, stopping')
                        end)

                        if stop then
                            stop()
                        end

                        return
                    end

                    state = state or {}

                    local endSilver = getServerValue('Silver')

                    if goKhei then
                        local sname, sregion = serverInfo(5)

                        infoNote('Gaia complete', string.format("%s finished Gaia, heading to Khei via Ya'alda", label()))
                    else
                        pcall(ProgHook.embedWith, '@everyone', progEmbed('Auto Progression complete', 0x57f287, {
                            string.format('**Day:** `%s`', tostring(getServerValue('DaysSurvived'))),
                            '**Next:** `returning to menu`',
                        }, {
                            {
                                name = 'Time Taken',
                                value = timeBlock(state.startClock, state.kheiClock),
                                inline = true,
                            },
                            {
                                name = 'Silver',
                                value = silverBlock(state.startSilver, endSilver),
                                inline = true,
                            },
                        }))
                    end

                    state.phase = 'DONE'

                    if goKhei then
                        state.kheiClock = state.kheiClock or os.time()
                    end

                    saveState()
                    MemStore.remove('progression_active')
                    restoreToggles()

                    if goKhei then
                        dbg('finish: auto-going to Khei via Yaalda')
                        MemStore.set('khei_run', 'true')
                        ctx.State.progYaaldaHandoff()

                        return
                    end

                    local old = ctx.State.progKillWhenClear()

                    if not old then
                        dbg('finish: no character to reset, leaving it standing')
                        idleUI()

                        running = false

                        return
                    end

                    local w = 0

                    repeat
                        task.wait(0.3)

                        w += 0.3
                    until (LocalPlayer.Character and LocalPlayer.Character ~= old and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')) or w > 15 or not running

                    waitMenuOut()

                    local rtm = requestRemote('ReturnToMenu')

                    if rtm then
                        pcall(function()
                            rtm:InvokeServer()
                        end)
                    end

                    idleUI()

                    running = false
                end
                local function orderlyRun()
                    setInn('Oresfall')
