                    local function reachSkycastle()
                        local function up()
                            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                            return hrp ~= nil and hrp.Position.Y > SKYCASTLE_Y
