                    local function lilinLetter()
                        if not near(LILIN_SPOT, 600) and setInn('Flowerlight Town') == false then
                            return false
                        end
                        if not pathTo(LILIN_PATH) then
                            return false
                        end

                        talkTo('Lilin', LILIN_SPOT, {})

                        if not (running and pathTo(LILIN_TO_HAND)) then
                            return false
                        end

                        talkTo('Toilet Hand', HAND_SPOT, {
                            '...?',
                        })

                        if not (running and pathTo(HAND_TO_LILIN)) then
                            return false
                        end

                        talkTo('Lilin', LILIN_SPOT, {
                            'Are you okay?',
                        })

                        local gotLetter = settleForAny({
                            'Love Letter',
                        })

                        if not (running and pathTo(LILIN_TO_HAND)) then
                            return false
                        end
                        if not gotLetter then
                            local _, delivered = talkTo('Toilet Hand', HAND_SPOT, {}, TOILET_DONE)

                            if delivered then
                                return true
                            end

                            skipQuiet('Lilin never handed the letter over')

                            return false
                        end

                        local startHum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                        if startHum then
                            pcall(function()
                                startHum:UnequipTools()
                            end)
                        end

                        local function holdLetter()
                            local char = LocalPlayer.Character

                            if char and char:FindFirstChild('Love Letter') then
                                return
                            end

                            local hum = char and char:FindFirstChildOfClass('Humanoid')
                            local bag = LocalPlayer:FindFirstChildOfClass('Backpack')
                            local letter = bag and bag:FindFirstChild('Love Letter')

                            if hum and letter then
                                hum:EquipTool(letter)
                            end
                        end

                        for _ = 1, 3 do
                            if not running then
                                return false
                            end

                            talkTo('Toilet Hand', HAND_SPOT, {
                                'Here.',
                            }, TOILET_DONE, nil, function(pick)
                                if pick == 'Here.' then
                                    holdLetter()
                                end
                            end)

                            local waited = 0

                            while running and hasTool('Love Letter') and waited < LETTER_GONE_WAIT do
                                task.wait(0.25)

                                waited += 0.25
                            end

                            if not hasTool('Love Letter') then
                                return true
                            end
                        end

                        skipQuiet('the Toilet Hand would not take the letter')

                        return false
                    end

                    once('p7_lilin', lilinLetter)
                end
                local function section1()
                    dbg('P7: section 1 (day >= 1)')

                    if (state.done and state.done.jagen) or settleForAny(JAGEN_SKILLS) then
                        markOrderlyDone()
                        dbg(
[[P7: Jagen training already held, going straight back for Mana Dash]])
                    else
                        orderlyRun()

                        if not running then
                            return
                        end
                    end
                    if state.done and state.done.jagen and hasManaDash() then
                        dbg(
[[P7: Jagen training and Mana Dash already held, not going back to Jagen]])
                        finishProgression()

                        return
                    end

                    setInn('Castle Sanctuary')

                    if state.p7dash and not hasManaDash() then
                        local resumed = jagenRoute(state)

                        saveState()
                        dbg('P7: resumed mid-training, walking the ledge on side %d', tonumber(state.p7side) or 0)
                        pathTo(resumed.path)
                    else
                        pathTo(JAGEN_PATH)
                    end

                    local boughtTraining = false

                    if not ((state.done and state.done.jagen) or settleForAny(JAGEN_SKILLS)) then
                        for _ = 1, 2 do
                            if not running or haveAnyOf(JAGEN_SKILLS) then
                                break
                            end

                            local _, _, refused = talkTo('Jagen', Vector3.new(6857, 1411,
-164), {
                                'Please train me.',
                                'Here is 350 Silver.',
                            }, nil, JAGEN_REFUSED)

                            if refused then
                                local skipped = {}

                                for _, key in ORDERLY_STEPS do
                                    if not (state.done and state.done[key]) then
                                        table.insert(skipped, key)
                                    end
                                end

                                stopNote(string.format('%s missed an orderly quest, Jagen refused the training', label()), {
                                    '**Unfinished steps in the cache**',
                                    #skipped > 0 and table.concat(skipped, ', ') or 'none recorded, so one was marked done without registering',
                                })
                                kheiMenuOut()
                                hardStop('Jagen refused the training')

                                return
                            end

                            task.wait(0.4)
                        end

                        boughtTraining = haveAnyOf(JAGEN_SKILLS)

                        if boughtTraining then
                            markOrderlyDone()
                        end
                    else
                        dbg('P7: Jagen training already held, skipping')
                    end
                    if not hasManaDash() then
                        state.p7dash = true

                        saveState()
                        infoNote('Training', (boughtTraining and 'Jagen training bought' or 'Jagen training already held') ..
[[, charging mana behind him until Mana Dash comes in for Khei]])
                    end

                    local route = state.p7dash and jagenRoute(state) or nil

                    if route then
                        saveState()

                        if running and not near(route.spot, 60) then
                            dbg('P7: walking the ledge on side %d', tonumber(state.p7side) or 0)
                            pathTo(route.path)
                        end
                    end

                    local dashDeadline = tick() + MANA_DASH_TIMEOUT

                    while running and route and state.p7dash and not hasManaDash() and tick() < dashDeadline do
                        if LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('ForceField') then
                            smoothTeleport(route.entry)
                            task.wait(1)
                        end
                        if not near(route.spot, 60) then
                            smoothTeleport(route.spot)
                        end
                        if hostileNear(route.spot, (Options.ProgProximity and Options.ProgProximity.Value) or 300) then
                            progressionServerhop('player near the mana training ledge', route.spot, (Options.ProgProximity and Options.ProgProximity.Value) or 300)

                            return
                        end

                        local mana = ctx.State.mana

                        if mana and mana.available and mana.available() then
                            mana.chargeUntil(100, function()
                                return running and not hasManaDash()
                            end)
                        end

                        task.wait(0.5)
                    end

                    if running and not hasManaDash() then
                        dbg('P7: Mana Dash never appeared in %ds', MANA_DASH_TIMEOUT)
                        stopNote(string.format('%s never got Mana Dash after %ds, stopping', label(), MANA_DASH_TIMEOUT))

                        if stop then
                            stop()
                        end

                        return
                    end
                    if state.p7dash then
                        state.p7dash = nil
                        state.p7side = nil

                        saveState()
                    end

                    finishProgression()
                end
                local function section2()
                    dbg('P7: section 2 dayfarm (day 0)')
                    setInn('Santorini')
                    pathTo({
                        Vector3.new(1355, 394, 2992),
                        Vector3.new(1331, 121, 3003),
                        Vector3.new(433, 121, 3583),
                    })
                    task.spawn(function()
                        local sname, sregion = serverInfo(5)

                        infoNote('Day farm', 'Waiting for day 1 before the sigil run')
                    end)

                    local gotDay = false
                    local dsc = requestRemote('DaysSurvivedChanged')

                    if dsc then
                        guard.dayFarmDay = dsc.OnClientEvent:Connect(function(
                            days
                        )
                            if days and days >= 1 then
                                gotDay = true
                            end
                        end)
                    end

                    local function intruder()
                        if Toggles.ProgStayInServer and Toggles.ProgStayInServer.Value then
                            return nil
                        end

                        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        if not hrp then
                            return nil
                        end

                        for _, p in Players:GetPlayers()do
                            local ph = p ~= LocalPlayer and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                            if ph and (ph.Position - hrp.Position).Magnitude <= 700 then
                                return p, hrp
                            end
                        end

                        return nil
                    end

                    while running and not gotDay do
                        if (getServerValue('DaysSurvived') or 0) >= 1 then
                            gotDay = true

                            break
                        end

                        local p, hrp = intruder()

                        if p then
                            guard.dayFarmDay = nil

                            saveState()
                            dbg('P7: dayfarm hop, %s within 700', p.Name)
                            hopOrDie('dayfarm: ' .. getRogue(p) .. ' within 700', hrp.Position, 700)

                            return
                        end

                        local manaApi = ctx.State.mana
                        local c = LocalPlayer.Character
                        local mana = c and c:FindFirstChild('Mana')

                        if manaApi and manaApi.available() and mana and mana.Value < 98 then
                            manaApi.chargeUntil(100, function()
                                return running and not gotDay and not intruder()
                            end)
                        end

                        task.wait(1)
                    end

                    guard.dayFarmDay = nil
                end
                local function phaseP7()
                    if (getServerValue('DaysSurvived') or 0) < 1 then
                        section2()
                    end
                    if running and (getServerValue('DaysSurvived') or 0) >= 1 then
                        section1()
                    end
                end
                local function ensureSpawned()
                    local function alive()
                        return LocalPlayer.Character ~= nil and LocalPlayer.Character:FindFirstChild('HumanoidRootPart') ~= nil
                    end

                    if alive() then
                        return
                    end

                    task.wait(2)

                    local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                    if pg and running and not alive() then
                        pg:WaitForChild('StartMenu', 45)
                    end

                    local g = 0

                    while running and not alive() and startMenu() and g < 30 do
                        clickPlay()
                        task.wait(0.5)

                        g += 0.5
                    end

                    local w = 0

                    while running and not alive() and w < 30 do
                        task.wait(0.3)

                        w += 0.3
                    end

                    if running and not alive() then
                        task.spawn(function()
                            stopNote(label() .. ' failed to spawn in, no character after Play')
                        end)
                        hardStop('failed to spawn in on new server')

                        return
                    end

                    Character.awaitPlaced(function()
                        return running
                    end, 20)
                    task.wait(5)
                end
                local function runCore()
                    if not state then
                        state = loadState() or {
                            phase = 'P0',
                            step = 0,
                        }
                    end
                    if not state.phase or state.phase == '' then
                        state.phase = 'P0'
                    end

                    dbg('runCore: starting at phase %s', tostring(state.phase))

                    local best = math.huge

                    for _ = 1, 5 do
                        local p = pingMs()

                        if p and p > 0 then
                            best = math.min(best, p)
                        end

                        task.wait(0.4)
                    end

                    local pingLimit = (Options.ProgPing and Options.ProgPing.Value) or 0

                    if running and pingLimit > 0 and best < math.huge and best > pingLimit and not (Toggles.ProgStayInServer and Toggles.ProgStayInServer.Value) then
                        dbg('runCore: %.0fms ping here, hopping for a closer server', best)

                        if progressionServerhop(string.format('%.0fms ping on arrival', best)) then
                            return
                        end
                    end

                    local twin = (Toggles.AvoidOtherBots == nil or Toggles.AvoidOtherBots.Value) and BotClaims.twinHere()

                    if running and twin and progressionServerhop('another of your bots (' .. twin.Name .. ') is already here') then
                        return
                    end

                    BotClaims.claim(game.JobId)

                    state.boundInn = nil

                    local lastPos = MemStore.getJSON('prog_lastpos')

                    if lastPos and running then
                        task.wait(1.5)

                        local prox = Options.ProgProximity and Options.ProgProximity.Value or 0

                        if prox > 0 and running then
                            local spot = Vector3.new(lastPos.x, lastPos.y, lastPos.z)

                            for _, p in Players:GetPlayers()do
                                if p ~= LocalPlayer and not friendly(ctx, p) then
                                    local ph = p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                                    if ph and (ph.Position - spot).Magnitude <= prox then
                                        dbg('resume spot occupied by %s - hopping', p.Name)

                                        if progressionServerhop('player at resume spot', spot, prox) then
                                            return
                                        end

                                        break
                                    end
                                end
                            end
                        end
                    end
                    if state.phase == 'P5' and running and hostileNear(PIT_CENTER, A2_PIT_CLEAR) then
                        dbg('P5: pit occupied on arrival, hopping again')

                        state.a2resume = true

                        saveState()

                        if progressionServerhop('A2 pit occupied on arrival', PIT_CENTER, A2_PIT_CLEAR) then
                            return
                        end
                    end

                    MemStore.remove('prog_lastpos')
                    ensureSpawned()
                    ctx.State.progPackSettled()

                    if haveAnyOf(JAGEN_SKILLS) then
                        markOrderlyDone()
                    end
                    if state.startSilver == nil then
                        state.startSilver = getServerValue('Silver')

                        saveState()
                    end

                    while running do
                        local ph = state.phase

                        if ph == 'DONE' then
                            dbg('progression complete')

                            break
                        elseif ph == 'P0' then
                            setPhase('P1')
                        elseif ph == 'P1' then
                            phaseP1()
                        elseif ph == 'P2' then
                            phaseP2()
                        elseif ph == 'P3' then
                            phaseP3()
                        elseif ph == 'P4' then
                            phaseP4()
                        elseif ph == 'P5' then
                            phaseP5()
                        elseif ph == 'P6' then
                            phaseP6()
                        elseif ph == 'KHEI' then
                            if game.PlaceId ~= KHEI_PLACE then
                                dbg('phase KHEI but this is not Khei, restarting from P0')

                                state.kheiStep = nil

                                setPhase('P0')
                            elseif ctx.State.kheiSequence then
                                ctx.State.kheiSequence()
                            else
                                break
                            end
                        elseif ph == 'P7' then
                            phaseP7()
                        else
                            dbg('phase %s not yet implemented - idling', tostring(ph))

                            while running and state.phase == ph do
                                task.wait(1)
                            end
                        end
                    end
                end

                local KHEI_SPIRE = Vector3.new(-3622, 1220, 2241)
                local KHEI_RESPAWN = Vector3.new(-1539, 621, 1888)
                local VALTER_CHOICES = {
                    'What do you mean?',
                    'How?',
                }
                local UBER_TITLE_TRIES = 3
                local UBER_TITLE_WAIT = 6
                local KHEI_VALTER_PATH = {
                    Vector3.new(-1552, 248, 1876),
                    Vector3.new(-632, 237, 1894),
                    Vector3.new(-614, 281, 1646),
                    Vector3.new(-255, 302, 1634),
                    Vector3.new(-241, 505, 1618),
                }

                local function kheiPurity(within)
                    local npcs = Workspace:FindFirstChild('NPCs')

                    if not npcs then
                        return nil
                    end

                    local model, dist = NPC.nearestModel(npcs, 'Purity', KHEI_SPIRE)

                    if not model or not dist or dist > (within or 20) then
                        return nil
                    end

                    return model, model:FindFirstChild('HumanoidRootPart')
                end
                local function touchMirror()
                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                    if not (hrp and firetouchinterest) then
                        return false
                    end

                    local mirror, best = nil, math.huge

                    for _, v in Workspace:GetDescendants()do
                        if v.Name == 'LookIntoMirror' and v:IsA('BasePart') and (v.Position - hrp.Position).Magnitude < best then
                            mirror, best = v, (v.Position - hrp.Position).Magnitude
                        end
                    end

                    if not mirror then
                        dbg('khei: LookIntoMirror not found')

                        return false
                    end
                    if best > 6 and best < 60 then
                        Character.walkTo(mirror.Position, 5, function()
                            return running
                        end, 8)

                        hrp = Character.root() or hrp
                    end

                    dbg('khei: touching the mirror from %.0f studs', (mirror.Position - hrp.Position).Magnitude)
                    pcall(function()
                        firetouchinterest(mirror, hrp, 0)
                        task.wait(0.15)
                        firetouchinterest(mirror, hrp, 1)
                    end)

                    return true
                end
                local function awaitSpireDeath()
                    local old = LocalPlayer.Character
                    local sawTag, t, respawnedAt = false, 0, nil
                    local giveUpAt = tick() + 180

                    while running and t < 40 and tick() < giveUpAt do
                        intentional()

                        local c = LocalPlayer.Character

                        if c and CollectionService:HasTag(c, 'Spired') then
                            sawTag = true
                        end
                        if c and c ~= old and c:FindFirstChild('HumanoidRootPart') then
                            respawnedAt = respawnedAt or t

                            if sawTag or t - respawnedAt >= 10 then
                                return sawTag
                            end
                        end

                        task.wait(0.3)

                        if not Danger.tagged() then
                            t += 0.3
                        end
                    end

                    return sawTag
                end
                local function kheiStep(name)
                    state = state or {}
                    state.phase = 'KHEI'
                    state.kheiStep = name

                    saveState()
                end

                ctx.State.kheiSequence = function()
                    state = state or loadState() or {}
                    state.phase = 'KHEI'
                    state.startClock = state.startClock or os.time()
                    state.kheiClock = state.kheiClock or os.time()
                    state.runId = Webhook.setRunId(state.runId)

                    saveState()

                    local step = state.kheiStep or 'inn'

                    dbg('khei: starting spire run at step %s', step)
                    ensureSpawned()

                    if not running then
                        return
                    end

                    local ls = LocalPlayer:WaitForChild('leaderstats', 15)

                    if ls then
                        ls:WaitForChild('UberTitle', 5)
                    end

                    local already = kheiUberTitle()

                    if already ~= '' then
                        dbg('khei: already titled %s, not going back to the spire', already)

                        state.kheiStep = nil
                        state.phase = 'DONE'

                        saveState()
                        infoNote('Already an uber', string.format('%s already holds %s, stopping', label(), already))

                        if stop then
                            stop()
                        end

                        return
                    end
                    if step == 'inn' then
                        local bound = false

                        for attempt = 1, KHEI_INN_TRIES do
                            if not running then
                                return
                            end

                            waitMenuReady(25, true)
                            dbg('Khei: binding Cavern Sanctuary, attempt %d/%d', attempt, KHEI_INN_TRIES)

                            if setInn('Cavern Sanctuary', true) then
                                bound = true

                                break
                            end
                            if attempt >= PING_HOP_AFTER and pingMs() > PING_HOP_LIMIT and not (Toggles.ProgStayInServer and Toggles.ProgStayInServer.Value) then
                                dbg(
[[Khei: %.0fms ping after %d inn tries - hopping to retry in a closer server]], pingMs(), attempt)
                                progressionServerhop(string.format('%.0fms ping stalling the Cavern Sanctuary bind', pingMs()))

                                return
                            end

                            task.wait(2)
                        end

                        if not bound then
                            haltNote(string.format('Khei: could not bind Cavern Sanctuary after %d tries', KHEI_INN_TRIES))

                            if stop then
                                stop()
                            end

                            return
                        end

                        kheiStep('spire')

                        step = 'spire'
                    end
                    if step == 'spire' and state.spireGiven then
                        dbg(
[[khei: the sacrifice was already given, moving on rather than spending a second life]])
                        kheiStep('valter')

                        step = 'valter'
                    end
                    if step == 'spire' then
                        local spireRoute = {
                            Vector3.new(-1539, 574, 1900),
                            Vector3.new(-1546, 328, 1941),
                            Vector3.new(-2564, 323, 1807),
                            Vector3.new(-2737, 331, 1811),
                            Vector3.new(-2912, 331, 1911),
                            Vector3.new(-3056, 338, 2042),
                            Vector3.new(-3170, 329, 2151),
                            Vector3.new(-3390, 333, 2194),
                            Vector3.new(-3617, 426, 2242),
                            Vector3.new(-3624, 1040, 2248),
                            Vector3.new(-3623, 1180, 2252),
                            Vector3.new(-3622, 1218, 2239),
                        }
                        local spireSpot = spireRoute[#spireRoute]

                        local function shielded()
                            local c = LocalPlayer.Character

                            return c ~= nil and c:FindFirstChildOfClass('ForceField') ~= nil
                        end

                        Character.awaitPlaced(function()
                            return running
                        end, 40)

                        if near(spireSpot, 40) then
                            dbg(
[[Khei: spawned back at the spire after a hop, lifting off the pad to shed the forcefield]])

                            for _ = 1, 3 do
                                if not running then
                                    break
                                end

                                smoothTeleport(Vector3.new(-3622, 1258, 2239))
                                task.wait(1)
                                smoothTeleport(spireSpot)
                                task.wait(1.5)

                                if not shielded() then
                                    break
                                end
                            end
                        else
                            resumePath = nil

                            dbg("Khei: walking the route to Flagellant's Spire")
                            pathTo(spireRoute)
                        end
                        if not running then
                            dbg('Khei: stopped while reaching the spire')

                            return
                        end
                        if not near(spireSpot, 40) then
                            haltNote("Khei: did not reach Flagellant's Spire, stopping")

                            if stop then
                                stop()
                            end

                            return
                        end

                        local purity = kheiPurity(30)

                        if not purity then
                            haltNote('Khei: no Purity NPC at the spire, stopping')

                            if stop then
                                stop()
                            end

                            return
                        end

                        for _ = 1, 3 do
                            if not running or not shielded() then
                                break
                            end

                            smoothTeleport(Vector3.new(-3626, 1340, 2244))
                            task.wait(1)
                            smoothTeleport(Vector3.new(-3622, 1218, 2248))
                            task.wait(1.5)
                        end

                        if not running then
                            return
                        end
                        if shielded() then
                            haltNote('Khei: forcefield would not drop at the spire')

                            if stop then
                                stop()
                            end

                            return
                        end

                        intentional()

                        local body = LocalPlayer.Character

                        state.spireGiven = true

                        saveState()

                        local sent = talkTo('Purity', purity:FindFirstChild('HumanoidRootPart') and purity.HumanoidRootPart.Position or KHEI_SPIRE, {
                            'I give myself.',
                            'I give my life.',
                        })

                        if not awaitSpireDeath() then
                            if not sent and LocalPlayer.Character == body then
                                dbg(
[[khei: nothing was sent and the body is untouched, so the sacrifice is still owed]])

                                state.spireGiven = nil

                                saveState()
                            end

                            haltNote('Khei: sacrificed but no Spired tag, stopping')

                            if stop then
                                stop()
                            end

                            return
                        end

                        kheiStep('valter')

                        step = 'valter'
                    end
                    if not running then
                        dbg('Khei: stopped right after the spire, before the Valter leg')

                        return
                    end

                    task.wait(2)

                    if not near(KHEI_RESPAWN, 150) then
                        dbg(
[[Khei: not at the spire exit yet, waiting for the respawn to settle]])

                        local settleUntil = tick() + SPIRE_EXIT_WAIT

                        while running and tick() < settleUntil and not near(KHEI_RESPAWN, 150) do
                            task.wait(1)
                        end
                    end
                    if running and not near(KHEI_RESPAWN, 150) then
                        dbg(
[[Khei: still away from the spire exit - teleporting back rather than stopping the run]])
                        menuTele(KHEI_RESPAWN)
                        task.wait(2)
                    end
                    if not running then
                        dbg('Khei: stopped while returning to the spire exit')

                        return
                    end

                    pathTo(KHEI_VALTER_PATH)

                    if not running then
                        dbg('Khei: stopped while pathing to Valter')

                        return
                    end

                    local valter = nearestNPC('Valter', KHEI_VALTER_PATH[#KHEI_VALTER_PATH])
                    local vhrp = valter and valter:FindFirstChild('HumanoidRootPart')
                    local me = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                    if not (vhrp and me and (vhrp.Position - me.Position).Magnitude <= 10) then
                        haltNote('Khei: Valter out of reach, stopping')

                        if stop then
                            stop()
                        end

                        return
                    end

                    local valterAt = vhrp.Position
                    local spoke = talkTo('Valter', valterAt, VALTER_CHOICES)

                    if not running then
                        dbg('Khei: stopped after talking to Valter')

                        return
                    end
                    if not spoke then
                        dbg(
[[Khei: Valter took none of the dialogue, running it once more before the mirror]])
                        task.wait(1.5)
                        talkTo('Valter', valterAt, VALTER_CHOICES)

                        if not running then
                            return
                        end
                    end

                    local touched = touchMirror()

                    for _ = 1, 3 do
                        if touched or not running then
                            break
                        end

                        task.wait(2)

                        touched = touchMirror()
                    end

                    if not touched then
                        haltNote('Khei: could not touch the mirror, stopping')

                        if stop then
                            stop()
                        end

                        return
                    end

                    task.wait(3)

                    if not running then
                        dbg('Khei: stopped after touching the mirror')

                        return
                    end

                    local title = kheiUberTitle()

                    for attempt = 1, UBER_TITLE_TRIES do
                        if title ~= '' or not running then
                            break
                        end
                        if attempt > 1 then
                            dbg(
[[Khei: still no uber title, touching the mirror again before Valter]])
                            touchMirror()
                            task.wait(1.5)
                        end

                        Character.walkTo(valterAt, 6, function()
                            return running
                        end, 8)
                        dbg(
[[Khei: no uber title after the mirror, talking to Valter again (%d/%d)]], attempt, UBER_TITLE_TRIES)
                        talkTo('Valter', valterAt, VALTER_CHOICES)

                        local deadline = tick() + UBER_TITLE_WAIT

                        while running and title == '' and tick() < deadline do
                            task.wait(0.5)

                            title = kheiUberTitle()
                        end
                    end

                    if not running then
                        dbg('Khei: stopped while waiting on the uber title')

                        return
                    end

                    state.kheiStep = nil
                    state.phase = 'DONE'

                    saveState()

                    local danger = LocalPlayer.Character ~= nil and CollectionService:HasTag(LocalPlayer.Character, 'Danger')

                    pcall(ProgHook.embedWith, '@everyone', progEmbed(title ~= '' and 'Auto Progression complete' or 'Auto Progression failed', title ~= '' and 0x57f287 or 0xed4245, {
                        string.format('**Uber:** `%s`', title ~= '' and title or 'still blank, something went wrong'),
                        string.format('**Day:** `%s`', tostring(getServerValue('DaysSurvived'))),
                    }, {
                        {
                            name = 'Time Taken',
                            value = timeBlock(state.startClock, state.kheiClock),
                            inline = true,
                        },
                        {
                            name = 'Silver',
                            value = silverBlock(state.startSilver, getServerValue('Silver')),
                            inline = true,
                        },
                    }))

                    if title == '' then
                        haltNote('Khei: no uber title, stopping')

                        if stop then
                            stop()
                        end

                        return
                    end
                    if danger or (LocalPlayer.Character and CollectionService:HasTag(LocalPlayer.Character, 'Danger')) then
                        dbg(
[[khei: tagged Danger after Valter, staying put instead of leaving]])

                        if stop then
                            stop()
                        end

                        return
                    end

                    local watched = false

                    for _, p in Players:GetPlayers()do
                        if p ~= LocalPlayer and not friendly(ctx, p) then
                            local ph = p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                            if ph and (ph.Position - KHEI_EXIT).Magnitude <= 300 then
                                watched = true

                                break
                            end
                        end
                    end

                    if watched then
                        dbg('khei: player near the exit, menuing from Valter')
                        kheiMenuOut()

                        if stop then
                            stop()
                        end

                        return
                    end

                    local old = ctx.State.progKillWhenClear()

                    if not old then
                        dbg('khei: no character at the exit, stopping')

                        if stop then
                            stop()
                        end

                        return
                    end

                    local w = 0

                    repeat
                        intentional()
                        task.wait(0.3)

                        w += 0.3
                    until (LocalPlayer.Character and LocalPlayer.Character ~= old and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')) or w > 20 or not running

                    task.wait(2)

                    if near(KHEI_EXIT, 150) then
                        pathTo({KHEI_EXIT_WALK})
                    else
                        dbg('khei: respawned away from the exit, menuing from here')
                    end

                    kheiMenuOut()

                    if stop then
                        stop()
                    end
                end

                local function kheiRun()
                    if running then
                        return
                    end

                    running = true
                    hopCommitted = false
                    ctx.State.progHalted = false

                    setStopVisible(true)
                    setStartVisible(false)
                    MemStore.set('progression_active', 'true')
                    arm()
                    task.spawn(function()
                        local ok, err = pcall(ctx.State.kheiSequence)

                        if not ok then
                            dbg('khei sequence stopped on an error: %s', tostring(err))
                            Webhook.textBounded('@everyone Auto-Sigil stopped in Khei on an error: **' .. tostring(err) .. '**')
                            stop()
                        end
                    end)
                end
                local function start(resumed)
                    if running then
                        return
                    end
                    if resumed then
                        local saved = loadState()

                        if saved and saved.phase == 'DONE' then
                            dbg('start: resumed onto a finished run, not starting another')
                            MemStore.remove('progression_active')
                            MemStore.remove('khei_run')

                            return
                        end
                    end
                    if game.PlaceId ~= KHEI_PLACE then
                        local saved = loadState()
                        local fresh = (tonumber(getServerValue('DaysSurvived')) or 0) < 1

                        if not fresh then
                            fresh = true

                            for _, potion in {
                                'Liquid Wisdom',
                                'Health Potion',
                                'Ice Protection',
                                'Tespian Elixir',
                            }do
                                if not hasTool(potion) then
                                    fresh = false
                                end
                            end
                        end
                        if saved and saved.phase == 'KHEI' and not fresh then
                            dbg('start: Khei run back on Gaia, handing off to Yaalda again')

                            state = saved

                            MemStore.remove('progression_active')
                            MemStore.set('khei_run', 'true')
                            task.spawn(ctx.State.progKheiHandoff)

                            return
                        end
                    end

                    running = true

                    if Toggles.ProximityNotifier then
                        Toggles.ProximityNotifier:SetValue(true)
                    end
                    if Toggles.ProximityIgnoreAllies then
                        Toggles.ProximityIgnoreAllies:SetValue(true)
                    end
                    if Options.ProximityDistance then
                        Options.ProximityDistance:SetValue(1000)
                    end

                    hopCommitted = false
                    ctx.State.progHalted = false

                    setStopVisible(true)
                    setStartVisible(false)

                    state = loadState()

                    if not state or state.phase == 'DONE' then
                        state = {
                            phase = 'P0',
                            step = 0,
                            startDay = getServerValue('DaysSurvived'),
                            startClock = os.time(),
                            startSilver = getServerValue('Silver'),
                            serverhops = 0,
                        }
                    end
                    if game.PlaceId == KHEI_PLACE then
                        state.phase = 'KHEI'
                        state.kheiStep = state.kheiStep or 'inn'
                        state.kheiClock = state.kheiClock or os.time()
                    elseif state.phase == 'KHEI' then
                        dbg(
[[start: Khei state on Gaia for a character that has not finished Gaia, beginning a fresh run]])

                        state = {
                            phase = 'P0',
                            step = 0,
                            startDay = getServerValue('DaysSurvived'),
                            startClock = os.time(),
                            startSilver = getServerValue('Silver'),
                            serverhops = 0,
                        }
                    end

                    state.startClock = state.startClock or os.time()
                    state.runId = Webhook.setRunId(state.runId)

                    saveState()

                    resumePath = nil

                    if resumed then
                        local pp = MemStore.getJSON('prog_pathpoint')

                        if pp and pp.sig then
                            resumePath = pp
                        end
                    else
                        MemStore.remove('prog_pathpoint')
                        MemStore.remove('prog_lastpos')
                    end

                    setResetVisible(true)

                    local missing = checkCapabilities()

                    if #missing > 0 then
                        notify('Auto-Sigil missing: ' .. table.concat(missing, ', '))
                        dbg('missing capabilities: %s', table.concat(missing, ', '))
                    end

                    forceToggles()
                    MemStore.set('progression_active', 'true')
                    MemStore.set('progression_class', Options.ProgClass and Options.ProgClass.Value or 'Sigil')
                    BotClaims.claim(game.JobId)
                    arm()
                    task.spawn(function()
                        local ok, err = pcall(runCore)

                        if not ok then
                            dbg('run stopped on an error: %s', tostring(err))
                            Webhook.textBounded('@everyone Auto-Sigil stopped on an error: **' .. tostring(err) .. '**')
                            stop()
                        end
                    end)
                end

                function stop(manual)
                    if not (running or dangerBusy or hopCommitted) then
                        return
                    end

                    ctx.State.progHalted = true
                    running = false

                    setStopVisible(false)
                    setStartVisible(true)
                    MemStore.remove('progression_active')
                    BotClaims.release()
                    MemStore.remove('khei_run')
                    MemStore.remove('khei_handoff_servers')
                    restoreToggles()
                    saveState()
                    setResetVisible(true)
                    zOffsetStop()
                    restoreTouch()
                    guard:DoCleaning()

                    if manual then
                        return
                    end

                    task.spawn(function()
                        Danger.waitClear()
                        waitMenuOut()
                        pcall(Danger.kick, 'auto-sigil: run stopped on its own')
                    end)
                end

                ctx.State.registerBot({
                    name = 'Auto Sigil',
                    running = function()
                        return running == true
                    end,
                    detail = function()
                        return state and state.phase
                    end,
                    stop = function()
                        stop(true)
                    end,
                })

                local PROG_PERSIST_TOGGLES = {
                    'ProgSkipIllusionist',
                    'ProgStayInServer',
                    'ProgGoToKhei',
                }
                local PROG_PERSIST_OPTIONS = {
                    'ProgProximity',
                    'ProgPing',
                    'ProgClass',
                }
                local progRestoring = false

                local function progSnapshot()
                    local snap = {
                        toggles = {},
                        options = {},
                    }

                    for _, key in PROG_PERSIST_TOGGLES do
                        local t = Toggles[key]

                        if t then
                            snap.toggles[key] = t.Value
                        end
                    end
                    for _, key in PROG_PERSIST_OPTIONS do
                        local o = Options[key]

                        if o then
                            snap.options[key] = o.Value
                        end
                    end

                    return snap
                end
                local function progSettingsSignature()
                    local snap = progSnapshot()
                    local ok, s = pcall(function()
                        return Services.HttpService:JSONEncode(snap)
                    end)

                    return ok and s or nil
                end
                local function saveProgSettings()
                    if progRestoring or (ctx.State and ctx.State.loadingConfig) then
                        return
                    end

                    local snap = progSnapshot()

                    MemStore.setJSON('progression_settings', snap)
                    dbg('saveProgSettings: skipIllu=%s', tostring(snap.toggles.ProgSkipIllusionist))
                end
                local function restoreProgSettings()
                    local snap = MemStore.getJSON('progression_settings')

                    if type(snap) ~= 'table' then
                        return
                    end

                    dbg('restoreProgSettings: applying skipIllu=%s', tostring(snap.toggles and snap.toggles.ProgSkipIllusionist))

                    progRestoring = true

                    if type(snap.toggles) == 'table' then
                        for key, v in snap.toggles do
                            local t = Toggles[key]

                            if t then
                                pcall(function()
                                    t:SetValue(v)
                                end)
                            end
                        end
                    end
                    if type(snap.options) == 'table' then
                        for key, v in snap.options do
                            local o = Options[key]

                            if o then
                                pcall(function()
                                    o:SetValue(v)
                                end)
                            end
                        end
                    end

                    progRestoring = false
                end

                section:AddDropdown('ProgClass', {
                    Text = 'Class',
                    Values = {
                        'Sigil',
