                local function startFlight()
                    Character.noFall(Character.humanoid())

                    return RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        local char = LocalPlayer.Character

                        if not char then
                            return
                        end

                        touchedChar = true

                        Character.noclip(char, true)
                    end))
                end
                local function tweenTo(pos, speed)
                    if not Character.awaitPlaced(function()
                        return running
                    end, 25, function()
                        notify('Waiting for the character to be placed')
                    end) then
                        return
                    end

                    while running do
                        if lives() == 0 then
                            return
                        end

                        local r = Character.root()

                        if not r then
                            return
                        end

                        local d = (pos - r.Position).Magnitude
                        local step = (d <= 1400) and pos or (r.Position + (pos - r.Position).Unit * 1400)
                        local dist = (step - r.Position).Magnitude
                        local tween = TweenService:Create(r, TweenInfo.new(math.max(dist / (speed or SPEED), 0.05), Enum.EasingStyle.Linear), {
                            CFrame = CFrame.new(step),
                        })
                        local done = false

                        tween.Completed:Connect(function()
                            done = true
                        end)
                        tween:Play()
                        BASIL_NO_VIRTUALIZE(function()
                            while not done and running do
                                task.wait()
                            end
                        end)()

                        if not running then
                            tween:Cancel()

                            return
                        end
                        if step == pos then
                            return
                        end
                    end
                end
                local function pathTo(points, speed)
                    local flight = startFlight()

                    for _, p in points do
                        if not running then
                            break
                        end

                        tweenTo(p, speed)
                    end

                    return flight
                end
                local function talkAt(points, npcName, choices, opts)
                    opts = opts or {}

                    local flight = pathTo(points, opts.speed)
                    local npcs = Workspace:FindFirstChild('NPCs')
                    local npc = npcs and npcs:FindFirstChild(npcName)
                    local npcHrp = npc and npc:FindFirstChild('HumanoidRootPart')
                    local r = Character.root()
                    local arrived = npcHrp ~= nil and r ~= nil and (r.Position - npcHrp.Position).Magnitude <= (opts.range or 20)

                    if arrived then
                        r.AssemblyLinearVelocity = Vector3.zero
                        touchedChar = true

                        local pin

                        if opts.anchor then
                            r.Anchored = true
                        else
                            local anchor = CFrame.new(r.Position)

                            pin = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                            )
                                local root = Character.root()

                                if root then
                                    root.CFrame = anchor
                                    root.AssemblyLinearVelocity = Vector3.zero
                                end
                            end))
                        end
                        if running then
                            task.wait(opts.settle or 0.25)
                        end

                        Dialogue.run(npc, choices, {
                            shouldRun = function()
                                return running
                            end,
                            minHold = 0,
                            openWait = 0,
                        })

                        if pin then
                            pin:Disconnect()
                        else
                            local root = Character.root()

                            if root then
                                root.Anchored = false
                            end
                        end
                    end

                    flight:Disconnect()
                    Character.clearVeil()

                    return arrived
                end
                local function waitRespawn(old, timeout)
                    local t = 0

                    repeat
                        task.wait(0.3)

                        t += 0.3
                    until (LocalPlayer.Character and LocalPlayer.Character ~= old and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')) or t > (timeout or 20) or not running
                end
                local function reset()
                    local old = LocalPlayer.Character

                    Character.kill()
                    waitRespawn(old, 20)
                end

                local lineageOf, lineageKey = nil, nil

                local function lineage()
                    local char = LocalPlayer.Character

                    if lineageKey and lineageOf == char then
                        return lineageKey
                    end

                    local parts = {}

                    for _, stat in {
                        'FirstName',
                        'Gender',
                        'ManaColor',
                    }do
                        local value = Remotes.getServerValue(stat)

                        if value == nil then
                            return nil
                        end

                        table.insert(parts, tostring(value))
                    end

                    lineageOf, lineageKey = char, table.concat(parts, '|')

                    return lineageKey
                end
                local function loadProgress()
                    local p = MemStore.getJSON(PROGRESS_KEY)

                    if type(p) ~= 'table' or tonumber(p.user) ~= LocalPlayer.UserId then
                        return {}
                    end

                    local key = lineage()

                    if key and p.lineage ~= key then
                        MemStore.remove(PROGRESS_KEY)

                        return {}
                    end

                    return p
                end
                local function saveProgress(key, value)
                    local p = loadProgress()

                    p[key] = value
                    p.user = LocalPlayer.UserId
                    p.lineage = lineage() or p.lineage

                    MemStore.setJSON(PROGRESS_KEY, p)
                end
                local function setInn(name)
                    local Toggles = Library.Toggles
                    local fallGuard = not (Toggles.NoFall and Toggles.NoFall.Value)
                    local killGuard = ctx.State.setKillbricks ~= nil and not (Toggles.NoKillBricks and Toggles.NoKillBricks.Value)
                    local binding = true

                    if fallGuard then
                        task.spawn(function()
                            while binding do
                                ctx.State.noFallUntil = tick() + INN_GUARD

                                task.wait(1)
                            end
                        end)
                    end
                    if killGuard then
                        pcall(ctx.State.setKillbricks, true)
                    end

                    local ok = NPC.setInn(name, {
                        shouldRun = function()
                            return running
                        end,
                        breakJoints = true,
                        attempts = 4,
                    })

                    binding = false

                    if fallGuard then
                        ctx.State.noFallUntil = 0
                    end
                    if killGuard then
                        pcall(ctx.State.setKillbricks, false)
                    end
                    if ok then
                        saveProgress('inn', name)
                    end

                    return ok
                end
                local function waitNear(pos, radius, timeout)
                    local t = 0

                    while running and not Character.near(pos, radius) and t < (timeout or 25) do
                        task.wait(0.3)

                        t += 0.3
                    end

                    return Character.near(pos, radius)
                end
                local function targetAtRenova()
                    local target = rotMaster()
                    local tHrp = target and target.Character and target.Character:FindFirstChild('HumanoidRootPart')

                    return tHrp ~= nil and (tHrp.Position - RENOVA_SPOT).Magnitude <= 225, target, tHrp
                end
                local function returnToMenu(ignoreButton)
                    local rtm = Remotes.requestRemote('ReturnToMenu')
                    local t = 0

                    while running and not Menu.startMenu() and t < 10 do
                        if rtm and (ignoreButton or Menu.safeToMenu()) then
                            pcall(function()
                                rtm:InvokeServer()
                            end)
                        end

                        task.wait(0.4)

                        t += 0.4
                    end

                    return Menu.startMenu() ~= nil
                end
                local function menuWait()
                    returnToMenu()

                    while running and not targetAtRenova() do
                        task.wait(0.5)
                    end

                    if not running then
                        return false
                    end

                    local t = 0

                    while running and Menu.startMenu() and t < 12 do
                        Menu.clickPlay()
                        task.wait(0.5)

                        t += 0.5
                    end

                    local w = 0

                    while running and not Character.root() and w < 15 do
                        task.wait(0.3)

                        w += 0.3
                    end

                    return Character.root() ~= nil
                end
                local function jailed(char)
                    return CollectionService:HasTag(char, 'Jailed') or (not isMaster() and (CollectionService:HasTag(char, 'JAILCOOL') or char:FindFirstChild('JAILCOOL') ~= nil))
                end
                local function downed(char)
                    return CollectionService:HasTag(char, 'Unconscious') or char:FindFirstChild('Carried') ~= nil
                end
                local function rotTeleport(target)
                    touchedChar = true

                    local conn = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        Character.noclip(LocalPlayer.Character, true)
                    end))

                    local function stopped()
                        local char = LocalPlayer.Character

                        return not running or (char ~= nil and (jailed(char) or downed(char)))
                    end
                    local function chase()
                        local deadline = tick() + 5

                        while not stopped() and tick() < deadline do
                            local r = Character.root()
                            local hrp = target.Character and target.Character:FindFirstChild('HumanoidRootPart')

                            if not (r and hrp) or (r.Position - hrp.Position).Magnitude <= 8 then
                                break
                            end

                            tweenTo(hrp.Position, 90)
                        end
                    end
                    local function heldNear()
                        local t = 0

                        while not stopped() and t < LAG_BACK_WATCH do
                            local r = Character.root()
                            local hrp = target.Character and target.Character:FindFirstChild('HumanoidRootPart')

                            if not (r and hrp) or (r.Position - hrp.Position).Magnitude > KNOCK_REACH then
                                return false
                            end

                            task.wait(0.1)

                            t += 0.1
                        end

                        return true
                    end

                    chase()

                    if not stopped() and not heldNear() then
                        for _, point in MASTER_DETOUR do
                            if stopped() then
                                break
                            end

                            tweenTo(point, 90)
                        end

                        chase()
                        heldNear()
                    end

                    conn:Disconnect()
                end
                local function rejoinSameServer()
                    MemStore.set('rotbot_active', 'true')
                    MemStore.set('rotbot_target', (Options.RotMaster and Options.RotMaster.Value) or '')
                    MemStore.set('rotbot_stopillu', stopsOnIllu())
                    Serverhop.setupResume()

                    if not returnToMenu(true) then
                        MemStore.remove('rotbot_active')
                        notify(
[[Rot Bot: could not reach the menu, carrying on in this server]])

                        return false
                    end

                    local join = Remotes.requestRemote('JoinPublicServer')

                    if not join then
                        MemStore.remove('rotbot_active')
                        notify(
[[Rot Bot: no JoinPublicServer on this realm, carrying on in this server]])

                        return false
                    end

                    local leaving = false
                    local watch = LocalPlayer.OnTeleport:Connect(function(
                        state
                    )
                        if state ~= Enum.TeleportState.Failed then
                            leaving = true
                        end
                    end)
                    local jobId = game.JobId

                    for attempt = 1, REJOIN_TRIES do
                        notify(attempt == 1 and 'Rot Bot: wiped, rejoining the server' or ('Rot Bot: rejoin attempt ' .. attempt))
                        pcall(function()
                            join:FireServer(jobId)
                        end)

                        local t = 0

                        while running and t < REJOIN_WAIT and not leaving do
                            task.wait(0.25)

                            t += 0.25
                        end

                        if leaving or not running then
                            break
                        end
                    end

                    pcall(function()
                        watch:Disconnect()
                    end)

                    if leaving then
                        task.wait(REJOIN_WAIT)

                        return true
                    end

                    MemStore.remove('rotbot_active')
                    notify('Rot Bot: rejoin did not land after ' .. REJOIN_TRIES .. ' tries, carrying on in this server')

                    return false
                end
                local function hasTarget()
                    return rotMaster() ~= nil
                end
                local function strangerNear(radius)
                    local root = Character.root()

                    if not root then
                        return nil
                    end

                    local ours = {}

                    for _, beacon in link.roster()do
                        ours[beacon.name] = true
                    end

                    local master = rotMaster()

                    for _, p in Players:GetPlayers()do
                        local hrp = p ~= LocalPlayer and p ~= master and not ours[p.Name] and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                        if hrp and (hrp.Position - root.Position).Magnitude <= radius and not (ctx.State.isFriendly and ctx.State.isFriendly(p)) then
                            return p
                        end
                    end

                    return nil
                end
                local function rotPhase()
                    local lastSay, awaySince = nil, nil
                    local carried, upAt = false, nil

                    local function say(key, msg)
                        if key ~= lastSay then
                            lastSay = key

                            notify('Rot Bot: ' .. msg)
                        end
                    end

                    while running do
                        if (lives() == 0 and not isMaster()) or (Character.near(FERRYMAN_AREA, 75) and (lives() or 0) <= 0) then
                            return 'ferryman'
                        end

                        local char = LocalPlayer.Character
                        local r = char and char:FindFirstChild('HumanoidRootPart')
                        local atRenova = r ~= nil and Character.near(RENOVA_SPOT, 100)

                        if atRenova then
                            awaySince = nil
                        end
                        if not r then
                            task.wait(0.3)
                        elseif jailed(char) then
                            carried, upAt = false, nil

                            Character.kill()
                            waitRespawn(char, 20)
                        elseif downed(char) then
                            carried = carried or (not isMaster() and char:FindFirstChild('Carried') ~= nil)
                            upAt = nil

                            task.wait(0.2)
                        elseif carried then
                            upAt = upAt or tick()

                            if tick() - upAt >= JAIL_WAIT then
                                carried, upAt = false, nil

                                Character.kill()
                                waitRespawn(char, 20)
                            else
                                task.wait(0.1)
                            end
                        elseif not atRenova then
                            awaySince = awaySince or tick()

                            if tick() - awaySince > 10 then
                                say('away', 'not at the Renova inn, waiting to be back there')
                            end

                            task.wait(0.4)
                        elseif isMaster() then
                            say('carrier',
[[this account is the master, waiting at Renova to carry the alts in]])
                            task.wait(0.4)
                        elseif not hasTarget() then
                            local typed = Options.RotMaster and Options.RotMaster.Value or ''

                            say('nomaster', typed ~= '' and (typed .. " isn't in this server, waiting in the menu") or 'no master set, waiting in the menu')

                            return 'menu'
                        else
                            local ok, target, tHrp = targetAtRenova()

                            if not ok then
                                say('masteraway', 'waiting in the menu for ' .. (target and target.Name or 'the master') .. ' to be at Renova')

                                return 'menu'
                            end
                            if tHrp then
                                say('going', 'going to ' .. target.Name .. ' to knock')
                                rotTeleport(target)

                                local r2 = Character.root()
                                local curHrp = target.Character and target.Character:FindFirstChild('HumanoidRootPart')

                                if r2 and curHrp and (r2.Position - curHrp.Position).Magnitude <= KNOCK_REACH then
                                    local t = 0

                                    while running and t < 5 and not (LocalPlayer.Character and CollectionService:HasTag(LocalPlayer.Character, 'Unconscious')) do
                                        fireFallDamage()
                                        task.wait(0.5)

                                        t += 0.5
                                    end
                                end
                            end

                            task.wait(0.4)
                        end
                    end

                    return nil
                end
                local function ferrymanWipe()
                    Ferryman.wipe(function()
                        return running
                    end, {
                        notify = function(m)
                            notify('Rot Bot: ' .. m)
                        end,
                    })
                end
                local function wipeAndRejoin()
                    ferrymanWipe()

                    if not running or (ctx.State.getServerValue and ctx.State.getServerValue('Lives') == 0) then
                        return false
                    end

                    MemStore.remove(PROGRESS_KEY)
                    rejoinSameServer()

                    return true
                end
                local function toFerryman()
                    notify('Rot Bot: 0 lives, going to the Ferryman')

                    if not Character.near(FERRYMAN_AREA, 75) then
                        reset()
                        waitNear(FERRYMAN_AREA, 75)
                    end
                    if running and Character.near(FERRYMAN_AREA, 75) and wipeAndRejoin() then
                        return true
                    end
                    if running then
                        notify('Rot Bot: the Ferryman wipe did not take - retrying')
                        task.wait(2)
                    end

                    return false
                end
                local function showRots()
                    if rotLabel then
                        pcall(function()
                            rotLabel:SetText('Rots: ' .. rotCount)
                        end)
                    end
                end
                local function countRot()
                    rotCount += 1

                    MemStore.set('rotbot_count', rotCount)
                    showRots()
                end

                local countedJail = setmetatable({}, {
                    __mode = 'k',
                })

                ctx.Maid:Give(CollectionService:GetInstanceAddedSignal('Jailed'):Connect(function(
                    instance
                )
                    if not running or countedJail[instance] then
                        return
                    end

                    local jailed = Players:GetPlayerFromCharacter(instance)

                    if not jailed then
                        return
                    end

                    local target = rotMaster()

                    if jailed == LocalPlayer or (target and jailed == target) then
                        countedJail[instance] = true

                        countRot()
                    end
                end))

                local function endPhase()
                    while running do
                        local result = rotPhase()

                        if not running then
                            return
                        end
                        if result == 'ferryman' then
                            if toFerryman() or not running then
                                return
                            end
                        elseif result == 'menu' then
                            if not menuWait() then
                                return
                            end
                        else
                            return
                        end
                    end
                end
                local function spawnIn()
                    local t = 0

                    while running and t < 30 and (Menu.startMenu() or Character.onLoadingPad()) do
                        if Menu.startMenu() then
                            Menu.clickPlay()
                        end

                        task.wait(0.5)

                        t += 0.5
                    end

                    return running and not Menu.startMenu() and not Character.onLoadingPad()
                end
                local function runCarrier()
                    if not spawnIn() then
                        return
                    end
                    if not Character.near(RENOVA_SPOT, 225) and not setInn('Renova') and running then
                        notify(
[[Rot Bot: could not bind Renova, go to the Renova inn and the alts will come to you]])
                    end

                    endPhase()
                end
                local function retry(msg)
                    if running then
                        notify('Rot Bot: ' .. msg)
                        task.wait(2)
                    end
                end
                local function resetTo(spot)
                    reset()

                    local t = 0

                    while running and not Character.near(spot, INN_NEAR) and lives() ~= 0 and t < 25 do
                        task.wait(0.3)

                        t += 0.3
                    end
                end
                local function runRotBot()
                    if isMaster() then
                        runCarrier()

                        return
                    end

                    local announced = false

                    while running do
                        if not spawnIn() then
                            retry('still in the menu - restarting')

                            continue
                        end

                        local p = loadProgress()

                        if not announced then
                            announced = true

                            if p.inn or p.brom or p.fir then
                                notify(string.format('Rot Bot: resuming, inn %s, Brom %s, Fir %s', p.inn or 'not set', p.brom and 'done' or 'not done', p.fir and 'done' or 'not done'))
                            end
                        end
                        if lives() == 0 then
                            toFerryman()

                            continue
                        end
                        if not p.brom then
                            if p.inn ~= 'Santorini' then
                                if not setInn('Santorini') then
                                    retry('Santorini inn failed - restarting')

                                    continue
                                end
                            elseif not Character.near(SANTORINI_RESPAWN, INN_NEAR) then
                                resetTo(SANTORINI_RESPAWN)
                            end
                            if not running then
                                break
                            end
                            if lives() == 0 then
                                continue
                            end
                            if not talkAt(BROM_PATH, 'Brom', {
                                "You're a merchant?",
                                'If I see her.',
                            }, {
                                settle = 0.25,
                                range = 30,
                                anchor = true,
                                speed = 100,
                            }) then
                                retry('Brom not in range - restarting')

                                continue
                            end
                            if not running then
                                break
                            end

                            saveProgress('brom', true)
                            notify('Rot Bot: Brom done, resetting for Fir')
                        end
                        if not p.fir then
                            if not Character.near(SANTORINI_RESPAWN, INN_NEAR) then
                                resetTo(SANTORINI_RESPAWN)

                                if not running then
                                    break
                                end
                                if lives() == 0 then
                                    continue
                                end
                            end
                            if not talkAt(FIR_PATH, 'Fir', {
                                "What's wrong?",
                                'Do you mean Brom?',
                                'Yeah, I saw him earlier.',
                                'I saw him napping on the job.',
                            }) then
                                retry('Fir not in range - restarting')

                                continue
                            end
                            if not running then
                                break
                            end

                            saveProgress('fir', true)
                            notify('Rot Bot: Fir done, binding Renova')
                        end
                        if p.fir and p.inn == 'Renova' then
                            if not Character.near(RENOVA_SPOT, INN_NEAR) then
                                resetTo(RENOVA_SPOT)
                            end
                        elseif not setInn('Renova') then
                            retry('Renova inn failed - restarting')

                            continue
                        end
                        if not running then
                            break
                        end
                        if masterHalted then
                            notify('Rot Bot: on Renova but the master is still stopped, menuing')
                            Danger.waitClear()
                            returnToMenu()
                            Library.Toggles.RotBotEnabled:SetValue(false)

                            break
                        end

                        endPhase()
                    end
                end
                local function restoreCharacter()
                    if not touchedChar then
                        return
                    end

                    touchedChar = false
                    ctx.State.noFallUntil = 0

                    Character.clearVeil()

                    local char = LocalPlayer.Character

                    if not char then
                        return
                    end

                    local hrp = char:FindFirstChild('HumanoidRootPart')

                    if hrp then
                        hrp.Anchored = false
                    end

                    for _, part in char:GetDescendants()do
                        if part:IsA('BasePart') and part.Name ~= 'HumanoidRootPart' then
                            part.CanCollide = part.Name == 'Head' or part.Name == 'Torso'
                        end
                    end

                    local humanoid = char:FindFirstChildOfClass('Humanoid')

                    if humanoid then
                        humanoid:SetStateEnabled(5, true)
                        humanoid:ChangeState(5)
                    end
                end

                ctx.Maid:Give(function()
                    running = false

                    restoreCharacter()
                end)

                rotLabel = section:AddLabel('Rots: ' .. rotCount)

                section:AddButton({
                    Text = 'Reset Rot Count',
                    Func = function()
                        rotCount = 0

                        MemStore.set('rotbot_count', 0)
                        showRots()
                    end,
                })
                section:AddButton({
                    Text = 'Reset Rot Progress',
                    Func = function()
                        MemStore.remove(PROGRESS_KEY)

                        local names = {}

                        for name, on in pairs(Options.RotAlts and Options.RotAlts.Value or {})do
                            if on then
                                table.insert(names, name)
                            end
                        end

                        if #names == 0 then
                            notify(
[[Rot Bot: progress cleared, this alt starts from the Santorini inn]])

                            return
                        end

                        link.write('reset', {
                            at = os.time(),
                            names = names,
                        })
                        notify('Rot Bot: progress cleared on ' .. table.concat(names, ', '))
                    end,
                })

                do
                    local altBusy, unloaded = false, false

                    ctx.Maid:Give(function()
                        unloaded = true

                        link.clearCommand()
                        link.dropBeacon()
                    end)
                    section:AddDivider()
                    section:AddInput('RotMaster', {
                        Text = 'Master',
                        Default = '',
                        Placeholder = 'who carries you',
                        Finished = true,
                        Tooltip = "Who carries this account, if they don't run sentinel",
                        Callback = function(value)
                            local p = AltLink.match(value)

                            if p and p.Name ~= value then
                                Options.RotMaster:SetValue(p.Name)
                            end
                        end,
                    })
                    section:AddLabel(
[[On the account that carries, pick the alts here. On the alts being carried, pick nothing]], true)

                    if not AltLink.available() then
                        section:AddLabel('This executor has no file access, so alts cannot be listed', true)
                    end

                    section:AddDropdown('RotAlts', {
                        Text = 'Alts',
                        Values = {},
                        Multi = true,
                        Default = {},
                        Tooltip = 'Only alts running sentinel show up',
                    })

                    local function masterAlive()
                        return not unloaded and running
                    end

                    local known, beaconByName = {}, {}

                    local function refreshRoster()
                        local names, changed = {}, false

                        table.clear(beaconByName)

                        for _, beacon in link.roster()do
                            table.insert(names, beacon.name)

                            beaconByName[beacon.name] = beacon
                        end

                        table.sort(names)

                        if #names ~= #known then
                            changed = true
                        else
                            for i, n in names do
                                if known[i] ~= n then
                                    changed = true

                                    break
                                end
                            end
                        end
                        if changed then
                            known = names

                            if Options.RotAlts then
                                Options.RotAlts:SetValues(names)
                            end
                        end
                    end
                    local function pickedAlts()
                        local out = {}

                        for name, on in pairs(Options.RotAlts and Options.RotAlts.Value or {})do
                            if on then
                                table.insert(out, name)
                            end
                        end

                        return out
                    end
                    local function grabbing()
                        local char = LocalPlayer.Character

                        return char ~= nil and char:FindFirstChild('Grabbing') ~= nil
                    end
                    local function carryRemote()
                        local char = LocalPlayer.Character
                        local handler = char and char:FindFirstChild('CharacterHandler')
                        local remotes = handler and handler:FindFirstChild('Remotes')

                        return remotes and remotes:FindFirstChild('Carry') or nil
                    end
                    local function bountyOfficer()
                        local npcs = Workspace:FindFirstChild('NPCs')

                        if not npcs then
                            return nil
                        end

                        local model, dist = NPC.nearestModel(npcs, 'Bounty Officer', BOUNTY_POS)

                        return (model and dist and dist <= BOUNTY_SEARCH) and model or nil
                    end
                    local function carryDown(player)
                        local waited = 0

                        while masterAlive() and not wrappingUp and waited < CARRY_LIMIT do
