                local viewport = main and main:WaitForChild('Viewport', 3)
                local union = viewport and viewport:WaitForChild('Union', 3)
                local options = main and main:WaitForChild('Options', 3)

                if not (union and options) then
                    return false, 'captcha gui never filled in'
                end

                task.wait(1)

                local answer, err = Captcha.answer(union, viewport)

                if not answer then
                    return false, err
                end

                local button = options:FindFirstChild(answer)

                if not button then
                    return false, 'no option button named ' .. tostring(answer)
