                return (bag and bag:FindFirstChild(name)) or (char and char:FindFirstChild(name)) or nil
            end

            return function(ctx)
                local Library = ctx.Library
                local Toggles, Options = Library.Toggles, Library.Options
                local section = ctx.State.castleRockTab

                if not section then
                    return
                end

                local runMaid = Maid.new()

                ctx.Maid:Give(runMaid)

                local bagParts = {}
                local ownedThrown = nil
                local sessionStart, runCount = 0, 0
                local unloaded = false
                local running, thread = false, nil
                local traversing, modHandled, gating, illuHandled = false, false, false, false
                local deathHandled, ownDeathUntil = false, 0
                local startButton, stopButton
                local guardsOff

                ctx.Maid:Give(function()
                    unloaded = true
                    running = false

                    if guardsOff then
                        guardsOff()
                    end
                    if thread then
                        pcall(task.cancel, thread)

                        thread = nil
                    end
                end)

                local function notify(text)
                    Notify.say(text)
                end
                local function log(fmt, ...)
                    local ok, line = pcall(string.format, fmt, ...)

                    line = ok and line or tostring(fmt)

                    Console.print('[sentinel] castle rock: ' .. line)
                    Debug.log('castlerock', line)
                end
                local function opt(name, fallback)
                    local o = Options[name]

                    return (o and o.Value) or fallback
                end
                local function flag(name)
                    local t = Toggles[name]

                    return t ~= nil and t.Value == true
                end
                local function stayIn()
                    return flag('CastleStayInServer')
                end

                runMaid:Connect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                )
                    if not running or gating or not flag('CastleHoldPebble') then
                        return
                    end

                    local char = LocalPlayer.Character
                    local hum = char and char:FindFirstChildOfClass('Humanoid')
                    local bag = LocalPlayer:FindFirstChildOfClass('Backpack')

                    if not hum then
                        return
                    end

                    local first = Options.CastleHoldItem and Options.CastleHoldItem.Value == 'Pebble' and 'Pebble' or 'Perflora'
                    local other = first == 'Pebble' and 'Perflora' or 'Pebble'
                    local want = ((bag and bag:FindFirstChild(first)) or char:FindFirstChild(first)) and first or other

                    if char:FindFirstChild(want) then
                        return
                    end

                    local tool = bag and bag:FindFirstChild(want)

                    if tool and tool:IsA('Tool') then
                        pcall(function()
                            hum:EquipTool(tool)
                        end)
                    end
                end))

                local activeTween = {
                    tween = nil,
                    connection = nil,
                }

                local function tele(target, settle, speedOverride)
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild('HumanoidRootPart')

                    if not root or unloaded then
                        return false
                    end

                    local targetPosition

                    if typeof(target) == 'CFrame' then
                        targetPosition = target.Position
                    elseif typeof(target) == 'Vector3' then
                        targetPosition = target
                    elseif typeof(target) == 'Instance' and target:IsA('BasePart') then
                        targetPosition = target.Position
                    else
                        return false
                    end

                    local distance = (targetPosition - root.Position).Magnitude

                    if distance > TELEPORT_CAP then
                        log(
[[refused a %.0f stud teleport to (%.0f, %.0f, %.0f), over the %d cap]], distance, targetPosition.X, targetPosition.Y, targetPosition.Z, TELEPORT_CAP)

                        return false
                    end

                    local humanoid = char:FindFirstChildOfClass('Humanoid')

                    if humanoid then
                        humanoid:SetStateEnabled(5, false)
                        humanoid:ChangeState(3)
                    end

                    local connection = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        if unloaded then
                            return
                        end

                        Character.noclip(LocalPlayer.Character, true)
                    end))

                    runMaid.teleNoclip = connection

                    local speed = speedOverride or TRAVEL_SPEED
                    local tween = TweenService:Create(root, TweenInfo.new(distance / speed, Enum.EasingStyle.Linear), {
                        CFrame = CFrame.new(targetPosition),
                    })

                    activeTween.tween = tween
                    activeTween.connection = connection

                    local completed = false

                    tween.Completed:Connect(function()
                        completed = true
                    end)
                    tween:Play()
                    BASIL_NO_VIRTUALIZE(function()
                        while not completed and not unloaded and running and not (illuHandled or modHandled) do
                            task.wait()
                        end
                    end)()

                    if unloaded or not running or illuHandled or modHandled then
                        tween:Cancel()
                    end
                    if not unloaded and settle then
                        task.wait(0.25)
                    end
                    if humanoid then
                        humanoid:SetStateEnabled(5, true)
                        humanoid:ChangeState(Enum.HumanoidStateType.Running)
                    end

                    activeTween.tween = nil

                    task.delay(ARRIVE_SETTLE, function()
                        if activeTween.connection == connection then
                            activeTween.connection = nil

                            Character.clearVeil()
                        end

                        connection:Disconnect()
                    end)

                    return completed
                end
                local function restoreCollisions()
                    local char = LocalPlayer.Character

                    if not char then
                        return
                    end

                    for _, part in char:GetDescendants()do
                        if part:IsA('BasePart') and part.Name ~= 'HumanoidRootPart' then
                            part.CanCollide = part.Name == 'Head' or part.Name == 'Torso'
                        end
                    end
                end
                local function walk(list, abortWhen)
                    traversing = true

                    for _, pos in list do
                        if not running or illuHandled or modHandled or (abortWhen and abortWhen()) then
                            traversing = false

                            return false
                        end

                        tele(pos)
                    end

                    traversing = false

                    return running and not (abortWhen and abortWhen())
                end
                local function setRunning(on)
                    running = on

                    if startButton and startButton.Holder then
                        startButton.Holder.Visible = not on
                    end
                    if stopButton and stopButton.Holder then
                        stopButton.Holder.Visible = on
                    end
                    if on then
                        MemStore.set('castlerock_active', 'true')
                    else
                        MemStore.remove('castlerock_active')
                    end
                end

                local SAVED_TOGGLES = {
                    'CastleOnlyLootRoom',
                    'CastleSkipIllusionist',
                    'CastleStayInServer',
                    'CastleHoldPebble',
                    'CastlePickupTrinkets',
                    'CastlePickupScrolls',
                    'CastlePickupIceEssence',
                    'CastlePickupEventItems',
                }
                local SAVED_OPTIONS = {
                    'CastleMinPlayers',
                    'CastleMinLastLooted',
                    'CastleLoopWait',
                    'CastlePickupMythicsArtifacts',
                    'CastleHoldItem',
                }

                local function saveSettings()
                    local snap = {
                        toggles = {},
                        options = {},
                    }

                    for _, key in SAVED_TOGGLES do
                        if Toggles[key] then
                            snap.toggles[key] = Toggles[key].Value
                        end
                    end
                    for _, key in SAVED_OPTIONS do
                        if Options[key] then
                            snap.options[key] = Options[key].Value
                        end
                    end

                    MemStore.setJSON('castlerock_settings', snap)
                end
                local function restoreSettings()
                    local snap = MemStore.getJSON('castlerock_settings')

                    if type(snap) ~= 'table' then
                        return
                    end

                    for key, value in snap.toggles or {}do
                        if Toggles[key] then
                            Toggles[key]:SetValue(value)
                        end
                    end
                    for key, value in snap.options or {}do
                        if Options[key] then
                            Options[key]:SetValue(value)
                        end
                    end
                end
                local function cacheFile()
                    return Paths.CACHE .. '/' .. tostring(LocalPlayer.UserId) .. '.json'
                end
                local function readCache()
                    local ok, data = pcall(function()
                        if isfile and isfile(cacheFile()) then
                            return HttpService:JSONDecode(readfile(cacheFile()))
                        end

                        return nil
                    end)

                    return (ok and type(data) == 'table') and data or {}
                end
                local function writeCache(data)
                    pcall(function()
                        if makefolder and isfolder and not isfolder(Paths.CACHE) then
                            makefolder(Paths.CACHE)
                        end

                        writefile(cacheFile(), HttpService:JSONEncode(data))
                    end)
                end
                local function markSuccess()
                    local data = readCache()

                    data.castleRock = {
                        lastSuccess = os.time(),
                    }

                    writeCache(data)
                end
                local function clearCooldown()
                    local data = readCache()

                    data.castleRock = nil

                    writeCache(data)
                end
                local function cooldownLeft()
                    local data = readCache()
                    local last = data.castleRock and tonumber(data.castleRock.lastSuccess)

                    if not last then
                        return 0
                    end

                    return math.max(0, COOLDOWN - (os.time() - last))
                end
                local function allied(p)
                    return (ctx.State.isFriendly and ctx.State.isFriendly(p)) or (ctx.State.isFriend and ctx.State.isFriend(p))
                end
                local function serverOk()
                    local minPlayers = opt('CastleMinPlayers', 0)

                    if #Players:GetPlayers() < minPlayers then
                        return false, string.format('only %d players, wanted %d', #Players:GetPlayers(), minPlayers)
                    end

                    local floor = opt('CastleMinLastLooted', 0)
                    local since = LootZones.minutesSince('Castle Rock')

                    if since ~= nil and since > LOOTED_UNSET then
                        return false, 'the room has not been stamped in this server yet'
                    end
                    if floor > 0 and since ~= nil and since < floor then
                        return false, string.format('looted %dm ago, wanted %dm', since, floor), true
                    end

                    for _, p in Players:GetPlayers()do
                        if p ~= LocalPlayer and not allied(p) then
                            local hrp = p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                            if hrp and not stayIn() and (hrp.Position - ROOM).Magnitude <= ROOM_CLEAR then
                                return false, p.Name .. ' is at the loot room'
                            end
                            if flag('CastleSkipIllusionist') and Threats.isIllusionist(p) and not stayIn() then
                                return false, p.Name .. ' is an illusionist'
                            end
                        end
                    end

                    return true
                end
                local function stop(force)
                    if not running and not force then
                        return
                    end

                    setRunning(false)
                    guardsOff()
                    runMaid:DoCleaning()

                    if thread then
                        pcall(task.cancel, thread)

                        thread = nil
                    end
                end
                local function hop(reason, inPlace)
                    if stayIn() then
                        log('%s (staying in server)', reason)

                        return false
                    end

                    saveSettings()

                    deathHandled = true

                    log('hopping: %s', reason)

                    local root

                    if inPlace then
                        local tween = activeTween.tween

                        if tween then
                            pcall(tween.Cancel, tween)
                        end

                        local hum = Character.humanoid()

                        root = hum and hum.FloorMaterial == Enum.Material.Air and Character.root()

                        log(root and 'midair, holding still and joining a new server' or 'joining a new server, menuing alongside it')

                        if root then
                            root.AssemblyLinearVelocity = Vector3.zero
                            root.Anchored = true
                        end
                    else
                        Menu.forceMenu(function()
                            return running
                        end)
                    end

                    local ok = Serverhop.hop({
                        strategy = 'random',
                        inGameList = true,
                        reason = reason,
                        menuWait = not inPlace,
                        returnToMenu = not inPlace,
                        cancelled = function()
                            return not running
                        end,
                    })

                    if root and not ok then
                        root.Anchored = false
                    end

                    return ok or not inPlace
                end

                local guardRelease = nil

                local function guardsOn()
                    if guardRelease or not ctx.State.holdGuards then
                        return
                    end

                    guardRelease = ctx.State.holdGuards(GUARD_WINDOW)

                    task.spawn(function()
                        while running and guardRelease do
                            ctx.State.refreshGuards(GUARD_WINDOW)
                            task.wait(GUARD_WINDOW / 3)
                        end
                    end)
                end

                function guardsOff()
                    if guardRelease then
                        guardRelease()

                        guardRelease = nil
                    end
                end

                local function ensureBags()
                    for i = #bagParts, 1, -1 do
                        if not bagParts[i].Parent then
                            table.remove(bagParts, i)
                        end
                    end

                    if #bagParts == #BAG_CFRAMES then
                        return
                    end

                    local thrown = Workspace:FindFirstChild('Thrown')

                    if not thrown then
                        thrown = Make('Folder', {
                            Name = 'Thrown',
                            Parent = Workspace,
                        })
                        ownedThrown = thrown
                    end

                    for _, cf in BAG_CFRAMES do
                        table.insert(bagParts, Make('Part', {
                            Name = 'ToolBag',
                            Size = Vector3.new(4, 1, 2),
                            Anchored = true,
                            Transparency = 1,
                            CFrame = cf,
                            Parent = thrown,
                        }))
                    end
                end

                local floorParts = {}

                local function ensureLootFloors()
                    for i = #floorParts, 1, -1 do
                        if not floorParts[i].Parent then
                            table.remove(floorParts, i)
                        end
                    end

                    if #floorParts == #LOOT_FLOORS then
                        return
                    end

                    local thrown = Workspace:FindFirstChild('Thrown')

                    if not thrown then
                        thrown = Make('Folder', {
                            Name = 'Thrown',
                            Parent = Workspace,
                        })
                        ownedThrown = thrown
                    end

                    for _, spec in LOOT_FLOORS do
                        table.insert(floorParts, Make('Part', {
                            Name = tostring(math.random(1111, 99999)),
                            Size = spec.size,
                            CFrame = spec.cf,
                            Anchored = true,
                            CanCollide = true,
                            Transparency = 1,
                            Parent = thrown,
                        }))
                    end
                end
                local function clearLootFloors()
                    for _, part in floorParts do
                        pcall(function()
                            part:Destroy()
                        end)
                    end

                    table.clear(floorParts)
                end

                ctx.Maid:Give(clearLootFloors)

                local function clearBags()
                    clearLootFloors()

                    for _, part in bagParts do
                        pcall(function()
                            part:Destroy()
                        end)
                    end

                    table.clear(bagParts)

                    if ownedThrown then
                        pcall(function()
                            ownedThrown:Destroy()
                        end)

                        ownedThrown = nil
                    end
                end

                ctx.Maid:Give(clearBags)

                local function serverInfo()
                    local name, region = '', ''
                    local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                    local statsGui = pg and pg:FindFirstChild('ServerStatsGui')
                    local frame = statsGui and statsGui:FindFirstChild('Frame')
                    local stats = frame and frame:FindFirstChild('Stats')

                    if stats then
                        local sn = stats:FindFirstChild('ServerName')

                        if sn then
                            name = sn.Text:match('Server Name: (.+)') or ''
                        end

                        local sr = stats:FindFirstChild('ServerRegion')

                        if sr then
                            region = sr.Text:match('Server Region: (.+)') or ''
                        end
                    end

                    return name, region
                end
                local function bagValue()
                    local total = 0
                    local bag = LocalPlayer:FindFirstChildOfClass('Backpack')

                    for _, child in (bag and bag:GetChildren() or {})do
                        local silver = child:FindFirstChild('SilverValue')

                        if silver then
                            total += silver.Value
                        end
                    end

                    return total
                end
                local function bagNames()
                    local out = {}
                    local bag = LocalPlayer:FindFirstChildOfClass('Backpack')

                    for _, child in (bag and bag:GetChildren() or {})do
                        out[child.Name] = (out[child.Name] or 0) + 1
                    end

                    return out
                end
                local function pokeEagle(detector)
                    if replicatesignal then
                        for _, action in {1, 0, 2}do
                            pcall(replicatesignal, detector.MouseActionReplicated, LocalPlayer, action)
                        end
                    elseif fireclickdetector then
                        pcall(fireclickdetector, detector)
                    end
                end
                local function wantedFilter()
                    local mythics = opt('CastlePickupMythicsArtifacts', {})
                    local wantIce = flag('CastlePickupIceEssence')
                    local wantScroll = flag('CastlePickupScrolls')
                    local wantEvent = flag('CastlePickupEventItems')
                    local wantTrinket = flag('CastlePickupTrinkets')

                    return function(name, zindex)
                        if not name then
                            return false
                        end
                        if name == 'Azael Horn' or name == 'Phoenix Down' then
                            return mythics[name] == true
                        end
                        if name == 'Ice Essence' then
                            return wantIce
                        end
                        if name:find('Scroll') then
                            return wantScroll
                        end
                        if zindex == 6 or zindex == 5 then
                            return mythics[name] == true
                        elseif zindex == 4 then
                            return wantEvent
                        elseif zindex == 2 or zindex == 3 then
                            return wantTrinket
                        end

                        return false
                    end
                end
                local function lootHere(seconds)
                    local identify = ctx.State.identifyTrinket

                    if not (identify and fireclickdetector) then
                        task.wait(seconds or LOOT_CFRAME_WAIT)

                        return
                    end

                    local wanted = wantedFilter()
                    local deadline = tick() + (seconds or LOOT_CFRAME_WAIT)

                    repeat
                        local root = Character.root()

                        if root then
                            for _, obj in Workspace:GetChildren()do
                                if obj.Name == 'Part' and obj:FindFirstChild('ID') then
                                    local cd = obj:FindFirstChild('ClickDetector', true)

                                    if cd and (obj.Position - root.Position).Magnitude < cd.MaxActivationDistance then
                                        local name, _, zindex = identify(obj)

                                        if wanted(name, zindex) then
                                            pcall(fireclickdetector, cd)
                                        end
                                    end
                                end
                            end
                        end

                        task.wait(0.1)
                    until tick() >= deadline or not running
                end
                local function sentryLive()
                    local turrets = Workspace:FindFirstChild('Turrets')
                    local room = turrets and turrets:FindFirstChild('MeetingRoom')
                    local sentry = room and room:FindFirstChild('Sentry')

                    return sentry ~= nil and sentry:FindFirstChild('Destroyed') == nil
                end
                local function isPrize(name, zindex)
                    return zindex == 5 or zindex == 6 or name == 'Azael Horn' or name == 'Phoenix Down'
                end
                local function collectNearby()
                    local identify = ctx.State.identifyTrinket
                    local root = Character.root()

                    if not (identify and root and fireclickdetector) then
                        return
                    end

                    local wanted = wantedFilter()
                    local guarded = sentryLive()
                    local targets = {}

                    for _, obj in Workspace:GetChildren()do
                        if obj.Name == 'Part' and obj:FindFirstChild('ID') then
                            local d = (obj.Position - root.Position).Magnitude

                            if d < COLLECT_RADIUS then
                                local name, _, zindex = identify(obj)
                                local covered = guarded and (obj.Position - MORI_SPOT).Magnitude <= MORI_RADIUS

                                if wanted(name, zindex) and not (covered and not isPrize(name, zindex)) then
                                    table.insert(targets, obj)
                                end
                            end
                        end
                    end

                    local anchor = root.Position

                    while#targets > 0 and running do
                        table.sort(targets, function(a, b)
                            return (a.Position - anchor).Magnitude < (b.Position - anchor).Magnitude
                        end)

                        local obj = table.remove(targets, 1)

                        if obj.Parent then
                            anchor = obj.Position

                            tele(anchor)

                            local cd = obj:FindFirstChild('ClickDetector', true)

                            if cd then
                                pcall(fireclickdetector, cd)
                            end

                            local me = Character.root()

                            for _, other in targets do
                                local ocd = other.Parent and other:FindFirstChild('ClickDetector', true)

                                if ocd and me and (other.Position - me.Position).Magnitude <= ocd.MaxActivationDistance then
                                    pcall(fireclickdetector, ocd)
                                end
                            end
                        end
                    end
                end
                local function summary(before, beforeValue)
                    local after, gained = bagNames(), {}

                    for name, count in after do
                        local had = before[name] or 0

                        if count > had then
                            table.insert(gained, string.format('%dx %s', count - had, name))
                        end
                    end

                    local body = #gained > 0 and table.concat(gained, '\n') or 'No items collected'
                    local serverName, serverRegion = serverInfo()
                    local elapsed = sessionStart > 0 and (tick() - sessionStart) or 0
                    local playerCount = #Players:GetPlayers()
                    local footerText = Webhook.config.showUsername and string.format('Players: %d/23 | %s | Job: %s', playerCount, LocalPlayer.Name, game.JobId) or string.format('Players: %d/23 | Job: %s', playerCount, game.JobId)
                    local embed = {
                        title = string.format('Castle Rock #%d | RUN COMPLETE', runCount),
                        description = string.format(
[[**Server:** `%s (%s)`
**Inventory Value:** %d (was %d)
**Session:** %dh %dm %ds]], serverName ~= '' and serverName or 'Unknown', serverRegion ~= '' and serverRegion or 'Unknown', bagValue(), beforeValue, math.floor(elapsed / 3600), math.floor((elapsed % 3600) / 60), math.floor(elapsed % 60)),
                        color = 0xff3679,
                        fields = {
                            {
                                name = 'Items Collected',
                                value = string.format('```\n%s```', body),
                                inline = false,
                            },
                        },
                        footer = {text = footerText},
                        timestamp = os.date('!%Y-%m-%dT%H:%M:%SZ'),
                    }

                    task.spawn(function()
                        Webhook.embed(embed)
                    end)
                end
                local function waitForCharacter(timeout, exclude)
                    local deadline = tick() + (timeout or 60)

                    while running and tick() < deadline do
                        local char = LocalPlayer.Character

                        if char and char ~= exclude and char:FindFirstChild('HumanoidRootPart') and char:FindFirstChildOfClass('Humanoid') then
                            return true
                        end

                        task.wait(0.25)
                    end

                    return false
                end
                local function spawnIn()
                    local deadline = tick() + 25

                    while running and tick() < deadline do
                        if Menu.startMenu() then
                            Menu.clickPlay()
                            task.wait(0.5)

                            continue
                        end

                        local char = LocalPlayer.Character

                        if char and char:FindFirstChild('HumanoidRootPart') and char:FindFirstChildOfClass('Humanoid') then
                            Character.awaitPlaced(function()
                                return running
                            end, 15)

                            return true
                        end

                        task.wait(0.25)
                    end

                    return false
                end
                local function waitOutDanger()
                    local char = LocalPlayer.Character

                    if not (char and CollectionService:HasTag(char, 'Danger')) then
                        return
                    end

                    log('holding until the Danger tag drops')

                    repeat
                        char = LocalPlayer.Character

                        while char and CollectionService:HasTag(char, 'Danger') do
                            RunService.Heartbeat:Wait()

                            char = LocalPlayer.Character
                        end

                        task.wait(0.5)

                        char = LocalPlayer.Character
                    until not (char and CollectionService:HasTag(char, 'Danger'))
                end
                local function killAndMenu()
                    if Menu.startMenu() then
                        return
                    end

                    waitOutDanger()

                    local old = LocalPlayer.Character

                    ownDeathUntil = tick() + 12

                    pcall(Character.kill)

                    if not waitForCharacter(45, old) then
                        log('no fresh character after the kill, menuing anyway')
                    end

                    Menu.waitMenuReady(MENU_READY_WAIT, true)
                    Menu.returnToMenu()
                end
                local function fetchFeather()
                    if held(FEATHER) then
                        return true
                    end

                    local function yetiAt()
                        local npcs = Workspace:FindFirstChild('NPCs')
                        local yeti = npcs and npcs:FindFirstChild(YETI)
                        local hrp = yeti and yeti:FindFirstChild('HumanoidRootPart')

                        return hrp and hrp.Position or nil
                    end

                    if not yetiAt() then
                        log('no %s in this server to ask for a %s', YETI, FEATHER)

                        return false
                    end

                    log('no %s in the pack, going to %s for another', FEATHER, YETI)
                    waitOutDanger()

                    if not running then
                        return false
                    end
                    if not Menu.menuTele(yetiAt, function()
                        return running
                    end) then
                        log('could not menu teleport to %s', YETI)

                        return false
                    end

                    local npcs = Workspace:FindFirstChild('NPCs')
                    local yeti = npcs and npcs:FindFirstChild(YETI)

                    if not yeti then
                        log('%s was gone by the time we landed', YETI)

                        return false
                    end

                    Dialogue.run(yeti, {
                        'Sure.',
                    }, {
                        shouldRun = function()
                            return running
                        end,
                        log = function(line)
                            log('%s', line)
                        end,
                    })

                    local waited = 0

                    while running and not held(FEATHER) and waited < FEATHER_SETTLE do
                        task.wait(0.25)

                        waited += 0.25
                    end

                    if not held(FEATHER) then
                        log('%s handed nothing over', YETI)

                        return false
                    end

                    waitOutDanger()

                    local old = LocalPlayer.Character

                    ownDeathUntil = tick() + 12

                    pcall(Character.kill)

                    if not waitForCharacter(45, old) then
                        log('no fresh character after fetching the %s', FEATHER)

                        return false
                    end

                    task.wait(RESPAWN_SETTLE)

                    return held(FEATHER)
                end
                local function park(seconds, why, quiet)
                    if not quiet then
                        log('waiting %ds %s: %s', seconds, Menu.startMenu() and 'in the menu' or 'in place', why)
                    end

                    local until_ = tick() + seconds

                    while running and tick() < until_ do
                        task.wait(1)
                    end

                    return running
                end
                local function handleDeath()
                    if deathHandled or not running or tick() < ownDeathUntil then
                        return
                    end

                    deathHandled = true

                    log('died to something we did not do, not going back')

                    if thread then
                        pcall(task.cancel, thread)

                        thread = nil
                    end

                    traversing = false

                    notify('Castle Rock: the bot died, stopping')
                    Webhook.textBounded('@everyone Castle Rock: bot died, stopping')
                    stop(true)
                    Menu.waitMenuReady(MENU_READY_WAIT, true)
                    Menu.returnToMenu()

                    if stayIn() then
                        log('staying in server, parked in the menu')

                        return
                    end

                    waitOutDanger()
                    Kick.now('sentinel: bot died during Castle Rock - stopped')
                end
                local function watchDeaths()
                    local function hook(char)
                        local hum = char and char:WaitForChild('Humanoid', 10)

                        if hum then
                            runMaid.deathWatch = hum.Died:Connect(handleDeath)
                        end
                    end

                    runMaid:Connect(LocalPlayer.CharacterAdded, hook)
                    task.spawn(hook, LocalPlayer.Character)
                end
                local function handleModerator(p)
                    if modHandled or not running or p == LocalPlayer or (allied(p) and not AvoidList.has(p)) then
                        return
                    end

                    modHandled = true

                    local onPath = traversing
                    local key = 'cr_mod_' .. p.Name
                    local count = (tonumber(MemStore.get(key)) or 0) + 1

                    MemStore.set(key, count)

                    local who = AvoidList.label(p)

                    log('%s %s (encounter %d), %s', who:lower(), p.Name, count, onPath and 'on the path' or 'idle')

                    if thread then
                        pcall(task.cancel, thread)

                        thread = nil
                    end

                    traversing = false

                    if onPath then
                        killAndMenu()
                    else
                        local deadline = tick() + 30

                        Menu.forceMenu(function()
                            return tick() < deadline
                        end)
                    end
                    if stayIn() then
                        Webhook.textBounded(string.format(
[[@everyone Castle Rock: %s **%s** (encounter %d) - stopping, staying in server]], who:lower(), p.Name, count))
                        notify(who .. ' ' .. p.Name .. ' - stopping Castle Rock')
                        stop(true)

                        return
                    end
                    if count >= 3 then
                        Webhook.textBounded(string.format('@everyone Castle Rock: %s **%s** encountered %dx - kicking', who:lower(), p.Name, count))
                        stop(true)
                        waitOutDanger()
                        Kick.now(who .. ' encountered during Castle Rock')

                        return
                    end

                    Webhook.text(string.format('Castle Rock: %s %s (%d/3) - hopping', who:lower(), p.Name, count))
                    hop(string.format('%s %s (%d/3)', who:lower(), p.Name, count))
                end
                local function handleIllusionist(p)
                    if illuHandled or modHandled or not running then
                        return
                    end

                    illuHandled = true

                    local onPath = traversing

                    log('illusionist %s observing, %s', p.Name, onPath and 'on the path' or 'idle')

                    if thread then
                        pcall(task.cancel, thread)

                        thread = nil
                    end

                    traversing = false

                    task.spawn(Webhook.text, string.format('Castle Rock: illusionist %s observing mid run - hopping', p.Name))

                    if onPath then
                        if hop(p.Name .. ' is an illusionist', true) or not running or stayIn() then
                            return
                        end

                        log('no server took the join, resetting to leave instead')
                        killAndMenu()
                    else
                        local deadline = tick() + 30

                        Menu.forceMenu(function()
                            return tick() < deadline
                        end)
                    end

                    hop(p.Name .. ' is an illusionist')
                end
                local function watchIllusionists()
                    local accum = 0

                    runMaid:Connect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                        dt
                    )
                        accum += dt

                        if accum < 0.25 then
                            return
                        end

                        accum = 0

                        if not (running and traversing) or illuHandled or not flag('CastleSkipIllusionist') or stayIn() then
                            return
                        end

                        for _, p in Players:GetPlayers()do
                            if p ~= LocalPlayer and not allied(p) and Threats.isIllusionist(p) then
                                task.spawn(handleIllusionist, p)

                                return
                            end
                        end
                    end))
                end
                local function isMod(p)
                    return (ctx.State.isModerator and ctx.State.isModerator(p)) or false
                end
                local function sweepModerators()
                    for _, p in Players:GetPlayers()do
                        if isMod(p) then
                            task.spawn(handleModerator, p)
                        end
                    end
                end
                local function watchModerators()
                    runMaid:Connect(Players.PlayerAdded, function(p)
                        task.wait(0.5)

                        if isMod(p) then
                            handleModerator(p)
                        end
                    end)
                    sweepModerators()
                    task.spawn(function()
                        while running and not ctx.State.onModeratorFlagged do
                            task.wait(0.5)
                        end

                        if not running then
                            return
                        end

                        runMaid.flagged = ctx.State.onModeratorFlagged(function(
                            p
                        )
                            handleModerator(p)
                        end)

                        sweepModerators()

                        while running and not ctx.State.moderatorsLoaded do
                            task.wait(1)
                        end

                        if running then
                            sweepModerators()
                        end
                    end)
                end
                local function awaitGoodServer()
                    local menued, reported, lastWhy = false, nil, nil

                    while running do
                        local left = cooldownLeft()

                        if left > 0 then
                            if not menued then
                                menued = true

                                killAndMenu()
                            end

                            local mins = math.ceil(left / 60)

                            if not reported or reported - mins >= 5 then
                                reported = mins

                                log('on cooldown, %dm left, sitting it out in this server', mins)
                            end

                            park(math.min(left + 5, 60), 'cooldown', true)

                            continue
                        end

                        local ok, why = serverOk()

                        if ok then
                            log('server accepted')

                            return true
                        end
                        if stayIn() then
                            if why ~= lastWhy then
                                lastWhy = why

                                log('waiting here: %s', why)
                            end

                            park(15, why, true)
                        else
                            hop(why)

                            return false
                        end
                    end

                    return false
                end
                local function playerNearRoute(route, radius)
                    for _, p in Players:GetPlayers()do
                        if p ~= LocalPlayer and not allied(p) then
                            local hrp = p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                            if hrp then
                                for _, pos in route do
                                    if (hrp.Position - pos).Magnitude <= radius then
                                        return p.Name
                                    end
                                end
                            end
                        end
                    end

                    return nil
                end
                local function eaglePosition()
                    local npcs = Workspace:FindFirstChild('NPCs')
                    local eagle = npcs and npcs:FindFirstChild('The Eagle')
                    local part = eagle and (eagle:FindFirstChild('HumanoidRootPart') or eagle:FindFirstChildWhichIsA('BasePart', true))

                    return part and part.Position or TO_EAGLE[#TO_EAGLE]
                end

                local eagleCrowdedBy = nil

                local function watchEagleApproach()
                    eagleCrowdedBy = nil

                    local watch = Maid.new()

                    runMaid:Give(watch)
                    watch:Connect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                    )
                        if eagleCrowdedBy then
                            return
                        end

                        local at = eaglePosition()

                        for _, p in Players:GetPlayers()do
                            if p ~= LocalPlayer and not allied(p) then
                                local hrp = p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                                if hrp and (hrp.Position - at).Magnitude <= EAGLE_GUARD_RANGE then
                                    eagleCrowdedBy = p.Name

                                    return
                                end
                            end
                        end
                    end))

                    return watch
                end
                local function eagleOutcome()
                    local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                    local failed, refused = false, false
                    local watch = Maid.new()

                    runMaid:Give(watch)

                    if pg then
                        watch:Connect(pg.ChildAdded, function(child)
                            if child.Name == 'CaptchaDisclaimer' then
                                failed = true
                            end
                        end)
                    end

                    local requests = Services.ReplicatedStorage:FindFirstChild('Requests')

                    if requests then
                        for _, remote in requests:GetChildren()do
                            if remote:IsA('RemoteEvent') then
                                watch:Connect(remote.OnClientEvent, function(
                                    data
                                )
                                    if type(data) == 'table' and type(data.msg) == 'string' and data.msg:find(REFUSED_LINE, 1, true) then
                                        refused = true
                                    end
                                end)
                            end
                        end
                    end

                    local detector
                    local npcs = Workspace:FindFirstChild('NPCs')
                    local eagle = npcs and npcs:FindFirstChild('The Eagle')

                    detector = eagle and eagle:FindFirstChildWhichIsA('ClickDetector', true)

                    if detector then
                        for _ = 1, 10 do
                            if not running then
                                break
                            end

                            pokeEagle(detector)
                            task.wait(0.1)
                        end
                    end
                    if Captcha.available() and pg then
                        local solved, detail = Captcha.solveGui(pg, 6)

                        log('captcha %s (%s)', solved and 'solved' or 'not solved', tostring(detail))
                    end

                    local deadline = tick() + 15
                    local letIn = false

                    while running and tick() < deadline do
                        local char = LocalPlayer.Character

                        if char and CollectionService:HasTag(char, EAGLE_TAG) then
                            letIn = true

                            break
                        end
                        if failed or refused then
                            break
                        end

                        task.wait(0.2)
                    end

                    watch:DoCleaning()

                    if letIn then
                        return 'in'
                    elseif failed then
                        return 'captcha'
                    elseif refused then
                        return 'refused'
                    end

                    return 'timeout'
                end
                local function isAzaelOrPhilo()
                    if Remotes.getServerValue('Race') == 'Azael' then
                        return true
                    end

                    local char = LocalPlayer.Character
                    local artifacts = char and char:FindFirstChild('Artifacts')

                    return artifacts ~= nil and artifacts:FindFirstChild('PhilosophersStone') ~= nil
                end
                local function snailWaitAvailable()
                    return stayIn() and held('Gate') and isAzaelOrPhilo()
                end
                local function labTrinketNear()
                    local area = ctx.State.trinketArea
                    local root = Character.root()

                    if not (area and root) then
                        return false
                    end

                    for _, obj in Workspace:GetChildren()do
                        if obj.Name == 'Part' and obj:FindFirstChild('ID') then
                            if (obj.Position - root.Position).Magnitude <= LAB_TRINKET_RANGE and area(obj) == LAB_AREA then
                                return true
                            end
                        end
                    end

                    return false
                end
                local function lootRoom()
                    task.wait(LEDGE_ARRIVE_WAIT)
                    waitOutDanger()

                    if not running then
                        return false
                    end
                    if not walk(TO_LEDGE) then
                        return false
                    end

                    ensureBags()
                    ensureLootFloors()

                    local root = Character.root()

                    if not root then
                        return false
                    end

                    traversing = true
                    root.CFrame = CFrame.new(LEDGE_DROP)

                    local dropped = false
                    local fall = Maid.new()

                    runMaid:Give(fall)
                    fall:Connect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                    )
                        local r = Character.root()

                        if r and r.Position.Y < DROP_Y then
                            dropped = true
                        end
                    end))

                    local deadline = tick() + 15
                    local nextCheck, retries = tick() + LEDGE_RETRY_AFTER, 0

                    while running and not dropped and tick() < deadline do
                        if tick() >= nextCheck then
                            nextCheck = tick() + LEDGE_RETRY_AFTER

                            local r = Character.root()

                            if r and retries < LEDGE_RETRIES and math.abs(r.Position.Y - LEDGE_STUCK_Y) <= LEDGE_STUCK_BAND then
                                retries += 1

                                log('still on the ledge at y %.0f, dropping again (%d/%d)', r.Position.Y, retries, LEDGE_RETRIES)

                                r.CFrame = CFrame.new(LEDGE_DROP)
                            end
                        end

                        task.wait()
                    end

                    fall:DoCleaning()

                    if not dropped then
                        traversing = false

                        log('never dropped below %d', DROP_Y)

                        return false
                    end
                    if not walk(POST_DROP) then
                        return false
                    end

                    traversing = true

                    local pin = Maid.new()

                    runMaid:Give(pin)
                    pin:Connect(RunService.RenderStepped, BASIL_NO_VIRTUALIZE(function(
                    )
                        local r = Character.root()

                        if r then
                            r.CFrame = SPAWN_WATCH_CF
                            r.AssemblyLinearVelocity = Vector3.zero
                        end
                    end))
                    log('holding %ds for the trinkets to spawn', POST_DROP_HOLD)

                    local holdUntil = tick() + POST_DROP_HOLD

                    while running and tick() < holdUntil do
                        task.wait(0.25)
                    end

                    pin:DoCleaning()

                    if not running then
                        traversing = false

                        return false
                    end
                    if labTrinketNear() then
                        log(
[[trinkets on the %s floor, walking over for them before the sweep]], LAB_AREA)

                        if not walk(LAB_SWEEP) then
                            return false
                        end

                        traversing = true
                    end

                    for _, spot in LOOT_CFRAMES do
                        if not running then
                            traversing = false

                            return false
                        end

                        local r = Character.root()

                        if r then
                            r.CFrame = spot.cf
                        end

                        lootHere(spot.hold or LOOT_CFRAME_WAIT)
                    end

                    task.wait(LOOT_KILL_WAIT)

                    traversing = false

                    if not running then
                        return false
                    end

                    local char = LocalPlayer.Character

                    if char and CollectionService:HasTag(char, 'Danger') then
                        log(
[[in danger after the loot sweep, holding at the corner until it drops]])

                        local corner = Character.root()

                        if corner then
                            corner.CFrame = LOOT_DANGER_SPOT
                        end

                        waitOutDanger()

                        if not running then
                            return false
                        end
                    end
                    if snailWaitAvailable() then
                        return true
                    end

                    killAndMenu()

                    return true
                end
                local function gateToSnail()
                    local gate = ctx.State.gate

                    if not gate then
                        log('no gate helper available')

                        return false
                    end

                    local mana = ctx.State.mana

                    if mana and mana.available and mana.available() then
                        log('charging to 60 for the gate')
                        mana.chargeUntil(60, function()
                            return running
                        end)
                    end

                    local bot = ctx.State.trinketBot
                    local was = bot and bot.path_running

                    if bot then
                        bot.path_running = true
                    end

                    gating = true

                    local ok = gate(GATE_SPOT) == true

                    gating = false

                    if bot then
                        bot.path_running = was
                    end

                    log('gate to %s: %s', GATE_SPOT, tostring(ok))

                    return ok
                end
                local function runOnce()
                    if not spawnIn() then
                        log('still in the menu after 25s of clicking Play')

                        return false
                    end

                    local before, beforeValue = bagNames(), bagValue()

                    guardsOn()

                    if not Character.near(INN_SPOT, INN_NEAR) then
                        log('not at the inn, binding %s', INN)

                        local atInn = LocalPlayer.Character
                        local bound = NPC.setInn(INN, {
                            shouldRun = function()
                                return running
                            end,
                            breakJoints = true,
                            attempts = 4,
                            log = function(n)
                                log('no keeper found for %s', tostring(n))
                            end,
                        })

                        if not bound then
                            notify('Castle Rock: could not bind ' .. INN)

                            return false
                        end
                        if not waitForCharacter(60, atInn) then
                            return false
                        end

                        task.wait(RESPAWN_SETTLE)
                    end
                    if not fetchFeather() then
                        notify('Castle Rock: could not get a ' .. FEATHER)

                        return false
                    end

                    local eagleWatch = watchEagleApproach()
                    local reached = walk(TO_EAGLE, function()
                        return eagleCrowdedBy ~= nil
                    end)

                    eagleWatch:DoCleaning()

                    if eagleCrowdedBy then
                        local who = eagleCrowdedBy

                        log('%s within %.0f studs of the eagle - abandoning this server', who, EAGLE_GUARD_RANGE)
                        notify('Castle Rock: someone is sat at the eagle, hopping')
                        Webhook.textBounded(string.format(
[[@here Castle Rock aborted: %s within %.0f studs of the eagle]], who, EAGLE_GUARD_RANGE))
                        waitOutDanger()

                        if not running then
                            return false
                        end

                        killAndMenu()
                        hop('player sat at the eagle')

                        return false
                    end
                    if not reached then
                        return false
                    end

                    local outcome = eagleOutcome()

                    log('eagle: %s', outcome)

                    if outcome == 'refused' then
                        notify('skipping cr because it wont let me in')
                        markSuccess()
                        killAndMenu()

                        return false
                    elseif outcome == 'captcha' then
                        notify('Castle Rock: captcha failed, waiting 5m30s')
                        killAndMenu()
                        park(CAPTCHA_FAIL_WAIT, 'captcha failed')

                        return false
                    elseif outcome ~= 'in' then
                        log('no answer from the statue')

                        return false
                    end

                    log('let in, waiting for the drop between y %d and %d', EAGLE_Y_MIN, EAGLE_Y_MAX)

                    local dropDeadline = tick() + EAGLE_DROP_TIMEOUT
                    local landed = false

                    while running and tick() < dropDeadline and not landed do
                        local r = Character.root()
                        local y = r and r.Position.Y

                        landed = y ~= nil and y < EAGLE_Y_MAX and y > EAGLE_Y_MIN

                        if not landed then
                            task.wait(0.1)
                        end
                    end

                    if not running then
                        return false
                    end
                    if not landed then
                        log('never landed in the drop band after %ds, moving anyway', EAGLE_DROP_TIMEOUT)
                    end

                    task.wait(EAGLE_SETTLE_EXTRA)

                    if not walk(ENTRY) then
                        return false
                    end

                    local skipSectionB = nil

                    if not flag('CastleOnlyLootRoom') then
                        skipSectionB = playerNearRoute(TO_SECTION_B_WAIT, SECTION_B_GUARD)

                        if skipSectionB then
                            log(
[[%s within %d studs of the section B route, running section A instead]], skipSectionB, SECTION_B_GUARD)
                        end
                    end
                    if flag('CastleOnlyLootRoom') or skipSectionB then
                        if not walk(SECTION_A) then
                            return false
                        end
                    else
                        if not walk(TO_SECTION_B_WAIT) then
                            return false
                        end

                        tele(SECTION_B_WAIT)
                        task.wait(ARRIVE_SETTLE + 0.1)
                        restoreCollisions()
                        park(TRINKET_SETTLE, 'letting the trinkets spawn')
                        collectNearby()

                        if not walk(SECTION_B) then
                            return false
                        end
                    end
                    if not lootRoom() then
                        return false
                    end

                    collectNearby()
                    markSuccess()

                    runCount += 1

                    summary(before, beforeValue)

                    return true
                end
                local function finish()
                    local loopWait = opt('CastleLoopWait', 30) * 60

                    if snailWaitAvailable() then
                        log('staying in server: gating to %s for the wait', GATE_SPOT)

                        if gateToSnail() and walk(TO_SNAIL) then
                            park(loopWait, 'between loops at the snail')

                            if not running then
                                return 'stopped'
                            end

                            local char = LocalPlayer.Character

                            if not (char and CollectionService:HasTag(char, EAGLE_TAG)) then
                                log(
[[lost the %s tag during the wait - stopping rather than running again]], EAGLE_TAG)
                                notify('Castle Rock: lost the Eagle tag, stopping')
                                Webhook.textBounded('@everyone Castle Rock stopped: lost the ' .. EAGLE_TAG .. ' tag')
                                stop()

                                return 'stopped'
                            end

                            log('tag still held, heading back down')
                            walk(FROM_SNAIL)

                            return 'continue'
                        end

                        log('could not gate to %s, falling back to the kill', GATE_SPOT)
                    end

                    killAndMenu()

                    if stayIn() then
                        park(math.max(loopWait, COOLDOWN), 'between loops in the menu')

                        return 'continue'
                    end

                    park(loopWait, 'between loops')
                    hop('run finished')

                    return 'hopped'
                end
                local function runCore()
                    while running do
                        if not awaitGoodServer() then
                            return
                        end

                        local ok = runOnce()

                        if not running then
                            return
                        end
                        if not ok then
                            guardsOff()
                            task.wait(5)

                            continue
                        end
                        if finish() ~= 'continue' then
                            return
                        end
                    end
                end

                section:AddDropdown('CastlePickupMythicsArtifacts', {
                    Text = 'Pick Up Mythics/Artifacts',
                    Values = MYTHIC_ARTIFACT_TYPES,
                    Default = table.clone(MYTHIC_ARTIFACT_TYPES),
                    Multi = true,
                    AllowNull = true,
                })
                section:AddToggle('CastlePickupTrinkets', {
                    Text = 'Pick Up Common Trinkets',
                    Default = true,
                })
                section:AddToggle('CastlePickupScrolls', {
                    Text = 'Pick Up Scrolls',
                    Default = true,
                })
                section:AddToggle('CastlePickupIceEssence', {
                    Text = 'Pick Up Ice Essence',
                    Default = false,
                })
                section:AddToggle('CastlePickupEventItems', {
                    Text = 'Pick Up Event Items',
                    Default = true,
                })
                section:AddDivider()
                section:AddToggle('CastleOnlyLootRoom', {
                    Text = 'Only Loot Room',
                    Default = false,
                })
                section:AddSlider('CastleMinPlayers', {
                    Text = 'Min Players In Server',
                    Default = 0,
                    Min = 0,
                    Max = 23,
                    Rounding = 0,
                })
                section:AddSlider('CastleMinLastLooted', {
                    Text = 'Min Last Looted',
                    Default = 0,
                    Min = 0,
                    Max = 60,
                    Rounding = 0,
                    Suffix = 'm',
                })
                section:AddToggle('CastleSkipIllusionist', {
                    Text = 'Skip Illusionist Server',
                    Default = true,
                })
                section:AddToggle('CastleHoldPebble', {
                    Text = 'Hold Pebble/Perflora',
                    Tooltip = 'Holds the one picked below, else the other',
                    Default = false,
                })
                section:AddDropdown('CastleHoldItem', {
                    Text = 'Hold',
                    Values = {
                        'Perflora',
                        'Pebble',
                    },
                    Default = 'Perflora',
                })
                section:AddDivider()
                section:AddToggle('CastleStayInServer', {
                    Text = 'Stay In Server',
                    Tooltip = 'Never hops or menus',
                    Default = false,
                })
                section:AddSlider('CastleLoopWait', {
                    Text = 'Time Between Loops',
                    Default = 30,
                    Min = 0,
                    Max = 30,
                    Rounding = 0,
                    Suffix = 'm',
                })

                startButton = section:AddButton({
                    Text = 'Start',
                    Tooltip = ModeGate.blatant(),
                    Func = function()
                        if running then
                            return
                        end
                        if not ModeGate.allow(ctx, 'Blatant', 'Castle Rock') then
                            return
                        end

                        setRunning(true)

                        modHandled = false
                        illuHandled = false
                        deathHandled = false

                        watchModerators()
                        watchIllusionists()
                        watchDeaths()

                        sessionStart = tick()

                        saveSettings()

                        thread = task.spawn(function()
                            local function bail(why)
                                log('%s', why)
                                notify('Castle Rock: ' .. why)
                                guardsOff()
                                setRunning(false)
                                runMaid:DoCleaning()
                            end

                            if not spawnIn() then
                                bail('could not spawn in to read the pack')

                                return
                            end
                            if not held(FEATHER) then
                                bail('needs a ' .. FEATHER)

                                return
                            end

                            local dash

                            for _, name in DASHES do
                                if held(name) then
                                    dash = name

                                    break
                                end
                            end

                            if not dash then
                                bail('needs ' .. table.concat(DASHES, ' or '))

                                return
                            end

                            log('started (%s)', dash)

                            local ok, err = pcall(runCore)

                            if not ok then
                                log('stopped on an error: %s', tostring(err))
                            end

                            guardsOff()
                            setRunning(false)
                            runMaid:DoCleaning()
                        end)
                    end,
                })
                stopButton = section:AddButton({
                    Text = 'Stop',
                    Func = function()
                        stop()
                    end,
                })

                section:AddButton({
                    Text = 'Reset Cooldown',
                    Func = function()
                        clearCooldown()
                        log('cooldown cleared')
                        notify('Castle Rock cooldown cleared')
                    end,
                })

                local resuming = MemStore.get('castlerock_active') == 'true'

                setRunning(false)

                if resuming and Serverhop.claimResume({
                    'castlerock_active',
                }) then
                    restoreSettings()
                    setRunning(true)

                    modHandled = false
                    illuHandled = false
                    deathHandled = false

                    watchModerators()
                    watchIllusionists()
                    watchDeaths()
                    log('resumed after a serverhop')

                    thread = task.spawn(function()
                        local ok, err = pcall(runCore)

                        if not ok then
                            log('stopped on an error: %s', tostring(err))
                        end

                        guardsOff()
                        setRunning(false)
                        runMaid:DoCleaning()
                    end)
                end
            end
        end

        function __DARKLUA_BUNDLE_MODULES.ad(): typeof(__modImpl())
            local v = __DARKLUA_BUNDLE_MODULES.cache.ad

            if not v then
                v = {
                    c = __modImpl(),
                }
