            local KEY_HOLD_DEFAULT = 0.05
            local keyPress = keypress
            local keyRelease = keyrelease

            return function(ctx)
                local Library = ctx.Library
                local Toggles, Options = Library.Toggles, Library.Options
                local Combat = ctx.Tabs.Combat
                local maid = Maid.new()

                ctx.Maid:Give(maid)

                local function notify(text)
                    Notify.say(text)
                end

                local stopping = false
                local runningMacros = {}
                local lastMissingNotify = {}
                local vimInstance

                local function getVim()
                    if not vimInstance then
                        local ok, v = pcall(function()
                            return Instance.new('VirtualInputManager')
                        end)

                        vimInstance = ok and v or nil
                    end

                    return vimInstance
                end

                local windowActive = true

                maid:Give(UserInputService.WindowFocused:Connect(function()
                    windowActive = true
                end))
                maid:Give(UserInputService.WindowFocusReleased:Connect(function()
                    windowActive = false
                end))

                local lastM1 = 0

                maid:Give(UserInputService.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 then
                        local char = LocalPlayer.Character

                        if char and char:FindFirstChild('Dagger') then
                            lastM1 = tick()
                        end
                    end
                end))

                local function clickRemote(name)
                    local char = LocalPlayer.Character
                    local handler = char and char:FindFirstChild('CharacterHandler')
                    local remotes = handler and handler:FindFirstChild('Remotes')

                    return remotes and remotes:FindFirstChild(name)
                end
                local function leftClick(ctl)
                    if ctl and ctl.stop then
                        return
                    end

                    lastM1 = tick()

                    local vim = getVim()

                    if vim then
                        task.spawn(function()
                            vim:SendMouseButtonEvent(0, 0, 0, true, game, 1)
                            task.wait(math.random(1, 15) / 1000)
                            vim:SendMouseButtonEvent(0, 0, 0, false, game, 1)
                        end)
                    end

                    local remote = clickRemote('LeftClick')

                    if remote then
                        pcall(function()
                            remote:FireServer({
                                math.random(1, 10),
                                tonumber('0.' .. math.random(1e15, 9e15)),
                            })
                        end)
                    end
                end
                local function m1Click(ctl)
                    if ctl and ctl.stop then
                        return
                    end

                    lastM1 = tick()

                    local vim = getVim()

                    if vim then
                        task.spawn(function()
                            vim:SendMouseButtonEvent(0, 0, 0, true, game, 1)
                            task.wait(math.random(1, 15) / 1000)
                            vim:SendMouseButtonEvent(0, 0, 0, false, game, 1)
                        end)
                    end

                    local press, release = clickRemote('LeftClick'), clickRemote('LeftClickRelease')

                    if press then
                        pcall(press.FireServer, press, {
                            math.random(1, 10),
                            math.random(),
                        })
                    end
                    if release then
                        pcall(release.FireServer, release, {
                            math.random(1, 10),
                            math.random(),
                        })
                    end

                    local char = LocalPlayer.Character
                    local tool = char and char:FindFirstChildOfClass('Tool')

                    if tool then
                        pcall(tool.Activate, tool)
                    end
                end
                local function rightClick(ctl)
                    if ctl and ctl.stop then
                        return
                    end

                    local remote = clickRemote('RightClick')

                    if remote then
                        pcall(function()
                            remote:FireServer({
                                math.random(1, 10),
                                math.random(),
                            })
                        end)
                    end
                end
                local function isStunned()
                    local char = LocalPlayer.Character

                    if not char then
                        return false
                    end

                    for _, obj in char:GetChildren()do
                        if IM_LAZY_STUNS[obj.Name] then
                            return true
                        end
                    end

                    return false
                end
                local function bufferAction(ctl)
                    if tick() - lastM1 < 0.05 then
                        repeat
                            task.wait()
                        until tick() - lastM1 > 0.05 or (ctl and ctl.stop)
                    end
                end
                local function findTool(name)
                    local lower = tostring(name or ''):match('^%s*(.-)%s*$'):lower()

                    if lower == '' then
                        return nil
                    end

                    local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                    if bp then
                        for _, t in bp:GetChildren()do
                            if t:IsA('Tool') and t.Name:lower() == lower then
                                return t
                            end
                        end
                    end

                    local char = LocalPlayer.Character

                    if char then
                        for _, t in char:GetChildren()do
                            if t:IsA('Tool') and t.Name:lower() == lower then
                                return t
                            end
                        end
                    end

                    return nil
                end
                local function punch(accessoryName, clicker, ctl)
                    local char = LocalPlayer.Character

                    if not char then
                        return
                    end

                    local landed = false
                    local conn = char.ChildAdded:Connect(function(obj)
                        if obj:IsA('Accessory') and obj.Name == accessoryName then
                            landed = true
                        end
                    end)

                    pcall(function()
                        local hum = char:FindFirstChildOfClass('Humanoid')
                        local hasDagger = char:FindFirstChild('Dagger')
                        local hasSword = char:FindFirstChild('Sword')

                        if (hasDagger or hasSword) and hum then
                            local bypass = hasDagger and findTool('Agility') or findTool('Action Surge')

                            if bypass then
                                hum:EquipTool(bypass)
                                task.wait(0.04)
                            end
                        end
                        if hum then
                            hum:UnequipTools()
                        end

                        task.wait(0.01)

                        local deadline = os.clock() + PUNCH_TIMEOUT

                        while not landed and not (ctl and ctl.stop) and LocalPlayer.Character == char and char.Parent ~= nil and os.clock() < deadline do
                            clicker(ctl)
                            task.wait(0.01)
                        end
                    end)
                    conn:Disconnect()
                end

                local activeNostun = {}

                local function runAction(action, ctl)
                    if ctl and ctl.stop then
                        return
                    end

                    local char = LocalPlayer.Character
                    local t = action.type

                    if t == 'wait' then
                        task.wait(tonumber(action.duration) or 0.1)
                    elseif t == 'equip' then
                        local tool = findTool(action.tool)
                        local hum = char and char:FindFirstChildOfClass('Humanoid')

                        if tool and hum then
                            hum:EquipTool(tool)
                        end
                    elseif t == 'unequip' then
                        local hum = char and char:FindFirstChildOfClass('Humanoid')

                        if hum then
                            hum:UnequipTools()
                        end

                        task.wait(0.005)
                    elseif t == 'click' then
                        if action.button == 'right' then
                            rightClick(ctl)
                        else
                            m1Click(ctl)
                        end

                        task.wait()
                    elseif t == 'leftclick' then
                        m1Click(ctl)
                        task.wait()
                    elseif t == 'rightclick' then
                        rightClick(ctl)
                        task.wait()
                    elseif t == 'loopclick' then
                        local duration = tonumber(action.duration) or 1
                        local interval = 1 / math.max(1, (Options.AutoclickerCPS and Options.AutoclickerCPS.Value) or 10)
                        local start = tick()

                        while tick() - start < duration and not (ctl and ctl.stop) do
                            m1Click(ctl)
                            task.wait(interval)
                        end
                    elseif t == 'keypress' then
                        local vk = action.key and VK_CODES[action.key]

                        if vk and windowActive and keyPress then
                            keyPress(vk)
                            task.wait(tonumber(action.hold) or KEY_HOLD_DEFAULT)

                            if keyRelease then
                                keyRelease(vk)
                            end
                        end
                    elseif t == 'charge' then
                        local mana = ctx.State.mana

                        if mana and mana.chargeUntil then
                            mana.chargeUntil(tonumber(action.amount) or 50)
                        end
                    elseif t == 'bufferaction' then
                        bufferAction(ctl)
                    elseif t == 'waitstun' then
                        if isStunned() then
                            repeat
                                task.wait()
                            until not isStunned() or (ctl and ctl.stop)
                        end
                    elseif t == 'nostun' then
                        local dur = tonumber(action.duration) or 0.2

                        if char then
                            local conn = char.ChildAdded:Connect(function(obj)
                                if STUNS[obj.Name] then
                                    task.defer(function()
                                        pcall(obj.Destroy, obj)
                                    end)
                                end
                            end)

                            table.insert(activeNostun, conn)
                            task.delay(dur, function()
                                conn:Disconnect()

                                local idx = table.find(activeNostun, conn)

                                if idx then
                                    table.remove(activeNostun, idx)
                                end
                            end)
                        end
                    elseif t == 'heavypunch' then
                        punch('HeavyAttack', rightClick, ctl)
                    elseif t == 'punch' then
                        punch('LightAttack', leftClick, ctl)
                    end
                end
                local function missingTools(actions)
                    local missing, seen = {}, {}

                    for _, action in ipairs(actions)do
                        local name = action.type == 'equip' and tostring(action.tool or ''):match('^%s*(.-)%s*$') or ''

                        if name ~= '' then
                            local key = name:lower()

                            if not seen[key] and not findTool(name) then
                                seen[key] = true

                                table.insert(missing, name)
                            end
                        end
                    end

                    return missing
                end
                local function requiresInAir(actions)
                    for _, action in ipairs(actions)do
                        if action.type == 'inair' then
                            return true
                        end
                    end

                    return false
                end
                local function gateValue(label)
                    local char = LocalPlayer.Character

                    if label == 'Mana' then
                        local mana = char and char:FindFirstChild('Mana')

                        return mana and tonumber(mana.Value)
                    elseif label == 'Health' then
                        local hum = char and char:FindFirstChildOfClass('Humanoid')

                        return hum and hum.Health
                    elseif label == 'Health %' then
                        local hum = char and char:FindFirstChildOfClass('Humanoid')

                        return (hum and hum.MaxHealth > 0) and (hum.Health / hum.MaxHealth * 100) or nil
                    elseif label == 'Players In Server' then
                        return #Players:GetPlayers()
                    end

                    return nil
                end
                local function gatePasses(gate)
                    if type(gate) ~= 'table' or not gate.var then
                        return true
                    end

                    local have = gateValue(gate.var)
                    local want = tonumber(gate.value)

                    if have == nil or want == nil then
                        return true
                    end

                    local op = gate.op

                    if op == '>=' then
                        return have >= want
                    elseif op == '<=' then
                        return have <= want
                    elseif op == '>' then
                        return have > want
                    elseif op == '<' then
                        return have < want
                    elseif op == '==' then
                        return have == want
                    end

                    return true
                end
                local function runMacro(name, actions, gate)
                    if stopping or runningMacros[name] or type(actions) ~= 'table' or not LocalPlayer.Character then
                        return
                    end
                    if not gatePasses(gate) then
                        if tick() - (lastMissingNotify[name] or 0) > 30 then
                            lastMissingNotify[name] = tick()

                            notify(string.format('%s held: %s %s %s not met', name, tostring(gate.var), tostring(gate.op), tostring(gate.value)))
                        end

                        return
                    end
                    if LocalPlayer.Character:FindFirstChild('FlightOk') and LocalPlayer.Character:FindFirstChild('GeliFreezing') then
                        return
                    end

                    local missing = missingTools(actions)

                    if #missing > 0 then
                        if tick() - (lastMissingNotify[name] or 0) > 300 then
                            lastMissingNotify[name] = tick()

                            notify(name .. ' needs: ' .. table.concat(missing, ', '))
                        end

                        return
                    end

                    local hrp = LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                    if requiresInAir(actions) and not (hrp and hrp:FindFirstChild('GrappleVelocity')) then
                        if tick() - (lastMissingNotify[name] or 0) > 300 then
                            lastMissingNotify[name] = tick()

                            notify(name .. ' needs: InAir')
                        end

                        return
                    end

                    local ctl = {stop = false}

                    runningMacros[name] = ctl

                    if ctx.State.toyAlert then
                        ctx.State.toyAlert('Macro Run')
                    end

                    pcall(function()
                        for _, action in ipairs(actions)do
                            if ctl.stop then
                                break
                            end
                            if action.type == 'loopclick' then
                                task.spawn(runAction, action, ctl)
                            else
                                runAction(action, ctl)
                            end
                        end
                    end)
                    task.wait(0.4)

                    runningMacros[name] = nil
                end
                local function stopMacro()
                    stopping = true

                    for _, ctl in runningMacros do
                        ctl.stop = true
                    end
                    for _, conn in activeNostun do
                        pcall(function()
                            conn:Disconnect()
                        end)
                    end

                    table.clear(activeNostun)
                end

                ctx.Maid:Give(stopMacro)

                local function ensureDir()
                    if makefolder and not (isfolder and isfolder(MACRO_DIR)) then
                        pcall(makefolder, 'sentinel')
                        pcall(makefolder, MACRO_DIR)
                    end
                end
                local function listMacros()
                    local out = {}

                    if not listfiles then
                        return out
                    end

                    ensureDir()

                    local ok, files = pcall(listfiles, MACRO_DIR)

                    if ok and files then
                        for _, f in files do
                            local n = tostring(f):match('([^/\\]+)%.json$')

                            if n then
                                table.insert(out, n)
                            end
                        end
                    end

                    return out
                end
                local function readMacro(name)
                    if not (isfile and readfile) or not name or name == '' then
                        return nil
                    end

                    local path = MACRO_DIR .. '/' .. name .. '.json'

                    if not isfile(path) then
                        return nil
                    end

                    local ok, decoded = pcall(function()
                        return HttpService:JSONDecode(readfile(path))
                    end)

                    if ok and type(decoded) == 'table' and type(decoded.actions) == 'table' then
                        return decoded
                    end

                    return nil
                end

                local loadedMacros = {}

                local function reloadMacros()
                    table.clear(loadedMacros)

                    for _, name in listMacros()do
                        local m = readMacro(name)

                        if m then
                            loadedMacros[name] = {
                                keybind = m.keybind or 'None',
                                actions = m.actions,
                                gate = m.gate,
                            }
                        end
                    end
                end
                local function beautifyJson(s)
                    local out, indent, i, n = {}, 0, 1, #s

                    local function newline()
                        out[#out + 1] = '\n' .. string.rep('\t', indent)
                    end

                    while i <= n do
                        local c = s:sub(i, i)

                        if c == '"' then
                            local j = i + 1

                            while j <= n do
                                local cj = s:sub(j, j)

                                if cj == '\\' then
                                    j = j + 2
                                elseif cj == '"' then
                                    break
                                else
                                    j = j + 1
                                end
                            end

                            out[#out + 1] = s:sub(i, j)
                            i = j + 1
                        elseif c == '{' or c == '[' then
                            local nxt = s:sub(i + 1, i + 1)

                            if nxt == '}' or nxt == ']' then
                                out[#out + 1] = c .. nxt
                                i = i + 2
                            else
                                indent += 1

                                out[#out + 1] = c

                                newline()

                                i += 1
                            end
                        elseif c == '}' or c == ']' then
                            indent -= 1

                            newline()

                            out[#out + 1] = c

                            i += 1
                        elseif c == ',' then
                            out[#out + 1] = c

                            newline()

                            i += 1
                        elseif c == ':' then
                            out[#out + 1] = ': '

                            i += 1
                        else
                            out[#out + 1] = c

                            i += 1
                        end
                    end

                    return table.concat(out)
                end
                local function saveMacro(name, keybind, actions, gate)
                    if not writefile or not name or name == '' then
                        notify('Enter a macro name first')

                        return false
                    end

                    ensureDir()

                    local encoded = select(2, pcall(function()
                        return HttpService:JSONEncode({
                            name = name,
                            keybind = keybind or 'None',
                            gate = gate,
                            actions = actions,
                        })
                    end))

                    if type(encoded) ~= 'string' then
                        return false
                    end

                    local ok = pcall(writefile, MACRO_DIR .. '/' .. name .. '.json', beautifyJson(encoded))

                    if ok then
                        reloadMacros()
                    end

                    return ok
                end
                local function deleteMacro(name)
                    if delfile and name and name ~= '' then
                        pcall(delfile, MACRO_DIR .. '/' .. name .. '.json')
                        reloadMacros()
                    end
                end

                local macroWindow
                local refreshAll, refreshTriggerRows
                local currentMacroName = nil

                local function saveMacroKeybind(name, keybind)
                    local m = loadedMacros[name]

                    if m and saveMacro(name, keybind, m.actions, m.gate) then
                        m.keybind = keybind
                    end
                end

                macroWindow = Library:CreateMacroCreator({
                    Title = 'macro creator',
                    Visible = false,
                    GateVars = {
                        {
                            label = 'Mana',
                            ops = {
                                '>=',
                                '<=',
                                '>',
                                '<',
                            },
                        },
                        {
                            label = 'Health',
                            ops = {
                                '>=',
                                '<=',
                                '>',
                                '<',
                            },
                        },
                        {
                            label = 'Health %',
                            ops = {
                                '>=',
                                '<=',
                                '>',
                                '<',
                            },
                        },
                        {
                            label = 'Players In Server',
                            ops = {
                                '>=',
                                '<=',
                                '==',
                            },
                        },
                    },
                    OnSave = function(sequence)
                        local name = macroWindow:GetName()

                        if name == '' then
                            notify('Enter a macro name first')

                            return
                        end

                        local keybind = (loadedMacros[name] and loadedMacros[name].keybind) or (currentMacroName and loadedMacros[currentMacroName] and loadedMacros[currentMacroName].keybind) or 'None'

                        if saveMacro(name, keybind, sequence, macroWindow:GetGate()) then
                            currentMacroName = name

                            notify('Saved macro: ' .. name)
                            refreshAll()
                        else
                            notify('Save failed (name + writefile required)')
                        end
                    end,
                    OnLoad = function(name)
                        local m = readMacro(name)

                        if not m then
                            notify('Select a saved macro to load')

                            return nil
                        end

                        macroWindow:SetName(m.name or name)
                        macroWindow:SetGate(m.gate)

                        currentMacroName = m.name or name

                        return m.actions
                    end,
                    OnSelect = function(name)
                        currentMacroName = name
                    end,
                    OnClear = function()
                        currentMacroName = nil

                        macroWindow:SetGate(nil)
                    end,
                    OnDelete = function(name)
                        deleteMacro(name)

                        if name == currentMacroName then
                            currentMacroName = nil
                        end

                        notify('Deleted macro: ' .. tostring(name))
                        refreshAll()
                    end,
                })

                macroWindow:RegisterStepType('equip', {
                    Label = 'Equip',
                    Color = Color3.fromRGB(125, 85, 255),
                    Fields = {
                        {
                            Key = 'tool',
                            Kind = 'text',
                            Default = '',
                            Width = 96,
                            Placeholder = 'tool name',
                        },
                    },
                })
                macroWindow:RegisterStepType('unequip', {
                    Label = 'Unequip',
                    Color = Color3.fromRGB(160, 130, 200),
                })
                macroWindow:RegisterStepType('loopclick', {
                    Label = 'Loop Click',
                    Color = Color3.fromRGB(0, 255, 255),
                    Fields = {
                        {
                            Key = 'duration',
                            Kind = 'number',
                            Default = 1,
                            Width = 38,
                        },
                    },
                })
                macroWindow:RegisterStepType('charge', {
                    Label = 'Charge Mana',
                    Color = Color3.fromRGB(85, 120, 255),
                    Fields = {
                        {
                            Key = 'amount',
                            Kind = 'number',
                            Default = 50,
                            Width = 38,
                        },
                    },
                })
                macroWindow:RegisterStepType('nostun', {
                    Label = 'No Stun',
                    Color = Color3.fromRGB(255, 136, 0),
                    Fields = {
                        {
                            Key = 'duration',
                            Kind = 'number',
                            Default = 0.2,
                            Width = 38,
                        },
                    },
                })
                macroWindow:RegisterStepType('bufferaction', {
                    Label = 'Buffer Action',
                    Color = Color3.fromRGB(255, 80, 255),
                })
                macroWindow:RegisterStepType('waitstun', {
                    Label = 'Wait Stun',
                    Color = Color3.fromRGB(255, 85, 85),
                })
                macroWindow:RegisterStepType('inair', {
                    Label = 'In Air',
                    Color = Color3.fromRGB(130, 200, 255),
                })
                macroWindow:RegisterStepType('heavypunch', {
                    Label = 'Heavy Punch',
                    Color = Color3.fromRGB(255, 170, 0),
                })
                macroWindow:RegisterStepType('punch', {
                    Label = 'Punch',
                    Color = Color3.fromRGB(255, 210, 110),
                })

                local MacroBox = Combat:AddLeftGroupbox('Macros')
                local TRIGGER_POOL = 12
                local triggerRows = {}

                for i = 1, TRIGGER_POOL do
                    local idx = 'MacroTrigger' .. i
                    local label = MacroBox:AddLabel('Trigger')

                    label:SetVisible(false)
                    label:AddKeyPicker(idx, {
                        Default = 'None',
                        Mode = 'Press',
                        Modes = {
                            'Press',
                        },
                        NoUI = true,
                        Text = 'Macro Trigger',
                        Callback = function()
                            local row = triggerRows[i]

                            if row and row.name and loadedMacros[row.name] then
                                task.spawn(runMacro, row.name, loadedMacros[row.name].actions, loadedMacros[row.name].gate)
                            end
                        end,
                        ChangedCallback = function(value)
                            local row = triggerRows[i]

                            if row and not row.suppress and row.name then
                                saveMacroKeybind(row.name, value)
                            end
                        end,
                    })

                    triggerRows[i] = {
                        label = label,
                        picker = Options[idx],
                        name = nil,
                        suppress = false,
                    }
                end

                local function saveActiveMacros()
                    local names = {}
                    local active = Options.ActiveMacros and Options.ActiveMacros.Value or {}

                    for name, on in active do
                        if on then
                            table.insert(names, name)
                        end
                    end

                    MemStore.setJSON('macros_active', names)
                end

                MacroBox:AddDropdown('ActiveMacros', {
                    Text = 'Active Macros',
                    Tooltip = 'Each gets its own keybind',
                    Values = listMacros(),
                    Default = {},
                    Multi = true,
                    AllowNull = true,
                    Callback = function()
                        saveActiveMacros()

                        if refreshTriggerRows then
                            refreshTriggerRows()
                        end
                    end,
                })

                function refreshTriggerRows()
                    local armed = {}
                    local active = Options.ActiveMacros and Options.ActiveMacros.Value or {}

                    for name, on in active do
                        if on and loadedMacros[name] then
                            table.insert(armed, name)
                        end
                    end

                    table.sort(armed)

                    for i = 1, TRIGGER_POOL do
                        local row = triggerRows[i]
                        local name = armed[i]

                        row.suppress = true

                        if name then
                            row.name = name

                            row.label:SetText(name .. ' Trigger Key')
                            row.label:SetVisible(true)
                            row.picker:SetValue(loadedMacros[name].keybind or 'None')
                        else
                            row.name = nil

                            row.label:SetVisible(false)
                            row.picker:SetValue('None')
                        end

                        row.suppress = false
                    end
                end
                function refreshAll()
                    reloadMacros()

                    local names = listMacros()

                    if Options.ActiveMacros then
                        Options.ActiveMacros:SetValues(names)
                    end
                    if macroWindow then
                        macroWindow:SetSavedList(names)
                    end

                    refreshTriggerRows()
                end

                MacroBox:AddButton({
                    Text = 'Reload Macros',
                    Func = refreshAll,
                })
                MacroBox:AddButton({
                    Text = 'Open Macro Creator',
                    Func = function()
                        macroWindow:Toggle()
                    end,
                })
                refreshAll()

                do
                    local saved = MemStore.getJSON('macros_active')

                    if type(saved) == 'table' and Options.ActiveMacros then
                        local valid = {}

                        for _, name in saved do
                            if loadedMacros[name] then
                                table.insert(valid, name)
                            end
                        end

                        if #valid > 0 then
                            Options.ActiveMacros:SetValue(valid)
                        end
                    end
                end
            end
        end

