                        end

                        pcall(chair.Activate, chair)

                        local deadline = os.clock() + 0.75

                        repeat
                            task.wait(0.05)
                        until seated() or os.clock() >= deadline

                        if seated() then
                            return true
                        end
                    end

                    return false
                end
                local function handleDeath()
                    if deathHandled or not farming() then
                        return
                    end

                    deathHandled = true

                    task.spawn(function()
                        local respawned = false
                        local conn = LocalPlayer.CharacterAdded:Connect(function(
                        )
                            respawned = true
                        end)
                        local waited = 0

                        while not respawned and waited < 30 do
                            task.wait(0.25)

                            waited += 0.25
                        end

                        pcall(function()
                            conn:Disconnect()
                        end)

                        if not farming() then
                            return
                        end

                        task.wait(2)

                        if not farming() then
                            return
                        end

                        returnToMenu()
                        Webhook.textBounded('player died during day farm')
                        Notify.say('Died during day farm - menuing + kicking')
                        Kick.now('player died during day farm')
                        Library:Unload()
                    end)
                end
                local function watchDeath(char)
                    local humanoid = char and char:FindFirstChildOfClass('Humanoid')
                    local deadline = os.clock() + 10

                    while char and not humanoid and os.clock() < deadline do
                        task.wait(0.1)

                        humanoid = char:FindFirstChildOfClass('Humanoid')
                    end

                    if humanoid and farming() and LocalPlayer.Character == char then
                        farmMaid.death = humanoid.Died:Connect(handleDeath)
                    end
                end
                local function handleDangerCaught(char)
                    if Toggles.BlatantMode and Toggles.BlatantMode.Value then
                        Toggles.BlatantMode:SetValue(false)
                    end

                    Webhook.text(
[[Day farm: lost forcefield in Danger - disabled Blatant Mode, waiting for combat to clear or death]])
                    Notify.say('Caught in Danger - disabled Blatant Mode, waiting it out')

                    while Toggles.DayFarm.Value and not deathHandled do
                        local c = LocalPlayer.Character

                        if not c or c ~= char then
                            break
                        end
                        if not CollectionService:HasTag(c, 'Danger') then
                            break
                        end

                        task.wait(0.2)
                    end
                end
                local function legitLoop()
                    waitForGacha()
                    returnToMenu()
                    task.wait(1.5)

                    while Toggles.DayFarm.Value and isLegit() and not deathHandled do
                        if goalHit then
                            waitMenuReady(10)
                            returnToMenu()
                            Notify.say('Day goal reached, waiting in the menu')

                            while Toggles.DayFarm.Value and isLegit() and goalHit do
                                task.wait(1)
                            end

                            break
                        end
                        if not (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')) then
                            local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                            if pg and not pg:FindFirstChild('StartMenu') then
                                pg:WaitForChild('StartMenu', 30)
                            end

                            task.wait(0.5)

                            if shriekerAtGacha() then
                                task.wait(math.random(SHRIEK_MENU_MIN * 100, SHRIEK_MENU_MAX * 100) / 100)
                                fleeShriekers('seen from the menu before spawning back in')

                                break
                            end

                            pressPlay()
                        end

                        local char = waitForCharacter()

                        if not (Toggles.DayFarm.Value and isLegit()) then
                            break
                        end
                        if char and char:FindFirstChild('HumanoidRootPart') then
                            task.wait(1)

                            if not (Toggles.DayFarm.Value and isLegit()) or deathHandled then
                                break
                            end

                            task.spawn(sitDown)
                            task.spawn(function()
                                task.wait(math.random(SHRIEK_SPAWN_MIN * 100, SHRIEK_SPAWN_MAX * 100) / 100)

                                if Toggles.DayFarm.Value and isLegit() and not hopInitiated and shriekerAtGacha() then
                                    fleeShriekers('still there after settling in')
                                end
                            end)

                            local sawFF = forceFieldOf(char) ~= nil

                            if not sawFF then
                                local ffWait = 0

                                while ffWait < 5 and Toggles.DayFarm.Value and isLegit() and not deathHandled do
                                    task.wait(0.25)

                                    ffWait += 0.25

                                    if forceFieldOf(char) then
                                        sawFF = true

                                        break
                                    end
                                end
                            end
                            if not sawFF then
                                if not (Toggles.DayFarm.Value and isLegit()) or deathHandled then
                                    break
                                end

                                waitForGacha()
                                waitMenuReady(10)
                                returnToMenu()
                                task.wait(1.5)

                                continue
                            end

                            local caught = false
                            local elapsed, sinceCheck = 0, 0
                            local campedSince

                            while elapsed < LEGIT_LIFE and Toggles.DayFarm.Value and isLegit() and not deathHandled and not hopInitiated do
                                task.wait(0.25)

                                elapsed += 0.25
                                sinceCheck += 0.25

                                local ff = forceFieldOf(char)

                                if ff then
                                    sawFF = true
                                elseif sawFF then
                                    break
                                end
                                if not ff and CollectionService:HasTag(char, 'Danger') then
                                    caught = true

                                    break
                                end
                                if sinceCheck >= 1 then
                                    sinceCheck = 0

                                    if elapsed > SHRIEK_SPAWN_MAX and shriekerAtGacha() then
                                        fleeShriekers('turned up mid life')

                                        break
                                    end

                                    local campRange = Options.DayFarmCampRange.Value
                                    local camper = campRange > 0 and not noKick() and strangerWithin(campRange)

                                    if camper then
                                        campedSince = campedSince or elapsed

                                        local campFor = Options.DayFarmCampSeconds.Value

                                        if elapsed - campedSince >= campFor then
                                            waitForGacha()

                                            local who = MemStore.get('dayfarm_gacha') == 'true' and 'the gacha bot' or 'the day farm bot'

                                            dayfarmHop(string.format('**%s** stayed within %d studs of %s for %ds - serverhopping', camper.Name, campRange, who, campFor), true)

                                            break
                                        end
                                    else
                                        campedSince = nil
                                    end
                                end
                            end

                            if caught and not deathHandled and Toggles.DayFarm.Value then
                                handleDangerCaught(char)
                            end
                            if not Toggles.DayFarm.Value or deathHandled or hopInitiated then
                                break
                            end

                            waitForGacha()
                            returnToMenu()
                            task.wait(1.5)
                        else
                            task.wait(1)
                        end
                    end
                end
                local function maxLives()
                    return PD_MAX_LIVES[Remotes.getServerValue('Race')] or 3
                end
                local function autoPopPD()
                    local lives = Remotes.getServerValue('Lives')

                    if type(lives) ~= 'number' or lives >= maxLives() then
                        return false
                    end

                    local bp = LocalPlayer:FindFirstChildOfClass('Backpack')
                    local pd = bp and bp:FindFirstChild('Phoenix Down')
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                    if not pd or not hum then
                        return false
                    end

                    local oldLives = lives

                    hum:EquipTool(pd)

                    local timeout = tick() + 5

                    while pd.Parent ~= LocalPlayer.Character and tick() < timeout do
                        task.wait()
                    end

                    if pd.Parent ~= LocalPlayer.Character then
                        return false
                    end

                    pd:Activate()
                    task.wait(1)

                    local newLives = Remotes.getServerValue('Lives')

                    Webhook.text(('Auto-popped a Phoenix Down (**%s** \u{2192} **%s** lives)'):format(tostring(oldLives), tostring(newLives or '?')))

                    return true
                end
                local function xenyari()
                    local npcs = Workspace:FindFirstChild('NPCs')
                    local npc = npcs and npcs:FindFirstChild(gachaNpcName())
                    local root = npc and npc:FindFirstChild('HumanoidRootPart')
                    local detector = npc and npc:FindFirstChildWhichIsA('ClickDetector', true)

                    if not (root and detector) then
                        return nil
                    end

                    return npc, root, detector
                end
                local function gachaRange(detector)
                    return math.max(detector.MaxActivationDistance - 2, 5)
                end
                local function nearXenyari()
                    local _, root, detector = xenyari()
                    local char = LocalPlayer.Character

                    return root ~= nil and char ~= nil and char:FindFirstChild('HumanoidRootPart') ~= nil and LocalPlayer:DistanceFromCharacter(root.Position) <= gachaRange(detector)
                end
                local function gachaBot()
                    if MemStore.get('dayfarm_gacha') == 'true' then
                        return true
                    end
                    if nearXenyari() then
                        MemStore.set('dayfarm_gacha', 'true')

                        return true
                    end

                    return false
                end
                local function xenyariShield()
                    local TeleportService, GuiService = Services.TeleportService, Services.GuiService
                    local life, lastFire, misses, token = XENYARI_FF_LIFE, -math.huge, 0, 0
                    local ours = setmetatable({}, {
                        __mode = 'k',
                    })

                    local function fire()
                        if os.clock() - lastFire < XENYARI_FF_GAP then
                            return
                        end
                        if not (farming() and not isLegit() and not deathHandled and not hopInitiated and misses < XENYARI_FF_MISSES and nearXenyari()) then
                            return
                        end

                        local remote = requestRemote('JoinPublicServer')

                        if not remote then
                            return
                        end

                        lastFire = os.clock()

                        misses += 1

                        pcall(remote.FireServer, remote, HttpService:GenerateGUID(false):lower())

                        if misses >= XENYARI_FF_MISSES then
                            task.delay(XENYARI_FF_OURS, function()
                                if misses >= XENYARI_FF_MISSES and farming() then
                                    Webhook.text(string.format(
[[%s forcefield stopped: **%d** fires in a row gave no forcefield]], gachaNpcName(), misses))
                                end
                            end)
                        end
                    end
                    local function clearPrompt()
                        for _, after in {
                            0,
                            0.1,
                            0.3,
                            0.6,
                            1,
                        }do
                            task.delay(after, pcall, GuiService.ClearError, GuiService)
                        end
                    end
                    local function bind(char)
                        if not char then
                            return
                        end

                        farmMaid.xenyariFFAdded = char.ChildAdded:Connect(function(
                            child
                        )
                            if not child:IsA('ForceField') then
                                return
                            end

                            misses = 0

                            if os.clock() - lastFire >= XENYARI_FF_OURS then
                                return
                            end

                            ours[child] = os.clock()

                            token += 1

                            local mine = token

                            task.delay(math.max(0.5, life - XENYARI_FF_LEAD), function(
                            )
                                if token == mine and child.Parent == char then
                                    fire()
                                end
                            end)
                        end)
                        farmMaid.xenyariFFRemoved = char.ChildRemoved:Connect(function(
                            child
                        )
                            if not (child:IsA('ForceField') and char.Parent) then
                                return
                            end

                            local now = os.clock()

                            if ours[child] and now - lastFire > XENYARI_FF_SWAP then
                                life = math.clamp(now - ours[child], 4, 30)
                            end
                            if not char:FindFirstChildOfClass('ForceField') then
                                fire()
                            end
                        end)
                    end

                    farmMaid.xenyariFFChar = LocalPlayer.CharacterAdded:Connect(bind)

                    bind(LocalPlayer.Character)

                    farmMaid.xenyariFFFailed = TeleportService.TeleportInitFailed:Connect(function(
                    )
                        if os.clock() - lastFire <= XENYARI_FF_CLEAR and not hopInitiated then
                            clearPrompt()
                        end
                    end)
                    farmMaid.xenyariFFError = GuiService.ErrorMessageChanged:Connect(function(
                        message
                    )
                        if os.clock() - lastFire <= XENYARI_FF_CLEAR and not hopInitiated and type(message) == 'string' and message:find('requested game instance', 1, true) then
                            clearPrompt()
                        end
                    end)
                    farmMaid.xenyariFFLoop = task.spawn(function()
                        while farming() do
                            local char = LocalPlayer.Character
                            local shielded, armed = false, false

                            for _, child in (char and char:GetChildren() or {})do
                                if child:IsA('ForceField') then
                                    shielded = true
                                    armed = armed or ours[child] ~= nil
                                end
                            end

                            if char and (not shielded or (not armed and os.clock() - lastFire > life)) then
                                fire()
                            end

                            task.wait(1)
                        end
                    end)
                end
                local function pokeDetector(detector)
                    local humanoid = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                    if humanoid then
                        pcall(humanoid.UnequipTools, humanoid)
                        task.wait(0.15)
                    end
                    if replicatesignal then
                        for _, action in {1, 0, 2}do
                            pcall(replicatesignal, detector.MouseActionReplicated, LocalPlayer, action)
                        end
                    elseif fireclickdetector then
                        pcall(fireclickdetector, detector)
                    end
                end
                local function solveCaptchaGui(pg)
                    return Captcha.solveGui(pg)
                end
                local function connectGachaDialogue()
                    local requests = ReplicatedStorage:FindFirstChild('Requests')

                    if not requests then
                        return nil
                    end

                    local keyed = Remotes.getRemote('PostDialogue') or Remotes.getRemote('SendDialogue')
                    local handle = {
                        finished = false,
                        answered = 0,
                        conns = {},
                    }

                    local function respond(remote, data)
                        if handle.finished or type(data) ~= 'table' or (data.choices == nil and data.speaker == nil) then
                            return
                        end
                        if type(data.msg) == 'string' and data.msg:find('examine the scroll more thoroughly', 1, true) then
                            handle.refused = true
                        end
                        if type(data.speaker) == 'string' and data.speaker ~= '' and not data.speaker:lower():find(gachaNpcName():lower(), 1, true) then
                            return
                        end

                        local target = keyed or remote
                        local pick = type(data.choices) == 'table' and data.choices[1] or nil

                        task.defer(function()
                            task.wait(0.08)

                            if pick then
                                handle.answered += 1

                                pcall(function()
                                    target:FireServer({choice = pick})
                                end)

                                return
                            end

                            handle.finished = true

                            pcall(function()
                                target:FireServer({exit = true})
                            end)
                        end)
                    end

                    for _, remote in requests:GetChildren()do
                        if remote:IsA('RemoteEvent') then
                            table.insert(handle.conns, remote.OnClientEvent:Connect(function(
                                data
                            )
                                respond(remote, data)
                            end))
                        end
                    end

                    handle.close = function()
                        for _, c in handle.conns do
                            pcall(function()
                                c:Disconnect()
                            end)
                        end

                        Dialogue.close()
                    end

                    return handle
                end

                local dayRead = {
                    at = nil,
                    busy = false,
                    watching = false,
                }

                local function upvalueDay()
                    local event = requestRemote('DaysSurvivedChanged')

                    if not (event and getconnections and getupvalue) then
                        return nil
                    end

                    local ok, conns = pcall(getconnections, event.OnClientEvent)

                    if ok and type(conns) == 'table' then
                        for _, conn in conns do
                            local fine, value = pcall(getupvalue, conn.Function, 2)

                            if fine and type(value) == 'number' then
                                return value
                            end
                        end
                    end

                    return nil
                end
                local function readDay()
                    local days = tonumber(Remotes.getServerValue('DaysSurvived')) or upvalueDay()

                    if days then
                        dayCache, dayRead.at = days, os.clock()
                    end
                end
                local function watchDays()
                    if dayRead.watching then
                        return
                    end

                    local event = requestRemote('DaysSurvivedChanged')

                    if not event then
                        return
                    end

                    dayRead.watching = true

                    ctx.Maid:Connect(event.OnClientEvent, function(days)
                        if type(days) == 'number' then
                            dayCache, dayRead.at = days, os.clock()
                        end
                    end)
                end
                local function currentDay()
                    watchDays()

                    if dayRead.at == nil then
                        readDay()
                    elseif os.clock() - dayRead.at > DAY_FRESH and not dayRead.busy then
                        dayRead.busy = true

                        task.spawn(function()
                            pcall(readDay)

                            dayRead.busy = false
                        end)
                    end

                    return dayCache
                end

                ctx.State.currentDay = currentDay

                local function snapshotRolls()
                    local counts = {}

                    for _, container in {
                        LocalPlayer:FindFirstChildOfClass('Backpack'),
                        LocalPlayer.Character,
                    }do
                        if container then
                            for _, item in container:GetChildren()do
                                if isRoll(item.Name) then
                                    counts[item.Name] = (counts[item.Name] or 0) + 1
                                end
                            end
                        end
                    end

                    return counts
                end
                local function newRoll(before)
                    for name, count in snapshotRolls()do
                        if count > (before[name] or 0) then
                            return name
                        end
                    end

                    return nil
                end
                local function stopTargetsComplete()
                    local selected = (Options.GachaStopRolls and Options.GachaStopRolls.Value) or {}
                    local wanted = false

                    for name, enabled in pairs(selected)do
                        if enabled then
                            wanted = true

                            if not rollProgress[name] then
                                return false
                            end
                        end
                    end

                    return wanted
                end
                local function pendingTargets()
                    local selected = (Options.GachaStopRolls and Options.GachaStopRolls.Value) or {}
                    local waiting = {}

                    for name, enabled in pairs(selected)do
                        if enabled and not rollProgress[name] then
                            table.insert(waiting, name)
                        end
                    end

                    table.sort(waiting)

                    return waiting
                end
                local function useScroll(name)
                    local char = LocalPlayer.Character
                    local bp = LocalPlayer:FindFirstChildOfClass('Backpack')
                    local hum = char and char:FindFirstChildOfClass('Humanoid')
                    local scroll = (bp and bp:FindFirstChild(name)) or (char and char:FindFirstChild(name))

                    if not (hum and scroll and scroll:IsA('Tool')) then
                        return false
                    end
                    if Dialogue.inDialogue() then
                        Debug.log('dayfarm', "the roll's talk is still open, leaving it before reading " .. name)
                    end
                    if not Dialogue.close(8) then
                        return false
                    end

                    hum:EquipTool(scroll)

                    local timeout = tick() + 5

                    while scroll.Parent ~= char and tick() < timeout do
                        task.wait()
                    end

                    if scroll.Parent ~= char or not Dialogue.close(4) then
                        return false
                    end

                    task.wait(0.05)
                    scroll:Activate()

                    timeout = tick() + 3

                    while scroll.Parent == char and tick() < timeout do
                        task.wait(0.1)
                    end

                    return scroll.Parent ~= char and scroll.Parent ~= bp
                end
                local function recordRoll(name)
                    local selected = (Options.GachaStopRolls and Options.GachaStopRolls.Value) or {}
                    local used

                    if selected[name] or selected[ANY_SCROLL] then
                        used = useScroll(name)
                    end
                    if selected[name] then
                        rollProgress[name] = true
                    end
                    if selected[ANY_SCROLL] then
                        rollProgress[ANY_SCROLL] = true
                    end

                    local usedText = used == true and ', used it' or used == false and ', **could not use it**' or ''
                    local day = currentDay()

                    if stopTargetsComplete() then
                        Webhook.text(string.format(
[[@everyone rolled **%s** on day **%d**%s, every target scroll obtained - menuing out]], name, day, usedText))

                        return true
                    end

                    local silver = tonumber(Remotes.getServerValue('Silver'))

                    Webhook.text(string.format('%srolled **%s** on day **%d**%s%s', RARE_ROLLS[name] and '@everyone ' or '', name, day, usedText, silver and string.format(', **%d** silver left', silver) or ''))

                    return false
                end

                local gachaWait = {
                    day = nil,
                    since = 0,
                    held = {},
                    closest = nil,
                    walks = 0,
                }

                local function refuseGacha(day, why, distance)
                    gachaWait.held[why] = (gachaWait.held[why] or 0) + 1

                    if distance then
                        gachaWait.closest = math.min(gachaWait.closest or math.huge, distance)
                    end
                    if gachaWait.held[why] == 1 then
                        warn(string.format('[sentinel] day farm: day %s roll waiting, %s', tostring(day), why))
                    end

                    return false
                end
                local function reportGachaWait(day)
                    if gachaWait.day ~= day then
                        return
                    end

                    local waited = os.clock() - gachaWait.since

                    if waited < GACHA_LATE or next(gachaWait.held) == nil then
                        return
                    end

                    local parts = {}

                    for why, count in gachaWait.held do
                        local label = why == 'out of range' and gachaWait.closest and string.format('out of range (closest %.0f studs)', gachaWait.closest) or why

                        table.insert(parts, string.format('%s x%d', label, count))
                    end

                    table.sort(parts)
                    Webhook.text(string.format('Day **%d** rolled **%ds** after it came due, held by %s', day, math.floor(waited), table.concat(parts, ', ')))
                end
                local function gachaDue()
                    if not Toggles.DayFarm.Value or goalHit then
                        return false
                    end

                    local day = currentDay()

                    return not (goalDay and day > goalDay) and tonumber(MemStore.get('dayfarm_gacha_day')) ~= day
                end
                local function spawnAgain()
                    menuOut()

                    local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                    if not (pg and pg:WaitForChild('StartMenu', 30)) or not Toggles.DayFarm.Value or deathHandled or hopInitiated then
                        return
                    end

                    task.wait(math.random(150, 300) / 100)
                    pressPlay()
                    waitForCharacter()
                end
                local function tryGacha(known)
                    if gachaRunning then
                        return false
                    end

                    local today = tonumber(known) or currentDay()

                    if tonumber(MemStore.get('dayfarm_gacha_day')) == today or not gachaBot() then
                        return false
                    end
                    if gachaWait.day ~= today then
                        gachaWait.day, gachaWait.since, gachaWait.closest, gachaWait.walks = today, os.clock(), nil, 0

                        table.clear(gachaWait.held)
                    end

                    local npc, root, detector = xenyari()

                    if not npc then
                        return refuseGacha(today, gachaNpcName() .. ' not loaded')
                    end

                    local char = LocalPlayer.Character

                    if not (char and char:FindFirstChild('HumanoidRootPart')) then
                        return refuseGacha(today, 'no character (menu or loading)')
                    end

                    local range = gachaRange(detector)
                    local distance = LocalPlayer:DistanceFromCharacter(root.Position)

                    if distance > range then
                        if distance > 250 or gachaWait.walks >= 3 then
                            return refuseGacha(today, 'out of range', distance)
                        end

                        local watcher, watcherAt = strangerWithin(200)

                        if watcher then
                            if noKick() then
                                return refuseGacha(today, 'someone too close to walk back')
                            end

                            dayfarmHop(string.format(
[[Pushed **%.0f** studs off %s with **%s** (**%d**) **%.0f** studs away - serverhopping to walk back in another server]], distance, gachaNpcName(), watcher.Name, watcher.UserId, watcherAt), isLegit())

                            return false
                        end

                        gachaWait.walks += 1

                        Debug.log('dayfarm', string.format('%.0f studs off Xenyari (reach %.0f), walking back', distance, range))

                        local humanoid = Character.humanoid()

                        if humanoid then
                            pcall(humanoid.UnequipTools, humanoid)

                            if humanoid.Sit then
                                humanoid.Jump = true
                            end
                        end

                        Character.walkTo(root.Position, math.max(range - 2, 3), function(
                        )
                            return Toggles.DayFarm.Value and not Menu.startMenu()
                        end, 20)

                        local hrp = Character.root()

                        if humanoid and hrp then
                            humanoid:MoveTo(hrp.Position)
                        end

                        distance = LocalPlayer:DistanceFromCharacter(root.Position)

                        if not (hrp and distance <= range) then
                            task.spawn(sitDown)

                            return refuseGacha(today, 'out of range', distance)
                        end
                        if not forceFieldOf(LocalPlayer.Character) then
                            Debug.log('dayfarm',
[[walked back without a forcefield, menuing and spawning again]])

                            if not isLegit() then
                                spawnAgain()
                            end
                            if isLegit() or not nearXenyari() then
                                return refuseGacha(today, 'respawning after walking back')
                            end
                        end
                    end
                    if not Captcha.available() then
                        postGachaSkip(today, 'captcha', gachaNpcName() .. ' gacha skipped: the captcha solver could not be loaded')

                        return refuseGacha(today, 'captcha solver missing')
                    end

                    local silver = Remotes.getServerValue('Silver')

                    if silverArmed and type(silver) == 'number' and silver <= 0 then
                        local players = #Players:GetPlayers()
                        local staying = noKick() or players > FULL_SERVER
                        local waiting = pendingTargets()

                        gachaRunning = true

                        Webhook.text(string.format(
[[@everyone needs silver: **%d** left of the **%d** it started with, still hoping for **%s**%s]], silver, startingSilver, #waiting > 0 and table.concat(waiting, ', ') or 'no scroll in particular', staying and string.format(' - menuing and holding this **%d** player server', players) or ' - menuing and kicking'))
                        Danger.waitClear()
                        menuOut()

                        gachaRunning = false

                        if not staying then
                            Danger.kick('sentinel: gacha bot out of silver')
                            Library:Unload()
                        end

                        return false
                    end
                    if type(silver) == 'number' and silver < GACHA_SILVER then
                        postGachaSkip(today, 'silver', string.format('%s gacha skipped: **%d** silver, **%d** needed', gachaNpcName(), silver, GACHA_SILVER))

                        return refuseGacha(today, 'short on silver')
                    end

                    gachaRunning = true

                    local rolled, solvedAs = false, nil
                    local before = snapshotRolls()
                    local observed
                    local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
                    local watch = backpack and backpack.ChildAdded:Connect(function(
                        item
                    )
                        if isRoll(item.Name) then
                            observed = item.Name
                        end
                    end)
                    local dialogue = connectGachaDialogue()
                    local finished, err = pcall(function()
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                        if not pg then
                            return
                        end

                        local function captchaUp()
                            return pg:FindFirstChild('CaptchaLoad') or pg:FindFirstChild('Captcha')
                        end

                        local deadline = tick() + 15

                        while tick() < deadline and not captchaUp() do
                            pokeDetector(detector)
                            task.wait(0.5)
                        end

                        if not captchaUp() then
                            Webhook.text(gachaNpcName() .. ' gacha: the captcha never opened')

                            return
                        end

                        local solved, detail = solveCaptchaGui(pg)

                        if not solved then
                            Webhook.text(gachaNpcName() .. ' gacha failed: **' .. tostring(detail) .. '**')

                            return
                        end

                        solvedAs = detail

                        local talkUntil = tick() + 20

                        while dialogue and not dialogue.finished and tick() < talkUntil do
                            task.wait(0.1)
                        end

                        if dialogue and dialogue.refused then
                            Debug.log('dayfarm',
[[Xenyari turned the roll away, the scroll needs examining first]])

                            return
                        end

                        rolled = true
                    end)

                    if dialogue then
                        pcall(dialogue.close)
                    end
                    if not finished then
                        Webhook.text(gachaNpcName() .. ' gacha errored: **' .. tostring(err) .. '**')
                    end

                    local got

                    if rolled then
                        local settle = tick() + 3

                        repeat
                            got = observed or newRoll(before)

                            if got then
                                break
                            end

                            task.wait(0.1)
                        until tick() > settle
                    end
                    if watch then
                        pcall(function()
                            watch:Disconnect()
                        end)
                    end
                    if rolled or (dialogue and dialogue.refused) then
                        MemStore.set('dayfarm_gacha_day', today)
                    end
                    if rolled then
                        reportGachaWait(today)
                    end
                    if rolled then
                        if got and recordRoll(got) then
                            menuOut()

                            if Toggles.DayFarm.Value then
                                Toggles.DayFarm:SetValue(false)
                            end
                        elseif not got then
                            warn(string.format(
[[[sentinel] day farm: rolled on day %d (captcha %s) and could not read what it gave]], currentDay(), tostring(solvedAs)))
                        end
                    end

                    gachaRunning = false

                    if not Menu.startMenu() then
                        task.spawn(sitDown)
                    end

                    return rolled
                end
                local function runGacha(known)
                    if gachaPending or gachaRunning then
                        return
                    end

                    gachaPending = true

                    task.spawn(function()
                        local ok, err = pcall(tryGacha, known)

                        gachaRunning = false
                        gachaPending = false

                        if not ok then
                            warn('[sentinel] day farm: gacha errored: ' .. tostring(err))
                            Debug.log('dayfarm', 'gacha errored: ' .. tostring(err))
                        end
                    end)
                end
                local function bindDayGoal()
                    local daysEvent = requestRemote('DaysSurvivedChanged')

                    if not daysEvent then
                        warn(
[[[sentinel] day farm: DaysSurvivedChanged remote missing, the target day will never fire]])

                        return
                    end

                    local announced = tonumber(Remotes.getServerValue('DaysSurvived')) or
-1

                    local function onDay(days)
                        if not Toggles.DayFarm.Value or goalHit then
                            return
                        end
                        if type(days) == 'number' then
                            dayCache = days
                        end
                        if Toggles.DayFarmAutoPopPD.Value then
                            task.spawn(autoPopPD)
                        end

                        local goal = tonumber(Options.DayGoal.Value) or 0
                        local reached = goal > 0 and dayCache >= goal

                        if dayCache > announced then
                            announced = dayCache

                            if not reached and not gachaBot() then
                                Webhook.text(string.format('Day **%d**%s', dayCache, goal > 0 and string.format(' of **%d**', goal) or ''))
                            end
                        end
                        if reached and goalDay then
                            return
                        end

                        runGacha(dayCache)

                        if not reached then
                            return
                        end

                        local target = dayCache

                        goalDay = target

                        if gachaBot() then
                            Webhook.text(string.format(
[[Day **%d** reached the goal, %s once today's roll is in (5 min at most)]], target, Toggles.DayGoalKick.Value and not noKick() and 'kicking' or 'stopping'))
                        end

                        Debug.log('dayfarm', string.format('day %d reached goal %d (gacha bot %s)', target, goal, tostring(gachaBot())))
                        task.spawn(function()
                            local waited = 0

                            while Toggles.DayFarm.Value and goalDay == target and waited < GOAL_ROLL_WAIT and dayCache <= target and tonumber(MemStore.get('dayfarm_gacha_day')) ~= target and gachaBot() do
                                task.wait(1)

                                waited += 1
                            end

                            Debug.log('dayfarm', string.format(
[[goal wait over after %ds (rolled %s), letting any roll in progress finish]], waited, tostring(tonumber(MemStore.get('dayfarm_gacha_day')) == target)))

                            local rollBy = tick() + 60

                            while(gachaPending or gachaRunning) and tick() < rollBy do
                                task.wait(0.25)
                            end

                            if not Toggles.DayFarm.Value or goalDay ~= target or goalHit then
                                Debug.log('dayfarm',
[[goal dropped: farm off, a newer goal day, or already handled]])

                                return
                            end

                            goalHit = true

                            local leaving = Toggles.DayGoalKick.Value and not noKick()

                            Webhook.text(string.format('%sreached day goal **%d**%s', leaving and '@everyone ' or '', goal, leaving and ', kicking' or ', staying in the server'))
                            Notify.say(string.format('Reached day goal %d', goal))

                            if leaving then
                                Danger.waitClear()
                                menuOut()
                                Danger.kick('Reached day goal ' .. goal)
                                Library:Unload()
                            end
                        end)
                    end

                    farmMaid.dayGoal = daysEvent.OnClientEvent:Connect(onDay)

                    local goal = tonumber(Options.DayGoal.Value) or 0

                    if goal > 0 and announced >= goal then
                        task.spawn(onDay, announced)
                    end
                end
                local function startFarm()
                    if getconnections then
                        pcall(function()
                            for _, conn in getconnections(LocalPlayer.Idled)do
                                conn:Disable()
                            end
                        end)
                    end

                    deathHandled = false
                    hopInitiated = false
                    goalHit = false
                    goalDay = nil
                    farmMaid.respawn = LocalPlayer.CharacterAdded:Connect(watchDeath)

                    task.spawn(watchDeath, LocalPlayer.Character)

                    if Toggles.ProximityNotifier then
                        Toggles.ProximityNotifier:SetValue(true)
                    end
                    if Toggles.ProximityIgnoreAllies then
                        Toggles.ProximityIgnoreAllies:SetValue(true)
                    end
                    if MemStore.get('dayfarming') ~= 'true' then
                        MemStore.remove('dayfarm_gacha')
                    end

                    MemStore.set('dayfarming', 'true')
                    MemStore.set('dayfarming_range', tostring(Options.DayFarmRange.Value))
                    MemStore.set('dayfarm_camp', string.format('%d,%d', Options.DayFarmCampRange.Value, Options.DayFarmCampSeconds.Value))
                    MemStore.set('day_goal_kick', tostring(Toggles.DayGoalKick.Value))
                    MemStore.set('no_kick', tostring(Toggles.NoKick.Value))
                    MemStore.set('daygoal', Options.DayGoal.Value ~= '' and Options.DayGoal.Value or '999')
                    MemStore.set('dayfarm_mode', Options.DayFarmMode.Value)
                    MemStore.set('dayfarm_autopoppd', tostring(Toggles.DayFarmAutoPopPD.Value))
                    MemStore.set('dayfarm_friends', tostring(Toggles.DayFarmIgnoreFriends.Value))
                    MemStore.set('dayfarm_chair', tostring(Toggles.DayFarmUseChair.Value))
                    MemStore.set('dayfarm_stoprolls', HttpService:JSONEncode((Options.GachaStopRolls and Options.GachaStopRolls.Value) or {}))

                    startingSilver = Remotes.getServerValue('Silver')
                    silverArmed = type(startingSilver) == 'number' and startingSilver > GACHA_SILVER

                    MemStore.set('dayfarm_start_silver', tostring(startingSilver or ''))

                    if Toggles.DayFarmGpu and Toggles.DayFarmGpu.Value then
                        CpuThrottle.start()
                    end

                    local name, region = serverInfo()

                    Webhook.text(string.format(
[[Started farming days [**%s**] in `%s (%s)` with **%d** players]], Options.DayFarmMode.Value, name, region, #Players:GetPlayers()))
                    bindDayGoal()
                    runGacha()

                    local witnessAccum, gachaRetryAccum, wasNear = 0, 0, false

                    farmMaid.witness = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                        dt
                    )
                        witnessAccum += dt
                        gachaRetryAccum += dt

                        if gachaRetryAccum >= GACHA_RETRY then
                            gachaRetryAccum = 0

                            if gachaDue() then
                                runGacha()
                            end
                        end
                        if witnessAccum < 1 then
                            return
                        end

                        witnessAccum = 0

                        local near = nearXenyari()

                        if near and not wasNear then
                            MemStore.set('dayfarm_gacha', 'true')

                            if gachaDue() then
                                runGacha()
                            end
                        end

                        wasNear = near

                        recordWitnesses()
                    end))

                    if isLegit() then
                        local thrown = Workspace:FindFirstChild('Thrown')

                        if thrown then
                            farmMaid.viribus = thrown.ChildAdded:Connect(function(
                                pillar
                            )
                                if pillar.Name ~= 'EarthPillar' then
                                    return
                                end

                                local crater = pillar:WaitForChild('Crater', 2)
                                local char = LocalPlayer.Character
                                local hrp = char and char:FindFirstChild('HumanoidRootPart')

                                if not (crater and hrp) or char:FindFirstChild('FlightOk') or hopInitiated or deathHandled or noKick() or not (Toggles.DayFarm.Value and isLegit()) then
                                    return
                                end

                                local at = (crater:IsA('BasePart') and crater.Position) or (crater:IsA('Model') and crater:GetPivot().Position)
                                local d = at and (at - hrp.Position).Magnitude

                                if not d or d > 40 then
                                    return
                                end

                                local caster = 'someone'

                                for _, part in pillar:GetChildren()do
                                    if part.Name:sub(1, 10) == 'EarthSpear' then
                                        caster = part.Name:sub(11)
                                    end
                                end

                                if caster == LocalPlayer.Name then
                                    return
                                end

                                local pos = hrp.Position

                                MemStore.set('dayfarm_viribus_pos', string.format('%f,%f,%f', pos.X, pos.Y, pos.Z))
                                dayfarmHop(string.format('Viribus backfire by **%s** %.0f studs away - serverhopping', caster, d), true)
                            end)
                        end

                        farmMaid.legit = task.spawn(legitLoop)

                        return
                    end

                    xenyariShield()

                    local accum = 0

                    farmMaid.heartbeat = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                        dt
                    )
                        accum += dt

                        if accum < 1 then
                            return
                        end

                        accum = 0

                        if noKick() or not Toggles.DayFarm.Value or deathHandled then
                            return
                        end
                        if shriekerAtGacha() then
                            fleeShriekers('blatant mode, leaving on sight')

                            return
                        end

                        local p = closePlayer()

                        if p then
                            dayfarmHop(string.format('**%s** (**%d**) came too close', p.Name, p.UserId))
                        end
                    end))

                    for _, p in Players:GetPlayers()do
                        if p ~= LocalPlayer and not noKick() and not isCarriedByMe(p) then
                            if strangerModerator(p) then
                                handleModerator(p)

                                break
                            end
                            if p.Character then
                                for _, item in p.Character:GetChildren()do
                                    if item:IsA('Tool') and DANGER_ITEMS[item.Name] then
                                        dayfarmHop(string.format('**%s** (**%d**) already has dangerous item: **%s**', p.Name, p.UserId, item.Name))

                                        break
                                    end
                                end
                            end
                        end
                    end

                    farmMaid.playerAdded = Players.PlayerAdded:Connect(function(
                        p
                    )
                        if isModerator(p) and not noKick() then
                            handleModerator(p)
                        end
                    end)
                    farmMaid.flagged = ctx.State.onModeratorFlagged(function(p)
                        if Toggles.DayFarm.Value and not noKick() then
                            handleModerator(p)
                        end
                    end)

                    local detach, snapArmed = Threats.watch({
                        active = function()
                            return Toggles.DayFarm.Value and not isLegit() and not noKick() and not hopInitiated
                        end,
                        isFriend = function(p)
                            return (ctx.State.isFriend and ctx.State.isFriend(p)) or isCarriedByMe(p)
                        end,
                        allow = function(kind)
                            return Threats.allowed(Options, kind)
                        end,
                        report = function(threat)
                            local escape = threat.dodge or Threats.sidestep(threat.position)

                            if escape and ctx.State.smoothTeleport then
                                ctx.State.smoothTeleport(escape)
                            end

                            dayfarmHop(threat.label)
                        end,
                    })

                    farmMaid.threats = detach

                    if not snapArmed then
                        warn(
[[[sentinel] day farm: ClientVFX missing, snap Celeritas detection is off]])
                    end

                    local live = Workspace:FindFirstChild('Live')

                    if live then
                        farmMaid.dangerWatch = live.DescendantAdded:Connect(function(
                            desc
                        )
                            if not Toggles.DayFarm.Value or noKick() then
                                return
                            end
                            if desc:IsA('Tool') and DANGER_ITEMS[desc.Name] then
                                local owner = desc.Parent and Players:GetPlayerFromCharacter(desc.Parent)

                                if owner and owner ~= LocalPlayer then
                                    dayfarmHop(string.format('**%s** (**%d**) has dangerous item: **%s**', owner.Name, owner.UserId, desc.Name))
                                end
                            end
                        end)
                    end
                end
                local function stopFarm()
                    farmMaid:DoCleaning()

                    hopInitiated = false

                    if getconnections then
                        pcall(function()
                            for _, conn in getconnections(LocalPlayer.Idled)do
                                conn:Enable()
                            end
                        end)
                    end

                    CpuThrottle.stop()

                    for _, key in {
                        'dayfarming',
                        'dayfarming_range',
                        'day_goal_kick',
                        'no_kick',
                        'daygoal',
                        'dayfarm_mode',
                        'dayfarm_autopoppd',
                        'dayfarm_stoprolls',
                        'dayfarm_friends',
                        'dayfarm_chair',
                        'dayfarm_viribus_pos',
                        'dayfarm_gacha',
                        'dayfarm_left_server',
                    }do
                        MemStore.remove(key)
                    end
                end

                ctx.Maid:Give(function()
                    if MemStore.get('dayfarming') == 'true' then
                        if getconnections then
                            pcall(function()
                                for _, conn in getconnections(LocalPlayer.Idled)do
                                    conn:Enable()
                                end
                            end)
                        end

                        for _, key in {
                            'dayfarming',
                            'dayfarming_range',
                            'day_goal_kick',
                            'no_kick',
                            'daygoal',
                            'dayfarm_mode',
                            'dayfarm_autopoppd',
                            'dayfarm_stoprolls',
                            'dayfarm_friends',
                            'dayfarm_chair',
                            'dayfarm_viribus_pos',
                            'dayfarm_gacha',
                            'dayfarm_left_server',
                        }do
                            MemStore.remove(key)
                        end
                    end
                end)

                local modePicked, syncingMode = false, false

                FarmBox:AddDropdown('DayFarmMode', {
                    Text = 'Mode',
                    Tooltip =
[[Blatant hops away from people. Legit spawns and menus every 90s]],
                    Values = {
                        'Blatant',
                        'Legit',
                    },
                    Default = 'Legit',
                    Callback = function()
                        if not syncingMode then
                            modePicked = true
                        end
                    end,
                })
                task.defer(function()
                    local blatant = Toggles.BlatantMode

                    if not blatant then
                        return
                    end

                    blatant:OnChanged(function(on)
                        if modePicked then
                            return
                        end

                        syncingMode = true

                        Options.DayFarmMode:SetValue(on and 'Blatant' or 'Legit')

                        syncingMode = false
                    end)
                end)
                FarmBox:AddToggle('DayFarm', {
                    Text = 'Day Farm',
                    Tooltip = 'Farms days afk',
                    Default = false,
                    Callback = function(on)
                        if on then
                            startFarm()
                        else
                            stopFarm()
                        end
                    end,
                })
                ctx.State.registerBot({
                    name = 'Day Farm',
                    running = function()
                        return Toggles.DayFarm ~= nil and Toggles.DayFarm.Value == true
                    end,
                    stop = function()
                        if Toggles.DayFarm then
                            Toggles.DayFarm:SetValue(false)
                        end
                    end,
                })
                FarmBox:AddToggle('DayFarmGpu', {
                    Text = 'Disable GPU Rendering',
                    Tooltip = 'Stops rendering while tabbed out',
                    Default = true,
                    Callback = function(on)
                        if ctx.State.loadingConfig then
                            return
                        end
                        if on and Toggles.DayFarm and Toggles.DayFarm.Value then
                            CpuThrottle.start()
                        elseif not on then
                            CpuThrottle.stop()
                        end
                    end,
                })
                FarmBox:AddSlider('DayFarmRange', {
                    Text = 'Hop Range',
                    Default = 500,
                    Min = 100,
                    Max = 2500,
                    Rounding = 0,
                })
                FarmBox:AddSlider('DayFarmCampRange', {
                    Text = 'Legit Hop Range',
                    Tooltip = '0 = off',
                    Default = 100,
                    Min = 0,
                    Max = 500,
                    Rounding = 0,
                })
                FarmBox:AddSlider('DayFarmCampSeconds', {
                    Text = 'Legit Hop After (s)',
                    Default = 5,
                    Min = 1,
                    Max = 60,
                    Rounding = 0,
                })
                FarmBox:AddToggle('DayFarmIgnoreFriends', {
                    Text = 'Ignore Friends Proximity',
                    Tooltip = "Friends don't make it hop (Blatant only)",
                    Default = false,
                })
                FarmBox:AddToggle('DayGoalKick', {
                    Text = 'Kick on Day Goal',
                    Default = false,
                })
                FarmBox:AddToggle('NoKick', {
                    Text = 'Stay In Server',
                    Tooltip = 'Never kicks or hops',
                    Default = false,
                })
                FarmBox:AddToggle('DayFarmAutoPopPD', {
                    Text = 'Auto Pop PD',
                    Tooltip = "Pops a Phoenix Down each day unless you're at max lives",
                    Default = false,
                })
                FarmBox:AddInput('DayGoal', {
                    Text = 'Target Day',
                    Numeric = true,
                    Finished = true,
                    Placeholder = '999',
                })
                FarmBox:AddDivider()
                FarmBox:AddLabel('Gacha Settings')

                local stopRollValues = table.clone(GACHA_STOP_ROLLS)

                if Debug.enabled() then
                    table.insert(stopRollValues, ANY_SCROLL)
                end

                FarmBox:AddToggle('DayFarmUseChair', {
                    Text = 'Use Chair',
                    Tooltip = 'Sits on a chair from your bag before rolling',
                    Default = false,
                })
                FarmBox:AddDropdown('GachaStopRolls', {
                    Text = 'Stop on Scroll',
                    Values = stopRollValues,
                    Default = {},
                    Multi = true,
                    AllowNull = true,
                    Tooltip = "Stops once you've rolled all of them",
                })
                task.spawn(function()
                    if MemStore.get('dayfarming') ~= 'true' then
                        return
                    end
                    if not Serverhop.claimResume({
                        'dayfarming',
                        'dayfarm_viribus_pos',
                        'dayfarm_left_server',
                    }) then
                        return
                    end

                    watchFollowers()

                    local resumeMode = MemStore.get('dayfarm_mode') or 'Blatant'

                    resumingLegit = resumeMode == 'Legit'

                    task.wait(2)

                    if resumeMode ~= 'Legit' then
                        for _, player in Players:GetPlayers()do
                            if player ~= LocalPlayer and strangerModerator(player) then
                                local key = 'dayfarm_mod_encounter_' .. player.Name
                                local count = (tonumber(MemStore.get(key)) or 0) + 1

                                MemStore.set(key, count)

                                local who = AvoidList.label(player)
                                local limit = AvoidList.encounterLimit(player, 2)

                                if count >= limit then
                                    Webhook.textBounded(string.format('@everyone Encountered %s **%s** after hop, kicking', who:lower(), player.Name))
                                    task.wait(0.5)
                                    Kick.now(who .. ' encountered during day farm auto-restart')
                                else
                                    Webhook.text(string.format(
[[%s **%s** detected on auto-restart (**%d**/%d), serverhopping]], who, player.Name, count, limit))
                                    rememberServer()
                                    Serverhop.hop({
                                        strategy = 'smallest',
                                    })
                                end

                                return
                            end
                        end
                    end

                    local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                    if not (pg and pg:WaitForChild('StartMenu', 45)) then
                        Webhook.textBounded(
[[@everyone Day farm resume failed (no StartMenu after 45s) - kicking bot]])
                        Kick.now('sentinel: day farm resume - StartMenu never loaded')

                        return
                    end

                    task.wait(MENU_SETTLE)

                    local savedAt = resumeMode == 'Legit' and MemStore.get('dayfarm_viribus_pos')
                    local x, y, z = (savedAt or ''):match('([^,]+),([^,]+),([^,]+)')
                    local spot = x and Vector3.new(tonumber(x), tonumber(y), tonumber(z))

                    if spot then
                        local sparing = MemStore.get('dayfarm_friends') == 'true'

                        for _, p in Players:GetPlayers()do
                            local root = p ~= LocalPlayer and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                            if root and (root.Position - spot).Magnitude <= 500 and not (sparing and ctx.State.isFriend and ctx.State.isFriend(p)) then
                                Webhook.text(string.format(
[[**%s** is within 500 studs of where the Viribus hop left off - serverhopping again]], p.Name))
                                rememberServer()

                                if Serverhop.hop({
                                    strategy = 'smallest',
                                }) then
                                    return
                                end

                                break
                            end
                        end
                    end

                    pressPlay()

                    local waited = 0

                    while not LocalPlayer.Character and waited < 30 do
                        task.wait(0.25)

                        waited += 0.25
                    end

                    if not LocalPlayer.Character then
                        Webhook.textBounded(
[[@everyone Day farm resume failed (no character after Play) - kicking bot]])
                        Kick.now('sentinel: day farm resume - character never spawned')

                        return
                    end

                    waited = 0

                    while LocalPlayer.Character and not LocalPlayer.Character:FindFirstChild('HumanoidRootPart') and waited < 15 do
                        task.wait(0.25)

                        waited += 0.25
                    end

                    if spot then
                        local char, sawFF = LocalPlayer.Character, false

                        for _ = 1, 20 do
                            if char:FindFirstChildOfClass('ForceField') then
                                sawFF = true
                            elseif sawFF then
                                Webhook.text(
[[Day farm: lost the forcefield right after spawning - menuing and spawning again]])
                                waitMenuReady(10)
                                returnToMenu()
                                pg:WaitForChild('StartMenu', 30)
                                task.wait(1.5)
                                pressPlay()

                                waited = 0

                                while not (LocalPlayer.Character ~= char and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')) and waited < 30 do
                                    task.wait(0.25)

                                    waited += 0.25
                                end

                                break
                            end

                            task.wait(0.25)
                        end

                        MemStore.remove('dayfarm_viribus_pos')
                    end

                    task.wait(1)
                    Options.DayFarmMode:SetValue(resumeMode)

                    local range = tonumber(MemStore.get('dayfarming_range'))

                    if range then
                        Options.DayFarmRange:SetValue(range)
                    end

                    local campRange, campFor = tostring(MemStore.get('dayfarm_camp') or ''):match('^(%d+),(%d+)$')

                    if campRange then
                        Options.DayFarmCampRange:SetValue(tonumber(campRange))
                        Options.DayFarmCampSeconds:SetValue(tonumber(campFor))
                    end

                    Toggles.DayGoalKick:SetValue(MemStore.get('day_goal_kick') == 'true')
                    Toggles.NoKick:SetValue(MemStore.get('no_kick') == 'true')
                    Toggles.DayFarmAutoPopPD:SetValue(MemStore.get('dayfarm_autopoppd') == 'true')
