            local function coordsFrom(text)
                local body = text:match('^[%a%d_%.]*%s*%((.*)%)%s*$') or text

                if not body:match('^[%s%d%.%-,]+$') then
                    return nil
                end

                local nums = {}

                for n in body:gmatch('-?%d+%.?%d*')do
                    nums[#nums + 1] = tonumber(n)
