                'TimeBetweenLooting',
                'TrinketBotPing',
                'BotFPS',
                'BotBagRange',
                'BotHoldItem',
            }
            local SETTING_MULTI = {
                'PickupMythicsArtifacts',
                'PickupTrinketTypes',
                'KickTrinketList',
                'AutoDropItems',
                'BotDetections',
                'NodeOres',
            }
            local NODE_REACH = 8
            local LIVES_TABLE = {
                Azael = 2,
                Kasparan = 4,
                Cameo = 9,
            }
            local ACTION_KINDS = {
                unequip = true,
                equip = true,
                leftclick = true,
                rightclick = true,
                use = true,
                sleep = true,
                charge = true,
                runlua = true,
                webhook = true,
                subpath = true,
                waitday = true,
                brew = true,
                smith = true,
                setinn = true,
                talkto = true,
                click = true,
                drop = true,
                wipe = true,
                walkto = true,
                reset = true,
                captcha = true,
                menutele = true,
                ['if'] = true,
                ['else'] = true,
                ['endif'] = true,
                loop = true,
                endloop = true,
            }

            local function pathStationary(points)
                local still = {
                    equip = true,
                    unequip = true,
                    leftclick = true,
                    rightclick = true,
                    use = true,
                    sleep = true,
                    charge = true,
                    runlua = true,
                    waitday = true,
                    webhook = true,
                    drop = true,
                    captcha = true,
                    ['if'] = true,
                    ['else'] = true,
                    ['endif'] = true,
                    loop = true,
                    endloop = true,
                }

                for _, p in points do
                    if not (p.action and still[p.action]) then
                        return false
                    end
                end

                return #points > 0
            end
            local function standingAllowed(point)
                if point == nil or point.action or point.is_gate_point or point.condition or point.wait_for_trinket or point.wait_for_node then
                    return true
                end

                return (tonumber(point.wait_time) or 0) > 0
            end

            local waitAtPoint = BASIL_NO_VIRTUALIZE(function(point, bot)
                local target = tonumber(point.wait_time) or 0

                if target <= 0 then
                    return
                end

                local waited = 0

                while waited < target and bot.path_running and not bot.moderator_detected do
                    task.wait(0.5)

                    waited += 0.5
                end
            end)
            local emergencyGateClear = BASIL_NO_VIRTUALIZE(function(
                points,
                j,
                nearFn
            )
                local limit = GATE_DEST_LOOKAHEAD

                for k = j + 1, #points do
                    if points[k].is_gate_point then
                        limit = math.min(k - j, GATE_DEST_LOOKAHEAD)

                        break
                    end
                end
                for k = 1, limit do
                    local dest = points[j + k]

                    if dest then
                        local near, who = nearFn(dest.position, GATE_DEST_RADIUS)

                        if near then
                            return false, who
                        end
                    end
                end

                return true
            end)
            local traversalGateClear = BASIL_NO_VIRTUALIZE(function(
                points,
                j,
                nearFn
            )
                local landing = points[j + 1]

                if landing then
                    local near, who = nearFn(landing.position, GATE_DEST_RADIUS)

                    if near then
                        return false, who
                    end
                end

                for k = j + 1, #points do
                    local pt = points[k]

                    if pt.is_gate_point then
                        break
                    end
                    if pt.wait_for_trinket then
                        local near, who = nearFn(pt.position, GATE_DEST_RADIUS)

                        if near then
                            return false, who
                        end
                    end
                end

                return true
            end)
            local nextClearGate = BASIL_NO_VIRTUALIZE(function(
                points,
                fromIndex,
                nearFn,
                clearFn,
                onBlocked
            )
                for j = fromIndex, #points do
                    if points[j].is_gate_point then
                        if j == #points then
                            if onBlocked then
                                onBlocked(j, nil, true)
                            end
                        else
                            local clear, who = clearFn(points, j, nearFn)

                            if clear then
                                return j
                            end
                            if onBlocked then
                                onBlocked(j, who, false)
                            end
                        end
                    end
                end

                return nil
            end)
            local resolveBranches = BASIL_NO_VIRTUALIZE(function(points)
                local map, stack, loops = {}, {}, {}

                for i, p in points do
                    local action = p.action

                    if action == 'if' then
                        table.insert(stack, i)

                        map[i] = {
                            endAt = #points + 1,
                        }
                    elseif action == 'else' then
                        local openAt = stack[#stack]

                        if openAt then
                            map[openAt].elseAt = i
                            map[i] = {
                                endAt = #points + 1,
                            }
                        end
                    elseif action == 'endif' then
                        local openAt = table.remove(stack)

                        if openAt then
                            map[openAt].endAt = i

                            if map[openAt].elseAt then
                                map[map[openAt].elseAt].endAt = i
                            end
                        end
                    elseif action == 'loop' then
                        table.insert(loops, i)
                    elseif action == 'endloop' then
                        local openAt = table.remove(loops)

                        if openAt then
                            map[i] = {loopAt = openAt}
                        end
                    end
                end

                return map
            end)

            local function branchDepths(points)
                local depths, level = {}, 0

                for i, p in points do
                    if p.action == 'endif' or p.action == 'endloop' then
                        level = math.max(0, level - 1)
                    end

                    depths[i] = p.action == 'else' and math.max(0, level - 1) or level

                    if p.action == 'if' or p.action == 'loop' then
                        level += 1
                    end
                end

                return depths
            end
            local function threatPosition(name)
                local p = type(name) == 'string' and Players:FindFirstChild(name) or nil
                local hrp = p and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                return hrp and hrp.Position or nil
            end

            local elevationParams = RaycastParams.new()

            elevationParams.FilterType = Enum.RaycastFilterType.Exclude

            local function dragonBlocks(pos)
                if pos.Y < 689 or pos.Y > 730 then
                    return false
                end

                local dragon = Workspace:FindFirstChild('Ice Dragon')
                local dr = dragon and dragon:FindFirstChild('HumanoidRootPart')

                return dr ~= nil and (dr.Position - pos).Magnitude <= 500
            end
            local function underside(hit)
                local inst = hit.Instance

                if not inst then
                    return hit.Position.Y - VOID_CLEAR
                end

                local cf, size = inst.CFrame, inst.Size
                local half = 0.5 * (math.abs(cf.RightVector.Y) * size.X + math.abs(cf.UpVector.Y) * size.Y + math.abs(cf.LookVector.Y) * size.Z)

                return math.min(hit.Position.Y, inst.Position.Y - half) - VOID_CLEAR
            end
            local function voidBelow(start)
                local pos = start

                for _ = 1, 12 do
                    elevationParams.FilterDescendantsInstances = {
                        LocalPlayer.Character,
                    }

                    local hit = Workspace:Raycast(pos, Vector3.new(0, -VOID_PROBE, 0), elevationParams)

                    if not hit then
                        return pos, true
                    end

                    pos = Vector3.new(pos.X, underside(hit), pos.Z)
                end

                return pos, false
            end
            local function inVoid(target)
                local char = LocalPlayer.Character
                local root = char and char:FindFirstChild('HumanoidRootPart')

                if not (root and target) or root.Position.Y > target.Y + VOID_CLEAR then
                    return false
                end

                elevationParams.FilterDescendantsInstances = {char}

                return Workspace:Raycast(root.Position, Vector3.new(0, -VOID_PROBE, 0), elevationParams) == nil
            end
            local function isGrounded()
                local char = LocalPlayer.Character
                local hum = char and char:FindFirstChildOfClass('Humanoid')

                if not hum then
                    return false
                end

                local st = hum:GetState()

                return hum.FloorMaterial ~= Enum.Material.Air and st ~= Enum.HumanoidStateType.Freefall and st ~= Enum.HumanoidStateType.Flying
            end

            return function(ctx)
                local Library = ctx.Library
                local Toggles, Options = Library.Toggles, Library.Options
                local Botting = ctx.Tabs.Botting
                local trinket_bot = {
                    path_points = {},
                    active_points = {},
                    point_visualizations = {},
                    path_running = false,
                    stopped = false,
                    current_path_name = '',
                    current_index = 0,
                    moderator_detected = false,
                    pending_pickup_ids = {},
                    pending_artifact_logs = {},
                    session_loot = {},
                    session_start_time = 0,
                    collected_order = {},
                }

                ctx.State.trinketBot = trinket_bot

                local escapeCombat

                local function botKick(reason, settle)
                    if Toggles.StayInServer and Toggles.StayInServer.Value then
                        Console.print(
[[[sentinel] trinket bot: kick suppressed (staying in server): ]] .. tostring(reason))

                        return false
                    end

                    local alive = Character.humanoid()

                    if escapeCombat and alive and alive.Health > 0 then
                        escapeCombat(reason)
                    end

                    repeat
                        local char = LocalPlayer.Character
                        local hum = char and char:FindFirstChildOfClass('Humanoid')
                        local tagged = hum ~= nil and hum.Health > 0 and CollectionService:HasTag(char, 'Danger')

                        if tagged then
                            task.wait(0.25)
                        end
                    until not tagged

                    return Kick.now(reason, settle)
                end
                local function botLog(fmt, ...)
                    if select('#', ...) > 0 then
                        local ok, s = pcall(string.format, fmt, ...)

                        Console.print('[sentinel.bz] ' .. (ok and s or tostring(fmt)))
                    else
                        Console.print('[sentinel.bz] ' .. tostring(fmt))
                    end
                end

                ctx.State.botLog = botLog
                allyOf = function(p)
                    return ctx.State.isFriendly ~= nil and ctx.State.isFriendly(p) == true
                end

                local function twinCanMoveUs()
                    return (Toggles.AvoidOtherBots == nil or Toggles.AvoidOtherBots.Value) and not (Toggles.StayInServer and Toggles.StayInServer.Value)
                end
                local function botActive()
                    return trinket_bot.path_running == true or MemStore.get('botstarted') == 'true'
                end
                local function botTargetFps()
                    if botActive() and Toggles.BotCustomFPS and Toggles.BotCustomFPS.Value then
                        return FpsCap.parse(Options.BotFPS and Options.BotFPS.Value) or 240
                    end

                    return 240
                end
                local function applyBotFps()
                    local on = botActive() and Toggles.BotCustomFPS and Toggles.BotCustomFPS.Value

                    FpsCap.set('trinketbot', on and Options.BotFPS and Options.BotFPS.Value or nil)
                end

                ctx.State.botTargetFps = botTargetFps

                local function checkCastleReply(listener)
                    if not listener then
                        return
                    end

                    local msg = listener:wait(8)

                    listener:stop()

                    if msg and tostring(msg):find('withered by the harsh winds', 1, true) then
                        trinket_bot.skipCastleRock = true

                        botLog('Castle Rock refused: %s', tostring(msg))
                        Notify.say('skipping cr because it wont let me in')
                    end
                end
                local function noteGateBlocked(gateIdx, total, who, isLast)
                    local msg = isLast and string.format('Gate %d/%d is the last point - skipping', gateIdx, total) or string.format('Gate %d/%d destination blocked by %s - trying next gate', gateIdx, total, tostring(who))

                    botLog('%s', msg)
                    Notify.say(msg)
                end

                local state = {
                    unloaded = false,
                    emergency_gate_requested = nil,
                    emergency_gate_in_progress = false,
                    currently_dropping = false,
                    current_gate_section = 0,
                    player_encounters = {},
                    proximity_warnings = {},
                    mana_initialized = false,
                    input_blocked = false,
                    dragMode = false,
                    vizDirty = false,
                    collectedIds = {},
                    iceDragonSkipIndex = nil,
                    gnavDetected = false,
                    gnavPlayerName = nil,
                    fimbulEscape = false,
                    lootBaselines = {},
                    conditionVarByLabel = {},
                    trinketInfo = {},
                    aaHandling = false,
                    droppedTools = {},
                    popAccum = 0,
                }
                local active_tween = {
                    tween = nil,
                    connection = nil,
                }

                ctx.Maid:Give(function()
                    state.unloaded = true
                    trinket_bot.path_running = false
                end)

                local vimInstance

                local function getVim()
                    if not vimInstance then
                        local ok, v = pcall(function()
                            return Instance.new('VirtualInputManager')
                        end)

                        vimInstance = ok and v or nil
                    end

                    return vimInstance
                end
                local function clickRemote(name)
                    local char = LocalPlayer.Character
                    local handler = char and char:FindFirstChild('CharacterHandler')
                    local remotes = handler and handler:FindFirstChild('Remotes')

                    return remotes and remotes:FindFirstChild(name)
                end
                local function rightClick()
                    local remote = clickRemote('RightClick')

                    if remote then
                        pcall(function()
                            remote:FireServer({
                                math.random(1, 10),
                                math.random(),
                            })
                        end)
                    end
                end
                local function leftClick()
                    local vim = getVim()

                    if vim then
                        task.spawn(function()
                            vim:SendMouseButtonEvent(0, 0, 0, true, game, 1)
                            task.wait(math.random(1, 15) / 1000)
                            vim:SendMouseButtonEvent(0, 0, 0, false, game, 1)
                        end)
                    end

                    local remote = clickRemote('LeftClick')

                    if remote then
                        pcall(function()
                            remote:FireServer({
                                math.random(1, 10),
                                tonumber('0.' .. math.random(1e15, 9e15)),
                            })
                        end)
                    end
                end
                local function findTool(name)
                    if not name or name == '' then
                        return nil
                    end

                    local lower = name:lower()
                    local bp = LocalPlayer:FindFirstChildOfClass('Backpack')
                    local char = LocalPlayer.Character

                    for _, container in {bp, char}do
                        if container then
                            for _, t in container:GetChildren()do
                                if t:IsA('Tool') and t.Name:lower() == lower then
                                    return t
                                end
                            end
                        end
                    end

                    return nil
                end
                local function sanitizeLuaName(raw)
                    local name = tostring(raw or ''):match('([^/\\]+)$')

                    if not name or name == '' then
                        return nil
                    end
                    if not name:match('%.lua$') then
                        name = name .. '.lua'
                    end
                    if name:find('%.%.', 1, true) then
                        return nil
                    end

                    return name
                end

                local setInnAction, talkToAction, clickAction, dropAction, wipeAction, walkToAction, menuTeleAction
                local waitOutDanger, trinketBotServerhop

                local function armRelocate()
                    trinket_bot.expectedDeathUntil = tick() + EXPECTED_DEATH_WINDOW
                    trinket_bot.spawnShieldUntil = tick() + SPAWN_SHIELD_GRACE
                end
                local function runPathLua(point, file, asCondition)
                    if not (isfile and readfile and loadstring) then
                        return
                    end

                    local name = sanitizeLuaName(file or (point and point.file))

                    if not name then
                        botLog('Lua action: invalid file %q', tostring(point.file))

                        return
                    end

                    local file = LUA_DIR .. '/' .. name

                    if not isfile(file) then
                        botLog('Lua action: %s not found in %s - skipping', name, LUA_DIR)

                        return
                    end

                    local source

                    if not pcall(function()
                        source = readfile(file)
                    end) or type(source) ~= 'string' then
                        botLog("Lua action: couldn't read %s", name)

                        return
                    end

                    source = source:gsub('^\u{feff}', '')

                    local chunk, compileErr = loadstring(source, '@' .. name)

                    if not chunk then
                        botLog("Lua action: %s won't compile - %s", name, tostring(compileErr))

                        return
                    end

                    local char = LocalPlayer.Character
                    local env = {
                        char = char,
                        hum = char and char:FindFirstChildOfClass('Humanoid'),
                        hrp = char and char:FindFirstChild('HumanoidRootPart'),
                        point = point,
                        findTool = findTool,
                        leftClick = leftClick,
                        rightClick = rightClick,
                        requestRemote = requestRemote,
                        mana = ctx.State.mana,
                        botLog = botLog,
                        running = function()
                            return trinket_bot.path_running and not trinket_bot.moderator_detected and not trinket_bot.stopped
                        end,
                        webhook = function(text)
                            local body = tostring(text or ''):match('^%s*(.-)%s*$')

                            if body == '' then
                                return false
                            end

                            Webhook.text(body)

                            return true
                        end,
                        drop = function(what, amount)
                            local name = tostring(what or ''):match('^%s*(.-)%s*$')

                            if name:lower() == 'silver' then
                                return dropAction(tonumber(amount) or tonumber(name) or 0) == true
                            end

                            local everything = amount == true
                            local limit = everything and 60 or math.max(1, math.floor(tonumber(amount) or 1))
                            local dropped = 0

                            while dropped < limit do
                                if dropped > 0 then
                                    task.wait(0.35)

                                    if everything and not findTool(name) then
                                        break
                                    end
                                end
                                if not dropAction(name) then
                                    break
                                end

                                dropped += 1
                            end

                            return dropped > 0
                        end,
                        expectDeath = armRelocate,
                        kill = function()
                            armRelocate()
                            waitOutDanger()
                            pcall(Character.kill)

                            trinket_bot.relocated = true
                        end,
                        wipe = function()
                            armRelocate()

                            local spent = wipeAction ~= nil and wipeAction() == true

                            trinket_bot.relocated = true

                            return spent
                        end,
                        menu = function(text, fallback)
                            armRelocate()

                            local moved = menuTeleAction ~= nil and menuTeleAction(fallback, text) == true

                            if moved then
                                trinket_bot.relocated = true
                            end

                            return moved
                        end,
                        setInn = function(name)
                            armRelocate()

                            local ok = setInnAction ~= nil and setInnAction(name) == true

                            if ok then
                                trinket_bot.relocated = true
                            end

                            return ok
                        end,
                    }

                    if not asCondition then
                        env.runPath = function(target, times)
                            local at = trinket_bot.current_index

                            if not (trinket_bot.path_running and at and trinket_bot.active_points[at] == point) then
                                return false
                            end

                            local raw = tostring(target or ''):gsub('\\', '/'):gsub('%.json$', ''):match('^%s*(.-)%s*$')

                            if raw == '' or raw:find('..', 1, true) then
                                return false
                            end

                            local folder = PathNames.split(trinket_bot.current_path_name)
                            local tries = {raw}

                            if folder ~= '' then
                                table.insert(tries, 1, folder .. '/' .. raw)
                            end

                            local resolved

                            for _, candidate in tries do
                                if isfile(PATH_DIR .. '/' .. candidate .. '.json') then
                                    resolved = candidate

                                    break
                                end
                            end

                            if not resolved then
                                botLog("Lua runPath: no path called '%s' next to %s", raw, trinket_bot.current_path_name)

                                return false
                            end

                            local depth = (point.subDepth or 0) + 1

                            if depth > BOT.subDepth then
                                botLog("Lua runPath: '%s' nested %d deep, skipping", resolved, depth)

                                return false
                            end

                            local runs = math.max(1, math.floor(tonumber(times) or 1))
                            local added, why = subPathRun(trinket_bot, at, resolved, runs - 1, nil, depth)

                            if why then
                                botLog('Lua %s', why)

                                return false
                            end

                            trinket_bot.branchesStale = true

                            botLog('Lua runPath: %s (%d points, %d run%s)', resolved, added, runs, runs == 1 and '' or 's')

                            return true
                        end
                        env.serverhop = function(reason)
                            if trinket_bot.stopped or trinket_bot.test_mode or (Toggles.StayInServer and Toggles.StayInServer.Value) then
                                return false
                            end

                            local why = tostring(reason or ''):match('^%s*(.-)%s*$')

                            trinketBotServerhop(string.format('%s (Lua %s)', why ~= '' and why or 'serverhop', name), nil, true)

                            return true
                        end
                    end

                    local ok, result = pcall(chunk, env)

                    if not ok then
                        botLog('Lua %s: %s errored - %s', asCondition and 'condition' or 'action', name, tostring(result))

                        return
                    end

                    return true, result
                end
                local function runPathAction(point)
                    local char = LocalPlayer.Character
                    local hum = char and char:FindFirstChildOfClass('Humanoid')
                    local a = point.action
                    local moved = true

                    if RELOCATING_ACTIONS[a] then
                        armRelocate()
                    end
                    if a == 'captcha' then
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                        if tick() - (trinket_bot.captchaSolvedAt or 0) < 12 then
                            botLog(
[[Captcha action: the click before this already solved one, skipping]])
                        elseif not Captcha.available() then
                            botLog('Captcha action: solver could not be loaded')
                        elseif not pg then
                            botLog('Captcha action: no PlayerGui')
                        else
                            local listener = Dialogue.listen()

                            local function captchaGui()
                                return pg:FindFirstChild('Captcha', true) or pg:FindFirstChild('CaptchaLoad', true)
                            end

                            local appearBy = tick() + 15

                            while not captchaGui() and tick() < appearBy and trinket_bot.path_running do
                                task.wait(0.1)
                            end

                            local found = captchaGui()
                            local ok, detail = false, nil

                            if found then
                                ok, detail = Captcha.solveGui(found.Parent, 8)
                            else
                                local open = {}

                                for _, gui in pg:GetChildren()do
                                    if gui:IsA('ScreenGui') and gui.Enabled then
                                        table.insert(open, gui.Name)
                                    end
                                end

                                detail = 'no captcha came up within 15s, open guis: ' .. (#open > 0 and table.concat(open, ', ') or 'none')
                            end

                            botLog('Captcha action: %s (%s)', ok and 'solved' or 'failed', tostring(detail))
                            checkCastleReply(listener)

                            if ok then
                                local settle = tick() + 5

                                while pg:FindFirstChild('Captcha', true) and tick() < settle do
                                    task.wait(0.1)
                                end

                                if pg:FindFirstChild('Captcha', true) then
                                    botLog('Captcha action: answered but the window is still up')
                                end
                                if Dialogue.inDialogue() then
                                    botLog('Captcha action: closing the talk it left open')
                                    Dialogue.close()
                                end
                            end
                        end
                    elseif a == 'unequip' then
                        path_tool = nil

                        if hum then
                            hum:UnequipTools()
                        end
                    elseif a == 'equip' then
                        local tool = findTool(point.tool)

                        if tool and hum then
                            hum:EquipTool(tool)

                            path_tool = tool.Name
                        end
                    elseif a == 'leftclick' then
                        leftClick()
                    elseif a == 'rightclick' then
                        rightClick()
                    elseif a == 'use' then
                        local tool = findTool(point.tool)

                        if tool and hum then
                            hum:EquipTool(tool)

                            path_tool = tool.Name
                        end

                        task.wait(0.35)
                        leftClick()
                    elseif a == 'sleep' then
                        local waited, target = 0, tonumber(point.duration) or 0

                        while waited < target and trinket_bot.path_running do
                            task.wait(0.1)

                            waited += 0.1
                        end
                    elseif a == 'charge' then
                        local mana = ctx.State.mana

                        if mana and mana.chargeUntil then
                            mana.chargeUntil(tonumber(point.amount) or 50, function(
                            )
                                return trinket_bot.path_running and not trinket_bot.moderator_detected
                            end)
                        end
                    elseif a == 'runlua' then
                        runPathLua(point)
                    elseif a == 'waitday' then
                        local reader = ctx.State.currentDay

                        local function today()
                            return tonumber(reader and reader() or Remotes.getServerValue('DaysSurvived'))
                        end

                        local target = tonumber(point.day) or 0

                        if target <= 0 then
                            target = (today() or 0) + 1
                        end

                        botLog('Waiting for day %d', target)

                        local nagged = tick()

                        while trinket_bot.path_running and not trinket_bot.moderator_detected do
                            local day = today()

                            if day and day >= target then
                                botLog('Day %d reached', day)

                                break
                            end
                            if tick() - nagged > BOT.waitDayNag then
                                nagged = tick()

                                botLog('Still day %s, holding for %d', tostring(day or '?'), target)
                            end

                            task.wait(BOT.waitDayPoll)
                        end
                    elseif a == 'brew' or a == 'smith' then
                        local craft = ctx.State.craft
                        local smithing = a == 'smith'
                        local label = smithing and 'Smith' or 'Potion'
                        local item = tostring((if smithing then point.weapon else point.potion) or '')
                        local count = craftCount(point.count)

                        if item == '' then
                            botLog('%s action: nothing picked', label)
                        elseif not craft then
                            botLog('%s action: auto crafting is not loaded', label)
                        else
                            botLog('%s %s %s', smithing and 'Smithing' or 'Brewing', count and tostring(count) or 'all the', item)

                            local ok, made, unit = craft(smithing and 'Smithing' or 'Alchemy', item, count, function(
                            )
                                return trinket_bot.path_running and not trinket_bot.moderator_detected
                            end)

                            botLog('%s action: made %d%s %s%s%s', label, made, count and (' of ' .. count) or ' (all materials)', item, unit == 'brews' and ' (counted by brews, Double Craft without Snake Blood)' or '', ok and '' or (', stopped early (no ' .. (smithing and 'smithing station' or 'cauldron') .. ', missing materials or a craft failed)'))
                        end
                    elseif a == 'webhook' then
                        local body = tostring(point.message or ''):match('^%s*(.-)%s*$')

                        if body == '' then
                            botLog('Webhook: no message set on this point')
                        else
                            botLog('Webhook -> %s', body)
                            Webhook.text(body)
                        end
                    elseif a == 'setinn' then
                        moved = setInnAction ~= nil and setInnAction(point.inn) == true

                        if moved then
                            if MemStore.get(MENUTELE_FAIL) == 'inn:' .. tostring(point.inn) then
                                MemStore.remove(MENUTELE_FAIL)
                            end
                        elseif trinket_bot.path_running and not trinket_bot.stopped then
                            trinket_bot.innFailed = tostring(point.inn or '')
                        end
                    elseif a == 'talkto' then
                        if talkToAction then
                            talkToAction(point.npc, point.choices, nil, point.hold)
                        end
                    elseif a == 'click' then
                        if clickAction then
                            clickAction(point.target)
                        end
                    elseif a == 'drop' then
                        if dropAction then
                            dropAction(point.tool)
                        end
                    elseif a == 'wipe' then
                        if wipeAction then
                            wipeAction()
                        end
                    elseif a == 'walkto' then
                        if walkToAction then
                            walkToAction(point.position)
                        end
                    elseif a == 'menutele' then
                        moved = menuTeleAction ~= nil and menuTeleAction(point.position, point.target) == true
                    elseif a == 'reset' then
                        waitOutDanger()
                        pcall(Character.kill)
                    end
                    if RELOCATING_ACTIONS[a] and moved then
                        trinket_bot.relocated = true
                    end
                end
                local function getStat(value)
                    local getRemote = requestRemote('Get')

                    if not getRemote then
                        return nil
                    end

                    local ok, result = pcall(function()
                        return getRemote:InvokeServer(utf8.char(65532) .. '\u{1f603}', value)[value]
                    end)

                    return ok and result or nil
                end
                local function getPing()
                    local ok, ping = pcall(function()
                        return game:GetService('Stats'):WaitForChild('PerformanceStats'):WaitForChild('Ping'):GetValue()
                    end)

                    return ok and ping or 0
                end

                local smoothedPing = getPing()

                task.spawn(function()
                    while not state.unloaded do
                        smoothedPing = smoothedPing * 0.8 + getPing() * 0.2

                        task.wait(0.1)
                    end
                end)

                local pingWait = BASIL_NO_VIRTUALIZE(function()
                    return math.min(0.025 + smoothedPing / 1000, 0.35)
                end)

                local function pingGateOk()
                    local saved = MemStore.getJSON('trinket_bot_settings')
                    local savedPing = type(saved) == 'table' and type(saved.options) == 'table' and tonumber(saved.options.TrinketBotPing) or nil
                    local maxPing = savedPing or (Options.TrinketBotPing and Options.TrinketBotPing.Value) or 500

                    if maxPing <= 0 then
                        return true
                    end

                    local item

                    pcall(function()
                        item = game:GetService('Stats').Network.ServerStatsItem['Data Ping']
                    end)

                    if not item then
                        return true
                    end

                    local score, started = 0, tick()

                    repeat
                        if item:GetValue() > maxPing then
                            score -= 1
                        else
                            score += 1
                        end

                        task.wait(0.5)
                    until score >= 5 or score <= -10 or tick() - started > 10

                    return score >= 5
                end
                local function blockInputs()
                    state.input_blocked = true

                    pcall(function()
                        ContextActionService:BindAction('SentinelBlockMouse', function(
                        )
                            if state.input_blocked then
                                return Enum.ContextActionResult.Sink
                            end

                            return Enum.ContextActionResult.Pass
                        end, false, Enum.UserInputType.MouseButton1, Enum.UserInputType.MouseButton2)
                    end)
                end
                local function unblockInputs()
                    state.input_blocked = false

                    pcall(function()
                        ContextActionService:UnbindAction('SentinelBlockMouse')
                    end)
                end

                local isOreNode, nodeOreFilter

                local function randomName()
                    local chars = {}

                    for _ = 1, 12 do
                        chars[#chars + 1] = string.char(math.random(97, 122))
                    end

                    return table.concat(chars)
                end

                local conditionText
                local sphereIndex = setmetatable({}, {
                    __mode = 'k',
                })
                local viz = {
                    gen = 0,
                    keys = {},
                    drawn = {},
                    tail = nil,
                    domes = {},
                    beams = {},
                    accum = 0,
                    drag = false,
                }

                local function createVisualization(
                    position,
                    isWait,
                    isGate,
                    index,
                    total,
                    gateLocation,
                    condition,
                    actionLabel,
                    isNode,
                    nodeRange,
                    trinketRange
                )
                    local color = actionLabel and POINT_ACTION or (isGate and POINT_GATE or (isNode and POINT_NODE or (isWait and POINT_WAIT or POINT_NORMAL)))
                    local dome
                    local sphere = Make('Part', {
                        Shape = Enum.PartType.Ball,
                        Size = Vector3.new(1.5, 1.5, 1.5),
                        Position = position,
                        Anchored = true,
                        CanCollide = false,
                        CanQuery = state.dragMode == true,
                        Material = Enum.Material.Neon,
                        Color = color,
                        Transparency = 0.2,
                        Name = randomName(),
                    })
                    local billboard = Make('BillboardGui', {
                        Name = 'Tag',
                        Size = UDim2.new(0, (isGate or actionLabel) and 180 or 120, 0, 30),
                        StudsOffset = Vector3.new(0, 2.1, 0),
                        AlwaysOnTop = true,
                        LightInfluence = 0,
                        Active = false,
                    })

                    billboard.MaxDistance = VIZ_LABEL_DISTANCE
                    billboard.Parent = sphere

                    local label = Make('TextLabel', {
                        Size = UDim2.new(1, 0, 1, 0),
                        BackgroundTransparency = 1,
                        Font = Enum.Font.GothamBold,
                        TextSize = 14,
                        TextColor3 = color,
                        TextStrokeColor3 = Color3.fromRGB(0, 0, 0),
                        TextStrokeTransparency = 0.3,
                    })

                    if actionLabel then
                        label.Text = string.format('%d/%d  \u{b7}  %s', index, total, actionLabel)
                    elseif isGate then
                        local dest = (gateLocation and gateLocation ~= '') and gateLocation or '?'

                        label.Text = string.format('%d/%d  \u{b7}  GATE \u{2192} %s', index, total, dest)
                    elseif isNode then
                        label.Text = string.format('%d/%d  \u{b7}  NODE', index, total)
                    elseif isWait then
                        label.Text = string.format('%d/%d  \u{b7}  WAIT', index, total)
                    else
                        label.Text = string.format('%d/%d', index, total)
                    end
                    if type(condition) == 'table' and condition.var then
                        label.Text = label.Text .. '\nif ' .. (conditionText and conditionText(condition) or '')
                        billboard.Size = UDim2.new(0, 200, 0, 44)
                    end

                    label.Parent = billboard

                    local attachment = Make('Attachment', {Parent = sphere})

                    sphere.Parent = Workspace:FindFirstChild('Thrown') or Workspace

                    local cover = (trinketRange and trinketRange > 0) and trinketRange or BOT.waitCover

                    if isWait and cover > 0 then
                        local dome = Make('Part', {
                            Shape = Enum.PartType.Ball,
                            Size = Vector3.new(cover * 2, cover * 2, cover * 2),
                            Position = position,
                            Anchored = true,
                            CanCollide = false,
                            CanQuery = false,
                            CanTouch = false,
                            CastShadow = false,
                            Material = Enum.Material.ForceField,
                            Color = POINT_WAIT,
                            Transparency = 0,
                            Name = randomName(),
                        })
                        local eye = Character.root()

                        dome.Transparency = (eye and (eye.Position - position).Magnitude <= cover + BOT.domeReveal) and 0 or 1
                        dome.Parent = sphere.Parent

                        table.insert(trinket_bot.point_visualizations, dome)

                        viz.domes[dome] = {
                            at = position,
                            reach = cover + BOT.domeReveal,
                        }
                    end
                    if isNode then
                        local ores = Workspace:FindFirstChild('Ores')

                        if ores then
                            local range = (nodeRange and nodeRange > 0) and nodeRange or 150
                            local filter = nodeOreFilter()
                            local drawn = 0

                            for _, node in ores:GetChildren()do
                                if drawn >= 24 then
                                    break
                                end
                                if isOreNode(node) and node.Transparency < 1 and (filter == nil or filter[node.Name]) and (node.Position - position).Magnitude <= range then
                                    drawn += 1

                                    local hl = Make('Highlight', {
                                        Adornee = node,
                                        FillColor = POINT_NODE,
                                        OutlineColor = POINT_NODE,
                                        FillTransparency = 0.5,
                                        OutlineTransparency = 0,
                                        Name = randomName(),
                                        Parent = sphere,
                                    })
                                end
                            end
                        end
                    end

                    return sphere, attachment, label, dome
                end
                local function createBeam(fromAttach, toAttach)
                    local beam = Make('Beam', {
                        Attachment0 = fromAttach,
                        Attachment1 = toAttach,
                        Width0 = 0.12,
                        Width1 = 0.12,
                        FaceCamera = true,
                        Color = ColorSequence.new(Color3.fromRGB(150, 150, 170)),
                        Transparency = NumberSequence.new(0.45),
                        Parent = fromAttach.Parent,
                    })
                    local a, b = fromAttach.WorldPosition, toAttach.WorldPosition

                    viz.beams[beam] = {
                        at = (a + b) / 2,
                        reach = VIZ_LABEL_DISTANCE + (a - b).Magnitude / 2,
                    }
                    beam.Enabled = false

                    return beam
                end
                local function actionLabelFor(point)
                    local base = ACTION_VIZ[point.action]

                    if not base then
                        return nil
                    end
                    if (point.action == 'equip' or point.action == 'use') and point.tool and point.tool ~= '' then
                        return base .. ' ' .. point.tool
                    elseif point.action == 'sleep' then
                        return base .. ' ' .. tostring(point.duration or 0) .. 's'
                    elseif point.action == 'charge' then
                        return base .. ' ' .. tostring(point.amount or 0)
                    elseif point.action == 'runlua' then
                        return base .. ' ' .. (point.file ~= nil and point.file ~= '' and tostring(point.file) or '?')
                    elseif point.action == 'setinn' then
                        return base .. ' ' .. (point.inn ~= nil and point.inn ~= '' and tostring(point.inn) or '?')
                    elseif point.action == 'talkto' then
                        return base .. ' ' .. (point.npc ~= nil and point.npc ~= '' and tostring(point.npc) or '?')
                    elseif point.action == 'click' then
                        return base .. ' ' .. ((point.target ~= nil and point.target ~= '' and tostring(point.target):match('([%w_ ]+)%]?$')) or '?')
                    elseif point.action == 'drop' then
                        return base .. ' ' .. (point.tool ~= nil and point.tool ~= '' and tostring(point.tool) or '?')
                    elseif point.action == 'webhook' then
                        return base .. ' ' .. (point.message ~= nil and point.message ~= '' and tostring(point.message):sub(1, 24) or '?')
                    elseif point.action == 'subpath' then
                        return base .. ' ' .. (point.target ~= nil and point.target ~= '' and tostring(point.target) or '?')
                    elseif point.action == 'waitday' then
                        return base .. ' ' .. ((tonumber(point.day) or 0) > 0 and tostring(point.day) or '+1')
                    elseif point.action == 'brew' or point.action == 'smith' then
                        local item = if point.action == 'smith'then point.weapon else point.potion
                        local name = item ~= nil and item ~= '' and tostring(item) or '?'
                        local count = craftCount(point.count)

                        return base .. ' ' .. name .. (count and (' x' .. count) or ' all')
                    end

                    return base
                end
                local function rebuildVisualizations()
                    viz.gen += 1

                    local myGen = viz.gen
                    local on = Toggles.VisualizePoints ~= nil and Toggles.VisualizePoints.Value == true
                    local keys = {}

                    if on then
                        for index, point in trinket_bot.path_points do
                            local cond = point.condition

                            keys[index] = table.concat({
                                index,
                                tostring(point.action or ''),
                                tostring(point.is_gate_point),
                                tostring(point.wait_for_trinket),
                                tostring(point.wait_for_node),
                                tostring(point.node_range),
                                tostring(point.trinket_range),
                                tostring(point.gate_location or ''),
                                tostring(point.position),
                                cond and (tostring(cond.var) .. tostring(cond.op) .. tostring(cond.value)) or '',
                                tostring(actionLabelFor(point) or ''),
                            }, '|')
                        end
                    end

                    local kept = on and #viz.drawn > 0 and #keys >= #viz.keys

                    if kept then
                        for i = 1, #viz.keys do
                            if viz.keys[i] ~= keys[i] then
                                kept = false

                                break
                            end
                        end
                    end
                    if not kept then
                        for _, part in trinket_bot.point_visualizations do
                            pcall(function()
                                part:Destroy()
                            end)
                        end

                        trinket_bot.point_visualizations = {}

                        table.clear(viz.drawn)
                        table.clear(viz.domes)
                        table.clear(viz.beams)

                        viz.tail = nil
                    end

                    viz.keys = keys

                    if not on then
                        return
                    end

                    local total = #trinket_bot.path_points
                    local from = 1

                    if kept then
                        if viz.drag ~= state.dragMode then
                            for _, entry in viz.drawn do
                                if entry.sphere and entry.sphere.Parent then
                                    entry.sphere.CanQuery = state.dragMode == true
                                end
                            end
                        end

                        from = viz.drawn[#viz.drawn].index + 1

                        for _, entry in viz.drawn do
                            if entry.label and entry.label.Parent then
                                entry.label.Text = entry.label.Text:gsub('^(%d+)/%d+', '%1/' .. total, 1)
                            end
                        end
                    end

                    viz.drag = state.dragMode

                    for index = from, total do
                        if state.unloaded or viz.gen ~= myGen then
                            return
                        end

                        local point = trinket_bot.path_points[index]

                        if not (point.action and BRANCH_KINDS[point.action]) then
                            local actionLabel = point.action and actionLabelFor(point) or nil
                            local ok, sphere, attach, label = pcall(createVisualization, point.position, point.wait_for_trinket, point.is_gate_point, index, total, point.gate_location, point.condition, actionLabel, point.wait_for_node, point.node_range, point.trinket_range)

                            if ok and sphere then
                                sphereIndex[sphere] = index

                                table.insert(trinket_bot.point_visualizations, sphere)
                                table.insert(viz.drawn, {
                                    index = index,
                                    label = label,
                                    sphere = sphere,
                                })

                                if viz.tail and attach then
                                    local okb, beam = pcall(createBeam, viz.tail, attach)

                                    if okb and beam then
                                        table.insert(trinket_bot.point_visualizations, beam)
                                    end
                                end

                                viz.tail = attach
                            end
                        end
                        if index % 20 == 0 then
                            task.wait()
                        end
                    end
                end

                ctx.Maid:Connect(RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                    dt
                )
                    viz.accum += dt

                    if viz.accum < BOT.domeTick then
                        return
                    end

                    viz.accum = 0

                    local root = Character.root()

                    for dome, info in viz.domes do
                        if not dome.Parent then
                            viz.domes[dome] = nil
                        else
                            dome.Transparency = (root and (root.Position - info.at).Magnitude <= info.reach) and 0 or 1
                        end
                    end
                    for beam, info in viz.beams do
                        if not beam.Parent then
                            viz.beams[beam] = nil
                        else
                            beam.Enabled = root ~= nil and (root.Position - info.at).Magnitude <= info.reach
                        end
                    end
                end))

                local function updateVisualizations()
                    if state.vizDirty then
                        return
                    end

                    state.vizDirty = true

                    task.delay(0.06, function()
                        state.vizDirty = false

                        rebuildVisualizations()
                    end)
                end

                ctx.State.updatePathVisualizations = updateVisualizations

                ctx.Maid:Give(function()
                    for _, part in trinket_bot.point_visualizations do
                        pcall(function()
                            part:Destroy()
                        end)
                    end
                end)

                local onLoadingPad = Character.onLoadingPad

                local function waitForSpawn()
                    if not onLoadingPad() then
                        return true
                    end

                    botLog('Character is still being placed, holding before moving')

                    local deadline = os.clock() + LOADING_PAD_WAIT

                    while os.clock() < deadline do
                        if not trinket_bot.path_running or state.unloaded then
                            return false
                        end
                        if not onLoadingPad() then
                            botLog('Character placed, resuming')

                            return true
                        end

                        task.wait(0.15)
                    end

                    return false
                end
                local function SmoothTeleport(
                    target,
                    isTrinketTeleport,
                    speedOverride,
                    pathLeg
                )
                    if not waitForSpawn() then
                        botLog(
[[Still not placed after %ds - stopping rather than moving from the pad]], LOADING_PAD_WAIT)

                        trinket_bot.path_running = false

                        return
                    end

                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild('HumanoidRootPart')

                    if not root or state.unloaded then
                        return
                    end

                    local targetPosition

                    if typeof(target) == 'CFrame' then
                        targetPosition = target.Position
                    elseif typeof(target) == 'Vector3' then
                        targetPosition = target
                    elseif typeof(target) == 'Instance' and target:IsA('BasePart') then
                        targetPosition = target.Position
                    else
                        return
                    end

                    local distance = (targetPosition - root.Position).Magnitude
                    local afterRespawn = trinket_bot.relocated == true

                    trinket_bot.relocated = false

                    if distance > TELEPORT_CAP then
                        if not (afterRespawn or pathLeg) then
                            botLog(
[[Refused %.0f-stud teleport to (%.0f, %.0f, %.0f) - over the %d cap]], distance, targetPosition.X, targetPosition.Y, targetPosition.Z, TELEPORT_CAP)

                            if Toggles.StayInServer.Value then
                                Notify.say(string.format('Refused %0.f-stud teleport - stopping path', distance))

                                trinket_bot.path_running = false
                            else
                                trinketBotServerhop(string.format('Refused a %.0f-stud teleport, recovering in a fresh server', distance))
                            end

                            return
                        end

                        botLog(afterRespawn and
[[Allowing a %.0f-stud teleport back to the path, the last action respawned us]] or 'Flying a %.0f-stud leg, the path is laid out that way', distance)
                    end

                    local humanoid = char:FindFirstChildOfClass('Humanoid')

                    if humanoid then
                        humanoid:SetStateEnabled(5, false)
                        humanoid:ChangeState(3)
                    end

                    local connection = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        if state.unloaded then
                            return
                        end

                        Character.noclip(LocalPlayer.Character, true)
                    end))
                    local speed = speedOverride or (Options.TrinketBotSpeed and Options.TrinketBotSpeed.Value) or 100
                    local tween = TweenService:Create(root, TweenInfo.new(distance / speed, Enum.EasingStyle.Linear), {
                        CFrame = CFrame.new(targetPosition),
                    })

                    active_tween.tween = tween
                    active_tween.connection = connection

                    local completed = false

                    tween.Completed:Connect(function()
                        completed = true
                    end)
                    tween:Play()
                    BASIL_NO_VIRTUALIZE(function()
                        while not completed and not state.unloaded and (trinket_bot.path_running or trinket_bot.combatEscape) and not state.emergency_gate_requested and not trinket_bot.moderator_detected do
                            task.wait()
                        end
                    end)()

                    if state.unloaded or not (trinket_bot.path_running or trinket_bot.combatEscape) or trinket_bot.moderator_detected then
                        tween:Cancel()
                    end
                    if not state.unloaded and isTrinketTeleport then
                        task.wait(0.25)
                    end
                    if humanoid then
                        humanoid:SetStateEnabled(5, true)
                        humanoid:ChangeState(Enum.HumanoidStateType.Running)
                    end

                    active_tween.tween = nil

                    task.spawn(function()
                        pcall(Character.awaitClear, 0.15, 1.5, function()
                            return trinket_bot.path_running == true or trinket_bot.combatEscape == true
                        end)

                        if active_tween.connection == connection then
                            active_tween.connection = nil

                            Character.clearVeil()
                        end

                        connection:Disconnect()
                    end)
                end
                local function holdInPlace(stillWaiting)
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild('HumanoidRootPart')
                    local humanoid = char and char:FindFirstChildOfClass('Humanoid')
                    local anchor = root and root.Position

                    if humanoid then
                        humanoid:SetStateEnabled(5, false)
                        humanoid:ChangeState(3)
                    end

                    local pin = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        local c = LocalPlayer.Character
                        local r = c and c:FindFirstChild('HumanoidRootPart')

                        if not (r and anchor) then
                            return
                        end

                        Character.noclip(c, true)

                        r.CFrame = CFrame.new(anchor)
                        r.AssemblyLinearVelocity = Vector3.zero
                    end))

                    while stillWaiting() do
                        task.wait(0.25)
                    end

                    pin:Disconnect()

                    local h = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                    if h then
                        h:SetStateEnabled(5, true)
                        h:ChangeState(Enum.HumanoidStateType.Running)
                    end
                end

                ctx.State.smoothTeleport = SmoothTeleport

                local function Gate(where, expectedDestination)
                    if not trinket_bot.path_running then
                        return false
                    end

                    trinket_bot.gatingUntil = tick() + 12

                    botLog('Gate: attempting -> %s', tostring(where))

                    local mana = ctx.State.mana

                    if not mana then
                        Notify.say('Gate needs the mana engine (Blatant + hookfunction)')

                        return false
                    end
                    if active_tween.tween then
                        pcall(function()
                            active_tween.tween:Cancel()
                        end)

                        active_tween.tween = nil
                    end
                    if active_tween.connection then
                        active_tween.connection:Disconnect()

                        active_tween.connection = nil
                    end

                    local char = LocalPlayer.Character
                    local humanoid = char and char:FindFirstChildOfClass('Humanoid')

                    if humanoid then
                        humanoid:SetStateEnabled(5, true)
                        humanoid:ChangeState(5)
                    end
                    if not char or not char:FindFirstChild('HumanoidRootPart') then
                        return false
                    end

                    local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
                    local gateTool = char:FindFirstChild('Gate') or (backpack and backpack:FindFirstChild('Gate'))

                    if not gateTool then
                        Notify.say('No Gate tool found')

                        return false
                    end
                    if backpack and backpack:FindFirstChild('Gate') then
                        humanoid:EquipTool(backpack.Gate)
                        task.wait(0.3)
                    end
                    if CollectionService:HasTag(char, 'SnapCool') then
                        local stayInServer = Toggles.StayInServer and Toggles.StayInServer.Value or false
                        local timeout, maxTimeout = 0, stayInServer and 999999 or 100

                        while CollectionService:HasTag(char, 'SnapCool') and timeout < maxTimeout and not state.emergency_gate_requested and trinket_bot.path_running do
                            task.wait(0.1)

                            timeout += 1

                            if CollectionService:HasTag(char, 'Danger') and not stayInServer then
                                return false
                            end
                        end

                        if CollectionService:HasTag(char, 'SnapCool') and not stayInServer then
                            return false
                        end
                    end

                    local mana_value = char:FindFirstChild('Mana')

                    if not mana_value then
                        return false
                    end
                    if CollectionService:HasTag(char, 'Danger') then
                        local stayInServer = Toggles.StayInServer and Toggles.StayInServer.Value or false
                        local nearby = false
                        local hrp = char:FindFirstChild('HumanoidRootPart')

                        if hrp then
                            for _, other in Players:GetPlayers()do
                                local ochar = other ~= LocalPlayer and other.Character
                                local ohrp = ochar and ochar:FindFirstChild('HumanoidRootPart')

                                if ohrp and (ohrp.Position - hrp.Position).Magnitude <= 250 then
                                    nearby = true

                                    break
                                end
                            end
                        end
                        if not nearby then
                            if stayInServer then
                                repeat
                                    task.wait(0.1)
                                until not CollectionService:HasTag(char, 'Danger') or trinket_bot.moderator_detected or not trinket_bot.path_running
                            else
                                repeat
                                    task.wait(0.1)
                                until not CollectionService:HasTag(char, 'Danger') or trinket_bot.moderator_detected or not trinket_bot.path_running
                            end
                            if trinket_bot.moderator_detected or not trinket_bot.path_running then
                                return false
                            end
                        end
                    end
                    if not state.mana_initialized then
                        local vim = getVim()

                        if vim then
                            task.wait(0.3)
                            vim:SendKeyEvent(true, Enum.KeyCode.G, false, game)
                            task.wait(0.15)
                            vim:SendKeyEvent(false, Enum.KeyCode.G, false, game)
                            task.wait(0.2)

                            state.mana_initialized = true
                        end
                    end

                    blockInputs()
                    task.delay(5, function()
                        if state.input_blocked then
                            unblockInputs()
                        end
                    end)

                    local isAzael = getStat('Race') == 'Azael'
                    local artifacts = char:FindFirstChild('Artifacts')
                    local hasPhilo = artifacts and artifacts:FindFirstChild('PhilosophersStone') ~= nil

                    local function chargeActive()
                        return trinket_bot.path_running and not trinket_bot.moderator_detected
                    end
                    local function gateActive()
                        return chargeActive() and not state.emergency_gate_requested
                    end

                    local inDanger = CollectionService:HasTag(char, 'Danger')

                    if isAzael and not inDanger then
                        if mana_value.Value <= AZAEL_GATE_MANA then
                            mana.chargeUntil(AZAEL_GATE_MANA, chargeActive)
                        end
                    elseif hasPhilo then
                        if mana_value.Value < PHILO_GATE_MANA then
                            mana.chargeUntil(PHILO_GATE_MANA, chargeActive)
                        end
                    else
                        local target = math.clamp(GATE_MANA_BASE - (smoothedPing / 900) * 50, GATE_MANA_MIN, GATE_MANA_MAX)

                        if mana_value.Value > GATE_MANA_MAX then
                            mana.decharge()

                            while mana_value.Value > GATE_MANA_MAX and gateActive() do
                                task.wait(0.05)
                            end
                        end
                        if mana_value.Value < target then
                            mana.chargeUntil(target, chargeActive)
                        end
                    end

                    local castRoot = char:FindFirstChild('HumanoidRootPart')
                    local castFrom = castRoot and castRoot.Position

                    task.wait(0.05)
                    rightClick()
                    task.wait(0.8)

                    local psuedo = gateTool:FindFirstChild('PsuedoChatted')

                    if psuedo then
                        psuedo:FireServer(where)
                    end
                    if state.input_blocked then
                        unblockInputs()
                    end

                    local started = tick()

                    while tick() - started < 2.5 and trinket_bot.path_running and not state.emergency_gate_requested and not trinket_bot.moderator_detected do
                        if char:FindFirstChild('NoFall') then
                            task.wait(1.5)

                            local hrp = char:FindFirstChild('HumanoidRootPart')

                            if not hrp then
                                return false
                            end

                            local landed = expectedDestination and (hrp.Position - expectedDestination).Magnitude or nil
                            local settle = tick() + BOT.gateLandWait

                            while landed and landed > 700 and castFrom and (hrp.Position - castFrom).Magnitude < BOT.gateMoved and tick() < settle and trinket_bot.path_running do
                                task.wait(0.1)

                                hrp = char:FindFirstChild('HumanoidRootPart')

                                if not hrp then
                                    return false
                                end

                                landed = (hrp.Position - expectedDestination).Magnitude
                            end

                            if landed and landed > 700 then
                                botLog('Gate: backfire -> %s (landed %.0f studs from next point)', tostring(where), landed)
                                Notify.say(string.format('Gate backfire (%0.f studs off)', landed))

                                return false
                            end

                            botLog('Gate: succeeded -> %s (landed %.0f studs from next point)', tostring(where), landed or 0)

                            trinket_bot.relocated = true

                            return true
                        end

                        task.wait(0.1)
                    end

                    botLog('Gate: timed out -> %s', tostring(where))

                    return false
                end

                ctx.State.gate = Gate

                local function ensureDir()
                    if makefolder and isfolder then
                        if not isfolder('sentinel') then
                            pcall(makefolder, 'sentinel')
                        end
                        if not isfolder(PATH_DIR) then
                            pcall(makefolder, PATH_DIR)
                        end
                        if not isfolder(LUA_DIR) then
                            pcall(makefolder, LUA_DIR)
                        end
                    end
                end

                local captureSettings, applySettings, importHydroxideSettings
                local pathEditor

                local function savePath(name)
                    if not writefile or name == '' then
                        return false
                    end

                    ensureDir()
                    PathNames.ensureFolder(name)

                    local points = {}

                    for _, p in trinket_bot.path_points do
                        local entry = {
                            x = p.position.X,
                            y = p.position.Y,
                            z = p.position.Z,
                            condition = p.condition,
                        }

                        for _, key in POINT_FIELDS do
                            entry[key] = p[key]
                        end

                        table.insert(points, entry)
                    end

                    local ok = pcall(writefile, PATH_DIR .. '/' .. name .. '.json', HttpService:JSONEncode({
                        points = points,
                        settings = captureSettings(),
                    }))

                    return ok
                end
                local function loadPath(name)
                    local points, saved = readPathPoints(name)

                    if not points then
                        return false
                    end

                    trinket_bot.path_points = points

                    table.clear(pathHistory)
                    table.clear(pathFuture)

                    if type(saved) == 'table' then
                        local s = saved
                        local apply = function()
                            if s.toggles or s.options or s.multi then
                                applySettings(s)
                            else
                                importHydroxideSettings(s)
                            end
                        end

                        if ctx.State.loadingConfig then
                            task.defer(apply)
                        else
                            apply()
                        end
                    end

                    trinket_bot.current_path_name = name

                    local folder, leaf = PathNames.split(name)

                    if Options.PathName then
                        Options.PathName:SetValue(leaf)
                    end
                    if Options.PathFolder then
                        Options.PathFolder:SetValue(folder)
                    end

                    updateVisualizations()

                    if pathEditor then
                        pathEditor:Refresh()
                    end

                    return true
                end
                local function listPaths()
                    local out = {}

                    if not listfiles then
                        return out
                    end

                    local function collect(dir, prefix)
                        local ok, entries = pcall(listfiles, dir)

                        if not (ok and entries) then
                            return
                        end

                        for _, entry in entries do
                            local text = tostring(entry)
                            local leaf = text:match('([^/\\]+)%.json$')

                            if leaf then
                                table.insert(out, prefix .. leaf)
                            elseif prefix == '' and isfolder and isfolder(text) then
                                local folder = text:match('([^/\\]+)$')

                                if folder and folder:lower() ~= 'lua' then
                                    collect(dir .. '/' .. folder, folder .. '/')
                                end
                            end
                        end
                    end

                    collect(PATH_DIR, '')
                    table.sort(out, function(a, b)
                        return a:lower() < b:lower()
                    end)

                    return out
                end

                local rootPos = Character.rootPos

                local function createPoint(waitForTrinket)
                    local pos = rootPos()

                    if not pos then
                        Notify.say('No character to record from')

                        return
                    end

                    pushHistory(trinket_bot)
                    table.insert(trinket_bot.path_points, {
                        position = pos,
                        wait_for_trinket = waitForTrinket or false,
                        wait_time = tonumber(Options.PointWaitTime.Value) or 0,
                    })
                    updateVisualizations()

                    if pathEditor then
                        pathEditor:Refresh()
                    end
                end

                local firesignal = firesignal
                local replicatesignal = replicatesignal
                local getconnections = getconnections
                local nearestModelNamed = NPC.nearestModel
                local resolvePath

                local function findNPCNamed(name)
                    local pos = rootPos() or Vector3.zero

                    return nearestModelNamed(Workspace:FindFirstChild('NPCs'), name, pos) or nearestModelNamed(Workspace:FindFirstChild('Live'), name, pos)
                end

                local innFallGuarded, innKillGuarded = false, false

                local function innGuardOn(seconds)
                    if not innFallGuarded and not (Toggles.NoFall and Toggles.NoFall.Value) then
                        innFallGuarded = true
                        ctx.State.noFallUntil = tick() + (seconds or 6)
                    end
                    if not innKillGuarded and ctx.State.setKillbricks and not (Toggles.NoKillBricks and Toggles.NoKillBricks.Value) then
                        innKillGuarded = true

                        pcall(ctx.State.setKillbricks, true)
                    end
                end
                local function innGuardOff()
                    if innFallGuarded then
                        innFallGuarded = false
                        ctx.State.noFallUntil = 0
                    end
                    if innKillGuarded then
                        innKillGuarded = false

                        pcall(ctx.State.setKillbricks, false)
                    end
                end

                function setInnAction(name)
                    if not name or name == '' then
                        botLog('Set Inn: no inn name set on this point')

                        return false
                    end
                    if not NPC.innKeeper(name) then
                        botLog(
[[Set Inn: no '%s' keeper here, the bot has to already be in that town]], tostring(name))

                        return false
                    end

                    botLog('Set Inn -> %s', tostring(name))
                    innGuardOn(120)

                    local binding = true

                    task.spawn(function()
                        while binding do
                            trinket_bot.expectedDeathUntil = tick() + EXPECTED_DEATH_WINDOW
                            trinket_bot.spawnShieldUntil = tick() + SPAWN_SHIELD_GRACE

                            task.wait(1)
                        end
                    end)

                    local ok = NPC.setInn(name, {
                        shouldRun = function()
                            return trinket_bot.path_running
                        end,
                        breakJoints = true,
                        attempts = 4,
                    })

                    binding = false

                    innGuardOff()
                    botLog('Set Inn %s: %s', ok and 'done' or 'failed', tostring(name))

                    return ok
                end
                function talkToAction(npcName, choices, atPos, holdName)
                    if not npcName or npcName == '' then
                        botLog('Talk: no NPC or path set on this point')

                        return false
                    end

                    local raw = tostring(choices or ''):match('^%s*(.-)%s*$')
                    local answerAll = raw:lower() == 'all'
                    local picks = {}

                    if not answerAll then
                        local compact = raw:gsub('%s', '')

                        if compact ~= '' and compact:gsub('%[%d+%]', ''):gsub('[,|]', '') == '' then
                            for position in compact:gmatch('%[(%d+)%]')do
                                table.insert(picks, {
                                    index = tonumber(position),
                                })
                            end
                        else
                            for part in raw:gmatch('[^|]+')do
                                local trimmed = part:match('^%s*(.-)%s*$')
                                local position = trimmed:match('^%[(%d+)%]$')

                                if position then
                                    table.insert(picks, {
                                        index = tonumber(position),
                                    })
                                elseif trimmed ~= '' then
                                    table.insert(picks, trimmed)
                                end
                            end
                        end
                    end
                    if not answerAll and #picks == 0 then
                        answerAll = true
                    end
                    if atPos then
                        SmoothTeleport(atPos)
                        task.wait(0.2)
                    end

                    local npc = resolvePath(npcName) or findNPCNamed(npcName)

                    if not npc then
                        botLog(
[[Talk: nothing found for '%s', try the ClickDetector path instead of a name]], tostring(npcName))

                        return false
                    end

                    botLog('Talk -> %s (%s)', tostring(npcName), answerAll and 'all choices' or (#picks .. ' choice(s)'))

                    local holding = tostring(holdName or ''):match('^%s*(.-)%s*$')
                    local wasTool = path_tool
                    local beforeAnswer

                    if holding ~= '' then
                        path_tool = nil
                        trinket_bot.talkHold = true

                        local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                        if hum then
                            hum:UnequipTools()
                        end
                        if not findTool(holding) then
                            botLog("Talk: no '%s' in the backpack to hold", holding)
                        end

                        beforeAnswer = function()
                            local tool = findTool(holding)
                            local h = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                            if tool and h and tool.Parent ~= LocalPlayer.Character then
                                h:EquipTool(tool)
                            end

                            path_tool = tool and tool.Name or path_tool
                        end
                    end

                    local ok, result = pcall(Dialogue.run, npc, picks, {
                        answerAll = answerAll,
                        beforeAnswer = beforeAnswer,
                        shouldRun = function()
                            return trinket_bot.path_running
                        end,
                        openWait = 0.8,
                        log = function(m)
                            botLog('%s', m)
                        end,
                    })

                    if holding ~= '' then
                        trinket_bot.talkHold = nil
                        path_tool = wasTool
                    end
                    if not ok then
                        botLog('Talk: %s', tostring(result))
                    end

                    return ok and result
                end
                function resolvePath(path)
                    local text = tostring(path or ''):match('^%s*(.-)%s*$')

                    if text == '' then
                        return nil
                    end

                    local node, pos
                    local service, after = text:match('^game:GetService%(%s*["\']([^"\']+)["\']%s*%)()')

                    if service then
                        node, pos = Services[service], after
                    else
                        local head, headEnd = text:match('^([%a_][%w_]*)()')

                        if not head then
                            return nil
                        end

                        local lower = head:lower()

                        node = (lower == 'game' and game) or (lower == 'workspace' and Workspace) or Workspace:FindFirstChild(head)
                        pos = headEnd
                    end
                    if not node then
                        return nil
                    end

                    while pos <= #text do
                        local name, nextPos = text:match('^%.([%w_%s]+)()', pos)

                        if not name then
                            name, nextPos = text:match('^%[%s*["\']([^"\']+)["\']%s*%]()', pos)
                        end
                        if not name then
                            break
                        end

                        name = name:match('^%s*(.-)%s*$')

                        local ok, child = pcall(function()
                            return node:FindFirstChild(name)
                        end)

                        if not (ok and child) then
                            return nil
                        end

                        node, pos = child, nextPos
                    end

                    return node
                end
                function clickAction(target)
                    local node = resolvePath(target)

                    if not node then
                        botLog("Click: could not resolve '%s'", tostring(target))

                        return false
                    end

                    local detector = node:IsA('ClickDetector') and node or node:FindFirstChildWhichIsA('ClickDetector') or node:FindFirstChildWhichIsA('ClickDetector', true)

                    if not detector then
                        botLog("Click: no ClickDetector under '%s'", tostring(target))

                        return false
                    end
                    if not fireclickdetector then
                        botLog('Click: fireclickdetector missing on this executor')

                        return false
                    end

                    local holder = detector.Parent
                    local part = holder and ((holder:IsA('BasePart') and holder) or holder:FindFirstChild('HumanoidRootPart') or holder:FindFirstChildWhichIsA('BasePart'))
                    local char = LocalPlayer.Character
                    local hrp = char and char:FindFirstChild('HumanoidRootPart')
                    local reach = detector.MaxActivationDistance
                    local away = (part and hrp) and (part.Position - hrp.Position).Magnitude or
-1
                    local stubborn, scan, hops = false, detector, 0

                    while scan and hops < 4 do
                        if CLICK_STUBBORN[scan.Name] then
                            stubborn = true

                            break
                        end

                        scan, hops = scan.Parent, hops + 1
                    end

                    local listener = stubborn and Dialogue.listen() or nil
                    local stand = stubborn and part ~= nil and hrp ~= nil and reach > 0 and away > reach

                    botLog('Click -> %s (%.0f studs away, reach %.0f%s)', detector:GetFullName(), away, reach, stubborn and ', burst' or '')

                    if stand then
                        botLog('Click: out of reach, standing on it to fire')
                    end

                    for _ = 1, (stubborn and 10 or 1)do
                        if not trinket_bot.path_running or not (hrp and hrp.Parent) then
                            break
                        end
                        if stand and part.Parent then
                            hrp.CFrame = part.CFrame
                        end

                        pcall(fireclickdetector, detector)
                        task.wait(0.1)
                    end

                    if stubborn then
                        if Captcha.available() then
                            local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                            local solved, detail = pg and Captcha.solveGui(pg, CAPTCHA_WATCH)

                            botLog('Click: captcha %s (%s)', solved and 'solved' or 'not solved', tostring(detail))

                            if solved then
                                trinket_bot.captchaSolvedAt = tick()
                            end
                        end

                        checkCastleReply(listener)
                    end

                    return true
                end

                local function dropRemote()
                    return Remotes.getRemote('PlaceTool') or Remotes.getRemote('Drop')
                end
                local function moneyRemote()
                    return Remotes.getRemote('PlaceMoney') or Remotes.getRemote('MoneyBag')
                end
                local function callRemote(remote, arg)
                    local ok = pcall(function()
                        remote:InvokeServer(arg)
                    end)

                    if not ok then
                        pcall(function()
                            remote:FireServer(arg)
                        end)
                    end
                end

                function dropAction(value)
                    local text = tostring(value or ''):match('^%s*(.-)%s*$')

                    if text == '' then
                        botLog('Drop: no tool or amount set on this point')

                        return false
                    end

                    local tool = findTool(text)

                    if tool then
                        local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                        if hum and tool.Parent ~= LocalPlayer.Character then
                            hum:EquipTool(tool)
                            task.wait(0.35)
                        end

                        local held = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(tool.Name)
                        local remote = dropRemote()

                        if not (remote and held) then
                            botLog('Drop: %s', remote and 'tool never reached the character' or 'no drop remote on this realm')

                            return false
                        end

                        botLog('Drop -> %s', text)
                        callRemote(remote, held)

                        return true
                    end

                    local silver = tonumber(text)

                    if not (silver and silver >= 1 and silver <= 10000) then
                        botLog("Drop: no tool called '%s' and it is not a silver amount", text)

                        return false
                    end

                    local remote = moneyRemote()

                    if not remote then
                        botLog('Drop: no money remote on this realm')

                        return false
                    end

                    botLog('Drop -> %d silver', silver)
                    callRemote(remote, silver)

                    return true
                end
                function walkToAction(target)
                    if not target or not waitForSpawn() then
                        return false
                    end

                    local waited = 0

                    while trinket_bot.path_running and waited < WALK_TIMEOUT do
                        local char = LocalPlayer.Character
                        local root = char and char:FindFirstChild('HumanoidRootPart')

                        if root and (root.Position - target).Magnitude < 6 then
                            return true
                        end

                        local hum = char and char:FindFirstChildOfClass('Humanoid')

                        if hum then
                            hum:MoveTo(target)
                        end

                        task.wait(0.2)

                        waited += 0.2
                    end

                    botLog('Walk To: never reached the point in %ds', WALK_TIMEOUT)

                    return false
                end
                function menuTeleAction(fallback, text)
                    local target = teleportTarget(text) or fallback

                    if not target then
                        botLog('Menu TP: could not read a destination from %q', tostring(text))

                        trinket_bot.menuTeleFailed = tostring(text or '')

                        return false
                    end

                    waitOutDanger()

                    local teleporting = true

                    task.spawn(function()
                        while teleporting do
                            trinket_bot.expectedDeathUntil = tick() + EXPECTED_DEATH_WINDOW
                            trinket_bot.spawnShieldUntil = tick() + SPAWN_SHIELD_GRACE

                            task.wait(1)
                        end
                    end)

                    local ok = Menu.menuTele(target, function()
                        return trinket_bot.path_running and not trinket_bot.moderator_detected
                    end)

                    teleporting = false

                    local where = string.format('%.0f, %.0f, %.0f', target.X, target.Y, target.Z)

                    botLog('Menu TP %s -> %s', ok and 'landed' or 'failed', where)

                    if ok then
                        MemStore.remove(MENUTELE_FAIL)
                    elseif trinket_bot.path_running and not trinket_bot.stopped then
                        trinket_bot.menuTeleFailed = where
                    end

                    return ok
                end
                function wipeAction()
                    while trinket_bot.path_running do
                        local remaining = tonumber(getStat('Lives'))

                        if remaining and remaining <= 0 then
                            botLog('Wipe: out of lives')

                            return true
                        end

                        local char = LocalPlayer.Character
                        local hrp = char and char:FindFirstChild('HumanoidRootPart')

                        if hrp then
                            SmoothTeleport(hrp.Position - Vector3.new(0, 20, 0))
                            task.wait(0.4)
                        end

                        trinket_bot.expectedDeathUntil = tick() + EXPECTED_DEATH_WINDOW
                        trinket_bot.spawnShieldUntil = tick() + SPAWN_SHIELD_GRACE

                        botLog('Wipe: killing (%s lives left)', tostring(remaining or '?'))
                        pcall(Character.kill)

                        local waited = 0

                        while waited < 12 and trinket_bot.path_running do
                            local ch = LocalPlayer.Character
                            local hum = ch and ch:FindFirstChildOfClass('Humanoid')

                            if not ch or not hum or hum.Health <= 0 then
                                break
                            end

                            task.wait(0.2)

                            waited += 0.2
                        end

                        local respawned = 0

                        while respawned < 30 and trinket_bot.path_running do
                            local ch = LocalPlayer.Character
                            local hum = ch and ch:FindFirstChildOfClass('Humanoid')

                            if ch and hum and hum.Health > 0 and ch:FindFirstChild('HumanoidRootPart') then
                                break
                            end

                            task.wait(0.5)

                            respawned += 0.5
                        end

                        task.wait(1)
                    end

                    return false
                end

                local affectedBricks = {}
                local affectedCollide = {}
                local beds

                local function bedsOff(off)
                    if not IS_KHEI then
                        return
                    end
                    if not beds then
                        beds = {}

                        for _, v in Workspace:GetDescendants()do
                            if v.Name == 'Bed' and v:IsA('BasePart') then
                                beds[v] = v.CanTouch
                            end
                        end
                    end

                    for v, was in beds do
                        if v.Parent then
                            v.CanTouch = not off and was
                        end
                    end
                end

                ctx.Maid:Give(LocalPlayer.CharacterAdded:Connect(function()
                    if MemStore.get('botstarted') == 'true' then
                        bedsOff(true)
                    end
                end))
                ctx.Maid:Give(function()
                    bedsOff(false)
                end)

                local ExecutePath, stopBot, stopButton

                local function setStopVisible(v)
                    if stopButton and stopButton.Holder then
                        stopButton.Holder.Visible = v == true
                    end
                    if pathEditor and pathEditor.SetRunning then
                        pathEditor:SetRunning(v == true)
                    end
                end
                local function botBusy()
                    return trinket_bot.hopCommitted == true or trinket_bot.combatEscape == true or trinket_bot.escaping == true or state.fimbulEscape == true
                end

                local visitedPositions = {}
                local markCollected = BASIL_NO_VIRTUALIZE(function(id)
                    if state.collectedIds[id] then
                        return
                    end

                    state.collectedIds[id] = true

                    local order = trinket_bot.collected_order

                    table.insert(order, id)

                    while#order > 1000 do
                        state.collectedIds[table.remove(order, 1)] = nil
                    end
                end)
                local alreadyVisited = BASIL_NO_VIRTUALIZE(function(pos)
                    for _, v in visitedPositions do
                        if (pos - v).Magnitude < 5 then
                            return true
                        end
                    end

                    return false
                end)
                local recordVisited = BASIL_NO_VIRTUALIZE(function(pos)
                    table.insert(visitedPositions, pos)

                    while#visitedPositions > 1000 do
                        table.remove(visitedPositions, 1)
                    end
                end)

                local function hostileMod(player)
                    if allyOf and allyOf(player) and not (ctx.State.isAvoided and ctx.State.isAvoided(player)) then
                        return false
                    end

                    return ctx.State.isModerator and ctx.State.isModerator(player) or false
                end

                local identify = BASIL_NO_VIRTUALIZE(function(obj)
                    local fn = ctx.State.identifyTrinket

                    if fn then
                        local ok, name, color, zindex = pcall(fn, obj)

                        if ok then
                            return name, color, zindex
                        end
                    end

                    return nil, nil, nil
                end)
                local shouldPickup = BASIL_NO_VIRTUALIZE(function(name, zindex)
                    if not name then
                        return false
                    end
                    if name == 'Azael Horn' or name == 'Phoenix Down' or name == 'Phoenix Flower' then
                        return Options.PickupMythicsArtifacts.Value[name] == true
                    end
                    if name == 'Ice Essence' then
                        return Toggles.PickupIceEssence.Value
                    end
                    if name:find('Scroll') then
                        return Toggles.PickupScrolls.Value
                    end
                    if zindex == 6 or zindex == 5 then
                        return Options.PickupMythicsArtifacts.Value[name] == true
                    elseif zindex == 4 then
                        return Toggles.PickupEventItems.Value
                    elseif zindex == 2 or zindex == 3 then
                        return Toggles.PickupTrinkets.Value or (Options.PickupTrinketTypes and Options.PickupTrinketTypes.Value[name] == true)
                    end

                    return false
                end)

                function waitOutDanger()
                    local char = LocalPlayer.Character

                    if not (char and CollectionService:HasTag(char, 'Danger')) then
                        return
                    end

                    botLog('Holding until the Danger tag drops')

                    repeat
                        char = LocalPlayer.Character

                        while char and CollectionService:HasTag(char, 'Danger') do
                            RunService.Heartbeat:Wait()

                            char = LocalPlayer.Character
                        end

                        task.wait(0.5)

                        char = LocalPlayer.Character
                    until not (char and CollectionService:HasTag(char, 'Danger'))

                    botLog('Danger clear')
                end
                function captureSettings()
                    local data = {
                        toggles = {},
                        options = {},
                        multi = {},
                    }

                    for _, k in SETTING_TOGGLES do
                        if Toggles[k] then
                            data.toggles[k] = Toggles[k].Value
                        end
                    end
                    for _, k in SETTING_OPTIONS do
                        if Options[k] then
                            data.options[k] = Options[k].Value
                        end
                    end
                    for _, k in SETTING_MULTI do
                        if Options[k] then
                            data.multi[k] = Options[k].Value
                        end
                    end

                    data.detectionsSeen = table.clone(BOT_DETECTIONS)

                    return data
                end

                local function withNewDetections(picked, seen)
                    local known = table.clone(DETECTIONS_BEFORE_SEEN)

                    if type(seen) == 'table' then
                        known = {}

                        for _, label in seen do
                            known[label] = true
                        end
                    end

                    local out = {}

                    for k, v in picked do
                        if type(k) == 'number' then
                            out[v] = true
                        elseif v then
                            out[k] = true
                        end
                    end
                    for old, new in Threats.RENAMED_LABELS do
                        if known[old] then
                            known[new] = true
                        end
                        if out[old] then
                            out[new] = true
                        end

                        out[old] = nil
                    end
                    for _, label in BOT_DETECTIONS do
                        if not known[label] then
                            out[label] = true
                        end
                    end

                    return out
                end

                function applySettings(data)
                    if type(data) ~= 'table' then
                        return
                    end

                    for k, v in data.toggles or {}do
                        if Toggles[k] then
                            Toggles[k]:SetValue(v)
                        end
                    end
                    for k, v in data.options or {}do
                        if Options[k] then
                            Options[k]:SetValue(v)
                        end
                    end
                    for k, v in data.multi or {}do
                        if Options[k] and type(v) == 'table' then
                            Options[k]:SetValue(k == 'BotDetections' and withNewDetections(v, data.detectionsSeen) or v)
                        end
                    end
                end
                function importHydroxideSettings(s)
                    local function setT(idx, v)
                        if Toggles[idx] then
                            pcall(function()
                                Toggles[idx]:SetValue(v)
                            end)
                        end
                    end
                    local function setO(idx, v)
                        if Options[idx] then
                            pcall(function()
                                Options[idx]:SetValue(v)
                            end)
                        end
                    end

                    setT('SkipIllusionist', s.skip_illusionist or false)
                    setT('PickupScrolls', s.pickup_scrolls or false)
                    setT('PickupIceEssence', s.pickup_ice_essence or false)

                    if Options.PickupMythicsArtifacts then
                        local val = s.pickup_mythics_artifacts

                        if type(val) ~= 'table' then
                            val = val and {
                                ['Rift Gem'] = true,
                                ['Mysterious Artifact'] = true,
                                ['Phoenix Flower'] = true,
                                ['Azael Horn'] = true,
                                ['Amulet of the White King'] = true,
                                ['Lannis Amulet'] = true,
                                ['Phoenix Down'] = true,
                                ['Night Stone'] = true,
                                ['Howler Friend'] = true,
                            } or {}
                        end
                        if s.pickup_phoenix_down then
                            val['Phoenix Down'] = true
                            val['Phoenix Flower'] = true
                        end
                        if s.pickup_azael_horn then
                            val['Azael Horn'] = true
                        end

                        setO('PickupMythicsArtifacts', val)
                    end

                    setT('PickupEventItems', s.pickup_event_items or false)
                    setT('PickupTrinkets', s.pickup_trinkets or false)
                    setT('DisableGPURendering', s.disable_gpu_rendering or false)

                    local hopConds = s.emergency_serverhop_conditions or {}
                    local detections = {}

                    for _, label in BOT_DETECTIONS do
                        if label ~= 'Perflora' or hopConds.Perflora == true then
                            table.insert(detections, label)
                        end
                    end

                    setO('BotDetections', detections)
                    setT('JoinOldestServer', s.join_oldest_server or false)
                    setT('AutoPopPDs', s.auto_pop_pds or false)
                    setO('AutoDropItems', s.auto_drop_items or {})
                    setT('KickOnTrinket', s.kick_on_trinket or false)
                    setO('KickTrinketList', s.kick_trinket_list or {})
                    setT('StayInServer', s.stay_in_server or false)
                    setO('TimeBetweenLooting', s.time_between_looting or 5)
                    setO('ProximityCheck', s.proximity_check or 0)
                    setO('CriticalDistance', s.critical_distance or 60)
                    setO('MinPlayerCount', s.min_player_count or 0)
                    setO('TrinketBotSpeed', s.speed or 100)
                end

                local function getServerInfo()
                    local name, region = '', ''
                    local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                    local gui = pg and pg:FindFirstChild('ServerStatsGui')
                    local frame = gui and gui:FindFirstChild('Frame')
                    local stats = frame and frame:FindFirstChild('Stats')

                    if stats then
                        local sn = stats:FindFirstChild('ServerName')

                        if sn then
                            name = sn.Text:match('Server Name: (.+)') or ''
                        end

                        local sr = stats:FindFirstChild('ServerRegion')

                        if sr then
                            region = sr.Text:match('Server Region: (.+)') or ''
                        end
                    end

                    return name, region
                end
                local function getInventoryValue()
                    local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                    if not bp then
                        return 0
                    end

                    local total = 0

                    for _, child in bp:GetChildren()do
                        local sv = child:FindFirstChild('SilverValue')

                        if sv then
                            total += sv.Value
                        end
                    end

                    return total
                end
                local function richEmbed(title, color)
                    local serverName, serverRegion = getServerInfo()
                    local elapsed = trinket_bot.session_start_time > 0 and (tick() - trinket_bot.session_start_time) or 0
                    local hours = math.floor(elapsed / 3600)
                    local minutes = math.floor((elapsed % 3600) / 60)
                    local seconds = math.floor(elapsed % 60)
                    local itemsText = ''

                    if next(trinket_bot.session_loot) then
                        local items = {}

                        for name, count in trinket_bot.session_loot do
                            table.insert(items, {
                                name = name,
                                count = count,
                            })
                        end

                        table.sort(items, function(a, b)
                            return a.count > b.count
                        end)

                        for _, item in items do
                            itemsText = itemsText .. string.format('%dx %s\n', item.count, item.name)
                        end
                    else
                        itemsText = 'No items collected'
                    end

                    local fields = {
                        {
                            name = 'Items Collected',
                            value = string.format('```\n%s```', itemsText),
                            inline = false,
                        },
                    }
                    local aaCount = AAGun.count()

                    if aaCount > 0 then
                        local at = AAGun.lastAt()

                        table.insert(fields, {
                            name = 'AA Guns',
                            value = string.format('%d in the last 24h', aaCount) .. (at and string.format('\nlast <t:%d:R>', at) or ''),
                            inline = true,
                        })
                    end

                    local playerCount = #Players:GetPlayers()
                    local footerText

                    if Webhook.config.showUsername then
                        footerText = string.format('Players: %d/23 | %s | Job: %s', playerCount, LocalPlayer.Name, game.JobId)
                    else
                        footerText = string.format('Players: %d/23 | Job: %s', playerCount, game.JobId)
                    end

                    return {
                        title = title,
                        description = string.format(
[[**Server:** `%s (%s)`
**Inventory Value:** %d
**Session:** %dh %dm %ds]], serverName ~= '' and serverName or 'Unknown', serverRegion ~= '' and serverRegion or 'Unknown', getInventoryValue(), hours, minutes, seconds),
                        color = color,
                        fields = fields,
                        footer = {text = footerText},
                        timestamp = os.date('!%Y-%m-%dT%H:%M:%SZ'),
                    }
                end

                local setupBackpackMonitoring
                local recoverWedge
                local threatMaid = Maid.new()

                ctx.Maid:Give(threatMaid)

                local deathMaid = Maid.new()

                ctx.Maid:Give(deathMaid)

                local function deathReport(why)
                    local char = LocalPlayer.Character
                    local hrp = char and char:FindFirstChild('HumanoidRootPart')
                    local lines = {
                        '@everyone ' .. why,
                    }

                    table.insert(lines, string.format('**Area:** %s', tostring(currentAreaName() or 'unknown')))

                    if hrp then
                        local at = hrp.Position

                        table.insert(lines, string.format('**At:** %.0f, %.0f, %.0f', at.X, at.Y, at.Z))
                    end
                    if trinket_bot.current_path_name ~= '' then
                        table.insert(lines, string.format('**Path:** %s (point %d/%d)', trinket_bot.current_path_name, trinket_bot.current_index or 0, #trinket_bot.active_points))
                    end

                    table.insert(lines, string.format('**In combat:** %s', (char and CollectionService:HasTag(char, 'Danger')) and 'yes' or 'no'))

                    local hum = char and char:FindFirstChildOfClass('Humanoid')
                    local creator = hum and hum:FindFirstChild('creator')

                    if creator and creator.Value then
                        table.insert(lines, string.format('**Credited to:** %s', tostring(creator.Value.Name)))
                    end
                    if hrp then
                        local near = {}

                        for _, p in Players:GetPlayers()do
                            local ph = p ~= LocalPlayer and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                            if ph then
                                local d = (ph.Position - hrp.Position).Magnitude

                                if d <= DEATH_SCAN_RADIUS then
                                    table.insert(near, {
                                        name = p.Name,
                                        dist = d,
                                    })
                                end
                            end
                        end

                        table.sort(near, function(a, b)
                            return a.dist < b.dist
                        end)

                        local names = {}

                        for idx = 1, math.min(#near, 5)do
                            table.insert(names, string.format('%s (%.0f)', near[idx].name, near[idx].dist))
                        end

                        table.insert(lines, string.format('**Players within %d:** %s', DEATH_SCAN_RADIUS, #names > 0 and table.concat(names, ', ') or 'none'))

                        local mobs = {}
                        local live = Workspace:FindFirstChild('Live')

                        if live then
                            for _, m in live:GetChildren()do
                                if m:IsA('Model') and not Players:GetPlayerFromCharacter(m) then
                                    local r = m:FindFirstChild('HumanoidRootPart') or m.PrimaryPart
                                    local d = r and (r.Position - hrp.Position).Magnitude

                                    if d and d <= DEATH_SCAN_RADIUS then
                                        table.insert(mobs, {
                                            name = m.Name,
                                            dist = d,
                                        })
                                    end
                                end
                            end
                        end

                        table.sort(mobs, function(a, b)
                            return a.dist < b.dist
                        end)

                        local mobNames = {}

                        for idx = 1, math.min(#mobs, 6)do
                            table.insert(mobNames, string.format('%s (%.0f)', mobs[idx].name, mobs[idx].dist))
                        end

                        table.insert(lines, string.format('**Mobs within %d:** %s', DEATH_SCAN_RADIUS, #mobNames > 0 and table.concat(mobNames, ', ') or 'none'))
                    end

                    Webhook.textBounded(table.concat(lines, '\n'))
                end
                local function bindBotDeathKick(character)
                    local hum = character and (character:FindFirstChildOfClass('Humanoid') or character:WaitForChild('Humanoid', 10))

                    if not hum or LocalPlayer.Character ~= character then
                        return
                    end

                    deathMaid.died = hum.Died:Connect(function()
                        if tick() < (trinket_bot.expectedDeathUntil or 0) then
                            trinket_bot.expectedDeathUntil = 0

                            botLog("Death was the action's own, not stopping the path")

                            return
                        end

                        trinket_bot.path_running = false

                        if trinket_bot.hopping and not trinket_bot.combatEscape then
                            return
                        end
                        if MemStore.get('botstarted') == 'true' and not (Toggles.StayInServer and Toggles.StayInServer.Value) then
                            MemStore.remove('botstarted')
                            MemStore.remove('serverhop_count')
                            task.spawn(deathReport, 'bot died')
                            botKick('sentinel: bot died - stopped', 2)
                        end
                    end)
                end

                ctx.Maid:Give(LocalPlayer.CharacterAdded:Connect(bindBotDeathKick))

                if LocalPlayer.Character then
                    task.spawn(bindBotDeathKick, LocalPlayer.Character)
                end

                local function removeFromArtifactQueue(name)
                    local logs = trinket_bot.pending_artifact_logs

                    for i = #logs, 1, -1 do
                        local log = logs[i]

                        for j = #log.artifact_names, 1, -1 do
                            if log.artifact_names[j] == name then
                                table.remove(log.artifact_names, j)

                                if log.artifact_ids then
                                    table.remove(log.artifact_ids, j)
                                end
                                if log.artifact_positions and log.artifact_positions[j] then
                                    table.remove(log.artifact_positions, j)
                                end

                                break
                            end
                        end

                        if #log.artifact_names == 0 then
                            table.remove(logs, i)
                        end
                    end
                end

                local lootMaid = Maid.new()

                ctx.Maid:Give(lootMaid)

                local function logPickup(name, qty)
                    trinket_bot.session_loot[name] = (trinket_bot.session_loot[name] or 0) + (qty or 1)

                    removeFromArtifactQueue(name)
                end
                local function startLootTracking()
                    trinket_bot.session_loot = {}
                    trinket_bot.session_start_time = tick()
                    state.lootBaselines = {}

                    lootMaid:DoCleaning()

                    local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                    if not bp then
                        return
                    end

                    for _, item in bp:GetDescendants()do
                        if item:IsA('IntValue') and item.Name == 'Quantity' and item.Parent:IsA('Tool') then
                            local toolName = item.Parent.Name

                            state.lootBaselines[toolName] = item.Value

                            lootMaid:Give(item:GetPropertyChangedSignal('Value'):Connect(function(
                            )
                                if MemStore.get('botstarted') ~= 'true' then
                                    return
                                end

                                local newAmt = item.Value - (state.lootBaselines[toolName] or 0) - (trinket_bot.session_loot[toolName] or 0)

                                if newAmt > 0 then
                                    logPickup(toolName, newAmt)
                                end
                            end))
                        end
                    end

                    lootMaid:Give(bp.ChildAdded:Connect(function(child)
                        if MemStore.get('botstarted') ~= 'true' or not child:IsA('Tool') then
                            return
                        end

                        task.wait(0.5)

                        if not child:FindFirstChild('SilverValue') then
                            return
                        end

                        local toolName = child.Name

                        state.lootBaselines[toolName] = state.lootBaselines[toolName] or 0

                        logPickup(toolName)
                        task.wait(1)

                        local qty = child:FindFirstChild('Quantity')

                        if qty and qty:IsA('IntValue') then
                            lootMaid['qty_' .. toolName] = qty:GetPropertyChangedSignal('Value'):Connect(function(
                            )
                                if MemStore.get('botstarted') ~= 'true' then
                                    return
                                end

                                local newAmt = qty.Value - (state.lootBaselines[toolName] or 0) - (trinket_bot.session_loot[toolName] or 0)

                                if newAmt > 0 then
                                    logPickup(toolName, newAmt)
                                end
                            end)
                        end
                    end))
                end
                local function stopLootTracking()
                    lootMaid:DoCleaning()
                end
                local function lootedText(label)
                    local m = LootZones.minutesSince(label)

                    return m and (m .. 'm') or 'N/A'
                end
                local function nearestPathPoint(firstObject)
                    if not (trinket_bot.path_running and firstObject and #trinket_bot.path_points > 0) then
                        return nil
                    end

                    local pos = firstObject.Position
                    local nearestIdx, nearestDist = nil, math.huge

                    for i, point in trinket_bot.path_points do
                        local d = (point.position - pos).Magnitude

                        if d < nearestDist then
                            nearestDist = d
                            nearestIdx = i
                        end
                    end

                    return nearestIdx, nearestDist
                end
                local function buildArtifactDesc(
                    names,
                    firstObject,
                    area,
                    positions
                )
                    local serverName, serverRegion = getServerInfo()
                    local lines = {
                        string.format('**Artifact%s**', #names > 1 and 's' or ''),
                    }

                    for i, name in names do
                        local pos = positions and positions[i]
                        local spot = (pos and #pos == 3) and string.format(' \u{b7} `%d, %d, %d`', pos[1], pos[2], pos[3]) or ''

                        table.insert(lines, string.format('- **%s**%s', name, spot))
                    end

                    local desc = table.concat(lines, '\n') .. '\n\n'
                    local nearestIdx, nearestDist = nearestPathPoint(firstObject)

                    if nearestIdx then
                        desc = desc .. string.format('**Path:** %s\n', trinket_bot.current_path_name ~= '' and trinket_bot.current_path_name or 'None')
                        desc = desc .. string.format('**Point:** %d (%.0f studs)\n', nearestIdx, nearestDist)
                    end

                    desc = desc .. string.format('**Server:** `%s (%s)`\n\n', serverName ~= '' and serverName or 'Unknown', serverRegion ~= '' and serverRegion or 'Unknown')
                    desc = desc .. string.format('> Castle Rock: %s\n', lootedText('Castle Rock'))
                    desc = desc .. string.format('> Sunken: %s\n', lootedText('Deep Sunken'))
                    desc = desc .. string.format('> Temple of Fire: %s', lootedText('Temple of Fire'))

                    return desc
                end

                ctx.State.buildArtifactDesc = buildArtifactDesc

                local function artifactStream()
                    return ReportChannel.get('__artifactstream')
                end
                local function queueArtifactStream(
                    names,
                    ids,
                    firstObject,
                    area,
                    positions
                )
                    local stream = artifactStream()

                    if not stream then
                        return
                    end
                    if Toggles.StayInServer and Toggles.StayInServer.Value then
                        return
                    end
                    if not (trinket_bot.path_running or MemStore.get('botstarted') == 'true') then
                        return
                    end

                    local serverName, serverRegion = getServerInfo()
                    local nearestIdx, nearestDist = nearestPathPoint(firstObject)

                    positions = positions or {}

                    local item = {
                        names = names,
                        positions = positions,
                        area = area or '',
                        path = nearestIdx and trinket_bot.current_path_name or nil,
                        point = nearestIdx,
                        dist = nearestIdx and math.floor(nearestDist) or nil,
                        server = serverName,
                        region = serverRegion,
                        castle = LootZones.minutesSince('Castle Rock'),
                        sunken = LootZones.minutesSince('Deep Sunken'),
                        temple = LootZones.minutesSince('Temple of Fire'),
                        players = #Players:GetPlayers(),
                        job = game.JobId,
                        world = IS_KHEI and 'khei' or 'gaia',
                    }
                    local artifactList = table.concat(names, ', ')

                    if not (Toggles.ShowInArtifactStream and Toggles.ShowInArtifactStream.Value) then
                        item.admin, item.user, item.userId = true, LocalPlayer.Name, LocalPlayer.UserId

                        task.spawn(function()
                            local ok, status = stream({item})

                            if not ok then
                                botLog('Artifact log: not sent (%s)', tostring(status))
                            end
                        end)

                        return
                    end

                    table.insert(trinket_bot.pending_artifact_logs, {
                        item = item,
                        at = os.clock(),
                        artifact_names = names,
                        artifact_ids = ids,
                        artifact_positions = positions,
                    })

                    while#trinket_bot.pending_artifact_logs > 50 do
                        table.remove(trinket_bot.pending_artifact_logs, 1)
                    end

                    botLog('Artifact stream: queued %s (%d total)', artifactList, #trinket_bot.pending_artifact_logs)
                end

                ctx.State.queueArtifactStream = queueArtifactStream

                local function flushArtifactStream()
                    local logs = trinket_bot.pending_artifact_logs
                    local stream = artifactStream()

                    if not stream or #logs == 0 then
                        return
                    end

                    local items = {}

                    for _, log in logs do
                        if log.item and #log.artifact_names > 0 then
                            log.item.age = math.floor(os.clock() - log.at)

                            table.insert(items, log.item)
                        end
                    end

                    trinket_bot.pending_artifact_logs = {}

                    if #items == 0 then
                        return
                    end

                    botLog('Artifact stream: flushing %d log(s) before serverhop', #items)
                    task.spawn(function()
                        local ok, status = stream(items)

                        if not ok then
                            botLog('Artifact stream: not sent (%s)', tostring(status))
                        end
                    end)
                end

                local leaveToMenu
                local safeServerhop

                local function hopStrategy()
                    if Toggles.JoinOldestServer and Toggles.JoinOldestServer.Value then
                        return 'oldest'
                    elseif Toggles.JoinSmallestServer and Toggles.JoinSmallestServer.Value then
                        return 'smallest'
                    elseif Toggles.JoinLargestServer and Toggles.JoinLargestServer.Value then
                        return 'largest'
                    end

                    return 'random'
                end

                function trinketBotServerhop(
                    reason,
                    keepPosition,
                    routine,
                    awayFrom
                )
                    if trinket_bot.stopped or trinket_bot.test_mode or (Toggles.StayInServer and Toggles.StayInServer.Value) or trinket_bot.hopCommitted or trinket_bot.combatEscape then
                        if not trinket_bot.combatEscape then
                            trinket_bot.escaping = false
                        end

                        return
                    end

                    trinket_bot.hopCommitted = true
                    trinket_bot.hopping = true

                    botLog('Serverhop: %s', tostring(reason))
                    flushArtifactStream()

                    trinket_bot.path_running = false

                    setStopVisible(true)

                    if trinket_bot.current_path_name ~= '' then
                        MemStore.set('trinket_bot_path', trinket_bot.current_path_name)
                        MemStore.setJSON('trinket_bot_settings', captureSettings())
                    end
                    if not keepPosition then
                        MemStore.remove('lastPlayerPosition')
                    end

                    local escaped = escapeCombat(reason, awayFrom)

                    if trinket_bot.stopped then
                        return
                    end
                    if escaped == 'dead' then
                        botKick('sentinel: died getting away from a fight (' .. tostring(reason) .. ')', 2)

                        return
                    end

                    local plain = reason and (reason:lower():find('repeat encounter') or reason:lower():find('unfriendly'))
                    local embed

                    if not plain then
                        local count = (tonumber(MemStore.get('serverhop_count')) or 0) + 1

                        embed = richEmbed(string.format('Serverhop #%d | %s', count, tostring(reason or 'Serverhop')), routine and 0x36ff79 or 0xff6b6b)
                    end

                    local airborne = not isGrounded()

                    if airborne then
                        botLog('Serverhop: airborne, joining without menuing')
                    else
                        leaveToMenu()
                    end
                    if plain then
                        Webhook.text(reason)
                    else
                        Webhook.embed(embed)
                    end

                    local hopOpts = {
                        strategy = hopStrategy(),
                        menuWait = not airborne,
                        minPlayers = (Options.MinPlayerCount and Options.MinPlayerCount.Value) or 0,
                        sizeFallback = true,
                        avoid = (Toggles.AvoidOtherBots == nil or Toggles.AvoidOtherBots.Value) and BotClaims.takenJobs() or nil,
                        onPick = BotClaims.claim,
                        cancelled = function()
                            return trinket_bot.stopped
                        end,
                        onDanger = function()
                            if not trinket_bot.stopped then
                                return escapeCombat('tagged mid hop')
                            end
                        end,
                    }
                    local ok, _, why = Serverhop.hop(hopOpts)
                    local rounds = 0

                    while not ok and not trinket_bot.stopped and not state.unloaded and why ~= 'died in a fight mid hop' do
                        rounds += 1

                        botLog(
[[Serverhop failed (%s) - clearing the visited list and going again]], tostring(why))

                        if rounds == 2 then
                            Webhook.textBounded(
[[Serverhop keeps failing, retrying every 30s until it gets in. Last reason: ]] .. tostring(why))
                        end

                        Serverhop.clearVisited()

                        if rounds > 1 then
                            for _ = 1, 30 do
                                if trinket_bot.stopped or state.unloaded then
                                    return
                                end

                                task.wait(1)
                            end
                        end

                        hopOpts.avoid = (Toggles.AvoidOtherBots == nil or Toggles.AvoidOtherBots.Value) and BotClaims.takenJobs() or nil
                        ok, _, why = Serverhop.hop(hopOpts)
                    end

                    if not ok and not trinket_bot.stopped and why == 'died in a fight mid hop' then
                        botKick('sentinel: died getting away from a fight mid hop', 2)
                    end
                end

                local function handleRelocateFail(label, where)
                    trinket_bot.path_running = false

                    if Toggles.StayInServer and Toggles.StayInServer.Value then
                        MemStore.remove(MENUTELE_FAIL)
                        Webhook.embedWith('@everyone', richEmbed(label .. ' - path stopped', 0xed4245))
                        stopBot()

                        return
                    end
                    if MemStore.get(MENUTELE_FAIL) == where then
                        MemStore.remove(MENUTELE_FAIL)
                        Webhook.embedWith('@everyone', richEmbed(label .. ' again after a hop - kicking', 0xed4245))
                        stopBot()
                        waitOutDanger()
                        leaveToMenu()
                        botKick('sentinel: ' .. label)

                        return
                    end

                    MemStore.set(MENUTELE_FAIL, where)
                    trinketBotServerhop(label .. ' - restarting the path')
                end
                local function handleMenuTeleFail(where)
                    trinket_bot.menuTeleFailed = nil

                    handleRelocateFail('Menu TP to ' .. tostring(where) .. ' failed', where)
                end
                local function preGateCritical()
                    local critical = Options.CriticalDistance.Value

                    if critical <= 0 or tick() < (trinket_bot.spawnGraceUntil or 0) then
                        return false
                    end

                    local char = LocalPlayer.Character
                    local hrp = char and char:FindFirstChild('HumanoidRootPart')

                    if not hrp then
                        return false
                    end

                    local near, who = isPlayerNear(hrp.Position, critical)

                    if not near then
                        return false
                    end

                    trinket_bot.path_running = false

                    local msg = string.format(
[[%s within critical distance pre-gate - serverhopping instead of gating]], tostring(who))

                    botLog('%s', msg)
                    Notify.say(msg)
                    trinketBotServerhop(msg)

                    return true
                end
                local function awaitGround(seconds)
                    local deadline = tick() + (seconds or 1.5)

                    while not isGrounded() and tick() < deadline and trinket_bot.path_running do
                        task.wait(0.1)
                    end

                    return isGrounded()
                end
                local function settleOnGround(fromIndex, threat)
                    if awaitGround() then
                        return true
                    end

                    local pts = trinket_bot.active_points
                    local base = tonumber(fromIndex) or 0

                    if not pts[base] then
                        return isGrounded()
                    end

                    local step = pts[base].is_gate_point and -1 or 1

                    if threat then
                        local function clearance(dir)
                            local worst, seen = math.huge, 0

                            for n = 1, GROUND_WALK_STEPS do
                                local pt = pts[base + dir * n]

                                if not pt or pt.is_gate_point then
                                    break
                                end

                                seen += 1

                                worst = math.min(worst, (pt.position - threat).Magnitude)
                            end

                            return seen > 0 and worst or -1
                        end

                        if clearance(-1) > clearance(1) then
                            step = -1
                        end
                    end

                    for _, dir in {
                        step,
                        -step,
                    }do
                        local idx, walked = base + dir, 0

                        while walked < GROUND_WALK_STEPS and trinket_bot.path_running do
                            local pt = pts[idx]

                            if not pt or pt.is_gate_point or (pt.action and RELOCATING_ACTIONS[pt.action]) then
                                break
                            end

                            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                            if not hrp then
                                break
                            end
                            if not pt.action then
                                if (pt.position - hrp.Position).Magnitude > TELEPORT_CAP then
                                    break
                                end

                                walked += 1

                                botLog('Gate: airborne, walking %s to point %d for solid ground', dir > 0 and 'on' or 'back', idx)
                                SmoothTeleport(pt.position)

                                if awaitGround(2) then
                                    return true
                                end
                            end

                            idx += dir
                        end
                    end

                    return isGrounded()
                end
                local function gateStabilized(
                    location,
                    expectedDest,
                    fromIndex,
                    threat
                )
                    if not settleOnGround(fromIndex, threat) then
                        botLog(
[[Gate: still airborne after walking the path - holding the gate rather than wasting it midair]])

                        return false
                    end

                    local ok = Gate(location, expectedDest)

                    trinket_bot.gatingUntil = 0

                    if ok then
                        state.current_gate_section += 1

                        table.clear(state.proximity_warnings)
                    end

                    return ok
                end
                local function forceFieldStrip()
                    local char = LocalPlayer.Character

                    if not (char and char:FindFirstChildOfClass('ForceField')) then
                        return
                    end

                    local hrp = char:FindFirstChild('HumanoidRootPart')

                    if not hrp then
                        return
                    end

                    local startPos = hrp.Position
                    local platform = Make('Part', {
                        Size = Vector3.new(7, 1, 7),
                        Position = startPos + Vector3.new(0, -3, 18),
                        Anchored = true,
                        CanCollide = true,
                        Transparency = 1,
                        Parent = Workspace,
                    })

                    SmoothTeleport(platform.Position + Vector3.new(0, 4, 0))
                    task.wait(1.5)
                    pcall(function()
                        platform:Destroy()
                    end)
                    SmoothTeleport(startPos)
                    task.wait(0.5)
                end

                local detectShrieker = Threats.detectShrieker
                local shriekersIgnored = BASIL_NO_VIRTUALIZE(function()
                    return inShriekerZone() or not Threats.labelAllowed(Options, 'Shrieker Check')
                end)
                local pathHasGates = BASIL_NO_VIRTUALIZE(function()
                    for _, pt in trinket_bot.path_points do
                        if pt.is_gate_point then
                            return true
                        end
                    end

                    return false
                end)
                local gateExpectedDest = BASIL_NO_VIRTUALIZE(function(
                    gateIndex
                )
                    local nxt = trinket_bot.active_points[gateIndex + 1]

                    return nxt and nxt.position or nil
                end)
                local CONDITION_VARS = {
                    {
                        label = 'Day',
                        unit = '',
                        default = 1,
                        get = function()
                            local cached = ctx.State.currentDay

                            return tonumber(cached and cached() or Remotes.getServerValue('DaysSurvived'))
                        end,
                    },
                    {
                        label = 'Players In Server',
                        unit = '',
                        default = 1,
                        get = function()
                            return #Players:GetPlayers()
                        end,
                    },
                    {
                        label = 'Backpack',
                        unit = '',
                        text = true,
                        ops = {
                            'has',
                            'missing',
                        },
                        test = function(op, value)
                            local name = tostring(value or ''):match('^%s*(.-)%s*$')

                            if name == '' then
                                return true
                            end

                            local found = findTool(name) ~= nil

                            return op == 'missing' and not found or (op ~= 'missing' and found)
                        end,
                    },
                    {
                        label = 'Position',
                        unit = '',
                        text = true,
                        ops = {
                            'near',
                            'far',
                        },
                        test = function(op, value)
                            local root = Character.root()

                            if not root then
                                return true
                            end

                            local nums = {}

                            for n in tostring(value or ''):gmatch('-?%d+%.?%d*')do
                                table.insert(nums, tonumber(n))
                            end

                            if #nums < 3 then
                                return true
                            end

                            local away = (root.Position - Vector3.new(nums[1], nums[2], nums[3])).Magnitude
                            local within = away <= (nums[4] or 25)

                            return op == 'far' and not within or (op ~= 'far' and within)
                        end,
                    },
                    {
                        label = 'Height',
                        unit = 'y',
                        default = 140,
                        get = function()
                            local root = Character.root()

                            return root and root.Position.Y or nil
                        end,
                    },
                    {
                        label = 'Backpack Count',
                        unit = '',
                        text = true,
                        ops = {
                            '>=',
                            '<=',
                        },
                        test = function(op, value)
                            local name, want = tostring(value or ''):match('^%s*(.-)%s+(%d+)%s*$')

                            if not name or name == '' then
                                return true
                            end

                            local needle, count = name:lower(), 0

                            for _, container in {
                                LocalPlayer:FindFirstChildOfClass('Backpack'),
                                LocalPlayer.Character,
                            }do
                                for _, item in (container and container:GetChildren()) or {}do
                                    if item:IsA('Tool') and item.Name:lower():find(needle, 1, true) then
                                        local stack = item:FindFirstChild('Quantity')

                                        count += (stack and tonumber(stack.Value)) or 1
                                    end
                                end
                            end

                            return op == '<=' and count <= tonumber(want) or (op ~= '<=' and count >= tonumber(want))
                        end,
                    },
                    {
                        label = 'Health',
                        unit = '%',
                        default = 50,
                        get = function()
                            local char = LocalPlayer.Character
                            local hum = char and char:FindFirstChildOfClass('Humanoid')

                            if not (hum and hum.MaxHealth > 0) then
                                return nil
                            end

                            return math.floor(hum.Health / hum.MaxHealth * 100)
                        end,
                    },
                    {
                        label = 'Lua',
                        unit = '',
                        text = true,
                        ops = {
                            'true',
                            'false',
                        },
                        test = function(op, value)
                            local ran, result = runPathLua(nil, value, true)

                            if not ran then
                                return true
                            end

                            local yes = result ~= nil and result ~= false

                            return op == 'false' and not yes or (op ~= 'false' and yes)
                        end,
                    },
                }

                for _, zone in LootZones.list do
                    table.insert(CONDITION_VARS, {
                        label = zone.label,
                        unit = 'm',
                        get = function()
                            return LootZones.minutesSince(zone.label)
                        end,
                    })
                end
                for _, entry in CONDITION_VARS do
                    state.conditionVarByLabel[entry.label] = entry
                end

                local function conditionMet(cond)
                    if not cond or not cond.var then
                        return true
                    end

                    local entry = state.conditionVarByLabel[cond.var]

                    if entry and entry.test then
                        local passed, result = pcall(entry.test, cond.op, cond.value)

                        return not passed or result == true
                    end

                    local ok, value = pcall(function()
                        return entry and entry.get()
                    end)

                    if not ok or type(value) ~= 'number' then
                        return true
                    end

                    local target = tonumber(cond.value) or 0

                    if cond.op == '<=' then
                        return value <= target
                    elseif cond.op == '>' then
                        return value > target
                    elseif cond.op == '<' then
                        return value < target
                    end

                    return value >= target
                end

                function conditionText(cond)
                    if not (cond and cond.var) then
                        return ''
                    end

                    local entry = state.conditionVarByLabel[cond.var]

                    return string.format('%s %s %s%s', tostring(cond.var), tostring(cond.op), tostring(cond.value), entry and entry.unit or '')
                end

                local function gateLandingClear(gateIndex)
                    for k = gateIndex + 1, math.min(gateIndex + 3, #trinket_bot.active_points)do
                        local dest = trinket_bot.active_points[k]

                        if dest and dest.position then
                            if not shriekersIgnored() and detectShrieker(dest.position, GATE_CLEAR_RADIUS, allyOf) then
                                return false, 'a shrieker'
                            end

                            local near, byName = isPlayerNear(dest.position, GATE_CLEAR_RADIUS)

                            if near then
                                return false, byName
                            end
                        end
                    end

                    return true
                end
                local function suicide(byPlayer)
                    trinket_bot.race = trinket_bot.race or getStat('Race')

                    if trinket_bot.race == 'Haselda' then
                        botLog(
[[Knock: Haseldan, the void would cost a life through the resurrection - running the path instead]])

                        return 'nodrop'
                    end

                    local livesBefore

                    task.spawn(function()
                        livesBefore = tonumber(getStat('Lives'))
                    end)

                    local prevNoFall = ctx.State.noFallUntil

                    ctx.State.noFallUntil = tick() + KNOCK_RESPAWN_WAIT + SUICIDE_RESPAWN_WAIT + 60

                    local keepDown, held

                    local function done(outcome)
                        ctx.State.noFallUntil = prevNoFall or 0

                        if keepDown then
                            keepDown:Disconnect()
                        end
                        if held and held.Parent then
                            held.Anchored = false
                        end

                        return outcome
                    end

                    local hrp = Character.root()
                    local target, clear = nil, false

                    if hrp then
                        target, clear = voidBelow(hrp.Position)
                    end
                    if not clear then
                        botLog('Knock: no void under this spot, not knocking on the ground')

                        return done('nodrop')
                    end

                    for attempt = 1, 3 do
                        botLog('Knock: dropping to y%.0f (try %d)', target.Y, attempt)
                        SmoothTeleport(target)

                        if inVoid(target) then
                            break
                        end
                    end

                    if not inVoid(target) then
                        local at = Character.root()

                        botLog(
[[Knock: never got below the floor (at y%.0f), not knocking on the ground]], at and at.Position.Y or
-1)

                        return done('nodrop')
                    end

                    trinket_bot.expectedDeathUntil = tick() + KNOCK_RESPAWN_WAIT + SUICIDE_RESPAWN_WAIT
                    trinket_bot.path_running = false

                    local knocked = ctx.State.fireFall and select(1, pcall(ctx.State.fireFall, 2.39, 'bot suicide')) or false

                    task.spawn(Webhook.text,
[[@everyone bot knocked itself into the void to get away from **]] .. tostring(byPlayer) .. '**')

                    local old = LocalPlayer.Character
                    local oldHum = old and old:FindFirstChildOfClass('Humanoid')

                    if oldHum then
                        oldHum.Died:Connect(function()
                            task.spawn(function()
                                local watchUntil = tick() + BOT.lifeWatch

                                while tick() < watchUntil do
                                    local now = tonumber(getStat('Lives'))

                                    if livesBefore and now and now < livesBefore then
                                        if Toggles.StayInServer and Toggles.StayInServer.Value then
                                            return
                                        end

                                        MemStore.remove('botstarted')
                                        MemStore.remove('serverhop_count')
                                        task.spawn(Webhook.text, string.format('@everyone the void knock cost a life (%d to %d), kicking', livesBefore, now))
                                        Kick.now('sentinel: the void knock cost a life')

                                        return
                                    end

                                    task.wait(0.5)
                                end
                            end)
                        end)
                    end

                    local refires, lastFire = 0, tick()

                    keepDown = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        local root = old and old:FindFirstChild('HumanoidRootPart')

                        if not (root and oldHum and oldHum.Health > 0 and LocalPlayer.Character == old) then
                            return
                        end
                        if CollectionService:HasTag(old, 'Knocked') or refires >= BOT.knockRefires then
                            if held then
                                held.Anchored = false
                                held = nil
                            end

                            return
                        end
                        if not held then
                            held = root
                            root.Anchored = true
                            root.AssemblyLinearVelocity = Vector3.zero
                        end
                        if tick() - lastFire >= BOT.knockRefireGap and ctx.State.fireFall then
                            lastFire = tick()

                            refires += 1

                            botLog('Knock: upright at y%.0f, knocking again (%d/%d)', root.Position.Y, refires, BOT.knockRefires)
                            task.spawn(pcall, ctx.State.fireFall, 2.39, 'bot suicide again')
                        end
                    end))

                    local function respawned()
                        local ch = LocalPlayer.Character
                        local hum = ch and ch:FindFirstChildOfClass('Humanoid')

                        return ch ~= nil and ch ~= old and hum ~= nil and hum.Health > 0
                    end

                    local deadline = tick() + KNOCK_RESPAWN_WAIT

                    while tick() < deadline and not respawned() do
                        task.wait(0.25)
                    end

                    if not respawned() and LocalPlayer.Character == old and oldHum and oldHum.Health > 0 then
                        local at = Character.root()

                        botLog(
[[Knock: still alive after %ds at y%.0f (knock %s) - waiting for the death, never leaving mid fight]], KNOCK_RESPAWN_WAIT, at and at.Position.Y or
-1, tostring(knocked))
                        Webhook.text(string.format(
[[@everyone knock did not take after %ds (knock %s), waiting for the death before kicking to deny **%s**]], KNOCK_RESPAWN_WAIT, tostring(knocked), tostring(byPlayer)))

                        while LocalPlayer.Character == old and oldHum.Parent and oldHum.Health > 0 do
                            task.wait(0.25)
                        end

                        return done('dead')
                    end

                    deadline = tick() + SUICIDE_RESPAWN_WAIT

                    while tick() < deadline and not respawned() do
                        task.wait(0.25)
                    end

                    return done(respawned() and 'respawned' or 'dead')
                end
                local function directionalEscape(
                    index,
                    playerName,
                    untilFree,
                    awayFrom
                )
                    if not untilFree then
                        if trinket_bot.escaping then
                            return
                        end

                        trinket_bot.escaping = true

                        local tagged = LocalPlayer.Character

                        if tagged and CollectionService:HasTag(tagged, 'Danger') then
                            trinket_bot.path_running = false

                            trinketBotServerhop('In combat with ' .. tostring(playerName))

                            return
                        end

                        botLog('Directional escape from point %d (player: %s)', index, tostring(playerName))
                    end

                    local points = trinket_bot.active_points

                    if #points == 0 then
                        points = trinket_bot.path_points
                    end

                    local char = LocalPlayer.Character
                    local hrp = char and char:FindFirstChild('HumanoidRootPart')

                    if not hrp or #points == 0 then
                        if untilFree then
                            return 0
                        end

                        trinket_bot.path_running = false

                        trinketBotServerhop('Escaping ' .. tostring(playerName))

                        return
                    end

                    local cur = hrp.Position
                    local distFirst = (points[1].position - cur).Magnitude
                    local distLast = (points[#points].position - cur).Magnitude
                    local towardFirst, towardLast = 0, 0

                    for j = index - 1, 1, -1 do
                        if isPlayerNear(points[j].position, 250) then
                            towardFirst += 1
                        end
                    end
                    for j = index + 1, #points do
                        if isPlayerNear(points[j].position, 250) then
                            towardLast += 1
                        end
                    end

                    local goFirst

                    if untilFree then
                        local threat = type(awayFrom) == 'function' and awayFrom() or awayFrom

                        local function reach(step)
                            local best = -1

                            for j = index + step, index + step * BOT.combatLookahead, step do
                                local pt = points[j]

                                if not pt then
                                    break
                                end

                                best = math.max(best, typeof(threat) == 'Vector3' and (pt.position - threat).Magnitude or math.abs(j - index))
                            end

                            return best
                        end

                        goFirst = reach(-1) > reach(1)
                    elseif typeof(awayFrom) == 'Vector3' then
                        goFirst = (points[1].position - awayFrom).Magnitude > (points[#points].position - awayFrom).Magnitude
                    elseif towardFirst ~= towardLast then
                        goFirst = towardFirst < towardLast
                    else
                        goFirst = distFirst <= distLast
                    end

                    local target = goFirst and 1 or #points
                    local step = goFirst and -1 or 1

                    botLog(
[[Escaping %s toward %s (point %d): %.0f studs that way / %d nearby players (vs %.0f studs / %d players the other way)]], tostring(playerName), goFirst and 'start' or 'end', target, goFirst and distFirst or distLast, goFirst and towardFirst or towardLast, goFirst and distLast or distFirst, goFirst and towardLast or towardFirst)

                    local function steppingToward(to)
                        local r = Character.root()
                        local from = r and r.Position or to

                        for _, p in Players:GetPlayers()do
                            local pchar = p ~= LocalPlayer and p.Character
                            local phrp = pchar and pchar:FindFirstChild('HumanoidRootPart')

                            if phrp and not isCarriedByMe(p) and not (allyOf and allyOf(p)) then
                                local d = (phrp.Position - to).Magnitude

                                if d <= 90 and d < (phrp.Position - from).Magnitude then
                                    return true, p.Name
                                end
                            end
                        end

                        return false
                    end

                    local traversed = 0

                    for j = index + step, target, step do
                        if not (trinket_bot.path_running or trinket_bot.combatEscape) or trinket_bot.moderator_detected or trinket_bot.stopped then
                            break
                        end
                        if untilFree then
                            local c = LocalPlayer.Character

                            if not (c and CollectionService:HasTag(c, 'Danger')) then
                                break
                            end
                            if trinket_bot.knockDue then
                                botLog('Cornered mid escape, stopping the run to knock')

                                break
                            end
                        end

                        local pt = points[j]

                        if pt then
                            local blocked, blockerName

                            if untilFree then
                                blocked, blockerName = steppingToward(pt.position)
                            else
                                blocked, blockerName = isPlayerNear(pt.position, 90)
                            end
                            if blocked then
                                botLog('Escape route blocked by %s near point %d', tostring(blockerName), j)

                                break
                            end

                            SmoothTeleport(pt.position)

                            traversed += 1

                            task.wait(0.3)
                        end
                    end

                    if untilFree then
                        return traversed
                    end

                    trinket_bot.path_running = false

                    trinketBotServerhop(traversed > 0 and string.format('Escaped %s via path traversal (%d points)', tostring(playerName), traversed) or string.format(
[[Could not traverse away from %s - hopping from where the bot stood]], tostring(playerName)))
                end

                do
                    local function fighting()
                        local char = LocalPlayer.Character
                        local hum = char and char:FindFirstChildOfClass('Humanoid')

                        return hum ~= nil and hum.Health > 0 and CollectionService:HasTag(char, 'Danger')
                    end

                    escapeCombat = function(reason, awayFrom)
                        while trinket_bot.combatEscape do
                            task.wait(0.2)
                        end

                        if not fighting() then
                            return 'clear'
                        end

                        trinket_bot.combatEscape = true
                        trinket_bot.escaping = true
                        trinket_bot.path_running = false
                        state.emergency_gate_requested = nil

                        botLog('In combat (%s) - running the path until the tag drops', tostring(reason))

                        local startChar = LocalPlayer.Character
                        local startHum = startChar and startChar:FindFirstChildOfClass('Humanoid')
                        local hurtAt, lastHp = 0, startHum and startHum.Health
                        local hurtConn = startHum and startHum.HealthChanged:Connect(function(
                            hp
                        )
                            if lastHp and hp < lastHp then
                                hurtAt = tick()
                            end

                            lastHp = hp
                        end)

                        local function cornered()
                            local r = Character.root()
                            local critical = Options.CriticalDistance.Value
                            local near, who = false, nil

                            if r then
                                near, who = isPlayerNear(r.Position, critical > 0 and math.min(critical, KNOCK_RANGE) or KNOCK_RANGE)
                            end

                            local h = Character.humanoid()
                            local low = h ~= nil and h.MaxHealth > 0 and h.Health <= h.MaxHealth * BOT.knockHealth

                            if low and not near then
                                local around, name = false, nil

                                if r then
                                    around, name = isPlayerNear(r.Position, BOT.knockWatch)
                                end
                                if around then
                                    who = name
                                elseif tick() - hurtAt > BOT.knockHurt then
                                    low = false
                                end
                            end

                            return near or low, who, low
                        end

                        trinket_bot.knockDue = false

                        local watching = true

                        task.spawn(function()
                            while watching and fighting() do
                                if cornered() then
                                    trinket_bot.knockDue = true

                                    local tween = active_tween.tween

                                    if tween then
                                        pcall(function()
                                            tween:Cancel()
                                        end)
                                    end

                                    return
                                end

                                task.wait(0.1)
                            end
                        end)

                        local function threatAt()
                            if typeof(awayFrom) == 'Vector3' then
                                return awayFrom
                            end

                            local moving = type(awayFrom) == 'function' and awayFrom()

                            if moving then
                                return moving
                            end

                            local r = Character.root()
                            local best, bestD

                            for _, p in Players:GetPlayers()do
                                local pchar = r and p ~= LocalPlayer and p.Character
                                local phrp = pchar and pchar:FindFirstChild('HumanoidRootPart')

                                if phrp and not isCarriedByMe(p) and not (allyOf and allyOf(p)) then
                                    local d = (phrp.Position - r.Position).Magnitude

                                    if d <= 250 and (not bestD or d < bestD) then
                                        best, bestD = phrp.Position, d
                                    end
                                end
                            end

                            return best
                        end
                        local function runPath()
                            local points = #trinket_bot.active_points > 0 and trinket_bot.active_points or trinket_bot.path_points
                            local root = Character.root()

                            if root and #points > 0 then
                                local cur, minD = 1, math.huge

                                for idx, pt in points do
                                    if not pt.is_gate_point and not pt.action then
                                        local d = (pt.position - root.Position).Magnitude

                                        if d < minD then
                                            minD, cur = d, idx
                                        end
                                    end
                                end

                                directionalEscape(cur, reason, true, threatAt)
                            end
                        end

                        runPath()

                        local outcome = 'clear'

                        if fighting() then
                            botLog(
[[Out of path to run and still tagged - holding until the tag drops, knocking only if they close in or health runs low]])
                        end

                        while fighting() and not trinket_bot.stopped and not state.unloaded do
                            local isCornered, who, low = cornered()

                            if isCornered then
                                botLog('Still tagged and %s - knocking into the void', low and 'low on health' or (tostring(who) .. ' closed in'))

                                outcome = suicide(who or 'a hit on low health')

                                if outcome ~= 'nodrop' then
                                    break
                                end

                                outcome = 'clear'
                                trinket_bot.knockDue = false

                                runPath()
                            end

                            task.wait(0.2)
                        end

                        watching = false

                        if hurtConn then
                            hurtConn:Disconnect()
                        end

                        trinket_bot.knockDue = false

                        if outcome == 'clear' and (LocalPlayer.Character ~= startChar or not startHum or startHum.Health <= 0) then
                            outcome = 'dead'
                        end

                        trinket_bot.combatEscape = false

                        botLog('Combat escape over: %s', outcome)

                        return outcome
                    end
                end

                local function opalEscape(strikeAt, label, dodge)
                    if trinket_bot.escaping then
                        return
                    end

                    trinket_bot.escaping = true

                    task.spawn(function()
                        local rtm = requestRemote('ReturnToMenu')
                        local waited = 0

                        while rtm and waited < 1.6 and not Menu.startMenu() do
                            local c = LocalPlayer.Character

                            if Menu.safeToMenu() and not (c and CollectionService:HasTag(c, 'Danger')) then
                                pcall(function()
                                    rtm:InvokeServer()
                                end)
                            end

                            task.wait(0.35)

                            waited += 0.35
                        end

                        if Menu.startMenu() then
                            trinket_bot.path_running = false
                        end
                    end)

                    local hrp = Character.root()
                    local clear = Threats.RANGE.opalClear

                    if hrp and Threats.flatDistance(hrp.Position, strikeAt) < clear then
                        local target, bestD = dodge, math.huge

                        for _, pt in trinket_bot.active_points do
                            local d = (pt.position - hrp.Position).Magnitude

                            if not pt.is_gate_point and d < bestD and d <= BOT.opalReach and Threats.flatDistance(pt.position, strikeAt) >= clear then
                                target, bestD = pt.position, d
                            end
                        end

                        if target then
                            botLog('%s - moving %.0f studs out of the strike', label, (target - hrp.Position).Magnitude)
                            SmoothTeleport(target, false, 145)
                        end
                    end

                    trinket_bot.path_running = false

                    trinketBotServerhop(label)
                end

                function leaveToMenu()
                    if trinket_bot.test_mode or (Toggles.StayInServer and Toggles.StayInServer.Value) then
                        return false
                    end
                    if Menu.startMenu() then
                        return true
                    end

                    local char = LocalPlayer.Character

                    if char and CollectionService:HasTag(char, 'Danger') then
                        botLog('Menu: still tagged, not menuing')

                        return false
                    end

                    local rtm = requestRemote('ReturnToMenu')

                    if not rtm then
                        return false
                    end
                    if not Menu.waitMenuReady(MENU_READY_WAIT, true) then
                        botLog(
[[Menu: no menu button on a spawned character after %ds, leaving without menuing rather than risking the pack]], MENU_READY_WAIT)

                        return false
                    end

                    pcall(function()
                        rtm:InvokeServer()
                    end)

                    return true
                end
                function safeServerhop(reason, skipGateEscape)
                    if trinket_bot.stopped then
                        return
                    end

                    trinket_bot.escaping = true

                    if not (trinket_bot.test_mode or Toggles.StayInServer.Value) then
                        trinket_bot.hopping = true
                    end

                    local char = LocalPlayer.Character
                    local tagged = char ~= nil and CollectionService:HasTag(char, 'Danger')

                    botLog('Safe serverhop: %s (in danger: %s)', tostring(reason), tostring(tagged))

                    local hrp = char and char:FindFirstChild('HumanoidRootPart')

                    if hrp then
                        MemStore.set('lastPlayerPosition', string.format('%f,%f,%f', hrp.Position.X, hrp.Position.Y, hrp.Position.Z))
                    end

                    local gated = false

                    if tagged and not skipGateEscape and #trinket_bot.path_points > 0 and not CollectionService:HasTag(char, 'SnapCool') then
                        for _, point in trinket_bot.path_points do
                            if point.is_gate_point and Gate(point.gate_location) then
                                trinket_bot.gatingUntil = 0
                                gated = true

                                task.wait(0.5)

                                break
                            end
                        end
                    end

                    trinket_bot.path_running = false

                    trinketBotServerhop(reason .. (gated and ' (gated out)' or ''), true)
                end

                do
                    local ffSince, accum = nil, 0
                    local anchor, anchorAt = nil, 0

                    ctx.Maid:Give(RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                        dt
                    )
                        accum += dt

                        if accum < 2 then
                            return
                        end

                        accum = 0

                        if MemStore.get('botstarted') ~= 'true' or (Toggles.StayInServer and Toggles.StayInServer.Value) or trinket_bot.hopping then
                            ffSince = nil

                            return
                        end

                        local char = LocalPlayer.Character
                        local shielded = char ~= nil and char:FindFirstChildOfClass('ForceField') ~= nil

                        if tick() < (trinket_bot.spawnShieldUntil or 0) then
                            if shielded then
                                ffSince = nil

                                return
                            end

                            trinket_bot.spawnShieldUntil = 0
                        end
                        if tick() < (trinket_bot.expectedDeathUntil or 0) then
                            ffSince = nil

                            return
                        end

                        local stalledHrp = not trinket_bot.path_running and char and char:FindFirstChild('HumanoidRootPart')
                        local critical = Options.CriticalDistance and Options.CriticalDistance.Value or 0

                        if stalledHrp and critical > 0 and tick() >= (trinket_bot.spawnGraceUntil or 0) then
                            local near, who = isPlayerNear(stalledHrp.Position, critical)

                            if near then
                                safeServerhop(string.format('%s within critical distance with the path stopped', tostring(who)))

                                return
                            end
                        end
                        if shielded then
                            local parked = trinket_bot.path_running and trinket_bot.active_points[trinket_bot.current_index or 0]

                            if parked and standingAllowed(parked) then
                                ffSince = nil

                                return
                            end

                            ffSince = ffSince or tick()

                            if tick() - ffSince > 30 and not trinket_bot.hopping then
                                ffSince = nil

                                deathReport('stalled in a spawn shield for 30s, hopping to recover')
                                safeServerhop('stalled in a spawn shield for 30s')
                            end

                            return
                        end

                        ffSince = nil

                        local hrp = trinket_bot.path_running and char and char:FindFirstChild('HumanoidRootPart')

                        if not hrp or trinket_bot.escaping or trinket_bot.wedgeRecovering or trinket_bot.hopping or state.emergency_gate_in_progress or Dialogue.inDialogue() or CollectionService:HasTag(char, 'Danger') or tick() < (trinket_bot.gatingUntil or 0) or standingAllowed(trinket_bot.active_points[trinket_bot.current_index or 0]) then
                            anchor = nil

                            return
                        end
                        if not anchor or (hrp.Position - anchor).Magnitude > WEDGE_MOVED then
                            anchor, anchorAt = hrp.Position, tick()
                        elseif tick() - anchorAt > WEDGE_SECONDS then
                            anchor = nil

                            task.spawn(recoverWedge)
                        end
                    end)))
                end

                recoverWedge = function()
                    if trinket_bot.wedgeRecovering then
                        return
                    end

                    trinket_bot.wedgeRecovering = true

                    local root = Character.root()
                    local from = root and root.Position
                    local points = trinket_bot.active_points

                    if not from or #points == 0 then
                        trinket_bot.wedgeRecovering = false

                        return
                    end

                    local function arrived(pos)
                        local now = Character.root()

                        return now ~= nil and (now.Position - pos).Magnitude < 12
                    end

                    local nearest, minD = nil, math.huge

                    for idx, pt in points do
                        if not pt.is_gate_point and not pt.action then
                            local d = (pt.position - from).Magnitude

                            if d < minD then
                                minD, nearest = d, idx
                            end
                        end
                    end

                    botLog('Wedge: held the same spot for %ds, rejoining the path', WEDGE_SECONDS)

                    for _, step in {
                        1,
                        -1,
                        2,
                        -2,
                    }do
                        local pt = nearest and points[nearest + step]

                        if pt and not pt.is_gate_point and not pt.action and (pt.position - from).Magnitude > WEDGE_MOVED then
                            trinket_bot.relocated = true

                            SmoothTeleport(pt.position)
                            task.wait(0.35)

                            if arrived(pt.position) then
                                botLog('Wedge: freed onto point %d', nearest + step)

                                trinket_bot.wedgeRecovering = false

                                return
                            end
                        end
                    end

                    local gateIdx = nextClearGate(points, nearest or 1, isPlayerNear, emergencyGateClear, function(
                        j,
                        who,
                        isLast
                    )
                        noteGateBlocked(j, #points, who, isLast)
                    end)

                    if gateIdx and gateStabilized(points[gateIdx].gate_location, gateExpectedDest(gateIdx)) then
                        botLog('Wedge: gated out through point %d', gateIdx)

                        trinket_bot.wedgeRecovering = false

                        return
                    end

                    botLog(
[[Wedge: could not rejoin the path or gate out - hopping with the pack intact]])

                    trinket_bot.wedgeRecovering = false

                    trinketBotServerhop('Bot wedged - could not rejoin the path or gate out')
                end

                local function handleModerator(player)
                    if trinket_bot.moderator_detected then
                        return
                    end

                    trinket_bot.moderator_detected = true
                    trinket_bot.path_running = false

                    local key = 'moderator_encounter_' .. player.Name
                    local count = (tonumber(MemStore.get(key)) or 0) + 1

                    MemStore.set(key, count)

                    local who = ctx.State.moderatorLabel and ctx.State.moderatorLabel(player) or 'Moderator'

                    botLog('%s %s detected (encounter %d)', who, player.Name, count)

                    if Toggles.StayInServer.Value then
                        Webhook.text(who .. ' **' .. player.Name .. '** detected (staying in server)')

                        return
                    end

                    local airborne = not isGrounded()

                    task.spawn(function()
                        Webhook.text(string.format('@everyone %s **%s** (encounter %d) - %s and leaving', who, player.Name, count, airborne and 'killing' or 'menuing'))
                    end)

                    if airborne then
                        waitOutDanger()

                        trinket_bot.expectedDeathUntil = tick() + EXPECTED_DEATH_WINDOW

                        local old = LocalPlayer.Character

                        pcall(Character.kill)

                        local deadline = tick() + 20

                        repeat
                            task.wait(0.25)
                        until (LocalPlayer.Character and LocalPlayer.Character ~= old and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')) or tick() > deadline
                    end

                    task.wait(math.random(3, 6))

                    if count >= 3 then
                        Webhook.textBounded(string.format('@everyone %s **%s** encountered %dx - kicking', who, player.Name, count))
                        botKick(who .. ' encountered during trinket bot')

                        return
                    end

                    leaveToMenu()
                    trinketBotServerhop(who .. ' ' .. player.Name)
                end
                local function setupThreats()
                    local pebbleHolders = {}

                    local function illusionistThreat(p)
                        if not trinket_bot.path_running or p == LocalPlayer or (allyOf and allyOf(p)) then
                            return
                        end
                        if Toggles.SkipIllusionist.Value and Threats.isIllusionist(p) then
                            trinketBotServerhop('Illusionist in server (' .. p.Name .. ')')
                        end
                    end
                    local function watchRoot(p, root)
                        local function bindEmitter(obj)
                            if obj.Name ~= 'MindMage' or not obj:IsA('ParticleEmitter') then
                                return
                            end

                            threatMaid['mind_' .. p.UserId] = obj:GetPropertyChangedSignal('Enabled'):Connect(function(
                            )
                                illusionistThreat(p)
                            end)

                            illusionistThreat(p)
                        end

                        threatMaid['root_' .. p.UserId] = root.ChildAdded:Connect(bindEmitter)

                        for _, obj in root:GetChildren()do
                            bindEmitter(obj)
                        end
                    end
                    local function watchCharacter(p, char)
                        if not char then
                            return
                        end

                        local root = char:FindFirstChild('HumanoidRootPart')

                        if root then
                            watchRoot(p, root)

                            return
                        end

                        threatMaid['char_' .. p.UserId] = char.ChildAdded:Connect(function(
                            child
                        )
                            if child.Name == 'HumanoidRootPart' then
                                watchRoot(p, child)
                            end
                        end)
                    end
                    local function watchPlayer(p)
                        if p == LocalPlayer then
                            return
                        end

                        illusionistThreat(p)
                        watchCharacter(p, Threats.liveCharacter(p))

                        threatMaid['cadd_' .. p.UserId] = p.CharacterAdded:Connect(function(
                            char
                        )
                            watchCharacter(p, char)
                        end)
                    end

                    for _, p in Players:GetPlayers()do
                        if p ~= LocalPlayer then
                            if hostileMod(p) then
                                handleModerator(p)

                                return
                            end

                            watchPlayer(p)
                        end
                    end

                    local pebbleOn, perfloraOn = Threats.allowed(Options, 'pebble'), Threats.labelAllowed(Options, 'Perflora')

                    local function heldOut(char)
                        for _, item in char:GetChildren()do
                            if item:IsA('Tool') and ((pebbleOn and item.Name == 'Pebble') or (perfloraOn and item.Name == 'Perflora')) then
                                return item.Name
                            end
                        end
                    end

                    for _, p in Players:GetPlayers()do
                        local char = p ~= LocalPlayer and not isCarriedByMe(p) and not (allyOf and allyOf(p)) and Threats.liveCharacter(p)
                        local held = char and heldOut(char)

                        if held then
                            task.spawn(trinketBotServerhop, string.format('%s already holding %s at the start', p.Name, held))

                            break
                        end
                    end

                    threatMaid.flagged = ctx.State.onModeratorFlagged and ctx.State.onModeratorFlagged(function(
                        p
                    )
                        if trinket_bot.path_running and hostileMod(p) then
                            handleModerator(p)
                        end
                    end)

                    local live = Workspace:FindFirstChild('Live')

                    local function observerThreat(obj)
                        if obj.Name ~= 'Observing' or not obj:IsA('Accessory') or not (trinket_bot.path_running and Toggles.SkipIllusionist.Value) then
                            return
                        end

                        local model = obj.Parent

                        while model and model.Parent ~= live do
                            model = model.Parent
                        end

                        if not model or model == LocalPlayer.Character then
                            return
                        end

                        local p = Players:GetPlayerFromCharacter(model) or Players:FindFirstChild(model.Name)

                        if p == LocalPlayer or (p and allyOf and allyOf(p)) then
                            return
                        end

                        trinketBotServerhop('Illusionist observing in server (' .. (p and p.Name or model.Name) .. ')')
                    end

                    if live then
                        threatMaid.observing = live.DescendantAdded:Connect(observerThreat)

                        for _, model in live:GetChildren()do
                            local observing = model:FindFirstChild('Observing', true)

                            if observing then
                                observerThreat(observing)
                            end
                        end
                    end

                    threatMaid.spawnGrace = LocalPlayer.CharacterAdded:Connect(function(
                    )
                        trinket_bot.spawnGraceUntil = tick() + 3
                    end)
                    threatMaid.playerAdded = Players.PlayerAdded:Connect(function(
                        p
                    )
                        task.wait(0.5)

                        if not trinket_bot.path_running then
                            return
                        end
                        if hostileMod(p) then
                            handleModerator(p)
                        else
                            watchPlayer(p)
                        end
                    end)
                    threatMaid.playerRemoving = Players.PlayerRemoving:Connect(function(
                        p
                    )
                        threatMaid['char_' .. p.UserId] = nil
                        threatMaid['cadd_' .. p.UserId] = nil
                        threatMaid['mind_' .. p.UserId] = nil
                        threatMaid['root_' .. p.UserId] = nil
                        state.player_encounters[p.UserId] = nil
                        state.proximity_warnings[p.UserId] = nil
                    end)

                    local live = Workspace:FindFirstChild('Live')

                    if live then
                        local function howlerBeside(pos)
                            for _, model in live:GetChildren()do
                                if model:IsA('Model') and string.find(string.lower(model.Name), '.howler', 1, true) and not Players:GetPlayerFromCharacter(model) then
                                    local hum = model:FindFirstChildOfClass('Humanoid')
                                    local root = model:FindFirstChild('HumanoidRootPart') or model.PrimaryPart

                                    if root and not (hum and hum.Health <= 0) then
                                        local d = (root.Position - pos).Magnitude

                                        if d <= 30 then
                                            return d
                                        end
                                    end
                                end
                            end

                            return nil
                        end
                        local function watchGater(gateOut)
                            local char = gateOut.Parent
                            local gater = char and Players:GetPlayerFromCharacter(char)

                            if not gater or gater == LocalPlayer then
                                return
                            end

                            task.spawn(function()
                                local deadline = os.clock() + 10

                                while gateOut.Parent == char and os.clock() < deadline and trinket_bot.path_running do
                                    if not Threats.labelAllowed(Options, 'Howler') then
                                        return
                                    end

                                    local root = char:FindFirstChild('HumanoidRootPart')
                                    local d = root and howlerBeside(root.Position)

                                    if d then
                                        trinketBotServerhop(string.format('%s gating with a Howler %.0f studs from them', gater.Name, d))

                                        return
                                    end

                                    task.wait(0.2)
                                end
                            end)
                        end

                        for _, p in Players:GetPlayers()do
                            local gateOut = p.Character and p.Character:FindFirstChild('GateOut')

                            if gateOut then
                                watchGater(gateOut)
                            end
                        end

                        local function watchHarpy(model)
                            local label = model.Name:find('Gorpig', 1, true) and 'Gorpig' or 'Harpy'

                            task.spawn(function()
                                local vars = model:WaitForChild('Variables', 10)
                                local target = vars and vars:WaitForChild('Target', 10)

                                if not (target and target:IsA('ObjectValue')) then
                                    return
                                end

                                local function check()
                                    local char = LocalPlayer.Character

                                    if not (char and target.Value == char and trinket_bot.path_running) then
                                        return
                                    end
                                    if Toggles.StayInServer.Value or not Threats.labelAllowed(Options, label) then
                                        return
                                    end

                                    local root = model:FindFirstChild('HumanoidRootPart')

                                    trinketBotServerhop(model.Name .. ' is targeting the bot', nil, nil, root and root.Position)
                                end

                                threatMaid:Connect(target:GetPropertyChangedSignal('Value'), check)
                                check()
                            end)
                        end

                        local mages = {}

                        local function watchMage(model)
                            if mages[model] then
                                return
                            end

                            mages[model] = true

                            task.spawn(function()
                                local vars = model:WaitForChild('Variables', 10)
                                local target = vars and vars:WaitForChild('Target', 10)

                                if not (target and target:IsA('ObjectValue')) then
                                    return
                                end

                                local function check()
                                    local char = LocalPlayer.Character

                                    if not (char and target.Value == char and trinket_bot.path_running) then
                                        return
                                    end
                                    if Toggles.StayInServer.Value or not Threats.labelAllowed(Options, 'Corrupted Mage') then
                                        return
                                    end

                                    trinketBotServerhop('Corrupted Mage aggroed but we got away', nil, nil, function(
                                    )
                                        local root = model:FindFirstChild('HumanoidRootPart')

                                        return root and root.Position
                                    end)
                                end

                                threatMaid:Connect(target:GetPropertyChangedSignal('Value'), check)
                                check()
                            end)
                        end

                        local mageAccum = 0

                        threatMaid.mageRange = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                            dt
                        )
                            mageAccum += dt

                            if mageAccum < 0.25 then
                                return
                            end

                            mageAccum = 0

                            if not trinket_bot.path_running or Toggles.StayInServer.Value or next(mages) == nil then
                                return
                            end

                            local mine = Character.root()

                            if not mine or not Threats.labelAllowed(Options, 'Corrupted Mage') then
                                return
                            end

                            for model in mages do
                                if not model.Parent then
                                    mages[model] = nil

                                    continue
                                end

                                local root = model:FindFirstChild('HumanoidRootPart')
                                local hum = model:FindFirstChildOfClass('Humanoid')

                                if root and not (hum and hum.Health <= 0) then
                                    local d = (root.Position - mine.Position).Magnitude

                                    if d <= 420 then
                                        trinketBotServerhop(string.format('Corrupted Mage %.0f studs away', d), nil, nil, root.Position)

                                        return
                                    end
                                end
                            end
                        end))

                        for _, model in live:GetChildren()do
                            if model:IsA('Model') and (model.Name:find('Harpy', 1, true) or model.Name:find('Gorpig', 1, true)) then
                                watchHarpy(model)
                            elseif model:IsA('Model') and model.Name:find('Corrupted Mage', 1, true) then
                                watchMage(model)
                            end
                        end

                        local function spearEscape(spear)
                            if state.spearEscape then
                                return
                            end

                            state.spearEscape = true

                            local from = spear.Position
                            local mine = Character.root()
                            local suspects = {}

                            for _, p in Players:GetPlayers()do
                                local bag = p ~= LocalPlayer and p:FindFirstChildOfClass('Backpack')

                                if bag and (bag:FindFirstChild('Justice Spears') or (p.Character and p.Character:FindFirstChild('Justice Spears'))) then
                                    table.insert(suspects, p.Name)
                                end
                            end

                            local shooter = #suspects > 0 and table.concat(suspects, ', ') or 'unknown'

                            task.spawn(Webhook.text, string.format(
[[@everyone `JUSTICE SPEARS` spear coming in from %.0f studs, possible shooter: %s]], mine and (from - mine.Position).Magnitude or 0, shooter))

                            local blocking = true
                            local holdBlock = BASIL_NO_VIRTUALIZE(function()
                                local char = LocalPlayer.Character
                                local root = char and char:FindFirstChild('HumanoidRootPart')
                                local handler = char and char:FindFirstChild('CharacterHandler')
                                local remotes = handler and handler:FindFirstChild('Remotes')
                                local block = remotes and remotes:FindFirstChild('Block')
                                local aim = spear.Parent and spear.Position or from

                                if root then
                                    pcall(function()
                                        root.CFrame = CFrame.lookAt(root.Position, Vector3.new(aim.X, root.Position.Y, aim.Z))
                                    end)
                                end
                                if block then
                                    pcall(block.FireServer, block, false)
                                end
                            end)

                            task.spawn(function()
                                local hum = Character.humanoid()

                                if hum then
                                    pcall(hum.UnequipTools, hum)
                                end

                                while blocking and not state.unloaded do
                                    holdBlock()
                                    RunService.Heartbeat:Wait()
                                end

                                local char = LocalPlayer.Character
                                local handler = char and char:FindFirstChild('CharacterHandler')
                                local remotes = handler and handler:FindFirstChild('Remotes')
                                local unblock = remotes and remotes:FindFirstChild('Unblock')

                                if unblock then
                                    pcall(unblock.FireServer, unblock, {})
                                end
                            end)

                            local reason = 'Justice Spear incoming (possible shooter: ' .. shooter .. ')'
                            local char = LocalPlayer.Character
                            local tagged = char ~= nil and CollectionService:HasTag(char, 'Danger')

                            if isGrounded() or tagged then
                                trinketBotServerhop(reason, nil, nil, from)

                                blocking = false

                                return
                            end

                            blocking = false

                            if trinket_bot.hopCommitted then
                                return
                            end

                            botLog(
[[Justice Spear: airborne and untagged, killing to leave from the respawn]])

                            trinket_bot.path_running = false
                            trinket_bot.hopping = true
                            trinket_bot.expectedDeathUntil = tick() + EXPECTED_DEATH_WINDOW

                            local old = LocalPlayer.Character

                            pcall(Character.kill)

                            local deadline = tick() + 20

                            repeat
                                task.wait(0.25)
                            until (LocalPlayer.Character and LocalPlayer.Character ~= old and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')) or tick() > deadline

                            Menu.waitMenuReady(MENU_READY_WAIT, true)
                            trinketBotServerhop(reason .. ' - killed out of the air to leave', nil, nil, from)
                        end
                        local function watchSpear(spear)
                            if state.spearEscape or not Threats.labelAllowed(Options, 'Justice Spears') then
                                return
                            end

                            task.spawn(function()
                                local function myPos()
                                    local r = Character.root()

                                    return r and r.Position or nil
                                end

                                local mine = myPos()

                                if not (mine and spear.Parent) or (spear.Position - mine).Magnitude > BOT.spearRange then
                                    return
                                end
                                if Threats.tracksToward(spear, myPos, function()
                                    return trinket_bot.path_running and not state.unloaded
                                end) then
                                    spearEscape(spear)
                                end
                            end)
                        end

                        threatMaid.pingSpike = PingWatch.watch(function(
                            ping,
                            baseline
                        )
                            if not trinket_bot.path_running or Toggles.StayInServer.Value or not Threats.labelAllowed(Options, 'Ping Spike') then
                                return
                            end

                            local root = Character.root()

                            if root then
                                MemStore.set('lastPlayerPosition', string.format('%f,%f,%f', root.Position.X, root.Position.Y, root.Position.Z))
                            end

                            trinketBotServerhop(string.format('ping spiked to %.0fms from %.0fms', ping, baseline), true)
                        end)
                        threatMaid.emergencyItem = live.DescendantAdded:Connect(BASIL_NO_VIRTUALIZE(function(
                            desc
                        )
                            if not trinket_bot.path_running or Toggles.StayInServer.Value then
                                return
                            end

                            local name = desc.Name

                            if name == 'GateOut' then
                                watchGater(desc)
                            elseif name == 'Energy Spear' and desc:IsA('BasePart') then
                                watchSpear(desc)
                            elseif desc.Parent == live and desc:IsA('Model') and (name:find('Harpy', 1, true) or name:find('Gorpig', 1, true)) then
                                watchHarpy(desc)
                            elseif desc.Parent == live and desc:IsA('Model') and name:find('Corrupted Mage', 1, true) then
                                watchMage(desc)
                            elseif name == 'Perflora' and desc:IsA('Tool') and Threats.labelAllowed(Options, 'Perflora') then
                                local owner = desc.Parent and Players:GetPlayerFromCharacter(desc.Parent)

                                if owner and owner ~= LocalPlayer then
                                    trinketBotServerhop(desc.Name .. ' equipped by ' .. owner.Name)
                                end
                            end
                        end))
                    end

                    threatMaid.pebbleThrow = Workspace.ChildAdded:Connect(function(
                        obj
                    )
                        if not trinket_bot.path_running or Toggles.StayInServer.Value then
                            return
                        end
                        if not (obj:IsA('MeshPart') and obj.Name == 'pebble') or not Threats.allowed(Options, 'pebble') then
                            return
                        end

                        local char = LocalPlayer.Character
                        local hrp = char and char:FindFirstChild('HumanoidRootPart')
                        local owner, ownerD

                        for p, t in pebbleHolders do
                            if p ~= LocalPlayer and not isCarriedByMe(p) and tick() - t <= 2.5 then
                                local ph = p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                                if ph then
                                    local d = hrp and (ph.Position - hrp.Position).Magnitude or 0

                                    if not ownerD or d < ownerD then
                                        owner, ownerD = p, d
                                    end
                                end
                            end
                        end

                        if not owner or (hrp and ownerD > 2000) then
                            return
                        end
                        if hrp and ownerD > PEBBLE_HOLD_RANGE then
                            local tracking = Threats.tracksToward(obj, function()
                                local c = LocalPlayer.Character
                                local r = c and c:FindFirstChild('HumanoidRootPart')

                                return r and r.Position or nil
                            end, function()
                                return trinket_bot.path_running and not state.unloaded
                            end)

                            if not tracking then
                                botLog('Pebble from %s at %.0f studs is not tracking us - ignoring', owner.Name, ownerD)

                                return
                            end
                        end

                        trinketBotServerhop(string.format('%s threw Pebble (%.0f studs)', owner.Name, ownerD))
                    end)

                    local function nearbyEscapePoint(fromPos, threatPos)
                        local best, bestAway

                        for _, pt in trinket_bot.path_points do
                            if not pt.is_gate_point then
                                local fromMe = (pt.position - fromPos).Magnitude

                                if fromMe >= 20 and fromMe <= 300 then
                                    local away = (pt.position - threatPos).Magnitude

                                    if not bestAway or away > bestAway then
                                        best, bestAway = pt.position, away
                                    end
                                end
                            end
                        end

                        return best
                    end
                    local function dodgeThenHop(
                        threatPos,
                        reason,
                        dodgeOverride,
                        extra
                    )
                        if state.fimbulEscape then
                            return
                        end

                        state.fimbulEscape = true

                        local char = LocalPlayer.Character
                        local hrp = char and char:FindFirstChild('HumanoidRootPart')
                        local escapeTo = dodgeOverride or (hrp and nearbyEscapePoint(hrp.Position, threatPos))

                        if escapeTo then
                            SmoothTeleport(escapeTo)
                        end

                        task.spawn(function()
                            Webhook.text('@everyone ' .. reason .. ' - escaping' .. (extra or ''))
                        end)

                        local after = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        if after then
                            MemStore.set('lastPlayerPosition', string.format('%f,%f,%f', after.Position.X, after.Position.Y, after.Position.Z))
                        end

                        trinket_bot.path_running = false

                        trinketBotServerhop(reason, true)
                    end
                    local function liveToolHolder(toolName)
                        local char = LocalPlayer.Character
                        local hrp = char and char:FindFirstChild('HumanoidRootPart')
                        local live = Workspace:FindFirstChild('Live')

                        if not hrp or not live then
                            return nil, nil
                        end

                        local bestName, bestD

                        for _, model in live:GetChildren()do
                            if model ~= char then
                                local tool = model:FindFirstChild(toolName)
                                local mh = model:FindFirstChild('HumanoidRootPart')

                                if tool and tool:IsA('Tool') and mh then
                                    local d = (mh.Position - hrp.Position).Magnitude

                                    if not bestD or d < bestD then
                                        bestName, bestD = model.Name, d
                                    end
                                end
                            end
                        end

                        return bestName, bestD
                    end
                    local function handleLaser(object)
                        if state.fimbulEscape or not trinket_bot.path_running or object.Name ~= 'Laser' then
                            return
                        end

                        task.spawn(BASIL_NO_VIRTUALIZE(function()
                            while object.Parent and trinket_bot.path_running and not state.fimbulEscape do
                                local part = (object:IsA('BasePart') and object) or object:FindFirstChildWhichIsA('BasePart')
                                local char = LocalPlayer.Character
                                local hrp = char and char:FindFirstChild('HumanoidRootPart')
                                local dist = part and hrp and (part.Position - hrp.Position).Magnitude

                                if dist and dist <= 350 then
                                    local bv = object:FindFirstChildWhichIsA('BodyVelocity')
                                    local vel = (bv and bv.Velocity) or part.AssemblyLinearVelocity

                                    if vel.Magnitude < 1 then
                                        vel = hrp.Position - part.Position
                                    end

                                    local flat = Vector3.new(vel.X, 0, vel.Z)
                                    local perp = flat.Magnitude > 0.1 and Vector3.new(
-flat.Z, 0, flat.X).Unit or Vector3.new(1, 0, 0)

                                    if (hrp.Position - part.Position):Dot(perp) < 0 then
                                        perp = -perp
                                    end

                                    local byName, byD = liveToolHolder('Spindulys')
                                    local reason = byName and string.format('Spindulys laser from %s (%.0f studs)', byName, byD) or string.format('Spindulys laser (%.0f studs)', dist)

                                    dodgeThenHop(part.Position, reason, hrp.Position + perp * 35)

                                    return
                                end

                                task.wait()
                            end
                        end))
                    end

                    local detach, snapArmed = Threats.watch({
                        active = function()
                            return trinket_bot.path_running and not state.fimbulEscape and not Toggles.StayInServer.Value
                        end,
                        isFriend = function(p)
                            return (ctx.State.isFriend and ctx.State.isFriend(p)) or isCarriedByMe(p)
                        end,
                        allow = function(kind)
                            return Threats.allowed(Options, kind)
                        end,
                        report = function(threat)
                            if threat.kind == 'glassmask' then
                                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
                                local rows = Threats.roster(hrp and hrp.Position, threat.range, function(
                                    p
                                )
                                    return ctx.State.getRogueName and ctx.State.getRogueName(p)
                                end)
                                local list = #rows > 0 and table.concat(rows, '\n') or 'nobody within 700 studs'

                                task.spawn(function()
                                    Webhook.text('@everyone `FIMBULVETR` ' .. threat.label .. ', possible opps below\n' .. list)
                                end)
                                dodgeThenHop(threat.position, threat.label)

                                return
                            end
                            if threat.kind == 'opalshard' then
                                if Toggles.StayInServer.Value then
                                    return
                                end

                                task.spawn(function()
                                    Webhook.text('@everyone `OPAL SHARD` ' .. threat.label .. ' - moving out of the strike and hopping')
                                end)
                                task.spawn(opalEscape, threat.position, threat.label, threat.dodge)

                                return
                            end
                            if threat.kind == 'celeritas' then
                                if Toggles.StayInServer.Value then
                                    return
                                end
                                if isGrounded() then
                                    task.spawn(leaveToMenu)
                                elseif not trinket_bot.test_mode then
                                    local jobId, why = Serverhop.joinNow({
                                        strategy = hopStrategy(),
                                        minPlayers = (Options.MinPlayerCount and Options.MinPlayerCount.Value) or 0,
                                        sizeFallback = true,
                                        avoid = (Toggles.AvoidOtherBots == nil or Toggles.AvoidOtherBots.Value) and BotClaims.takenJobs() or nil,
                                        onPick = BotClaims.claim,
                                    })

                                    botLog(jobId and 'Celeritas: airborne, joining %s at once' or 'Celeritas: airborne and no instant join (%s)', tostring(jobId or why))
                                end

                                trinket_bot.path_running = false

                                trinketBotServerhop(threat.label)

                                return
                            end

                            local suspects = ''

                            if not threat.caster then
                                local rows = Threats.roster(threat.position, Threats.RANGE.caster, function(
                                    p
                                )
                                    return ctx.State.getRogueName and ctx.State.getRogueName(p)
                                end, allyOf)

                                if #rows > 0 then
                                    suspects = '\npossible casters:\n' .. table.concat(rows, '\n')
                                end
                            end

                            dodgeThenHop(threat.position, threat.label, Threats.sidestep(threat.position), suspects)
                        end,
                    })

                    threatMaid.threats = detach

                    if not snapArmed then
                        botLog('ClientVFX missing, snap Celeritas detection is off')
                    end

                    threatMaid.laser = Workspace.ChildAdded:Connect(handleLaser)

                    local thrown = Workspace:FindFirstChild('Thrown')

                    if thrown then
                        threatMaid.laserThrown = thrown.ChildAdded:Connect(handleLaser)
                    end

                    local function detectGnav(p)
                        if p == LocalPlayer or not trinket_bot.path_running or state.gnavDetected then
                            return
                        end

                        local bp = p:FindFirstChildOfClass('Backpack')

                        if bp and (bp:FindFirstChild('Flying Flower God') or bp:FindFirstChild('Flying Mushroom God')) then
                            state.gnavDetected = true
                            state.gnavPlayerName = p.Name
                        end
                    end

                    for _, p in Players:GetPlayers()do
                        if p.Character then
                            task.spawn(detectGnav, p)
                        end
                    end

                    local proxAccum, shriekAccum, shriekSeen = 0, 0, false

                    threatMaid.proximity = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                        dt
                    )
                        shriekAccum += dt

                        if not trinket_bot.path_running or Toggles.StayInServer.Value then
                            return
                        end

                        proxAccum += dt

                        if proxAccum < 0.05 then
                            return
                        end

                        proxAccum = 0

                        local char = LocalPlayer.Character
                        local hrp = char and char:FindFirstChild('HumanoidRootPart')

                        if not hrp then
                            return
                        end
                        if CollectionService:HasTag(char, 'Danger') and not trinket_bot.escaping and tick() >= (trinket_bot.startGraceUntil or 0) then
                            if inShriekerZone() or dangerFromMob(hrp) then
                                return
                            end
                            if inCalmZone() and not isPlayerNear(hrp.Position, 400) then
                                return
                            end

                            local threat, threatD

                            for _, p in Players:GetPlayers()do
                                local ph = p ~= LocalPlayer and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                                if ph and not isCarriedByMe(p) then
                                    local d = (ph.Position - hrp.Position).Magnitude

                                    if d <= 220 and (not threatD or d < threatD) then
                                        threat, threatD = p, d
                                    end
                                end
                            end

                            if threat then
                                local curIdx, minD = 1, math.huge

                                for idx, pt in trinket_bot.active_points do
                                    if not pt.is_gate_point and not pt.action then
                                        local d = (pt.position - hrp.Position).Magnitude

                                        if d < minD then
                                            minD, curIdx = d, idx
                                        end
                                    end
                                end

                                botLog('In combat with a player nearby - fleeing along the path')
                                task.spawn(directionalEscape, curIdx, threat.Name)
                            end

                            return
                        end
                        if not state.iceDragonSkipIndex then
                            local dragon = Workspace:FindFirstChild('Ice Dragon')
                            local dr = dragon and dragon:FindFirstChild('HumanoidRootPart')

                            if dr and (dr.Position - hrp.Position).Magnitude <= ICE_DRAGON_RANGE then
                                local cur, minD = 1, math.huge

                                for idx, pt in trinket_bot.active_points do
                                    local d = (pt.position - hrp.Position).Magnitude

                                    if d < minD then
                                        minD = d
                                        cur = idx
                                    end
                                end

                                for idx = cur + 1, #trinket_bot.active_points do
                                    local pt = trinket_bot.active_points[idx]

                                    if pt.is_gate_point or (pt.position - dr.Position).Magnitude >= ICE_DRAGON_RANGE then
                                        state.iceDragonSkipIndex = idx

                                        break
                                    end
                                end
                            end
                        end
                        if Toggles.StayInServer.Value then
                            return
                        end

                        local critical = Options.CriticalDistance.Value
                        local proximity = Options.ProximityCheck.Value
                        local graced = tick() < (trinket_bot.spawnGraceUntil or 0)

                        if shriekAccum >= 0.25 then
                            shriekAccum = 0

                            local seen, which = false, nil

                            if critical > 0 and not shriekersIgnored() then
                                seen, which = detectShrieker(hrp.Position, critical, allyOf)
                            end

                            shriekSeen = seen and Threats.shriekerLabel(which) or false
                        end
                        if shriekSeen then
                            safeServerhop('Shrieker within critical distance (' .. shriekSeen .. ')')

                            return
                        end

                        local perfloraOn = Threats.labelAllowed(Options, 'Perflora')

                        for _, p in Players:GetPlayers()do
                            if p ~= LocalPlayer and not isCarriedByMe(p) then
                                local pchar = p.Character
                                local phrp = pchar and pchar:FindFirstChild('HumanoidRootPart')

                                if phrp and not Threats.inSpawnBox(phrp.Position) then
                                    local d = (phrp.Position - hrp.Position).Magnitude
                                    local pebbleTool = Threats.allowed(Options, 'pebble') and pchar:FindFirstChild('Pebble')

                                    if pebbleTool and pebbleTool:IsA('Tool') then
                                        pebbleHolders[p] = tick()

                                        if d <= PEBBLE_HOLD_RANGE then
                                            trinketBotServerhop(string.format('%s holding Pebble (%.0f studs)', p.Name, d))

                                            return
                                        end
                                    end

                                    local perflora = perfloraOn and pchar:FindFirstChild('Perflora')

                                    if perflora and perflora:IsA('Tool') then
                                        trinketBotServerhop(string.format('Perflora held by %s (%.0f studs)', p.Name, d))

                                        return
                                    end
                                    if smoothedPing > 150 then
                                        for name, range in DISTANCE_GATED_CONDITIONS do
                                            local held = d <= range and Threats.labelAllowed(Options, name) and pchar:FindFirstChild(name)

                                            if held and held:IsA('Tool') then
                                                trinketBotServerhop(string.format('%s holding %s (%.0f studs, high ping pre-emptive)', p.Name, name, d))

                                                return
                                            end
                                        end
                                    end

                                    local ally = ctx.State.isFriendly

                                    if not (ally and ally(p)) then
                                        local opal = smoothedPing > Threats.OPAL_HOLD_PING and d <= Threats.RANGE.opalHold and pchar:FindFirstChild('Opal Shard')

                                        if opal and opal:IsA('Tool') and Threats.labelAllowed(Options, 'Opal Shard') then
                                            trinketBotServerhop(string.format('%s holding Opal Shard (%.0f studs, %.0fms ping)', p.Name, d, smoothedPing))

                                            return
                                        end
                                        if critical > 0 and d < critical and not graced then
                                            trinketBotServerhop(p.Name .. ' within critical distance')

                                            return
                                        end
                                        if proximity > 0 and not graced and not state.emergency_gate_in_progress then
                                            local now = tick()
                                            local warning = state.proximity_warnings[p.UserId]

                                            if d < proximity then
                                                if warning then
                                                    warning.lastSeen = now
                                                else
                                                    warning = {
                                                        firstSeen = now,
                                                        lastSeen = now,
                                                        lastNotified = now,
                                                    }
                                                    state.proximity_warnings[p.UserId] = warning
                                                end
                                                if not state.emergency_gate_requested then
                                                    local enc = state.player_encounters[p.UserId]

                                                    if not enc then
                                                        state.player_encounters[p.UserId] = {
                                                            first_section = state.current_gate_section,
                                                            encounter_count = 1,
                                                        }

                                                        botLog(
[[Player %s within proximity (%d) - first encounter, emergency gate queued]], p.Name, proximity)

                                                        state.emergency_gate_requested = {
                                                            player = p.Name,
                                                        }
                                                    elseif enc.first_section ~= state.current_gate_section then
                                                        enc.encounter_count += 1

                                                        botLog('Repeat encounter with %s (#%d) - serverhopping', p.Name, enc.encounter_count)
                                                        safeServerhop(string.format('Repeat encounter with %s', p.Name))

                                                        return
                                                    else
                                                        botLog('Player %s still in the same section - emergency gating', p.Name)

                                                        state.emergency_gate_requested = {
                                                            player = p.Name,
                                                        }
                                                    end
                                                elseif now - warning.lastNotified >= 3 then
                                                    warning.lastNotified = now

                                                    botLog('Player %s still within %d studs (emergency gate pending)', p.Name, proximity)
                                                end
                                            elseif warning and now - warning.lastSeen > 3 then
                                                state.proximity_warnings[p.UserId] = nil
                                            end
                                        end
                                    end
                                end

                                detectGnav(p)
                            end
                        end
                    end))
                end

                local suppressTouch = BASIL_NO_VIRTUALIZE(function()
                    affectedBricks = {}
                    affectedCollide = {}

                    local container = (game.PlaceId == 5208655184 and Workspace:FindFirstChild('Map')) or (game.PlaceId == 3541987450 and Workspace) or Workspace:FindFirstChild('Map') or Workspace

                    for _, v in container:GetChildren()do
                        if v:IsA('BasePart') and v:FindFirstChild('TouchInterest') then
                            local disable = not (SAFE_BRICKS[v.Name] or MUST_TOUCH[v.BrickColor.Number]) or v.Name == 'Fire'

                            if disable and v.CanTouch then
                                v.CanTouch = false

                                table.insert(affectedBricks, v)
                            end
                        end
                    end
                    for _, v in container:GetDescendants()do
                        if v:IsA('BasePart') and (v.Name == 'OrderField' or v.Name == 'PurityField' or v.Name == 'MageField') then
                            if v.CanTouch then
                                v.CanTouch = false

                                table.insert(affectedBricks, v)
                            end
                            if v.CanCollide then
                                v.CanCollide = false

                                table.insert(affectedCollide, v)
                            end
                        end
                    end

                    bedsOff(true)

                    if not Toggles.BotNoMobTrigger or Toggles.BotNoMobTrigger.Value then
                        local monsters = Workspace:FindFirstChild('MonstersSpawns') or Workspace:FindFirstChild('MonsterSpawns')
                        local triggers = monsters and monsters:FindFirstChild('Triggers')

                        if triggers then
                            for _, obj in triggers:GetDescendants()do
                                if obj.ClassName == 'Part' and obj.CanTouch then
                                    pcall(function()
                                        obj.CanTouch = false
                                    end)
                                    table.insert(affectedBricks, obj)
                                end
                            end
                        end
                    end
                end)

                local function restoreTouch()
                    for _, v in affectedBricks do
                        if v and v.Parent then
                            pcall(function()
                                v.CanTouch = true
                            end)
                        end
                    end
                    for _, v in affectedCollide do
                        if v and v.Parent then
                            pcall(function()
                                v.CanCollide = true
                            end)
                        end
                    end

                    affectedBricks = {}
                    affectedCollide = {}
                end

                local pickupConn, trinketAddConn
                local trinketsList = {}
                local pickupReady = {}
                local KIND_NONE, KIND_MYTHIC, KIND_ICE, KIND_SCROLL, KIND_EVENT, KIND_TRINKET = 0, 1, 2, 3, 4, 5
                local describe = BASIL_NO_VIRTUALIZE(function(obj)
                    local info = state.trinketInfo[obj]

                    if not info then
                        local name, _, zindex = identify(obj)
                        local kind = KIND_NONE

                        if name then
                            if name == 'Azael Horn' or name == 'Phoenix Down' or name == 'Phoenix Flower' then
                                kind = KIND_MYTHIC
                            elseif name == 'Ice Essence' then
                                kind = KIND_ICE
                            elseif name:find('Scroll') then
                                kind = KIND_SCROLL
                            elseif zindex == 6 or zindex == 5 then
                                kind = KIND_MYTHIC
                            elseif zindex == 4 then
                                kind = KIND_EVENT
                            elseif zindex == 2 or zindex == 3 then
                                kind = KIND_TRINKET
                            end
                        end

                        info = {
                            name = name,
                            zindex = zindex,
                            kind = kind,
                            rank = pickupRank(name, zindex),
                        }
                        state.trinketInfo[obj] = info
                    end

                    return info
                end)
                local stopPickup

                local function startPickup()
                    if stopPickup then
                        stopPickup()
                    end

                    trinketsList = {}

                    for _, o in Workspace:GetChildren()do
                        if isTrinketPart(o) then
                            table.insert(trinketsList, o)
                        end
                    end

                    trinketAddConn = Workspace.ChildAdded:Connect(function(o)
                        if isTrinketPart(o) then
                            table.insert(trinketsList, o)
                        elseif o.Name == 'Part' then
                            task.delay(0.2, function()
                                if o.Parent and isTrinketPart(o) and not table.find(trinketsList, o) then
                                    table.insert(trinketsList, o)
                                end
                            end)
                        end
                    end)

                    local pickupAccum = 0

                    pickupConn = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                        dt
                    )
                        if not LocalPlayer.Character or not fireclickdetector or not trinket_bot.path_running then
                            return
                        end

                        pickupAccum += dt

                        if pickupAccum < 0.05 then
                            return
                        end

                        pickupAccum = 0

                        if state.currently_dropping then
                            return
                        end

                        local reGate = Toggles.BotReequipGate ~= nil and Toggles.BotReequipGate.Value == true
                        local char = LocalPlayer.Character
                        local bp = LocalPlayer:FindFirstChildOfClass('Backpack')
                        local hold = nil

                        if Toggles.BotHoldPebble and Toggles.BotHoldPebble.Value then
                            local first = Options.BotHoldItem and Options.BotHoldItem.Value == 'Pebble' and 'Pebble' or 'Perflora'
                            local other = first == 'Pebble' and 'Perflora' or 'Pebble'

                            if (bp and bp:FindFirstChild(first)) or (char and char:FindFirstChild(first)) then
                                hold = first
                            elseif (bp and bp:FindFirstChild(other)) or (char and char:FindFirstChild(other)) then
                                hold = other
                            end
                        end

                        local want = (tick() < (trinket_bot.gatingUntil or 0) and 'Gate') or path_tool or hold or (reGate and 'Gate') or nil

                        if want and tick() < drop_hold_until then
                            want = nil
                        end
                        if trinket_bot.talkHold and want ~= path_tool then
                            want = nil
                        end
                        if want then
                            local hum = char and char:FindFirstChildOfClass('Humanoid')

                            if want == 'Pebble' and bp and not bp:FindFirstChild('Pebble') and char and not char:FindFirstChild('Pebble') then
                                want = reGate and 'Gate' or nil
                            end
                            if want and hum and char and not char:FindFirstChild(want) then
                                local tool = bp and bp:FindFirstChild(want)

                                if tool and tool:IsA('Tool') then
                                    pcall(function()
                                        hum:EquipTool(tool)
                                    end)
                                end
                            end
                        end

                        for i = #trinketsList, 1, -1 do
                            local gone = trinketsList[i]

                            if not gone or not gone.Parent then
                                if gone then
                                    state.trinketInfo[gone] = nil
                                end

                                table.remove(trinketsList, i)
                            end
                        end

                        table.clear(pickupReady)

                        local mythics = (Options.PickupMythicsArtifacts and Options.PickupMythicsArtifacts.Value) or {}
                        local wantIce = Toggles.PickupIceEssence.Value
                        local wantScroll = Toggles.PickupScrolls.Value
                        local wantEvent = Toggles.PickupEventItems.Value
                        local wantTrinket = Toggles.PickupTrinkets.Value
                        local trinketTypes = (Options.PickupTrinketTypes and Options.PickupTrinketTypes.Value) or {}

                        for _, obj in trinketsList do
                            local info = state.trinketInfo[obj] or describe(obj)
                            local kind = info.kind
                            local want = (kind == KIND_MYTHIC and mythics[info.name] == true) or (kind == KIND_ICE and wantIce) or (kind == KIND_SCROLL and wantScroll) or (kind == KIND_EVENT and wantEvent) or (kind == KIND_TRINKET and (wantTrinket or trinketTypes[info.name] == true))

                            if want then
                                local cd = info.cd

                                if not cd then
                                    cd = obj:FindFirstChild('ClickDetector', true)
                                    info.cd = cd
                                end
                                if cd then
                                    local d = LocalPlayer:DistanceFromCharacter(obj.CFrame.Position)

                                    if d > 0 and d < cd.MaxActivationDistance then
                                        table.insert(pickupReady, {
                                            cd = cd,
                                            rank = info.rank,
                                            d = d,
                                        })
                                    end
                                end
                            end
                        end

                        if #pickupReady > 1 then
                            table.sort(pickupReady, rankThenDistance)
                        end

                        for _, entry in pickupReady do
                            fireclickdetector(entry.cd)
                        end
                    end))
                end

                function stopPickup()
                    if pickupConn then
                        pickupConn:Disconnect()

                        pickupConn = nil
                    end
                    if trinketAddConn then
                        trinketAddConn:Disconnect()

                        trinketAddConn = nil
                    end

                    trinketsList = {}

                    table.clear(state.trinketInfo)
                end

                ctx.Maid:Give(stopPickup)

                do
                    local firetouchinterest = firetouchinterest
                    local ingredientFolder, lastFolderScan = nil, 0
                    local activeIngredients = {}
                    local lastCheck, lastPos = 0, nil
                    local ingredientCds = {}
                    local ingredientMaid = Maid.new()

                    ctx.Maid:Give(ingredientMaid)

                    local function trackIngredient(object)
                        local cd = object:FindFirstChild('ClickDetector')

                        if cd then
                            ingredientCds[object] = cd
                        end
                    end
                    local function bindIngredientFolder(folder)
                        ingredientMaid:DoCleaning()
                        table.clear(ingredientCds)

                        if not folder then
                            return
                        end

                        for _, object in folder:GetChildren()do
                            trackIngredient(object)
                        end

                        ingredientMaid:Give(folder.ChildAdded:Connect(trackIngredient))
                        ingredientMaid:Give(folder.ChildRemoved:Connect(function(
                            object
                        )
                            ingredientCds[object] = nil
                        end))
                    end

                    local refreshActiveIngredients = BASIL_NO_VIRTUALIZE(function(
                        hrp
                    )
                        local now = tick()

                        if not (ingredientFolder and ingredientFolder.Parent) or now - lastFolderScan > 1 then
                            lastFolderScan = now

                            local found = ctx.State.findIngredientFolder and ctx.State.findIngredientFolder() or nil

                            if found ~= ingredientFolder then
                                ingredientFolder = found

                                bindIngredientFolder(found)
                            end
                        end

                        table.clear(activeIngredients)

                        for object, cd in ingredientCds do
                            if object.Parent then
                                local d = (object.Position - hrp.Position).Magnitude

                                if d > 0 and d < cd.MaxActivationDistance - 2 then
                                    table.insert(activeIngredients, cd)
                                end
                            else
                                ingredientCds[object] = nil
                            end
                        end
                    end)
                    local bagAccum = 0

                    ctx.Maid:Give(RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                        dt
                    )
                        if not trinket_bot.path_running then
                            ingredientFolder, activeIngredients, lastPos = nil, {}, nil

                            return
                        end

                        local char = LocalPlayer.Character
                        local hrp = char and char:FindFirstChild('HumanoidRootPart')

                        if not hrp then
                            return
                        end

                        bagAccum += dt

                        if Toggles.BotAutoBag and Toggles.BotAutoBag.Value and firetouchinterest and bagAccum >= 0.1 then
                            bagAccum = 0

                            local thrown = Workspace:FindFirstChild('Thrown')

                            if thrown then
                                local range = (Options.BotBagRange and Options.BotBagRange.Value) or 80

                                for _, object in thrown:GetChildren()do
                                    if object:IsA('BasePart') and object.Name:find('Bag') and (object.Position - hrp.Position).Magnitude <= range then
                                        firetouchinterest(object, hrp, 0)
                                        firetouchinterest(object, hrp, 1)
                                    end
                                end
                            end
                        end
                        if Toggles.BotAutoIngredient and Toggles.BotAutoIngredient.Value and fireclickdetector then
                            local now = tick()
                            local pos = hrp.Position

                            if lastPos == nil or now - lastCheck > 0.2 or (now - lastCheck > 0.1 and (pos - lastPos).Magnitude > 2) then
                                lastCheck, lastPos = now, pos

                                refreshActiveIngredients(hrp)
                            end

                            for _, cd in activeIngredients do
                                fireclickdetector(cd)
                            end
                        elseif #activeIngredients > 0 then
                            activeIngredients = {}
                        end
                    end)))
                end

                local checkForTrinkets = BASIL_NO_VIRTUALIZE(function(
                    center,
                    range
                )
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild('HumanoidRootPart')

                    if not root then
                        return
                    end

                    local origin = center or root.Position
                    local reach = (range and range > 0) and range or BOT.waitCover

                    table.clear(visitedPositions)

                    local targets = {}

                    for _, obj in trinketsList do
                        if obj.Parent then
                            local idVal = obj:FindFirstChild('ID')
                            local id = idVal and idVal.Value

                            if not (id and state.collectedIds[id]) and not alreadyVisited(obj.Position) then
                                local name, _, zindex = identify(obj)

                                if shouldPickup(name, zindex) then
                                    local d = (obj.CFrame.Position - origin).Magnitude

                                    if d <= reach then
                                        table.insert(targets, {
                                            obj = obj,
                                            id = id,
                                        })
                                    end
                                end
                            end
                        end
                    end

                    local anchor = root.Position

                    while#targets > 0 do
                        if not trinket_bot.path_running or state.unloaded or state.emergency_gate_requested or trinket_bot.moderator_detected then
                            break
                        end

                        table.sort(targets, function(a, b)
                            return (a.obj.Position - anchor).Magnitude < (b.obj.Position - anchor).Magnitude
                        end)

                        local t = table.remove(targets, 1)

                        if t.obj.Parent then
                            local at = t.obj.Position
                            local cd = t.obj:FindFirstChild('ClickDetector', true)
                            local reach = LocalPlayer:DistanceFromCharacter(t.obj.CFrame.Position)

                            if not (cd and reach > 0 and reach < cd.MaxActivationDistance) then
                                SmoothTeleport(at, true)

                                anchor = at

                                task.wait(math.max(0.18, pingWait()))
                            end

                            recordVisited(at)

                            if cd and fireclickdetector then
                                fireclickdetector(cd)
                                task.wait(math.max(0.18, pingWait()))

                                if t.id then
                                    markCollected(t.id)
                                end
                            end
                        end
                    end
                end)

                local function mineNode()
                    local char = LocalPlayer.Character
                    local hum = char and char:FindFirstChildOfClass('Humanoid')
                    local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')

                    if not (hum and backpack) then
                        return false
                    end

                    local pick = backpack:FindFirstChild('Pickaxe') or char:FindFirstChild('Pickaxe')

                    if not pick then
                        botLog("Node: no Pickaxe in backpack/character - can't mine")

                        return false
                    end

                    hum:UnequipTools()
                    hum:EquipTool(pick)

                    for _ = 1, 8 do
                        pcall(function()
                            pick:Activate()
                        end)
                        hum:UnequipTools()
                    end

                    hum:EquipTool(pick)

                    return true
                end

                function isOreNode(obj)
                    if not obj:IsA('BasePart') then
                        return false
                    end

                    local emitter = obj:FindFirstChild('Emitter')

                    return emitter ~= nil and emitter:IsA('ParticleEmitter')
                end
                function nodeOreFilter()
                    local sel = (Options.NodeOres and Options.NodeOres.Value) or {}
                    local set, any = {}, false

                    for name, on in sel do
                        if on == true then
                            set[name] = true
                            any = true
                        end
                    end

                    if not any then
                        return nil
                    end

                    return set
                end

                local function oneCenter(positions)
                    local n = #positions

                    if n == 0 then
                        return nil
                    end
                    if n == 1 then
                        return positions[1]
                    end

                    local c = Vector3.zero

                    for _, p in positions do
                        c += p
                    end

                    c /= n

                    for i = 1, 300 do
                        local far, farD

                        for _, p in positions do
                            local d = (p - c).Magnitude

                            if not farD or d > farD then
                                far, farD = p, d
                            end
                        end

                        c += (far - c) / (i + 1)
                    end

                    return c
                end
                local function clusterNodes(nodes, anchor)
                    local remaining = {}

                    for _, n in nodes do
                        table.insert(remaining, n)
                    end

                    local clusters = {}

                    while#remaining > 0 do
                        local count = #remaining
                        local best

                        local function consider(idxs)
                            local pts = {}

                            for _, i in idxs do
                                table.insert(pts, remaining[i].Position)
                            end

                            local c = oneCenter(pts)
                            local radius = 0

                            for _, p in pts do
                                local d = (p - c).Magnitude

                                if d > radius then
                                    radius = d
                                end
                            end

                            if radius > NODE_REACH then
                                return
                            end
                            if not best or #idxs > #best.idxs or (#idxs == #best.idxs and radius < best.radius) then
                                best = {
                                    idxs = idxs,
                                    center = c,
                                    radius = radius,
                                }
                            end
                        end
                        local function near(i, j)
                            return (remaining[i].Position - remaining[j].Position).Magnitude <= 2 * NODE_REACH
                        end

                        for i = 1, count do
                            consider({i})

                            for j = i + 1, count do
                                if near(i, j) then
                                    consider({i, j})

                                    for k = j + 1, count do
                                        if near(i, k) and near(j, k) then
                                            consider({i, j, k})
                                        end
                                    end
                                end
                            end
                        end

                        local chosen = {}

                        for _, i in best.idxs do
                            table.insert(chosen, remaining[i])
                        end

                        table.sort(best.idxs, function(a, b)
                            return a > b
                        end)

                        for _, i in best.idxs do
                            table.remove(remaining, i)
                        end

                        table.insert(clusters, {
                            center = best.center,
                            nodes = chosen,
                        })
                    end

                    table.sort(clusters, function(a, b)
                        return (a.center - anchor).Magnitude < (b.center - anchor).Magnitude
                    end)

                    return clusters
                end
                local function checkForNodes(point, idx)
                    local ores = Workspace:FindFirstChild('Ores')

                    if not ores then
                        botLog('Node point %d: no workspace.Ores', idx or 0)

                        return
                    end

                    local range = tonumber(point.node_range) or 150
                    local filter = nodeOreFilter()
                    local center = point.position
                    local targets, seenTypes = {}, {}

                    for _, node in ores:GetChildren()do
                        if isOreNode(node) then
                            seenTypes[node.Name] = true

                            if node.Transparency < 1 and (filter == nil or filter[node.Name]) then
                                if (node.Position - center).Magnitude <= range then
                                    table.insert(targets, node)
                                end
                            end
                        end
                    end

                    local typeList = {}

                    for n in seenTypes do
                        table.insert(typeList, n)
                    end

                    local filterDesc = 'all'

                    if filter ~= nil then
                        local names = {}

                        for n in filter do
                            table.insert(names, n)
                        end

                        filterDesc = table.concat(names, ',')
                    end

                    botLog(
[[Node point %d: %d unmined node(s) within %d studs | filter=%s | ores present: %s]], idx or 0, #targets, range, filterDesc, table.concat(typeList, ', '))

                    local clusters = clusterNodes(targets, center)

                    for _, c in clusters do
                        if not trinket_bot.path_running or state.unloaded or state.emergency_gate_requested or trinket_bot.moderator_detected then
                            break
                        end

                        SmoothTeleport(c.center, true)

                        local mineHum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                        if mineHum then
                            mineHum:SetStateEnabled(5, false)
                            mineHum:ChangeState(3)
                        end

                        local pinCF = CFrame.new(c.center)
                        local mineLock = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                        )
                            local cc = LocalPlayer.Character
                            local rr = cc and cc:FindFirstChild('HumanoidRootPart')

                            if rr then
                                Character.noclip(cc)

                                rr.CFrame = pinCF
                                rr.AssemblyLinearVelocity = Vector3.zero
                            end
                        end))

                        task.wait(0.18)

                        for _ = 1, 3 do
                            mineNode()
                            task.wait(0.18)

                            local left = false

                            for _, n in c.nodes do
                                if n.Parent and n.Transparency < 1 then
                                    left = true

                                    break
                                end
                            end

                            if not left then
                                break
                            end
                        end

                        mineLock:Disconnect()
                        botLog(
[[Node cluster: %d node(s) mined from middle (%.0f, %.0f, %.0f)]], #c.nodes, c.center.X, c.center.Y, c.center.Z)
                    end
                end

                local opportunisticDetour = BASIL_NO_VIRTUALIZE(function(
                    currentPos,
                    fromIndex,
                    center,
                    range
                )
                    local cover = (range and range > 0) and range or BOT.waitCover

                    for _, obj in trinketsList do
                        if not trinket_bot.path_running or trinket_bot.escaping then
                            break
                        end
                        if obj.Parent then
                            local idVal = obj:FindFirstChild('ID')
                            local id = idVal and idVal.Value

                            if not (id and state.collectedIds[id]) and not alreadyVisited(obj.Position) then
                                local name, _, zindex = identify(obj)

                                if (zindex == 6 or zindex == 5) and Options.PickupMythicsArtifacts.Value[name] == true then
                                    local away = (obj.Position - currentPos).Magnitude

                                    if away < 150 and (not center or (obj.Position - center).Magnitude <= cover) then
                                        local nearWait = false

                                        for j = fromIndex, #trinket_bot.active_points do
                                            local pt = trinket_bot.active_points[j]

                                            if pt.wait_for_trinket and (obj.Position - pt.position).Magnitude <= (tonumber(pt.trinket_range) or BOT.waitCover) then
                                                nearWait = true

                                                break
                                            end
                                        end

                                        if not nearWait then
                                            local msg = string.format('Detouring for %s (%.0f studs)', tostring(name), away)

                                            botLog('%s', msg)
                                            Notify.say(msg)

                                            if id then
                                                markCollected(id)
                                            end

                                            SmoothTeleport(obj.Position, true)
                                            recordVisited(obj.Position)
                                            task.wait(0.18)

                                            local cd = obj:FindFirstChild('ClickDetector', true)

                                            if cd and fireclickdetector then
                                                fireclickdetector(cd)
                                                task.wait(0.18)
                                            end
                                            if trinket_bot.path_running and not trinket_bot.escaping then
                                                SmoothTeleport(currentPos)
                                                task.wait(0.2)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end)

                local function botRunAutoTrinket(suppress)
                    local toggle = Toggles.AutoTrinket

                    if suppress then
                        if not toggle then
                            return
                        end
                        if not MemStore.has('autotrinket_was') then
                            MemStore.set('autotrinket_was', toggle.Value and 'true' or 'false')
                        end
                        if toggle.Value then
                            toggle:SetValue(false)
                        end

                        return
                    end

                    local was = MemStore.get('autotrinket_was')

                    if was == nil then
                        return
                    end

                    MemStore.remove('autotrinket_was')

                    if was == 'true' and toggle then
                        toggle:SetValue(true)
                    end
                end
                local function restoreBotState()
                    local char = LocalPlayer.Character

                    if not char then
                        return
                    end

                    for _, part in char:GetDescendants()do
                        if part:IsA('BasePart') and part.Name ~= 'HumanoidRootPart' then
                            part.CanCollide = part.Name == 'Head' or part.Name == 'Torso'
                        end
                    end

                    local hum = char:FindFirstChildOfClass('Humanoid')

                    if hum then
                        hum:SetStateEnabled(5, true)
                        hum:ChangeState(5)
                    end

                    local hrp = char:FindFirstChild('HumanoidRootPart')

                    if hrp then
                        hrp.Anchored = false
                    end
                end

                ctx.Maid:Give(function()
                    pcall(restoreTouch)

                    if MemStore.get('botstarted') == 'true' then
                        pcall(restoreBotState)

                        if getconnections then
                            pcall(function()
                                for _, c in getconnections(LocalPlayer.Idled)do
                                    c:Enable()
                                end
                            end)
                        end

                        MemStore.remove('botstarted')
                        MemStore.remove('serverhop_count')
                    end
                end)

                local function branchSafeStart(startIdx)
                    local level, openAt = 0, nil

                    for i = 1, math.min(startIdx, #trinket_bot.path_points)do
                        local action = trinket_bot.path_points[i].action

                        if action == 'if' or action == 'loop' then
                            if level == 0 then
                                openAt = i
                            end

                            level += 1
                        elseif action == 'endif' or action == 'endloop' then
                            level = math.max(0, level - 1)

                            if level == 0 then
                                openAt = nil
                            end
                        end
                    end

                    return (level > 0 and openAt) or startIdx
                end

                local setActiveFromStart = BASIL_NO_VIRTUALIZE(function(
                    startIdx
                )
                    startIdx = startIdx and branchSafeStart(startIdx) or startIdx

                    if startIdx and startIdx > 1 and startIdx <= #trinket_bot.path_points then
                        local rotated = {}

                        for k = startIdx, #trinket_bot.path_points do
                            table.insert(rotated, trinket_bot.path_points[k])
                        end
                        for k = 1, startIdx - 1 do
                            table.insert(rotated, trinket_bot.path_points[k])
                        end

                        trinket_bot.active_points = rotated
                        trinket_bot.lap_end_index = #rotated - startIdx + 2
                    else
                        trinket_bot.active_points = trinket_bot.path_points
                        trinket_bot.lap_end_index = nil
                    end
                end)

                local function recoverToPath(root)
                    local closest, closestD = nil, math.huge

                    for idx, pt in trinket_bot.path_points do
                        if not pt.is_gate_point and not pt.action then
                            local d = (pt.position - root.Position).Magnitude

                            if d < closestD then
                                closestD = d
                                closest = idx
                            end
                        end
                    end

                    if closest and closestD <= 1500 then
                        botLog(
[[Recovery: resuming at nearby point %d (%.0f studs from here)]], closest, closestD)
                        MemStore.remove('stranded_count')
                        MemStore.remove('stranded_cleared')
                        setActiveFromStart(closest)

                        return true
                    end

                    local firstGate

                    for idx, pt in trinket_bot.path_points do
                        if pt.is_gate_point then
                            firstGate = idx

                            break
                        end
                    end

                    if firstGate then
                        local dest = (trinket_bot.path_points[firstGate + 1] or trinket_bot.path_points[1]).position

                        botLog(
[[Recovery: nothing within 1500 - gating to the first gate (point %d -> %s) for a fresh run]], firstGate, tostring(trinket_bot.path_points[firstGate].gate_location))

                        local budget = tick() + RECOVERY_BUDGET

                        for attempt = 1, GATE_RETRIES do
                            if not trinket_bot.path_running then
                                return false
                            end
                            if tick() > budget then
                                botLog('Recovery: %ds spent trying to gate back, hopping instead', RECOVERY_BUDGET)
                                safeServerhop('could not gate back onto the path in time')

                                return false
                            end

                            forceFieldStrip()

                            local shielded = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('ForceField')

                            if shielded then
                                botLog(
[[Recovery: spawn shield still up on attempt %d, hopping rather than casting into it]], attempt)
                                safeServerhop('could not clear the spawn shield to gate back onto the path')

                                return false
                            end
                            if gateStabilized(trinket_bot.path_points[firstGate].gate_location, dest) then
                                MemStore.remove('stranded_count')
                                MemStore.remove('stranded_cleared')
                                setActiveFromStart(firstGate + 1)

                                return true
                            end

                            task.wait(0.5)
                        end

                        botLog('Recovery: gating to the first gate failed after %d tries', GATE_RETRIES)
                    end

                    local char = LocalPlayer.Character
                    local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
                    local heldGate = (char and char:FindFirstChild('Gate')) or (backpack and backpack:FindFirstChild('Gate'))
                    local why = string.format(
[[no point within 1500, gate tool %s, %d gate points in the path]], heldGate and 'held' or 'missing', firstGate and 1 or 0)
                    local stranded = (tonumber(MemStore.get('stranded_count')) or 0) + 1

                    MemStore.set('stranded_count', stranded)

                    if stranded >= STRANDED_LIMIT then
                        if MemStore.get('stranded_cleared') ~= 'true' then
                            MemStore.set('stranded_cleared', 'true')
                            MemStore.set('stranded_count', 0)
                            Serverhop.clearVisited(game.PlaceId)
                            botLog(
[[Recovery: stranded %d servers running (%s) - clearing the server history and going round again]], stranded, why)
                            Webhook.text(string.format(
[[@everyone Bot stranded on %d servers (%s) - cleared server history, trying again]], stranded, why))
                            safeServerhop('stranded far from the path')

                            return false
                        end

                        botLog(
[[Recovery: stranded %d servers running on a clean history (%s) - kicking]], stranded, why)
                        Webhook.textBounded(string.format(
[[@everyone Bot stranded on %d servers with a clean history (%s) - kicking]], stranded, why))

                        trinket_bot.path_running = false

                        MemStore.remove('botstarted')
                        MemStore.remove('stranded_count')
                        MemStore.remove('stranded_cleared')
                        botKick(
[[sentinel: stranded from path - kicked to stop serverhop loop]])

                        return false
                    end

                    botLog('Recovery: stranded (%s) - hopping (%d/%d)', why, stranded, STRANDED_LIMIT)
                    Webhook.text(string.format('@everyone Bot stranded from the path (%s) - hopping (%d/%d)', why, stranded, STRANDED_LIMIT))
                    safeServerhop('stranded far from the path')

                    return false
                end

                ExecutePath = function(testMode)
                    if trinket_bot.path_running then
                        Notify.say('Path already running')

                        return
                    end
                    if #trinket_bot.path_points == 0 then
                        Notify.say('No path points recorded')

                        return
                    end

                    local blankTp = 0

                    for idx, p in trinket_bot.path_points do
                        if p.action == 'menutele' and tostring(p.target or ''):match('^%s*$') then
                            blankTp += 1

                            botLog('Menu TP on point %d has no destination set', idx)
                        end
                    end

                    if blankTp > 0 then
                        Library:Notify({
                            Title = 'sentinel.bz',
                            Description = string.format(
[[%d Menu TP point%s ha%s no destination - set one or the path will not work]], blankTp, blankTp == 1 and '' or 's', blankTp == 1 and 's' or 've'),
                        })
                    end

                    local resumeStartIdx = trinket_bot.resume_start_index

                    trinket_bot.resume_start_index = nil
                    trinket_bot.menuTeleFailed = nil
                    trinket_bot.innFailed = nil

                    if not resumeStartIdx then
                        MemStore.remove(MENUTELE_FAIL)
                    end
                    if spectatingPoint then
                        spectatingPoint = nil

                        if ctx.State.freecamOff then
                            ctx.State.freecamOff()
                        end

                        Workspace.CurrentCamera.CameraType = Enum.CameraType.Custom

                        local spectChar = LocalPlayer.Character
                        local spectHum = spectChar and spectChar:FindFirstChildOfClass('Humanoid')

                        if spectHum then
                            Workspace.CurrentCamera.CameraSubject = spectHum
                        end
                    end

                    trinket_bot.test_mode = testMode == true
                    trinket_bot.stopped = false
                    trinket_bot.moderator_detected = false
                    trinket_bot.kickAfterPath = false
                    trinket_bot.hopping = false
                    trinket_bot.hopCommitted = false
                    trinket_bot.escaping = false
                    trinket_bot.startGraceUntil = tick() + 10
                    trinket_bot.skipCastleRock = false
                    state.emergency_gate_requested = nil
                    state.emergency_gate_in_progress = false
                    state.current_gate_section = 0

                    table.clear(state.player_encounters)
                    table.clear(state.proximity_warnings)

                    state.gnavDetected = false
                    state.gnavPlayerName = nil
                    state.iceDragonSkipIndex = nil
                    state.fimbulEscape = false
                    state.spearEscape = false

                    table.clear(state.collectedIds)
                    table.clear(visitedPositions)
                    table.clear(trinket_bot.collected_order)

                    local serverhopCount = tonumber(MemStore.get('serverhop_count')) or 0
                    local blatant = Toggles.BlatantMode and Toggles.BlatantMode.Value

                    if not blatant and serverhopCount < 1 and not trinket_bot.test_mode then
                        Notify.say('Enable Blatant Mode (Settings) to start the bot')

                        return
                    end

                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild('HumanoidRootPart')

                    if not root then
                        Notify.say('No character')

                        return
                    end
                    if not resumeStartIdx then
                        local first = trinket_bot.path_points[1]
                        local away = first and (root.Position - first.position).Magnitude or math.huge

                        if away > BOT.nearStart then
                            local closest, closestD = nil, math.huge

                            for idx, pt in trinket_bot.path_points do
                                if not pt.is_gate_point and not pt.action then
                                    local d = (pt.position - root.Position).Magnitude

                                    if d < closestD then
                                        closestD, closest = d, idx
                                    end
                                end
                            end

                            if closest and closestD <= BOT.nearStart then
                                resumeStartIdx = closest
                                trinket_bot.skip_distance_check = true

                                botLog(
[[Start: %.0f studs from point 1, starting at the nearest point %d instead (%.0f studs away)]], away, closest, closestD)
                            end
                        end
                    end
                    if not trinket_bot.skip_distance_check and not Toggles.StayInServer.Value and not trinket_bot.path_points[1].is_gate_point and not trinket_bot.path_points[1].action then
                        if (root.Position - trinket_bot.path_points[1].position).Magnitude > 400 then
                            Notify.say('Too far from path start (>400 studs)')

                            return
                        end
                    end

                    trinket_bot.skip_distance_check = false

                    if not Toggles.StayInServer.Value then
                        local startProximity = (Options.ProximityCheck and Options.ProximityCheck.Value) or 0

                        if startProximity > 0 then
                            local ally = ctx.State.isFriendly

                            for _, p in Players:GetPlayers()do
                                local phrp = p ~= LocalPlayer and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                                if phrp and not (ally and ally(p)) and not isCarriedByMe(p) and (phrp.Position - root.Position).Magnitude <= startProximity then
                                    trinket_bot.path_running = false

                                    local why = string.format('%s is within %d studs - cannot start path', p.Name, math.floor(startProximity))

                                    Notify.say(why)
                                    botLog('%s', why)

                                    if not trinket_bot.test_mode and MemStore.get('botstarted') == 'true' then
                                        trinketBotServerhop(string.format('%s within %d studs at spawn - cannot start path', p.Name, math.floor(startProximity)))
                                    end

                                    return
                                end
                            end
                        end
                    end

                    setActiveFromStart(resumeStartIdx)
                    botRunAutoTrinket(true)

                    path_tool = nil
                    trinket_bot.talkHold = nil
                    trinket_bot.path_running = true

                    applyBotFps()

                    trinket_bot.spawnShieldUntil = tick() + SPAWN_SHIELD_GRACE

                    startLootTracking()
                    botLog('Path started (%s, %d points)', trinket_bot.test_mode and 'test' or 'live', #trinket_bot.active_points)
                    setStopVisible(true)

                    if not trinket_bot.test_mode then
                        MemStore.set('botstarted', 'true')
                        BotClaims.claim(game.JobId)

                        if not MemStore.has('serverhop_count') then
                            MemStore.set('serverhop_count', 0)
                        end

                        MemStore.set('trinket_bot_path', trinket_bot.current_path_name)
                        MemStore.setJSON('trinket_bot_settings', captureSettings())

                        if getconnections then
                            pcall(function()
                                for _, c in getconnections(LocalPlayer.Idled)do
                                    c:Disable()
                                end
                            end)
                        end
                    end

                    local stationary = pathStationary(trinket_bot.active_points)
                    local hum = char:FindFirstChildOfClass('Humanoid')

                    if hum and not stationary then
                        hum:SetStateEnabled(5, false)
                        hum:ChangeState(3)
                    end

                    suppressTouch()
                    startPickup()
                    setupThreats()
                    pcall(setupBackpackMonitoring)
                    task.spawn(function()
                        local ffHrp = not stationary and not Toggles.StayInServer.Value and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        if ffHrp then
                            local near, who = isPlayerNear(ffHrp.Position, SPAWN_WATCH_RANGE)

                            if near then
                                botLog(
[[%s within %d studs of the spawn - hopping rather than stripping the shield in front of them]], tostring(who), SPAWN_WATCH_RANGE)
                                trinketBotServerhop(string.format('%s watching the spawn before the shield strip', tostring(who)))

                                return
                            end
                        end
                        if not stationary then
                            forceFieldStrip()
                        end

                        local firstPt = trinket_bot.active_points[1]
                        local rRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        if rRoot and firstPt and not firstPt.is_gate_point and not firstPt.action and (rRoot.Position - firstPt.position).Magnitude > 1500 then
                            botLog(
[[Resume: %.0f studs from the path start - forced respawn, recovering]], (rRoot.Position - firstPt.position).Magnitude)

                            if not recoverToPath(rRoot) then
                                return
                            end
                        end

                        local branchMap = resolveBranches(trinket_bot.active_points)
                        local loopLeft = {}
                        local i = 1

                        while i <= #trinket_bot.active_points and trinket_bot.path_running and not trinket_bot.moderator_detected do
                            local point = trinket_bot.active_points[i]

                            trinket_bot.current_index = i

                            if trinket_bot.skipCastleRock then
                                trinket_bot.skipCastleRock = false

                                local out = castleRockExit(trinket_bot.active_points, i)

                                if out and out > i then
                                    botLog('Castle Rock skipped: point %d -> %d', i, out)

                                    i = out
                                    point = trinket_bot.active_points[i]
                                elseif not out then
                                    botLog(
[[Castle Rock skipped and nothing follows it - ending the path here]])

                                    break
                                end
                            end

                            local escapeWait = 0

                            while trinket_bot.escaping and trinket_bot.path_running and escapeWait < ESCAPE_HOLD_MAX do
                                task.wait(0.2)

                                escapeWait += 0.2
                            end

                            if trinket_bot.escaping and trinket_bot.path_running then
                                botLog(
[[Escape flag stuck for %ds, clearing it rather than standing here]], ESCAPE_HOLD_MAX)

                                trinket_bot.escaping = false
                            end
                            if not waitForSpawn() then
                                botLog(
[[Still not placed after %ds - hopping rather than sitting here]], LOADING_PAD_WAIT)
                                safeServerhop(string.format('character never placed after %ds', LOADING_PAD_WAIT))

                                return
                            end

                            local pingCeiling = (Options.TrinketBotPing and Options.TrinketBotPing.Value) or 500

                            if pingCeiling > 0 and smoothedPing > pingCeiling then
                                botLog('Ping %.0fms over the %.0fms limit - serverhopping', smoothedPing, pingCeiling)

                                trinket_bot.path_running = false

                                trinketBotServerhop(string.format('Ping %.0fms too high to continue', smoothedPing))

                                return
                            end
                            if trinket_bot.lap_end_index and i >= trinket_bot.lap_end_index then
                                botLog('Completed lap to original point 1 - serverhopping')

                                trinket_bot.path_running = false

                                trinketBotServerhop('Run complete', nil, true)

                                return
                            end
                            if state.emergency_gate_requested and not Toggles.StayInServer.Value then
                                local emergencyPlayer = (type(state.emergency_gate_requested) == 'table' and state.emergency_gate_requested.player) or 'unknown'

                                state.emergency_gate_requested = nil
                                state.emergency_gate_in_progress = true

                                botLog('Emergency at point %d/%d: %s too close', i, #trinket_bot.active_points, emergencyPlayer)

                                local pts = trinket_bot.active_points
                                local escapedAt, searchFrom = nil, i + 1

                                while not escapedAt and trinket_bot.path_running and not trinket_bot.moderator_detected do
                                    local gateIdx = nextClearGate(pts, searchFrom, isPlayerNear, emergencyGateClear, function(
                                        j,
                                        who,
                                        isLast
                                    )
                                        noteGateBlocked(j, #pts, who, isLast)
                                    end)

                                    if not gateIdx then
                                        break
                                    end

                                    local groundFrom = i

                                    for attempt = 1, GATE_RETRIES do
                                        if not trinket_bot.path_running or trinket_bot.moderator_detected then
                                            break
                                        end
                                        if attempt > 1 then
                                            botLog('Emergency gate %d retry %d', gateIdx, attempt)
                                            task.wait(0.5)

                                            groundFrom += 1
                                        end
                                        if gateStabilized(pts[gateIdx].gate_location, gateExpectedDest(gateIdx), groundFrom, threatPosition(emergencyPlayer)) then
                                            escapedAt = gateIdx

                                            break
                                        end
                                    end

                                    if not escapedAt then
                                        botLog(
[[Emergency gate %d failed after %d attempts - trying the next gate]], gateIdx, GATE_RETRIES)

                                        searchFrom = gateIdx + 1
                                    end
                                end

                                if escapedAt then
                                    state.emergency_gate_in_progress = false

                                    botLog(
[[Emergency: gated through point %d, resuming at %d (escaped %s)]], escapedAt, escapedAt + 1, emergencyPlayer)

                                    i = escapedAt + 1

                                    continue
                                end
                                if pathHasGates() then
                                    local msg = string.format('No clear gate point available - serverhopping to escape %s', emergencyPlayer)

                                    botLog('%s', msg)
                                    Notify.say(msg)

                                    state.emergency_gate_in_progress = false
                                    trinket_bot.path_running = false

                                    trinketBotServerhop(string.format('No clear gate point while escaping %s', emergencyPlayer))

                                    return
                                end

                                botLog(
[[Emergency: no gates on this path - escaping along it from %s]], emergencyPlayer)
                                directionalEscape(i, emergencyPlayer)

                                state.emergency_gate_in_progress = false

                                return
                            end
                            if point.action and BRANCH_KINDS[point.action] then
                                local node = branchMap[i]

                                if point.action == 'if' then
                                    if conditionMet(point.condition) then
                                        botLog('Branch at %d taken (%s)', i, conditionText(point.condition))

                                        i += 1
                                    else
                                        local to = node and ((node.elseAt and node.elseAt + 1) or (node.endAt + 1)) or i + 1

                                        botLog('Branch at %d not taken (%s) - jumping to %d', i, conditionText(point.condition), to)

                                        i = to
                                    end
                                elseif point.action == 'else' then
                                    i = node and (node.endAt + 1) or i + 1
                                elseif point.action == 'loop' then
                                    local runs = math.floor(tonumber(point.times) or 0)

                                    loopLeft[i] = runs > 0 and runs - 1 or math.huge

                                    i += 1
                                elseif point.action == 'endloop' then
                                    local openAt = node and node.loopAt
                                    local left = openAt and loopLeft[openAt]

                                    if left and left > 0 then
                                        loopLeft[openAt] = left - 1

                                        local base, removed = trinket_bot.active_points[openAt].subDepth or 0, 0

                                        for k = i - 1, openAt + 1, -1 do
                                            if (trinket_bot.active_points[k].subDepth or 0) > base then
                                                table.remove(trinket_bot.active_points, k)

                                                removed += 1
                                            end
                                        end

                                        if removed > 0 then
                                            if trinket_bot.lap_end_index and trinket_bot.lap_end_index > openAt then
                                                trinket_bot.lap_end_index -= removed
                                            end

                                            branchMap = resolveBranches(trinket_bot.active_points)
                                        end

                                        botLog('Loop at %d: back to the top%s', openAt, left == math.huge and '' or string.format(', %d more after this', left - 1))

                                        i = openAt + 1

                                        task.wait()
                                    else
                                        i += 1
                                    end
                                else
                                    i += 1
                                end

                                continue
                            end
                            if point.condition and not conditionMet(point.condition) then
                                botLog('Skipped %s %d, %s is not true', point.is_gate_point and 'gate' or 'point', i, conditionText(point.condition))

                                i += 1

                                continue
                            end
                            if Dialogue.inDialogue() and point.action ~= 'captcha' then
                                holdInPlace(function()
                                    return trinket_bot.path_running and not trinket_bot.moderator_detected and Dialogue.inDialogue()
                                end)

                                if not trinket_bot.path_running then
                                    return
                                end
                            end
                            if point.action == 'subpath' then
                                local runs = math.max(1, math.floor(tonumber(point.times) or 1))
                                local depth = (point.subDepth or 0) + 1
                                local added, why

                                if depth > BOT.subDepth then
                                    why = string.format("Run Path: '%s' nested %d deep, skipping", tostring(point.target), depth)
                                else
                                    added, why = subPathRun(trinket_bot, i, point.target, runs - 1, point.condition, depth)
                                end
                                if why then
                                    botLog('%s', why)
                                else
                                    botLog('Run Path: %s (%d points, %d run%s)', tostring(point.target), added, runs, runs == 1 and '' or 's')

                                    branchMap = resolveBranches(trinket_bot.active_points)
                                end

                                i += 1

                                continue
                            end
                            if point.action == '__subend' then
                                if point.left > 0 and (point.cond == nil or conditionMet(point.cond)) then
                                    local added, why = subPathRun(trinket_bot, i, point.target, point.left - 1, point.cond, point.subDepth or 1)

                                    if why then
                                        botLog('%s', why)
                                    else
                                        botLog('Run Path: %s again, %d run%s left after this', tostring(point.target), point.left - 1, point.left == 2 and '' or 's')

                                        branchMap = resolveBranches(trinket_bot.active_points)
                                    end
                                end

                                i += 1

                                continue
                            end
                            if point.action then
                                if not (point.action == 'walkto' or RELOCATING_ACTIONS[point.action] or NON_POSITIONAL[point.action]) then
                                    SmoothTeleport(point.position, nil, nil, true)
                                end

                                runPathAction(point)

                                if trinket_bot.branchesStale then
                                    trinket_bot.branchesStale = nil
                                    branchMap = resolveBranches(trinket_bot.active_points)
                                end
                                if trinket_bot.menuTeleFailed then
                                    handleMenuTeleFail(trinket_bot.menuTeleFailed)

                                    return
                                end
                                if trinket_bot.innFailed then
                                    local inn = trinket_bot.innFailed

                                    trinket_bot.innFailed = nil

                                    handleRelocateFail('Set Inn ' .. inn .. ' failed', 'inn:' .. inn)

                                    return
                                end

                                waitAtPoint(point, trinket_bot)

                                i += 1

                                continue
                            end
                            if state.gnavDetected then
                                if Toggles.StayInServer.Value then
                                    state.gnavDetected = false
                                else
                                    local lastGate

                                    for j = #trinket_bot.active_points, 1, -1 do
                                        if trinket_bot.active_points[j].is_gate_point then
                                            lastGate = j

                                            break
                                        end
                                    end

                                    if lastGate and gateStabilized(trinket_bot.active_points[lastGate].gate_location, gateExpectedDest(lastGate)) then
                                        i = lastGate + 1
                                        state.gnavDetected = false

                                        continue
                                    end

                                    trinketBotServerhop('GNAV detected (' .. tostring(state.gnavPlayerName) .. ')')

                                    return
                                end
                            end
                            if state.iceDragonSkipIndex and state.iceDragonSkipIndex > i then
                                local sp = trinket_bot.active_points[state.iceDragonSkipIndex]

                                if sp then
                                    if sp.is_gate_point then
                                        if not gateStabilized(sp.gate_location, gateExpectedDest(state.iceDragonSkipIndex)) then
                                            SmoothTeleport(sp.position)
                                            task.wait(0.5)
                                        end
                                    else
                                        SmoothTeleport(sp.position)
                                        task.wait(0.5)
                                    end

                                    i = state.iceDragonSkipIndex + 1
                                end

                                state.iceDragonSkipIndex = nil

                                continue
                            elseif state.iceDragonSkipIndex then
                                state.iceDragonSkipIndex = nil
                            end
                            if point.is_gate_point then
                                local stayIn = Toggles.StayInServer.Value
                                local pts = trinket_bot.active_points
                                local gated, searchFrom = false, i

                                while not gated do
                                    if not trinket_bot.path_running or trinket_bot.moderator_detected then
                                        return
                                    end
                                    if state.emergency_gate_requested then
                                        break
                                    end

                                    local gateIdx = i

                                    if not stayIn then
                                        gateIdx = nextClearGate(pts, searchFrom, isPlayerNear, traversalGateClear, function(
                                            j,
                                            who,
                                            isLast
                                        )
                                            noteGateBlocked(j, #pts, who, isLast)
                                        end)

                                        if not gateIdx then
                                            break
                                        end
                                        if preGateCritical() then
                                            return
                                        end
                                        if gateIdx ~= i then
                                            botLog('Gate %d blocked, skipping to gate %d', i, gateIdx)

                                            i = gateIdx
                                            point = pts[i]
                                        end
                                    end

                                    botLog('Path point %d/%d: gate -> %s', i, #pts, tostring(point.gate_location))

                                    local groundFrom = i

                                    for attempt = 1, (stayIn and 999 or GATE_RETRIES)do
                                        if not trinket_bot.path_running or trinket_bot.moderator_detected or state.emergency_gate_requested then
                                            break
                                        end
                                        if attempt > 1 then
                                            botLog('Gate %d retry %d', i, attempt)
                                            task.wait(0.5)

                                            groundFrom += 1
                                        end
                                        if gateStabilized(point.gate_location, gateExpectedDest(i), groundFrom) then
                                            gated = true

                                            break
                                        end
                                    end

                                    if stayIn then
                                        if not gated then
                                            Notify.say('Gate failed but staying in server - continuing path')
                                            Webhook.text(string.format('@here Gate to %s repeatedly failing (stay in server mode)', tostring(point.gate_location)))
                                        end

                                        break
                                    end
                                    if not gated then
                                        botLog('Gate %d failed after %d attempts - trying next gate', i, GATE_RETRIES)

                                        searchFrom = i + 1
                                    end
                                end

                                if state.emergency_gate_requested and not stayIn then
                                    continue
                                end
                                if not gated and not stayIn then
                                    Notify.say('All gate points blocked or failed - serverhopping')
                                    trinketBotServerhop('All gate points blocked or failed')

                                    return
                                end
                            else
                                botLog('Path point %d/%d: moving to (%.0f, %.0f, %.0f)', i, #trinket_bot.active_points, point.position.X, point.position.Y, point.position.Z)

                                local char = LocalPlayer.Character
                                local hrp = char and char:FindFirstChild('HumanoidRootPart')

                                if i == #trinket_bot.active_points and hrp and not Toggles.StayInServer.Value then
                                    local camping, campName = isPlayerNear(point.position, 180)

                                    if camping then
                                        safeServerhop('Player ' .. tostring(campName) .. ' camping last point')

                                        return
                                    end
                                end

                                local nearP, nearName = isPlayerNear(point.position, 65)

                                if nearP and not Toggles.StayInServer.Value then
                                    if pathHasGates() then
                                        local gated, gIdx

                                        for j = i + 1, #trinket_bot.active_points do
                                            if trinket_bot.active_points[j].is_gate_point then
                                                local clear = true

                                                for k = j + 1, math.min(j + 3, #trinket_bot.active_points)do
                                                    if isPlayerNear(trinket_bot.active_points[k].position, 65) then
                                                        clear = false

                                                        break
                                                    end
                                                end

                                                if clear then
                                                    for _ = 1, 2 do
                                                        if gateStabilized(trinket_bot.active_points[j].gate_location, gateExpectedDest(j)) then
                                                            gated, gIdx = true, j

                                                            break
                                                        end

                                                        task.wait(0.5)
                                                    end
                                                end
                                                if gated then
                                                    break
                                                end
                                            end
                                        end

                                        if gated then
                                            i = gIdx + 1

                                            continue
                                        end
                                    end

                                    directionalEscape(i, nearName)

                                    return
                                end

                                local shriekNear, shrieker = false, nil

                                if not Toggles.StayInServer.Value and not shriekersIgnored() then
                                    shriekNear, shrieker = detectShrieker(point.position, 65, allyOf)
                                end
                                if shriekNear then
                                    botLog('Shrieker near point %d/%d (%s)', i, #trinket_bot.active_points, Threats.shriekerLabel(shrieker))

                                    if pathHasGates() then
                                        local ng

                                        for j = i + 1, #trinket_bot.active_points do
                                            if trinket_bot.active_points[j].is_gate_point then
                                                local clear, blocker = gateLandingClear(j)

                                                if clear then
                                                    if gateStabilized(trinket_bot.active_points[j].gate_location, gateExpectedDest(j)) then
                                                        ng = j + 1
                                                    end

                                                    break
                                                end

                                                botLog('Gate %d lands near %s - looking for a later gate', j, tostring(blocker))
                                            end
                                        end

                                        if ng then
                                            i = ng

                                            continue
                                        end

                                        trinketBotServerhop('Shrieker - gate escape failed')

                                        return
                                    end

                                    for ri = i - 1, 1, -1 do
                                        if not trinket_bot.path_running then
                                            break
                                        end

                                        SmoothTeleport(trinket_bot.active_points[ri].position)
                                        task.wait(0.3)
                                    end

                                    trinketBotServerhop('Shrieker near point ' .. i)

                                    return
                                end
                                if i == #trinket_bot.active_points and not Toggles.StayInServer.Value then
                                    local camper
                                    local watch = task.spawn(function()
                                        while trinket_bot.path_running do
                                            local near, who = isPlayerNear(point.position, 160)

                                            if near then
                                                camper = who

                                                if active_tween.tween then
                                                    pcall(function()
                                                        active_tween.tween:Cancel()
                                                    end)
                                                end

                                                return
                                            end

                                            task.wait(1)
                                        end
                                    end)

                                    SmoothTeleport(point.position, nil, nil, true)
                                    pcall(task.cancel, watch)

                                    if camper then
                                        safeServerhop('Player ' .. camper .. ' camping last point')

                                        return
                                    end
                                else
                                    SmoothTeleport(point.position, nil, nil, true)
                                end
                            end

                            waitAtPoint(point, trinket_bot)

                            if point.wait_for_trinket and not dragonBlocks(point.position) then
                                if not Toggles.StayInServer.Value then
                                    for _, p in Players:GetPlayers()do
                                        local ph = p ~= LocalPlayer and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                                        if ph and (ph.Position - point.position).Magnitude <= 150 and not isCarriedByMe(p) then
                                            trinketBotServerhop('Player camping wait point ' .. i)

                                            return
                                        end
                                    end
                                end

                                local lockConn
                                local waitChar = LocalPlayer.Character
                                local waitHum = waitChar and waitChar:FindFirstChildOfClass('Humanoid')
                                local waitRoot = waitChar and waitChar:FindFirstChild('HumanoidRootPart')
                                local anchor = waitRoot and waitRoot.Position
                                local reached = anchor ~= nil and (anchor - point.position).Magnitude <= 10

                                if not reached then
                                    botLog(
[[Point %d: never reached the wait spot (%s off), not waiting there]], i, anchor and string.format('%.0f studs', (anchor - point.position).Magnitude) or 'no body')
                                elseif waitHum and waitHum.FloorMaterial == Enum.Material.Air then
                                    lockConn = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                                    )
                                        local r = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                                        if r then
                                            r.CFrame = CFrame.new(anchor)
                                            r.AssemblyLinearVelocity = Vector3.zero
                                        end
                                    end))
                                elseif waitHum then
                                    waitHum:SetStateEnabled(5, true)
                                    waitHum:ChangeState(5)
                                end

                                local elapsed = 0

                                while reached and elapsed < 8.67 and trinket_bot.path_running and not state.emergency_gate_requested and not trinket_bot.moderator_detected do
                                    task.wait(0.25)

                                    elapsed += 0.25
                                end

                                if lockConn then
                                    lockConn:Disconnect()
                                end
                                if reached and trinket_bot.path_running and not trinket_bot.moderator_detected then
                                    local skipCollect = dragonBlocks(point.position)

                                    if not skipCollect and not shriekersIgnored() then
                                        local mob, mobName = Threats.detectMob(point.position, 120)

                                        if mob then
                                            botLog('Skipping collection at point %d, %s is on it', i, tostring(mobName))

                                            skipCollect = true
                                        end
                                    end

                                    local terraDanger = false

                                    if (point.position - TUNDRA2_CENTER).Magnitude <= 150 then
                                        local ms = Workspace:FindFirstChild('MonsterSpawns')
                                        local groups = ms and ms:FindFirstChild('Groups')
                                        local maze = groups and groups:FindFirstChild('MazeSnakes')
                                        local serpent = maze and maze:FindFirstChild('Terra Serpent')
                                        local spawned = serpent and serpent:FindFirstChild('Spawned')

                                        if spawned and spawned.Value == true then
                                            terraDanger = true
                                        end
                                    end
                                    if skipCollect then
                                    elseif terraDanger then
                                        SmoothTeleport(TUNDRA2_SAFE)
                                    else
                                        checkForTrinkets(point.position, tonumber(point.trinket_range))

                                        local r = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                                        if r then
                                            opportunisticDetour(r.Position, i, point.position, tonumber(point.trinket_range))
                                        end
                                    end
                                end
                            end
                            if point.wait_for_node and trinket_bot.path_running and not trinket_bot.moderator_detected then
                                checkForNodes(point, i)
                            end

                            i += 1
                        end

                        stopPickup()
                        stopLootTracking()
                        threatMaid:DoCleaning()

                        if MemStore.get('botstarted') == 'true' then
                            applyBotFps()
                        else
                            FpsCap.set('trinketbot', nil)
                        end

                        restoreTouch()

                        if MemStore.get('botstarted') ~= 'true' then
                            bedsOff(false)
                        end

                        restoreBotState()
                        botRunAutoTrinket(false)

                        if not trinket_bot.test_mode and getconnections then
                            pcall(function()
                                for _, c in getconnections(LocalPlayer.Idled)do
                                    c:Enable()
                                end
                            end)
                        end
                        if trinket_bot.stopped then
                            trinket_bot.path_running = false

                            setStopVisible(false)

                            return
                        end
                        if trinket_bot.kickAfterPath and not trinket_bot.test_mode then
                            trinket_bot.path_running = false

                            setStopVisible(false)
                            waitOutDanger()
                            botKick('Trinket bot: kicked after picking up a flagged item')

                            return
                        end
                        if trinket_bot.moderator_detected then
                            trinket_bot.path_running = false

                            setStopVisible(botBusy())

                            return
                        end
                        if i <= #trinket_bot.active_points then
                            botLog(
[[Path stopped at point %d/%d, not treating it as a finished lap]], i, #trinket_bot.active_points)

                            trinket_bot.path_running = false

                            setStopVisible(botBusy())

                            return
                        end
                        if trinket_bot.test_mode then
                            trinket_bot.path_running = false

                            setStopVisible(false)
                            botLog('Path complete: test run')
                            Webhook.embed(richEmbed('Test Run Completed', 0xff00))
                            Notify.say('Test run complete')
                        elseif Toggles.StayInServer and Toggles.StayInServer.Value then
                            local runNumber = (tonumber(MemStore.get('stay_in_server_runs')) or 0) + 1

                            MemStore.set('stay_in_server_runs', runNumber)
                            botLog('Path complete: stay-in-server run #%d (looping in %d min)', runNumber, (Options.TimeBetweenLooting.Value or 5))
                            Webhook.embed(richEmbed(string.format('Stay In Server - Run #%d', runNumber), 0x5865f2))

                            local target = (Options.TimeBetweenLooting.Value or 5) * 60
                            local waited = 0

                            while waited < target and trinket_bot.path_running do
                                task.wait(1)

                                waited += 1
                            end

                            trinket_bot.path_running = false

                            if not trinket_bot.stopped and Toggles.StayInServer.Value then
                                ExecutePath(false)
                            end
                        else
                            botLog(
[[Path complete: reached the end - serverhopping (server farmed)]])
                            trinketBotServerhop('Server farmed', nil, true)
                        end
                    end)
                end
                stopBot = function()
                    setStopVisible(false)

                    trinket_bot.stopped = true

                    local tween = active_tween.tween

                    if tween then
                        pcall(function()
                            tween:Cancel()
                        end)
                    end

                    trinket_bot.kickAfterPath = false
                    trinket_bot.path_running = false
                    trinket_bot.moderator_detected = false
                    trinket_bot.escaping = false
                    trinket_bot.hopping = false
                    trinket_bot.hopCommitted = false
                    trinket_bot.resume_start_index = nil
                    trinket_bot.lap_end_index = nil
                    trinket_bot.skipCastleRock = false
                    state.emergency_gate_requested = nil
                    state.emergency_gate_in_progress = false
                    state.current_gate_section = 0

                    table.clear(state.player_encounters)
                    table.clear(state.proximity_warnings)

                    state.gnavDetected = false
                    state.gnavPlayerName = nil
                    state.iceDragonSkipIndex = nil
                    state.fimbulEscape = false
                    state.spearEscape = false

                    table.clear(state.collectedIds)
                    table.clear(visitedPositions)
                    table.clear(trinket_bot.collected_order)
                    stopPickup()
                    stopLootTracking()
                    threatMaid:DoCleaning()
                    FpsCap.set('trinketbot', nil)
                    restoreTouch()
                    bedsOff(false)
                    restoreBotState()
                    botRunAutoTrinket(false)
                    MemStore.remove('botstarted')
                    MemStore.remove('serverhop_count')
                    BotClaims.release()

                    if getconnections then
                        pcall(function()
                            for _, c in getconnections(LocalPlayer.Idled)do
                                c:Enable()
                            end
                        end)
                    end

                    Notify.say('Bot stopped')
                end

                local function aaRestart()
                    local waited = 0

                    while waited < 60 do
                        local char = LocalPlayer.Character
                        local hum = char and char:FindFirstChildOfClass('Humanoid')

                        if char and hum and hum.Health > 0 then
                            break
                        end

                        task.wait(0.25)

                        waited += 0.25
                    end

                    if not Character.awaitPlaced(function()
                        return not state.unloaded
                    end, 40) then
                        botLog(
[[AA gun: never left the spawn pad, stopping instead of moving]])
                        stopBot()

                        return
                    end

                    task.wait(2)

                    trinket_bot.skip_distance_check = true
                    trinket_bot.relocated = true

                    botLog('AA gun: running the path again from the start')
                    ExecutePath(false)
                end
                local function onAAGun()
                    local count, at = AAGun.record()
                    local botting = trinket_bot.path_running or MemStore.get('botstarted') == 'true'

                    botLog('AA gunned (%d in the last 24h)%s', count, botting and '' or ' while not botting')

                    if not botting or state.aaHandling then
                        return
                    end

                    state.aaHandling = true

                    local resume = Toggles.ContinueAfterAAGun and Toggles.ContinueAfterAAGun.Value
                    local stamp = string.format('<t:%d:f>', at)

                    if count >= 2 or not resume then
                        trinket_bot.path_running = false

                        local why = count >= 2 and string.format('AA gunned %d times inside 24h', count) or 'AA gunned'

                        Webhook.embedWith('@everyone', richEmbed(why .. ' - stopping', 0xed4245))
                        Webhook.text(string.format('AA gun #%d landed at %s', count, stamp))
                        stopBot()
                        waitOutDanger()
                        botKick('sentinel: ' .. why)

                        return
                    end

                    trinket_bot.path_running = false
                    trinket_bot.expectedDeathUntil = tick() + 30

                    Webhook.embedWith('@everyone', richEmbed('AA gunned - restarting the path', 0xe67e22))
                    Webhook.text(string.format('AA gun #%d landed at %s', count, stamp))
                    task.spawn(function()
                        local ok, err = pcall(aaRestart)

                        if not ok then
                            botLog('AA gun: restart failed (%s)', tostring(err))
                        end

                        state.aaHandling = false
                    end)
                end

                AAGun.watch(ctx.Maid, onAAGun)
                ctx.State.registerBot({
                    name = 'Trinket Bot',
                    running = function()
                        return trinket_bot.path_running == true
                    end,
                    detail = function()
                        return trinket_bot.current_path_name ~= '' and trinket_bot.current_path_name or nil
                    end,
                    stop = function()
                        stopBot()
                    end,
                    startPos = function()
                        local first = trinket_bot.active_points[1] or trinket_bot.path_points[1]

                        return first and first.position or nil
                    end,
                })

                local function shouldDrop(name)
                    local drops = (Options.AutoDropItems and Options.AutoDropItems.Value) or {}
                    local stripped = name:gsub(' ', '')

                    for dropName, enabled in drops do
                        if enabled and stripped == tostring(dropName):gsub(' ', '') then
                            return true
                        end
                    end

                    return false
                end
                local function dropItem(item)
                    if MemStore.get('botstarted') ~= 'true' then
                        return
                    end

                    local char = LocalPlayer.Character

                    if not (char and char:FindFirstChildOfClass('Humanoid')) then
                        return
                    end

                    while state.currently_dropping and (tick() - dropping_since) < 12 do
                        task.wait(0.1)
                    end

                    state.currently_dropping = true
                    dropping_since = tick()

                    if state.droppedTools[item.Name] or not shouldDrop(item.Name) then
                        state.currently_dropping = false

                        return
                    end

                    state.droppedTools[item.Name] = true

                    local hum = char:FindFirstChildOfClass('Humanoid')
                    local tryUse = item.Name:lower():find('scroll of') ~= nil or item.Name == 'Ice Essence'

                    if not pcall(function()
                        hum:EquipTool(item)
                    end) then
                        state.droppedTools[item.Name] = nil
                        state.currently_dropping = false

                        return
                    end

                    local start = tick()

                    while item.Parent ~= char and (tick() - start) < 3 do
                        task.wait(0.1)
                    end

                    if item.Parent ~= char then
                        state.droppedTools[item.Name] = nil
                        state.currently_dropping = false

                        return
                    end

                    local vim = getVim()

                    if tryUse then
                        task.wait(0.1)

                        if vim then
                            vim:SendMouseButtonEvent(0, 0, 0, true, game, 1)
                            task.wait(math.random(1, 15) / 1000)
                            vim:SendMouseButtonEvent(0, 0, 0, false, game, 1)
                        end

                        task.wait(0.5)

                        local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                        if not item.Parent or (item.Parent ~= char and item.Parent ~= bp) then
                            state.droppedTools[item.Name] = nil
                            state.currently_dropping = false

                            return
                        end
                        if item.Parent == bp then
                            pcall(function()
                                hum:EquipTool(item)
                            end)
                            task.wait(0.3)
                        end
                    end

                    task.wait(0.075)

                    if vim then
                        vim:SendKeyEvent(true, Enum.KeyCode.Backspace, false, game)
                        task.wait()
                        vim:SendKeyEvent(false, Enum.KeyCode.Backspace, false, game)
                    end

                    local nm = item.Name

                    task.delay(2, function()
                        state.droppedTools[nm] = nil
                    end)
                    task.wait(0.3)

                    state.currently_dropping = false
                end
                local function tryPopPD()
                    if MemStore.get('botstarted') ~= 'true' or not Toggles.AutoPopPDs.Value then
                        return
                    end

                    local lives = getStat('Lives')

                    if type(lives) ~= 'number' or lives >= (LIVES_TABLE[getStat('Race')] or 3) then
                        return
                    end

                    local day = getStat('DaysSurvived')
                    local key = 'last_pd_day_' .. LocalPlayer.UserId

                    if MemStore.get(key) == tostring(day) then
                        return
                    end

                    local bp = LocalPlayer:FindFirstChildOfClass('Backpack')
                    local pd = bp and bp:FindFirstChild('Phoenix Down')
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                    if not pd or not hum then
                        return
                    end

                    local oldLives = lives

                    hum:EquipTool(pd)

                    local timeout = tick() + 5

                    while pd.Parent ~= LocalPlayer.Character and tick() < timeout do
                        task.wait()
                    end

                    if pd.Parent ~= LocalPlayer.Character then
                        return
                    end

                    pd:Activate()
                    MemStore.set(key, tostring(day))
                    task.wait(1)

                    local newLives = getStat('Lives')

                    Webhook.text(('Auto-popped a Phoenix Down (%s \u{2192} %s lives)'):format(tostring(oldLives), tostring(newLives or '?')))
                end
                local function secureFlagged(itemName)
                    if trinket_bot.test_mode or (Toggles.StayInServer and Toggles.StayInServer.Value) then
                        return
                    end

                    trinket_bot.path_running = false
                    trinket_bot.escaping = true

                    local points = trinket_bot.active_points
                    local chosen

                    for j = #points - 1, 1, -1 do
                        if points[j].is_gate_point and emergencyGateClear(points, j, isPlayerNear) then
                            chosen = j

                            break
                        end
                    end

                    if chosen then
                        botLog('Flagged item: gating out through point %d', chosen)
                        gateStabilized(points[chosen].gate_location, gateExpectedDest(chosen))
                    else
                        botLog(
[[Flagged item: no gate with a clear landing, leaving from where we stand]])
                    end

                    waitOutDanger()
                    leaveToMenu()
                    botKick('Trinket bot: kicked after picking up ' .. tostring(itemName))
                end

                function setupBackpackMonitoring()
                    local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')

                    if not backpack then
                        return
                    end

                    threatMaid.backpack = backpack.ChildAdded:Connect(function(
                        obj
                    )
                        if MemStore.get('botstarted') ~= 'true' or not obj:IsA('Tool') then
                            return
                        end

                        drop_hold_until = tick() + DROP_HOLD_GRACE

                        task.wait(0.05)

                        if Toggles.KickOnTrinket.Value then
                            local list = (Options.KickTrinketList and Options.KickTrinketList.Value) or {}
                            local stripped = obj.Name:gsub('%s', '')

                            for entry in list do
                                if tostring(entry):gsub('%s', '') == stripped then
                                    trinket_bot.kickAfterPath = true

                                    Webhook.text('Flagged item picked up (' .. obj.Name .. ') - gating out and kicking')
                                    task.spawn(secureFlagged, obj.Name)

                                    break
                                end
                            end
                        end

                        task.wait(0.67)

                        for _, item in backpack:GetChildren()do
                            if item:IsA('Tool') and not state.droppedTools[item.Name] and shouldDrop(item.Name) then
                                task.spawn(dropItem, item)
                            end
                        end

                        drop_hold_until = tick() + DROP_HOLD_GRACE
                    end)
                end

                local function pointEditorKind(p)
                    if p.action then
                        return p.action
                    elseif p.is_gate_point then
                        return 'gate'
                    elseif p.wait_for_node then
                        return 'node'
                    elseif p.wait_for_trinket then
                        return 'wait'
                    end

                    return 'normal'
                end
                local function pointArea(pos)
                    local fn = ctx.State and ctx.State.trinketArea

                    if not fn then
                        return ''
                    end

                    local key = string.format('%d,%d,%d', pos.X // 4, pos.Y // 4, pos.Z // 4)
                    local known = areaCache[key]

                    if known == nil then
                        local ok, area = pcall(fn, {Position = pos})

                        known = (ok and area and area ~= 'None') and area or ''
                        areaCache[key] = known
                    end

                    return known
                end
                local function readPointsForEditor()
                    local out = {}
                    local depths = branchDepths(trinket_bot.path_points)

                    for i, p in trinket_bot.path_points do
                        local row = {
                            kind = pointEditorKind(p),
                            depth = depths[i],
                            x = p.position.X,
                            y = p.position.Y,
                            z = p.position.Z,
                            area = (p.action and NON_POSITIONAL[p.action]) and '' or pointArea(p.position),
                            condition = p.condition,
                        }

                        for _, key in POINT_FIELDS do
                            row[key] = p[key]
                        end

                        row.trinket_range = p.trinket_range or BOT.waitCover

                        table.insert(out, row)
                    end

                    return out
                end

