                        if trinket_bot.current_path_name == '' then
                            Notify.say('No saved path to refresh from - load or save one first')

                            return
                        end
                        if not loadPath(trinket_bot.current_path_name) then
                            Notify.say("Refresh failed - couldn't reload saved path")
                        end
                    end,
                    OnTest = function()
                        if trinket_bot.path_running then
                            stopBot()
                        elseif ModeGate.allow(ctx, 'Blatant', 'Test Path') then
                            ExecutePath(true)
                        end
                    end,
                    OnSpectate = function(i)
                        local cam = Workspace.CurrentCamera
                        local point = i and trinket_bot.path_points[i]

                        if not point or spectatingPoint == i then
                            if spectatingPoint == nil then
                                return
                            end

                            spectatingPoint = nil

                            if ctx.State.freecamOff then
                                ctx.State.freecamOff()
                            end

                            cam.CameraType = Enum.CameraType.Custom

                            local char = LocalPlayer.Character
                            local hum = char and char:FindFirstChildOfClass('Humanoid')

                            if hum then
                                cam.CameraSubject = hum
                            end

                            return
                        end

                        spectatingPoint = i

                        local target = CFrame.lookAt(point.position + BOT.spectateOffset, point.position)

                        if not (ctx.State.freecamAt and ctx.State.freecamAt(target)) then
                            cam.CameraType = Enum.CameraType.Scriptable
                            cam.CFrame = target
                        end
                    end,
                    OnTeleport = function(i)
                        local point = trinket_bot.path_points[i]
                        local pos = point and point.position

                        if typeof(pos) ~= 'Vector3' then
                            Notify.say('That point has no position to teleport to')

                            return
                        end
                        if trinket_bot.path_running then
                            Notify.say('Stop the bot before teleporting')

                            return
                        end
                        if trinket_bot.teleportingToPoint or not ModeGate.allow(ctx, 'Blatant', 'Teleport') then
                            return
                        end

                        trinket_bot.teleportingToPoint = true

                        task.spawn(function()
                            local ok = false

                            pcall(function()
                                ok = Menu.menuTele(pos, nil, 1)
                            end)
                            Notify.say(string.format(ok and 'Teleported to point %d' or 'Teleport to point %d failed', i))

                            trinket_bot.teleportingToPoint = false
                        end)
                    end,
                    OnCopyPosition = function(i)
                        local point = trinket_bot.path_points[i]
                        local pos = point and point.position
                        local copy = setclipboard or toclipboard or set_clipboard

                        if typeof(pos) ~= 'Vector3' or not copy then
                            Notify.say(copy and 'That point has no position to copy' or "Your executor can't copy to the clipboard")

                            return
                        end

                        local text = string.format('%.0f, %.0f, %.0f', pos.X, pos.Y, pos.Z)

                        pcall(copy, text)
                        Notify.say('Copied ' .. text)
                    end,
                    OnUndo = function()
                        local at, count = stepHistory(trinket_bot, false)

                        if at then
                            updateVisualizations()
                        end

                        return at, count
                    end,
                    OnRedo = function()
                        local at, count = stepHistory(trinket_bot, true)

                        if at then
                            updateVisualizations()
                        end

                        return at, count
                    end,
                    OnCopy = function(indices)
                        table.clear(pointClipboard)

                        for _, i in indices do
                            local p = trinket_bot.path_points[i]

                            if p then
                                table.insert(pointClipboard, clonePoint(p))
                            end
                        end

                        Library:Notify({
                            Title = 'sentinel.bz',
                            Description = string.format('Copied %d point%s', #pointClipboard, #pointClipboard == 1 and '' or 's'),
                        })
                    end,
                    OnPaste = function(afterIndex)
                        pushHistory(trinket_bot)

                        if #pointClipboard == 0 then
                            Notify.say('Nothing copied yet - pick some points and press Ctrl+C')

                            return 0
                        end

                        local at = math.clamp(tonumber(afterIndex) or #trinket_bot.path_points, 0, #trinket_bot.path_points)

                        for n = #pointClipboard, 1, -1 do
                            table.insert(trinket_bot.path_points, at + 1, clonePoint(pointClipboard[n]))
                        end

                        updateVisualizations()
                        Library:Notify({
                            Title = 'sentinel.bz',
                            Description = string.format('Pasted %d point%s after %d', #pointClipboard, #pointClipboard == 1 and '' or 's', at),
                        })

                        return #pointClipboard
                    end,
                    OnField = function(i, key, value)
                        pushHistory(trinket_bot)

                        local p = trinket_bot.path_points[i]

                        if not p or not table.find(POINT_FIELDS, key) then
                            return
                        end

                        local fallback = BOT.numericFields[key]

                        if value == nil then
                            p[key] = nil
                        elseif fallback ~= nil then
                            p[key] = tonumber(value) or fallback
                        else
                            p[key] = tostring(value)
                        end

                        updateVisualizations()
                    end,
                    OnKind = function(i, kind)
                        pushHistory(trinket_bot)

                        local p = trinket_bot.path_points[i]

                        if not p then
                            return
                        end
                        if ACTION_KINDS[kind] then
                            p.action = kind
                            p.is_gate_point = nil
                            p.wait_for_trinket = false
                            p.wait_for_node = false
                        else
                            p.action = nil
                            p.is_gate_point = kind == 'gate' or nil
                            p.wait_for_trinket = kind == 'wait'
                            p.wait_for_node = kind == 'node'

                            if kind == 'node' and not p.node_range then
                                p.node_range = 150
                            end
                            if kind == 'gate' and not p.gate_location then
                                p.gate_location = ''
                            end
                        end

                        updateVisualizations()
                    end,
                    OnReorderMany = function(indices, to)
                        pushHistory(trinket_bot)

                        local pts = trinket_bot.path_points
                        local block, at = {}, to

                        for n = #indices, 1, -1 do
                            local taken = table.remove(pts, indices[n])

                            if taken then
                                table.insert(block, 1, taken)
                            end
                        end

                        for _, idx in indices do
                            if idx < to then
                                at -= 1
                            end
                        end

                        at = math.clamp(at, 1, #pts + 1)

                        for n = #block, 1, -1 do
                            table.insert(pts, at, block[n])
                        end

                        updateVisualizations()

                        return at, #block
                    end,
                    OnReorder = function(from, to)
                        pushHistory(trinket_bot)

                        local pts = trinket_bot.path_points
                        local moved = table.remove(pts, from)

                        if not moved then
                            return
                        end

                        table.insert(pts, math.clamp(to, 1, #pts + 1), moved)
                        updateVisualizations()
                    end,
                    OnMove = function(i, delta)
                        pushHistory(trinket_bot)

                        local pts = trinket_bot.path_points
                        local j = i + delta

                        if pts[i] and pts[j] then
                            pts[i], pts[j] = pts[j], pts[i]

                            updateVisualizations()
                        end
                    end,
                    OnDelete = function(i)
                        pushHistory(trinket_bot)

                        if trinket_bot.path_points[i] then
                            table.remove(trinket_bot.path_points, i)
                            updateVisualizations()
                        end
                    end,
                    OnRecapture = function(i)
                        pushHistory(trinket_bot)

                        local p = trinket_bot.path_points[i]
                        local pos = rootPos()

                        if not (p and pos) then
                            Notify.say('No character to capture from')

                            return
                        end

                        p.position = pos

                        updateVisualizations()
                    end,
                    OnInsert = function(i)
                        pushHistory(trinket_bot)

                        local pos = rootPos()

                        if not pos then
                            Notify.say('No character to capture from')

                            return
                        end

                        table.insert(trinket_bot.path_points, i + 1, {
                            position = pos,
                            wait_for_trinket = false,
                            wait_time = 0,
                        })
                        updateVisualizations()
                    end,
                    OnAppend = function(after)
                        pushHistory(trinket_bot)

                        local pos = rootPos()

                        if not pos then
                            Notify.say('No character to capture from')

                            return
                        end

                        local at = landingSlot(trinket_bot, after)

                        table.insert(trinket_bot.path_points, at, {
                            position = pos,
                            wait_for_trinket = false,
                            wait_time = 0,
                        })
                        updateVisualizations()

                        return at, 1
                    end,
                    OnAppendAction = function(after)
                        pushHistory(trinket_bot)

                        local at = landingSlot(trinket_bot, after)

                        table.insert(trinket_bot.path_points, at, {
                            position = rootPos() or Vector3.zero,
                            action = 'equip',
                            tool = '',
                            wait_for_trinket = false,
                            wait_time = 0,
                        })
                        updateVisualizations()

                        return at, 1
                    end,
                    OnAppendBranch = function(after)
                        pushHistory(trinket_bot)

                        local pos = rootPos() or Vector3.zero
                        local at = landingSlot(trinket_bot, after)

                        for offset, action in {
                            'if',
                            'else',
                            'endif',
                        }do
                            table.insert(trinket_bot.path_points, at + offset - 1, {
                                position = pos,
                                action = action,
                                condition = action == 'if' and {
                                    var = CONDITION_VARS[1].label,
                                    op = '>=',
                                    value = 1,
                                } or nil,
                                wait_for_trinket = false,
                                wait_time = 0,
                            })
                        end

                        updateVisualizations()

                        return at, 3
                    end,
                    OnAppendLoop = function(after)
                        pushHistory(trinket_bot)

                        local pos = rootPos() or Vector3.zero
                        local at = landingSlot(trinket_bot, after)

                        for offset, action in {
                            'loop',
                            'endloop',
                        }do
                            table.insert(trinket_bot.path_points, at + offset - 1, {
                                position = pos,
                                action = action,
                                wait_for_trinket = false,
                                wait_time = 0,
                            })
                        end

                        updateVisualizations()

                        return at, 2
                    end,
                    OnSave = function()
                        local name = PathNames.target(Options) or trinket_bot.current_path_name

                        if not name or name == '' then
                            Notify.say('Set a Path Name first, then Save')

                            return false
                        end
                        if savePath(name) then
                            trinket_bot.current_path_name = name

                            if Options.SavedPaths then
                                Options.SavedPaths:SetValues(listPaths())
                            end

                            Notify.say('Saved path: ' .. name)

                            return true
                        end

                        Notify.say('Save failed')

                        return false
                    end,
                })

                for _, kind in pathEditor.Kinds do
                    if kind.Positional == false then
                        NON_POSITIONAL[kind.key] = true
                    end
                end

                pcall(ensureDir)

                local PathBox = Botting:AddLeftGroupbox('Path Recorder')

                PathBox:AddInput('PointWaitTime', {
                    Text = 'Point Wait Time',
                    Numeric = true,
                    Default = '0',
                    Finished = true,
                })
                PathBox:AddButton({
                    Text = 'Create Point',
                    Func = function()
                        createPoint(false)
                    end,
                })
                PathBox:AddLabel('Create Point Keybind'):AddKeyPicker('CreatePointKeybind', {
                    Default = 'None',
                    Mode = 'Press',
                    Modes = {
                        'Press',
                    },
                    Text = 'Create Point',
                    Callback = function()
                        createPoint(false)
                    end,
                })
                PathBox:AddButton({
                    Text = 'Set Wait-For-Trinket Point',
                    Func = function()
                        createPoint(true)
                    end,
                })
                PathBox:AddButton({
                    Text = 'Add Node Point',
                    Func = function()
                        local pos = rootPos()

                        if not pos then
                            Notify.say('No character to record from')

                            return
                        end

                        pushHistory(trinket_bot)
                        table.insert(trinket_bot.path_points, {
                            position = pos,
                            wait_for_node = true,
                            node_range = 150,
                            wait_time = 0,
                        })
                        botLog('Node point added at (%.0f, %.0f, %.0f)', pos.X, pos.Y, pos.Z)
                        updateVisualizations()

                        if pathEditor then
                            pathEditor:Refresh()
                        end
                    end,
                })
                PathBox:AddButton({
                    Text = 'Undo Point',
                    Func = function()
                        pushHistory(trinket_bot)
                        table.remove(trinket_bot.path_points)
                        updateVisualizations()
                        pathEditor:Refresh()
                    end,
                })
                PathBox:AddButton({
                    Text = 'Clear Points',
                    DoubleClick = true,
                    Func = function()
                        pushHistory(trinket_bot)

                        trinket_bot.path_points = {}

                        updateVisualizations()
                        pathEditor:Refresh()
                    end,
                })
                PathBox:AddButton({
                    Text = 'Open Path Editor',
                    Func = function()
                        if pathEditor.Holder.Visible then
                            pathEditor:Hide()

                            return
                        end

                        pathEditor:Refresh()

                        if Toggles.VisualizePoints and not Toggles.VisualizePoints.Value then
                            Toggles.VisualizePoints:SetValue(true)
                        end

                        pathEditor:Show()
                    end,
                })
                PathBox:AddInput('GateLocation', {
                    Text = 'Gate Location',
                    Placeholder = 'Tundra 7',
                    Finished = true,
                })
                PathBox:AddButton({
                    Text = 'Add Gate Point',
                    Func = function()
                        local pos = rootPos()

                        if not pos then
                            return
                        end

                        pushHistory(trinket_bot)
                        table.insert(trinket_bot.path_points, {
                            position = pos,
                            is_gate_point = true,
                            gate_location = Options.GateLocation.Value,
                            wait_for_trinket = false,
                            wait_time = 0,
                        })
                        updateVisualizations()
                        pathEditor:Refresh()
                    end,
                })
                PathBox:AddButton({
                    Text = 'Test Gate',
                    Func = function()
                        if Options.GateLocation.Value == '' then
                            Notify.say('Set a Gate Location first')

                            return
                        end

                        task.spawn(function()
                            path_tool = nil
                            trinket_bot.path_running = true

                            Gate(Options.GateLocation.Value)

                            trinket_bot.gatingUntil = 0
                            trinket_bot.path_running = false
                        end)
                    end,
                })
                PathBox:AddToggle('VisualizePoints', {
                    Text = 'Visualize Points',
                    Default = true,
                    Callback = function()
                        updateVisualizations()
                    end,
                })

                do
                    local dragMaid = Maid.new()

                    ctx.Maid:Give(dragMaid)

                    local dragging, dragSphere = nil, nil
                    local verticalAnchor, flatAnchor, placeMode = nil, nil, nil

                    local function dropPoint()
                        if dragSphere then
                            pcall(function()
                                dragSphere.CanQuery = true
                            end)
                        end
                        if dragging then
                            botLog('Dragged point %d to (%.0f, %.0f, %.0f)', dragging, trinket_bot.path_points[dragging].position.X, trinket_bot.path_points[dragging].position.Y, trinket_bot.path_points[dragging].position.Z)

                            if pathEditor then
                                pcall(function()
                                    pathEditor:Refresh()
                                end)
                            end
                        end

                        dragging, dragSphere, verticalAnchor, flatAnchor, placeMode = nil, nil, nil, nil, nil
                    end
                    local function startDrag()
                        dragMaid:DoCleaning()

                        verticalAnchor, flatAnchor, placeMode = nil, nil, nil
                        state.dragMode = true

                        updateVisualizations()

                        local mouse = LocalPlayer:GetMouse()

                        dragMaid:Connect(UserInputService.InputBegan, function(
                            input,
                            processed
                        )
                            if processed or input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                                return
                            end

                            local hit = mouse.Target
                            local index = hit and sphereIndex[hit]

                            if not index or not trinket_bot.path_points[index] then
                                return
                            end

                            dragging, dragSphere = index, hit

                            pcall(function()
                                hit.CanQuery = false
                            end)
                        end)
                        dragMaid:Connect(UserInputService.InputEnded, function(
                            input
                        )
                            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                                dropPoint()
                            end
                        end)
                        dragMaid:Connect(RunService.RenderStepped, BASIL_NO_VIRTUALIZE(function(
                        )
                            if not dragging then
                                return
                            end

                            local point = trinket_bot.path_points[dragging]

                            if not (point and dragSphere and dragSphere.Parent) then
                                dropPoint()

                                return
                            end

                            local ctrlDown = UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
                            local altDown = UserInputService:IsKeyDown(Enum.KeyCode.LeftAlt) or UserInputService:IsKeyDown(Enum.KeyCode.RightAlt)
                            local want = (ctrlDown and 'vertical') or (altDown and 'flat') or placeMode

                            if want ~= placeMode then
                                placeMode = want
                                verticalAnchor, flatAnchor = nil, nil
                            end
                            if placeMode == 'vertical' then
                                verticalAnchor = verticalAnchor or point.position

                                local camera = Workspace.CurrentCamera
                                local look = camera and camera.CFrame.LookVector
                                local normal = look and Vector3.new(look.X, 0, look.Z) or nil

                                if normal and normal.Magnitude > 1e-4 then
                                    local ray = mouse.UnitRay

                                    normal = normal.Unit

                                    local denom = ray.Direction:Dot(normal)

                                    if math.abs(denom) > 1e-4 then
                                        local t = (verticalAnchor - ray.Origin):Dot(normal) / denom

                                        if t > 0 then
                                            point.position = Vector3.new(verticalAnchor.X, (ray.Origin + ray.Direction * t).Y, verticalAnchor.Z)
                                            dragSphere.Position = point.position
                                        end
                                    end
                                end

                                return
                            end
                            if placeMode == 'flat' then
                                flatAnchor = flatAnchor or point.position

                                local ray = mouse.UnitRay

                                if math.abs(ray.Direction.Y) > 1e-4 then
                                    local t = (flatAnchor.Y - ray.Origin.Y) / ray.Direction.Y

                                    if t > 0 then
                                        local at = ray.Origin + ray.Direction * t

                                        point.position = Vector3.new(at.X, flatAnchor.Y, at.Z)
                                        dragSphere.Position = point.position
                                    end
                                end

                                return
                            end

                            local target = mouse.Hit and mouse.Hit.Position

