                })

                do
                    local isWindowActive = isrbxactive or iswindowactive or isgameactive
                    local gpuMaid = Maid.new()

                    ctx.Maid:Give(gpuMaid)

                    local gpu = {
                        active = false,
                        low = false,
                        focused = true,
                        savedQL = nil,
                    }

                    local function setRender(low)
                        FpsCap.set('gpu', low and 25 or nil)
                        pcall(function()
                            settings().Rendering.QualityLevel = low and 1 or gpu.savedQL
                        end)
                        pcall(function()
                            RunService:Set3dRenderingEnabled(not low)
                        end)
                    end
                    local function apply(low)
                        if low == gpu.low then
                            return
                        end

                        gpu.low = low

                        setRender(low)
                    end
                    local function windowFocused()
                        if isWindowActive then
                            local ok, active = pcall(isWindowActive)

                            if ok and type(active) == 'boolean' then
                                return active
                            end
                        end

                        return gpu.focused
                    end
                    local function evaluate()
                        apply(gpu.active and not windowFocused() and botActive())
                    end

                    gpuMaid.focus = UserInputService.WindowFocused:Connect(function(
                    )
                        gpu.focused = true

                        evaluate()
                    end)
                    gpuMaid.unfocus = UserInputService.WindowFocusReleased:Connect(function(
                    )
                        gpu.focused = false

                        evaluate()
                    end)

                    ctx.Maid:Give(function()
                        if gpu.low then
                            apply(false)
                        end
                    end)

                    local PerfBox = Botting:AddLeftGroupbox('Performance')

                    PerfBox:AddToggle('DisableGPURendering', {
                        Text = 'Disable GPU Rendering',
                        Tooltip = 'Stops rendering while tabbed out',
                        Default = false,
                        Callback = function(on)
                            gpu.active = on

                            if on then
                                pcall(function()
                                    gpu.savedQL = settings().Rendering.QualityLevel
                                end)

                                local accum = 0

                                gpuMaid.poll = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                                    dt
                                )
                                    accum += dt

                                    if accum >= 0.5 then
                                        accum = 0

                                        evaluate()
                                    end
                                end))
                            else
                                gpuMaid.poll = nil
                            end

                            evaluate()
                        end,
                    })
                end

                ctx.Maid:Give(task.spawn(function()
                    while true do
                        task.wait(60)

                        if MemStore.get('botstarted') == 'true' and not trinket_bot.hopping then
                            BotClaims.claim(game.JobId)
                        end
                    end
                end))
                ctx.Maid:Connect(Players.PlayerAdded, function(player)
                    if MemStore.get('botstarted') ~= 'true' or trinket_bot.hopping or trinket_bot.test_mode or not twinCanMoveUs() then
                        return
                    end

                    task.wait(1)

                    if twinCanMoveUs() and BotClaims.twinHere() == player then
                        trinketBotServerhop('another of your bots (' .. player.Name .. ') joined')
                    end
                end)
                pcall(setupBackpackMonitoring)
                ctx.Maid:Give(LocalPlayer.CharacterAdded:Connect(function()
                    task.wait(2.5)
                    setupBackpackMonitoring()
                    tryPopPD()
                end))
                ctx.Maid:Give(RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                    dt
                )
                    state.popAccum += dt

                    if state.popAccum < 15 then
                        return
                    end

                    state.popAccum = 0

                    task.spawn(tryPopPD)
                end)))
                task.spawn(function()
                    if MemStore.get('botstarted') ~= 'true' then
                        return
                    end
                    if not Serverhop.claimResume({
                        'botstarted',
                        'serverhop_count',
                    }) then
                        botLog(
[[Resume: botstarted was left over from a manual leave, not restarting]])

                        return
                    end

                    botLog(
[[Resume: botstarted flag set - rejoining and relaunching the path]])
                    task.wait(2)

                    trinket_bot.path_running = false

                    for _, p in Players:GetPlayers()do
                        if p ~= LocalPlayer and hostileMod(p) then
                            trinketBotServerhop((ctx.State.moderatorLabel and ctx.State.moderatorLabel(p) or 'Moderator') .. ' present on resume')

                            return
                        end
                    end

                    local twin = twinCanMoveUs() and BotClaims.twinHere()

                    if twin then
                        trinketBotServerhop('another of your bots (' .. twin.Name .. ') is already here')

                        return
                    end

                    BotClaims.claim(game.JobId)

                    local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                    if not (pg and pg:WaitForChild('StartMenu', 45)) then
                        Webhook.textBounded(
[[@everyone Resume failed (no StartMenu after 45s) - kicking bot]])
                        botKick('sentinel: resume - StartMenu never loaded')

                        return
                    end

                    task.wait(3)

                    if not pingGateOk() then
                        Notify.say('Ping too high - serverhopping before spawn')
                        trinketBotServerhop('Bad ping before spawn')

                        return
                    end

                    pcall(function()
                        local choices = pg.StartMenu:FindFirstChild('Choices')
                        local play = choices and choices:FindFirstChild('Play')

                        if not play then
                            return
                        end
                        if replicatesignal then
                            pcall(replicatesignal, play.MouseButton1Click)
                        end
                        if firesignal then
                            pcall(firesignal, play.MouseButton1Click)
                        end
                    end)

                    local waited = 0
                    local nextPlayRetry = math.random(15, 20)

                    while not LocalPlayer.Character and waited < 90 do
                        task.wait(0.25)

                        waited += 0.25

                        if not LocalPlayer.Character and waited >= nextPlayRetry then
                            nextPlayRetry = waited + math.random(15, 20)

                            botLog('Resume: no character after %.0fs - pressing Play again', waited)
                            pcall(function()
                                local retryPg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                                local retryMenu = retryPg and retryPg:FindFirstChild('StartMenu')
                                local retryChoices = retryMenu and retryMenu:FindFirstChild('Choices')
                                local retryPlay = retryChoices and retryChoices:FindFirstChild('Play')

                                if not retryPlay then
                                    return
                                end
                                if replicatesignal then
                                    pcall(replicatesignal, retryPlay.MouseButton1Click)
                                end
                                if firesignal then
                                    pcall(firesignal, retryPlay.MouseButton1Click)
                                end
                            end)
                        end
                    end

                    if not LocalPlayer.Character then
                        Webhook.textBounded(
[[@everyone Resume failed (no character after Play) - kicking bot]])
                        botKick('sentinel: resume - character never spawned')

                        return
                    end

                    waited = 0

                    while LocalPlayer.Character and not LocalPlayer.Character:FindFirstChild('HumanoidRootPart') and waited < 15 do
                        task.wait(0.25)

                        waited += 0.25
                    end

                    task.wait(1)

                    local resumeHum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                    if resumeHum and resumeHum.Health < 5 and resumeHum.MaxHealth > 5 then
                        task.wait(0.5)

                        resumeHum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                        if resumeHum and resumeHum.Health < 5 and resumeHum.MaxHealth > 5 then
                            botLog(
[[Resume: spawned at %.0f/%.0f health - probable combat log, kicking]], resumeHum.Health, resumeHum.MaxHealth)
                            MemStore.remove('botstarted')
                            MemStore.remove('serverhop_count')
                            Webhook.textBounded('@everyone bot combat logged (under 5 hp on spawn) - kicking')
                            botKick('sentinel: resume - under 5 health, probable combat log')

                            return
                        end
                    end

                    local pathName = MemStore.get('trinket_bot_path')

                    if pathName == '' then
                        pathName = nil
                    end
                    if not pathName or not loadPath(pathName) or #trinket_bot.path_points == 0 then
                        botLog('Resume: saved path %s would not load (%d points) - stopping', tostring(pathName), #trinket_bot.path_points)
                        Webhook.textBounded(string.format(
[[@everyone Resume failed: saved path `%s` would not load - bot stopped]], tostring(pathName)))
                        MemStore.remove('botstarted')

                        return
                    end

                    applySettings(MemStore.getJSON('trinket_bot_settings'))
                    applyBotFps()

                    if ctx.State.syncWebhook then
                        ctx.State.syncWebhook()
                    end
                    if not Toggles.StayInServer.Value then
                        local saved = MemStore.get('lastPlayerPosition')

                        if saved then
                            local x, y, z = saved:match('([^,]+),([^,]+),([^,]+)')

                            if x then
                                local ref = Vector3.new(tonumber(x), tonumber(y), tonumber(z))
                                local closest, closestD = 1, math.huge

                                for idx, pt in trinket_bot.path_points do
                                    local d = (pt.position - ref).Magnitude

                                    if d < closestD then
                                        closestD = d
                                        closest = idx
                                    end
                                end

                                if closest > 1 and closestD < 2000 then
                                    local firstGate

                                    for idx, pt in trinket_bot.path_points do
                                        if pt.is_gate_point then
                                            firstGate = idx

                                            break
                                        end
                                    end

                                    if firstGate and closest > firstGate then
                                        botLog(
[[Resume: interrupted at point %d, gating back in at the first gate (point %d)]], closest, firstGate)

                                        closest = firstGate
                                    end

                                    trinket_bot.resume_start_index = closest
                                end
                            end
                        end
                    end
                    if not Toggles.StayInServer.Value and #trinket_bot.path_points > 0 then
                        local startPoint = (trinket_bot.resume_start_index and trinket_bot.path_points[trinket_bot.resume_start_index]) or trinket_bot.path_points[1]
                        local refs = {
                            startPoint.position,
                        }
                        local spawnHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                        if spawnHrp then
                            table.insert(refs, spawnHrp.Position)
                        end

                        local saved = MemStore.get('lastPlayerPosition')

                        if saved then
                            local x, y, z = saved:match('([^,]+),([^,]+),([^,]+)')

                            if x then
                                table.insert(refs, Vector3.new(tonumber(x), tonumber(y), tonumber(z)))
                            end
                        end

                        local function camperNear()
                            for _, p in Players:GetPlayers()do
                                local ph = p ~= LocalPlayer and p.Character and p.Character:FindFirstChild('HumanoidRootPart')

                                if ph and not isCarriedByMe(p) then
                                    for _, ref in refs do
                                        if (ph.Position - ref).Magnitude <= 180 then
                                            return p.Name
                                        end
                                    end
                                end
                            end

                            return nil
                        end

                        local dragon = Workspace:FindFirstChild('Ice Dragon')
                        local dr = dragon and dragon:FindFirstChild('HumanoidRootPart')

                        if dr then
                            for _, ref in refs do
                                local d = (dr.Position - ref).Magnitude

                                if d <= ICE_DRAGON_RANGE then
                                    botLog(
[[Resume: Ice Dragon %.0f studs from the resume spot - hopping without spawning in]], d)
                                    trinketBotServerhop('Ice Dragon on the resume position')

                                    return
                                end
                            end
                        end
                        if camperNear() then
                            botLog(
[[Resume: player(s) near resume area - waiting 10s before stripping FF]])
                            task.wait(10)

                            if camperNear() then
                                trinketBotServerhop('Player camping resume area')

                                return
                            end
                        end
                    end

                    trinket_bot.skip_distance_check = true

                    task.wait(1)
                    ExecutePath(false)
                end)
            end
        end

        function __DARKLUA_BUNDLE_MODULES.ag(): typeof(__modImpl())
            local v = __DARKLUA_BUNDLE_MODULES.cache.ag

            if not v then
                v = {
                    c = __modImpl(),
                }
                __DARKLUA_BUNDLE_MODULES.cache.ag = v
            end

            return v.c
        end
    end
