            local Paths = __DARKLUA_BUNDLE_MODULES.c()
            local Players, Workspace, RunService, GuiService, CollectionService, StarterGui, UserInputService = Services:Get('Players', 'Workspace', 'RunService', 'GuiService', 'CollectionService', 'StarterGui', 'UserInputService')
            local LocalPlayer = Players.LocalPlayer
            local getconnections = getconnections
            local getupvalues = (debug and debug.getupvalues) or getupvalues or getupvals
            local getreg = getreg
            local getfenv = getfenv
            local islclosure = islclosure or is_l_closure
            local isourclosure = isourclosure or is_synapse_function or checkclosure
            local debugGetconstants = debug and debug.getconstants
            local debugSetupvalue = debug and debug.setupvalue
            local IS_KHEI = Realm.isKhei()
