            local function artifactColor(name)
                if ARTIFACT_MYTHIC[name] then
                    return Color3.fromRGB(255, 0, 80)
                elseif ARTIFACT_TIER[name] then
                    return Color3.fromRGB(160, 100, 160)
                elseif ARTIFACT_RARE[name] then
                    return Color3.fromRGB(60, 150, 150)
                end

                return Color3.fromRGB(189, 97, 29)
            end
            local function getName(player)
                local ok, result = pcall(function()
                    if IS_ATTR_PLACE then
                        local first = player:GetAttribute('FirstName')

                        if not first or first == '' then
                            return 'nil'
                        end

                        local last = player:GetAttribute('LastName')
                        local uber = player:GetAttribute('UberTitle')
                        local full = (last and last ~= '') and (first .. ' ' .. last) or first

                        return (uber and uber ~= '') and (full .. ', ' .. uber) or full
                    elseif IS_KHEI then
                        local ls = player:FindFirstChild('leaderstats')
                        local fn = ls and ls:FindFirstChild('FirstName')

                        if not fn then
                            return 'nil'
                        end

                        local last = ls:FindFirstChild('LastName')

                        last = last and last.Value or ''

                        local uber = ls:FindFirstChild('UberTitle')

                        uber = uber and uber.Value or ''

                        local full = (last ~= '') and (fn.Value .. ' ' .. last) or fn.Value

                        return (uber ~= '') and (full .. ', ' .. uber) or full
                    end

                    return 'nil'
                end)

                return ok and result or 'Unknown'
            end
            local function getFirstName(player)
                local ok, result = pcall(function()
                    if IS_ATTR_PLACE then
                        return player:GetAttribute('FirstName')
                    elseif IS_KHEI then
                        local ls = player:FindFirstChild('leaderstats')
                        local fn = ls and ls:FindFirstChild('FirstName')

                        return fn and fn.Value or nil
                    end

                    return nil
                end)

                return ok and result or nil
            end

            return function(ctx)
                local Library = ctx.Library
