                    local function hasTool(player, name)
                        local bp = player:FindFirstChildOfClass('Backpack')

                        if bp and bp:FindFirstChild(name) then
                            return true
                        end

                        local char = player.Character

                        return char ~= nil and char:FindFirstChild(name) ~= nil
                    end
                    local function hasListedTool(player)
                        for _, pool in {
                            player:FindFirstChildOfClass('Backpack'),
                            player.Character,
                        }do
                            if pool then
                                for _, tool in pool:GetChildren()do
                                    if TOOL_SET[tool.Name] then
                                        return true
                                    end
                                end
                            end
                        end

                        return false
                    end
                    local function hasMaxEdict(player)
                        if player:GetAttribute('MaxEdict') == true then
                            return true
                        end
                        if IS_KHEI then
                            local ls = player:FindFirstChild('leaderstats')
                            local me = ls and ls:FindFirstChild('MaxEdict')

                            return me ~= nil and me.Value == true
                        end

                        return false
                    end
                    local function hasJackTool(player)
                        local char = player.Character

                        if char then
                            local j = char:FindFirstChild('Jack')

                            if j and j:IsA('Tool') then
                                return true
                            end
                        end

                        local bp = player:FindFirstChildOfClass('Backpack')

                        if bp then
                            local j = bp:FindFirstChild('Jack')

                            if j and j:IsA('Tool') then
                                return true
                            end
                        end

                        return false
                    end
                    local function threatColor(player)
                        if not player then
                            return Color3.new(1, 1, 1)
                        end

                        local hasChar = player.Character ~= nil

                        if player == LocalPlayer then
                            return Color3.fromRGB(40, 225, 90)
                        end

                        local isMod = ctx.State.isModerator and ctx.State.isModerator(player) or false

                        if isMod or player:GetAttribute('Hidden') == true or wasHidden[player] or hasJackTool(player) then
                            return hasChar and Color3.fromRGB(255, 90, 255) or Color3.fromRGB(200, 70, 200)
                        end
                        if hasTool(player, 'Observe') then
                            return hasChar and Color3.fromRGB(41, 212, 255) or Color3.fromRGB(77, 150, 158)
                        end
                        if hasMaxEdict(player) then
                            return hasChar and Color3.fromRGB(255, 214, 81) or Color3.fromRGB(180, 160, 7)
                        end
                        if hasListedTool(player) then
                            return hasChar and Color3.fromRGB(240, 80, 80) or Color3.fromRGB(150, 60, 60)
                        end

                        return hasChar and Color3.new(1, 1, 1) or Color3.fromRGB(120, 120, 120)
                    end

                    ctx.State.threatColor = threatColor

                    local function nativeColor(player)
                        return hasMaxEdict(player) and Color3.fromRGB(255, 214, 81) or Color3.new(1, 1, 1)
                    end
                    local function spectate(player)
                        local cam = Workspace.CurrentCamera

                        if spectating == player or player == LocalPlayer then
                            spectating = nil

                            local char = LocalPlayer.Character
                            local hum = char and char:FindFirstChildOfClass('Humanoid')

                            if hum then
                                cam.CameraSubject = hum
                            end
                        else
                            local char = player.Character
                            local hum = char and char:FindFirstChildOfClass('Humanoid')

                            if hum then
                                spectating = player
                                cam.CameraType = Enum.CameraType.Custom
                                cam.CameraSubject = hum
                            end
                        end
                    end
                    local function stopSpectate()
                        if not spectating then
                            return
                        end

                        spectating = nil

                        local char = LocalPlayer.Character
                        local hum = char and char:FindFirstChildOfClass('Humanoid')

                        if hum then
                            Workspace.CurrentCamera.CameraSubject = hum
                        end
                    end

                    ctx.State.spectate = spectate
                    leaderMaid.spectateGone = Players.PlayerRemoving:Connect(function(
                        player
                    )
                        if spectating == player then
                            stopSpectate()
                        end
                    end)

                    local function observingOther()
                        if not spectating then
                            return false
                        end
                        if spectating == LocalPlayer or not spectating.Parent then
                            return false
                        end

                        local cam = Workspace.CurrentCamera
                        local subject = cam and cam.CameraSubject
                        local char = LocalPlayer.Character

                        return subject ~= nil and subject ~= (char and char:FindFirstChildOfClass('Humanoid'))
                    end

                    ctx.State.isSpectating = observingOther

                    local unhideMaid = Maid.new()

                    ctx.Maid:Give(unhideMaid)

                    local unhideActive = false

                    local function clearHidden(player)
                        if player:GetAttribute('Hidden') then
                            wasHidden[player] = true

                            player:SetAttribute('Hidden', false)
                        end
                        if IS_KHEI then
                            local ls = player:FindFirstChild('leaderstats')
                            local h = ls and ls:FindFirstChild('Hidden')

                            if h and h:IsA('BoolValue') and h.Value then
                                wasHidden[player] = true
                                h.Value = false
                            end
                        end
                    end
                    local function watchHidden(player)
                        clearHidden(player)

                        unhideMaid['attr_' .. player.UserId] = player.AttributeChanged:Connect(function(
                            attr
                        )
                            if attr == 'Hidden' and player:GetAttribute('Hidden') then
                                wasHidden[player] = true

                                player:SetAttribute('Hidden', false)
                            end
                        end)

                        if IS_KHEI then
                            local ls = player:FindFirstChild('leaderstats')
                            local h = ls and ls:FindFirstChild('Hidden')

                            if h and h:IsA('BoolValue') then
                                unhideMaid['hidden_' .. player.UserId] = h.Changed:Connect(function(
                                )
                                    if h.Value then
                                        h.Value = false
                                    end
                                end)
                            end
                        end
                    end
                    local function enableUnhide()
                        if unhideActive then
                            return
                        end

                        unhideActive = true

                        for _, p in Players:GetPlayers()do
                            watchHidden(p)
                        end

                        unhideMaid:Connect(Players.PlayerAdded, watchHidden)
                        unhideMaid:Connect(Players.PlayerRemoving, function(p)
                            unhideMaid['attr_' .. p.UserId] = nil
                            unhideMaid['hidden_' .. p.UserId] = nil
                        end)
                    end
                    local function disableUnhide()
                        if not unhideActive then
                            return
                        end

                        unhideActive = false

                        unhideMaid:DoCleaning()

                        for _, p in Players:GetPlayers()do
                            if hasJackTool(p) then
                                p:SetAttribute('Hidden', true)

                                if IS_KHEI then
                                    local ls = p:FindFirstChild('leaderstats')
                                    local h = ls and ls:FindFirstChild('Hidden')

                                    if h and h:IsA('BoolValue') then
                                        h.Value = true
                                    end
                                end
                            end
                        end

                        table.clear(wasHidden)
                    end

                    local selectedPlayer = nil
                    local healthConn = nil
                    local tagsPolling = false
                    local clickMenu = nil

                    ctx.Maid:Give(function()
