                    end)

                    local function applyTitleColor(title, player)
                        title.TextColor3 = (ctx.State.isFriend and ctx.State.isFriend(player)) and Color3.fromRGB(144, 238, 144) or Color3.fromRGB(255, 255, 255)
                    end
                    local function buildClickMenu()
