                                    applyTitleColor(title, selectedPlayer)
                                end
                            end)

                            local subtitle = mkLabel('Subtitle', 2, Enum.Font.SourceSans, 20, Color3.fromRGB(200, 200, 200))
                            local classL = mkLabel('ClassLabel', 3, Enum.Font.SourceSansBold, 19, Color3.fromRGB(240, 80, 80))
                            local cpad = Make('UIPadding', {
