                            local spells = mkLabel('SpellsLabel', 6, Enum.Font.SourceSans, 18, Color3.fromRGB(255, 255, 255))
                            local tags = mkLabel('TagsLabel', 7, Enum.Font.SourceSans, 18, Color3.fromRGB(255, 255, 255))
                            local health = Instance.new('Frame')

                            health.Name = 'Health'
                            health.AnchorPoint = Vector2.new(0.5, 0)
                            health.BackgroundColor3 = Color3.fromRGB(88, 69, 78)
                            health.BorderSizePixel = 0
                            health.Size = UDim2.new(0.867702961, 0, 0, 24)
                            health.SizeConstraint = Enum.SizeConstraint.RelativeXX
                            health.ZIndex = 4
                            health.LayoutOrder = 8
                            health.Parent = main

                            local slider = Make('Frame', {
                                Name = 'Slider',
                                BackgroundColor3 = Color3.fromRGB(206, 61, 48),
                                BorderSizePixel = 0,
                                Size = UDim2.new(1.00247765, 0, 1, 0),
                                ZIndex = 4,
                                Parent = health,
                            })
                            local divider = Make('Frame', {
                                Name = 'Divider',
                                BackgroundColor3 = Color3.fromRGB(97, 25, 25),
                                BorderSizePixel = 0,
                                Position = UDim2.new(1, 0, 0, 0),
                                Size = UDim2.new(0, 1, 1, 0),
                                ZIndex = 4,
                                Parent = slider,
                            })
                            local num = Make('TextLabel', {
                                Name = 'Num',
                                BackgroundTransparency = 1,
                                AnchorPoint = Vector2.new(0.5, 0.5),
                                Position = UDim2.new(0.5, 0, 0.5, 0),
                                Size = UDim2.new(1, 0, 1, 0),
                                Font = Enum.Font.SourceSans,
                                Text = '100 / 100',
                                TextColor3 = Color3.fromRGB(255, 255, 255),
