                                num = num,
                            }
                        end)

                        clickMenu = ok and refs or nil

                        return clickMenu
                    end
                    local function classOf(player)
                        local names = {}

                        for _, pool in {
                            player:FindFirstChildOfClass('Backpack'),
                            player.Character,
                        }do
                            if pool then
                                for _, item in pool:GetChildren()do
                                    if item:IsA('Tool') or item:IsA('Folder') then
                                        names[item.Name] = true
                                    end
                                end
                            end
                        end
                        for className, tools in CLASS_IDENTIFIERS do
                            for _, t in tools do
                                if names[t] then
                                    return className
                                end
                            end
                        end

                        if hasListedTool(player) then
                            return 'Ultra Class'
                        end
                        if hasTool(player, 'Observe') then
                            return 'Observing'
                        end

                        return 'Freshie'
                    end
                    local function collectByMarker(player, isSpell)
                        local found = {}

                        for _, pool in {
                            player:FindFirstChildOfClass('Backpack'),
                            player.Character,
                        }do
                            if pool then
                                for _, item in pool:GetChildren()do
                                    if isSpell then
                                        if item:IsA('Tool') and item:FindFirstChild('Spell') then
                                            table.insert(found, item.Name)
                                        end
                                    else
                                        local isSkill = (item:IsA('Tool') and (item:FindFirstChild('Skill') or item:FindFirstChild('SkillSpell'))) or (item:IsA('Folder') and item:FindFirstChild('Skill'))

                                        if isSkill then
                                            table.insert(found, item.Name)
                                        end
                                    end
                                end
                            end
                        end

                        return found
                    end
                    local function updateHealth(ui, player)
                        local char = player.Character
                        local hum = char and char:FindFirstChildOfClass('Humanoid')

                        if not hum then
                            ui.health.Visible = false

                            return
                        end

                        ui.health.Visible = true

                        local pct = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)

                        ui.slider.Size = UDim2.new(pct, 0, 1, 0)
                        ui.num.Text = string.format('%d / %d', math.floor(hum.Health), math.floor(hum.MaxHealth))
                    end
                    local function showClickMenu(player)
                        local ui = buildClickMenu()

                        if not ui then
                            return
                        end
                        if healthConn then
                            healthConn:Disconnect()

                            healthConn = nil
                        end

                        tagsPolling = false

                        if not player or (selectedPlayer == player and ui.screen.Enabled) then
                            ui.screen.Enabled = false
                            selectedPlayer = nil

                            return
                        end

                        selectedPlayer = player
                        ui.title.Text = (player == LocalPlayer and ctx.State.streamerName and ctx.State.streamerName()) or (ctx.State.maskUser and ctx.State.maskUser(player)) or player.Name

                        applyTitleColor(ui.title, player)

                        local raceName = (ctx.State.maskRogue and ctx.State.maskRogue(player, getName(player))) or getName(player)

                        ui.subtitle.Text = raceName
                        ui.subtitle.TextColor3 = (hasTool(player, 'ObserveBlock') or hasTool(player, 'Watchful')) and Color3.fromRGB(255, 215, 0) or Color3.fromRGB(200, 200, 200)
                        ui.classL.Text = classOf(player)
                        ui.blessings.Visible = false

                        if game.PlaceId == 3541987450 and player.Character then
                            local bf = player.Character:FindFirstChild('Blessings')

                            if bf then
                                local names = {}

                                for _, b in bf:GetChildren()do
                                    table.insert(names, b.Name)
                                end

                                if #names > 0 then
                                    ui.blessings.Text = table.concat(names, ', ')
                                    ui.blessings.Visible = true
                                end
                            end
                        end

                        ui.artifacts.Visible = false

                        local bp = player:FindFirstChildOfClass('Backpack')

                        if bp then
                            local counts, order = {}, {}

                            for _, tool in bp:GetChildren()do
                                if tool:IsA('Tool') and ARTIFACTS_SET[tool.Name] then
                                    if not counts[tool.Name] then
                                        table.insert(order, tool.Name)
                                    end

                                    counts[tool.Name] = (counts[tool.Name] or 0) + 1
                                end
                            end

                            if #order > 0 then
                                local parts = {}

                                for _, name in order do
                                    local c = artifactColor(name)

                                    table.insert(parts, string.format('<font color="rgb(%d,%d,%d)">%dx %s</font>', math.floor(c.R * 255), math.floor(c.G * 255), math.floor(c.B * 255), counts[name], name))
                                end

                                ui.artifacts.Text = 'Artifacts: ' .. table.concat(parts, ', ')
                                ui.artifacts.Visible = true
                            end
                        end

                        local skills = collectByMarker(player, false)
                        local spells = collectByMarker(player, true)

                        ui.skills.Text = 'Skills: ' .. (#skills > 0 and table.concat(skills, ', ') or 'None')
                        ui.spells.Text = 'Spells: ' .. (#spells > 0 and table.concat(spells, ', ') or 'None')

                        updateHealth(ui, player)

                        local hum = player.Character and player.Character:FindFirstChildOfClass('Humanoid')

                        if hum then
                            healthConn = hum.HealthChanged:Connect(function()
                                if selectedPlayer == player then
                                    updateHealth(ui, player)
                                end
                            end)
                        end

                        ui.screen.Enabled = true
                        tagsPolling = true

                        task.spawn(function()
                            while tagsPolling and selectedPlayer == player and ui.screen.Enabled do
                                local char = player.Character
                                local tags = char and CollectionService:GetTags(char) or {}

                                ui.tags.Text = 'Tags: ' .. (#tags > 0 and table.concat(tags, ', ') or 'None')

                                task.wait(0.05)
                            end
                        end)
                    end

                    ctx.Maid:Give(function()
                        tagsPolling = false
                        selectedPlayer = nil

                        if clickMenu and clickMenu.screen then
                            pcall(function()
                                clickMenu.screen:Destroy()
                            end)
                        end
                    end)

                    local labelsNeedingButtons = {}
                    local SPROC = setmetatable({}, {
                        __mode = 'k',
                    })
                    local installed = false
                    local currentLeaderboardGui = nil
                    local menuClone = nil

                    local function wantButtons()
                        return Toggles.LeaderboardObserve and Toggles.LeaderboardObserve.Value or Toggles.BetterLeaderboard.Value
                    end
                    local function gameLeaderboard()
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                        if not pg then
                            return nil, nil
                        end

                        for _, child in pg:GetChildren()do
                            if child.Name == 'LeaderboardGui' and child ~= menuClone then
                                return child, pg
                            end
                        end

                        return nil, pg
                    end
                    local function dropMenuClone()
                        if menuClone then
                            pcall(function()
                                menuClone:Destroy()
                            end)

                            menuClone = nil
                        end
                    end
                    local function updatePlayerLabel(player, label)
                        if unloading or not player or not label or not label:IsA('TextLabel') then
                            return
                        end
                        if Toggles.BetterLeaderboard.Value then
                            label.TextColor3 = threatColor(player)
                        else
                            label.TextColor3 = nativeColor(player)
                        end
                    end

                    local scrambleLabels = {}
                    local scrambleOff = false
                    local scramblePending = setmetatable({}, {
                        __mode = 'k',
                    })
                    local scrambleBound = setmetatable({}, {
                        __mode = 'k',
                    })

                    local function dropScramble(label)
                        local entry = scrambleLabels[label]

                        if entry then
                            scrambleLabels[label] = nil

                            for _, conn in entry.conns do
                                pcall(function()
                                    conn:Disconnect()
                                end)
                            end
                        end

                        scrambleBound[label] = nil
                        scramblePending[label] = nil
                    end
                    local function bindScramble(player, label)
                        if scrambleBound[label] or player == LocalPlayer or not label.Parent then
                            return
                        end

                        for old in scrambleLabels do
                            if not old.Parent then
                                dropScramble(old)
                            end
                        end

                        scrambleBound[label] = true

                        local hovered = false

                        local function paint()
                            if scrambleOff or not (ctx.State.scrambleOn and ctx.State.scrambleOn()) then
                                return
                            end

                            local want = hovered and ctx.State.maskUser(player) or ctx.State.maskRogue(player, getName(player))

                            if want and want ~= '' and label.Text ~= want then
                                label.Text = want
                            end
                        end
                        local function restore()
                            local want = getName(player)

                            if label.Parent and want and want ~= '' and label.Text ~= want then
                                label.Text = want
                            end
                        end

                        local entry = {
                            paint = paint,
                            restore = restore,
                            conns = {},
                        }

                        scrambleLabels[label] = entry

                        table.insert(entry.conns, label.MouseEnter:Connect(function(
                        )
                            hovered = true

                            paint()
                        end))
                        table.insert(entry.conns, label.MouseLeave:Connect(function(
                        )
                            hovered = false

                            paint()
                        end))
                        table.insert(entry.conns, label:GetPropertyChangedSignal('Text'):Connect(paint))
                        table.insert(entry.conns, label.Destroying:Connect(function(
                        )
                            dropScramble(label)
                        end))
                        paint()
                    end

                    ctx.State.leaderboardLabelFor = function(player)
                        for label, who in pairs(playerLabels)do
                            if who == player and label.Parent then
                                return label
                            end
                        end

                        return nil
                    end

                    local function pinScramble(player, label)
                        if player == LocalPlayer then
                            return
                        end

                        scramblePending[label] = player

                        if ctx.State.scrambleOn and ctx.State.scrambleOn() then
                            bindScramble(player, label)
                        end
                    end
                    local function applyPrestige(on)
                        for label, player in pairs(playerLabels)do
                            local badge = label.Parent and label:FindFirstChild('Prestige')

                            if badge then
                                if on then
                                    if badge.Visible then
                                        badge.Visible = false
                                    end
                                else
                                    local rank = player:GetAttribute('Prestige')

                                    badge.Visible = type(rank) == 'number' and rank > 0
                                end
                            end
                        end
                    end

                    ctx.State.applyPrestige = applyPrestige
                    ctx.State.refreshScramble = function(on)
                        if on then
                            scrambleOff = false

                            for label, player in pairs(scramblePending)do
                                pcall(bindScramble, player, label)
                            end
                            for _, entry in scrambleLabels do
                                pcall(entry.paint)
                            end

                            pcall(applyPrestige, true)

                            return
                        end

                        scrambleOff = true

                        for _, entry in scrambleLabels do
                            pcall(entry.restore)
                        end

                        pcall(applyPrestige, false)
                    end

                    ctx.Maid:Give(function()
                        scrambleOff = true

                        for _, entry in scrambleLabels do
                            for _, conn in entry.conns do
                                pcall(function()
                                    conn:Disconnect()
                                end)
                            end

                            pcall(entry.restore)
                        end

                        scrambleLabels = {}

                        pcall(applyPrestige, false)
                    end)

                    local function updateAllLabels()
                        local snapshot = {}

                        for label, player in pairs(playerLabels)do
                            snapshot[label] = player
                        end
                        for label, player in pairs(snapshot)do
                            if label and label.Parent and label:IsA('TextLabel') and player and Players:FindFirstChild(player.Name) then
                                local ok = pcall(updatePlayerLabel, player, label)

                                if not ok then
                                    playerLabels[label] = nil
                                end
                            else
                                playerLabels[label] = nil
                            end
                        end
                    end
                    local function NameRightClick(Player, Label)
                        if not (Player and typeof(Player) == 'Instance' and Player:IsA('Player')) then
                            return
                        end
                        if not (Label and typeof(Label) == 'Instance' and Label:IsA('TextLabel') and Label.Parent) then
                            return
                        end

                        playerLabels[Label] = Player

                        updatePlayerLabel(Player, Label)

                        if not wantButtons() then
                            return Label
                        end

                        local existing = Label:FindFirstChild('SPB')
                        local Button = existing or Instance.new('TextButton', Label)

                        Button.Name = 'SPB'
                        Button.BackgroundTransparency = 1
                        Button.TextTransparency = 1
                        Button.Text = ''
                        Button.AutoButtonColor = false
                        Button.Active = true
                        Button.Size = UDim2.new(1, 0, 1, 0)
                        Button.Position = UDim2.new(0, 0, 0, 0)
                        Button.ZIndex = 50

                        if not existing then
                            Button.MouseButton2Click:Connect(function()
                                if Toggles.LeaderboardObserve.Value then
                                    spectate(Player)
                                end
                            end)
                            Button.MouseButton1Click:Connect(function()
                                if Toggles.BetterLeaderboard.Value then
                                    showClickMenu(Player)
                                end
                            end)
                        end

                        return Label
                    end
                    local function processLeaderboardLabel(label)
                        if not label:IsA('TextLabel') then
                            return
                        end

                        task.spawn(function()
                            local ok, conns = pcall(getconnections, label.MouseEnter)

                            if not ok or not conns then
                                return
                            end

                            for _, connection in pairs(conns)do
                                if connection.Function then
                                    local ok2, upvalues = pcall(getupvalues, connection.Function)

                                    if ok2 and upvalues then
                                        for _, value in pairs(upvalues)do
                                            local player = nil

                                            if type(value) == 'string' then
                                                player = Players:FindFirstChild((value:gsub('\u{200e}', '')))
                                            elseif typeof(value) == 'Instance' and value:IsA('Player') then
                                                player = value
                                            end
                                            if player then
                                                playerLabels[label] = player

                                                updatePlayerLabel(player, label)
                                                pcall(pinScramble, player, label)
                                                pcall(NameRightClick, player, label)

                                                return
                                            end
                                        end
                                    end
                                end
                            end
                        end)
                    end
                    local function initializeLeaderboard()
                        local leaderboardGui = gameLeaderboard() or menuClone

                        if not leaderboardGui or currentLeaderboardGui == leaderboardGui then
                            return
                        end

                        currentLeaderboardGui = leaderboardGui

                        local ok, frame = pcall(function()
                            return leaderboardGui:WaitForChild('MainFrame', 5):WaitForChild('ScrollingFrame', 5)
                        end)

                        if not ok or not frame or not leaderboardGui.Parent then
                            return
                        end

                        for _, label in frame:GetChildren()do
                            if label:IsA('TextLabel') then
                                processLeaderboardLabel(label)
                            end
                        end

                        leaderMaid.lbAdded = frame.ChildAdded:Connect(function(
                            label
                        )
                            if label:IsA('TextLabel') then
                                task.wait(0.1)
                                processLeaderboardLabel(label)
                            end
                        end)
                        leaderMaid.lbRemoved = frame.ChildRemoved:Connect(function(
                            label
                        )
                            playerLabels[label] = nil
                        end)
                    end
                    local function InTable(Table, Value)
                        for _, v in pairs(Table)do
                            if v == Value then
                                return true
                            end
                        end

                        return false
                    end
                    local function Find(container, predicate)
                        local upvalues = container

                        if typeof(container) == 'function' then
                            upvalues = getupvalues(container)
                        end
                        if type(upvalues) ~= 'table' then
                            return nil
                        end

                        for i, v in pairs(upvalues)do
                            local ok, res = pcall(predicate, v)

                            if ok and res then
                                return v, i
                            end
                        end

                        return nil
                    end
                    local function InitSpectator()
                        if not (getreg and getupvalues and debugSetupvalue and getfenv and islclosure and debugGetconstants) then
                            return
                        end

                        pcall(function()
                            local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                            local leaderboardGui = pg and pg:WaitForChild('LeaderboardGui', 50)

                            if not leaderboardGui then
                                return
                            end

                            pcall(function()
                                leaderboardGui:WaitForChild('LeaderboardClient', 10)
                            end)
                            task.wait()
                            pcall(function()
                                collectgarbage('collect')
                            end)
                            task.wait(0.1)

                            for _, v in pairs(getreg())do
                                if typeof(v) == 'function' and islclosure(v) and not (isourclosure and isourclosure(v)) then
                                    local scrOk, scr = pcall(function()
                                        return getfenv(v).script
                                    end)

                                    if scrOk and scr and scr.Name == 'LeaderboardClient' then
                                        local ups = getupvalues(v)
                                        local builder, builderIndex = Find(ups, function(
                                            x
                                        )
                                            return typeof(x) == 'function' and InTable(debugGetconstants(x), 'HouseRank')
                                        end)

                                        if builder then
                                            local labelsTable = Find(builder, function(
                                                x
                                            )
                                                return typeof(x) == 'table' and x[LocalPlayer] ~= nil
                                            end)

                                            if labelsTable then
                                                for player, lbl in pairs(labelsTable)do
                                                    pcall(NameRightClick, player, lbl)
                                                end
                                            end

                                            local Index = (SPROC[v] and SPROC[v].Index) or builderIndex
                                            local Original = (SPROC[v] and SPROC[v].Function) or getupvalues(v)[Index]

                                            SPROC[v] = {
                                                Index = Index,
                                                Function = Original,
                                            }

                                            debugSetupvalue(v, Index, function(
                                                Player,
                                                ...
                                            )
                                                local Label = Original(Player,
...)

                                                if Player and Label and #labelsNeedingButtons < 100 then
                                                    table.insert(labelsNeedingButtons, {
                                                        label = Label,
                                                        player = Player,
                                                    })
                                                end

                                                return Label
                                            end)
                                        end
                                    end
                                end
                            end
                        end)
                    end
                    local function ensureMenuLeaderboard()
                        local game, pg = gameLeaderboard()

                        if not pg then
                            return
                        end
                        if game then
                            dropMenuClone()

                            if not game.Enabled then
                                game.Enabled = true
                            end

                            return
                        end
                        if not (Toggles.Leaderboard and Toggles.Leaderboard.Value) then
                            dropMenuClone()

                            return
                        end
                        if menuClone and menuClone.Parent then
                            if not menuClone.Enabled then
                                menuClone.Enabled = true
                            end

                            return
                        end

                        menuClone = nil

                        if LocalPlayer.Character then
                            return
                        end

                        local src = StarterGui:FindFirstChild('LeaderboardGui')

                        if src then
                            pcall(function()
                                local c = src:Clone()

                                c.Enabled = true
                                c.ResetOnSpawn = false
                                c.Parent = pg
                                menuClone = c
                            end)
                        end
                    end
                    local function scanLeaderboard()
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local gui = pg and pg:FindFirstChild('LeaderboardGui')
                        local main = gui and gui:FindFirstChild('MainFrame')
                        local scroll = main and main:FindFirstChild('ScrollingFrame')

                        if not scroll then
                            return
                        end

                        for _, label in scroll:GetChildren()do
                            if label:IsA('TextLabel') and not playerLabels[label] then
                                processLeaderboardLabel(label)
                            end
                        end
                    end

                    local spectatorBusy = false

                    local function initSpectatorOnce()
                        if spectatorBusy then
                            return
                        end

                        spectatorBusy = true

                        task.spawn(function()
                            pcall(InitSpectator)

                            spectatorBusy = false
                        end)
                    end
                    local function install()
                        if installed then
                            return
                        end

                        installed = true

                        pcall(function()
                            Workspace.CurrentCamera.CameraType = Enum.CameraType.Custom
                        end)
                        task.spawn(function()
                            local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                            if pg then
                                leaderMaid.guiAdded = pg.ChildAdded:Connect(function(
                                    child
                                )
                                    if child.Name == 'LeaderboardGui' then
                                        task.wait(1)
                                        initializeLeaderboard()
                                        initSpectatorOnce()
                                    end
                                end)
                            end

                            local waited = 0

                            while waited < 30 do
                                ensureMenuLeaderboard()

                                local p = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                                if p and p:FindFirstChild('LeaderboardGui') then
                                    break
                                end

                                task.wait(0.5)

                                waited += 0.5
                            end

                            task.wait(0.5)
                            initializeLeaderboard()
                        end)

                        leaderMaid.charAdded = LocalPlayer.CharacterAdded:Connect(function(
                        )
                            stopSpectate()
                            dropMenuClone()
                            task.wait(1)

                            currentLeaderboardGui = nil

                            initializeLeaderboard()
                            initSpectatorOnce()
                        end)
                        leaderMaid.drain = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                        )
                            if #labelsNeedingButtons > 0 then
                                local toProcess = {}

                                for i, item in ipairs(labelsNeedingButtons)do
                                    toProcess[i] = item
                                end

                                for i = #labelsNeedingButtons, 1, -1 do
                                    labelsNeedingButtons[i] = nil
                                end

                                for _, item in ipairs(toProcess)do
                                    local label, player = item.label, item.player

                                    if label and label.Parent and player then
                                        local old = label:FindFirstChild('SPB')

                                        if old then
                                            old:Destroy()
                                        end

                                        pcall(NameRightClick, player, label)
                                    end
                                end
                            end
                        end))

                        local enabledAccum, colorAccum = 0, 0

                        leaderMaid.loop = RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                            dt
                        )
                            enabledAccum += dt
                            colorAccum += dt

                            if enabledAccum >= 0.4 then
                                enabledAccum = 0

                                if Toggles.BetterLeaderboard.Value then
                                    enableUnhide()
                                else
                                    disableUnhide()
                                end

                                ensureMenuLeaderboard()
                                scanLeaderboard()

                                if ctx.State.scrambleOn and ctx.State.scrambleOn() then
                                    pcall(applyPrestige, true)
                                end

                                for label, player in pairs(playerLabels)do
                                    if label and label.Parent then
                                        local btn = label:FindFirstChild('SPB')

                                        if not wantButtons() then
                                            if btn then
                                                btn:Destroy()
                                            end
                                        elseif not btn and player and player.Parent then
                                            pcall(NameRightClick, player, label)
                                        end
                                    end
                                end

                                if spectating and Toggles.LeaderboardObserve.Value then
                                    local tchar = spectating.Character
                                    local thum = tchar and tchar:FindFirstChildOfClass('Humanoid')

                                    if thum then
                                        Workspace.CurrentCamera.CameraSubject = thum
                                    else
                                        stopSpectate()
                                    end
                                end
                            end
                            if colorAccum >= 3 then
                                colorAccum = 0

                                updateAllLabels()
                            end
                        end))

                        task.spawn(function()
                            pcall(InitSpectator)
                        end)
                    end

                    ctx.Maid:Give(function()
                        unloading = true

                        leaderMaid:DoCleaning()

                        for fn, data in pairs(SPROC)do
                            if debugSetupvalue then
                                pcall(debugSetupvalue, fn, data.Index, data.Function)
                            end
                        end

                        SPROC = {}

                        for label, player in pairs(playerLabels)do
                            if label and label.Parent then
                                local btn = label:FindFirstChild('SPB')

                                if btn then
                                    pcall(function()
                                        btn:Destroy()
                                    end)
                                end

                                pcall(function()
                                    label.TextColor3 = nativeColor(player)
                                end)
                            end
                        end

                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                        for _, gui in (pg and pg:GetChildren()) or {}do
                            if gui.Name == 'LeaderboardGui' then
                                local frame = gui:FindFirstChild('MainFrame')

                                frame = frame and frame:FindFirstChild('ScrollingFrame')

                                for _, label in (frame and frame:GetChildren()) or {}do
                                    if label:IsA('TextLabel') and not playerLabels[label] then
                                        local btn = label:FindFirstChild('SPB')

                                        if btn then
                                            pcall(function()
                                                btn:Destroy()
                                            end)
                                        end

                                        pcall(function()
                                            label.TextColor3 = Color3.new(1, 1, 1)
                                        end)
                                    end
                                end
                            end
                        end

                        dropMenuClone()

                        if not LocalPlayer.Character then
                            local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                            if pg then
                                for _, child in pg:GetChildren()do
                                    if child.Name == 'LeaderboardGui' then
                                        pcall(function()
                                            child.Enabled = false
                                        end)
                                    end
                                end
                            end
                        end

                        stopSpectate()
                    end)

                    local function sync()
                        if not Toggles.LeaderboardObserve.Value then
                            stopSpectate()
                        end
                        if not Toggles.BetterLeaderboard.Value then
                            showClickMenu(nil)
                        end

                        pcall(updateAllLabels)
                    end

                    Box:AddToggle('LeaderboardObserve', {
                        Text = 'Leaderboard Observe',
                        Tooltip = 'Right click a name to spectate',
                        Default = true,
                        Callback = sync,
                    })
                    Box:AddToggle('Leaderboard', {
                        Text = 'Leaderboard in Menu',
                        Default = true,
                        Callback = function()
                            ensureMenuLeaderboard()
                        end,
                    })
                    Box:AddToggle('BetterLeaderboard', {
                        Text = 'Better Leaderboard',
                        Tooltip = 'Colours names by threat, shows hidden players',
                        Default = true,
                        Callback = sync,
                    })
                    Box:AddDivider()

                    if getconnections and getupvalues then
                        task.spawn(install)
                    end
                end
                do
                    local overlayMaid = Maid.new()

                    ctx.Maid:Give(overlayMaid)

                    local spellvis, snapvis
                    local currentSpell

                    local function clearVisuals()
                        if spellvis then
                            spellvis.Visible = false
                        end
                        if snapvis then
                            snapvis.Visible = false
                        end
                    end
                    local function ensureDrawings()
                        if spellvis then
                            return true
                        end

                        local ok = pcall(function()
                            spellvis = Drawing.new('Square')
                            spellvis.Visible = false
                            spellvis.Transparency = 0.45
                            spellvis.Filled = true
                            spellvis.ZIndex = 100
                            spellvis.Color = Color3.fromRGB(255, 0, 0)
                            snapvis = Drawing.new('Square')
                            snapvis.Visible = false
                            snapvis.Transparency = 0.45
                            snapvis.Filled = true
                            snapvis.ZIndex = 100
                            snapvis.Color = Color3.fromRGB(0, 0, 255)
                        end)

                        return ok and spellvis ~= nil
                    end
                    local function updateVisuals(tool)
                        if not Toggles.ManaOverlay.Value or not LocalPlayer.Character then
                            clearVisuals()

                            return
                        end
                        if not ensureDrawings() then
                            return
                        end

                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local statGui = pg and pg:FindFirstChild('StatGui')
                        local left = statGui and statGui:FindFirstChild('LeftContainer')
                        local manaBar = left and left:FindFirstChild('Mana')
                        local char = LocalPlayer.Character

                        if not manaBar or not tool or not tool:IsDescendantOf(char) then
                            clearVisuals()

                            return
                        end

                        local spellCost = ctx.State.spellCost
                        local spell = spellCost and spellCost[tool.Name]

                        if not spell or not spell[1] then
                            clearVisuals()

                            return
                        end

                        local boost = 0
                        local boosts = char:FindFirstChild('Boosts')
                        local scholars = boosts and boosts:FindFirstChild('ScholarsBoon')

                        if scholars then
                            boost += scholars.Value
                        end

                        local bp = LocalPlayer:FindFirstChildOfClass('Backpack')

                        if bp then
                            if bp:FindFirstChild('WiseCasting') then
                                boost += 2
                            end
                            if bp:FindFirstChild('RemTraining') then
                                boost += 3
                            end
                        end

                        local baseX, baseY = manaBar.AbsolutePosition.X, manaBar.AbsolutePosition.Y
                        local barW, barH = manaBar.AbsoluteSize.X, manaBar.AbsoluteSize.Y
                        local inset = GuiService:GetGuiInset().Y

                        local function getY(p)
                            return baseY + barH * (1 - p / 100) + inset
                        end

                        local hi = getY(math.min(100, spell[1][2] + boost))

                        spellvis.Position = Vector2.new(baseX, hi)
                        spellvis.Size = Vector2.new(barW, math.abs(getY(math.max(0, spell[1][1] - boost)) - hi))
                        spellvis.Visible = true

                        if spell[2] then
                            local shi = getY(math.min(100, spell[2][2] + boost))

                            snapvis.Position = Vector2.new(baseX, shi)
                            snapvis.Size = Vector2.new(barW, math.abs(getY(math.max(0, spell[2][1] - boost)) - shi))
                            snapvis.Visible = true
                        else
                            snapvis.Visible = false
                        end
                    end
                    local function equippedSpell()
                        local char = LocalPlayer.Character
                        local sc = ctx.State.spellCost

                        if not char or not sc then
                            return nil
                        end

                        for _, t in char:GetChildren()do
                            if t:IsA('Tool') and sc[t.Name] then
                                return t
                            end
                        end

                        return nil
                    end
                    local function setupCharacter(char)
                        currentSpell = nil

                        if not char then
                            return
                        end

                        overlayMaid.charChild = char.ChildAdded:Connect(function(
                            child
                        )
                            local sc = ctx.State.spellCost

                            if child:IsA('Tool') and sc and sc[child.Name] then
                                currentSpell = child

                                updateVisuals(child)

                                overlayMaid.spellMoved = child.AncestryChanged:Connect(function(
                                )
                                    if not child:IsDescendantOf(LocalPlayer.Character) then
                                        clearVisuals()

                                        currentSpell = nil
                                    end
                                end)
                            end
                        end)

                        updateVisuals(equippedSpell())
                    end

                    Box:AddToggle('AutoDialogue', {
                        Text = 'Auto Dialogue',
                        Tooltip = Gate.risky('skips through NPC dialogue'),
                        Default = false,
                        Callback = function(on)
                            if on and ctx.State.autoDialogueSetup then
                                task.spawn(ctx.State.autoDialogueSetup)
                            elseif not on and ctx.State.autoDialogueTeardown then
                                ctx.State.autoDialogueTeardown()
                            end
                        end,
                    })
                    Gate.mark(ctx, 'Risky', 'AutoDialogue')
                    Box:AddToggle('AutoBard', {
                        Text = 'Auto Bard',
                        Default = false,
                        Callback = function(on)
                            if on and ctx.State.autoBardSetup then
                                task.spawn(ctx.State.autoBardSetup)
                            elseif not on and ctx.State.autoBardClear then
                                ctx.State.autoBardClear()
                            end
                        end,
                    })

                    do
                        local ORIGINAL, SOUND_ID = 'Original', 'Sound ID'
                        local bardControls = {}
                        local songPick, musicPick, idBox
                        local syncing = false

                        local function bm()
                            return ctx.State.bardMusic
                        end
                        local function showBardMusic(on)
                            for _, c in bardControls do
                                if c.SetVisible then
                                    c:SetVisible(on)
                                elseif c.Holder then
                                    c.Holder.Visible = on
                                end
                            end
                        end

                        local shownLists

                        local function refreshLists()
                            local engine = bm()

                            if not (engine and songPick and musicPick) then
                                return
                            end

                            local songs = engine.songs()
                            local files = engine.files()

                            table.insert(files, 1, ORIGINAL)
                            table.insert(files, 2, SOUND_ID)

                            local key = table.concat(songs, '\0') .. '\1' .. table.concat(files, '\0')

                            if key == shownLists then
                                return
                            end

                            shownLists = key

                            songPick:SetValues(songs)
                            musicPick:SetValues(files)

                            if songPick.Value == nil and songs[1] then
                                songPick:SetValue(songs[1])
                            end
                        end

                        local pairsLabel

                        local function showPairs()
                            local engine = bm()

                            if not (engine and pairsLabel) then
                                return
                            end

                            local rows = {}

                            for song, pick in engine.map()do
                                local id = tostring(pick):match('^id:(%d+)$')

                                table.insert(rows, song .. ': ' .. (id and ('ID ' .. id) or tostring(pick)))
                            end

                            table.sort(rows)
                            pairsLabel:SetText(#rows > 0 and table.concat(rows, '\n') or 'No songs changed yet')
                        end
                        local function syncMusic()
                            showPairs()

                            local engine, song = bm(), songPick and songPick.Value

                            if not (engine and musicPick and idBox and song) then
                                return
                            end

                            local picked = engine.map()[song]
                            local id = type(picked) == 'string' and picked:match('^id:(%d+)$')

                            syncing = true

                            idBox:SetValue(id or '')
                            musicPick:SetValue((id and SOUND_ID) or picked or ORIGINAL)

                            syncing = false
                        end
                        local function setPick(want)
                            local engine, song = bm(), songPick.Value

                            if syncing or not (engine and song) then
                                return
                            end

                            local map = engine.map()

                            if map[song] == want then
                                return
                            end

                            map[song] = want

                            Json.write(Paths.BARD_MUSIC, map)
                            Library.Options.BardMusicMap:SetValue(Services:Get('HttpService'):JSONEncode(map))
                            engine.apply()
                        end

                        local listMaid = Maid.new()

                        ctx.Maid:Give(listMaid)
                        Box:AddToggle('CustomBardMusic', {
                            Text = 'Custom Bard Music',
                            Tooltip = 'Songs go in workspace/sentinel/bard',
                            Default = false,
                            Callback = function(on)
                                showBardMusic(on)
                                listMaid:DoCleaning()

                                local engine = bm()

                                if not engine then
                                    return
                                end
                                if on then
                                    refreshLists()
                                    engine.apply()

                                    listMaid.loop = task.spawn(function()
                                        while true do
                                            task.wait(2)
                                            refreshLists()
                                        end
                                    end)
                                else
                                    engine.stop()
                                end
                            end,
                        })

                        songPick = Box:AddDropdown('BardSong', {
                            Text = 'Change Song',
                            Values = {},
                            AllowNull = true,
                            Callback = syncMusic,
                        })
                        musicPick = Box:AddDropdown('BardMusic', {
                            Text = 'Play For It',
                            Values = {ORIGINAL},
                            Default = ORIGINAL,
                            Callback = function(file)
                                if file == SOUND_ID then
                                    local id = idBox and idBox.Value:match('^%d+$')

                                    if id then
                                        setPick('id:' .. id)
                                    end
                                else
                                    setPick((file ~= ORIGINAL and file) or nil)
                                end
                            end,
                        })
                        idBox = Box:AddInput('BardSoundId', {
                            Text = 'Sound ID',
                            Numeric = true,
                            Finished = true,
                            Placeholder = 'or a roblox sound id for this song',
                            Callback = function(text)
                                if syncing then
                                    return
                                end

                                local id = tostring(text):match('^%d+$')

                                if id then
                                    setPick('id:' .. id)
                                    musicPick:SetValue(SOUND_ID)
                                elseif text == '' and musicPick.Value == SOUND_ID then
                                    setPick(nil)
                                    musicPick:SetValue(ORIGINAL)
                                end
                            end,
                        })

                        local volume = Box:AddSlider('BardMusicVolume', {
                            Text = 'Volume',
                            Default = 1,
                            Min = 0,
                            Max = 3,
                            Rounding = 1,
                            Callback = function(v)
                                local engine = bm()

                                if engine then
                                    engine.setVolume(v)
                                end
                            end,
                        })

                        pairsLabel = Box:AddLabel({
                            Text = 'No songs changed yet',
                            DoesWrap = true,
                        })

                        local refresh = Box:AddButton({
                            Text = 'Refresh Songs',
                            Func = refreshLists,
                        })

                        Box:AddInput('BardMusicMap', {
                            Text = '',
                            Default = '',
                            Finished = true,
                            Visible = false,
                            Callback = syncMusic,
                        })
                        Library.Options.BardMusicMap:SetVisible(false)

                        local savedPairs = Json.read(Paths.BARD_MUSIC)

                        if type(savedPairs) == 'table' and next(savedPairs) ~= nil then
                            Library.Options.BardMusicMap:SetValue(Services:Get('HttpService'):JSONEncode(savedPairs))
                        end

                        bardControls = {
                            songPick,
                            musicPick,
                            idBox,
                            volume,
                            refresh,
                            pairsLabel,
                        }

                        showBardMusic(Toggles.CustomBardMusic.Value)
                        showPairs()
                        task.defer(refreshLists)
                    end

                    Box:AddDivider()

                    local healPad

                    if Menu.isPrivateServer() then
                        healPad = function()
                            if not fireclickdetectorGlobal then
                                return false
                            end

                            local arena = Workspace:FindFirstChild('PrivateServerArena')
                            local pads = arena and arena:FindFirstChild('HealingPads')
                            local part = pads and pads:FindFirstChild('Part')
                            local detector = part and part:FindFirstChildOfClass('ClickDetector')

                            if not detector then
                                return false
                            end

                            return pcall(fireclickdetectorGlobal, detector)
                        end
                        ctx.State.healPad = healPad

                        local healMaid = Maid.new()

                        ctx.Maid:Give(healMaid)
                        Box:AddToggle('LoopHeal', {
                            Text = 'Loop Heal',
                            Tooltip = 'Spams the arena heal pad',
                            Default = false,
                            Callback = function(on)
                                healMaid:DoCleaning()

                                if not on then
                                    return
                                end

                                healMaid.loop = task.spawn(function()
                                    while true do
                                        local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')

                                        if hum and hum.Health > 0 then
                                            healPad()
                                        end

                                        task.wait(LOOP_HEAL_INTERVAL)
                                    end
                                end)
                            end,
                        })
                    end

                    Box:AddLabel('Return to Menu'):AddKeyPicker('ReturnToMenuKeybind', {
                        Default = 'None',
                        Mode = 'Press',
                        Modes = {
                            'Press',
                        },
                        Text = 'Return to Menu',
                        Callback = function()
                            local requests = Services:Get('ReplicatedStorage'):FindFirstChild('Requests')
                            local rtm = requests and requests:FindFirstChild('ReturnToMenu')

                            if rtm and LocalPlayer.Character then
                                pcall(function()
                                    rtm:InvokeServer()
                                end)
                            end
                        end,
                    })

                    if healPad then
                        Box:AddLabel('Private Server Heal'):AddKeyPicker('PrivateServerHealKeybind', {
                            Default = 'None',
                            Mode = 'Press',
                            Modes = {
                                'Press',
                            },
                            Text = 'Private Server Heal',
                            Callback = healPad,
                        })
                    end

                    Box:AddDivider()
                    Box:AddToggle('ManaOverlay', {
                        Text = 'Mana Overlay',
                        Tooltip = "Your spell's cast and snap window on the mana bar",
                        Default = false,
                        Callback = function(on)
                            if on then
                                setupCharacter(LocalPlayer.Character)

                                overlayMaid.respawn = LocalPlayer.CharacterAdded:Connect(setupCharacter)
                                overlayMaid.removing = LocalPlayer.CharacterRemoving:Connect(clearVisuals)
                            else
                                overlayMaid:DoCleaning()
                                clearVisuals()
                            end
                        end,
                    })
                    ctx.Maid:Give(function()
                        clearVisuals()
                        pcall(function()
                            if spellvis then
                                spellvis:Remove()
                            end
                            if snapvis then
                                snapvis:Remove()
                            end
                        end)
                    end)
                end
                do
                    local globusMaid = Maid.new()

                    ctx.Maid:Give(globusMaid)
                    Box:AddToggle('AntiGlobus', {
                        Text = 'Anti Globus',
                        Tooltip = Gate.blatant(),
                        Default = false,
                        Callback = function(on)
                            if not on then
                                globusMaid:DoCleaning()

                                return
                            end

                            local thrown = Workspace:FindFirstChild('Thrown')

                            if not thrown then
                                return
                            end

                            globusMaid:Connect(thrown.ChildAdded, function(
                                child
                            )
                                if child.Name == 'OrderBubble' then
                                    task.defer(function()
                                        child.CanTouch = false
                                    end)
                                end
                            end)
                        end,
                    })
                    Gate.mark(ctx, 'Blatant', 'AntiGlobus')

                    local mineMaid, fryMaid = Maid.new(), Maid.new()

                    ctx.Maid:Give(mineMaid)
                    ctx.Maid:Give(fryMaid)

                    local function spamOnClick(maid, toolName)
                        return function(on)
                            if not on then
                                maid:DoCleaning()

                                return
                            end

                            local ready = true

                            maid:Connect(LocalPlayer.CharacterAdded, function()
                                ready = true
                            end)
                            maid:Connect(UserInputService.InputBegan, function(
                                input,
                                gameProcessed
                            )
                                if gameProcessed or input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                                    return
                                end

                                local char = LocalPlayer.Character
                                local humanoid = char and char:FindFirstChildOfClass('Humanoid')
                                local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')

                                if not (humanoid and backpack and char:FindFirstChild(toolName) and ready and humanoid.Health > 0) then
                                    return
                                end

                                ready = false

                                pcall(function()
                                    humanoid:UnequipTools()

                                    for _, tool in backpack:GetChildren()do
                                        if tool.Name == toolName and humanoid.Health > 0 then
                                            humanoid:EquipTool(tool)

                                            for _ = 1, 8 do
                                                tool:Activate()
                                                humanoid:UnequipTools()
                                            end

                                            humanoid:EquipTool(tool)
                                        end
                                    end
                                end)
                                task.wait(0.05)

                                ready = true
                            end)
                        end
                    end

                    Box:AddToggle('InstantMine', {
                        Text = 'Instant Mine',
                        Tooltip = Gate.risky('have like 5 pickaxes'),
                        Default = false,
                        Callback = spamOnClick(mineMaid, 'Pickaxe'),
                    })
                    Gate.mark(ctx, 'Risky', 'InstantMine')
                    Box:AddToggle('InstantFry', {
                        Text = 'Instant Fry',
                        Tooltip = Gate.risky('have like 5 frying pans'),
                        Default = false,
                        Callback = spamOnClick(fryMaid, 'Frying Pan'),
                    })
                    Gate.mark(ctx, 'Risky', 'InstantFry')
                end
                do
                    local offsetMaid = Maid.new()

                    ctx.Maid:Give(offsetMaid)

                    local ghostMaterial, rootBrick, brickGlow, ghostChar, ghostAccum = {}, nil, nil, nil, 0

                    local function ghostBody(char)
                        for _, part in char:GetDescendants()do
                            if part:IsA('BasePart') and part.Transparency < 1 and ghostMaterial[part] == nil then
                                ghostMaterial[part] = part.Material
                                part.Material = Enum.Material.ForceField
                            end
                        end
                    end
                    local function unghostBody()
                        for part, material in ghostMaterial do
                            if part.Parent then
                                pcall(function()
                                    part.Material = material
                                end)
                            end
                        end

                        table.clear(ghostMaterial)
                    end
                    local function ensureBrick()
                        if rootBrick and rootBrick.Parent then
                            return rootBrick
                        end

                        local brick = Make('Part', {
                            Name = 'Root',
                            Size = Vector3.new(2, 2, 1),
                            Color = Color3.fromRGB(255, 0, 0),
                            Material = Enum.Material.SmoothPlastic,
                            Transparency = 1,
                            Anchored = true,
                            CanCollide = false,
                            CanQuery = false,
                            CanTouch = false,
                            CastShadow = false,
                        })
                        local glow = Make('SelectionBox', {
                            Adornee = brick,
                            Color3 = Color3.fromRGB(255, 0, 0),
                            SurfaceColor3 = Color3.fromRGB(255, 0, 0),
                            SurfaceTransparency = 0.6,
                            Transparency = 0,
                            LineThickness = 0.012,
                            Parent = brick,
                        })

                        brick.Parent = Workspace.CurrentCamera
                        rootBrick, brickGlow = brick, glow

                        return brick
                    end
                    local function clearGhost()
                        unghostBody()

                        ghostChar, ghostAccum = nil, 0

                        if rootBrick then
                            pcall(function()
                                rootBrick:Destroy()
                            end)
                        end

                        rootBrick, brickGlow = nil, nil
                    end

                    Box:AddToggle('CharacterOffset', {
                        Text = 'Character Offset',
                        Default = false,
                        Callback = function(on)
                            offsetMaid:DoCleaning()
                            clearGhost()

                            if not on or not ctx.State.offsetHold then
                                if ctx.State.offsetStop then
                                    ctx.State.offsetStop()
                                end

                                return
                            end

                            ctx.State.offsetStart()
                            offsetMaid:Give(RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                                dt
                            )
                                local char = LocalPlayer.Character
                                local root = char and char:FindFirstChild('HumanoidRootPart')

                                if root and root.Anchored then
                                    root.Anchored = false
                                end

                                ctx.State.offsetHold()

                                if not root then
                                    return
                                end

                                ghostAccum += dt

                                if char ~= ghostChar then
                                    unghostBody()

                                    ghostChar, ghostAccum = char, 0

                                    ghostBody(char)
                                elseif ghostAccum >= 1 then
                                    ghostAccum = 0

                                    ghostBody(char)
                                end

                                ensureBrick().CFrame = root.CFrame
                            end)))
                            offsetMaid:Give(function()
                                clearGhost()

                                if ctx.State.offsetStop then
                                    ctx.State.offsetStop()
                                end
                            end)
                        end,
                    }):AddKeyPicker('CharacterOffsetKeybind', {
                        Default = 'None',
                        Mode = 'Toggle',
                        Text = 'Character Offset',
                        SyncToggleState = true,
                    })
                    Gate.mark(ctx, 'Blatant', 'CharacterOffset')
                end
                do
                    local Options = Library.Options
                    local fireclickdetector = fireclickdetector
                    local busy = false
                    local INN_NAMES = NPC.innNames(IS_KHEI)
                    local nearestInnKeeper = NPC.innKeeper

                    local function needCharacter(label)
                        local char = LocalPlayer.Character

                        if char and char:FindFirstChild('HumanoidRootPart') then
                            return true
                        end

                        Notify.say(label .. ' needs a spawned character')

                        return false
                    end

                    local guardRelease = nil

                    local function guardOn(seconds)
                        if guardRelease or not ctx.State.holdGuards then
                            return
                        end

                        guardRelease = ctx.State.holdGuards(seconds or 6)
                    end
                    local function guardOff()
                        if guardRelease then
                            guardRelease()

                            guardRelease = nil
                        end
                    end
                    local function setInn(name)
                        if not nearestInnKeeper(name) then
                            Notify.say("No '" .. name .. "' keeper here - be in that town first")

                            return false
                        end

                        guardOn(6)

                        local ok = NPC.setInn(name, {
                            breakJoints = true,
                            attempts = 1,
                            verify = false,
                        })

                        guardOff()
                        Notify.say(ok and ('Inn set: ' .. name) or ('Set Inn failed: ' .. name))

                        return ok
                    end
                    local function label(p)
                        local rogue = getName(p)

                        return (rogue and rogue ~= '' and rogue ~= 'Unknown') and (rogue .. ' (' .. p.Name .. ')') or p.Name
                    end
                    local function matchPlayer(query)
                        query = tostring(query or ''):lower():gsub('^%s+', ''):gsub('%s+$', '')

                        if query == '' then
                            return nil
                        end

                        local best, bestScore

                        for _, p in Players:GetPlayers()do
                            if p ~= LocalPlayer then
                                for _, candidate in {
                                    p.Name,
                                    p.DisplayName,
                                    getName(p),
                                }do
                                    local c = candidate and tostring(candidate):lower()
                                    local score

                                    if c == nil or c == '' then
                                        score = nil
                                    elseif c == query then
                                        score = 0
                                    elseif c:sub(1, #query) == query then
                                        score = 1 + (#c - #query)
                                    else
                                        local at = c:find(query, 1, true)

                                        score = at and (1000 + at) or nil
                                    end
                                    if score and (bestScore == nil or score < bestScore) then
                                        best, bestScore = p, score
                                    end
                                end
                            end
                        end

                        return best
                    end

                    local TELEPORTS = {
                        ['Skycastle'] = function()
                            local npcs = Workspace:FindFirstChild('NPCs')
                            local xen = npcs and npcs:FindFirstChild('Xenyari')
                            local xhrp = xen and xen:FindFirstChild('HumanoidRootPart')

                            return xhrp and xhrp.Position
                        end,
                        ["Ya'alda"] = function()
                            local npcs = Workspace:FindFirstChild('NPCs')
                            local yaalda = npcs and npcs:FindFirstChild('Yaalda')
                            local yhrp = yaalda and yaalda:FindFirstChild('HumanoidRootPart')

                            return yhrp and yhrp.Position
                        end,
                        ["Flagellant's Spire"] = function()
                            local npcs = Workspace:FindFirstChild('NPCs')

                            if not npcs then
                                return nil
                            end

                            local model, dist = NPC.nearestModel(npcs, 'Purity', Vector3.new(
-3622, 1220, 2241))
                            local hrp = model and model:FindFirstChild('HumanoidRootPart')

                            return (hrp and dist and dist <= 20) and hrp.Position or nil
                        end,
                    }
                    local TOMELESS_SECONDS = 25
                    local TOMELESS_STEP = 0.025
                    local TELEPORT_NAMES = IS_KHEI and {
                        "Flagellant's Spire",
                    } or {
                        'Skycastle',
                        "Ya'alda",
                    }

                    Box:AddDivider()
                    Box:AddDropdown('SetInnLocation', {
                        Text = 'Inn',
                        Values = INN_NAMES,
                        Multi = false,
                        Default = INN_NAMES[1],
                        Tooltip = 'You have to be in that town',
                    })
                    Box:AddButton({
                        Text = 'Set Inn',
                        Tooltip = Gate.blatant(),
                        Func = function()
                            if busy or not Gate.allow(ctx, 'Blatant', 'Set Inn') or not needCharacter('Set Inn') then
                                return
                            end

                            busy = true

                            task.spawn(function()
                                pcall(setInn, Options.SetInnLocation.Value)

                                busy = false
                            end)
                        end,
                    })
                    Box:AddDropdown('MenuTeleportDest', {
                        Text = 'Teleport',
                        Values = TELEPORT_NAMES,
                        Multi = false,
                        Default = TELEPORT_NAMES[1],
                        Tooltip = 'Menu tp',
                    })
                    Box:AddButton({
                        Text = 'Teleport',
                        Tooltip = Gate.blatant(),
                        Func = function()
                            if busy or not Gate.allow(ctx, 'Blatant', 'Teleport') or not needCharacter('Teleport') then
                                return
                            end

                            local dest = Options.MenuTeleportDest.Value
                            local fn = TELEPORTS[dest]
                            local pos = fn and fn()

                            if not pos then
                                Notify.say(dest .. ' not reachable from here')

                                return
                            end

                            busy = true

                            task.spawn(function()
                                local ok = false

                                pcall(function()
                                    ok = Menu.menuTele(pos, nil, 1)
                                end)
                                Notify.say(ok and ('Teleported to ' .. dest) or ('Teleport to ' .. dest .. ' failed'))

                                busy = false
                            end)
                        end,
                    })

                    local snapping = false

                    local function snapTo(p)
                        if not p or snapping or Options.MenuTeleportPlayer.Value == p.Name then
                            return
                        end

                        snapping = true

                        Options.MenuTeleportPlayer:SetValue(p.Name)

                        snapping = false
                    end

                    Box:AddInput('MenuTeleportPlayer', {
                        Text = 'Player',
                        Placeholder = 'name',
                        Finished = true,
                        Tooltip = 'Partial names work',
                        Callback = function(text)
                            snapTo(matchPlayer(text))
                        end,
                    })
                    Box:AddButton({
                        Text = 'Teleport To Player',
                        Tooltip = Gate.blatant(),
                        Func = function()
                            if busy or not Gate.allow(ctx, 'Blatant', 'Teleport To Player') or not needCharacter('Teleport To Player') then
                                return
                            end

                            local target = matchPlayer(Options.MenuTeleportPlayer.Value)

                            if not target then
                                Notify.say('No player here matching that name')

                                return
                            end

                            snapTo(target)

                            local function where()
                                local h = target.Character and target.Character:FindFirstChild('HumanoidRootPart')

                                return h and h.Position or nil
                            end

                            if not where() then
                                Notify.say(label(target) .. ' has no character to land on')

                                return
                            end

                            busy = true

                            task.spawn(function()
                                local ok = false

                                pcall(function()
                                    ok = Menu.menuTele(where, nil, 1)
                                end)
                                Notify.say(ok and ('Teleported to ' .. label(target)) or ('Teleport to ' .. label(target) .. ' failed'))

                                busy = false
                            end)
                        end,
                    })
                    Box:AddDivider()
                    Box:AddButton({
                        Text = 'Tomeless Sacrifice',
                        Tooltip = Gate.blatant('rides the SpectralFire'),
                        Func = function()
                            if busy or not Gate.allow(ctx, 'Blatant', 'Tomeless Sacrifice') then
                                return
                            end

                            local blatant = Library.Toggles.BlatantMode

                            busy = true

                            task.spawn(function()
                                local noKill = Library.Toggles.NoKillBricks and Library.Toggles.NoKillBricks.Value

                                if noKill and ctx.State.setKillbricks then
                                    pcall(ctx.State.setKillbricks, false)
                                end

                                local prevNoFall = ctx.State.noFallUntil

                                ctx.State.noFallUntil = tick() + TOMELESS_SECONDS + 2

                                local rider = LocalPlayer.Character
                                local humanoid = rider and rider:FindFirstChildOfClass('Humanoid')
                                local deadline = tick() + TOMELESS_SECONDS
                                local rode = false

                                local function riding()
                                    return tick() < deadline and blatant.Value and rider ~= nil and rider.Parent ~= nil and LocalPlayer.Character == rider and not (humanoid and humanoid.Health <= 0)
                                end

                                while riding() do
                                    local map = Workspace:FindFirstChild('Map')

                                    for _, part in (map and map:GetChildren()) or {}do
                                        if not riding() then
                                            break
                                        end
                                        if part:IsA('Part') and part.Name == 'SpectralFire' then
                                            local root = rider:FindFirstChild('HumanoidRootPart')

                                            if root then
                                                rode = true
                                                root.CFrame = part.CFrame * CFrame.Angles(
-1.5, 0, 0) - Vector3.new(0, 2, 0)

                                                task.wait()

