                                    nameMaid.respawn = LocalPlayer.CharacterAdded:Connect(function(
                                    )
                                        pinShadow()

                                        for _ = 1, 12 do
                                            task.wait(0.1)

                                            if currentName == '' then
                                                return
                                            end

                                            applyName(currentName)
                                        end

                                        pinShadow()
                                    end)

                                    if LocalPlayer:GetAttribute('FirstName') ~= nil then
                                        nameMaid.pin = LocalPlayer:GetAttributeChangedSignal('FirstName'):Connect(function(
                                        )
                                            if currentName ~= '' then
                                                applyName(currentName)
                                            end
                                        end)
                                    end

                                    for _, attr in {
                                        'LastName',
                                        'UberTitle',
                                        'HouseRank',
                                    }do
                                        nameMaid['pin' .. attr] = LocalPlayer:GetAttributeChangedSignal(attr):Connect(function(
                                        )
                                            if currentName ~= '' then
                                                applyName(currentName)
                                            end
                                        end)
                                    end
                                end
                            end)
                        end,
                    })

                    local dayMaid = Maid.new()

                    ctx.Maid:Give(dayMaid)

                    local spoofingDays = false
                    local originalDays = {}
                    local daysRespawn

                    local function spoofDays(days)
                        if spoofingDays then
                            return
                        end

                        spoofingDays = true

                        local gui = statGui()
                        local container = gui and gui:FindFirstChild('Container')
                        local health = container and container:FindFirstChild('Health')
                        local lives = health and health:FindFirstChild('Lives')

                        if not lives then
                            spoofingDays = false

                            return
                        end

                        local rollers = {}

                        for _, child in lives:GetChildren()do
                            if child.Name == 'Roller' and child:FindFirstChild('Char') then
                                table.insert(rollers, child)
                            end
                        end

                        if #rollers < 4 then
                            spoofingDays = false

                            return
                        end

                        local hasThousand = #rollers >= 6
                        local slots = hasThousand and {
                            rollers[2],
                            rollers[3],
                            rollers[4],
                            rollers[5],
                        } or {
                            rollers[2],
                            rollers[3],
                            rollers[4],
                        }

                        dayMaid:DoCleaning()

                        local clamped = math.clamp(days, 0, hasThousand and 9999 or 999)
                        local padded = string.format('%0' .. #slots .. 'd', clamped)

                        for i, roller in slots do
                            if originalDays[roller] == nil then
                                originalDays[roller] = roller.Char.Text
                            end

                            roller.Char.Text = string.sub(padded, i, i)
                        end

                        if Toggles.SpoofDays.Value then
                            for _, roller in slots do
                                dayMaid:Connect(roller.Char:GetPropertyChangedSignal('Text'), function(
                                )
                                    if not spoofingDays and Toggles.SpoofDays.Value then
                                        spoofDays(Options.CustomDays.Value)
                                    end
                                end)
                            end
                        end

                        spoofingDays = false
                    end
                    local function restoreDays()
                        dayMaid:DoCleaning()

                        for roller, text in originalDays do
                            if roller and roller.Parent then
                                roller.Char.Text = text
                            end
                        end

                        table.clear(originalDays)
                    end

                    ctx.Maid:Give(restoreDays)

                    local function reapplyDays()
                        if not (Toggles.SpoofDays and Toggles.SpoofDays.Value) then
                            return
                        end

                        task.spawn(function()
                            for _ = 1, 40 do
                                if not (Toggles.SpoofDays and Toggles.SpoofDays.Value) then
                                    return
                                end

                                local gui = statGui()
                                local container = gui and gui:FindFirstChild('Container')
                                local health = container and container:FindFirstChild('Health')
                                local lives = health and health:FindFirstChild('Lives')
                                local count = 0

                                if lives then
                                    for _, child in lives:GetChildren()do
                                        if child.Name == 'Roller' and child:FindFirstChild('Char') then
                                            count += 1
                                        end
                                    end
                                end
                                if count >= 4 then
                                    spoofDays(tonumber(Options.CustomDays.Value) or 0)

                                    return
                                end

                                task.wait(0.2)
                            end
                        end)
                    end

                    ctx.Maid:Give(function()
                        if daysRespawn then
                            daysRespawn:Disconnect()

                            daysRespawn = nil
                        end
                    end)
                    SpoofBox:AddInput('CustomDays', {
                        Text = 'Custom Days',
                        Placeholder = '0-9999',
                        Numeric = true,
                        Default = '0',
                        Finished = true,
                        Callback = function(value)
                            if Toggles.SpoofDays and Toggles.SpoofDays.Value then
                                spoofDays(tonumber(value) or 0)
                            end
                        end,
                    })
                    SpoofBox:AddToggle('SpoofDays', {
                        Text = 'Spoof Days',
                        Default = false,
                        Callback = function(on)
                            if on then
                                spoofDays(tonumber(Options.CustomDays.Value) or 0)

                                if not daysRespawn then
                                    local live = Workspace:FindFirstChild('Live')

                                    if live then
                                        daysRespawn = live.ChildAdded:Connect(function(
                                            child
                                        )
                                            if child:IsA('Model') and child.Name == LocalPlayer.Name then
                                                reapplyDays()
                                            end
                                        end)
                                    else
                                        daysRespawn = LocalPlayer.CharacterAdded:Connect(reapplyDays)
                                    end
                                end
                            else
                                if daysRespawn then
                                    daysRespawn:Disconnect()

                                    daysRespawn = nil
                                end

                                restoreDays()
                            end
                        end,
                    })
                    SpoofBox:AddDivider()

                    if hookfunction and CollectionService.HasTag then
                        local oldHasTag

                        local function replacement(self, object, tag)
                            if (not checkcaller or not checkcaller()) and object == LocalPlayer.Character then
                                if tag == 'The Soul' and Toggles.SpoofTheSoul and Toggles.SpoofTheSoul.Value then
                                    return true
                                end
                                if tag == 'Acrobat' and Toggles.SpoofAcrobat and Toggles.SpoofAcrobat.Value then
                                    return true
                                end
                            end

                            return oldHasTag(self, object, tag)
                        end

                        oldHasTag = hookfunction(CollectionService.HasTag, newcclosure and newcclosure(replacement) or replacement)

                        ctx.Maid:Give(function()
                            pcall(hookfunction, CollectionService.HasTag, oldHasTag)
                        end)
                    end

                    SpoofBox:AddToggle('SpoofTheSoul', {
                        Text = 'Spoof The Soul',
                        Default = false,
                    })
                    SpoofBox:AddToggle('SpoofAcrobat', {
                        Text = 'Spoof Acrobat',
                        Default = false,
                    })
                    SpoofBox:AddDivider()

                    local getConnections = getconnections or get_signal_cons or (getgenv and getgenv().getconnections)
                    local streamerConns = {}
                    local disabledConns = {}
                    local rowConns = {}
                    local deathPins = {}
                    local ragoozerFrame
                    local rowSwap
                    local streamerRespawn
                    local deathWatch = false
                    local menuConn
                    local menuBusy = false
                    local menuOpen = false
                    local FAKE_ICON = 'rbxthumb://type=Avatar&id=5710225&w=100&h=100'

                    local function fakeName()
                        return Options.StreamerName.Value ~= '' and Options.StreamerName.Value or 'Ragoozer'
                    end

                    ctx.State.streamerName = function()
                        return Toggles.StreamerMode and Toggles.StreamerMode.Value and fakeName() or nil
                    end

                    local scrambleMaid = Maid.new()

                    ctx.Maid:Give(scrambleMaid)

                    local tagOriginals = {}
                    local lastSweep = 0

                    local function scrambleOn()
                        return Toggles.StreamerMode and Toggles.StreamerMode.Value and Toggles.StreamerScramble and Toggles.StreamerScramble.Value or false
                    end

                    ctx.State.scrambleOn = scrambleOn
                    ctx.State.maskUser = function(player)
                        if not player then
                            return ''
                        end
                        if player == LocalPlayer then
                            return (Toggles.StreamerMode and Toggles.StreamerMode.Value) and fakeName() or player.Name
                        end

                        return scrambleOn() and fakeUserFor(player) or player.Name
                    end
                    ctx.State.maskRogue = function(player, real)
                        if not player or player == LocalPlayer or not scrambleOn() then
                            return real
                        end

                        return fakeRogueFor(player)
                    end

                    local function nameTagOf(char)
                        for _, child in char:GetChildren()do
                            if child:IsA('Model') and child:FindFirstChildOfClass('Humanoid') then
                                return child
                            end
                        end

                        return nil
                    end
                    local function applyTag(player)
                        local char = player.Character
                        local tag = char and nameTagOf(char)

                        if not tag then
                            return
                        end
                        if tagOriginals[tag] == nil then
                            tagOriginals[tag] = tag.Name
                        end

                        local want = fakeRogueFor(player)

                        if tag.Name ~= want then
                            tag.Name = want
                        end
                    end
                    local function restoreTags()
                        for tag, original in pairs(tagOriginals)do
                            pcall(function()
                                if tag.Parent then
                                    tag.Name = original
                                end
                            end)
                        end

                        table.clear(tagOriginals)
                    end

                    local hiddenServers = {}

                    local function hideCurrentServer()
                        if LocalPlayer.Character then
                            return
                        end

                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local menu = pg and pg:FindFirstChild('StartMenu')
                        local public = menu and menu:FindFirstChild('PublicServers')
                        local scroll = public and public:FindFirstChild('ScrollingFrame')

                        if not scroll then
                            return
                        end

                        for _, frame in scroll:GetChildren()do
                            local label = frame:IsA('GuiObject') and frame:FindFirstChild('ServerName')

                            if label and label:IsA('TextLabel') and string.find(label.Text, '(Current)', 1, true) and frame.Visible then
                                hiddenServers[frame] = true
                                frame.Visible = false
                            end
                        end
                    end
                    local function restoreServers()
                        for frame in pairs(hiddenServers)do
                            pcall(function()
                                if frame.Parent then
                                    frame.Visible = true
                                end
                            end)
                        end

                        table.clear(hiddenServers)
                    end

                    local codeOverlay, codeConn = nil, nil

                    local function maskPrivateCode()
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local menu = pg and pg:FindFirstChild('StartMenu')
                        local private = menu and menu:FindFirstChild('PrivateServers')
                        local code = private and private:FindFirstChild('Code')

                        if not (code and code:IsA('TextBox')) then
                            return
                        end
                        if codeOverlay and codeOverlay.Parent == code then
                            return
                        end
                        if codeOverlay then
                            codeOverlay:Destroy()
                        end

                        codeOverlay = Make('TextLabel', {
                            Name = 'SentinelCodeMask',
                            Size = UDim2.fromScale(1, 1),
                            BackgroundTransparency = 1,
                            BorderSizePixel = 0,
                            ZIndex = code.ZIndex + 5,
                            Font = code.Font,
                            TextSize = code.TextSize,
                            TextColor3 = code.TextColor3,
                            TextXAlignment = code.TextXAlignment,
                            TextYAlignment = code.TextYAlignment,
                            Text = string.rep('\u{2588}', utf8.len(code.Text) or #code.Text),
                            Parent = code,
                        })
                        codeConn = code:GetPropertyChangedSignal('Text'):Connect(function(
                        )
                            if codeOverlay and codeOverlay.Parent then
                                codeOverlay.Text = string.rep('\u{2588}', utf8.len(code.Text) or #code.Text)
                            end
                        end)
                    end
                    local function restorePrivateCode()
                        if codeConn then
                            pcall(function()
                                codeConn:Disconnect()
                            end)

                            codeConn = nil
                        end
                        if codeOverlay then
                            pcall(function()
                                codeOverlay:Destroy()
                            end)

                            codeOverlay = nil
                        end
                    end
                    local function hideServerStats(on)
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local gui = pg and pg:FindFirstChild('ServerStatsGui')

                        if gui then
                            gui.Enabled = not on
                        end
                    end
                    local function startScramble()
                        scrambleMaid:DoCleaning()
                        hideServerStats(true)
                        hideCurrentServer()
                        maskPrivateCode()
                        scrambleMaid:Give(RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                        )
                            if tick() - lastSweep < 1 or not scrambleOn() then
                                return
                            end

                            lastSweep = tick()

                            for tag in tagOriginals do
                                if not tag.Parent then
                                    tagOriginals[tag] = nil
                                end
                            end
                            for _, p in Players:GetPlayers()do
                                if p ~= LocalPlayer then
                                    pcall(applyTag, p)
                                end
                            end

                            pcall(hideServerStats, true)
                            pcall(hideCurrentServer)
                            pcall(maskPrivateCode)
                        end)))
                    end
                    local function stopScramble()
                        scrambleMaid:DoCleaning()
                        restoreTags()
                        hideServerStats(false)
                        restoreServers()
                        restorePrivateCode()

                        if ctx.State.refreshScramble then
                            pcall(ctx.State.refreshScramble, false)
                        end
                    end

                    ctx.Maid:Give(stopScramble)

                    local pinned = setmetatable({}, {
                        __mode = 'k',
                    })

                    local function pinText(label, getValue)
                        label.Text = getValue()

                        if pinned[label] then
                            return
                        end

                        pinned[label] = true

                        table.insert(streamerConns, label:GetPropertyChangedSignal('Text'):Connect(function(
                        )
                            local want = getValue()

                            if label.Text ~= want then
                                label.Text = want
                            end
                        end))
                    end
                    local function pinImage(icon)
                        icon.Image = FAKE_ICON

                        if pinned[icon] then
                            return
                        end

                        pinned[icon] = true

                        table.insert(streamerConns, icon:GetPropertyChangedSignal('Image'):Connect(function(
                        )
                            if icon.Image ~= FAKE_ICON then
                                icon.Image = FAKE_ICON
                            end
                        end))
                    end
                    local function findDeep(root, ...)
                        local node = root

                        for _, n in ipairs({...})do
                            node = node and node:FindFirstChild(n)
                        end

                        return node
                    end
                    local function isOwnName(text)
                        if type(text) ~= 'string' or text == '' then
                            return false
                        end

                        local stripped = (text:gsub('%W', ''))

                        return stripped == (LocalPlayer.Name:gsub('%W', '')) or stripped == (tostring(LocalPlayer.DisplayName):gsub('%W', ''))
                    end
                    local function applyOldMenu(inner)
                        local players = inner and inner:FindFirstChild('Players')
                        local label = players and (players:FindFirstChild('PlayerLabel' .. LocalPlayer.Name) or players:WaitForChild('PlayerLabel' .. LocalPlayer.Name, 0.5))

                        if not label or not label:FindFirstChild('NameLabel') then
                            return false
                        end

                        pinText(label.NameLabel, function()
                            return '@' .. fakeName()
                        end)
                        pinText(label.DisplayNameLabel, fakeName)
                        pinImage(label.Icon)

                        if scrambleOn() then
                            for _, row in players:GetChildren()do
                                local who = row.Name:match('^PlayerLabel(.+)$')
                                local other = who and Players:FindFirstChild(who)

                                if other and other ~= LocalPlayer and row:FindFirstChild('NameLabel') then
                                    pinText(row.NameLabel, function()
                                        return '@' .. ctx.State.maskUser(other)
                                    end)

                                    if row:FindFirstChild('DisplayNameLabel') then
                                        pinText(row.DisplayNameLabel, function()
                                            return ctx.State.maskUser(other)
                                        end)
                                    end
                                    if row:FindFirstChild('Icon') then
                                        pinImage(row.Icon)
                                    end
                                end
                            end
                        end

                        return true
                    end
                    local function applyNewMenu(inner)
                        local people = inner and findDeep(inner, 'peoplepage', 'FocusRoot', 'PeopleReactView', 'People')

                        if not people then
                            return false
                        end

                        local found = false

                        for _, item in ipairs(people:GetChildren())do
                            local container = findDeep(item, 'Item', 'CardContent', 'CardDetails', 'NameContainer')
                            local handle = container and container:FindFirstChild('Handle')
                            local nameLabel = container and container:FindFirstChild('Name')
                            local thumb = findDeep(item, 'Item', 'CardContent', 'CardThumbnail', 'AvatarThumbnailContainer', 'AvatarThumbnail')

                            if handle and handle:IsA('TextLabel') then
                                local stripped = (handle.Text:gsub('%W', ''))

                                if stripped == (LocalPlayer.Name:gsub('%W', '')) then
                                    pinText(handle, function()
                                        return '@' .. fakeName()
                                    end)

                                    if nameLabel then
                                        pinText(nameLabel, fakeName)
                                    end
                                    if thumb and thumb:IsA('ImageLabel') then
                                        pinImage(thumb)
                                    end

                                    found = true
                                elseif scrambleOn() then
                                    local other

                                    for _, p in Players:GetPlayers()do
                                        if p ~= LocalPlayer and (p.Name:gsub('%W', '')) == stripped then
                                            other = p

                                            break
                                        end
                                    end

                                    if other then
                                        pinText(handle, function()
                                            return '@' .. ctx.State.maskUser(other)
                                        end)

                                        if nameLabel then
                                            pinText(nameLabel, function()
                                                return ctx.State.maskUser(other)
                                            end)
                                        end
                                        if thumb and thumb:IsA('ImageLabel') then
                                            pinImage(thumb)
                                        end

                                        found = true
                                    end
                                end
                            end
                        end

                        return found
                    end
                    local function applyRowMenu(inner)
                        local list = inner and findDeep(inner, 'peoplepage', 'FocusRoot', 'PeopleReactView', 'People', 'PeopleList')

                        if not list then
                            return false
                        end

                        local found = false

                        for _, row in ipairs(list:GetChildren())do
                            local container = findDeep(row, 'RowContent', 'LeftContent', 'NameContainer')
                            local userName = container and container:FindFirstChild('UserName')

                            if userName and userName:IsA('TextLabel') then
                                local stripped = (userName.Text:gsub('%W', ''))
                                local mine = stripped == (LocalPlayer.Name:gsub('%W', ''))
                                local other

                                if not mine and scrambleOn() then
                                    for _, p in Players:GetPlayers()do
                                        if p ~= LocalPlayer and (p.Name:gsub('%W', '')) == stripped then
                                            other = p

                                            break
                                        end
                                    end
                                end
                                if mine or other then
                                    local nameFor = mine and fakeName or function(
                                    )
                                        return ctx.State.maskUser(other)
                                    end
                                    local prefix = userName.Text:sub(1, 1) == '@' and '@' or ''

                                    pinText(userName, function()
                                        return prefix .. nameFor()
                                    end)

                                    local displayName = container:FindFirstChild('DisplayName')

                                    if displayName and displayName:IsA('TextLabel') then
                                        pinText(displayName, nameFor)
                                    end

                                    for _, obj in row:GetDescendants()do
                                        if (obj:IsA('ImageLabel') or obj:IsA('ImageButton')) and tostring(obj.Image):find('rbxthumb', 1, true) then
                                            pinImage(obj)
                                        end
                                    end

                                    found = true
                                end
                            end
                        end

                        return found
                    end
                    local function applyPeopleSweep(inner)
                        local people = inner and findDeep(inner, 'peoplepage', 'FocusRoot', 'PeopleReactView', 'People')

                        if not people then
                            return
                        end

                        for _, obj in people:GetDescendants()do
                            if obj:IsA('TextLabel') and isOwnName(obj.Text) then
                                local prefix = obj.Text:sub(1, 1) == '@' and '@' or ''

                                pinText(obj, function()
                                    return prefix .. fakeName()
                                end)
                            end
                        end
                    end
                    local function applyMenuLabel()
                        if menuBusy then
                            return
                        end

                        menuBusy = true
                        menuOpen = true

                        task.spawn(function()
                            RunService.RenderStepped:Wait()

                            while menuOpen do
                                pcall(function()
                                    local robloxGui = CoreGui:FindFirstChild('RobloxGui')
                                    local shield = robloxGui and robloxGui:FindFirstChild('SettingsClippingShield')
                                    local inner = shield and findDeep(shield, 'SettingsShield', 'MenuContainer', 'Page', 'PageViewClipper', 'PageView', 'PageViewInnerFrame')

                                    if inner then
                                        applyOldMenu(inner)
                                        applyNewMenu(inner)
                                        applyRowMenu(inner)
                                        applyPeopleSweep(inner)
                                    end
                                end)
                                task.wait(0.25)
                            end

                            menuBusy = false
                        end)
                    end
                    local function pinDeathLabel(obj)
                        if not obj:IsA('TextLabel') or deathPins[obj] then
                            return
                        end

                        local function fix()
                            if isOwnName(obj.Text) then
                                obj.Text = fakeName()
                            end
                        end

                        task.defer(fix)

                        deathPins[obj] = obj:GetPropertyChangedSignal('Text'):Connect(fix)

                        obj.Destroying:Once(function()
                            local conn = deathPins[obj]

                            if conn then
                                conn:Disconnect()

                                deathPins[obj] = nil
                            end
                        end)
                    end
                    local function watchStatGui(statGui)
                        if not statGui then
                            return
                        end

                        for _, child in statGui:GetDescendants()do
                            pinDeathLabel(child)
                        end

                        table.insert(streamerConns, statGui.DescendantAdded:Connect(pinDeathLabel))
                    end
                    local function watchDeathName()
                        if deathWatch then
                            return
                        end

                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                        if not pg then
                            return
                        end

                        deathWatch = true

                        watchStatGui(pg:FindFirstChild('StatGui'))
                        table.insert(streamerConns, pg.ChildAdded:Connect(function(
                            child
                        )
                            if child.Name == 'StatGui' then
                                watchStatGui(child)
                            end
                        end))
                    end
                    local function applyStreamer()
                        if not getConnections then
                            return false
                        end

                        local found = false
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local lb = pg and pg:WaitForChild('LeaderboardGui', 30)
                        local main = lb and lb:WaitForChild('MainFrame', 10)
                        local scroll = main and main:WaitForChild('ScrollingFrame', 10)

                        if scroll then
                            local mine = ctx.State.leaderboardLabelFor and ctx.State.leaderboardLabelFor(LocalPlayer)

                            for _, frame in scroll:GetChildren()do
                                local matched = frame == mine

                                if not matched and not mine then
                                    pcall(function()
                                        for _, conn in getConnections(frame.MouseEnter)do
                                            conn:Fire()
                                        end

                                        task.wait()

                                        matched = frame.Text:gsub('%W', '') == LocalPlayer.Name
                                    end)
                                end
                                if matched then
                                    if ragoozerFrame ~= frame then
                                        for _, conn in disabledConns do
                                            pcall(function()
                                                conn:Enable()
                                            end)
                                        end

                                        disabledConns = {}

                                        for _, conn in rowConns do
                                            pcall(function()
                                                conn:Disconnect()
                                            end)
                                        end

                                        table.clear(rowConns)

                                        for _, conn in getConnections(frame.MouseEnter)do
                                            table.insert(disabledConns, conn)
                                            pcall(function()
                                                conn:Disable()
                                            end)
                                        end
                                    end

                                    ragoozerFrame = frame
                                    found = true

                                    local function swapRowName()
                                        local text = frame.Text

                                        if text == '' then
                                            return
                                        end

                                        local fake = fakeName()

                                        for _, real in {
                                            LocalPlayer.Name,
                                            LocalPlayer.DisplayName,
                                        }do
                                            if type(real) == 'string' and real ~= '' and real ~= fake and text:find(real, 1, true) then
                                                frame.Text = (text:gsub(real, fake, 1))

                                                return
                                            end
                                        end
                                    end

                                    rowSwap = swapRowName

                                    if #rowConns == 0 then
                                        table.insert(rowConns, frame:GetPropertyChangedSignal('Text'):Connect(swapRowName))
                                        table.insert(rowConns, frame.MouseEnter:Connect(function(
                                        )
                                            frame.Text = fakeName()
                                            frame.TextTransparency = 0.3
                                        end))
                                    end

                                    task.defer(swapRowName)
                                    pcall(function()
                                        for _, conn in getConnections(frame.MouseLeave)do
                                            conn:Fire()
                                        end
                                    end)

                                    break
                                end
                            end
                        end
                        if not menuConn then
                            menuConn = GuiService.MenuOpened:Connect(applyMenuLabel)

                            table.insert(streamerConns, GuiService.MenuClosed:Connect(function(
                            )
                                menuOpen = false
                            end))
                        end

                        return found
                    end
                    local function streamerReady()
                        local t = 0

                        repeat
                            task.wait(0.05)

                            t += 0.05

                            local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                            local statGui = pg and pg:FindFirstChild('StatGui')
                            local container = statGui and statGui:FindFirstChild('Container')
                            local charName = container and container:FindFirstChild('CharacterName')

                            if charName and charName:FindFirstChild('Shadow') then
                                break
                            end
                        until t > 15

                        t = 0

                        repeat
                            task.wait(0.05)

                            t += 0.05
                        until (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('FakeHumanoid', true)) or t > 6

                        task.wait(0.05)
                    end

                    local streamerBusy = false

                    local function triggerStreamer()
                        if streamerBusy then
                            return
                        end

                        streamerBusy = true

                        task.spawn(function()
                            watchDeathName()

                            local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                            if not (pg and pg:FindFirstChild('LeaderboardGui')) then
                                streamerReady()
                            end

                            for _ = 1, 30 do
                                if not (Toggles.StreamerMode and Toggles.StreamerMode.Value) then
                                    break
                                end
                                if applyStreamer() then
                                    break
                                end

                                task.wait(0.5)
                            end

                            streamerBusy = false
                        end)
                    end
                    local function restoreStreamer()
                        for _, conn in streamerConns do
                            pcall(function()
                                conn:Disconnect()
                            end)
                        end

                        streamerConns = {}

                        for _, conn in rowConns do
                            pcall(function()
                                conn:Disconnect()
                            end)
                        end

                        table.clear(rowConns)

                        for _, conn in deathPins do
                            pcall(function()
                                conn:Disconnect()
                            end)
                        end

                        table.clear(deathPins)

                        deathWatch = false

                        for _, conn in disabledConns do
                            pcall(function()
                                conn:Enable()
                            end)
                        end

                        disabledConns = {}

                        if ragoozerFrame and getConnections then
                            pcall(function()
                                for _, conn in getConnections(ragoozerFrame.MouseEnter)do
                                    conn:Fire()
                                end
                            end)

                            ragoozerFrame = nil
                            rowSwap = nil
                        end
                        if menuConn then
                            menuConn:Disconnect()

                            menuConn = nil
                        end
                        if streamerRespawn then
                            streamerRespawn:Disconnect()

                            streamerRespawn = nil
                        end
                    end

                    ctx.Maid:Give(restoreStreamer)
                    SpoofBox:AddToggle('StreamerMode', {
                        Text = 'Streamer Mode',
                        Tooltip = 'Hides your Roblox username',
                        Default = false,
                        Callback = function(on)
                            if not on then
                                restoreStreamer()

                                return
                            end
                            if not getConnections then
                                Notify.say('Streamer Mode needs getconnections (unsupported executor)')

                                return
                            end

                            triggerStreamer()

                            local live = Workspace:FindFirstChild('Live')

                            if live then
                                streamerRespawn = live.ChildAdded:Connect(function(
                                    child
                                )
                                    if child:IsA('Model') and child.Name == LocalPlayer.Name and Toggles.StreamerMode.Value then
                                        triggerStreamer()
                                    end
                                end)
                            else
                                streamerRespawn = LocalPlayer.CharacterAdded:Connect(function(
                                )
                                    if Toggles.StreamerMode.Value then
                                        triggerStreamer()
                                    end
                                end)
                            end
                        end,
                    })
                    SpoofBox:AddToggle('StreamerScramble', {
                        Text = 'Scramble Server',
                        Tooltip = 'Fake names for everyone else',
                        Default = false,
                        Callback = function(on)
                            if on and not (Toggles.StreamerMode and Toggles.StreamerMode.Value) then
                                Toggles.StreamerScramble:SetValue(false)

                                return
                            end
                            if on then
                                startScramble()

                                if ctx.State.refreshScramble then
                                    pcall(ctx.State.refreshScramble, true)
                                end
                            else
                                stopScramble()
                            end
                        end,
                    })

                    local function gateScramble()
                        local on = Toggles.StreamerMode and Toggles.StreamerMode.Value or false
                        local scramble = Toggles.StreamerScramble

                        if not scramble then
                            return
                        end

                        scramble:SetDisabled(not on)

                        if not on and scramble.Value then
                            scramble:SetValue(false)
                        end
                    end

                    Toggles.StreamerMode:OnChanged(gateScramble)
                    gateScramble()
                    SpoofBox:AddInput('StreamerName', {
                        Text = 'Streamer Name',
                        Placeholder = 'Ragoozer',
                        Finished = true,
                        Callback = function()
                            if Toggles.StreamerMode.Value and rowSwap then
                                pcall(rowSwap)
                            end
                        end,
                    })
                end
                do
                    local WHITE = Color3.fromRGB(255, 253, 247)
                    local respawnMaid = Maid.new()
                    local monitorMaid = Maid.new()

                    ctx.Maid:Give(respawnMaid)
                    ctx.Maid:Give(monitorMaid)

                    local original = {
                        shirtCached = false,
                        pantsCached = false,
                        skinCached = false,
                        faceCached = false,
                    }
                    local active = {
                        face = false,
                        shirt = false,
                        pants = false,
                        accessories = false,
                        skin = false,
                        rlface = false,
                        dye = false,
                        bundle = false,
                        helm = false,
                    }
                    local lastChar
                    local applyHideHelm, restoreHelm
                    local rigs = setmetatable({}, {
                        __mode = 'k',
                    })

                    local function rigFor(char)
                        local rig = char and rigs[char]

                        if not rig then
                            rig = {
                                parts = {},
                                hidden = {},
                                veil = {},
                                stash = {},
                                conns = {},
                                morphs = {},
                                acc = {},
                                helm = {},
                                helmConns = {},
                                id = nil,
                            }

                            if char then
                                rigs[char] = rig
                            end
                        end

                        return rig
                    end

                    local bundleCache = {}
                    local headHandles = {
                        maid = Maid.new(),
                        dragMaid = Maid.new(),
                        clicks = {
                            LeftClick = true,
                            LeftClickRelease = true,
                        },
                        fit = {
                            x = 0,
                            rx = 0,
                            ry = 0,
                            rz = 0,
                        },
                    }

                    ctx.Maid:Give(headHandles.maid)
                    ctx.Maid:Give(headHandles.dragMaid)

                    local loadingAdjust = false
                    local templateCache, templatePending, templateFails = {}, {}, {}
                    local TEMPLATE_RETRY_BASE = 1
                    local TEMPLATE_RETRY_MAX = 15
                    local TEMPLATE_TRIES = 8
                    local TEMPLATE_GAP = 0.2
                    local reapplyClothing

                    local function rlFace(char)
                        if not char then
                            return nil
                        end

                        for _, name in {
                            'Head',
                            'FaceHolder',
                        }do
                            local holder = char:FindFirstChild(name)
                            local face = holder and holder:FindFirstChild('RLFace')

                            if face and face:IsA('Decal') then
                                return face
                            end
                        end

                        return nil
                    end
                    local function clearItem(char, className)
                        local item = char:FindFirstChildOfClass(className)

                        if item then
                            item:Destroy()
                        end
                    end
                    local function extractId(value)
                        return value:match('asset/%?id=(%d+)') or value:match('rbxassetid://(%d+)') or value:match('^(%d+)$') or value
                    end
                    local function maskId(value)
                        local text = tostring(value or '')

                        if text == '' or text == 'nil' then
                            return 'none'
                        end

                        return '***' .. text:sub(-4)
                    end
                    local function garmentLabel(assetId)
                        local id = tostring(assetId)

                        for _, option in {
                            Options.CharShirt,
                            Options.CharPants,
                        }do
                            local mine = option and option.Value

                            if type(mine) == 'string' and mine ~= '' and extractId(mine) == id then
                                return id
                            end
                        end

                        return maskId(id)
                    end
                    local function fetchTemplate(assetId)
                        local url = 'https://assetdelivery.roblox.com/v1/asset/?id=' .. assetId
                        local httpRequest = (http and http.request) or http_request or request
                        local note = 'no request function'

                        if httpRequest then
                            local ok, res = pcall(httpRequest, {
                                Url = url,
                                Method = 'GET',
                            })
                            local body = ok and type(res) == 'table' and (res.Body or res.body)

                            if type(body) == 'string' and (body:sub(1, 4) == '\137PNG' or body:sub(1, 3) == '\255\216\255') then
                                return assetId
                            end

                            local found = type(body) == 'string' and (body:match('rbxassetid://(%d+)') or body:match('id=(%d+)'))

                            if found then
                                return found
                            end
                            if not (ok and type(res) == 'table') then
                                note = 'direct request threw'
                            elseif type(body) ~= 'string' or body == '' then
                                note = 'direct ' .. tostring(res.StatusCode or res.status_code or '?') .. ', empty body'
                            else
                                note = 'direct ' .. tostring(res.StatusCode or res.status_code or '?') .. ', no template in a ' .. tostring(#body) .. ' byte body'
                            end
                        end

                        local loaded, objects = pcall(function()
                            return game:GetObjects('rbxassetid://' .. assetId)
                        end)

                        if loaded and type(objects) == 'table' then
                            for _, root in objects do
                                local scan = root:GetDescendants()

                                table.insert(scan, root)

                                for _, inst in scan do
                                    local content = (inst:IsA('Shirt') and inst.ShirtTemplate) or (inst:IsA('Pants') and inst.PantsTemplate) or (inst:IsA('ShirtGraphic') and inst.Graphic) or nil
                                    local id = content and tostring(content):match('(%d+)')

                                    if id then
                                        return id
                                    end
                                end
                            end

                            note = note .. '; loaded but no clothing in it'
                        else
                            note = note .. '; would not load'
                        end
                        if not ctx.State.robloxGet then
                            return nil, note .. '; no proxy'
                        end

                        local body, status, location = ctx.State.robloxGet(url)

                        if not body and type(location) == 'string' and location ~= '' then
                            body, status = ctx.State.robloxGet(location)
                        end
                        if type(body) == 'string' and (body:sub(1, 4) == '\137PNG' or body:sub(1, 3) == '\255\216\255') then
                            return assetId
                        end

                        local found = body and (body:match('rbxassetid://(%d+)') or body:match('id=(%d+)'))

                        if found then
                            return found
                        end

                        local proxy = type(status) == 'number' and ('http ' .. status) or tostring(status)

                        return nil, note .. '; proxy ' .. proxy .. (body and ', no template in body' or ', no body')
                    end
                    local function getTemplateId(assetId)
                        local cached = templateCache[assetId]

                        if cached then
                            return cached
                        end

                        local fail = templateFails[assetId]
                        local backoff = fail and math.min(TEMPLATE_RETRY_BASE * (2 ^ (fail.count - 1)), TEMPLATE_RETRY_MAX) or 0

                        if not templatePending[assetId] and (not fail or os.clock() - fail.at >= backoff) then
                            templatePending[assetId] = true

                            task.spawn(function()
                                local templateId, why

                                for _ = 1, TEMPLATE_TRIES do
                                    pcall(function()
                                        templateId, why = fetchTemplate(assetId)
                                    end)

                                    if templateId then
                                        break
                                    end

                                    task.wait(TEMPLATE_GAP)
                                end

                                templatePending[assetId] = nil

                                if templateId then
                                    templateCache[assetId] = templateId
                                    templateFails[assetId] = nil

                                    if reapplyClothing then
                                        reapplyClothing()
                                    end
                                else
                                    Debug.log('template', garmentLabel(assetId) .. ': ' .. tostring(why))

                                    templateFails[assetId] = {
                                        at = os.clock(),
                                        count = (fail and fail.count or 0) + 1,
                                    }
                                end
                            end)
                        end

                        return nil
                    end
                    local function getPlayerGender()
                        local ok, result = pcall(function()
                            return ReplicatedStorage.Requests.Get:InvokeServer(utf8.char(65532) .. '\u{1f603}', 'Gender')['Gender']
                        end)

                        return (ok and result) or 'Male'
                    end
                    local function scanDecals(folder, prefix, out)
                        for _, child in folder:GetChildren()do
                            if child:IsA('Decal') then
                                out[prefix .. child.Name] = child.Texture
                            end
                        end
                    end
                    local function getFacePresets()
                        local faces = {}

                        pcall(function()
                            local folder = ReplicatedStorage.Assets.Faces

                            scanDecals(folder, '', faces)

                            local rigan = folder:FindFirstChild('Rigan')

                            if rigan then
                                scanDecals(rigan, 'Rigan', faces)
                            end
                        end)

                        return faces
                    end
                    local function getOutfitPresets()
                        local outfits = {}

                        pcall(function()
                            for _, folder in ReplicatedStorage.Assets.Outfits:GetChildren()do
                                if folder:IsA('Folder') then
                                    outfits[folder.Name] = folder
                                end
                            end
                        end)

                        return outfits
                    end

                    local appliedFace

                    local function applyFace(char, look)
                        pcall(function()
                            local face = rlFace(char)
                            local id = (look and look.face) or (Options.CharFace and Options.CharFace.Value) or ''

                            if face and id ~= '' then
                                local texture = 'rbxassetid://' .. extractId(id)

                                if not look then
                                    if not original.faceCached and face.Texture ~= '' and face.Texture ~= appliedFace and face.Texture ~= texture then
                                        original.face, original.rlfaceColor, original.faceCached = face.Texture, face.Color3, true
                                    end

                                    appliedFace = texture
                                end

                                face.Texture = texture
                            end
                        end)
                    end
                    local function clothingTarget(option)
                        local id = option and option.Value or ''

                        if id == '' then
                            return nil
                        end

                        local extracted = extractId(id)

                        if extracted == '' or #extracted > 50 then
                            return nil
                        end

                        local template = getTemplateId(extracted)

                        if not template then
                            return nil
                        end

                        return 'rbxassetid://' .. template
                    end

                    local applying = {}

                    local function applyClothing(
                        char,
                        kind,
                        className,
                        prop,
                        option,
                        pinMaid
                    )
                        local target = clothingTarget(option)

                        if not char or not target or applying[kind] then
                            return false
                        end

                        applying[kind] = true

                        local landed = pcall(function()
                            local first, duplicate = nil, false

                            for _, child in char:GetChildren()do
                                if child:IsA(className) then
                                    if first then
                                        duplicate = true
                                    else
                                        first = child
                                    end
                                end
                            end

                            local garment = first

                            if not (first and not duplicate and first[prop] == target) then
                                for _, child in char:GetChildren()do
                                    if child:IsA(className) then
                                        child:Destroy()
                                    end
                                end

                                garment = Instance.new(className)
                                garment[prop] = target
                                garment.Parent = char
                            end

                            (pinMaid or monitorMaid)['pin_' .. kind] = garment:GetPropertyChangedSignal(prop):Connect(function(
                            )
                                if garment.Parent and garment[prop] ~= target then
                                    garment[prop] = target
                                end
                            end)
                        end)

                        applying[kind] = false

                        return landed
                    end
                    local function applyShirt(char, look, pinMaid)
                        return applyClothing(char, 'shirt', 'Shirt', 'ShirtTemplate', look and {
                            Value = look.shirt,
                        } or Options.CharShirt, pinMaid)
                    end
                    local function applyPants(char, look, pinMaid)
                        return applyClothing(char, 'pants', 'Pants', 'PantsTemplate', look and {
                            Value = look.pants,
                        } or Options.CharPants, pinMaid)
                    end

                    function reapplyClothing()
                        local char = getChar()

                        if not (char and Toggles.CharCustomMaster and Toggles.CharCustomMaster.Value) then
                            return
                        end
                        if active.shirt then
                            applyShirt(char)
                        end
                        if active.pants then
                            applyPants(char)
                        end
                    end

                    local function applySkin(char, look)
                        local color = (look and look.skin and Color3.fromHex(look.skin)) or Options.SkinColor.Value

                        pcall(function()
                            local body = char:FindFirstChildOfClass('BodyColors')

                            if not body then
                                body = Make('BodyColors', {Parent = char})
                            end

                            body.HeadColor3, body.TorsoColor3 = color, color
                            body.LeftArmColor3, body.RightArmColor3 = color, color
                            body.LeftLegColor3, body.RightLegColor3 = color, color
                        end)
                    end
                    local function applyDye(char, look)
                        pcall(function()
                            local color = (look and look.dye and Color3.fromHex(look.dye)) or Options.ClothingDye.Value
                            local shirt = char:FindFirstChildOfClass('Shirt')

                            if shirt then
                                shirt.Color3 = color
                            end

                            local pants = char:FindFirstChildOfClass('Pants')

                            if pants then
                                pants.Color3 = color
                            end
                        end)
                    end
                    local function applyRLFaceColor(char)
                        pcall(function()
                            local face = rlFace(char)

                            if face then
                                if Options.RLFaceColor then
                                    face.Color3 = Options.RLFaceColor.Value
                                end
                            end
                        end)
                    end
                    local function ghostAccessory(acc)
                        for _, d in acc:GetDescendants()do
                            if d:IsA('BasePart') then
                                d.Anchored, d.CanCollide, d.CanQuery, d.CanTouch, d.Massless = false, false, false, false, true
                            end
                        end
                    end
                    local function applyAccessories(char, look)
                        local worn = rigFor(char).acc

                        for _, acc in worn do
                            if acc and acc.Parent then
                                acc:Destroy()
                            end
                        end

                        table.clear(worn)

                        local head = char:FindFirstChild('Head')

                        if not head then
                            return
                        end

                        local wanted = (look and look.acc and table.concat(look.acc, ',')) or Options.CharAccessories.Value

                        for token in wanted:gmatch('[^,]+')do
                            local id = extractId(token:match('^%s*(.-)%s*$'))

                            pcall(function()
                                local acc = game:GetObjects('rbxassetid://' .. id)[1]

                                if not acc then
                                    return
                                end

                                acc.Name = 'Asset:' .. id

                                ghostAccessory(acc)

                                acc.Parent = char

                                local handle = acc:WaitForChild('Handle', 5)

                                if not handle then
                                    return
                                end

                                for _, obj in handle:GetChildren()do
                                    if obj:IsA('Weld') or obj:IsA('WeldConstraint') or obj:IsA('Motor6D') then
                                        obj:Destroy()
                                    end
                                end

                                local accAtt = handle:FindFirstChildWhichIsA('Attachment')
                                local headAtt = accAtt and head:FindFirstChild(accAtt.Name)

                                if not headAtt then
                                    return
                                end

                                local weld = Instance.new('Weld')

                                weld.Part0, weld.Part1 = handle, head
                                weld.C0, weld.C1 = accAtt.CFrame, headAtt.CFrame
                                weld.Parent = handle

                                table.insert(worn, acc)
                            end)
                        end
                    end
                    local function applyOutfit(char, folder)
                        local gender = getPlayerGender()
                        local genderFolder = folder:FindFirstChild(gender) or folder:FindFirstChild('Male') or folder:FindFirstChild('Female')

                        if not genderFolder then
                            return
                        end

                        pcall(function()
                            local shirt = genderFolder:FindFirstChild('Shirt')

                            if shirt and shirt:IsA('Shirt') then
                                Options.CharShirt:SetValue(shirt.ShirtTemplate)
                                clearItem(char, 'Shirt')

                                shirt:Clone().Parent = char
                                active.shirt = true
                            end

                            local pants = genderFolder:FindFirstChild('Pants')

                            if pants and pants:IsA('Pants') then
                                Options.CharPants:SetValue(pants.PantsTemplate)
                                clearItem(char, 'Pants')

                                pants:Clone().Parent = char
                                active.pants = true
                            end
                        end)
                    end

                    local R15_TO_R6 = {
                        Head = 'Head',
                        UpperTorso = 'Torso',
                        LowerTorso = 'Torso',
                        LeftUpperArm = 'Left Arm',
                        LeftLowerArm = 'Left Arm',
                        LeftHand = 'Left Arm',
                        RightUpperArm = 'Right Arm',
                        RightLowerArm = 'Right Arm',
                        RightHand = 'Right Arm',
                        LeftUpperLeg = 'Left Leg',
                        LeftLowerLeg = 'Left Leg',
                        LeftFoot = 'Left Leg',
                        RightUpperLeg = 'Right Leg',
                        RightLowerLeg = 'Right Leg',
                        RightFoot = 'Right Leg',
                    }
                    local MODEL_LIMBS = {
                        r6 = {
                            Head = true,
                            Torso = true,
                            ['Left Arm'] = true,
                            ['Right Arm'] = true,
                            ['Left Leg'] = true,
                            ['Right Leg'] = true,
                        },
                        characterMesh = {
                            Torso = 'Torso',
                            LeftArm = 'Left Arm',
                            RightArm = 'Right Arm',
                            LeftLeg = 'Left Leg',
                            RightLeg = 'Right Leg',
                        },
                        effects = {
                            'ParticleEmitter',
                            'Fire',
                            'Smoke',
                            'Sparkles',
                            'Trail',
                            'Beam',
                            'Light',
                            'Decal',
                            'BillboardGui',
                            'SurfaceGui',
                        },
                        anchors = {
                            h = 'Head',
                            head = 'Head',
                            t = 'Torso',
                            torso = 'Torso',
                            chest = 'Torso',
                            la = 'Left Arm',
                            leftarm = 'Left Arm',
                            arm1 = 'Left Arm',
                            ra = 'Right Arm',
                            rightarm = 'Right Arm',
                            arm2 = 'Right Arm',
                            ll = 'Left Leg',
                            leftleg = 'Left Leg',
                            leg1 = 'Left Leg',
                            rl = 'Right Leg',
                            rightleg = 'Right Leg',
                            leg2 = 'Right Leg',
                        },
                    }

                    local function isModelFile(id)
                        return tostring(id):lower():match('%.rbxmx?%s*$') ~= nil
                    end
                    local function clearBundle(char)
                        local c = char or getChar()
                        local rig = rigFor(c)

                        for _, conn in rig.conns do
                            pcall(function()
                                conn:Disconnect()
                            end)
                        end

                        table.clear(rig.conns)

                        if rig.morphWatch then
                            rig.morphWatch:Disconnect()

                            rig.morphWatch = nil
                        end

                        rig.hideSet, rig.hideScope = nil, nil

                        for _, inst in rig.parts do
                            if inst and inst.Parent then
                                pcall(function()
                                    inst:Destroy()
                                end)
                            end
                        end

                        table.clear(rig.parts)
                        table.clear(rig.morphs)

                        if c then
                            for name, transparency in rig.hidden do
                                local limb = c:FindFirstChild(name)

                                if limb then
                                    pcall(function()
                                        limb.Transparency = transparency
                                    end)
                                end
                            end
                        end

                        table.clear(rig.hidden)

                        for inst, transparency in rig.veil do
                            if inst and inst.Parent then
                                pcall(function()
                                    inst.Transparency = transparency
                                end)
                            end
                        end

                        table.clear(rig.veil)

                        for inst, parent in rig.stash do
                            if inst then
                                pcall(function()
                                    inst.Parent = parent
                                end)
                            end
                        end

                        table.clear(rig.stash)

                        if c ~= getChar() or not active.helm then
                            restoreHelm(c)
                        end

                        rig.id = nil

                        if c then
                            pcall(c.SetAttribute, c, 'SentinelBundle', nil)
                        end
                        if c == getChar() and headHandles.show then
                            headHandles.show()
                        end
                    end
                    local function hideOriginal(char, scope)
                        local rig = rigFor(char)

                        for _, holderName in {
                            'Head',
                            'FaceHolder',
                        }do
                            local holder = char:FindFirstChild(holderName)

                            if holder then
                                for _, name in {
                                    'RLFace',
                                    'FacialMarking',
                                    'EdictMark',
                                }do
                                    local decal = holder:FindFirstChild(name)

                                    if decal and rig.veil[decal] == nil then
                                        rig.veil[decal] = decal.Transparency

                                        pcall(function()
                                            decal.Transparency = 1
                                        end)
                                    end
                                end
                            end
                        end

                        if scope ~= 'head' then
                            for _, child in char:GetChildren()do
                                if child.Name:match('^Asset:%d') and rig.stash[child] == nil then
                                    rig.stash[child] = child.Parent

                                    pcall(function()
                                        child.Parent = nil
                                    end)
                                end
                            end
                            for _, inst in char:GetDescendants()do
                                if (inst:IsA('MeshPart') or (inst:IsA('UnionOperation') and inst.Name == 'ScroomHead')) and rig.veil[inst] == nil and rig.hidden[inst.Name] == nil then
                                    local fromBundle = false
                                    local node = inst

                                    while node and node ~= char do
                                        if node:GetAttribute('SentinelBundle') then
                                            fromBundle = true

                                            break
                                        end

                                        node = node.Parent
                                    end

                                    if not fromBundle then
                                        rig.veil[inst] = inst.Transparency

                                        pcall(function()
                                            inst.Transparency = 1
                                        end)
                                    end
                                end
                            end
                        end

                        local function reVeil()
                            for inst in rig.veil do
                                if inst and inst.Parent then
                                    pcall(function()
                                        inst.Transparency = 1
                                    end)
                                end
                            end
                            for name in rig.hidden do
                                local limb = char:FindFirstChild(name)

                                if limb then
                                    pcall(function()
                                        limb.Transparency = 1
                                    end)
                                end
                            end
                        end
                        local function watchPart(inst)
                            table.insert(rig.conns, inst:GetPropertyChangedSignal('Transparency'):Connect(function(
                            )
                                if rig.id and inst.Transparency ~= 1 then
                                    reVeil()
                                end
                            end))
                        end

                        for _, conn in rig.conns do
                            pcall(function()
                                conn:Disconnect()
                            end)
                        end

                        table.clear(rig.conns)

                        for inst in rig.veil do
                            if typeof(inst) == 'Instance' and inst:IsA('BasePart') then
                                watchPart(inst)
                            end
                        end
                        for name in rig.hidden do
                            local limb = char:FindFirstChild(name)

                            if limb and limb:IsA('BasePart') then
                                watchPart(limb)
                            end
                        end
                    end
                    local function weldAccessory(char, acc)
                        local handle = acc:FindFirstChild('Handle')
                        local accAtt = handle and handle:FindFirstChildWhichIsA('Attachment')

                        if not accAtt then
                            return false
                        end

                        for _, limb in char:GetChildren()do
                            if limb:IsA('BasePart') then
                                local limbAtt = limb:FindFirstChild(accAtt.Name)

                                if limbAtt then
                                    for _, j in handle:GetChildren()do
                                        if j:IsA('Weld') or j:IsA('WeldConstraint') or j:IsA('Motor6D') then
                                            j:Destroy()
                                        end
                                    end

                                    local weld = Instance.new('Weld')

                                    weld.Part0, weld.Part1 = handle, limb
                                    weld.C0, weld.C1 = accAtt.CFrame, limbAtt.CFrame
                                    weld.Parent = handle

                                    ghostAccessory(acc)

                                    acc.Parent = char

                                    acc:SetAttribute('SentinelBundle', true)

                                    return true
                                end
                            end
                        end

                        return false
                    end
                    local function scaleCFrame(cf, s)
                        return CFrame.new(cf.Position * s) * (cf - cf.Position)
                    end
                    local function lookValue(look, key, flag, default)
                        if look then
                            local value = look[key]

                            if value == nil then
                                return default
                            end

                            return value
                        end

                        local option = Options[flag]

                        if option == nil or option.Value == nil then
                            return default
                        end

                        return option.Value
                    end
                    local function headFit(look)
                        local turn = headHandles.fit
                        local x, rx, ry, rz = turn.x, turn.rx, turn.ry, turn.rz

                        if look then
                            x, rx, ry, rz = look.headx or 0, look.headrx or 0, look.headry or 0, look.headrz or 0
                        end

                        return CFrame.new(x, lookValue(look, 'heady', 'BundleHeadY', 0),
-lookValue(look, 'headz', 'BundleHeadZ', 0)) * CFrame.Angles(math.rad(rx), math.rad(ry), math.rad(rz))
                    end
                    local function repositionBundle(rig, look)
                        rig = rig or rigFor(getChar())

                        local offset = lookValue(look, 'offset', 'BundleOffset', 0)
                        local scale = lookValue(look, 'scale', 'BundleScale', 1)
                        local fit = headFit(look)

                        for _, entry in rig.morphs do
                            if entry.weld and entry.weld.Parent and entry.limbRest and entry.localOffset then
                                if entry.isHead and entry.headBase then
                                    entry.localOffset = entry.headBase * fit
                                end

                                entry.weld.C0 = entry.limbRest:ToObjectSpace(CFrame.new(0, offset, 0) * scaleCFrame(entry.localOffset, scale))
                            elseif entry.headOnly and entry.weld and entry.weld.Parent then
                                entry.weld.C0 = CFrame.new(0, offset, 0) * fit
                            end
                        end
                    end
                    local function scaleEffects(entry, s)
                        if not entry.effects then
                            entry.effects = {}

                            for _, d in entry.mesh:GetDescendants()do
                                if d:IsA('Attachment') then
                                    entry.effects[d] = d.Position
                                elseif d:IsA('ParticleEmitter') then
                                    entry.effects[d] = d.Size
                                end
                            end
                        end

                        for inst, base in entry.effects do
                            if inst:IsA('Attachment') then
                                inst.Position = base * s
                            else
                                local points = {}

                                for _, point in base.Keypoints do
                                    table.insert(points, NumberSequenceKeypoint.new(point.Time, point.Value * s, point.Envelope * s))
                                end

                                inst.Size = NumberSequence.new(points)
                            end
                        end
                    end
                    local function resizeBundle(rig, look)
                        rig = rig or rigFor(getChar())

                        local scale = lookValue(look, 'scale', 'BundleScale', 1)
                        local headScale = lookValue(look, 'head', 'BundleHeadSize', 1)

                        for _, entry in rig.morphs do
                            local s = entry.isHead and (scale * headScale) or scale

                            if entry.headMesh and entry.baseScale then
                                entry.headMesh.Scale = entry.baseScale * s
                            elseif entry.baseSize and entry.mesh then
                                entry.mesh.Size = entry.baseSize * s
                            end

                            for _, rider in entry.riders or {}do
                                if rider.part.Parent then
                                    if rider.mesh then
                                        rider.mesh.Scale = rider.scale * s
                                    else
                                        rider.part.Size = rider.size * s
                                    end

                                    rider.weld.C0 = scaleCFrame(rider.c0, s)
                                end
                            end

                            if entry.mesh and entry.mesh.Parent then
                                scaleEffects(entry, s)
                            end
                        end
                    end

                    local CACHE_DIR = Paths.CUSTOMIZATION
                    local BUNDLE_BATCH = 50

                    local function bdbg(fmt, ...)
                        if not (Toggles.CharDebug and Toggles.CharDebug.Value) then
                            return
                        end

                        local ok, line = pcall(string.format, fmt, ...)

                        print('[sentinel/bundle] ' .. (ok and line or tostring(fmt)))
                    end

                    local bundleNames = {}

                    local function readBundleFile(id)
                        return Json.read(CACHE_DIR .. '/' .. id .. '.json')
                    end
                    local function writeBundleFile(id, data)
                        Json.write(CACHE_DIR .. '/' .. id .. '.json', data)
                    end
                    local function readBundleMeta(id)
                        local data = readBundleFile(id)

                        return (data and type(data.items) == 'table') and data or nil
                    end
                    local function writeBundleMeta(
                        id,
                        items,
                        headMeshId,
                        headTexId,
                        name
                    )
                        local data = readBundleFile(id) or {}

                        data.items, data.headMeshId, data.headTexId = items, headMeshId, headTexId
                        data.name = name or data.name

                        writeBundleFile(id, data)
                    end
                    local function writeBundleName(id, name)
                        local data = readBundleFile(id)

                        if data and name then
                            data.name = name

                            writeBundleFile(id, data)
                        end
                    end

                    local EXTRAS_FILE = Paths.EXTRAS
                    local extraNames = Json.read(EXTRAS_FILE) or {}

                    local function rememberExtra(id, name)
                        id = tostring(id)

                        if not name or name == '' or extraNames[id] == name then
                            return
                        end

                        extraNames[id] = name

                        Json.write(EXTRAS_FILE, extraNames)
                    end
                    local function bundleNameOf(id, data)
                        if data and data.name then
                            return data.name
                        end

                        local counts, best, bestCount = {}, nil, 0

                        for _, item in (data and data.items) or {}do
                            local prefix = tostring(item.name):match('^(.-)%s+%-%s+.+$')

                            if prefix and prefix ~= '' then
                                counts[prefix] = (counts[prefix] or 0) + 1

                                if counts[prefix] > bestCount then
                                    best, bestCount = prefix, counts[prefix]
                                end
                            end
                        end

                        return best or ('Bundle ' .. id)
                    end
                    local function listBundles()
                        local out = {}

                        if not (listfiles and isfolder and isfolder(CACHE_DIR)) then
                            return out
                        end

                        local ok, files = pcall(listfiles, CACHE_DIR)

                        if not ok then
                            return out
                        end

                        for _, path in files do
                            local id = tostring(path):match('([%d]+)%.json$')

                            if id then
                                table.insert(out, {
                                    id = id,
                                    name = bundleNameOf(id, readBundleFile(id)),
                                })
                            end
                        end

                        table.sort(out, function(a, b)
                            return a.name:lower() < b.name:lower()
                        end)

                        return out
                    end
                    local function extraEntries(look)
                        local out = {}
                        local list = lookValue(look, 'extras', 'BundleExtras', '')

                        for piece in string.gmatch(list, '[^,]+')do
                            local trimmed = string.match(piece, '^%s*(.-)%s*$')

                            if trimmed ~= '' then
                                table.insert(out, trimmed)
                            end
                        end

                        return out
                    end
                    local function saveBundleAdjust(id, adjust)
                        local data = readBundleFile(id) or {}

                        data.adjust = adjust

                        writeBundleFile(id, data)
                    end
                    local function modelShows(part)
                        if part.Transparency < 1 then
                            return true
                        end

                        for _, d in part:GetDescendants()do
                            for _, class in MODEL_LIMBS.effects do
                                if d:IsA(class) then
                                    return true
                                end
                            end
                        end

                        return false
                    end
                    local function anchorLimb(name)
                        return MODEL_LIMBS.anchors[(tostring(name):lower():gsub('[%s_]', ''))]
                    end
                    local function gatherModel(file, mode)
                        file = file:match('^%s*(.-)%s*$')

                        local cacheKey = mode .. ':' .. file
                        local cached = bundleCache[cacheKey]

                        if cached then
                            local meshes, accessories = {}, {}

                            for key, template in cached.meshes do
                                meshes[key] = template:Clone()
                            end
                            for _, template in cached.accessories do
                                table.insert(accessories, template:Clone())
                            end

                            return meshes, accessories, true, cached.root, cached.hide
                        end

                        local path = Paths.CHARACTERS .. '/' .. file

                        if not (isfile and isfile(path)) then
                            Notify.say('Put ' .. file .. ' in ' .. Paths.CHARACTERS, 8)

                            return nil
                        end
                        if not getcustomasset then
                            Notify.say(
[[Your executor has no getcustomasset, so .rbxm models cannot load]], 8)

                            return nil
                        end

                        local ok, objects = pcall(function()
                            return game:GetObjects(getcustomasset(path))
                        end)
                        local model = ok and objects and objects[1]

                        if not model then
                            Notify.say(file .. ' would not load', 8)

                            return nil
                        end

                        local scan = model:GetDescendants()

                        table.insert(scan, model)

                        local parts, accessories, joints = {}, {}, {}
                        local rootPart

                        for _, d in scan do
                            if d:IsA('Accessory') then
                                table.insert(accessories, d)
                            elseif not d:FindFirstAncestorWhichIsA('Accessory') then
                                if d:IsA('BasePart') then
                                    table.insert(parts, d)

                                    if d.Name == 'HumanoidRootPart' then
                                        rootPart = rootPart or d
                                    end
                                elseif d:IsA('JointInstance') or d:IsA('WeldConstraint') then
                                    table.insert(joints, d)
                                end
                            end
                        end

                        local function depthOf(inst)
                            local depth, node = 0, inst

                            while node and node ~= model do
                                depth += 1

                                node = node.Parent
                            end

                            return depth
                        end

                        local anchors, anchorDepth, rigParts = {}, {}, {}

                        for _, part in parts do
                            if part ~= rootPart then
                                local limb = anchorLimb(part.Name) or (part.Name == 'Middle' and part.Parent and anchorLimb(part.Parent.Name)) or nil

                                if limb then
                                    local depth = depthOf(part)

                                    if not anchors[limb] or depth < anchorDepth[limb] then
                                        anchors[limb], anchorDepth[limb] = part, depth
                                    end
                                elseif R15_TO_R6[part.Name] and not rigParts[part.Name] then
                                    rigParts[part.Name] = part
                                end
                            end
                        end

                        if mode == 'head' then
                            local head = anchors.Head

                            if not head then
                                for _, part in parts do
                                    if part ~= rootPart and modelShows(part) then
                                        local headLike = part.Name:lower():find('head', 1, true) ~= nil

                                        if headLike or not head or part.Size.Magnitude > head.Size.Magnitude then
                                            head = part

                                            if headLike then
                                                break
                                            end
                                        end
                                    end
                                end
                            end

                            anchors, rigParts = {Head = head}, {}
                        end

                        local rigid = {}

                        for limb, part in anchors do
                            if rootPart and mode == 'body' and MODEL_LIMBS.r6[part.Name] then
                                rigParts[limb], anchors[limb] = part, nil
                            else
                                rigid[part] = true
                            end
                        end

                        local owners, ownerOf = {}, {}

                        for key, part in anchors do
                            owners[part] = key
                        end
                        for key, part in rigParts do
                            owners[part] = key
                        end

                        local function hierarchyOwner(part)
                            local node = part.Parent

                            while node and node ~= model.Parent do
                                if owners[node] then
                                    return node
                                end

                                local middle = node:FindFirstChild('Middle')

                                if middle and owners[middle] then
                                    return middle
                                end

                                node = node.Parent
                            end

                            return nil
                        end

                        local links = {}

                        for _, joint in joints do
                            local a, b = joint.Part0, joint.Part1

                            if a and b then
                                links[a] = links[a] or {}
                                links[b] = links[b] or {}

                                table.insert(links[a], b)
                                table.insert(links[b], a)
                            end
                        end

                        if mode == 'head' then
                            for _, part in parts do
                                if not owners[part] then
                                    ownerOf[part] = anchors.Head
                                end
                            end
                        else
                            for _, part in parts do
                                if not owners[part] then
                                    ownerOf[part] = hierarchyOwner(part)
                                end
                            end

                            local queue = {}

                            for owner in owners do
                                table.insert(queue, owner)
                            end

                            local reached = {}
                            local cursor = 1

                            while cursor <= #queue do
                                local node = queue[cursor]

                                cursor += 1

                                local owner = owners[node] and node or ownerOf[node]

                                for _, linked in links[node] or {}do
                                    if not owners[linked] and not reached[linked] and not ownerOf[linked] then
                                        reached[linked] = true
                                        ownerOf[linked] = owner

                                        table.insert(queue, linked)
                                    end
                                end
                            end

                            for _, part in parts do
                                if not owners[part] and not ownerOf[part] and part ~= rootPart then
                                    local best, bestDistance

                                    for owner in owners do
                                        local distance = (owner.Position - part.Position).Magnitude

                                        if not best or distance < bestDistance then
                                            best, bestDistance = owner, distance
                                        end
                                    end

                                    ownerOf[part] = best
                                end
                            end
                        end

                        local placed = {}

                        for _, joint in joints do
                            local a, b = joint.Part0, joint.Part1

                            if a and b and joint:IsA('JointInstance') then
                                if ownerOf[b] == a then
                                    placed[b] = a.CFrame * joint.C0 * joint.C1:Inverse()
                                elseif ownerOf[a] == b then
                                    placed[a] = b.CFrame * joint.C1 * joint.C0:Inverse()
                                end
                            end
                        end
                        for _, joint in joints do
                            joint:Destroy()
                        end
                        for _, d in scan do
                            local limbPart = d:IsA('CharacterMesh') and (anchors[MODEL_LIMBS.characterMesh[d.BodyPart.Name] or ''] or rigParts[MODEL_LIMBS.characterMesh[d.BodyPart.Name] or ''])

                            if limbPart and d.MeshId > 0 and not limbPart:IsA('MeshPart') and not limbPart:FindFirstChildWhichIsA('DataModelMesh') then
                                local mesh = Make('SpecialMesh', {
                                    MeshType = Enum.MeshType.FileMesh,
                                    MeshId = 'rbxassetid://' .. d.MeshId,
                                })

                                if d.BaseTextureId > 0 then
                                    mesh.TextureId = 'rbxassetid://' .. d.BaseTextureId
                                end

                                mesh.Parent = limbPart
                            end
                        end

                        local riding = {}

                        for part, owner in ownerOf do
                            if owner and modelShows(part) and not owner:IsDescendantOf(part) then
                                part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.Massless = false, false, false, false, true
                                part.CFrame = placed[part] or part.CFrame

                                if anchorLimb(part.Name) or R15_TO_R6[part.Name] or part.Name == 'HumanoidRootPart' then
                                    part.Name = 'Morph' .. part.Name
                                end

                                part.Parent = owner

                                local weld = Make('Weld', {
                                    Name = 'RiderWeld',
                                    Part0 = owner,
                                    Part1 = part,
                                    C0 = owner.CFrame:ToObjectSpace(part.CFrame),
                                    Parent = part,
                                })

                                riding[owner] = true
                            end
                        end

                        local meshes = {}

                        for key, part in anchors do
                            if modelShows(part) or riding[part] then
                                if rigid[part] then
                                    part:SetAttribute('SentinelRigid', true)
                                end

                                meshes[key] = part
                            end
                        end
                        for key, part in rigParts do
                            if modelShows(part) or riding[part] then
                                meshes[key] = part
                            end
                        end

                        if next(meshes) == nil and #accessories == 0 then
                            Notify.say(file .. ' has nothing in it to wear', 8)

                            return nil
                        end

                        local ghosts = {}

                        for _, part in meshes do
                            if part.Transparency >= 1 and not riding[part] then
                                table.insert(ghosts, part.Name)
                            end
                        end

                        if #ghosts > 0 then
                            Library:Notify({
                                Title = 'sentinel.bz',
                                Description = string.format(
[[%s: %s is saved invisible (Transparency 1), so only its effects show. Set it to 0 in Studio to see the mesh]], file, table.concat(ghosts, ', ')),
                                Time = 10,
                            })
                        end

                        local hide

                        if mode == 'head' then
                            hide = {Head = true}
                        else
                            hide = {}

                            local flag = model:FindFirstChild('HideBody', true)
                            local text = (flag and flag:IsA('ValueBase')) and tostring(flag.Value):lower() or 'all'

                            if text == 'all' or text == 'true' or text == '1' then
                                for name in MODEL_LIMBS.r6 do
                                    hide[name] = true
                                end
                            else
                                for token in text:gmatch('[^,;]+')do
                                    local limb = anchorLimb(token)

                                    if limb then
                                        hide[limb] = true
                                    end
                                end
                            end
                        end

                        local root = rootPart and rootPart.CFrame

                        if not root then
                            local lower = rigParts.LowerTorso or rigParts.UpperTorso
                            local att = lower and lower:FindFirstChild('RootRigAttachment', true)

                            root = (att and lower.CFrame * att.CFrame) or (lower and lower.CFrame) or (rigParts.Torso and rigParts.Torso.CFrame) or nil
                        end

                        local store = {
                            meshes = {},
                            accessories = {},
                            root = root,
                            hide = hide,
                        }

                        for key, m in meshes do
                            store.meshes[key] = m:Clone()
                        end
                        for _, a in accessories do
                            table.insert(store.accessories, a:Clone())
                        end

                        bundleCache[cacheKey] = store

                        return meshes, accessories, true, root, hide
                    end
                    local function gatherBundle(id)
                        local cached = bundleCache[id]

                        if cached then
                            local meshes = {}

                            for key, template in cached.meshes do
                                meshes[key] = template:Clone()
                            end

                            local accessories = {}

                            for _, template in cached.accessories do
                                table.insert(accessories, template:Clone())
                            end

                            return meshes, accessories, cached.headSameSpace
                        end

                        local meta = readBundleMeta(id)
                        local items, storedHeadMeshId, storedHeadTexId

                        if meta then
                            items, storedHeadMeshId, storedHeadTexId = meta.items, meta.headMeshId, meta.headTexId
                        else
                            local body = ctx.State.robloxGet and ctx.State.robloxGet('https://catalog.roblox.com/v1/bundles/' .. id .. '/details')

                            if not body then
                                return nil
                            end

                            local data = select(2, pcall(function()
                                return HttpService:JSONDecode(body)
                            end))

                            if type(data) ~= 'table' or type(data.items) ~= 'table' then
                                return nil
                            end

                            items = {}

                            for _, item in data.items do
                                if item.type == 'Asset' then
                                    table.insert(items, {
                                        id = tostring(item.id),
                                        name = item.name,
                                    })
                                end
                            end

                            bundleNames[id] = data.name
                        end

                        local meshes, meshPriority, meshRootOf = {}, {}, {}
                        local accessories = {}
                        local headItemId

                        for _, item in items do
                            if not headItemId and tostring(item.name):lower():find('head') then
                                headItemId = item.id
                            end

                            local ok, objs = pcall(function()
                                return game:GetObjects('rbxassetid://' .. tostring(item.id))
                            end)

                            if not (ok and objs and #objs > 0) then
                                local ok2, model = pcall(function()
                                    return game:GetService('InsertService'):LoadAsset(tonumber(item.id))
                                end)

                                if ok2 and model then
                                    ok, objs = true, {model}
                                end
                            end

                            for _, root in (ok and objs or {})do
                                if root:IsA('Accessory') or root:FindFirstChild('Handle') then
                                    table.insert(accessories, root)
                                else
                                    local scan = root:GetDescendants()

                                    table.insert(scan, root)

                                    for _, m in scan do
                                        if m:IsA('MeshPart') then
                                            local key = R15_TO_R6[m.Name] and m.Name or ((m:FindFirstChildOfClass('FaceControls') or m:FindFirstChild('FaceFrontAttachment') or m:FindFirstChild('FaceCenterAttachment')) and 'Head') or nil

                                            if key then
                                                local prio = (m:FindFirstAncestor('R15ArtistIntent') ~= nil and 2 or 1) + (key == m.Name and 0.5 or 0)

                                                if (meshPriority[key] or 0) < prio then
                                                    meshes[key] = m
                                                    meshPriority[key] = prio
                                                    meshRootOf[key] = root
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end

                        local resolvedHeadMeshId, resolvedHeadTexId

                        if not meshes.Head and headItemId then
                            local meshId, texId = storedHeadMeshId, storedHeadTexId

                            if not meshId then
                                pcall(function()
                                    if not ctx.State.robloxGet then
                                        return
                                    end

                                    local rbxm, _, location = ctx.State.robloxGet('https://assetdelivery.roblox.com/v1/asset/?id=' .. tostring(headItemId))

                                    if not rbxm and type(location) == 'string' and location ~= '' then
                                        rbxm = ctx.State.robloxGet(location)
                                    end

                                    meshId = rbxm and rbxm:match('MeshId.-rbxassetid://(%d+)')
                                    texId = rbxm and rbxm:match('TextureId.-rbxassetid://(%d+)')
                                end)
                            end
                            if meshId then
                                local part = Make('Part', {
                                    Name = 'BundleHead',
                                    Size = Vector3.new(1, 1, 1),
                                })
                                local sm = Make('SpecialMesh', {
                                    MeshType = Enum.MeshType.FileMesh,
                                    MeshId = 'rbxassetid://' .. meshId,
                                })

                                if texId then
                                    sm.TextureId = 'rbxassetid://' .. texId
                                end

                                sm.Parent = part
                                meshes.Head = part
                                resolvedHeadMeshId, resolvedHeadTexId = meshId, texId
                            end
                        end
                        if not meta then
                            writeBundleMeta(id, items, resolvedHeadMeshId, resolvedHeadTexId, bundleNames[id])
                        end

                        local headSameSpace = (meshRootOf.Head ~= nil and (meshRootOf.Head == meshRootOf.UpperTorso or meshRootOf.Head == meshRootOf.LowerTorso)) or false

                        if next(meshes) ~= nil or #accessories > 0 then
                            local store = {
                                meshes = {},
                                accessories = {},
                                headSameSpace = headSameSpace,
                            }

                            for key, m in meshes do
                                store.meshes[key] = m:Clone()
                            end
                            for _, a in accessories do
                                table.insert(store.accessories, a:Clone())
                            end

                            bundleCache[id] = store
                        end

                        return meshes, accessories, headSameSpace
                    end
                    local function gatherExtra(entry)
                        local out = {}
                        local bundleId = entry:match('/bundles/(%d+)') or entry:match('^bundle:(%d+)$')

                        if bundleId then
                            local _, accessories = gatherBundle(bundleId)

                            for _, acc in accessories or {}do
                                table.insert(out, acc)
                            end

                            return out
                        end

                        local assetId = entry:match('/catalog/(%d+)') or extractId(entry)

                        if not tonumber(assetId) then
                            return out
                        end

                        local ok, objs = pcall(function()
                            return game:GetObjects('rbxassetid://' .. tostring(assetId))
                        end)

                        if not (ok and objs) then
                            local ok2, model = pcall(function()
                                return game:GetService('InsertService'):LoadAsset(tonumber(assetId))
                            end)

                            objs = ok2 and model and {model} or {}
                        end

                        for _, root in objs do
                            if root:IsA('Accessory') or root:FindFirstChild('Handle') then
                                table.insert(out, root)
                            else
                                for _, child in root:GetDescendants()do
                                    if child:IsA('Accessory') then
                                        table.insert(out, child)
                                    end
                                end
                            end
                        end

                        if out[1] then
                            rememberExtra(assetId, out[1].Name)
                        end

                        return out
                    end
                    local function extraLabel(entry)
                        local id = entry:match('/bundles/(%d+)') or entry:match('^bundle:(%d+)$') or entry:match('/catalog/(%d+)') or extractId(entry)
                        local name = id and extraNames[tostring(id)]

                        return name and (name .. '  #' .. id) or entry
                    end
                    local function gatherExtras(look)
                        local chosen = (Options.BundleExtraWear and Options.BundleExtraWear.Value) or {}
                        local out = {}

                        for _, entry in extraEntries(look)do
                            if look or chosen[extraLabel(entry)] ~= false then
                                for _, acc in gatherExtra(entry)do
                                    table.insert(out, acc)
                                end
                            end
                        end

                        return out
                    end
                    local function extraTag(entry)
                        local bundleId = entry:match('/bundles/(%d+)') or entry:match('^bundle:(%d+)$')

                        if bundleId then
                            return 'bundle:' .. bundleId
                        end

                        local assetId = entry:match('/catalog/(%d+)') or extractId(entry)

                        return tonumber(assetId) and tostring(assetId) or nil
                    end
                    local function morphVeil(rig, inst)
                        if rig.veil[inst] == nil then
                            rig.veil[inst] = inst.Transparency
                        end

                        pcall(function()
                            inst.Transparency = 1
                        end)
                    end
                    local function morphHideLimb(rig, limb)
                        if rig.hidden[limb.Name] == nil then
                            rig.hidden[limb.Name] = limb.Transparency
                        end

                        pcall(function()
                            limb.Transparency = 1
                        end)

                        for _, d in limb:GetChildren()do
                            if d:IsA('Decal') then
                                morphVeil(rig, d)
                            end
                        end
                    end
                    local function hideForMorph(char, rig)
                        for name in rig.hideSet or {}do
                            local limb = char:FindFirstChild(name)

                            if limb and limb:IsA('BasePart') then
                                morphHideLimb(rig, limb)
                            end
                        end
                        for name in rig.hidden do
                            local limb = char:FindFirstChild(name)

                            if limb and limb:IsA('BasePart') then
                                morphHideLimb(rig, limb)
                            end
                        end

                        local head = char:FindFirstChild('Head')
                        local bodyHidden = true

                        for name in MODEL_LIMBS.r6 do
                            if rig.hidden[name] == nil then
                                bodyHidden = false
                            end
                        end

                        if not (head and (bodyHidden or rig.hidden.Head ~= nil)) then
                            return
                        end

                        local holder = char:FindFirstChild('FaceHolder')

                        for _, d in holder and holder:GetChildren() or {}do
                            if d:IsA('Decal') then
                                morphVeil(rig, d)
                            end
                        end
                        for _, d in char:GetDescendants()do
                            if d:IsA('JointInstance') or d:IsA('WeldConstraint') then
                                local other = (d.Part0 == head and d.Part1) or (d.Part1 == head and d.Part0) or nil

                                if other and other:IsA('BasePart') and not MODEL_LIMBS.r6[other.Name] and other.Name ~= 'HumanoidRootPart' and not other:GetAttribute('SentinelBundle') and not other:FindFirstAncestorWhichIsA('Accoutrement') then
                                    morphVeil(rig, other)
                                end
                            end
                        end
                        for _, acc in char:GetChildren()do
                            local handle = acc:IsA('Accoutrement') and not acc:GetAttribute('SentinelBundle') and acc:FindFirstChild('Handle')

                            if handle and handle:IsA('BasePart') then
                                local joint = handle:FindFirstChild('AccessoryWeld')
                                local att = handle:FindFirstChildWhichIsA('Attachment')
                                local onHead = (joint and joint:IsA('JointInstance') and (joint.Part0 == head or joint.Part1 == head)) or (att ~= nil and head:FindFirstChild(att.Name) ~= nil)

                                if bodyHidden or onHead then
                                    morphVeil(rig, handle)

                                    for _, d in handle:GetDescendants()do
                                        if d:IsA('BasePart') or d:IsA('Decal') then
                                            morphVeil(rig, d)
                                        end
                                    end
                                end
                            end
                        end
                    end
                    local function watchMorph(char, rig)
                        if rig.morphWatch then
                            rig.morphWatch:Disconnect()
                        end

                        local queued = false

                        rig.morphWatch = char.DescendantAdded:Connect(function(
                            inst
                        )
                            if queued or not rig.id or not (inst:IsA('BasePart') or inst:IsA('Decal') or inst:IsA('Accoutrement')) then
                                return
                            end

                            local node = inst

                            while node and node ~= char do
                                if node:GetAttribute('SentinelBundle') then
                                    return
                                end

                                node = node.Parent
                            end

                            queued = true

                            task.defer(function()
                                queued = false

                                if rig.id and char.Parent then
                                    hideForMorph(char, rig)
                                end
                            end)
                        end)
                    end
                    local function morphSources(look)
                        if look then
                            return extractId(look.bundle or ''), nil, nil
                        end

                        local bundleId = extractId((Options.CharBundle and Options.CharBundle.Value) or '')

                        if isModelFile(bundleId) then
                            Notify.say('Bundle ID only takes catalog bundles. Put ' .. bundleId .. ' in Custom Character or Custom Head', 8)

                            bundleId = ''
                        end

                        local function file(flag)
                            local raw = ((Options[flag] and Options[flag].Value) or ''):match('^%s*(.-)%s*$')

                            if raw == '' then
                                return nil
                            end

                            return isModelFile(raw) and raw or (raw .. '.rbxm')
                        end

                        return bundleId, file('CharCustomBody'), file('CharCustomHead')
                    end
                    local function applyBundleInner(char, keepAdjust, look)
                        local rig = rigFor(char)
                        local bundleId, bodyFile, headFile = morphSources(look)
                        local key = bodyFile or (bundleId ~= '' and bundleId) or headFile

                        if not char or not key then
                            return
                        end

                        local hrp = char:FindFirstChild('HumanoidRootPart')

                        if not hrp then
                            return
                        end

                        clearBundle(char)

                        local freshTurn = headHandles.loadedFor ~= key

                        if not look and (not keepAdjust or freshTurn) then
                            local saved = readBundleFile(key)
                            local adj = (saved and saved.adjust) or {}

                            loadingAdjust = true

                            if not keepAdjust then
                                for flag, value in {
                                    BundleScale = adj.scale or 1,
                                    BundleOffset = adj.offset or 0,
                                    BundleHeadSize = adj.size or 1,
                                    BundleHeadY = adj.y or 0,
                                    BundleHeadZ = adj.z or 0,
                                }do
                                    if Options[flag] then
                                        Options[flag]:SetValue(value)
                                    end
                                end
                            end

                            local turn = headHandles.fit

                            turn.x, turn.rx, turn.ry, turn.rz = adj.x or 0, adj.rx or 0, adj.ry or 0, adj.rz or 0
                            headHandles.loadedFor = key
                            loadingAdjust = false
                        end

                        local meshes, accessories, headSameSpace, modelRoot, hideSet

                        if bodyFile then
                            meshes, accessories, headSameSpace, modelRoot, hideSet = gatherModel(bodyFile, 'body')
                        elseif bundleId ~= '' then
                            meshes, accessories, headSameSpace, modelRoot = gatherBundle(bundleId)

                            if not meshes then
                                Notify.say('Could not load bundle (check ID / API)')
                            end
                        end

                        meshes, accessories = meshes or {}, accessories or {}

                        if headFile then
                            local custom = gatherModel(headFile, 'head')

                            if custom and custom.Head then
                                if meshes.Head then
                                    meshes.Head:Destroy()
                                end

                                meshes.Head = custom.Head
                            end
                        end
                        if next(meshes) == nil and #accessories == 0 then
                            return
                        end

                        local applied = 0
                        local ref = meshes.LowerTorso or meshes.UpperTorso
                        local refAtt = ref and (ref:FindFirstChild('RootRigAttachment', true) or ref:FindFirstChildWhichIsA('Attachment'))
                        local refRoot = modelRoot or (refAtt and (ref.CFrame * refAtt.CFrame)) or (ref and ref.CFrame)
                        local offset = lookValue(look, 'offset', 'BundleOffset', 0)
                        local fit = headFit(look)
                        local jointByPart = {}

                        for _, m in char:GetDescendants()do
                            if m:IsA('Motor6D') and m.Part0 and m.Part1 then
                                jointByPart[m.Part1] = m
                            end
                        end

                        local function restRelHRP(part, depth)
                            if not part or part == hrp then
                                return CFrame.new()
                            end

                            local joint = jointByPart[part]

                            if not joint or depth > 6 then
                                return hrp.CFrame:ToObjectSpace(part.CFrame)
                            end

                            return restRelHRP(joint.Part0, depth + 1) * joint.C0 * joint.C1:Inverse()
                        end

                        for name, mesh in meshes do
                            local limbName = R15_TO_R6[name] or (MODEL_LIMBS.r6[name] and name)
                            local limb = limbName and char:FindFirstChild(limbName)
                            local isHead = name == 'Head'
                            local rigid = mesh:GetAttribute('SentinelRigid') == true

                            if limb and (isHead or rigid or refRoot) then
                                mesh.Anchored, mesh.CanCollide, mesh.CanQuery, mesh.CanTouch, mesh.Massless = false, false, false, false, true
                                mesh.Name = 'Morph' .. (name:gsub(' ', ''))
                                mesh.Parent = char

                                mesh:SetAttribute('SentinelBundle', true)

                                local weld = Instance.new('Weld')

                                weld.Part0, weld.Part1 = limb, mesh

                                local entry = {
                                    mesh = mesh,
                                    limb = limb,
                                    weld = weld,
                                    isHead = isHead,
                                    rigid = rigid,
                                    riders = {},
                                }

                                for _, d in mesh:GetDescendants()do
                                    if d:IsA('Weld') and d.Name == 'RiderWeld' and d.Part1 then
                                        local sm = d.Part1:FindFirstChildOfClass('SpecialMesh')

                                        table.insert(entry.riders, {
                                            weld = d,
                                            c0 = d.C0,
                                            part = d.Part1,
                                            size = d.Part1.Size,
                                            mesh = sm,
                                            scale = sm and sm.Scale,
                                        })
                                    end
                                end

                                if isHead then
                                    local sm = mesh:FindFirstChildOfClass('SpecialMesh')

                                    if sm then
                                        entry.headMesh = sm
                                        entry.baseScale = sm.Scale
                                    else
                                        entry.baseSize = mesh.Size
                                    end

                                    local base

                                    if not rigid then
                                        if modelRoot ~= nil or (not sm and headSameSpace) then
                                            base = mesh.CFrame
                                        else
                                            local ut = meshes.UpperTorso or meshes.LowerTorso

                                            if ut then
                                                local neck = ut:FindFirstChild('NeckRigAttachment', true)
                                                local neckWorld = neck and (ut.CFrame * neck.CFrame) or (ut.CFrame * CFrame.new(0, ut.Size.Y / 2, 0))

                                                base = CFrame.new(neckWorld.Position) * ut.CFrame.Rotation * CFrame.new(0, 0,
-0.3)
                                            end
                                        end
                                    end
                                    if base and refRoot then
                                        entry.headBase = refRoot:ToObjectSpace(base)
                                        entry.localOffset = entry.headBase * fit
                                        entry.limbRest = restRelHRP(limb, 0)
                                        weld.C0 = entry.limbRest:ToObjectSpace(CFrame.new(0, offset, 0) * entry.localOffset)
                                    else
                                        entry.headOnly = true
                                        weld.C0 = CFrame.new(0, offset, 0) * fit
                                    end
                                else
                                    entry.baseSize = mesh.Size
                                    entry.limbRest = restRelHRP(limb, 0)
                                    entry.localOffset = rigid and entry.limbRest or refRoot:ToObjectSpace(mesh.CFrame)
                                    weld.C0 = entry.limbRest:ToObjectSpace(CFrame.new(0, offset, 0) * entry.localOffset)
                                end

                                weld.Parent = mesh

                                table.insert(rig.parts, mesh)
                                table.insert(rig.morphs, entry)

                                if hideSet == nil or hideSet[limb.Name] or (isHead and headFile ~= nil) then
                                    morphHideLimb(rig, limb)
                                end

                                applied += 1
                            end
                        end

                        rig.hideSet = hideSet

                        hideForMorph(char, rig)
                        resizeBundle(rig, look)
                        repositionBundle(rig, look)

                        for _, acc in accessories do
                            if weldAccessory(char, acc) then
                                table.insert(rig.parts, acc)

                                applied += 1
                            else
                                acc:Destroy()
                            end
                        end
                        for _, acc in ((bundleId ~= '' and not bodyFile) and gatherExtras(look) or {})do
                            if weldAccessory(char, acc) then
                                table.insert(rig.parts, acc)

                                applied += 1
                            else
                                acc:Destroy()
                            end
                        end

                        if applied > 0 then
                            rig.hideScope = (bodyFile or bundleId ~= '') and 'body' or 'head'

                            hideOriginal(char, rig.hideScope)
                            watchMorph(char, rig)
                            applyHideHelm(char)

                            rig.id = key

                            pcall(char.SetAttribute, char, 'SentinelBundle', true)
                            task.spawn(function()
                                task.wait(0.3)

                                if active.bundle then
                                    repositionBundle(rig, look)
                                end
                            end)

                            if char == getChar() and headHandles.show then
                                headHandles.show()
                            end
                        end
                        if not look then
                            local wearing = {}

                            for _, part in {
                                bodyFile or (bundleId ~= '' and 'bundle ' .. bundleId) or nil,
                                headFile and ('head ' .. headFile) or nil,
                            }do
                                table.insert(wearing, part)
                            end

                            Library:Notify({
                                Title = 'sentinel.bz',
                                Description = applied > 0 and string.format('Wearing %s (%d parts)', table.concat(wearing, ' + '), applied) or 'The morph loaded nothing',
                            })
                        end
                    end

                    local bundleApplying = false
                    local bundleRerun = nil

                    local function applyBundle(char, keepAdjust, look)
                        if bundleApplying then
                            bundleRerun = bundleRerun or {}

                            table.insert(bundleRerun, {
                                char = char,
                                keepAdjust = keepAdjust,
                                look = look,
                            })

                            return
                        end

                        bundleApplying = true

                        local ok, err = pcall(applyBundleInner, char, keepAdjust, look)

                        bundleApplying = false

                        if not ok then
                            warn('[sentinel] applyBundle: ' .. tostring(err))
                        end

                        local queued = bundleRerun and table.remove(bundleRerun, 1)

                        if not (bundleRerun and #bundleRerun > 0) then
                            bundleRerun = nil
                        end
                        if queued then
                            applyBundle(queued.char, queued.keepAdjust, queued.look)
                        end
                    end

                    local adjustSaveScheduled = false

                    local function recordAdjust()
                        local rig = rigFor(getChar())

                        if loadingAdjust or not rig.id or not active.bundle then
                            return
                        end

                        saveBundleAdjust(rig.id, {
                            offset = (Options.BundleOffset and Options.BundleOffset.Value) or 0,
                            scale = (Options.BundleScale and Options.BundleScale.Value) or 1,
                            size = (Options.BundleHeadSize and Options.BundleHeadSize.Value) or 1,
                            y = (Options.BundleHeadY and Options.BundleHeadY.Value) or 0,
                            z = (Options.BundleHeadZ and Options.BundleHeadZ.Value) or 0,
                            x = headHandles.fit.x,
                            rx = headHandles.fit.rx,
                            ry = headHandles.fit.ry,
                            rz = headHandles.fit.rz,
                        })
                    end
                    local function scheduleAdjust()
                        local rig = rigFor(getChar())

                        if loadingAdjust or not rig.id or not active.bundle or adjustSaveScheduled then
                            return
                        end

                        adjustSaveScheduled = true

                        task.delay(0.6, function()
                            adjustSaveScheduled = false

                            recordAdjust()
                        end)
                    end

                    local preloading = {}

                    local function preloadBundle()
                        if getChar() then
                            return
                        end
                        if not (active.bundle and Toggles.CharCustomMaster and Toggles.CharCustomMaster.Value) then
                            return
                        end

                        local id = extractId(Options.CharBundle and Options.CharBundle.Value or '')

                        if id == '' or isModelFile(id) or bundleCache[id] or preloading[id] then
                            return
                        end

                        preloading[id] = true

                        task.spawn(function()
                            pcall(gatherBundle, id)

                            preloading[id] = nil
                        end)
                    end
                    local function cacheOriginal(char)
                        if not char then
                            return
                        end

                        pcall(function()
                            if not original.shirtCached then
                                local shirt = char:FindFirstChildOfClass('Shirt')

                                if shirt and shirt.ShirtTemplate ~= clothingTarget(Options.CharShirt) then
                                    original.shirt, original.shirtColor = shirt.ShirtTemplate, shirt.Color3
                                    original.shirtCached = true
                                end
                            end
                            if not original.pantsCached then
                                local pants = char:FindFirstChildOfClass('Pants')

                                if pants and pants.PantsTemplate ~= clothingTarget(Options.CharPants) then
                                    original.pants, original.pantsColor = pants.PantsTemplate, pants.Color3
                                    original.pantsCached = true
                                end
                            end
                            if not original.skinCached then
                                local body = char:FindFirstChildOfClass('BodyColors')
                                local head = char:FindFirstChild('Head')
                                local skin = (body and body.HeadColor3) or (head and head.Color)

                                if skin and not (active.skin and Options.SkinColor and skin == Options.SkinColor.Value) then
                                    original.skin = skin
                                    original.skinCached = true
                                end
                            end
                            if not original.faceCached then
                                local face = rlFace(char)

                                if face and face.Texture ~= '' and face.Texture ~= appliedFace then
                                    original.face = face.Texture
                                    original.rlfaceColor = face.Color3
                                    original.faceCached = true
                                end
                            end
                        end)
                    end
                    local function hasOriginal()
                        return original.shirtCached or original.pantsCached or original.skinCached or original.faceCached
                    end
                    local function restoreOriginal(char)
                        pcall(function()
                            local face = rlFace(char)

                            if face and original.face then
                                face.Texture = original.face

                                if original.rlfaceColor then
                                    face.Color3 = original.rlfaceColor
                                end
                            end
                            if original.shirt then
                                clearItem(char, 'Shirt')

                                local shirt = Make('Shirt', {
                                    ShirtTemplate = original.shirt,
                                })

                                if original.shirtColor then
                                    shirt.Color3 = original.shirtColor
                                end

                                shirt.Parent = char
                            end
                            if original.pants then
                                clearItem(char, 'Pants')

                                local pants = Make('Pants', {
                                    PantsTemplate = original.pants,
                                })

                                if original.pantsColor then
                                    pants.Color3 = original.pantsColor
                                end

                                pants.Parent = char
                            end
                            if original.skin then
                                local body = char:FindFirstChildOfClass('BodyColors') or Instance.new('BodyColors')

                                body.Parent = char
                                body.HeadColor3, body.TorsoColor3 = original.skin, original.skin
                                body.LeftArmColor3, body.RightArmColor3 = original.skin, original.skin
                                body.LeftLegColor3, body.RightLegColor3 = original.skin, original.skin
                            end

                            local worn = rigFor(char).acc

                            for _, acc in worn do
                                if acc and acc.Parent then
                                    acc:Destroy()
                                end
                            end

                            table.clear(worn)
                        end)
                    end

                    function applyHideHelm(char)
                        local rig = rigFor(char)

                        for i = #rig.helmConns, 1, -1 do
                            local conn = rig.helmConns[i]

                            if not (typeof(conn) == 'RBXScriptConnection' and conn.Connected) then
                                table.remove(rig.helmConns, i)
                            end
                        end

                        for part in rig.helm do
                            if not (typeof(part) == 'Instance' and part.Parent) then
                                rig.helm[part] = nil
                            end
                        end
                        for _, child in char:GetChildren()do
                            if child:IsA('Accessory') and child.Name == 'Helm' then
                                for _, part in child:GetDescendants()do
                                    if part:IsA('BasePart') and rig.helm[part] == nil then
                                        rig.helm[part] = part.Transparency

                                        pcall(function()
                                            part.Transparency = 1
                                        end)
                                        table.insert(rig.helmConns, part:GetPropertyChangedSignal('Transparency'):Connect(function(
                                        )
                                            local keep = (active.helm and char == getChar()) or rig.id ~= nil

                                            if keep and part.Transparency ~= 1 then
                                                pcall(function()
                                                    part.Transparency = 1
                                                end)
                                            end
                                        end))
                                    end
                                end
                            end
                        end
                    end
                    function restoreHelm(char)
                        local rig = rigFor(char or getChar())

                        for _, conn in rig.helmConns do
                            pcall(function()
                                conn:Disconnect()
                            end)
                        end

                        table.clear(rig.helmConns)

                        for part, transparency in rig.helm do
                            if part and part.Parent then
                                pcall(function()
                                    part.Transparency = transparency
                                end)
                            end
                        end

                        table.clear(rig.helm)
                    end

                    local function settleCharacter(char)
                        local started, last = os.clock(), os.clock()
                        local conn = char.DescendantAdded:Connect(function(
                            inst
                        )
                            if inst:IsA('BasePart') or inst:IsA('Accoutrement') or inst:IsA('Decal') then
                                last = os.clock()
                            end
                        end)

                        while char.Parent and os.clock() - started < 6 and os.clock() - last < 0.75 do
                            task.wait(0.1)
                        end

                        conn:Disconnect()
                    end
                    local function watchFaceTexture(char)
                        local face = rlFace(char)

                        if not face then
                            return
                        end

                        monitorMaid.faceTexture = face:GetPropertyChangedSignal('Texture'):Connect(function(
                        )
                            local texture = face.Texture

                            if texture == '' or texture == appliedFace then
                                return
                            end

                            original.face, original.rlfaceColor, original.faceCached = texture, face.Color3, true

                            if active.face then
                                task.defer(applyFace, char)
                            end
                        end)
                    end
                    local function applyAll(char)
                        if not char then
                            return
                        end

                        cacheOriginal(char)
                        monitorMaid:DoCleaning()

                        if active.face then
                            applyFace(char)
                        end
                        if active.shirt then
                            applyShirt(char)
                        end
                        if active.pants then
                            applyPants(char)
                        end
                        if active.accessories then
                            applyAccessories(char)
                        end
                        if active.skin then
                            applySkin(char)
                        end
                        if active.rlface then
                            applyRLFaceColor(char)
                        end
                        if active.dye then
                            applyDye(char)
                        end
                        if active.bundle then
                            task.spawn(function()
                                settleCharacter(char)

                                if active.bundle and char.Parent then
                                    applyBundle(char, true)
                                end
                            end)
                        end
                        if active.helm then
                            applyHideHelm(char)
                        end

                        local function touch(child)
                            if child:IsA('Accessory') and child.Name == 'Helm' and (active.helm or active.bundle) then
                                task.wait(0.1)
                                applyHideHelm(char)
                            elseif child:IsA('Shirt') and active.shirt then
                                cacheOriginal(char)
                                applyShirt(char)
                            elseif child:IsA('Pants') and active.pants then
                                cacheOriginal(char)
                                applyPants(char)
                            elseif child:IsA('BodyColors') and active.skin then
                                cacheOriginal(char)
                                applySkin(char)
                            end
                        end

                        monitorMaid.body = char.ChildAdded:Connect(touch)
                        monitorMaid.stripped = char.ChildRemoved:Connect(function(
                            child
                        )
                            if child:IsA('Shirt') and active.shirt then
                                applyShirt(char)
                            elseif child:IsA('Pants') and active.pants then
                                applyPants(char)
                            end
                        end)
                        monitorMaid.reconcile = task.spawn(function()
                            while true do
                                task.wait(CLOTHING_RECHECK)

                                local c = getChar()

                                if c == char and c.Parent then
                                    if active.shirt then
                                        applyShirt(c)
                                    end
                                    if active.pants then
                                        applyPants(c)
                                    end
                                    if active.skin then
                                        applySkin(c)
                                    end
                                end
                            end
                        end)

                        watchFaceTexture(char)

                        local function watchFaceDecals(holder)
                            if not holder then
                                return
                            end

                            monitorMaid['face_' .. holder.Name] = holder.ChildAdded:Connect(function(
                                child
                            )
                                if child.Name == 'RLFace' and child:IsA('Decal') then
                                    watchFaceTexture(char)
                                end
                                if not debounce and child:IsA('Decal') and active.face then
                                    debounce = true

                                    task.wait(0.1)
                                    applyFace(char)
                                    task.wait(0.5)

                                    debounce = false
                                end
                            end)
                        end

                        watchFaceDecals(char:FindFirstChild('Head'))
                        watchFaceDecals(char:FindFirstChild('FaceHolder'))
                    end
                    local function onNewCharacter(char)
                        if not char or char == lastChar then
                            return
                        end

                        lastChar = char

                        task.spawn(function()
                            char:WaitForChild('Humanoid', 5)
                            char:WaitForChild('Head', 5)

                            original.shirtCached, original.pantsCached, original.skinCached, original.faceCached = false, false, false, false

                            applyAll(char)

                            local t = 0

                            while not rlFace(char) and t < 5 do
                                task.wait(0.1)

                                t += 0.1
                            end

                            if rlFace(char) then
                                cacheOriginal(char)
                                watchFaceTexture(char)

                                if active.face then
                                    applyFace(char)
                                end
                                if active.rlface then
                                    applyRLFaceColor(char)
                                end
                            end
                        end)
                    end
                    local function startCustomization()
                        respawnMaid:DoCleaning()

                        local live = Workspace:FindFirstChild('Live')

                        if live then
                            respawnMaid.live = live.ChildAdded:Connect(function(
                                child
                            )
                                if child:IsA('Model') and child.Name == LocalPlayer.Name then
                                    onNewCharacter(child)
                                end
                            end)
                        end

                        respawnMaid.respawn = LocalPlayer.CharacterAdded:Connect(onNewCharacter)
                    end

                    local TOGGLE_FLAG = {
                        face = 'ApplyFace',
                        shirt = 'ApplyShirt',
                        pants = 'ApplyPants',
                        accessories = 'ApplyAccessories',
                        skin = 'ApplySkin',
                        dye = 'ApplyDye',
                        rlface = 'ApplyRLFace',
                        bundle = 'ApplyBundle',
                        helm = 'HideHelm',
                    }

                    local function syncActiveFromToggles()
                        for flag, tname in TOGGLE_FLAG do
                            local toggle = Toggles[tname]

                            if toggle then
                                active[flag] = toggle.Value
                            end
                        end
                    end
                    local function loadAndApply()
                        syncActiveFromToggles()

                        local char = getChar()

                        if char then
                            lastChar = char

                            if hasOriginal() then
                                clearBundle(char)
                                restoreOriginal(char)
                            end

                            cacheOriginal(char)
                            applyAll(char)
                        else
                            preloadBundle()
                        end

                        startCustomization()
                    end

                    local reapplying = false

                    ctx.State.reapplyCustomization = function()
                        if not (Toggles.CharCustomMaster and Toggles.CharCustomMaster.Value) then
                            return
                        end
                        if reapplying then
                            return
                        end

                        reapplying = true

                        task.delay(3, function()
                            reapplying = false
                        end)
                        task.spawn(function()
                            pcall(loadAndApply)

                            if ctx.State.refreshCharLists then
                                pcall(ctx.State.refreshCharLists)
                            end

                            reapplying = false
                        end)
                    end

                    ctx.Maid:Give(function()
                        respawnMaid:DoCleaning()
                        monitorMaid:DoCleaning()
                        clearBundle(getChar())
                        restoreHelm()

                        if hasOriginal() and getChar() then
                            restoreOriginal(getChar())
                        end
                    end)

                    local function requireMaster()
                        if Toggles.CharCustomMaster.Value then
                            return true
                        end

                        Notify.say('Enable Character Customization first')

                        return false
                    end

                    local facePresets = getFacePresets()
                    local faceNames = {}

                    for name in facePresets do
                        table.insert(faceNames, name)
                    end

                    table.sort(faceNames)

                    local outfitPresets = getOutfitPresets()
                    local outfitNames = {}

                    for name in outfitPresets do
                        table.insert(outfitNames, name)
                    end

                    table.sort(outfitNames)

                    local shared = {
                        peers = {},
                        sent = nil,
                        at = 0,
                        published = false,
                        maid = Maid.new(),
                    }

                    ctx.Maid:Give(shared.maid)

                    local SHARE_TICK = 5
                    local SHARE_REFRESH = 300

                    local function shareLog(fmt, ...)
                        if Toggles.ShareDebug and Toggles.ShareDebug.Value then
                            print('[share] ' .. string.format(fmt, ...))
                        end
                    end

                    local LOOK_URL = 'https://sentinel.heroinhound.cc/api/v1/sentinel/look'
                    local DEV_KEY_FILE = 'sentinel/devkey.txt'
                    local devKeyCache

                    local function devKey()
                        if devKeyCache then
                            return devKeyCache
                        end
                        if not (isfile and readfile) then
                            return nil
                        end

                        local ok, key = pcall(function()
                            return isfile(DEV_KEY_FILE) and readfile(DEV_KEY_FILE) or nil
                        end)

                        key = ok and type(key) == 'string' and key:match('^%s*(.-)%s*$') or nil
                        devKeyCache = key ~= '' and key or nil

                        return devKeyCache
                    end
                    local function devSync(look, watch)
                        local key = devKey()
                        local httpRequest = (http and http.request) or http_request or request

                        if not (key and httpRequest) then
                            return nil, 'no dev key'
                        end

                        local payload = {
                            watch = watch == true,
                            job = tostring(game.JobId or ''),
                            user = LocalPlayer.UserId,
                        }

                        if look == false then
                            payload.clear = true
                        elseif type(look) == 'table' then
                            payload.look = look
                        end

                        local built, body = pcall(function()
                            return HttpService:JSONEncode(payload)
                        end)

                        if not (built and type(body) == 'string') then
                            return nil, 'encode'
                        end

                        local ok, res = pcall(httpRequest, {
                            Url = LOOK_URL,
                            Method = 'POST',
                            Headers = {
                                ['x-sfx'] = key,
                                ['Content-Type'] = 'application/json',
                            },
                            Body = body,
                        })

                        if not (ok and type(res) == 'table') then
                            return nil, 'transport'
                        end

                        local status = res.StatusCode or res.status_code or 0

                        if status ~= 200 then
                            return nil, status
                        end

                        local read, decoded = pcall(function()
                            return HttpService:JSONDecode(res.Body or res.body or '')
                        end)

                        if not (read and type(decoded) == 'table') then
                            return nil, 'decode'
                        end

                        return type(decoded.data) == 'table' and decoded.data or decoded, status
                    end
                    local function lookPicked(name)
                        local picked = Options.SharedLook and Options.SharedLook.Value

                        return picked ~= nil and picked[name] == true
                    end
                    local function optionText(option)
                        local value = option and option.Value

                        return (type(value) == 'string' and value ~= '') and value or nil
                    end
                    local function idOnly(value)
                        local text = tostring(value or '')

                        return text:match('asset/%?id=(%d+)') or text:match('rbxassetid://(%d+)') or text:match('/catalog/(%d+)') or text:match('/bundles/(%d+)') or text:match('^%s*(%d+)%s*$')
                    end
                    local function myLook()
                        local look = {
                            face = active.face and idOnly(optionText(Options.CharFace)) or nil,
                            shirt = active.shirt and idOnly(optionText(Options.CharShirt)) or nil,
                            pants = active.pants and idOnly(optionText(Options.CharPants)) or nil,
                            skin = active.skin and Options.SkinColor and Options.SkinColor.Value:ToHex() or nil,
                            dye = active.dye and Options.ClothingDye and Options.ClothingDye.Value:ToHex() or nil,
                        }
                        local list = active.accessories and optionText(Options.CharAccessories)

                        if list then
                            look.acc = {}

                            for token in list:gmatch('[^,]+')do
                                local id = token:match('%d+')

                                if id and #look.acc < 8 then
                                    table.insert(look.acc, id)
                                end
                            end
                        end

                        local customBody = optionText(Options.CharCustomBody) ~= nil
                        local customHead = optionText(Options.CharCustomHead) ~= nil

                        if lookPicked('Share My Bundle') and active.bundle and not customBody then
                            local id = idOnly(optionText(Options.CharBundle)) or ''

                            if id ~= '' then
                                look.bundle = id
                                look.scale = Options.BundleScale and Options.BundleScale.Value or nil
                                look.offset = Options.BundleOffset and Options.BundleOffset.Value or nil

                                if not customHead then
                                    look.head = Options.BundleHeadSize and Options.BundleHeadSize.Value or nil
                                    look.heady = Options.BundleHeadY and Options.BundleHeadY.Value or nil
                                    look.headz = Options.BundleHeadZ and Options.BundleHeadZ.Value or nil

                                    for key, field in {
                                        headx = 'x',
                                        headrx = 'rx',
                                        headry = 'ry',
                                        headrz = 'rz',
                                    }do
                                        local value = headHandles.fit[field]

                                        if value ~= 0 then
                                            look[key] = value
                                        end
                                    end
                                end

                                local chosen = (Options.BundleExtraWear and Options.BundleExtraWear.Value) or {}
                                local tags = {}

                                for _, entry in extraEntries()do
                                    if chosen[extraLabel(entry)] ~= false then
                                        local tag = extraTag(entry)

                                        if tag and #tags < 8 then
                                            table.insert(tags, tag)
                                        end
                                    end
                                end

                                if #tags > 0 then
                                    look.extras = table.concat(tags, ',')
                                end
                            end
                        end

                        return look
                    end
                    local function lookKey(look)
                        local parts = {}

                        for _, key in {
                            'face',
                            'shirt',
                            'pants',
                            'bundle',
                            'extras',
                            'skin',
                            'dye',
                            'scale',
                            'offset',
                            'head',
                            'heady',
                            'headz',
                            'headx',
                            'headrx',
                            'headry',
                            'headrz',
                        }do
                            table.insert(parts, tostring(look[key]))
                        end

                        table.insert(parts, table.concat(look.acc or {}, '.'))

                        return table.concat(parts, '|')
                    end
                    local function peerCache(char, entry)
                        if entry.was then
                            return
                        end

                        local shirt = char:FindFirstChildOfClass('Shirt')
                        local pants = char:FindFirstChildOfClass('Pants')
                        local face = rlFace(char)
                        local body = char:FindFirstChildOfClass('BodyColors')
                        local limbs = {}

                        for _, part in char:GetChildren()do
                            if part:IsA('BasePart') then
                                limbs[part.Name] = part.Color
                            end
                        end

                        entry.was = {
                            shirt = shirt and shirt.ShirtTemplate,
                            pants = pants and pants.PantsTemplate,
                            shirtDye = shirt and shirt.Color3,
                            pantsDye = pants and pants.Color3,
                            face = face and face.Texture,
                            limbs = limbs,
                            hadBody = body ~= nil,
                            skin = body and {
                                body.HeadColor3,
                                body.TorsoColor3,
                                body.LeftArmColor3,
                                body.RightArmColor3,
                                body.LeftLegColor3,
                                body.RightLegColor3,
                            },
                        }
                    end
                    local function peerRestore(char, entry)
                        local was = entry.was

                        if not (char and was) then
                            return
                        end

                        pcall(function()
                            local shirt = char:FindFirstChildOfClass('Shirt')

                            if shirt then
                                if was.shirt then
                                    shirt.ShirtTemplate = was.shirt
                                end
                                if was.shirtDye then
                                    shirt.Color3 = was.shirtDye
                                end
                            end

                            local pants = char:FindFirstChildOfClass('Pants')

                            if pants then
                                if was.pants then
                                    pants.PantsTemplate = was.pants
                                end
                                if was.pantsDye then
                                    pants.Color3 = was.pantsDye
                                end
                            end
                            if was.face then
                                local face = rlFace(char)

                                if face then
                                    face.Texture = was.face
                                end
                            end

                            local body = char:FindFirstChildOfClass('BodyColors')

                            if body and not was.hadBody then
                                body:Destroy()
                            elseif body and was.skin then
                                body.HeadColor3, body.TorsoColor3 = was.skin[1], was.skin[2]
                                body.LeftArmColor3, body.RightArmColor3 = was.skin[3], was.skin[4]
                                body.LeftLegColor3, body.RightLegColor3 = was.skin[5], was.skin[6]
                            end

                            for name, colour in was.limbs or {}do
                                local part = char:FindFirstChild(name)

                                if part and part:IsA('BasePart') then
                                    part.Color = colour
                                end
                            end
                        end)
                    end
                    local function dropPeer(userId)
                        local entry = shared.peers[userId]

                        if not entry then
                            return
                        end

                        shared.peers[userId] = nil

                        if entry.maid then
                            entry.maid:DoCleaning()
                        end

                        local player = Players:GetPlayerByUserId(userId)
                        local char = player and player.Character

                        if char then
                            pcall(clearBundle, char)
                            peerRestore(char, entry)
                        end
                    end
                    local function wearPeerLook(char, look, entry, again)
                        entry.maid = entry.maid or Maid.new()

                        entry.maid:DoCleaning()

                        if look.face then
                            pcall(applyFace, char, look)
                        end

                        local shirtOk = (look.shirt or '') == '' or select(2, pcall(applyShirt, char, look, entry.maid)) == true
                        local pantsOk = (look.pants or '') == '' or select(2, pcall(applyPants, char, look, entry.maid)) == true

                        if look.skin then
                            pcall(applySkin, char, look)
                        end
                        if look.dye then
                            pcall(applyDye, char, look)
                        end
                        if not again then
                            pcall(applyAccessories, char, {
                                acc = look.acc or {},
                            })

                            if look.bundle and look.bundle ~= '' and lookPicked('Show Their Bundles') then
                                task.spawn(applyBundle, char, true, look)
                            end
                        end

                        return shirtOk and pantsOk
                    end
                    local function takeLooks(rows)
                        local seen = {}
                        local wantBundle = lookPicked('Show Their Bundles')

                        shareLog('%d look(s) came back', #rows)

                        for _, row in rows do
                            local userId = tonumber(row.user) or 0
                            local look = type(row.look) == 'table' and row.look or nil
                            local player = userId > 0 and Players:GetPlayerByUserId(userId)
                            local char = player and player ~= LocalPlayer and player.Character

                            shareLog('peer %s player=%s char=%s look=%s', maskId(userId), player and player.Name or 'not in server', char and 'yes' or 'no', look and 'yes' or 'no')

                            if char and look then
                                seen[userId] = true

                                local entry = shared.peers[userId]
                                local key = lookKey(look)

                                if not entry then
                                    entry = {
                                        key = nil,
                                        char = nil,
                                    }
                                    shared.peers[userId] = entry
                                end
                                if entry.key ~= key or entry.char ~= char or entry.bundle ~= wantBundle then
                                    local sameBody = entry.char == char

                                    entry.key, entry.char, entry.bundle = key, char, wantBundle

                                    if entry.worn and sameBody then
                                        if entry.maid then
                                            entry.maid:DoCleaning()
                                        end

                                        pcall(clearBundle, char)
                                        peerRestore(char, entry)
                                    elseif not sameBody then
                                        entry.was = nil
                                    end

                                    peerCache(char, entry)

                                    entry.worn = true
                                    entry.pending = not wearPeerLook(char, look, entry)

                                    shareLog('peer %s dressed shirt=%s pants=%s bundle=%s pending=%s', maskId(userId), maskId(look.shirt), maskId(look.pants), maskId(look.bundle), tostring(entry.pending))
                                elseif entry.pending then
                                    entry.pending = not wearPeerLook(char, look, entry, true)

                                    shareLog('peer %s retried, pending=%s', maskId(userId), tostring(entry.pending))
                                end
                            end
                        end
                        for userId in shared.peers do
                            if not seen[userId] then
                                dropPeer(userId)
                            end
                        end
                    end
                    local function forgetEveryone()
                        for userId in shared.peers do
                            dropPeer(userId)
                        end
                    end
                    local function shareTick()
                        if shared.off then
                            return
                        end

                        local sync = getgenv and getgenv().__looksync
                        local how = 'loader'

                        if type(sync) ~= 'function' then
                            sync, how = devKey() and devSync or nil, 'dev key'
                        end

                        shareLog('channel=%s', type(sync) == 'function' and how or 'MISSING')

                        if type(sync) ~= 'function' then
                            if not shared.warned and (lookPicked('Share Mine') or lookPicked('Show Others')) then
                                shared.warned = true

                                Library:Notify({
                                    Title = 'sentinel.bz',
                                    Description = 'Sharing needs a newer build than this one is running',
                                    Time = 10,
                                })
                            end

                            return
                        end

                        local sharing = lookPicked('Share Mine') and Toggles.CharCustomMaster ~= nil and Toggles.CharCustomMaster.Value == true
                        local watching = lookPicked('Show Others')

                        shareLog('master=%s share=%s watch=%s', tostring(Toggles.CharCustomMaster and Toggles.CharCustomMaster.Value), tostring(sharing), tostring(watching))

                        if not (sharing or watching) then
                            if shared.published then
                                shared.published, shared.sent = false, nil

                                pcall(sync, false, false)
                            end

                            forgetEveryone()

                            return
                        end

                        local payload, candidate

                        if sharing then
                            local look = myLook()
                            local key = lookKey(look)

                            shareLog('mine face=%s shirt=%s pants=%s bundle=%s', maskId(look.face), maskId(look.shirt), maskId(look.pants), maskId(look.bundle))

                            if key ~= shared.sent or os.clock() - (shared.at or 0) > SHARE_REFRESH then
                                candidate, payload = key, look
                            else
                                shareLog('unchanged since the last publish, not resending')
                            end
                        elseif shared.published then
                            shared.published, shared.sent = false, nil
                            payload = false
                        end

                        local ok, reply, status = pcall(sync, payload, watching)

                        shareLog('sent=%s status=%s reply=%s', payload == nil and 'nothing' or (payload == false and 'clear' or 'look'), tostring(status), type(reply))

                        if not (ok and type(reply) == 'table') then
                            shareLog(
[[no usable reply. 401=no session, 409=session has no server, 400=look refused]])

                            return
                        end
                        if candidate then
                            shared.sent, shared.at, shared.published = candidate, os.clock(), true
                        end
                        if not watching then
                            forgetEveryone()
                        elseif type(reply.looks) == 'table' then
                            takeLooks(reply.looks)
                        else
                            shareLog('the reply carried no looks list')
                        end
                    end

                    shared.maid:Give(Players.PlayerRemoving:Connect(function(
                        player
                    )
                        dropPeer(player.UserId)
                    end))
                    shared.maid:Give(task.spawn(function()
                        while true do
                            task.wait(SHARE_TICK)
                            pcall(shareTick)
                        end
                    end))
                    ctx.Maid:Give(function()
                        shared.off = true

                        shared.maid:DoCleaning()
                        forgetEveryone()

                        local sync = getgenv and getgenv().__looksync

                        if shared.published and type(sync) == 'function' then
                            pcall(sync, false, false)
                        end

                        shared.published, shared.sent = false, nil
                    end)

                    local Box = Player:AddRightGroupbox('Character Customization')

                    Box:AddToggle('CharCustomMaster', {
                        Text = 'Enable Character Customization',
                        Default = false,
                        Callback = function(on)
                            if ctx.State.loadingConfig then
                                return
                            end
                            if on then
                                task.spawn(loadAndApply)
                            else
                                respawnMaid:DoCleaning()
                                monitorMaid:DoCleaning()

                                for key in active do
                                    active[key] = false
                                end

                                clearBundle(getChar())
                                restoreHelm()

                                if getChar() then
                                    restoreOriginal(getChar())
                                end
                            end
                        end,
                    })
                    Box:AddDivider()
                    Box:AddDropdown('SharedLook', {
                        Text = 'Share With Sentinel Users',
                        Tooltip = 'Other sentinel users see your look, you see theirs',
                        Multi = true,
                        Values = {
                            'Share Mine',
                            'Share My Bundle',
                            'Show Others',
                            'Show Their Bundles',
                        },
                        Default = {},
                        AllowNull = true,
                        Callback = function()
                            if ctx.State.loadingConfig then
                                return
                            end

                            task.spawn(function()
                                pcall(shareTick)
                            end)
                        end,
                    })
                    Box:AddDivider()
                    Box:AddToggle('ShareDebug', {
                        Text = 'Debug Sharing',
                        Default = false,
                    })

                    local function restoreAccessories()
                        local worn = rigFor(getChar()).acc

                        for _, acc in worn do
                            if acc and acc.Parent then
                                acc:Destroy()
                            end
                        end

                        table.clear(worn)
                    end
                    local function bindFeature(
                        name,
                        text,
                        flag,
                        applyFn,
                        restoreFn
                    )
                        return Box:AddToggle(name, {
                            Text = text,
                            Default = false,
                            Callback = function(on)
                                active[flag] = on

                                if ctx.State.loadingConfig then
                                    return
                                end

                                local char = getChar()

                                if on then
                                    if not Toggles.CharCustomMaster.Value then
                                        Notify.say('Enable Character Customization first')
                                    elseif char then
                                        applyFn(char)
                                    end
                                elseif char then
                                    pcall(restoreFn, char)
                                end
                            end,
                        })
                    end

                    Box:AddDropdown('FacePreset', {
                        Text = 'Face Preset',
                        Values = faceNames,
                        Default = nil,
                        Multi = false,
                        Callback = function(value)
                            local texture = facePresets[value]

                            if texture then
                                Options.CharFace:SetValue(texture)
                            end
                        end,
                    })
                    Box:AddInput('CharFace', {
                        Text = 'Face ID',
                        Placeholder = 'Face ID',
                        Finished = true,
                        Callback = function()
                            if active.face and Toggles.CharCustomMaster.Value and getChar() then
                                applyFace(getChar())
                            end
                        end,
                    })
                    bindFeature('ApplyFace', 'Apply Face', 'face', applyFace, function(
                        char
                    )
                        local face = rlFace(char)

                        if face and original.face then
                            face.Texture = original.face
                        end
                    end)
                    Box:AddDropdown('OutfitPreset', {
                        Text = 'Outfit Preset',
                        Values = outfitNames,
                        Default = nil,
                        Multi = false,
                    })
                    Box:AddButton({
                        Text = 'Apply Outfit',
                        Func = function()
                            if not requireMaster() then
                                return
                            end

                            local folder = outfitPresets[Options.OutfitPreset.Value]

                            if not folder then
                                Notify.say('Select an outfit first')

                                return
                            end
                            if not respawnMaid.respawn then
                                startCustomization()
                            end
                            if getChar() then
                                applyOutfit(getChar(), folder)

                                if Toggles.ApplyShirt then
                                    Toggles.ApplyShirt:SetValue(true)
                                end
                                if Toggles.ApplyPants then
                                    Toggles.ApplyPants:SetValue(true)
                                end

                                Notify.say('Outfit applied')
                            end
                        end,
                    })
                    Box:AddInput('CharShirt', {
                        Text = 'Shirt ID',
                        Placeholder = 'Shirt template ID',
                        Finished = true,
                        Callback = function()
                            clothingTarget(Options.CharShirt)

                            if active.shirt and Toggles.CharCustomMaster.Value and getChar() then
                                applyShirt(getChar())
                            end
                        end,
                    })
                    bindFeature('ApplyShirt', 'Apply Shirt', 'shirt', applyShirt, function(
                        char
                    )
                        clearItem(char, 'Shirt')

                        if original.shirt then
                            local shirt = Make('Shirt', {
                                ShirtTemplate = original.shirt,
                                Parent = char,
                            })
                        end
                    end)
                    Box:AddInput('CharPants', {
                        Text = 'Pants ID',
                        Placeholder = 'Pants template ID',
                        Finished = true,
                        Callback = function()
                            clothingTarget(Options.CharPants)

                            if active.pants and Toggles.CharCustomMaster.Value and getChar() then
                                applyPants(getChar())
                            end
                        end,
                    })
                    bindFeature('ApplyPants', 'Apply Pants', 'pants', applyPants, function(
                        char
                    )
                        clearItem(char, 'Pants')

                        if original.pants then
                            local pants = Make('Pants', {
                                PantsTemplate = original.pants,
                                Parent = char,
                            })
                        end
                    end)
                    Box:AddInput('CharAccessories', {
                        Text = 'Accessories',
                        Placeholder = 'id,id,id',
                        Finished = true,
                        Callback = function()
                            if active.accessories and Toggles.CharCustomMaster.Value and getChar() then
                                applyAccessories(getChar())
                            end
                        end,
                    })
                    bindFeature('ApplyAccessories', 'Apply Accessories', 'accessories', applyAccessories, function(
                    )
                        restoreAccessories()
                    end)
                    pcall(Paths.ensure, Paths.CHARACTERS)

                    local function morphChanged()
                        if ctx.State.loadingConfig then
                            return
                        end
                        if active.bundle and Toggles.CharCustomMaster.Value and getChar() then
                            task.spawn(applyBundle, getChar())
                        else
