                    local function refreshFromDisk()
                        local labels = {}

                        for _, entry in listBundles()do
                            table.insert(labels, entry.name .. '  #' .. entry.id)
                        end

                        if Options.SavedBundles then
                            Options.SavedBundles:SetValues(labels)
                        end

                        refreshExtraList()
                    end

                    local refreshing = false

                    local function refreshBundleLists()
                        if refreshing then
                            return
                        end

                        refreshing = true

                        task.spawn(function()
                            local entries = listBundles()
                            local alive, answered = {}, {}

                            for first = 1, #entries, BUNDLE_BATCH do
                                local ids = {}

                                for i = first, math.min(first + BUNDLE_BATCH - 1, #entries)do
                                    table.insert(ids, entries[i].id)
                                end

                                local body = ctx.State.robloxGet and ctx.State.robloxGet('https://catalog.roblox.com/v1/bundles/details?bundleIds=' .. table.concat(ids, ','))
                                local data = body and select(2, pcall(function()
                                    return HttpService:JSONDecode(body)
                                end))

                                bdbg('checked %d ids, %s', #ids, type(data) == 'table' and (#data .. ' came back') or 'no reply')

                                if type(data) == 'table' then
                                    for _, id in ids do
                                        answered[id] = true
                                    end
                                    for _, item in data do
                                        if item.id then
                                            alive[tostring(item.id)] = item.name
                                        end
                                    end
                                end
                            end

                            local labels, dead = {}, {}

                            for _, entry in entries do
                                local name = alive[entry.id]

                                if name then
                                    entry.name = name

                                    writeBundleName(entry.id, name)
                                    table.insert(labels, name .. '  #' .. entry.id)
                                elseif answered[entry.id] then
                                    table.insert(dead, entry.name)

                                    bundleCache[entry.id] = nil

                                    if delfile then
                                        pcall(delfile, CACHE_DIR .. '/' .. entry.id .. '.json')
                                    end

                                    bdbg('deleted cache for %s (%s)', entry.name, entry.id)
                                else
                                    table.insert(labels, '[?] ' .. entry.name .. '  #' .. entry.id)
                                end
                            end

                            if Options.SavedBundles then
                                Options.SavedBundles:SetValues(labels)
                            end

                            refreshExtraList()
                            Library:Notify({
                                Title = 'sentinel.bz',
                                Description = #dead > 0 and (#dead .. ' gone, removed: ' .. table.concat(dead, ', ')) or (#labels .. ' bundle(s) checked, all good'),
                                Time = 8,
                            })

                            refreshing = false
                        end)
                    end

                    Box:AddButton({
