                    local function headEntry()
                        for _, entry in rigFor(getChar()).morphs do
                            if entry.isHead and entry.mesh and entry.mesh.Parent then
                                return entry
                            end
                        end

                        return nil
                    end
                    local function syncHeadSliders(fit)
                        local rx, ry, rz = fit:ToEulerAnglesXYZ()
                        local turn = headHandles.fit

                        turn.x, turn.rx, turn.ry, turn.rz = fit.X, math.deg(rx), math.deg(ry), math.deg(rz)

                        for flag, value in {
                            BundleHeadY = fit.Y,
                            BundleHeadZ = -fit.Z,
                        }do
                            if Options[flag] then
                                Options[flag]:SetValue(value)
                            end
                        end

                        repositionBundle()
                        scheduleAdjust()
                    end
                    local function endHeadDrag()
                        if not headHandles.drag then
                            return
                        end

                        headHandles.drag = nil

                        headHandles.dragMaid:DoCleaning()
                        Remotes.blockFire('bundleHeadHandle', nil)

                        ctx.State.bundleHandleHeld = nil

                        scheduleAdjust()
                    end
                    local function beginHeadDrag()
                        local entry = headEntry()

                        if headHandles.drag or not entry then
                            return
                        end

                        local scale = entry.headOnly and 1 or math.max(lookValue(nil, 'scale', 'BundleScale', 1), 0.05)

                        headHandles.drag = {
                            fit = headFit(nil),
                            scale = scale,
                        }

                        Remotes.blockFire('bundleHeadHandle', headHandles.clicks)

                        ctx.State.bundleHandleHeld = true

                        headHandles.dragMaid:Connect(UserInputService.InputEnded, function(
                            input
                        )
                            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                                endHeadDrag()
                            end
                        end)
                        headHandles.dragMaid:Connect(RunService.Heartbeat, function(
                        )
                            if not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
                                endHeadDrag()
                            end
                        end)
                    end
                    local function headSnapped()
                        return Toggles.BundleSnap ~= nil and Toggles.BundleSnap.Value == true
                    end
                    local function buildHeadHandles()
                        local move = Make('Handles', {
                            Style = Enum.HandlesStyle.Movement,
                            Color3 = Color3.fromRGB(90, 200, 255),
                            Visible = false,
                            Parent = Gui.root(),
                        })
                        local turn = Make('ArcHandles', {
                            Visible = false,
                            Parent = Gui.root(),
                        })

                        headHandles.maid:Give(move)
                        headHandles.maid:Give(turn)
                        headHandles.maid:Connect(move.MouseButton1Down, beginHeadDrag)
                        headHandles.maid:Connect(move.MouseButton1Up, endHeadDrag)
                        headHandles.maid:Connect(move.MouseDrag, function(
                            face,
                            distance
                        )
                            local drag = headHandles.drag

                            if not drag then
                                return
                            end
                            if headSnapped() then
                                distance = math.round(distance / 0.1) * 0.1
                            end

                            syncHeadSliders(drag.fit * CFrame.new(Vector3.FromNormalId(face) * (distance / drag.scale)))
                        end)
                        headHandles.maid:Connect(turn.MouseButton1Down, beginHeadDrag)
                        headHandles.maid:Connect(turn.MouseButton1Up, endHeadDrag)
                        headHandles.maid:Connect(turn.MouseDrag, function(
                            axis,
                            angle
                        )
                            local drag = headHandles.drag

                            if not drag then
                                return
                            end
                            if headSnapped() then
                                angle = math.round(angle / math.rad(15)) * math.rad(15)
                            end

                            syncHeadSliders(drag.fit * CFrame.fromAxisAngle(Vector3.FromAxis(axis), angle))
                        end)

                        headHandles.move, headHandles.turn = move, turn
                    end

                    function headHandles.show()
                        local entry = Toggles.BundleHandles and Toggles.BundleHandles.Value and headEntry() or nil

                        if not entry then
                            endHeadDrag()

                            if headHandles.move then
                                headHandles.move.Adornee, headHandles.turn.Adornee = nil, nil
                                headHandles.move.Visible, headHandles.turn.Visible = false, false
                            end

                            return
                        end
                        if not headHandles.move then
                            buildHeadHandles()
                        end

                        local rotate = Options.BundleHandleMode ~= nil and Options.BundleHandleMode.Value == 'Rotate'

                        headHandles.move.Adornee = not rotate and entry.mesh or nil
                        headHandles.turn.Adornee = rotate and entry.mesh or nil
                        headHandles.move.Visible, headHandles.turn.Visible = not rotate, rotate
                    end

                    ctx.Maid:Give(function()
                        endHeadDrag()
                        Remotes.blockFire('bundleHeadHandle', nil)

                        ctx.State.bundleHandleHeld = nil
                    end)
                    Box:AddToggle('BundleHandles', {
