                    })

                    do
                        local ashiinMaid = Maid.new()

                        ctx.Maid:Give(ashiinMaid)

                        local ashiin = {
                            punches = {
                                ['rbxassetid://2604492936'] = 'MonkPunch1',
                                ['rbxassetid://2604509857'] = 'MonkPunch2',
                                ['rbxassetid://2604512331'] = 'MonkPunch3',
                                ['rbxassetid://2604513567'] = 'MonkPunch4',
                                ['rbxassetid://2604515616'] = 'MonkPunch5',
                            },
                            muted = 'rbxassetid://2916750659',
                            tracks = {},
                            busy = {},
                        }

                        local function combatAnims(char)
                            local handler = char:FindFirstChild('CharacterHandler')
                            local live = handler and handler:FindFirstChild('CombatAnims')

                            if live then
                                return live
                            end

                            local starter = Services:Get('StarterPlayer'):FindFirstChild('StarterCharacterScripts')

                            handler = starter and starter:FindFirstChild('CharacterHandler')

                            return (handler and handler:FindFirstChild('CombatAnims')) or ReplicatedStorage:FindFirstChild('CombatAnims')
                        end
                        local function hookAshiin(char)
                            ashiinMaid.played = nil

                            table.clear(ashiin.tracks)
                            table.clear(ashiin.busy)

                            local humanoid = char and char:WaitForChild('Humanoid', 10)

                            if not humanoid or char ~= getChar() then
                                return
                            end

                            ashiinMaid.played = humanoid.AnimationPlayed:Connect(function(
                                track
                            )
                                local id = track.Animation and track.Animation.AnimationId

                                if id == ashiin.muted then
                                    track:Stop()

                                    return
                                end

                                local name = ashiin.punches[id]

                                if not name or ashiin.busy[id] then
                                    return
                                end

                                local anims = combatAnims(char)
                                local source = anims and anims:FindFirstChild(name)

                                if not source then
                                    return
                                end

                                ashiin.busy[id] = true

                                track:Stop()

                                local swap = ashiin.tracks[name]

                                if not swap then
                                    swap = (humanoid:FindFirstChildOfClass('Animator') or humanoid):LoadAnimation(source)
                                    ashiin.tracks[name] = swap
                                end

                                task.delay(swap.Length, function()
                                    ashiin.busy[id] = nil
                                end)

                                local speed = CollectionService:HasTag(char, 'BrokenArm') and 0.8 or 1

                                swap:Play(0.1, 1, speed * 1.45)
                            end)
                        end

                        Box:AddToggle('AshiinCombat', {
                            Text = 'Ashiin Combat',
                            Tooltip = 'Swaps the plain fist M1s for Ashiin m1',
                            Default = false,
                            Callback = function(on)
                                ashiinMaid:DoCleaning()
                                table.clear(ashiin.tracks)
                                table.clear(ashiin.busy)

                                if not on then
                                    return
                                end

                                ashiinMaid.respawn = LocalPlayer.CharacterAdded:Connect(hookAshiin)

                                local char = getChar()

                                if char then
                                    task.spawn(hookAshiin, char)
                                end
                            end,
                        })
                    end

                    Box:AddDivider()
                    Box:AddButton({
                        Text = 'Clear All & Disable',
                        Func = function()
                            for _, tname in TOGGLE_FLAG do
