                end
                do
                    local ServersBox = Player:AddLeftGroupbox('Servers')
                    local PS_FILE = Paths.PRIVATE_SERVERS
                    local loopJoinMaid = Maid.new()

                    ctx.Maid:Give(loopJoinMaid)

                    local function jobIdList()
                        local out = {}

                        for id in string.gmatch(Options.JobIdInput.Value or '', '[^,]+')do
                            local trimmed = id:match('^%s*(.-)%s*$')

                            if trimmed ~= '' then
                                table.insert(out, trimmed)
                            end
                        end

                        return out
                    end
                    local function recentSet()
                        local set = {}

                        for _, id in Serverhop.visited()do
                            set[id] = true
                        end

                        return set
                    end
                    local function remote(name)
                        local requests = ReplicatedStorage:FindFirstChild('Requests')

                        return requests and requests:FindFirstChild(name)
                    end
                    local function returnToMenu()
                        local r = remote('ReturnToMenu')

                        if r and Menu.safeToMenu() then
                            pcall(function()
                                r:InvokeServer()
                            end)
                            task.wait(0.5)
                        end
                    end
                    local function joinJob(jobId)
                        if not jobId or jobId == '' then
                            Notify.say('Enter a Job ID')

                            return
                        end

                        local r = remote('JoinPublicServer')

                        if not r then
                            Notify.say('Join remote not found')

                            return
                        end

                        Danger.hold(Library, function()
                            Notify.say('In Danger, holding the join until combat clears', 6)
                        end)
                        returnToMenu()
                        Serverhop.markVisited(jobId)
                        Console.print(string.format('[sentinel] joining server %s (%d in recent cache)', jobId, #Serverhop.visited()))
                        Notify.say('Joining server')
                        r:FireServer(jobId)
                    end
                    local function serverInfoPick(wantMax)
                        local folder = ReplicatedStorage:FindFirstChild('ServerInfo')

                        if not folder then
                            return nil
                        end

                        local best, bestLife
                        local seen = recentSet()

                        for _, info in folder:GetChildren()do
                            local lifespan = info:FindFirstChild('Lifespan')
                            local players = info:FindFirstChild('Players')

                            if lifespan and players and info.Name ~= game.JobId and not seen[info.Name] then
                                local count = 0

                                pcall(function()
                                    count = #HttpService:JSONDecode(players.Value)
                                end)

                                if count < 23 and (not bestLife or (wantMax and lifespan.Value > bestLife) or (not wantMax and lifespan.Value < bestLife)) then
                                    best, bestLife = info.Name, lifespan.Value
                                end
                            end
                        end

                        return best
                    end
                    local function resolvePlayerJob(username)
                        username = username:lower()

                        local folder = ReplicatedStorage:FindFirstChild('ServerInfo')

                        if folder then
                            for _, info in folder:GetChildren()do
                                local players = info:FindFirstChild('Players')
                                local list

                                if players then
                                    pcall(function()
                                        list = HttpService:JSONDecode(players.Value)
                                    end)
                                end

                                for _, entry in list or {}do
                                    local name = type(entry) == 'table' and (entry.Name or entry.username) or entry

                                    if name and tostring(name):lower() == username then
                                        return info.Name
                                    end
                                end
                            end
                        end

                        local ok, userId = pcall(function()
                            return Players:GetUserIdFromNameAsync(username)
                        end)

                        if not ok or not userId then
                            return nil, "Couldn't find user '" .. username .. "'"
                        end

                        local presences = ctx.State.getPresence and ctx.State.getPresence({userId})
                        local presence = presences and presences[userId]

                        if not presence or not presence.joinable or not presence.gameId or presence.gameId == '' then
                            return nil, 'User is not in a joinable server'
                        end

                        return presence.gameId
                    end
                    local function joinByPlayer(username)
                        task.spawn(function()
                            local jobId, why = resolvePlayerJob(username)

                            if jobId then
                                joinJob(jobId)
                            else
                                Notify.say(why or 'No server found')
                            end
                        end)
                    end
                    local function joinOr(jobId, what)
                        Console.print(string.format('[sentinel] %s -> %s', what or 'serverhop', jobId and ('picked ' .. jobId) or 'no joinable server found'))

                        if jobId then
                            joinJob(jobId)
                        else
                            Notify.say('No server found')
                        end
                    end

                    local joinDebounce = false

                    local function debounced(fn)
                        return function()
                            if joinDebounce then
                                Notify.say('Please wait before joining again')

                                return
                            end

                            joinDebounce = true

                            task.delay(2, function()
                                joinDebounce = false
                            end)
                            fn()
                        end
                    end

                    if game.PlaceId == 5208655184 then
                        local lootLabels = {}

                        for _, zone in LootZones.list do
                            lootLabels[zone.trigger] = ServersBox:AddLabel(zone.label .. ': ...')
                        end

                        ServersBox:AddDivider()

                        local valueLabel = ServersBox:AddLabel('Inventory Value: ...')
                        local countLabel = ServersBox:AddLabel('Players: ...')
                        local lootAccum = 0

                        ctx.Maid:Give(RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                            dt
                        )
                            lootAccum += dt

                            if lootAccum < 1 then
                                return
                            end

                            lootAccum = 0

                            for _, zone in LootZones.list do
                                local mins = LootZones.minutesSince(zone.trigger)

                                lootLabels[zone.trigger]:SetText(zone.label .. ': ' .. (mins and (mins .. 'm') or '?'))
                            end

                            local worth = 0
                            local bag = LocalPlayer:FindFirstChildOfClass('Backpack')

                            for _, child in (bag and bag:GetChildren() or {})do
                                local silver = child:FindFirstChild('SilverValue')

                                if silver then
                                    worth += silver.Value
                                end
                            end

                            valueLabel:SetText('Inventory Value: ' .. worth)
                            countLabel:SetText(string.format('Players: %d/%d', #Players:GetPlayers(), Players.MaxPlayers))
                        end)))
                        ServersBox:AddDivider()
                    end

                    ServersBox:AddInput('JobIdInput', {
                        Text = 'Job ID',
                        Placeholder = 'jobid',
                        Finished = false,
                    })
                    ServersBox:AddButton({
                        Text = 'Join by Job ID',
