                    ServersBox:AddToggle('LoopJoin', {
                        Text = 'Loop Join',
                        Tooltip = 'Keeps trying until it gets in',
                        Default = false,
                        Callback = function(on)
                            loopJoinMaid:DoCleaning()

                            if not on then
                                return
                            end

                            local join = remote('JoinPublicServer')

                            if not join then
                                Notify.say('Join remote not found')
                                Toggles.LoopJoin:SetValue(false)

                                return
                            end
                            if Toggles.AntiAfk and not Toggles.AntiAfk.Value then
                                Toggles.AntiAfk:SetValue(true)
                            end

                            local alive, idx = true, 1
                            local cachedJob

                            loopJoinMaid:Give(function()
                                alive = false
                            end)
                            task.spawn(function()
                                while alive do
                                    local who = Options.ServerPlayerInput.Value or ''
                                    local ids

                                    if who ~= '' then
                                        if not cachedJob then
                                            local why

                                            cachedJob, why = resolvePlayerJob(who)

                                            if not cachedJob then
                                                Notify.say(why or 'No server found')
                                                Toggles.LoopJoin:SetValue(false)

                                                return
                                            end

                                            Notify.say(string.format('Loop Join: %s is in %s', who, cachedJob))
                                        end

                                        ids = {cachedJob}
                                    else
                                        ids = jobIdList()
                                    end
                                    if #ids == 0 then
                                        Notify.say('Enter a Job ID or a player name first')
                                        Toggles.LoopJoin:SetValue(false)

                                        return
                                    end

                                    local jobId = ids[((idx - 1) % #ids) + 1]

                                    idx += 1

                                    local char = LocalPlayer.Character

                                    while alive and char and CollectionService:HasTag(char, 'Danger') do
                                        task.wait(0.2)

                                        char = LocalPlayer.Character
                                    end

                                    if not alive then
                                        return
                                    end
                                    if LocalPlayer.Character then
                                        returnToMenu()
                                    end

                                    pcall(function()
                                        join:FireServer(jobId)
                                    end)
                                    task.wait(0.5)
                                end
                            end)
                        end,
                    })
                    ServersBox:AddDivider()
                    ServersBox:AddButton({
                        Text = 'Serverhop',
                        Tooltip = 'Blocks everyone here through RAM, then hops',
                        Func = function()
                            task.spawn(function()
                                Console.print(string.format(
[[[sentinel] Serverhop -> blocking lobby + hopping (%d in recent cache)]], #Serverhop.visited()))
                                Danger.hold(Library, function()
                                    Notify.say('In Danger, holding the hop until combat clears', 6)
                                end)
                                Notify.say('Serverhopping...')
                                Serverhop.hop({
                                    strategy = 'random',
                                    block = true,
                                    minPlayers = 0,
                                    menuWait = false,
                                })
                            end)
                        end,
