                            joinOr(Serverhop.pickServer({
                                strategy = 'largest',
                            }), 'Join Largest Server')
                        end),
                    })
                    ServersBox:AddButton({
                        Text = 'Join Smallest Server',
                        Func = debounced(function()
                            joinOr(Serverhop.pickServer({
                                strategy = 'smallest',
                            }), 'Join Smallest Server')
                        end),
                    })
                    ServersBox:AddButton({
                        Text = 'Join Oldest Server',
