                            joinOr(serverInfoPick(true), 'Join Oldest Server')
                        end),
                    })
                    ServersBox:AddButton({
                        Text = 'Join Newest Server',
                        Func = debounced(function()
                            joinOr(serverInfoPick(false), 'Join Newest Server')
                        end),
