                    ServersBox:AddButton({
                        Text = 'Clear Server History',
                        Func = function()
                            local hist = Serverhop.visited()

                            Console.print(string.format(
[[[sentinel] Clear Server History -> wiping %d recent server(s): %s]], #hist, #hist > 0 and table.concat(hist, ', ') or '(none)'))
                            Serverhop.clearVisited()
                            Notify.say('History cleared')
                        end,
                    })

                    local function serverInfo()
                        local name, region = '', ''
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local gui = pg and pg:FindFirstChild('ServerStatsGui')
                        local stats = gui and gui:FindFirstChild('Frame') and gui.Frame:FindFirstChild('Stats')

                        if stats then
                            local sn = stats:FindFirstChild('ServerName')

                            if sn then
                                name = sn.Text:match('Server Name: (.+)') or ''
                            end

                            local sr = stats:FindFirstChild('ServerRegion')

                            if sr then
                                region = sr.Text:match('Server Region: (.+)') or ''
                            end
                        end

                        return name, region
                    end

                    ServersBox:AddButton({
                        Text = 'Copy Server Information',
                        Func = function()
                            local clip = setclipboard or toclipboard

                            if not clip then
                                Notify.say('Clipboard not available on this executor')

                                return
                            end

                            local result = ''
                            local name, region = serverInfo()

                            if name ~= '' and region ~= '' then
                                result = name .. ' ' .. game.JobId .. ' [' .. region .. ']\n\n'
                            end

                            local others, ids = {}, {}

                            for _, player in Players:GetPlayers()do
                                if player ~= LocalPlayer then
                                    table.insert(others, player)
                                    table.insert(ids, player.UserId)
                                end
                            end

                            local joinable = ctx.State.getPresence and ctx.State.getPresence(ids)
                            local withLinks, withoutLinks = {}, {}

                            for _, player in others do
                                local rogue = (ctx.State.getRogueName and ctx.State.getRogueName(player)) or ''

                                if rogue == '' or rogue == 'nil' or rogue == 'Unknown' then
                                    rogue = player.DisplayName or player.Name
                                end

                                local label = rogue .. ' [' .. player.Name .. ']'

                                if joinable and joinable[player.UserId] and joinable[player.UserId].joinable then
                                    table.insert(withLinks, label .. ' <https://www.roblox.com/users/' .. tostring(player.UserId) .. '/profile>')
                                else
                                    table.insert(withoutLinks, label)
                                end
                            end

                            if #withLinks > 0 then
                                result = result .. table.concat(withLinks, '\n')

                                if #withoutLinks > 0 then
                                    result = result .. '\n'
                                end
                            end
                            if #withoutLinks > 0 then
                                result = result .. table.concat(withoutLinks, '\n')
                            end

                            clip(result)
                            Notify.say('Copied server info')
                        end,
                    })

                    local function loadPS()
                        return Json.read(PS_FILE) or {}
                    end
                    local function savePS(list)
                        Json.write(PS_FILE, list)
                    end

                    local psServers = loadPS()

                    local function joinPrivate(code)
                        local r = remote('JoinPrivateServer')

                        if r and code ~= '' then
                            MemStore.set('privateserver_code', code)
                            Danger.hold(Library, function()
                                Notify.say('In Danger, holding the join until combat clears', 6)
                            end)
                            returnToMenu()
                            r:FireServer(code)
                            Notify.say('Joining private server')
                        end
                    end

                    ServersBox:AddDivider()
                    ServersBox:AddDropdown('PSServerList', {
                        Text = 'Saved PS Codes',
                        Values = psServers,
                        Default = nil,
                        Multi = false,
                    })
                    ServersBox:AddInput('PSCode', {
                        Text = 'PS Code',
                        Placeholder = 'server code',
                        Finished = false,
                    })
                    ServersBox:AddButton({
                        Text = 'Join PS Code',
                        Func = function()
                            joinPrivate(Options.PSCode.Value ~= '' and Options.PSCode.Value or (Options.PSServerList.Value or ''))
                        end,
                    })
                    ServersBox:AddButton({
                        Text = 'Save PS Code',
                        Func = function()
                            local code = Options.PSCode.Value

                            if code ~= '' and not table.find(psServers, code) then
                                table.insert(psServers, code)
                                savePS(psServers)
                                Options.PSServerList:SetValues(psServers)
                                Notify.say('Saved PS code')
                            end
                        end,
                    })
                    ServersBox:AddButton({
                        Text = 'Delete PS Code',
                        Func = function()
                            local idx = Options.PSServerList.Value and table.find(psServers, Options.PSServerList.Value)

                            if idx then
                                table.remove(psServers, idx)
                                savePS(psServers)
                                Options.PSServerList:SetValues(psServers)
                            end
                        end,
                    })
                end
            end
        end

        function __DARKLUA_BUNDLE_MODULES.ai(): typeof(__modImpl())
            local v = __DARKLUA_BUNDLE_MODULES.cache.ai

            if not v then
                v = {
                    c = __modImpl(),
                }
                __DARKLUA_BUNDLE_MODULES.cache.ai = v
            end

            return v.c
        end
    end
    do
        local function __modImpl()
            local Services = __DARKLUA_BUNDLE_MODULES.a()
            local Character = __DARKLUA_BUNDLE_MODULES.C()
            local Maid = __DARKLUA_BUNDLE_MODULES.d()
            local Paths = __DARKLUA_BUNDLE_MODULES.c()
            local Gate = __DARKLUA_BUNDLE_MODULES.q()
            local StaffWatch = __DARKLUA_BUNDLE_MODULES.l()
            local AvoidList = __DARKLUA_BUNDLE_MODULES.k()
            local Json = __DARKLUA_BUNDLE_MODULES.e()
            local Players, RunService, CollectionService, HttpService, TweenService = Services:Get('Players', 'RunService', 'CollectionService', 'HttpService', 'TweenService')
            local LocalPlayer = Players.LocalPlayer
            local LIVE_DIR = Paths.CACHE .. '/grips'
            local COUNT_FILE = Paths.BIN .. '/grips.json'
            local BEACON_EVERY = 2
            local BEACON_STALE = 8
            local LEASH = 250
            local GRIP_RANGE = 15
            local KNOCK_LIMIT = 12
            local KNOCK_STEP = 0.5
            local SPAWN_WAIT = 30
            local EXECUTE_EVERY = 1
            local EXEC_WINDOW = 6
            local BEACON_ROT = 120
            local TRAVEL_SPEED = 90
            local TRAVEL_HOP = 1400
            local TRAVEL_LIMIT = 12
            local ARRIVE_RANGE = 8
            local STOP_EVERY = 0.5

            return function(ctx)
                local section = ctx.State.gripsTab

                if not section then
                    return
                end

                local Options, Toggles = ctx.Library.Options, ctx.Library.Toggles
                local maid = Maid.new()

                ctx.Maid:Give(maid)

                local unloaded = false
                local running, altBusy = false, false

                ctx.Maid:Give(function()
                    unloaded = true
                end)

                local readJson, writeJson = Json.read, Json.write
                local counts = readJson(COUNT_FILE) or {}
                local myKey = tostring(LocalPlayer.UserId)
                local gripCount = tonumber(counts[myKey]) or 0
                local gripLabel

                local function paintCount()
                    if gripLabel then
                        gripLabel:SetText('Grips: ' .. gripCount)
                    end
                end
                local function countGrip()
                    gripCount += 1

                    counts = readJson(COUNT_FILE) or counts
                    counts[myKey] = gripCount

                    writeJson(COUNT_FILE, counts)
                    paintCount()
                end
                local function beaconPath(userId)
                    return string.format('%s/p_%s.json', LIVE_DIR, tostring(userId))
                end
                local function commandPath()
                    return LIVE_DIR .. '/cmd.json'
                end
                local function myChar()
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild('HumanoidRootPart')

                    return char, root
                end
                local function knocked(char)
                    return char ~= nil and CollectionService:HasTag(char, 'Unconscious')
                end
                local function writeBeacon()
                    local char, root = myChar()

                    writeJson(beaconPath(LocalPlayer.UserId), {
                        name = LocalPlayer.Name,
                        display = LocalPlayer.DisplayName,
                        userId = LocalPlayer.UserId,
                        jobId = game.JobId,
                        at = os.time(),
                        down = knocked(char),
                        blatant = Gate.on(ctx.Library, 'Blatant'),
                        y = root and math.floor(root.Position.Y) or 0,
                    })
                end
                local function readBeacons()
                    local out = {}

                    if not (listfiles and isfolder and isfolder(LIVE_DIR)) then
                        return out
                    end

                    local ok, files = pcall(listfiles, LIVE_DIR)

                    if not ok then
                        return out
                    end

                    local now = os.time()

                    for _, file in files do
                        local leaf = tostring(file):match('[^/\\]+$') or ''

                        if leaf:sub(1, 2) == 'p_' and leaf:sub(-5) == '.json' then
                            local data = readJson(file)

                            if type(data) == 'table' then
                                local age = now - (tonumber(data.at) or 0)

                                if age > BEACON_ROT then
                                    if delfile then
                                        pcall(delfile, file)
                                    end
                                elseif data.jobId == game.JobId and tonumber(data.userId) ~= LocalPlayer.UserId and age <= BEACON_STALE then
                                    table.insert(out, data)
                                end
                            end
                        end
                    end

                    return out
                end
                local function playerByName(name)
                    for _, p in Players:GetPlayers()do
                        if p.Name == name then
                            return p
                        end
                    end

                    return nil
                end
                local function matchPlayer(name)
                    name = tostring(name or ''):lower()

                    if name == '' then
                        return nil
                    end

                    local prefix, contains

                    for _, p in Players:GetPlayers()do
                        if p ~= LocalPlayer then
                            local n, d = p.Name:lower(), (p.DisplayName or ''):lower()

                            if n == name or d == name then
                                return p
                            end
                            if not prefix and (n:sub(1, #name) == name or d:sub(1, #name) == name) then
                                prefix = p
                            end
                            if not contains and (n:find(name, 1, true) or d:find(name, 1, true)) then
                                contains = p
                            end
                        end
                    end

                    return prefix or contains
                end
                local function rootOf(player)
                    local char = player and player.Character

                    return char and char:FindFirstChild('HumanoidRootPart') or nil
                end
                local function distanceTo(player)
                    local _, root = myChar()
                    local theirs = rootOf(player)

                    if not (root and theirs) then
                        return nil
                    end

                    return (theirs.Position - root.Position).Magnitude
                end

                local haltedBy, activeTween = nil, nil
                local commandedAt = 0

                local function halted()
                    return haltedBy ~= nil
                end
                local function executionRemote()
                    local char = LocalPlayer.Character
                    local handler = char and char:FindFirstChild('CharacterHandler')
                    local remotes = handler and handler:FindFirstChild('Remotes')

                    return remotes and remotes:FindFirstChild('Execution') or nil
                end

                gripLabel = section:AddLabel('Grips: ' .. gripCount)

                if not (writefile and readfile and isfile and listfiles and isfolder) then
                    section:AddLabel('This executor has no file access, so alts cannot be listed', true)
                end

                section:AddLabel('Inject sentinel on every alt, then pick them here', true)
                section:AddDropdown('GripTargets', {
                    Text = 'Alts',
                    Values = {},
                    Multi = true,
                    Default = {},
                    Tooltip = 'Only alts running sentinel show up',
                })
                section:AddButton({
                    Text = 'Reset Count',
                    DoubleClick = true,
                    Func = function()
                        gripCount = 0
                        counts[myKey] = 0

                        writeJson(COUNT_FILE, counts)
                        paintCount()
                    end,
                })

                local known, beaconByName = {}, {}

                local function refreshRoster()
                    local names, changed = {}, false

                    table.clear(beaconByName)

                    for _, beacon in readBeacons()do
                        table.insert(names, beacon.name)

                        beaconByName[beacon.name] = beacon
                    end

                    table.sort(names)

                    if #names ~= #known then
                        changed = true
                    else
                        for i, n in names do
                            if known[i] ~= n then
                                changed = true

                                break
                            end
                        end
                    end
                    if changed then
                        known = names

                        if Options.GripTargets then
                            Options.GripTargets:SetValues(names)
                        end
                    end
                end
                local function selectedNames()
                    local picked = Options.GripTargets and Options.GripTargets.Value or {}
                    local out = {}

                    for name, on in pairs(picked)do
                        if on then
                            table.insert(out, name)
                        end
                    end

                    return out
                end

                local lastExecuting = 0
                local watched = setmetatable({}, {
                    __mode = 'k',
                })

                local function watchVictim(player)
                    if watched[player] then
                        return
                    end

                    watched[player] = true

                    local function hook(char)
                        local hum = char:FindFirstChildOfClass('Humanoid') or char:WaitForChild('Humanoid', 5)

                        if not hum then
                            return
                        end

                        maid['died_' .. player.UserId] = hum.Died:Connect(function(
                        )
                            if unloaded then
                                return
                            end

                            local d = distanceTo(player)

                            if d and d <= GRIP_RANGE and tick() - lastExecuting <= EXEC_WINDOW then
                                countGrip()
                            end
                        end)
                    end

                    if player.Character then
                        task.spawn(hook, player.Character)
                    end

                    maid['spawn_' .. player.UserId] = player.CharacterAdded:Connect(hook)
                end

                maid:Give(Players.PlayerRemoving:Connect(function(p)
                    maid['spawn_' .. p.UserId] = nil
                    maid['died_' .. p.UserId] = nil
                    watched[p] = nil
                end))

                for _, p in Players:GetPlayers()do
                    if p ~= LocalPlayer then
                        watchVictim(p)
                    end
                end

                maid:Give(Players.PlayerAdded:Connect(function(p)
                    if p ~= LocalPlayer then
                        watchVictim(p)
                    end
                end))

                local function pushCommand()
                    local targets = {}

                    for _, name in selectedNames()do
                        local p = playerByName(name)

                        if p then
                            table.insert(targets, p.UserId)
                        end
                    end

                    writeJson(commandPath(), {
                        master = LocalPlayer.UserId,
                        masterName = LocalPlayer.Name,
                        jobId = game.JobId,
                        targets = targets,
                        at = os.time(),
                    })
                end
                local function clearCommand()
                    local cmd = readJson(commandPath())

                    if type(cmd) == 'table' and tonumber(cmd.master) ~= LocalPlayer.UserId then
                        return
                    end
                    if delfile and isfile and isfile(commandPath()) then
                        pcall(delfile, commandPath())
                    end
                end

                local lastExecute = 0
                local warned = {}

                local function masterStep()
                    if halted() then
                        return
                    end

                    for _, name in selectedNames()do
                        local p = playerByName(name)
                        local beacon = beaconByName[name]

                        if beacon and beacon.blatant == false and not warned[name] then
                            warned[name] = true

                            ctx.Library:Notify({
                                Title = 'sentinel.bz',
                                Description = name .. ' needs Blatant Mode on for grips',
                            })
                        end
                        if p then
                            watchVictim(p)

                            local d = distanceTo(p)
                            local theirChar = p.Character
                            local busy = LocalPlayer.Character ~= nil and LocalPlayer.Character:FindFirstChild('Executing') ~= nil

                            if not busy and d and d <= GRIP_RANGE and knocked(theirChar) and tick() - lastExecute >= EXECUTE_EVERY then
                                local remote = executionRemote()

                                if remote then
                                    lastExecute = tick()

                                    pcall(function()
                                        remote:FireServer()
                                    end)
                                end
                            end
                        end
                    end
                end

                section:AddInput('GripMaster', {
                    Text = 'Master',
                    Default = '',
                    Placeholder = 'who grips you',
                    Finished = true,
                    Tooltip = 'Empty = whoever turned it on',
                    Callback = function(value)
                        local p = matchPlayer(value)

                        if not p then
                            return
                        end
                        if p.Name ~= value then
                            Options.GripMaster:SetValue(p.Name)

                            return
                        end

                        for _, beacon in readBeacons()do
                            if beacon.name == p.Name then
                                ctx.Library:Notify({
                                    Title = 'sentinel.bz',
                                    Description = p.Name ..
[[ is injected too, so you can drive every alt from there instead]],
                                })

                                break
                            end
                        end
                    end,
                })
                section:AddLabel('Goes to the master and knocks itself, over and over', true)

                local function altRole()
                    local typed = Options.GripMaster and Options.GripMaster.Value or ''

                    return typed ~= ''
                end
                local function commandedMaster()
                    local cmd = readJson(commandPath())

                    if type(cmd) == 'table' and cmd.jobId == game.JobId and os.time() - (tonumber(cmd.at) or 0) <= BEACON_STALE and type(cmd.targets) == 'table' then
                        for _, id in cmd.targets do
                            if tonumber(id) == LocalPlayer.UserId then
                                return playerByName(tostring(cmd.masterName))
                            end
                        end
                    end

                    local typed = Options.GripMaster and Options.GripMaster.Value or ''

                    if typed ~= '' and Toggles.GripBotEnabled and Toggles.GripBotEnabled.Value then
                        return matchPlayer(typed)
                    end

                    return nil
                end
                local function awaitSpawn(deadline)
                    while not unloaded and tick() < deadline do
                        if Character.ready() then
                            return true
                        end

                        task.wait(0.3)
                    end

                    return Character.ready() ~= nil
                end
                local function knockSelf()
                    local waited = 0

                    while not unloaded and not halted() and waited < KNOCK_LIMIT do
                        local char = LocalPlayer.Character

                        if knocked(char) then
                            return true
                        end

                        local hum = char and char:FindFirstChildOfClass('Humanoid')

                        if not (hum and hum.Health > 0) then
                            return knocked(char)
                        end
                        if ctx.State.fireFall then
                            ctx.State.fireFall(2.39, 'grips')
                        end

                        task.wait(KNOCK_STEP)

                        waited += KNOCK_STEP
                    end

                    return knocked(LocalPlayer.Character)
                end
                local function tweenStep(pos, speed)
                    local r = Character.root()

                    if not r then
                        return false
                    end

                    local far = (pos - r.Position).Magnitude
                    local step = (far <= TRAVEL_HOP) and pos or (r.Position + (pos - r.Position).Unit * TRAVEL_HOP)
                    local dist = (step - r.Position).Magnitude
                    local tween = TweenService:Create(r, TweenInfo.new(math.max(dist / (speed or TRAVEL_SPEED), 0.05), Enum.EasingStyle.Linear), {
                        CFrame = CFrame.new(step),
                    })
                    local done = false

                    tween.Completed:Connect(function()
                        done = true
                    end)

                    activeTween = tween

                    tween:Play()

                    local waited = 0

                    while not done and not unloaded and not halted() and waited < TRAVEL_LIMIT do
                        task.wait(0.05)

                        waited += 0.05
                    end

                    if not done then
                        pcall(function()
                            tween:Cancel()
                        end)
                    end

                    activeTween = nil

                    return done
                end
                local function goToMaster(master)
                    local conn = RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        Character.noclip(LocalPlayer.Character, true)
                    end))
                    local deadline = tick() + TRAVEL_LIMIT

                    while not unloaded and not halted() and tick() < deadline do
                        local r = Character.root()
                        local theirs = rootOf(master)

                        if not (r and theirs) or (r.Position - theirs.Position).Magnitude <= ARRIVE_RANGE then
                            break
                        end

                        tweenStep(theirs.Position, TRAVEL_SPEED)
                    end

                    conn:Disconnect()
                    Character.reclip(LocalPlayer.Character)
                    task.wait(0.4)
                end
                local function altStep()
                    if not Gate.on(ctx.Library, 'Blatant') then
                        return
                    end
                    if running and not altRole() then
                        return
                    end

                    local master = commandedMaster()

                    if master then
                        commandedAt = tick()
                    end
                    if not master or halted() then
                        return
                    end
                    if not awaitSpawn(tick() + SPAWN_WAIT) then
                        return
                    end
                    if knocked(LocalPlayer.Character) then
                        return
                    end

                    local d = distanceTo(master)

                    if not d or d > LEASH then
                        return
                    end

                    goToMaster(master)

                    local arrived = distanceTo(master)

                    if halted() or not arrived or arrived > ARRIVE_RANGE * 3 then
                        return
                    end

                    knockSelf()
                end
                local function findIntruder(range)
                    local _, root = myChar()

                    if not root then
                        return nil
                    end

                    local friendly = ctx.State.isFriendly
                    local typed = Options.GripMaster and Options.GripMaster.Value or ''
                    local master = typed ~= '' and matchPlayer(typed) or nil
                    local picked = Options.GripTargets and Options.GripTargets.Value or {}

                    for _, p in Players:GetPlayers()do
                        local theirs = p ~= LocalPlayer and rootOf(p)

                        if theirs and p ~= master and not beaconByName[p.Name] and not picked[p.Name] and not (friendly and friendly(p)) then
                            local d = (theirs.Position - root.Position).Magnitude

                            if d <= range then
                                return p, d
                            end
                        end
                    end

                    return nil
                end

                local accum, stopAccum = 0, 0

                maid:Give(RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                    dt
                )
                    if unloaded then
                        return
                    end

                    local me = LocalPlayer.Character

                    if me and me:FindFirstChild('Executing') then
                        lastExecuting = tick()
                    end

                    stopAccum += dt

                    if stopAccum >= STOP_EVERY then
                        stopAccum = 0

                        local engaged = running or tick() - commandedAt < BEACON_STALE
                        local found, kind = nil, nil

                        if engaged then
                            local stopIllu = Toggles.GripStopOnIllusionist ~= nil and Toggles.GripStopOnIllusionist.Value

                            found, kind = StaffWatch.find(ctx, {
                                moderators = true,
                                illusionists = stopIllu,
                            })
                        end

                        local why = found and string.format('%s %s is in the server', kind == 'illusionist' and 'Illusionist' or AvoidList.label(found), found.Name)
                        local range = Options.GripProximity and Options.GripProximity.Value or 0

                        if engaged and not found and range > 0 then
                            local d

                            found, d = findIntruder(range)
                            why = found and string.format('%s came within %.0f studs', found.Name, d)
                        end
                        if found and found ~= haltedBy then
                            ctx.Library:Notify({
                                Title = 'sentinel.bz',
                                Description = why .. ', grip bot stopped',
                            })
                        end

                        haltedBy = found

                        if found then
                            if activeTween then
                                pcall(function()
                                    activeTween:Cancel()
                                end)
                            end
                            if Toggles.GripBotEnabled and Toggles.GripBotEnabled.Value then
                                Toggles.GripBotEnabled:SetValue(false)
                            end
                        end
                    end

                    accum += dt

                    if accum < BEACON_EVERY then
                        return
                    end

                    accum = 0

                    writeBeacon()
                    refreshRoster()

                    if running and not altRole() then
                        pushCommand()
                        masterStep()
                    end
                    if not altBusy then
                        altBusy = true

                        task.spawn(function()
                            pcall(altStep)

                            altBusy = false
                        end)
                    end
                end)))
                section:AddDivider()
                section:AddToggle('GripBotEnabled', {
                    Text = 'Enable Grip Bot',
                    Tooltip = Gate.blatant('alts come to you and knock themselves'),
                    Default = false,
                    Callback = function(value)
                        if value and Gate.blocked(ctx, 'Blatant', 'GripBotEnabled', 'Grip Bot') then
                            return
                        end

                        running = value

                        if value then
                            pushCommand()
                        else
                            clearCommand()
                        end
                    end,
                })
                Gate.mark(ctx, 'Blatant', 'GripBotEnabled')
                section:AddToggle('GripStopOnIllusionist', {
                    Text = 'Stop On Illusionist',
                    Tooltip = 'Stops everything while one is in the server',
                    Default = true,
                })
                section:AddSlider('GripProximity', {
