            local function stringDirection(index, total, phase)
                local camera = Workspace.CurrentCamera
                local right = camera and camera.CFrame.RightVector or Vector3.xAxis
                local up = camera and camera.CFrame.UpVector or Vector3.yAxis
                local depthAxis = camera and camera.CFrame.LookVector or Vector3.zAxis
                local sector = (math.pi * 2) / total
                local angle = phase + (index - 1) * sector

                angle += rand:NextNumber(-sector * 0.16, sector * 0.16)

                local radial = right * math.cos(angle) + up * math.sin(angle)
                local depthPattern = {
                    -1,
                    0.55,
                    -0.25,
                    0.9,
                    0,
                    -0.7,
                    0.3,
                }
                local depth = depthPattern[((index - 1) % #depthPattern) + 1] * STRING_DEPTH

                return (radial + depthAxis * depth).Unit
            end
