                local phase = rand:NextNumber(0, math.pi * 2)

                for i = 1, total do
                    local object = parts[((i - 1) % #parts) + 1]

                    if object and object.Parent then
                        local reach = rand:NextNumber(STRING_REACH_MIN, STRING_REACH_MAX)
                        local direction = stringDirection(i, total, phase)

                        buildString(object, folder, reach, direction, i % 7 == 0)
