            local CODE_KEY = 'privateserver_code'
            local ALIASES = {
                joinps = 'private',
                joinprivate = 'private',
                joinprivateserver = 'private',
                joinserver = 'server',
                join = 'player',
                rejoin = 'rejoin',
                heal = 'heal',
                jobid = 'jobid',
