                private = true,
                server = true,
                player = true,
            }

            return function(ctx)
                local Library = ctx.Library
                local maid = Maid.new()

                ctx.Maid:Give(maid)

                local function notify(text)
                    Notify.say(text, 6)
                end
                local function holdForDanger()
                    Danger.hold(Library, function()
                        notify('In Danger, holding the join until combat clears')
                    end)
                end
                local function returnToMenu()
                    local rtm = Remotes.requestRemote('ReturnToMenu')

                    if not rtm or not Menu.safeToMenu() then
                        return
                    end

                    pcall(function()
                        rtm:InvokeServer()
                    end)
                    task.wait(MENU_SETTLE)
                end
                local function joinPrivate(code)
                    local remote = Remotes.requestRemote('JoinPrivateServer')

                    if not remote then
                        return notify('JoinPrivateServer remote not found')
                    end

                    MemStore.set(CODE_KEY, code)
                    holdForDanger()
                    returnToMenu()
                    pcall(function()
                        remote:FireServer(code)
                    end)
                    notify('Joining private server ' .. code)
                end
                local function joinServer(jobId)
                    local remote = Remotes.requestRemote('JoinPublicServer')

                    if not remote then
                        return notify('JoinPublicServer remote not found')
                    end

                    holdForDanger()
                    returnToMenu()
                    pcall(function()
                        remote:FireServer(jobId)
                    end)
                    notify('Joining server ' .. jobId)
                end
                local function jobIdFromServerInfo(name)
                    local folder = ReplicatedStorage:FindFirstChild('ServerInfo')

                    if not folder then
                        return nil
                    end

                    local wanted = name:lower()

                    for _, server in folder:GetChildren()do
                        local list = server:FindFirstChild('Players')

                        if list and list:IsA('StringValue') then
                            local ok, decoded = pcall(function()
                                return HttpService:JSONDecode(list.Value)
                            end)

                            if ok and type(decoded) == 'table' then
                                for _, entry in decoded do
                                    local entryName = type(entry) == 'table' and (entry.Name or entry.name) or entry

                                    if type(entryName) == 'string' and entryName:lower() == wanted then
                                        return server.Name
                                    end
                                end
                            end
                        end
                    end

                    return nil
                end
                local function jobIdFromPresence(username)
                    if not ctx.State.getPresence then
                        return nil
                    end

                    local ok, userId = pcall(function()
                        return Players:GetUserIdFromNameAsync(username)
                    end)

                    if not ok or not userId then
                        return nil, 'no Roblox user called ' .. username
                    end

                    local presences = ctx.State.getPresence({userId})
                    local entry = presences and presences[userId]

                    if not entry or not entry.joinable or not entry.gameId or entry.gameId == '' then
                        return nil, username .. ' is not in a joinable game'
                    end

                    return entry.gameId
                end
                local function joinPlayer(username)
                    local jobId = jobIdFromServerInfo(username)

                    if jobId then
                        return joinServer(jobId)
                    end

                    local reason

                    jobId, reason = jobIdFromPresence(username)

                    if not jobId then
                        return notify(reason or ('could not locate ' .. username))
                    end

                    joinServer(jobId)
                end
                local function rejoin()
                    if not Menu.isPrivateServer() then
                        return joinServer(game.JobId)
                    end

                    local code = MemStore.get(CODE_KEY)

                    if not code or code == '' then
                        return notify(
[[No private server code stored, sentinel has to be running where you joined from]])
                    end

                    joinPrivate(code)
                end
                local function heal()
                    local pad = ctx.State.healPad

                    if not pad then
                        return notify('The healing pad is private server only')
                    end
                    if not pad() then
                        notify('Healing pad not reachable from here')
                    end
                end
                local function copyJobId()
                    if not setclipboard then
                        return notify("This executor can't copy to the clipboard")
                    end

                    setclipboard(game.JobId)
                    notify('Job ID copied')
                end

                local ACTIONS = {
                    private = joinPrivate,
                    server = joinServer,
                    player = joinPlayer,
                    rejoin = rejoin,
                    heal = heal,
                    jobid = copyJobId,
                }

                local function dispatch(message)
                    local words = {}

                    for word in message:gmatch('%S+')do
                        table.insert(words, word)
                    end

                    if #words < 2 or words[1]:lower() ~= PREFIX then
                        return
                    end

                    local key = ALIASES[words[2]:lower()]
                    local action = key and ACTIONS[key]

                    if not action or (NEEDS_ARG[key] and not words[3]) then
                        return
                    end

                    task.spawn(action, words[3])
                end

                local codeMaid = Maid.new()

                ctx.Maid:Give(codeMaid)

                local function watchCode(box)
                    if not (box:IsA('TextBox') and box.Name == 'Code' and box.Parent and box.Parent.Name == 'PrivateServers') then
                        return
                    end
                    if box.Text ~= '' then
                        MemStore.set(CODE_KEY, box.Text)
                    end

                    codeMaid.typed = box:GetPropertyChangedSignal('Text'):Connect(function(
                    )
                        if box.Text ~= '' then
                            MemStore.set(CODE_KEY, box.Text)
                        end
                    end)
                end

                local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                if pg then
                    for _, box in pg:GetDescendants()do
                        pcall(watchCode, box)
                    end

                    codeMaid.added = pg.DescendantAdded:Connect(function(child)
                        pcall(watchCode, child)
                    end)
                end

                ctx.State.chatCommandsStart = function()
                    maid:DoCleaning()

                    maid.chatted = LocalPlayer.Chatted:Connect(function(
                        message
                    )
                        local ok, err = pcall(dispatch, message)

                        if not ok then
                            warn('[sentinel] chat command failed: ' .. tostring(err))
                        end
                    end)
