                    for _, name in friends do
                        table.insert(lines, name .. (known[name] and ': paired' or ': has not scanned yet'))
                    end
                end
                if mine then
                    local data, err = localCommand({
                        command = 'GetToys',
                    })

                    if not data then
                        table.insert(lines, 'you: no answer from ' .. Lovense.host() .. ', is Lovense Remote open with Game Mode on (' .. (err or 'unreachable') .. ')')
                    else
                        local names = toyList(data)

                        table.insert(lines, #names > 0 and ('you: ' .. table.concat(names, ', ')) or ('you: reached ' .. Lovense.host() .. ' but no toy is paired'))
                    end
                end

                return table.concat(lines, ' | ')
            end
            function Lovense.connected()
                local friends, mine = Lovense.selected()

                if #friends > 0 then
                    return #Lovense.targets() > 0
                end
                if not mine then
                    return false
                end

                local data = localCommand({
                    command = 'GetToys',
