                local gui, label = Gui.status('MenuPanStatus', 0)

                label.TextColor3 = OUT_COLOR
                label.Text = 'Not In Menu Pan'

                local function addPoint(point)
                    if point:IsA('BasePart') then
                        table.insert(points, point)
                    end
                end
                local function watchPan(pan)
                    for _, point in pan:GetChildren()do
                        addPoint(point)
                    end

                    table.insert(conns, pan.ChildAdded:Connect(addPoint))
                end

                task.spawn(function()
                    local pans = ReplicatedStorage:FindFirstChild('MenuPans') or ReplicatedStorage:WaitForChild('MenuPans', 30)

                    if not (pans and alive) then
                        return
                    end

                    for _, pan in pans:GetChildren()do
                        watchPan(pan)
                    end

                    table.insert(conns, pans.ChildAdded:Connect(watchPan))
