                    accum += dt

                    if accum < CHECK_GAP then
                        return
                    end

                    accum = 0

                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild('HumanoidRootPart')

                    label.Visible = root ~= nil

                    if not root then
                        return
                    end
                    if filteredFor ~= char then
                        filteredFor = char

                        local markers = Workspace:FindFirstChild('AreaMarkers')

                        params.FilterDescendantsInstances = markers and {char, markers} or {char}
                    end

                    local target = root.Position
                    local seen = false

                    for _, point in points do
                        local from = point.Position
                        local toRoot = target - from

                        if toRoot.Magnitude > 0 and point.CFrame.LookVector:Dot(toRoot.Unit) >= SIGHT_DOT and not Workspace:Raycast(from, toRoot, params) then
                            seen = true

