                    if token:match('^%d+$') then
                        table.insert(parts, '<@&' .. token .. '>')
                    elseif token == '@everyone' or token == '@here' or token:match('^<@[&!]?%d+>$') then
                        table.insert(parts, token)
                    elseif token == 'everyone' or token == 'here' then
                        table.insert(parts, '@' .. token)
                    end
                end

                return table.concat(parts, ' ')
            end
            local function escapeRich(s)
                return (tostring(s):gsub('&', '&amp;'):gsub('<', '&lt;'):gsub('>', '&gt;'))
            end
            local function readServerStats()
                local name, region = '', ''
                local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                local stats = pg and pg:FindFirstChild('ServerStatsGui')

                stats = stats and stats:FindFirstChild('Frame')
                stats = stats and stats:FindFirstChild('Stats')

                if stats then
                    local sn = stats:FindFirstChild('ServerName')

                    name = sn and (sn.Text:match('Server Name: (.+)') or '') or ''

                    local sr = stats:FindFirstChild('ServerRegion')

                    region = sr and (sr.Text:match('Server Region: (.+)') or '') or ''
                end

                return name, region
            end

            local BackpackBind = (function()
                local Players, UserInputService, RunService, CollectionService, HttpService, GuiService = Services:Get('Players', 'UserInputService', 'RunService', 'CollectionService', 'HttpService', 'GuiService')
                local conns = {}
                local bindings = {}
                local hooked = setmetatable({}, {
                    __mode = 'k',
                })
                local capturing = nil
                local captureFrame = nil
                local capturePrevText = nil
                local capturePrevVisible = nil
                local running = false
                local onChange = nil
                local onReject = nil
                local RESERVED_STRINGS = {
                    ['\u{a7}'] = true,
                    ['\u{bd}'] = true,
                    ['`'] = true,
                    ['~'] = true,
                }
                local SLOT_PLACEHOLDER = '-'
                local hoveredFrame = nil
                local RESERVED_CODES = {}

                for _, name in {
                    'Tilde',
                    'Backquote',
                }do
                    local ok, code = pcall(function()
                        return Enum.KeyCode[name]
                    end)

                    if ok and code then
                        RESERVED_CODES[code] = true
                    end
                end

                local function serialize()
                    local out = {}

                    for name, keycode in bindings do
                        out[name] = keycode.Name
                    end

                    return HttpService:JSONEncode(out)
                end

                local BINDS_FILE = 'sentinel/backpackbinds.json'

                local function readAll()
                    return Json.read(BINDS_FILE) or {}
                end
                local function userKey()
                    return tostring(LocalPlayer.UserId)
                end
                local function save()
                    local data = readAll()
                    local mine, count = {}, 0

                    for name, keycode in bindings do
                        mine[name] = keycode.Name

                        count += 1
                    end

                    data[userKey()] = count > 0 and mine or nil

                    Json.write(BINDS_FILE, data)
                end
                local function load()
                    local mine = readAll()[userKey()]

                    if type(mine) ~= 'table' then
                        return false
                    end

                    table.clear(bindings)

                    for name, kn in mine do
                        local kc

                        pcall(function()
                            kc = Enum.KeyCode[kn]
                        end)

                        if kc then
                            bindings[name] = kc
                        end
                    end

                    return true
                end
                local function deserialize(str)
                    if type(str) ~= 'string' or str == '' then
                        return
                    end

                    local ok, data = pcall(function()
                        return HttpService:JSONDecode(str)
                    end)

                    if not ok or type(data) ~= 'table' then
                        return
                    end

                    table.clear(bindings)

                    for name, kn in data do
                        local kc

                        pcall(function()
                            kc = Enum.KeyCode[kn]
                        end)

                        if kc then
                            bindings[name] = kc
                        end
                    end
                end
                local function backpackGui()
                    local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                    return pg and pg:FindFirstChild('BackpackGui')
                end
                local function isToolFrame(obj)
                    return obj:IsA('GuiObject') and #obj.Name > 1 and obj:FindFirstChild('Slot') ~= nil and obj:FindFirstChild('Overlay') ~= nil
                end
                local function toolName(frame)
                    return frame.Name:sub(2)
                end
                local function keyName(keycode)
                    local ok, s = pcall(function()
                        return UserInputService:GetStringForKeyCode(keycode)
                    end)

                    if ok and s and s ~= '' then
                        return s:upper()
                    end

                    return keycode.Name
                end
                local function reserved(keycode)
                    if RESERVED_CODES[keycode] then
                        return true
                    end

                    local ok, s = pcall(function()
                        return UserInputService:GetStringForKeyCode(keycode)
                    end)

                    return ok and s ~= nil and RESERVED_STRINGS[s] == true
                end
                local function eachToolFrame(g, fn)
                    local main = g:FindFirstChild('MainFrame')
                    local bpf = g:FindFirstChild('BackpackFrame')
                    local scroll = bpf and bpf:FindFirstChild('ScrollingFrame')

                    for _, container in {main, scroll, g}do
                        if container then
                            for _, child in container:GetChildren()do
                                if isToolFrame(child) then
                                    fn(child)
                                end
                            end
                        end
                    end
                end
                local function hotbarHolder(g, key)
                    local main = g and g:FindFirstChild('MainFrame')

                    if not main then
                        return nil
                    end

                    for _, child in main:GetChildren()do
                        if child ~= captureFrame and isToolFrame(child) then
                            local slot = child:FindFirstChild('Slot')
                            local text = slot and slot.Text

                            if type(text) == 'string' and text ~= '' and text:upper() == key then
                                return toolName(child)
                            end
                        end
                    end

                    return nil
                end
                local function toggleTool(name)
                    local char = LocalPlayer.Character

                    if not char or CollectionService:HasTag(char, 'NoEquip') then
                        return
                    end

                    local humanoid = char:FindFirstChildOfClass('Humanoid')

                    if not humanoid then
                        return
                    end
                    if char:FindFirstChild(name) then
                        humanoid:UnequipTools()
                    else
                        local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
                        local tool = backpack and backpack:FindFirstChild(name)

                        if tool then
                            humanoid:EquipTool(tool)
                        end
                    end
                end
                local function within(point, obj)
                    local at, size = obj.AbsolutePosition, obj.AbsoluteSize

                    return point.X >= at.X and point.X <= at.X + size.X and point.Y >= at.Y and point.Y <= at.Y + size.Y
                end
                local function overSlot(input, frame, slot)
                    if not slot then
                        return false
                    end

                    local raw = Vector2.new(input.Position.X, input.Position.Y)

                    for _, point in {
                        raw - GuiService:GetGuiInset(),
                        raw,
                    }do
                        if within(point, frame) then
                            return within(point, slot)
                        end
                    end

                    return true
                end
                local function hookFrame(frame)
                    if hooked[frame] or not isToolFrame(frame) then
                        return
                    end

                    hooked[frame] = true

                    table.insert(conns, frame.MouseEnter:Connect(function()
                        hoveredFrame = frame
                    end))
                    table.insert(conns, frame.MouseLeave:Connect(function()
                        if hoveredFrame == frame then
                            hoveredFrame = nil
                        end
                    end))
                    table.insert(conns, frame.InputBegan:Connect(function(
                        input
                    )
                        if not (running and input.UserInputType == Enum.UserInputType.MouseButton2) then
                            return
                        end

                        local slot = frame:FindFirstChild('Slot')

                        if not overSlot(input, frame, slot) then
                            return
                        end

                        capturing = toolName(frame)
                        captureFrame = frame

                        if slot then
                            capturePrevText = slot.Text
                            capturePrevVisible = slot.Visible
                            slot.Text = '<...>'
                            slot.Visible = true
                        end
                    end))
                end
                local function start()
                    if running then
                        return
                    end

                    running = true

                    local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                    local g = backpackGui()

                    if g then
                        eachToolFrame(g, hookFrame)
                    end
                    if pg then
                        table.insert(conns, pg.DescendantAdded:Connect(hookFrame))
                    end

                    table.insert(conns, UserInputService.InputBegan:Connect(function(
                        input
                    )
                        if capturing then
                            if input.UserInputType == Enum.UserInputType.Keyboard then
                                local refusal

                                if input.KeyCode ~= Enum.KeyCode.Escape then
                                    local pressed = keyName(input.KeyCode)

                                    if reserved(input.KeyCode) then
                                        refusal = pressed .. ' opens your inventory - bind cancelled'
                                    else
                                        local taken = hotbarHolder(backpackGui(), pressed)

                                        refusal = taken and (pressed .. ' is already ' .. taken .. "'s hotbar slot - bind cancelled")
                                    end
                                end
                                if refusal then
                                    if onReject then
                                        onReject(refusal)
                                    end
                                elseif input.KeyCode == Enum.KeyCode.Escape then
                                    bindings[capturing] = nil
                                elseif keyName(input.KeyCode) ~= capturePrevText then
                                    for n, k in bindings do
                                        if k == input.KeyCode then
                                            bindings[n] = nil
                                        end
                                    end

                                    bindings[capturing] = input.KeyCode
                                end
                                if captureFrame then
                                    local slot = captureFrame:FindFirstChild('Slot')

                                    if slot and capturePrevText ~= nil then
                                        slot.Text = capturePrevText
                                        slot.Visible = capturePrevVisible
                                    end
                                end

                                capturing = nil
                                captureFrame = nil

                                if onChange then
                                    onChange()
                                end
                            end

                            return
                        end
                        if UserInputService:GetFocusedTextBox() then
                            return
                        end

                        for name, keycode in bindings do
                            if input.KeyCode == keycode then
                                toggleTool(name)

                                break
                            end
                        end
                    end))
                    table.insert(conns, RunService.RenderStepped:Connect(BASIL_NO_VIRTUALIZE(function(
                    )
                        local bg = backpackGui()

                        if not bg then
                            return
                        end

                        eachToolFrame(bg, function(frame)
                            local slot = frame:FindFirstChild('Slot')

                            if not slot then
                                return
                            end

                            local n = toolName(frame)
                            local inScroll = frame.Parent and frame.Parent.Name == 'ScrollingFrame'

                            if n == capturing then
                                slot.Text = '<...>'
                                slot.Visible = true
                            elseif inScroll and bindings[n] then
                                slot.Text = keyName(bindings[n])
                                slot.Visible = true
                            elseif inScroll and frame == hoveredFrame then
                                slot.Text = SLOT_PLACEHOLDER
                                slot.Visible = true
                            elseif inScroll then
                                slot.Visible = false
                            end
                        end)
                    end)))
                end
                local function stop()
                    running = false
                    capturing = nil
                    hoveredFrame = nil

                    for _, c in conns do
                        pcall(function()
                            c:Disconnect()
                        end)
                    end

                    table.clear(conns)
                    table.clear(hooked)

                    local g = backpackGui()

                    if g then
                        eachToolFrame(g, function(frame)
                            if frame.Parent and frame.Parent.Name == 'ScrollingFrame' then
                                local slot = frame:FindFirstChild('Slot')

                                if slot then
                                    slot.Visible = false
                                end
                            end
                        end)
                    end
                end

                return {
                    start = start,
                    stop = stop,
                    save = save,
                    load = load,
                    setOnReject = function(fn)
                        onReject = fn
                    end,
                    serialize = serialize,
                    deserialize = deserialize,
                    setOnChange = function(fn)
                        onChange = fn
                    end,
                }
            end)()

            return function(ctx)
                local Library, SaveManager, ThemeManager = ctx.Library, ctx.SaveManager, ctx.ThemeManager
                local Settings = ctx.Tabs.Settings
                local blatantFeatures = (ctx.State and ctx.State.blatant) or {}
                local riskyFeatures = (ctx.State and ctx.State.risky) or {}

                local function applyGate(features, on)
                    for _, key in features do
                        local toggle = Library.Toggles[key]

                        if toggle then
                            if on then
                                toggle:SetDisabled(false)
                            else
                                if toggle.Value then
                                    toggle:SetValue(false)
                                end

                                toggle:SetDisabled(true)
                            end
                        end
                    end
                end
                local function applyBlatant(on)
                    applyGate(blatantFeatures, on)
                end
                local function applyRisky(on)
                    applyGate(riskyFeatures, on)
                end

                do
                    local AvoidBox = Settings:AddRightGroupbox('Avoid List')

                    local function refreshAvoided()
                        Library.Options.AvoidList:SetValues(AvoidList.names())
                        Library.Options.AvoidList:SetValue(nil)
                    end

                    AvoidBox:AddDropdown('AvoidList', {
                        Text = 'Avoided',
                        Values = AvoidList.names(),
                        AllowNull = true,
                    })
                    AvoidBox:AddInput('AvoidName', {
                        Text = 'Username',
                        Placeholder = 'username',
                    })
                    AvoidBox:AddButton('Add', function()
                        local text = (Library.Options.AvoidName.Value or ''):match('^%s*(.-)%s*$')

                        if text == '' then
                            return
                        end

                        local id, name = AvoidList.resolve(text)

                        if not id then
                            Notify.say('No Roblox user named ' .. text)

                            return
                        end
                        if id == Services.Players.LocalPlayer.UserId then
                            Notify.say("You can't avoid yourself")

                            return
                        end

                        AvoidList.add(id, name)
                        Library.Options.AvoidName:SetValue('')
                        refreshAvoided()
                        Notify.say('Avoiding ' .. name)

                        local here = Services.Players:GetPlayerByUserId(id)

                        if here and ctx.State.alertModerator then
                            ctx.State.alertModerator(here)
                        end
                    end):AddButton('Remove', function()
                        local name = Library.Options.AvoidList.Value

                        if not name then
                            Notify.say('Pick someone to remove first')

                            return
                        end

                        AvoidList.remove(name)
                        refreshAvoided()
                        Notify.say('No longer avoiding ' .. name)
                    end)
                end

                local box = Settings:AddLeftGroupbox('Menu')

                box:AddLabel('Modes')
                box:AddToggle('BlatantMode', {
                    Text = 'Blatant Mode',
                    Default = false,
                    Callback = function(on)
                        applyBlatant(on)
                        MemStore.set('blatant', on and 'true' or 'false')
                    end,
                })

                local nsfwControls = {}

                local function applyNsfw(on)
                    for _, entry in nsfwControls do
                        local control = type(entry) == 'string' and (Library.Toggles[entry] or Library.Options[entry]) or entry

                        if control then
                            if control.SetVisible then
                                control:SetVisible(on)
                            end
                            if control.SetDisabled then
                                if not on and control.Value == true then
                                    control:SetValue(false)
                                end

                                control:SetDisabled(not on)
                            end
                        end
                    end
                end

                ctx.State.registerNsfw = function(entry)
                    table.insert(nsfwControls, entry)
                    applyNsfw(Library.Toggles.NsfwMode and Library.Toggles.NsfwMode.Value or false)
                end

                box:AddToggle('NsfwMode', {
                    Text = 'NSFW Mode',
                    Default = false,
                    Tooltip = 'Unlocks the toy alert',
                    Callback = applyNsfw,
                })

                local riskyToggle = box:AddToggle('RiskyMode', {
                    Text = 'Risky Mode',
                    Default = false,
                    Callback = applyRisky,
                })

                riskyToggle:SetTextColorKey('Orange')
                box:AddDivider()
                box:AddLabel('Interface')
                box:AddToggle('ShowKeybinds', {
                    Text = 'Show Keybinds UI',
