                    local HttpService = Services.HttpService
                    local ReplicatedStorage = Services.ReplicatedStorage

                    local function getServerInfoData()
                        local jobIdToServerName, jobIdToPlayers = {}, {}
                        local serverInfo = ReplicatedStorage:FindFirstChild('ServerInfo')

                        if serverInfo then
                            for _, folder in serverInfo:GetChildren()do
                                if folder:IsA('Folder') then
                                    local jobId = folder.Name:lower()
                                    local nameVal = folder:FindFirstChild('ServerName')

                                    if nameVal and nameVal:IsA('StringValue') then
                                        jobIdToServerName[jobId] = nameVal.Value
                                    end

                                    local playersVal = folder:FindFirstChild('Players')

                                    if playersVal and playersVal:IsA('StringValue') then
                                        local ok, data = pcall(function()
                                            return HttpService:JSONDecode(playersVal.Value)
                                        end)

                                        if ok and type(data) == 'table' then
                                            jobIdToPlayers[jobId] = data
                                        end
                                    end
                                end
                            end
                        end

                        return jobIdToServerName, jobIdToPlayers
                    end
                    local function randName()
                        local pool = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
                        local t = {}

                        for i = 1, 12 do
                            local n = math.random(1, #pool)

                            t[i] = pool:sub(n, n)
                        end

                        return table.concat(t)
                    end

                    local uiNames = {
