                                Parent = btn,
                            })

                            btn.MouseButton1Click:Connect(onClick)

                            return btn
                        end

                        serverMaid.rejoin = menuButton(uiNames.rejoin, 'Rejoin', sorts, UDim2.new(0, 370, 0, 5), 70, 3, function(
                        )
                            pcall(function()
                                local r = Remotes.requestRemote('JoinPublicServer')

                                if r then
                                    r:FireServer(game.JobId)
                                end
                            end)
                        end)
                        serverMaid.serverhop = menuButton(uiNames.serverhop, 'Serverhop', sorts, UDim2.new(0, 445, 0, 5), 90, 3, function(
                        )
                            task.spawn(function()
                                pcall(Serverhop.hop, {
                                    strategy = 'random',
                                    block = true,
                                    minPlayers = 0,
                                })
                            end)
                        end)
                        serverMaid.enter = search.FocusLost:Connect(function(
                            enterPressed
                        )
                            if not enterPressed then
                                return
                            end

                            local jobId = search.Text:match('^%s*(.-)%s*$')

                            if not jobId:match('^%w+%-%w+%-%w+%-%w+%-%w+$') then
                                return
                            end

                            pcall(function()
                                local r = Remotes.requestRemote('JoinPublicServer')

                                if r then
                                    r:FireServer(jobId)
                                end
                            end)
                        end)
                        serverMaid.copyjob = menuButton(uiNames.copyjob, 'Copy JobId', publicServers, UDim2.new(0, 12, 1, 14), 90, 6, function(
                        )
                            local copy = setclipboard or toclipboard or set_clipboard

                            if copy then
                                pcall(copy, tostring(game.JobId))
                                Notify.say('Copied JobId')
                            end
                        end)

                        local function joinBySize(strategy)
                            if joining then
                                return
                            end

                            joining = true

                            task.spawn(function()
                                local ok, _, why = false, nil, nil

                                pcall(function()
                                    ok, _, why = Serverhop.hop({
                                        strategy = strategy,
                                        minPlayers = 0,
                                        ignoreVisited = true,
                                    })
                                end)

                                if not ok then
                                    Notify.say('Could not join a server: ' .. tostring(why or 'no joinable server'))
                                end

                                joining = false
                            end)
                        end

                        serverMaid.largest = menuButton(uiNames.largest, 'Join Largest Server', publicServers, UDim2.new(0, 110, 1, 14), 125, 6, function(
                        )
                            joinBySize('largest')
                        end)
                        serverMaid.smallest = menuButton(uiNames.smallest, 'Join Smallest Server', publicServers, UDim2.new(0, 243, 1, 14), 130, 6, function(
                        )
                            joinBySize('smallest')
                        end)
                        serverMaid.filter = search:GetPropertyChangedSignal('Text'):Connect(function(
                        )
                            local text = search.Text:match('^%s*(.-)%s*$'):lower()
                            local scrollingFrame = publicServers:FindFirstChild('ScrollingFrame')

                            if not scrollingFrame then
                                return
                            end
                            if text == '' then
                                for _, server in scrollingFrame:GetChildren()do
                                    if server:IsA('Frame') then
                                        server.Visible = true
                                    end
                                end

                                return
                            end

                            local jobIdToServerName, jobIdToPlayers = getServerInfoData()
                            local targetServerName = jobIdToServerName[text]

                            for _, server in scrollingFrame:GetChildren()do
                                if server:IsA('Frame') then
                                    local nameObj = server:FindFirstChild('ServerName')
                                    local regionObj = server:FindFirstChild('ServerRegion')

                                    if nameObj and regionObj then
                                        local matches = false

                                        if targetServerName and nameObj.Text == targetServerName then
                                            matches = true
                                        elseif server.Name:lower():find(text, 1, true) then
                                            matches = true
                                        elseif regionObj.Text:lower():find(text, 1, true) then
                                            matches = true
                                        else
                                            for jobId, serverName in jobIdToServerName do
                                                if jobId:find(text, 1, true) and nameObj.Text == serverName then
                                                    matches = true

                                                    break
                                                end
                                            end

                                            if not matches then
                                                for jobId, players in jobIdToPlayers do
                                                    if jobIdToServerName[jobId] == nameObj.Text then
                                                        for _, info in players do
                                                            if info.Name and info.Name:lower():find(text, 1, true) then
                                                                matches = true

                                                                break
                                                            end
                                                        end
                                                    end
                                                    if matches then
                                                        break
                                                    end
                                                end
                                            end
                                        end

                                        server.Visible = matches
                                    end
                                end
                            end
                        end)
                    end

                    local hideOverlayUntil = 0

                    local function hideTeleportOverlay(child)
                        if child.Name ~= 'TeleportGui' then
                            return
                        end

                        pcall(function()
                            child.Enabled = false
                        end)
                    end
                    local function armTeleportOverlay()
                        hideOverlayUntil = tick() + TELEPORT_OVERLAY_WINDOW

                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                        for _, child in (pg and pg:GetChildren()) or {}do
                            hideTeleportOverlay(child)
                        end
                    end

                    box:AddToggle('ServerSearch', {
                        Text = 'Better Menu',
                        Tooltip = 'Search, rejoin and hop on the server list',
                        Default = false,
                        Callback = function(on)
                            if not on then
                                serverMaid:DoCleaning()

                                return
                            end

                            task.delay(0.5, createBetterMenu)

                            local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                            if pg then
                                serverMaid.guiAdded = pg.ChildAdded:Connect(function(
                                    child
                                )
                                    if child.Name == 'StartMenu' and Library.Toggles.ServerSearch.Value then
                                        task.wait(0.5)
                                        createBetterMenu()
                                    end
                                end)
                            end
                        end,
                    })
                    box:AddToggle('HideTeleportGui', {
                        Text = 'Hide Teleport Overlay',
                        Default = false,
                        Callback = function(on)
                            if not on then
                                overlayMaid:DoCleaning()

                                hideOverlayUntil = 0

                                return
                            end

                            local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')

                            if not pg then
                                return
                            end

                            overlayMaid.guiAdded = pg.ChildAdded:Connect(function(
                                child
                            )
                                if tick() < hideOverlayUntil then
                                    hideTeleportOverlay(child)
                                end
                            end)
                            overlayMaid.removing = LocalPlayer.CharacterRemoving:Connect(armTeleportOverlay)
                            overlayMaid.nilled = LocalPlayer:GetPropertyChangedSignal('Character'):Connect(function(
                            )
                                if not LocalPlayer.Character then
                                    armTeleportOverlay()
                                end
                            end)
                        end,
                    })
                    box:AddToggle('ChatCommands', {
                        Text = 'Chat Commands',
                        Tooltip = '/e join commands, list goes to console',
                        Default = true,
                        Callback = function(on)
                            if on and ctx.State.chatCommandsStart then
                                ctx.State.chatCommandsStart()
                            elseif not on and ctx.State.chatCommandsStop then
                                ctx.State.chatCommandsStop()
                            end
                        end,
                    })

                    if Library.Toggles.ChatCommands.Value and ctx.State.chatCommandsStart then
                        ctx.State.chatCommandsStart()
                    end

                    box:AddToggle('BindBackpackTools', {
                        Text = 'Bind Backpack Tools',
                        Tooltip = 'Right click a tool, then press a key',
                        Default = false,
                        Callback = function(on)
                            if on then
                                BackpackBind.start()
                            else
                                BackpackBind.stop()
                            end

                            MemStore.set('bind_backpack_tools', on and 'true' or 'false')
                        end,
                    })
                    BackpackBind.setOnReject(function(reason)
                        Notify.say(reason, 5)
                    end)
                    BackpackBind.setOnChange(function()
                        BackpackBind.save()
                        MemStore.set('backpack_binds', BackpackBind.serialize())
                    end)

                    if not BackpackBind.load() then
                        local memBinds = MemStore.get('backpack_binds')

                        if memBinds then
                            BackpackBind.deserialize(memBinds)
                            BackpackBind.save()
                        end
                    end

                    ctx.Maid:Give(BackpackBind.stop)
                    box:AddDivider()
                    box:AddLabel('Status')

                    local panMaid = Maid.new()

                    ctx.Maid:Give(panMaid)
                    box:AddToggle('MenuPanStatus', {
                        Text = 'Menu Pan Status',
                        Tooltip = 'Red when a menu camera can see you',
                        Default = false,
                        Callback = function(on)
                            panMaid:DoCleaning()

                            if on then
                                panMaid:Give(MenuPan.watch())
                            end
                        end,
                    })

                    local observeMaid = Maid.new()

                    ctx.Maid:Give(observeMaid)
                    box:AddToggle('ObservingStatus', {
                        Text = 'Show Observing Status',
                        Tooltip = 'Red when an illusionist is observing',
                        Default = false,
                        Callback = function(on)
                            observeMaid:DoCleaning()

                            if on then
                                observeMaid:Give(Observers.watch(ctx.State.maskUser))
                            end
                        end,
                    })
                    box:AddSlider('StatusTextSize', {
                        Text = 'Status Text Size',
                        Default = 28,
                        Min = 16,
                        Max = 48,
                        Rounding = 0,
                        Callback = Gui.setStatusSize,
                    })
                    box:AddDivider()
                    box:AddLabel('Bots')
                    box:AddToggle('IgnoreDanger', {
                        Text = 'Ignore Danger',
                        Tooltip = 'Lets you hop mid fight',
                        Default = false,
                    })
                    box:AddToggle('AvoidOtherBots', {
                        Text = 'Avoid My Other Bots',
                        Tooltip = 'Stays out of servers your other accounts are botting in',
                        Default = true,
                    })
                end

                box:AddDivider()
                box:AddLabel('Session')
                box:AddToggle('PersistentConfigs', {
                    Text = 'Persistent Configs',
                    Tooltip = 'Keeps your config after a hop',
                    Default = true,
                    Callback = function(on)
                        if not on then
                            MemStore.remove('loaded_config')
                        end
                    end,
                })
                Serverhop.setupResume()
                ctx.Maid:Give(Serverhop.teardown)
                box:AddToggle('ExecuteOnServerhop', {
                    Text = 'Execute on Serverhop',
                    Tooltip = 'Reruns sentinel after a hop',
                    Default = false,
                    Callback = function(on)
                        MemStore.set('execute_on_serverhop', on and 'true' or 'false')

                        if on then
                            Serverhop.setupResume()
                        end
                    end,
                })
                box:AddToggle('QuietConsole', {
                    Text = 'Quiet Console',
                    Tooltip = "Stops sentinel's info prints",
                    Default = Console.quiet(),
                    Callback = Console.setQuiet,
                })
                box:AddDivider()
                box:AddLabel('Keys')

                local function savedKeybinds()
                    return Json.read(Paths.KEYBINDS) or {}
                end
                local function rememberKeybind(name, value)
                    Json.update(Paths.KEYBINDS, function(all)
                        all[name] = value
                    end)
                end

                box:AddLabel('Menu Keybind'):AddKeyPicker('MenuKeybind', {
                    Default = 'RightControl',
                    Text = 'Menu',
                    ChangedCallback = function(value, bind)
                        Library.ToggleKeybind = bind

                        rememberKeybind('MenuKeybind', value)
                    end,
                })

                ctx.State.restoreMenuKeybind = function()
                    local stored = savedKeybinds().MenuKeybind

                    if type(stored) == 'string' and stored ~= '' and Library.Options.MenuKeybind then
                        Library.Options.MenuKeybind:SetValue(stored)
                    end
                end

                ctx.State.restoreMenuKeybind()
                box:AddLabel('Unload Keybind'):AddKeyPicker('UnloadKeybind', {
                    Default = 'End',
                    Mode = 'Toggle',
                    Text = 'Unload',
                    Callback = function()
                        Library:Unload()
                    end,
                })
                box:AddButton({
                    Text = 'Unload',
                    Func = function()
                        Library:Unload()
                    end,
                })

                do
                    local Players = Services.Players
                    local notifMaid = Maid.new()

                    ctx.Maid:Give(notifMaid)

                    local function notificationsOn()
                        if not ctx.State.notificationsReady then
                            return false
                        end

                        local master = Library.Toggles.Notifications

                        return not master or master.Value
                    end

                    local originalNotify = Library.Notify

                    Library.Notify = function(self, ...)
                        if not notificationsOn() then
                            return
                        end

                        return originalNotify(self, ...)
                    end

                    ctx.Maid:Give(function()
                        Library.Notify = originalNotify
                    end)
                    Audio.prewarm({1693890393, 2865227039, 6432593850})

                    local function alertSound(id, volume, removal)
                        if not notificationsOn() then
                            return
                        end

                        Audio.play(id, volume, removal)
                    end
                    local function detectedName(player)
                        local rogue = ctx.State.getRogueName and ctx.State.getRogueName(player)

                        rogue = (ctx.State.maskRogue and ctx.State.maskRogue(player, rogue)) or rogue

                        local user = (ctx.State.maskUser and ctx.State.maskUser(player)) or player.Name

                        return '<b>' .. escapeRich(rogue or 'nil') .. '</b> [' .. escapeRich(user) .. ']'
                    end

                    local notifiedMods, notifiedIllu, checkingMod = {}, {}, {}

                    local function checkMod(player)
                        if player == LocalPlayer or notifiedMods[player.UserId] or checkingMod[player.UserId] then
                            return
                        end
                        if not notificationsOn() then
                            return
                        end

                        checkingMod[player.UserId] = true

                        local info = ctx.State.moderatorInfo and ctx.State.moderatorInfo(player)

                        checkingMod[player.UserId] = nil

                        if info and not notifiedMods[player.UserId] then
                            notifiedMods[player.UserId] = true

                            if ctx.State.toyAlert then
                                ctx.State.toyAlert('Moderator Detected')
                            end

                            alertSound('rbxassetid://1693890393', 4, 4)
                            Library:Notify({
                                Title = AvoidList.has(player) and '\u{1f6d1} AVOIDED PLAYER' or '\u{1f6d1} MODERATOR DETECTED',
                                Description = detectedName(player) .. ' ' .. info,
                                Time = 25,
                                RichText = true,
                            })
                        end
                    end
                    local function hasObserve(player)
                        local bp = player:FindFirstChildOfClass('Backpack')

                        if bp and bp:FindFirstChild('Observe') then
                            return true
                        end

                        local char = player.Character

                        return char ~= nil and char:FindFirstChild('Observe') ~= nil
                    end
                    local function checkIllu(player)
                        if player == LocalPlayer or notifiedIllu[player.UserId] then
                            return
                        end
                        if not notificationsOn() then
                            return
                        end
                        if hasObserve(player) then
                            notifiedIllu[player.UserId] = true

                            alertSound('rbxassetid://2865227039', 4, 2)
                            Library:Notify({
                                Title = '\u{26a0}\u{fe0f} ILLUSIONIST DETECTED',
                                Description = detectedName(player) .. ' is an illusionist',
                                Time = 10,
                                RichText = true,
                            })
                        end
                    end

                    local validNames, lichNames, namesLoaded = {}, {}, false

                    task.spawn(function()
                        pcall(function()
                            local rs = Services.ReplicatedStorage
                            local gen = rs and rs:FindFirstChild('Info')

                            gen = gen and gen:FindFirstChild('NameGenerator')

                            if not gen then
                                return
                            end

                            for _, moduleName in {
                                'Azael',
                                'Cameo',
                                'Kasparan',
                                'Feminine',
                                'LesserNavaran',
                                'Lich',
                                'Masculine',
                                'Navaran',
                                'Scroom',
                                'Vind',
                            }do
                                local mod = gen:FindFirstChild(moduleName)

                                if mod then
                                    local ok, names = pcall(gameRequire, mod)

                                    if ok and type(names) == 'table' then
                                        for _, n in names do
                                            validNames[n] = true

                                            if moduleName == 'Lich' then
                                                lichNames[n] = true
                                            end
                                        end
                                    end
                                end
                            end

                            namesLoaded = true
                        end)
                    end)

                    local SPEC_SKILLS = {}

                    for _, n in {
                        'Eyes of Justice',
                        "Justinian's Helm",
                        'Speech',
                        'Undying Justinian',
                        'Handgun',
                        'StaticField',
                        'Chain Lightning',
                        'Overgrowth',
                        'Scroomflora',
                        'Mind Read',
                        'Domination Rune',
                        'Bestowal',
                        'Domination',
                        'Despair',
                        'Better Manus Dei',
                        'Better Mori',
                        'Maledicta Terra',
                        'Terrible Scream',
                        'FrostAura',
                        'Ray of Frost',
                        'Aculeor',
                        'Infettare',
                        "Sylvester's Cloak",
                        "Jester's Trick",
                        'Quick Stop',
                        'Abyssbypass',
                        'VeryCoolBard',
                        'Snowball',
                        'Time Halt',
                        'Time Erase',
                        "Jester's Ruse",
                        "Jester's Scheme",
                        'Wallet Swipe',
                        'Epitaph',
                        'Pondus',
                        'Darkness',
                    }do
                        SPEC_SKILLS[n] = true
                    end

                    local notifiedName, notifiedSpec = {}, {}

                    local function checkName(player)
                        if player == LocalPlayer or notifiedName[player.UserId] or not notificationsOn() then
                            return
                        end

                        local first = ctx.State.getFirstName and ctx.State.getFirstName(player)

                        if not first or first == '' or first == 'nil' or first == 'Faceless One' or first == 'Fungless One' then
                            return
                        end
                        if lichNames[first] then
                            notifiedName[player.UserId] = true

                            if ctx.State.flagModerator then
                                ctx.State.flagModerator(player, 'has Lich name [' .. first .. ']')
                            end
                            if ctx.State.toyAlert then
                                ctx.State.toyAlert('Moderator Detected')
                            end

                            alertSound('rbxassetid://1693890393', 4, 4)
                            Library:Notify({
                                Title = '\u{1f6d1} MODERATOR DETECTED',
                                Description = detectedName(player) .. ' has Lich name [' .. escapeRich(first) .. ']',
                                Time = 25,
                                RichText = true,
                            })
                        elseif namesLoaded and not SKIP_SPECIAL_NAMES and not validNames[first] then
                            notifiedName[player.UserId] = true

                            alertSound('rbxassetid://2865227039', 4, 2)
                            Library:Notify({
                                Title = '\u{26a0}\u{fe0f} WARNING',
                                Description = detectedName(player) .. " has a special name '" .. escapeRich(first) .. "'",
                                Time = 25,
                                RichText = true,
                            })
                        end
                    end
                    local function checkSpecs(player)
                        if player == LocalPlayer or notifiedSpec[player.UserId] or not notificationsOn() then
                            return
                        end

                        local bp = player:FindFirstChildOfClass('Backpack')

                        if not bp then
                            return
                        end

                        notifiedSpec[player.UserId] = true

                        local isDruid = bp:FindFirstChild('ScroomSpeech') or bp:FindFirstChild('Life Sense') or bp:FindFirstChild('Fons Vitae')

                        if bp:FindFirstChild('Verdien') and not isDruid then
                            alertSound('rbxassetid://2865227039', 4, 2)
                            Library:Notify({
                                Title = '\u{26a0}\u{fe0f} WARNING',
                                Description = detectedName(player) .. ' has Verdien but is not a druid',
                                Time = 25,
                                RichText = true,
                            })

                            return
                        end

                        local flower, mushroom = bp:FindFirstChild('Flying Flower God'), bp:FindFirstChild('Flying Mushroom God')

                        if flower or mushroom then
                            alertSound('rbxassetid://2865227039', 4, 2)
                            Library:Notify({
                                Title = '\u{26a0}\u{fe0f} WARNING',
                                Description = detectedName(player) .. ' can teleport to you with ' .. (flower and 'Flying Flower God' or 'Flying Mushroom God'),
                                Time = 25,
                                RichText = true,
                            })
                        end

                        local found = {}

                        for _, item in bp:GetChildren()do
                            if SPEC_SKILLS[item.Name] then
                                table.insert(found, item.Name)
                            end
                        end

                        if #found > 0 then
                            alertSound('rbxassetid://2865227039', 4, 2)
                            Library:Notify({
                                Title = '\u{26a0}\u{fe0f} WARNING',
                                Description = detectedName(player) .. ' has spec skills: ' .. table.concat(found, ', '),
                                Time = 25,
                                RichText = true,
                            })
                        end
                    end

                    local lastArtifactNotify = {}

                    local function notifyArtifact(player, name)
                        if player == LocalPlayer or not notificationsOn() then
                            return
                        end

                        local seen = lastArtifactNotify[player.UserId]

                        if not seen then
                            seen = {}
                            lastArtifactNotify[player.UserId] = seen
                        end

                        local now = tick()

                        if seen[name] and now - seen[name] < 1.26 then
                            return
                        end

                        seen[name] = now

                        Library:Notify({
                            Title = '\u{1f48e} ARTIFACT',
                            Description = detectedName(player) .. ' has a ' .. name,
                            Time = 8,
                            RichText = true,
                        })
                    end
                    local function checkArtifacts(player)
                        local artifacts = ctx.State.artifacts
                        local bp = player:FindFirstChildOfClass('Backpack')

                        if not artifacts or not bp then
                            return
                        end

                        for _, item in bp:GetChildren()do
                            if artifacts[item.Name] then
                                notifyArtifact(player, item.Name)
                            end
                        end
                    end
                    local function watchBackpack(player)
                        local bp = player:FindFirstChildOfClass('Backpack')

                        if not bp then
                            return
                        end

                        notifMaid['bp_' .. player.UserId] = bp.ChildAdded:Connect(function(
                            child
                        )
                            if child.Name == 'Observe' then
                                checkIllu(player)
                            elseif ctx.State.artifacts and ctx.State.artifacts[child.Name] then
                                notifyArtifact(player, child.Name)
                            end
                        end)
                    end
                    local function setupPlayer(player)
                        if player == LocalPlayer then
                            return
                        end

                        task.spawn(checkMod, player)
                        task.spawn(function()
                            if not player:FindFirstChildOfClass('Backpack') then
                                player:WaitForChild('Backpack', 10)
                            end

                            checkIllu(player)
                            checkArtifacts(player)
                            watchBackpack(player)
                            task.wait(1)
                            checkMod(player)
                            checkName(player)
                            checkSpecs(player)
                        end)

                        notifMaid['char_' .. player.UserId] = player.CharacterAdded:Connect(function(
                        )
                            notifiedIllu[player.UserId] = nil
                            notifiedName[player.UserId] = nil
                            notifiedSpec[player.UserId] = nil

                            task.wait(1)
                            checkIllu(player)
                            checkArtifacts(player)
                            watchBackpack(player)
                            checkName(player)
                            checkSpecs(player)
                        end)
                    end

                    for _, player in Players:GetPlayers()do
                        setupPlayer(player)
                    end

                    local function rescanMods()
                        for _, player in Players:GetPlayers()do
                            checkMod(player)
                        end
                    end

                    ctx.State.onModeratorsLoaded = rescanMods

                    if ctx.State.moderatorsLoaded then
                        rescanMods()
                    end

                    local function scanPresent()
                        for _, player in Players:GetPlayers()do
                            if player ~= LocalPlayer then
                                task.spawn(function()
                                    checkMod(player)
                                    checkIllu(player)
                                    checkArtifacts(player)
                                    checkName(player)
                                    checkSpecs(player)
                                end)
                            end
                        end
                    end

                    ctx.State.onNotificationsReady = scanPresent

                    if ctx.State.notificationsReady then
                        scanPresent()
                    end

                    notifMaid:Give(Players.PlayerAdded:Connect(setupPlayer))
                    notifMaid:Give(Players.PlayerRemoving:Connect(function(
                        player
                    )
                        notifMaid['bp_' .. player.UserId] = nil
                        notifMaid['char_' .. player.UserId] = nil
                        notifiedMods[player.UserId] = nil
                        checkingMod[player.UserId] = nil
                        notifiedIllu[player.UserId] = nil
                        notifiedName[player.UserId] = nil
                        notifiedSpec[player.UserId] = nil
                        lastArtifactNotify[player.UserId] = nil
                    end))

                    do
                        local Workspace = Services.Workspace
                        local batch, batchTimer = {}, nil

                        notifMaid:Give(Workspace.ChildAdded:Connect(function(
                            object
                        )
                            if object.Name ~= 'Part' or not object:FindFirstChild('ID') then
                                return
                            end

                            local identify = ctx.State.identifyTrinket

                            if not identify then
                                return
                            end

                            local name, _, zindex = identify(object)

                            if zindex ~= 5 and zindex ~= 6 then
                                return
                            end
                            if not batchTimer then
                                alertSound('rbxassetid://6432593850', 5, 2)
                            else
                                task.cancel(batchTimer)
                            end

                            table.insert(batch, {
                                name = name,
                                object = object,
                            })

                            batchTimer = task.delay(0.25, function()
                                batchTimer = nil

                                local names, ids, positions, first = {}, {}, {}, nil

                                for _, a in batch do
                                    if a.object and a.object.Parent then
                                        table.insert(names, a.name)

                                        local idVal = a.object:FindFirstChild('ID')

                                        table.insert(ids, idVal and idVal.Value or '')

                                        local ok, pos = pcall(function()
                                            return a.object.Position
                                        end)

                                        table.insert(positions, ok and {
                                            math.floor(pos.X),
                                            math.floor(pos.Y),
                                            math.floor(pos.Z),
                                        } or {})

                                        first = first or a.object
                                    end
                                end

                                batch = {}

                                if #names == 0 then
                                    return
                                end

                                local pings = {}

                                for _, found in names do
                                    local opt = Library.Options[artifactPingId(found)]
                                    local who = opt and mention(opt.Value) or ''

                                    if who ~= '' and not table.find(pings, who) then
                                        table.insert(pings, who)
                                    end
                                end

                                local area = first and ctx.State.trinketArea and ctx.State.trinketArea(first)
                                local areaText = (area and area ~= 'None') and (' (' .. area .. ')') or ''
                                local artifactList = table.concat(names, ', ')

                                Library:Notify(string.format('\u{2728} Artifact%s Spawned: %s%s', #names > 1 and 's' or '', artifactList, areaText), 10)

                                if ctx.State.toyAlert and #pings > 0 then
                                    ctx.State.toyAlert('Pinged Artifact')
                                end

                                local botting = ctx.State.trinketBot ~= nil and ctx.State.trinketBot.path_running == true

                                if botting and Webhook.available() then
                                    task.spawn(function()
                                        task.wait()

                                        local playerCount = #Services.Players:GetPlayers()
                                        local footer = Webhook.config.showUsername and string.format('Players: %d/23 | %s | Job: %s', playerCount, LocalPlayer.Name, game.JobId) or string.format('Players: %d/23 | Job: %s', playerCount, game.JobId)
                                        local desc

                                        if ctx.State.buildArtifactDesc then
                                            desc = ctx.State.buildArtifactDesc(names, first, area, positions)
                                        else
                                            local sName, sRegion = readServerStats()

                                            desc = string.format('**Artifact%s:** %s\n**Server:** `%s (%s)`', #names > 1 and 's' or '', artifactList, sName ~= '' and sName or 'Unknown', sRegion ~= '' and sRegion or 'Unknown')
                                        end

                                        local spots = {}

                                        for _, p in positions do
                                            if #p == 3 then
                                                table.insert(spots, table.concat(p, ','))
                                            end
                                        end

                                        Webhook.send({
                                            username = Webhook.config.username,
                                            content = #pings > 0 and table.concat(pings, ' ') or nil,
                                            embeds = {
                                                {
                                                    title = artifactList .. areaText .. ' | ARTIFACT FOUND',
                                                    url = #spots > 0 and string.format('https://stella.heroinhound.cc/map/explore?world=%s&at=%s', game.PlaceId == 3541987450 and 'khei' or 'gaia', table.concat(spots, ';')) or nil,
                                                    description = desc,
                                                    color = 0xff3679,
                                                    thumbnail = {
                                                        url =
[[https://static.wikia.nocookie.net/rogue-lineage/images/d/d8/PhiloRender.png/revision/latest?cb=20251012003300]],
                                                    },
                                                    footer = {text = footer},
                                                    timestamp = os.date('!%Y-%m-%dT%H:%M:%SZ'),
                                                },
                                            },
                                        })
                                    end)
                                end
                                if ctx.State.queueArtifactStream then
                                    ctx.State.queueArtifactStream(names, ids, first, area, positions)
                                end
                            end)
                        end))
                    end
                end
                do
                    local function syncWebhook()
                        local url = Library.Options.WebhookUrl.Value
                        local username = Library.Options.WebhookUsername.Value
                        local showUsername = Library.Toggles.WebhookShowUsername.Value
                        local prefixOpt = Library.Options.WebhookPrefix
                        local prefix = (prefixOpt and prefixOpt.Value) or ''
                        local alertOpt = Library.Options.WebhookAlertPing
                        local alert = alertOpt and alertOpt.Value or '@everyone'

                        Webhook.setConfig({
                            url = url,
                            username = username,
                            showUsername = showUsername,
                            prefix = prefix,
                            alertPing = alert ~= '@everyone' and mention(alert) or false,
                        })

                        local artifactPings = {}

                        for _, name in PING_ARTIFACTS do
                            local opt = Library.Options[artifactPingId(name)]

                            if opt then
                                artifactPings[name] = opt.Value
                            end
                        end

                        MemStore.setJSON('shared_settings', {
                            webhook = url,
                            webhook_username = username,
                            webhook_show_username = showUsername,
                            webhook_prefix = prefix,
                            webhook_alert_ping = alert,
                            artifact_pings = artifactPings,
                        })
                    end

                    ctx.State.Webhook = Webhook
                    ctx.State.MemStore = MemStore

                    local WebhookBox = Settings:AddRightGroupbox('Webhook')

                    WebhookBox:AddInput('WebhookUrl', {
                        Text = 'Discord Webhook URL',
                        Placeholder = 'https://discord.com/api/webhooks/...',
                        Finished = true,
                        Callback = function(value)
                            if value ~= '' and not value:match('^https://discord%.com/api/webhooks/%d+/%S+$') and not value:match('^https://discordapp%.com/api/webhooks/%d+/%S+$') then
                                Notify.say("That doesn't look like a Discord webhook URL")
                            end

                            syncWebhook()
                        end,
                    })
                    WebhookBox:AddInput('WebhookUsername', {
                        Text = 'Webhook Username',
                        Default = 'sentinel',
                        Finished = true,
                        Callback = syncWebhook,
                    })
                    WebhookBox:AddInput('WebhookPrefix', {
                        Text = 'Custom Message',
                        Tooltip = 'Pings or text above every webhook',
                        Default = '',
                        Placeholder = '<@&123456789> heads up',
                        Finished = true,
                        Callback = syncWebhook,
                    })
                    WebhookBox:AddButton({
                        Text = 'Test Webhook',
                        Func = function()
                            syncWebhook()

                            if not Webhook.available() then
                                Notify.say(
[[Set a webhook URL first (and your executor needs http_request)]])

                                return
                            end
                            if Webhook.text('Test message from sentinel.bz') then
                                Notify.say('Webhook sent')
                            else
                                Notify.say('Webhook send failed')
                            end
                        end,
                    })
                    WebhookBox:AddToggle('WebhookShowUsername', {
                        Text = 'Show My Username',
                        Default = true,
                        Callback = syncWebhook,
                    })

                    ctx.State.toyAlert, ctx.State.toyHold = ToyAlert.attach(ctx, Settings, TOY_TRIGGERS)

                    do
                        local Workspace, CollectionService = Services:Get('Workspace', 'CollectionService')
                        local gripping, releaseAt, lowHealth = false, nil, false

                        local function gripNearby()
                            local char = LocalPlayer.Character
                            local root = char and char:FindFirstChild('HumanoidRootPart')

                            if not root then
                                return false
                            end
                            if char:FindFirstChild('Executing') then
                                return true
                            end

                            local live = Workspace:FindFirstChild('Live')

                            if not live then
                                return false
                            end

                            for _, model in live:GetChildren()do
                                if model ~= char and CollectionService:HasTag(model, 'BeingExecuted') then
                                    local theirs = model:FindFirstChild('HumanoidRootPart')

                                    if theirs and (theirs.Position - root.Position).Magnitude <= GRIP_RANGE then
                                        return true
                                    end
                                end
                            end

                            return false
                        end

                        local accum = 0

                        ctx.Maid:Connect(Services.RunService.Heartbeat, BASIL_NO_VIRTUALIZE(function(
                            dt
                        )
                            accum += dt

                            if accum < GRIP_POLL then
                                return
                            end

                            accum = 0

                            local now = gripNearby()

                            if now then
                                releaseAt = nil

                                if not gripping then
                                    gripping = true

                                    ctx.State.toyHold('Grip Nearby', true)
                                end
                            elseif gripping then
                                releaseAt = releaseAt or (tick() + GRIP_TAIL)

                                if tick() >= releaseAt then
                                    gripping, releaseAt = false, nil

                                    ctx.State.toyHold('Grip Nearby', false)
                                end
                            end

                            local char = LocalPlayer.Character
                            local humanoid = char and char:FindFirstChildOfClass('Humanoid')
                            local share = (humanoid and humanoid.MaxHealth > 0) and (humanoid.Health / humanoid.MaxHealth * 100) or 100
                            local threshold = (Library.Options.LowHealthPercent and Library.Options.LowHealthPercent.Value) or LOW_HEALTH_DEFAULT
                            local hurt = humanoid ~= nil and humanoid.Health > 0 and share < threshold and CollectionService:HasTag(char, 'Danger')

                            if hurt ~= lowHealth then
                                lowHealth = hurt

                                ctx.State.toyHold('Low Health Danger', hurt)
                            end
                        end))
                    end

                    WebhookBox:AddToggle('ShowInArtifactStream', {
                        Text = 'Show in Community Artifact Stream',
                        Tooltip = 'Shares artifacts you leave behind',
                        Default = false,
                    })

                    local PingBox = (ctx.Tabs.Botting or Settings):AddRightGroupbox('Webhook Pings')

                    local function pingEdited(value)
                        if tostring(value or '') ~= '' and mention(value) == '' and not ctx.State.loadingConfig then
                            Notify.say(
[[That isn't a role ID. Paste the number from Copy Role ID, or @everyone / @here]])
                        end

                        syncWebhook()
                    end

                    PingBox:AddLabel(
[[Paste a Discord role ID in a box to ping that role. To get one, turn on Developer Mode in Discord, right-click the role and Copy Role ID. @everyone and @here work too. Empty means no ping.]], true)
                    PingBox:AddInput('WebhookAlertPing', {
                        Text = 'Bot Alerts',
                        Tooltip = 'Deaths, moderators, kicks and threats',
                        Default = '@everyone',
                        Placeholder = 'no ping',
                        Finished = true,
                        Callback = pingEdited,
                    })
                    PingBox:AddDivider()
                    PingBox:AddLabel('Artifact spawns while botting')

                    for _, name in PING_ARTIFACTS do
                        PingBox:AddInput(artifactPingId(name), {
                            Text = name,
                            Default = ARTIFACT_PING_DEFAULT[name] and '@here' or '',
                            Placeholder = 'no ping',
                            Finished = true,
                            Callback = pingEdited,
                        })
                    end

                    ctx.State.syncWebhook = syncWebhook
                end
                do
                    local ChatBox = Settings:AddLeftGroupbox('Chat Logger')
                    local chatMaid = Maid.new()

                    ctx.Maid:Give(chatMaid)

                    local Players = Services.Players
                    local ReplicatedStorage = Services.ReplicatedStorage
                    local RunService = Services.RunService
                    local chatLog = Library:CreateChatLog({
                        Title = 'chat log',
                        MaxLines = 200,
                        Visible = false,
                    })
                    local chatDefaultPos = chatLog.Holder.Position

                    local function geomString(h)
                        return ('%d,%d,%d,%d'):format(h.Position.X.Offset, h.Position.Y.Offset, h.Size.X.Offset, h.Size.Y.Offset)
                    end
                    local function applyGeomString(s)
                        local px, py, sx, sy = tostring(s or ''):match('^(-?%d+),(-?%d+),(%d+),(%d+)$')

                        if not px then
                            return
                        end

                        pcall(function()
                            chatLog.Holder.Size = UDim2.fromOffset(tonumber(sx), tonumber(sy))
                            chatLog.Holder.Position = UDim2.fromOffset(tonumber(px), tonumber(py))
                        end)
                    end

                    ChatBox:AddInput('ChatLogGeom', {
                        Default = '',
                        Visible = false,
                        Callback = applyGeomString,
                    })

                    local savedGeom = MemStore.getJSON('chatlog_geom')

                    if type(savedGeom) == 'table' and savedGeom.px then
                        applyGeomString(('%d,%d,%d,%d'):format(savedGeom.px, savedGeom.py, savedGeom.sx or 300, savedGeom.sy or 180))
                    end

                    do
                        local accum, lastKey = 0, ''

                        ctx.Maid:Give(RunService.Heartbeat:Connect(BASIL_NO_VIRTUALIZE(function(
                            dt
                        )
                            accum += dt

                            if accum < 2 then
                                return
                            end

                            accum = 0

                            local h = chatLog.Holder
                            local s = geomString(h)

                            if s ~= lastKey then
                                lastKey = s

                                local geomOpt = Library.Options.ChatLogGeom

                                if geomOpt then
                                    geomOpt.Value = s
                                end

                                pcall(function()
                                    MemStore.setJSON('chatlog_geom', {
                                        px = h.Position.X.Offset,
                                        py = h.Position.Y.Offset,
                                        sx = h.Size.X.Offset,
                                        sy = h.Size.Y.Offset,
                                    })
                                end)
                            end
                        end)))
                    end

                    local function esc(s)
                        return (tostring(s):gsub('&', '&amp;'):gsub('<', '&lt;'):gsub('>', '&gt;'))
                    end
                    local function toHex(c)
                        return ('#%02X%02X%02X'):format(math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
                    end

                    local logLines = {}

                    local function serverInfo()
                        local name, region = '', ''
                        local pg = LocalPlayer:FindFirstChildOfClass('PlayerGui')
                        local statsGui = pg and pg:FindFirstChild('ServerStatsGui')
                        local frame = statsGui and statsGui:FindFirstChild('Frame')
                        local stats = frame and frame:FindFirstChild('Stats')

                        if stats then
                            local sn = stats:FindFirstChild('ServerName')

                            if sn then
                                name = sn.Text:match('Server Name: (.+)') or ''
                            end

                            local sr = stats:FindFirstChild('ServerRegion')

                            if sr then
                                region = sr.Text:match('Server Region: (.+)') or ''
                            end
                        end

                        return name, region
                    end

                    local recent, recentCount = {}, 0

                    local function pushMessage(player, name, text)
                        text = tostring(text or '')

                        if text == '' or not chatLog then
                            return
                        end

                        local key = tostring(player and player.UserId or name) .. '\0' .. text
                        local now = os.clock()

                        if recent[key] and now - recent[key] < 2 then
                            return
                        end
                        if recentCount >= 100 then
                            table.clear(recent)

                            recentCount = 0
                        end

                        recentCount += 1

                        recent[key] = now

                        if text:find('<font color="#d4d4d4">', 1, true) then
                            return
                        end

                        name = tostring(name or (player and player.Name) or '?')

                        if player == LocalPlayer and ctx.State.streamerName then
                            local fake = ctx.State.streamerName()

                            if fake then
                                name = fake
                            end
                        end

                        local rogue = (player and ctx.State.getRogueName and ctx.State.getRogueName(player)) or ''
                        local hasRogue = rogue ~= '' and rogue ~= 'nil' and rogue ~= 'Unknown'
                        local nameStr = esc(name)

                        if player and ctx.State.threatColor then
                            nameStr = ('<font color="%s">%s</font>'):format(toHex(ctx.State.threatColor(player)), nameStr)
                        end

                        local line

                        if hasRogue then
                            line = ('<b>%s</b> [%s] %s'):format(esc(rogue), nameStr, esc(text))
                        else
                            line = ('[%s] %s'):format(nameStr, esc(text))
                        end

                        local stamp = os.date('%H:%M:%S')

                        if hasRogue then
                            table.insert(logLines, ('[%s] %s [%s]: %s'):format(stamp, rogue, name, text))
                        else
                            table.insert(logLines, ('[%s] [%s]: %s'):format(stamp, name, text))
                        end
                        if #logLines > 5000 then
                            table.remove(logLines, 1)
                        end

                        local label = chatLog:Add(line)

                        if label then
                            label.RichText = true

                            local lower = text:lower()
                            local mine = LocalPlayer.Name:lower()
                            local rogueMine = ctx.State.getRogueName and ctx.State.getRogueName(LocalPlayer)

                            if lower:find(mine, 1, true) or (rogueMine and rogueMine ~= '' and rogueMine ~= 'nil' and rogueMine ~= 'Unknown' and lower:find(rogueMine:lower(), 1, true)) then
                                label.TextColor3 = Color3.fromRGB(255, 165, 60)
                            end
                            if player then
                                label.Active = true

                                label.InputBegan:Connect(function(input)
                                    if input.UserInputType == Enum.UserInputType.MouseButton2 and ctx.State.spectate then
                                        ctx.State.spectate(player)
                                    end
                                end)
                            end
                        end
                    end
                    local function startLogging()
                        local tcs = Services.TextChatService

                        if tcs then
                            pcall(function()
                                chatMaid.tcs = tcs.MessageReceived:Connect(function(
                                    message
                                )
                                    local plr, name = nil, '?'
                                    local source = message.TextSource

                                    if source then
                                        plr = Players:GetPlayerByUserId(source.UserId)
                                        name = (plr and plr.Name) or source.Name or '?'
                                    end

                                    pushMessage(plr, name, message.Text)
                                end)
                            end)
                        end

                        local chat = Services.Chat

                        if chat then
                            pcall(function()
                                chatMaid.bubble = chat.Chatted:Connect(function(
                                    part,
                                    message
                                )
                                    local plr

                                    while part and not plr do
                                        plr = Players:GetPlayerFromCharacter(part)
                                        part = part.Parent
                                    end

                                    if plr then
                                        pushMessage(plr, plr.Name, message)
                                    end
                                end)
                            end)
                        end

                        local events = ReplicatedStorage:FindFirstChild('DefaultChatSystemChatEvents')
                        local filtered = events and events:FindFirstChild('OnMessageDoneFiltering')

                        if filtered then
                            pcall(function()
                                chatMaid.legacy = filtered.OnClientEvent:Connect(function(
                                    data
                                )
                                    if type(data) == 'table' then
                                        local plr = data.FromSpeaker and Players:FindFirstChild(data.FromSpeaker)

                                        pushMessage(plr, data.FromSpeaker, data.Message)
                                    end
                                end)
                            end)
                        end
                    end

                    ChatBox:AddToggle('RobloxChat', {
                        Text = 'Roblox Chat',
                        Default = false,
                        Callback = function(on)
                            pcall(function()
                                Services.TextChatService.ChatWindowConfiguration.Enabled = on
                            end)
                        end,
                    })
                    ChatBox:AddToggle('ChatLogger', {
                        Text = 'Chat Logger',
                        Default = false,
                        Callback = function(on)
                            chatLog:SetVisible(on)

                            if on then
                                startLogging()
                            else
                                chatMaid:DoCleaning()
                            end
                        end,
                    })
                    ChatBox:AddButton({
                        Text = 'Reset Window Positions',
                        Func = function()
                            pcall(function()
                                chatLog.Holder.Position = chatDefaultPos
                            end)

                            if ctx.State.resetStatusWindow then
                                ctx.State.resetStatusWindow()
                            end
                        end,
                    })
                    ChatBox:AddButton({
                        Text = 'Save Chat Log',
                        Func = function()
                            if not writefile then
                                Notify.say('Executor has no file writing')

                                return
                            end
                            if #logLines == 0 then
                                Notify.say('Chat log is empty')

                                return
                            end

                            local sname, region = serverInfo()
                            local header = table.concat({
                                '===== Sentinel Chat Log =====',
                                'Date: ' .. os.date('%Y-%m-%d %H:%M:%S'),
                                'Server: ' .. (sname ~= '' and sname or 'Unknown') .. (region ~= '' and (' (' .. region .. ')') or ''),
                                'Job ID: ' .. tostring(game.JobId),
                                'Place ID: ' .. tostring(game.PlaceId),
                                'Players: ' .. tostring(#Players:GetPlayers()),
                                '=============================',
                                '',
                            }, '\n')

                            pcall(function()
                                if makefolder then
                                    if isfolder and not isfolder('sentinel') then
                                        makefolder('sentinel')
                                    end
                                    if not (isfolder and isfolder('sentinel/chatlogs')) then
                                        makefolder('sentinel/chatlogs')
                                    end
                                end
                            end)

                            local fname = ('sentinel/chatlogs/chatlog_%s.txt'):format(os.date('%Y-%m-%d_%H-%M-%S'))
                            local ok = pcall(writefile, fname, header .. table.concat(logLines, '\n') .. '\n')

                            Library:Notify({
                                Title = 'sentinel.bz',
                                Description = ok and ('Saved ' .. #logLines .. ' lines to ' .. fname) or 'Failed to save chat log',
                            })
                        end,
                    })
                    ChatBox:AddButton({
                        Text = 'Clear Chat Log',
                        Func = function()
                            chatLog:Clear()
                            table.clear(logLines)
                        end,
                    })
                end

                Library:SetKeybindFrameVisible(false)
                applyBlatant(Library.Toggles.BlatantMode.Value)
                applyRisky(Library.Toggles.RiskyMode.Value)
                ThemeManager:SetLibrary(Library)
                ThemeManager:SetFolder('sentinel')

                ThemeManager.BuiltInThemes['Sentinel'] = {
                    0,
                    {
                        FontColor = 'c8c8c8',
                        MainColor = '262626',
                        AccentColor = 'c32148',
                        BackgroundColor = '141414',
                        OutlineColor = '383838',
                    },
                }
                ThemeManager.DefaultTheme = 'Sentinel'

                ThemeManager:ApplyToGroupbox(Settings:AddLeftGroupbox('Themes'))
                SaveManager:SetLibrary(Library)
                SaveManager:IgnoreThemeSettings()
                SaveManager:SetFolder('sentinel')

                local ignoreIndexes = {
                    'AutoclickerBlockedTools',
                    'AvoidList',
                    'AvoidName',
                    'SavedPaths',
                    'LoopJoin',
                    'BotCustomFPS',
                    'BotFPS',
                    'StayInServer',
                    'ProgStayInServer',
                    'CastleStayInServer',
                    'GripBotEnabled',
                    'GripTargets',
                    'GripMaster',
                    'RotAlts',
                    'QuietConsole',
                    'BardSong',
                    'BardMusic',
                    'BardSoundId',
                    'BardMusicMap',
                    'BagItems',
                    'BagItemName',
                }

                for i = 1, 12 do
                    table.insert(ignoreIndexes, 'MacroTrigger' .. i)
                end

                SaveManager:SetIgnoreIndexes(ignoreIndexes)

                local originalLoad = SaveManager.Load

                SaveManager.Load = function(self, configName)
                    ctx.State.loadingConfig = true

                    local ok, err = originalLoad(self, configName)

                    ctx.State.loadingConfig = false

                    if ctx.State.restoreMenuKeybind then
                        ctx.State.restoreMenuKeybind()
                    end

                    applyBlatant(Library.Toggles.BlatantMode.Value)
                    applyRisky(Library.Toggles.RiskyMode.Value)
                    MemStore.set('blatant', Library.Toggles.BlatantMode.Value and 'true' or 'false')

                    if ctx.State.reapplyCustomization then
                        pcall(ctx.State.reapplyCustomization)
                    end
                    if ctx.State.refreshCharLists then
                        pcall(ctx.State.refreshCharLists)
                    end
                    if ctx.State.tickNewDetections then
                        pcall(ctx.State.tickNewDetections)
                    end
                    if ok and configName and Library.Toggles.PersistentConfigs and Library.Toggles.PersistentConfigs.Value then
                        MemStore.set('loaded_config', configName)
                    end

                    return ok, err
                end

                ctx.Maid:Give(function()
                    MemStore.remove('loaded_config')
                end)
                SaveManager:BuildConfigSection(Settings, Settings:AddRightGroupbox('Configuration'))

                if not BASIL_OBFUSCATED then
                    do
                        local DebugBox = Settings:AddRightGroupbox('Debug')
                        local dlgMaid = Maid.new()

                        ctx.Maid:Give(dlgMaid)

                        local lines, seen = {}, 0

                        local function keep(text)
                            print('[sentinel/dlg] ' .. text)
                            table.insert(lines, text)

                            if #lines > DLG_LOG_MAX then
                                table.remove(lines, 1)
                            end
                        end
                        local function reveal(str)
                            if type(str) ~= 'string' then
                                return tostring(str)
                            end

                            local out = {}

                            for i = 1, #str do
                                local b = str:byte(i)

                                table.insert(out, (b >= 32 and b < 127) and str:sub(i, i) or string.format('<%d>', b))
                            end

                            return table.concat(out)
                        end
                        local function listOf(t)
                            if type(t) ~= 'table' or #t == 0 then
                                return 'none'
                            end

                            local out = {}

                            for _, v in t do
                                table.insert(out, string.format('%q', tostring(v)))
                            end

                            return table.concat(out, ' | ')
                        end

                        DebugBox:AddToggle('DialogueDebug', {
                            Text = 'Dialogue Debugging',
                            Tooltip = 'Prints NPC dialogue to console',
                            Default = false,
                            Callback = function(on)
                                dlgMaid:DoCleaning()

                                if not on then
                                    return
                                end

                                table.clear(lines)

                                seen = 0

                                local requests = Services.ReplicatedStorage:FindFirstChild('Requests')

                                if not requests then
                                    Notify.say('Dialogue Debugging: no Requests folder in this place')

                                    return
                                end

                                for _, remote in requests:GetChildren()do
                                    if remote:IsA('RemoteEvent') then
                                        dlgMaid:Connect(remote.OnClientEvent, function(
                                            data
                                        )
                                            if type(data) ~= 'table' or (data.choices == nil and data.speaker == nil and data.msg == nil) then
                                                return
                                            end

                                            seen += 1

                                            local char = LocalPlayer.Character

                                            keep(string.format('IN #%d speaker=%s tag=%s', seen, tostring(data.speaker), tostring(char ~= nil and char:FindFirstChild('InDialogue') ~= nil)))
                                            keep(string.format('    msg %q', tostring(data.msg)))
                                            keep('    bytes ' .. reveal(data.msg))
                                            keep(string.format('    choices [%s] endchoice=%s', listOf(data.choices), tostring(data.endchoice)))
                                        end)
                                    end
                                end

                                Notify.say(
[[Dialogue Debugging on, talk to an NPC and the lines print to console]])
                            end,
                        })
                        DebugBox:AddButton({
                            Text = 'Copy Dialogue Log',
                            Func = function()
                                if #lines == 0 then
                                    Notify.say('Dialogue log is empty')

                                    return
                                end
                                if setclipboard then
                                    setclipboard(table.concat(lines, '\n'))
                                    Notify.say(string.format('Copied %d dialogue lines', #lines))
                                else
                                    Notify.say('This executor has no setclipboard')
                                end
                            end,
                        })
                    end
                end

                local resumeWasOn = MemStore.get('execute_on_serverhop') == 'true'
                local persistedConfig = MemStore.get('loaded_config')
                local restored = false

                if persistedConfig and persistedConfig ~= '' then
                    restored = SaveManager:Load(persistedConfig) == true
                end
                if not restored then
                    SaveManager:LoadAutoloadConfig()

                    if ctx.State.reapplyCustomization then
                        pcall(ctx.State.reapplyCustomization)
                    end
                    if ctx.State.refreshCharLists then
                        pcall(ctx.State.refreshCharLists)
                    end
                end
                if ctx.State.tickNewDetections then
                    pcall(ctx.State.tickNewDetections)
                end

                ctx.State.notificationsReady = true

                if ctx.State.onNotificationsReady then
                    ctx.State.onNotificationsReady()
                end
                if restored then
                    Notify.say('Restored config: ' .. persistedConfig)
                end
                if resumeWasOn and Library.Toggles.ExecuteOnServerhop then
                    Library.Toggles.ExecuteOnServerhop:SetValue(true)
                end
                if MemStore.get('bind_backpack_tools') == 'true' and Library.Toggles.BindBackpackTools then
                    Library.Toggles.BindBackpackTools:SetValue(true)
                end
                if Library.Options.WebhookUrl.Value == '' then
                    local persisted = MemStore.getJSON('shared_settings')

                    if persisted and type(persisted.webhook) == 'string' and persisted.webhook ~= '' then
                        Library.Options.WebhookUrl:SetValue(persisted.webhook)

                        if type(persisted.webhook_username) == 'string' then
                            Library.Options.WebhookUsername:SetValue(persisted.webhook_username)
                        end
                        if persisted.webhook_show_username ~= nil then
                            Library.Toggles.WebhookShowUsername:SetValue(persisted.webhook_show_username == true)
                        end
                        if type(persisted.webhook_prefix) == 'string' then
                            Library.Options.WebhookPrefix:SetValue(persisted.webhook_prefix)
                        end
                        if type(persisted.webhook_alert_ping) == 'string' and Library.Options.WebhookAlertPing then
                            Library.Options.WebhookAlertPing:SetValue(persisted.webhook_alert_ping)
                        end

                        for name, value in (type(persisted.artifact_pings) == 'table' and persisted.artifact_pings or {})do
                            local opt = Library.Options[artifactPingId(name)]

                            if opt and type(value) == 'string' then
                                opt:SetValue(value)
                            end
                        end
                    end
                end
                if ctx.State.syncWebhook then
                    ctx.State.syncWebhook()
                end
            end
        end

        function __DARKLUA_BUNDLE_MODULES.ar(): typeof(__modImpl())
