local function xorString(str, salt)
    salt = salt or 27

    if not (bit32 and bit32.bxor) then
        return str
    end

    local chars = {}

    for i = 1, #str do
        chars[i] = string.char(bit32.bxor(string.byte(str, i), salt + (i % 7)))
    end

    return table.concat(chars)
end

